-- Sources: data/i18n/ukUA. Lore text adapted from warcraft.wiki.gg (CC BY-SA 4.0); the core add-on's src fields name the articles.
local P = LoreForeverPacks.Begin("LoreForever_Lang_ukUA")
P.entries["quest:1084"] = {n="Поранені Прадавні",s="«Поранені Прадавні» — завдання Альянсу від Каели Шедовспір у Горах Кам'яного Кігтя. Підозрюючи, що місцевих лісових охоронців довели до божевілля гоблінські боєприпаси, Каела посилає шукачів пригод добути шрапнель, що застрягла в зіпсованих деревлянах, щоб гном-інженер Ґаксим Растфіззл міг дослідити отруту.",h="«Поранені Прадавні» — завдання Альянсу від Каели Шедовспір у Горах Кам'яного Кігтя.",kw={"поранені прадавні","деревляни","каела шедовспір","ґаксим растфіззл","шрапнель","венчурна компанія"},ang={["class:Druid"]="Деревляни — живий пульс природи; витягти чужий метал, що отруює їхню плоть, — похмура необхідність у протистоянні руйнуванню від Венчурної Компанії.",["profession:Engineering"]="Роз'їдений метал, вийнятий із деревлян, показує руйнівну, абияку природу боєприпасів Венчурної Компанії порівняно з вишуканою гномською майстерністю.",["race:Gnome"]="Аналітичне око Ґаксима Растфіззла доводить, що механічне ремесло можна обернути на розуміння й розпізнання злочинів проти природи, скоєних безвідповідальними інженерами.",["race:NightElf"]="Бачити, як давні захисники лісу гниють і корчаться від гоблінського промислу, — наруга для кожного калдорея, відданого захистові дикої природи Калімдору."},sec={{t="Уражені захисники",b="Лісові гаї Гір Кам'яного Кігтя здавна стерегли височенні деревляни — лагідні, але люті охоронці, пов'язані зі здоров'ям землі. Коли сюди прийшла Венчурна Компанія з циркулярними пилками, вибухівкою й відкритим видобутком, природа дала відсіч. Деревлянам удалося вигнати загарбників із частини долини, але перемога обійшлася підступною ціною. Захисники не повернулися до мирної варти — натомість вони перетворилися на ворожі, збожеволілі оболонки."},{t="Гномське розслідування",b="Каела Шедовспір, розвідниця Альянсу в горах, вважає, що занепад деревлян — не природна хвороба. Гном-інженер Ґаксим Растфіззл підозрює, що винен хімічний і механічний арсенал, який гобліни застосовували під час безладного відступу. Витягуючи роз'їдену шрапнель із поранених деревних створінь, Ґаксим сподівається з'ясувати, чи справді боєприпаси Венчурної Компанії отруюють давніх охоронців Гір Кам'яного Кігтя."}},faq={{q="Хто дає завдання «Поранені Прадавні»?",a="Завдання дає Каела Шедовспір — агентка Альянсу, що стежить за дедалі запеклішою боротьбою й шкодою природі в Горах Кам'яного Кігтя.",al={"давець поранених прадавніх","хто дає поранених прадавніх","завдання каели шедовспір"}},{q="Чому древені зіпсовані?",a="Ґаксим Растфіззл підозрює, що отруйні набої й зброя, якими Венчурна Компанія стріляла під час свого безладного відступу, застрягли в трентах і поступово отруюють та зводять з розуму лісових охоронців.",al={"чому древні зіпсовані","чому древні скажені","причина скверни древніх"}},{q="Який предмет треба здобути для цього завдання?",a="Вам треба здобути шматок Роз'їденої Шрапнелі, що застряг у корі й тілі поранених древенів, які блукають околицями.",al={"предмет завдання","предмет поранених прадавніх"}},{q="Хто такий Ґаксим Растфіззл?",a="Ґаксим — гном-інженер, що служить Альянсу й допомагає Каелі Шедовспір. Своїми механічними знаннями він досліджує техніку Венчурної Компанії, щоб з'ясувати, як їхня зброя псує живу природу.",al={"хто такий ґаксим","гном у стоунталоні","роль ґаксима"}},{q="Що Венчурна Компанія робить у Горах Кам'яного Кігтя?",a="Венчурна Компанія — безжальне гоблінське лісорубне й гірниче угруповання, що вдерлося в Гори Кам'яного Кігтя, щоб суцільно вирубувати священні ліси й грабувати родовища, не зважаючи на місцеву рівновагу.",al={"венчурна компанія стоунталон","чому гобліни в стоунталоні"}},{q="Чи зцілює древенів зібрана шрапнель?",a="Ні. Здобута шрапнель — лише зразок для аналізу, щоб Ґаксим міг дослідити природу й походження отрути, а не негайні ліки для зіпсованих охоронців.",al={"чи шрапнель зцілює древніх","чи можна вилікувати древніх"}}},fp="16,301,19.469.0,21.440.0,38.151.0,30.195.0,42.128.0,24.197.0,53.185.0,46.181.0"}
P.entries["quest:1086"] = {n="Аеропорт літальних машин",s="За дорученням Аптекарки Замах із Тандер Блафа шукачі пригод з Орди розшукують прихований посадковий майданчик Венчурної Компанії високо над Горами Кам'яного Кігтя. З алхімічним Розпилювачем Токсинів агенти мають пробратися в серце гоблінських лісозаготівель і отруїти газом їхній повітряний вузол. Місія б'є просто по зв'язку картелю й водночас показує безжальні методи Королівського Аптекарського Товариства.",h="За дорученням Аптекарки Замах із Тандер Блафа шукачі пригод з Орди розшукують прихований посадковий майданчик...",kw={"аеропорт літальних машин","аптекарка замах","розпилювач токсинів","венчурна компанія","коптери","озеро скельної заводі"},ang={["faction:Horde"]="Щоб убезпечити Гори Кам'яного Кігтя, треба відрізати Венчурну Компанію від зовнішньої допомоги, і удар по її повітряних перевезеннях — важливий удар по постачанню.",["profession:Engineering"]="Гоблінський майданчик для коптерів показує грубу, суто практичну інженерію, на якій тримаються швидкі перевезення Венчурної Компанії через суворі гірські хребти.",["race:Tauren"]="Ваш народ гидує тим, як Венчурна Компанія нищить Гори Кам'яного Кігтя, але застосування хімічних отрут за порадою аптекарки-Відступниці випробовує рівновагу між шаною до Земної Матері й суворим бойовим прагматизмом.",["race:Undead"]="Для Відступників застосування Розпилювача Токсинів у Горах Кам'яного Кігтя — звична справа, що показує Калімдору: алхімічний геній Андерсіті розв'язує те, чого не здолає груба сила."},sec={{t="Тиха доставка",b="Поки таурени прагнуть захистити Гори Кам'яного Кігтя від вирубки й нищівних машин, Відступники приносять на фронт зовсім іншу філософію. Аптекарка Замах створює смертоносну сполуку, щоб розладнати постачання Венчурної Компанії. Замість нападати просто на найманців чи лісорубів, вона б'є по зв'язку картелю із зовнішнім світом — по майданчику для коптерів, про який ходять чутки, звідки легкі вантажі й повідомлення перевозять між Горами Кам'яного Кігтя й далекими корпоративними конторами."},{t="Небесний порт біля Скельної Заводі",b="Високо в околицях Озера Скельної Заводі, на південь від великого водяного колеса, захований майданчик для коптерів Венчурної Компанії, що височіє над кіптявою й зрубаним лісом. Він невеликий, призначений для легких літальних машин, а не для величезних цепелінів. Увімкнений просто на майданчику Розпилювач Токсинів огортає смертельною парою кожного пілота, гінця чи механіка, що обслуговує машини, перш ніж ті встигнуть сповістити командирів."},{t="Прагматизм Відступників",b="Отримавши вісті про напад, Аптекарка Замах не вибачається за хімічну війну проти гоблінів. На її думку, Венчурна Компанія заслуговує на куди гірше за те, що вона чинить із землею. А головне — вона дає Орді основний урок учення Андерсіті: ніколи не цурайся темних шляхів, якщо вони ведуть до остаточної перемоги."}},faq={{q="Де розташований аеропорт літальних машин?",a="Майданчик для коптерів Венчурної Компанії розташований біля Озера Скельної Заводі в Горах Кам'яного Кігтя. Ви знайдете цю підняту дерев'яну споруду на південь від величезного промислового водяного колеса, над південним вигином озера.",al={"місце аеропорту","майданчик гелікоптерів","де небесний порт","посадковий майданчик венчурної компанії"}},{q="Чому Аптекарка Замах хоче отруїти це місце?",a="Замах прагне перерізати зв'язок і легкі шляхи постачання між Горами Кам'яного Кігтя й далеким штабом Венчурної Компанії. Отруївши майданчик для коптерів, вона сподівається покалічити гоблінські льотні екіпажі, а може, й переправити отруту на попутному рейсі до самого керівництва компанії.",al={"чому замах хоче отруїти","навіщо бомбити аеропорт","мотив замах"}},{q="Хто така Аптекарка Замах?",a="Аптекарка Замах — посланиця Королівського Аптекарського Товариства в Ставках Видінь під Тандер Блафом. Вона вивчає флору й фауну Калімдору й водночас розробляє алхімічну зброю для Відступників і Орди.",al={"хто така замах","особа замах","нежить у тандер блафі"}},{q="Чому Орда застосовує тут хімічну зброю?",a="Відступники б'ються з розважливою безжальністю. Хоча їхні союзники таурени віддають перевагу духовному зціленню й прямому захисту землі, Замах вважає, що руйнівна жадібність Венчурної Компанії заслуговує на безжальні методи, і наголошує, що перемога важливіша за сентиментальну стриманість.",al={"чому орда застосовує хімію","орда використовує чуму","чи це чума"}},{q="Які літальні апарати Венчурна Компанія використовує тут?",a="Майданчик розрахований на невеликі гоблінські літальні машини й гірокоптери, а не на повнорозмірні цепеліни. Ці спритні апарати дають картелю змогу швидко оминати суворі гірські перевали Кам'яного Кігтя, перевозячи термінові листи й вантажі.",al={"які літальні апарати","гелікоптери венчурної компанії","гоблінська авіація стоунталона"}},{q="Що буде, коли розпилювач запущено?",a="Щойно ви запускаєте розпилювач на верхівці майданчика, треба тікати, поки вас не накрили випари. Замах вважає застосування вдалим і розраховує, що отрута серйозно порушить гоблінське постачання.",al={"що після розпилювача","результат розпилювача"}}},fp="26,416,17.466.0,19.420.0,19.352.1,44.224.0,50.278.0,24.235.0,45.276.0,56.236.0,42.204.1"}
P.entries["quest:1087"] = {n="Спадок Кенарія",s="«Спадок Кенарія» — завдання Орди від Брейлін Файргенд біля Притулку Сонячної Скелі в Горах Кам'яного Кігтя. Роздратована природними захисними чарами нічних ельфів і дітей Кенарія, магиня з-поміж кривавих ельфів прагне проредити їх на Піку Кам'яного Кігтя, щоб відновити вільний плин магії. Для Орди удар по захисниках Кола Кенарія водночас послаблює присутність Альянсу в краї.",h="«Спадок Кенарія» — завдання Орди від Брейлін Файргенд біля Притулку Сонячної Скелі в Горах Кам'яного Кігтя.",kw={"спадок кенарія","брейлін файргенд","коло кенарія","пік кам'яного кігтя","рада тіней","джеденар","притулок сонячної скелі"},ang={["class:Druid"]="Для друїдів-тауренів вирізати нащадків Кенарія й ботаніків Кола Кенарія — незручний і глибоко суперечливий учинок, що підкреслює трагічне тертя між вірністю фракції й священними шляхами природи.",["class:Mage"]="Скарги Брейлін відгукуються знавцям чарівної магії, які бачать тертя між давніми калдорейськими захисними чарами й вільним плином лей-енергії, хоч її безрозсудний запал межує з одержимістю.",["faction:Horde"]="Пік Кам'яного Кігтя — найбільший оплот Альянсу й калдореїв у гірському хребті; знищення його захисників вкрай важливе, щоб убезпечити Притулок Сонячної Скелі й Долину Великолісся."},sec={{t="Задушені потоки",b="Брейлін Файргенд живе в пагорбах біля Притулку Сонячної Скелі й аж кипить від роздратування природою Гір Кам'яного Кігтя. За її словами, друїди Кола Кенарія й нащадки напівбога Кенарія навмисно придушують і душать чарівні потоки краю. Порівнюючи спроби черпати тут силу з набиранням води дірявим відром, вона жадає зірвати їхній природний захист, щоб сира магічна енергія знову вільно ринула."},{t="Удар по Піку Кам'яного Кігтя",b="Щоб послабити цю зелену хватку, Брейлін наймає поборників Орди вирушити на північ, до Піку Кам'яного Кігтя. Там, довкола давніх калдорейських гаїв і храмових земель, ходять дозором ботаніки Кола Кенарія разом із гордими Синами й Доньками Кенарія. Знищення цих охоронців служить подвійній меті: руйнує захисні чари, що глушать чаклунство Брейлін, і завдає кривавого удару анклаву нічних ельфів, що загрожує опорі Орди в горах."},{t="Зв'язки з Радою Тіней",b="Брейлін подає свою образу як питання магічної зручності, але її справжня вірність ховається в темніших закутках. Вона прагне повернутися до Джеденара — зіпсованої твердині Ради Тіней, захованої в Скверноліссі на півночі, — але зауважує, що її невидимий господар забороняє їй повертатися, доки її робота в Горах Кам'яного Кігтя не завершена. Орда допомагає їй з міркувань вигоди в боротьбі за землі, часто й не здогадуючись про зловісний культ, що смикає її за ниточки."}},faq={{q="Хто така Брейлін Файргенд?",a="Брейлін Файргенд — чарівниця з ельфів крові, що отаборилася серед скель біля Притулку Сонячної Скелі. Хоч вона й приймає допомогу Орди, щоб вигнати нічних ельфів із Гір Кам'яного Кігтя, насправді вона служить таємному господареві, що сидить у Джеденарі в Скверноліссі.",al={"лор брейлін файргенд","хто дає завдання","брейлін"}},{q="Чому Брейлін хоче смерті дітей Кенарія?",a="Вона запевняє, що друїдська магія, яку практикують ботаніки-калдореї й нащадки Кенарія, придушує плин первісної таємної сили в горах. Якщо їх знищити, охоронні чари гаю ослабнуть, і магія вільно потече їй до рук.",al={"чому вбивати дітей кенарія","чому ненавидіти ботаніків ценарія","чому брейлін ненавидить їх"}},{q="Де ці цілі?",a="Сини Кенарія, Доньки Кенарія й Кенарійські ботаніки зібралися далеко на півночі, на Піку Кам'яного Кігтя, де стережуть руїни предків, гаї й місячні колодязі, які доглядають нічні ельфи.",al={"де цілі","місця дітей кенарія","де ботаніки ценарія"}},{q="Що таке Джеденар, який згадує Брейлін?",a="Джеденар — глибокий каньйон із печерами в Скверноліссі, тяжко осквернений Палаючим Легіоном; нині це головний осідок Ради Тіней у Калімдорі.",al={"що таке джеденар","майстер брейлін джеденар","зв'язок з джеденаром"}},{q="Чому Орда готова допомогти Брейлін напасти на захисників-кенарійців?",a="Нічні ельфи з Піку Кам'яного Кігтя — прямі союзники Альянсу й заважають Орді поширюватися Горами Кам'яного Кігтя. Ослабивши їхній гай, Орда закріплює край за собою, хай якими є особисті мотиви Брейлін.",al={"чому орда вбиває коло ценарія","конфлікт орди на піку стоунталона"}},{q="Що буде після завершення «Спадку Кенарія»?",a="Braelyn's next assignment targets Ordanus, a keeper of the grove at Raynewood Retreat in Ashenvale. He can be found atop the great tree there.",al={"що після спадку кенарія","наступне завдання ланцюжка","ланцюжок ордануса"}}},fp="16,401,16.468.0,27.454.0,26.429.1,24.243.1,52.256.0,30.204.0,41.194.0,67.242.0,47.142.1"}
P.entries["quest:1088"] = {n="Орданус",s="Брейлін Файргенд із Притулку Сонячної Скелі магічним зором вистежує Хранителя Ордануса, старшого сина Кенарія, що втік із Піку Кам'яного Кігтя. Переконана, що його народ осквернив давні руїни Високородних, вона посилає героїв Орди через кордон до Ашенвалю — по його голову.",h="Брейлін Файргенд із Притулку Сонячної Скелі магічним зором вистежує Хранителя Ордануса, старшого сина...",kw={"орданус","кенарій","брейлін файргенд","високородні","ашенваль","притулок рейнвуд"},ang={["class:Druid"]="Друїди Орди в цьому завданні опиняються перед похмурим вибором: щоб утамувати давню ворожнечу кривавої ельфійки, їм доведеться відібрати життя в рідного сина Кенарія.",["class:Mage"]="Брейлін Файргенд уособлює непохитну чародійську гординю Високородних, які ставлять тайну магію вище за кенарійську філософію природи.",["faction:Horde"]="Убивство старшого сина Кенарія підриває владу нічних ельфів на кордоні Ашенвалю й Гір Кам'яного Кігтя і допомагає Орді просуватися в спірні лісові угіддя."},sec={{t="Полювання, яке живлять давні образи",b="Брейлін Файргенд прибула в Гори Кам'яного Кігтя з наказу свого господаря, щоб повернути священні руїни давніх храмів Азшари. На піку вона застала нічних ельфів, які вже облаштувалися там і ставилися до реліквій її високородних предків як до дикої глушини, яку треба приборкати. Її головна ціль, Хранитель Орданус, утік, перш ніж вона встигла загнати його в кут, і непомітно перебрався через кордон до Ашенвалю. Магічним зором Брейлін розгледіла його схованку — високий дерев'яний прихисток у Притулку Рейнвуд — і закликала Орду завершити полювання."},{t="Нащадок лісового бога",b="Орданус — один із найстарших синів Кенарія, глибоко пов'язаний із дикою магією Калімдору. Охоронці з нічних ельфів перевели його з Піку Кам'яного Кігтя до Притулку Рейнвуд, щоб уберегти від чародійських сил, що підступали до священних гаїв. Під захистом відданих кенарійських поборників і викликаних лісових древолюдів хранитель уособлює і давню владу лісового напівбога, і живу перепону на шляху помсти Брейлін."},{t="Помста Високородних",b="Для Брейлін Файргенд голова Ордануса — справа глибоко особиста, а не лише тактична. Вона відкрито згадує, що знала його століття тому, і пам'ятає зверхність, з якою нащадки Кенарія дивилися на Високородних та їхнє володіння тайною магією. Відтявши йому голову, вона помститься за давні образи й розчистить шлях для глибших задумів свого господаря в дикій глушині Калімдору."}},faq={{q="Хто такий Хранитель Орданус?",a="Орданус — хранитель гаю й один з найстарших синів напівбога Кенарія. Спершу він перебував біля Піку Кам'яного Кігтя, а потім утік в Ашенваль, рятуючись від помсти Високородних.",al={"лор ордануса","хто такий орданус","хто хранитель орданус"}},{q="Де знайти Хранителя Ордануса?",a="Орданус живе на верхівці величезного дуплистого дерева в Притулку Рейнвуд, при дорозі через центральний Ашенваль.",al={"місце ордануса","де орданус","дерево притулку рейнвуд"}},{q="Чому Брейлін Файргенд хоче смерті Ордануса?",a="Брейлін вважає присутність нічних ельфів у Горах Кам'яного Кігтя оскверненням давніх храмових руїн Високородних. До того ж вона давно й особисто ненавидить Ордануса, пам'ятаючи, яким пихатим і зневажливим він був до її народу в минулі віки.",al={"чому брейлін хоче вбити ордануса","образа брейлін","чому брейлін хоче ордануса"}},{q="Хто господар Брейлін Файргенд?",a="Брейлін каже, що служить господареві, який послав її на Пік Кам'яного Кігтя повернути давні храмові руїни Азшари, але хто саме цей господар, вона ретельно приховує.",al={"господар брейлін","хто послав брейлін","господар брейлін файргенд"}},{q="Як цей конфлікт пов'язаний із присутністю Орди в Горах Кам'яного Кігтя?",a="Сили Орди з Притулку Сонячної Скелі раз у раз сходяться з вартовими нічних ельфів і захисниками-кенарійцями за землі й ресурси Гір Кам'яного Кігтя й Ашенвалю, тож удар Брейлін по кенарійському провідникові вигідний обом.",al={"чому орда допомагає брейлін","мотиви орди в стоунталоні"}},{q="Що буде, коли Орданус загине?",a="Коли Орданус мертвий, Брейлін нагороджує поборника й спрямовує його до завдання «Лігво», щоб глибше зануритися в загрози серед вершин Кам'яного Кігтя.",al={"що після ордануса","завдання після ордануса","лігво далі"}}},fp="7,272,32.520.0,27.444.0,19.389.1,22.193.0,34.133.0,44.232.0,33.179.0,67.239.0,36.157.1"}
P.entries["quest:1089"] = {n="Лігво",s="«Лігво» — кульмінація таємної кампанії Орди проти друїдів нічних ельфів, що окопалися на Піку Кам'яного Кігтя. За вказівкою кривавої ельфійки-агентки Брейлін Файргенд герої спускаються в підземні зали притулку в Лігві Кігтя, щоб зламати багатоступеневий захист і забрати приховані реліквії друїдів.",h="«Лігво» — кульмінація таємної кампанії Орди проти друїдів нічних ельфів, що окопалися на Піку Кам'яного Кігтя.",kw={"лігво кігтя","пік кам'яного кігтя","друїди","ключ воротаря","брейлін файргенд","реліквії"},ang={["class:Druid"]="Для друїдів-тауренів з Орди тут криється гірка іронія: ключі, створені за традиційним задумом притулків і названі на честь Сплячих, Кігтів і Притулків, вони обертають проти таких самих кенарійських хранителів.",["class:Rogue"]="Щоб прокрастися тінистими залами притулку й поцупити ключі з потаємних ліхтарів і тримачів для смолоскипів, знадобиться неабияка вправність у проникненні та хитрощах.",["faction:Horde"]="Набіг на Лігво Кігтя ламає хребет оборони нічних ельфів на Піку Кам'яного Кігтя: Орда закріплює за собою підступи до гори й захоплює могутні магічні реліквії.",["race:NightElf"]="Осквернення Лігва Кігтя — тяжке порушення священних притулків: давній сон кенарійських охоронців перервано, а їхні реліквії, захищені замками-оберегами, розграбовано."},sec={{t="Підземні таємниці",b="Лігво Кігтя на самій вершині Гір Кам'яного Кігтя — підземна твердиня друїдів нічних ельфів. Ці зали, глибоко висічені в живому камені, мають оберігати охоронців, занурених у медитацію, і ховати священні скарби від чужих очей. Знаючи, яку стратегічну й чародійську цінність має те, що спочиває всередині, Брейлін Файргенд допитує полоненого друїда, щоб вирвати в нього таємниці їхнього захисту."},{t="Ланцюжок замків",b="Щоб уберегти найпотужніші реліквії, друїди не покладалися на одні двері, а вигадали хитромудрий механізм. На порозі підземних залів, у звичайнісінькому ліхтарі, сховано Ключ Воротаря. Він відмикає три схованки, розкидані глибше в лабіринті, — у них лежать Ключ Сплячих, Кігтистий Ключ і Ключ від Притулку. Лише коли всі три різьблені камені повернуто в центральній скарбниці, друїдські печаті розвіюються й віддають давні предмети до рук Орди."}},faq={{q="Що таке Лігво Кігтя?",a="Лігво Кігтя — підземний курганний комплекс нічних ельфів, вирубаний на висотах Піку Кам'яного Кігтя. Це водночас святилище для медитації сплячих друїдів і надійне сховище їхніх священних реліквій.",al={"де лігво кігтя","що таке лігво","курганне лігво стоунталона"}},{q="Хто наказує проникнути в Лігво Кігтя?",a="Нападом керує Брейлін Файргенд — агентка-син'дорейка, що діє разом з Ордою в Горах Кам'яного Кігтя. Вивідавши важливі відомості в нещасного полоненого друїда, вона посилає агентів Орди обійти захисні чари святилища й пограбувати його скарб.",al={"хто наказує проникнути в лігво","мета брейлін файргенд","хто послав у лігво"}},{q="Як працюють ключі в Лігві?",a="Головний Ключ Воротаря захований у ліхтарі біля входу. Він відмикає три схованки, розкидані по кургану, де лежать Ключ Сплячих, Кігтистий Ключ і Ключ від Притулку. Коли їх разом вставити у вирізьблене кам'яне сховище, чари розвіюються.",al={"як використовувати ключі","як відкрити скарб лігва кігтя","три ключі стоунталона"}},{q="Чому мішенню стали друїди з Піку Кам'яного Кігтя?",a="Брейлін Файргенд хоче відновити плин магії в краї й звинувачує в його блокуванні друїдів Піку Кам'яного Кігтя й синів Кенарія. Вона домагається їхньої смерті, а також смерті їхнього провідника, Хранителя Ордануса, якого, за її словами, колись знала, а тоді посилає вас винести з Лігва його могутні речі.",al={"чому друїди пік стоунталона мішень","причина орди вбити ордануса","навіщо грабувати лігво"}},{q="Що лежить у Скарбі Лігва Кігтя?",a="У скарбі — могутні реліквії й коштовності, зібрані друїдами нічних ельфів. Захищені кількома шарами охоронних чарів, ці речі були в безпеці від чужинців, доки Брейлін не видобула силою послідовність їхнього захисту.",al={"що в скарбі лігва кігтя","лор скарбу лігва кігтя","що сховали друїди"}},{q="Що сталося просто перед цим завданням?",a="Перш ніж вдертися в Лігво, шукачі пригод з Орди мають розібратися з нічними ельфами в завданні «Спадок Кенарія» й убити хранителя Ордануса, щоб розладнати командування захисників.",al={"що передує лігву","ланцюжок лігва","передумови лігва"}}},fp="7,309,20.428.0,17.496.1,22.209.0,45.262.0,36.254.0,53.304.0,35.216.0,38.193.0"}
P.entries["quest:109"] = {n="Доповісти Ґраяну Стаутмантлу",s="Це доручення скеровує досвідчених шукачів пригод, що виходять із Лісу Елвінн, до знесиленого прикордоння Вестфолу. Корона занедбала далекі ниви, тож місцеві захисники покладаються на охочих найманців, які згуртуються довкола Ґраяна Стаутмантла в Сентінел Гіллі.",h="Це доручення скеровує досвідчених шукачів пригод, що виходять із Лісу Елвінн, до знесиленого прикордоння...",kw={"ґраян стаутмантл","сентінел гілл","народне ополчення","ліс елвінн","вестфол","новобранці"},ang={["class:Warrior"]="Ґраян Стаутмантл понад усе цінує загартовану бойову дисципліну, тож досвідчені бійці передової — неоціненна підмога для нечисленного Народного ополчення.",["faction:Alliance"]="Це доручення показує внутрішню напругу, що випробовує Альянс: поки королівський двір сперечається про політику в Стормвінді, звичайні громадяни мусять самі збирати ополчення, щоб вижити.",["race:Human"]="Для людей королівства дорога до Вестфолу показує різкий контраст між безпечними мармуровими вулицями Стормвінда й суворою, занедбаною дійсністю його віддалених нив."},sec={{t="Заклик з-за річки",b="Хай його передають вартові на кордонах Елвінну чи зневірені фермери, що тікають на захід, заклик однаковий: за річкою потрібні вправні бійці. Вестфол стрімко поринає в хаос — грабіжники, гноли й ворожі жнивні големи заполонили колишню житницю королівства. Королівські батальйони на заклик не відгукуються, тож ті, хто хоче боронити королівство, мусять ставати до лав місцевих добровольців."},{t="Сентінел Гілл і ополчення",b="Пройшовши дорогою до Вестфолу, новобранці знаходять Ґраяна Стаутмантла в укріпленій кам'яній вежі на вершині Сентінел Гілла. Стаутмантл очолює Народне ополчення — неофіційну спілку місцевих фермерів, ветеранів у відставці й найманців, що постала саме як відповідь на бездіяльність корони. Дістатися до нього — означає вступити в запеклу партизанську війну за те, щоб ниви не поглинуло беззаконня."}},faq={{q="Хто такий Ґраян Стаутмантл?",a="Ґраян Стаутмантл — досвідчений воїн і командир Народного ополчення. Із вежі на вершині Сентінел Гілла він організовує оборону й набирає охочих бійців, щоб захищати Вестфол від бандитів і звірів, що загрожують його фермерам.",al={"хто такий ґраян","ґраян стаутмантл","керівник сентінел гілла"}},{q="Навіщо потрібне Народне ополчення?",a="Армія Стормвінда зосередилася на самій столиці, і віддалені краї на кшталт Вестфолу майже не мають підтримки корони. Мешканці створили Народне ополчення як загони самооборони від бандитів, збунтованих автоматів-жниварів і гнолів Річколапів, що грабують округу.",al={"навіщо ополчення","чому немає армії стормвінда","чому вестфол покинуто"}},{q="Де розташований Сентінел Гілл?",a="Сентінел Гілл стоїть майже в центрі Вестфолу при головній дорозі. Пагорб увінчує міцна кам'яна вартова вежа й укріплений табір, де збирається Народне ополчення.",al={"де сентінел гілл","місце сентінел гілла","де шукати стаутмантла"}},{q="Хто посилає шукачів пригод із цим дорученням?",a="Кілька стурбованих людей спрямовують сюди шукача пригод, щойно той доведе свою вправність: Маршал Дуґан із Ґолдширу, прикордонні вартові на кшталт Вартового Томаса й Помічника Рейнера або місцеві, що втратили домівки, як-от Фермер Фурлброу й Фермер Салдін.",al={"хто дає завдання","давці завдань","давець доповіді ґраяну"}},{q="Що буде, коли доповіси Ґраянові?",a="Коли ви доповідаєте Стаутмантлові, він залучає вашу бойову вправність на службу Народного ополчення: спершу треба прорідити розбійників Дефіас і гнолів, що загрожують краю.",al={"що після доповіді","продовження стаутмантла","ланцюжок ополчення"}},{q="Чи Вестфол формально досі належить до Альянсу?",a="Так, Вестфол — територія Альянсу під номінальною владою Королівства Стормвінд. Проте місцеві вельми незадоволені, бо королівський гарнізон занедбав провінцію, і її виживання лягло на плечі озброєних мешканців.",al={"чи вестфол досі в альянсі","чи стормвінд володіє вестфолом"}}},fp="27,253,23.440.0,29.439.0,25.262.0,35.286.0,31.183.0,41.230.0,38.203.0,51.245.0"}
P.entries["quest:1090"] = {n="Накази Ґерензо",s="На розкопі Венчурної Компанії в Горах Кам'яного Кігтя скинутий із посади гоблін Пізнік плете інтриги, щоб викрити свого нового боса, Ґерензо. Захищаючи Пізніка від табірних патрулів, поки той видобуває дивну золотаво-зелену руду, шукачі пригод допомагають розкрити прибуткові таємниці, що стоять за завзятими розкопками компанії.",h="На розкопі Венчурної Компанії в Горах Кам'яного Кігтя скинутий із посади гоблін Пізнік плете інтриги, щоб...",kw={"пізнік","ґерензо","венчурна компанія","золотаво-зелена руда","зіз фіззікс","гори кам'яного кігтя"},ang={["faction:Horde"]="Безрозсудний, загарбницький видобуток Венчурної Компанії плюндрує природу Гір Кам'яного Кігтя, тож будь-яка спроба стежити за її роботою, зірвати її чи обернути собі на користь стане в пригоді загонам Орди поблизу.",["profession:Mining"]="Дивна золотаво-зелена руда, яку знайшли гірники Венчурної Компанії в Горах Кам'яного Кігтя, не схожа на звичні залізні чи олов'яні жили — тож неабияк зацікавить кожного рудошукача, небайдужого до рідкісних мінералів."},sec={{t="Корпоративна зрада серед скель",b="Розмах Венчурної Компанії в Горах Кам'яного Кігтя тримається на нещадній конкуренції: підвищення тут здобувають безжальністю, а не вірністю. Колись Пізнік був другим після керівника на розкопі, але Ґерензо захопив владу, усунув наглядача Зіза Фіззікса й понизив Пізніка до звичайного копача з кайлом. Пізнік не пішов геть, а залишився інформатором за вказівкою Зіза: він стежить за кожним кроком Ґерензо й вичікує нагоди відплатити віроломному новому начальникові."},{t="Золотаво-зелена жила",b="За раптовим захопленням влади стоїть одержимість Ґерензо загадковою золотаво-зеленою рудою, що пронизує скелі Кам'яного Кігтя. Переконаний, що мінерал має надзвичайну комерційну цінність, Ґерензо наказав гірникам видирати його із землі величезними обсягами. Підозрюючи, що загадковий новий наймач Зіза Фіззікса щедро заплатить за відомості про цю справу, Пізнік ризикує бути викритим і викопує чистий зразок, покладаючись на союзника, який відбиватиметься від лютих копачів, шкідників і наглядачів, що пильнують за роботою."}},faq={{q="Хто такий Пізнік?",a="Пізнік — гоблін-робітник на промислі Венчурної Компанії на Кручі Вітрорізу в Горах Кам'яного Кігтя. Колись він був другим за важливістю управителем на розкопі під началом Зіза Фіззікса, але коли владу захопив Ґерензо, Пізніка понизили до простого робітника в шахтах.",al={"пізнік","хто гоблін-шахтар","пізнік стоунталон"}},{q="Чому Пізнік потай добуває цю руду?",a="Пізнік потай набирає зразок дивного золотаво-зеленого мінералу, який Ґерензо наказав добувати у величезних кількостях. Його колишній бос, Зіз Фіззікс, пообіцяв, що новий наймач щедро заплатить за відомості про цінну справу, яку проворачує Ґерензо.",al={"чому пізнік добуває руду","таємнича руда","золота зелена руда"}},{q="Хто такий Ґерензо?",a="Ґерензо — безжальний наглядач Венчурної Компанії, що взяв розкопки в Горах Кам'яного Кігтя під свій контроль, звільнивши Зіза Фіззікса. Він одразу спрямував ресурси компанії на хижацький видобуток незнайомої, цінної золотаво-зеленої руди, яка трапляється по всій кручі.",al={"ґерензо","хто такий ґерензо","ґерензо венчурна компанія"}},{q="На кого тепер працює Зіз Фіззікс?",a="Звільнений Ґерензо, Зіз Фіззікс пристав до нових покровителів, яким цікаво стежити за діями Венчурної Компанії в краї. Він платить агентам та інформаторам на кшталт Пізніка, щоб ті шкодили Ґерензо й з'ясували, що саме Венчурна Компанія викопує.",al={"хто тепер бос зіза","хто найняв зіза","роботодавець зіза"}},{q="Хто нападає на Пізніка, поки той копає?",a="Під час видобутку нападають працівники Венчурної Компанії: Тунельні щури Зрізаного Вітру, Шкідники Зрізаного Вітру, копачі, геоманти, каменотеси й наглядачі.",al={"засідка на пізніка","хто нападає на пізніка","патрулі вітрорізу"}},{q="Що буде, коли зразок видобуто?",a="Щойно Пізнік видобуде зразок руди, він віддає його своєму захисникові, щоб той доставив його просто Зізові Фіззіксу, — сподіваючись, що це дасть важіль, потрібний, аби зірвати честолюбні задуми Ґерензо.",al={"куди нести руду","що робити зі зразком"}}},fp="16,300,30.527.0,30.511.0,14.259.0,39.273.0,15.260.0,34.252.0,34.154.0,38.190.0"}
P.entries["quest:1091"] = {n="Новини від Каели",s="«Новини від Каели» — доручення Альянсу в Горах Кам'яного Кігтя: доставити перехоплене листування агентам на передовій. Гном-маг Ґаксим Растфіззл відсилає шукача пригод назад до Каели Шедовспір із перехопленими листами Венчурної Компанії. Ці відомості допомагають Вартовим нічних ельфів стежити, як гоблінський картель руйнівно розповзається священними землями.",h="«Новини від Каели» — доручення Альянсу в Горах Кам'яного Кігтя: доставити перехоплене листування агентам на...",kw={"каела шедовспір","ґаксим растфіззл","вартові","венчурна компанія","листи","круча вітрорізу"},ang={["faction:Alliance"]="Доставлене перехоплене листування Венчурної Компанії зміцнює хиткий плацдарм Альянсу в Горах Кам'яного Кігтя проти корпоративного грабунку.",["race:Gnome"]="Ґаксим Растфіззл гордо уособлює гномську чародійську винахідливість і пильнує, щоб його союзники, нічні ельфи, неодмінно визнали незамінність гномської магії.",["race:NightElf"]="Кожна крихта відомостей про Венчурну Компанію допомагає Вартовим захищати поранену дику природу Калімдору від промислового осквернення."},sec={{t="Посланець у горах",b="Після того як шукач пригод допоміг гному-магу Ґаксиму Растфіззлу розкрити пересування Венчурної Компанії, той збирає здобуті листи з подробицями дій картелю. Ґаксим не з тих, хто впустить нагоду приписати собі заслугу, тож відсилає посланця просто до Каели Шедовспір — нічної ельфійки, що керує Вартовими біля Кручі Вітрорізу. І неодмінно нагадує розповісти, як саме його магічна вправність забезпечила успіх розслідування."},{t="Очі Вартових",b="Вартові в Горах Кам'яного Кігтя з дедалі більшою тривогою стежать за кручами. Поки загони Орди змагаються за нижні стежки, суцільні вирубки й гірничі машини Венчурної Компанії становлять безпосередню загрозу і для природи, і для оборони. Листи, які здобув Ґаксим, дають Каелі цінне уявлення про внутрішнє листування картелю й зміцнюють оборонні плани Альянсу вздовж хребтів."}},faq={{q="Хто така Каела Шедовспір?",a="Каела Шедовспір — офіцерка Вартових із нічних ельфів, що служить Альянсу в таборі біля Кручі Вітрорізу. Вона керує розвідкою й обороною як від Орди, що насувається, так і від руйнівних підприємств гоблінських гірничих компаній у горах.",al={"каела шедовспір","хто така каела","каела стоунталон"}},{q="Хто такий Ґаксим Растфіззл?",a="Ґаксим Растфіззл — завзятий гном-маг, що працює в Горах Кам'яного Кігтя. Своїми магічними вміннями він розвідує й зриває роботи Венчурної Компанії, тісно співпрацюючи з місцевими Вартовими нічних ельфів.",al={"ґаксим","ґаксим растфіззл","гном-маг стоунталон"}},{q="Що в листах Венчурної Компанії?",a="У листах — внутрішнє листування Венчурної Компанії, перехоплене під час операцій проти їхніх таборів. Вони дають Каелі Шедовспір і Вартовим важливі відомості про місцеве постачання картелю, розкопки й хижацький видобуток ресурсів.",al={"листи венчурної компанії","що в листах","листи для каели"}},{q="Чому Вартових турбує Венчурна Компанія?",a="Венчурна Компанія суцільно вирубує священні ліси й калічить землю безоглядними гірничими машинами. Для Вартових ця невпинна індустріалізація — образа природи й пряма загроза святості Кам'яного Кігтя.",al={"чому вартові турбуються про гоблінів","вартові й венчурна компанія","венчурна компанія стоунталон"}},{q="Де починається й закінчується це завдання?",a="Завдання починається в Ґаксима Растфіззла на гірських стежках і закінчується в Каели Шедовспір у її таборі біля Кручі Вітрорізу.",al={"місце завдання","здача новин каели","де каела"}},{q="Чи веде це завдання до подальших розслідувань?",a="Доставлені листи тримають Вартових у курсі справ картелю, тож Каела може планувати подальші військові відповіді й розвідку по всіх Горах Кам'яного Кігтя.",al={"наступне завдання","що після новин каели","продовження"}}},fp="14,367,28.421.0,21.394.0,25.261.0,24.215.0,39.255.0,58.224.0,36.135.0,47.181.0"}
P.entries["quest:1092"] = {n="Накази Ґерензо",s="Відбившись від патрулів на розкопі й здобувши зразок дивної руди, яку наказав видобувати Ґерензо, Пізнік відсилає шукачів пригод віднести її своєму зв'язковому, Зізові Фіззіксу. Ця доставка завершує ризиковану оборудку корпоративного шпигунства в самому серці робіт Венчурної Компанії на Кручі Вітрорізу.",h="Відбившись від патрулів на розкопі й здобувши зразок дивної руди, яку наказав видобувати Ґерензо, Пізнік...",kw={"пізнік","зіз фіззікс","невпізнана руда","круча вітрорізу","андермайн","шпигунство"},ang={["profession:Engineering"]="Гоблінські інженери в Андермайні щедро платять за необроблені екзотичні руди, здатні живити непередбачувані нові механізми й прототипи.",["profession:Mining"]="Невпізнана Руда, видобута за наказом Ґерензо, показує: Венчурна Компанія на Кручі Вітрорізу не лише вирубує ліси, а й так само завзято нишпорить у горах у пошуках невідомих підземних багатств."},sec={{t="Квиток на волю",b="Після бійки на розкопі прикриття Пізніка розкрито, і він розуміє, що його час серед робітників Венчурної Компанії на Кручі Вітрорізу сплив. Керівництво в Андермайні не милує за внутрішні диверсії, тож знервований гоблін готує втечу. Перш ніж зникнути в пошуках нового наймача, він довіряє чужинцеві Невпізнану Руду, видобуту за наказом Ґерензо: так цінний зразок дістанеться за призначенням, не накликавши на самого Пізніка підозри."},{t="Корпоративні дивовижі",b="Руда має потрапити до Зіза Фіззікса, який облаштував потаємну стоянку на західному краю Кручі Вітрорізу. Зіз розуміє стратегічну цінність мінералу: він збирається відіслати його на південь, інженерам Андермайну, а тим часом тишком відщипнути добрий шмат собі на зиск. Такий корисливий прагматизм добре показує, якою безжальною буває боротьба за торгівлю й інженерні секрети під вершинами Гір Кам'яного Кігтя."}},faq={{q="Чому Пізнікові треба тікати з Кручі Вітрорізу?",a="Наглядачі розкопу спіймали Пізніка, коли той потай добував для Зіза зразок руди, і викрили його як інформатора. Він знає, що щойно до верхівки Венчурної Компанії дійдуть чутки про цей випадок, розплата не забариться, тож мусить непомітно втекти й пошукати нову роботу.",al={"чому пізнік тікає","пізнік утікач","чому пізнік наляканий"}},{q="Хто такий Зіз Фіззікс?",a="Зіз Фіззікс — гоблін-ділок, що отаборився на західному гребені Кручі Вітрорізу. Він підсадив Пізніка у Венчурну Компанію, щоб красти корпоративні відомості й рідкісні зразки мінералів.",al={"хто такий зіз","роль зіза фіззікса","де зіз"}},{q="Що таке Невпізнана Руда?",a="Це зразок загадкової золотаво-зеленої руди, яку Головний Інженер Ґерензо наказав добувати у великих кількостях. Зіз Фіззікс збирається відіслати її дослідникам та інженерам в Андермайн, щоб ті визначили, де її можна застосувати в промисловості.",al={"невпізнана руда","що за руда","руда ґерензо"}},{q="Де знайти Зіза Фіззікса?",a="Зіз Фіззікс ховається в невеликому таборі на західному краю над Кручею Вітрорізу в Горах Кам'яного Кігтя.",al={"місце зіза фіззікса","знайти зіза","де здати накази ґерензо"}},{q="Що буде з рудою, коли її отримає Зіз?",a="Більшу частину зразка Зіз збирається переслати інженерам Андермайна заради зиску й репутації, а невеликий уламок потай від наймачів залишити собі.",al={"що зіз робить з рудою","чи зіз залишить руду"}},{q="Чи відданий Пізнік Венчурній Компанії?",a="Пізнік працював на Венчурну Компанію лише стільки, скільки було треба для справ Зіза. Він аніскільки не відданий цьому угрупованню й щиро боїться помсти його керівництва.",al={"фракція пізніка","чи пізнік з венчурної компанії","на кого працює пізнік"}}},fp="16,298,12.479.0,21.444.1,44.277.0,19.182.0,29.220.0,31.126.0,45.173.0,39.171.0"}
P.entries["quest:1093"] = {n="Супержнець 6000",s="«Супержнець 6000» — завдання від невдоволеного гоблінського майстра Зіза Фіззікса на Кручі Вітрорізу в Горах Кам'яного Кігтя. Прагнучи вислужитися перед новим босом Спаттервалвом, Зіз наймає шукачів пригод, щоб ті проникли на місцеву лісорозробку Венчурної Компанії й викрали креслення велетенської лісорубної машини, сконструйованої його суперником — гномом Ґерензо Ренчвіслом.",h="«Супержнець 6000» — завдання від невдоволеного гоблінського майстра Зіза Фіззікса на Кручі Вітрорізу в Горах...",kw={"супержнець 6000","зіз фіззікс","ґерензо ренчвісл","спаттервалв","креслення","інженерія"},ang={["profession:Engineering"]="Це завдання показує віковічне суперництво гоблінського прагматизму — вибухового, швидкого й грубого — з гномським конструюванням, що понад усе цінує надмірну складність і точність.",["race:Gnome"]="Зіз не може повірити, що гоблінський синдикат довірив гномові будувати свою флагманську машину, — і сам опиняється цілком спантеличений технічним генієм цього гнома.",["race:NightElf"]="Супержнець 6000 — вершина зневаги смертних до природи: він суцільно вирубує прадавні дерева в Горах Кам'яного Кігтя, щоб нагодувати ненаситну пащу промислового зиску."},sec={{t="Промислове шпигунство на Кручі Вітрорізу",b="Венчурна Торгова Компанія випалила промисловий шрам просто в серці Гір Кам'яного Кігтя, нещадно вирубуючи ліси на Кручі Вітрорізу. Та під смогом і крутими лезами ховається дріб'язкове корпоративне суперництво. Зіз Фіззікс, гоблінський інженер, якого нещодавно вигнали з лав Венчурної Компанії, знайшов роботу у Спаттервалва. Прагнучи закріпитися на новому місці й показати, чого вартий, Зіз хоче заполучити найцінніший механічний скарб Венчурної Компанії — креслення її величезної автоматичної лісорубної машини, Супержнеця 6000."},{t="Гобліни проти гномської інженерії",b="Неабияка частка пекучої образи Зіза — від гордощів. Венчурна Компанія, формально гоблінський синдикат, порушила традицію й поставила на чолі місцевих інженерних робіт гнома — Ґерензо Ренчвісла. Коли креслення нарешті вирвано з рук машиністів Венчурної Компанії, Зіз доходить до відчаю: заплутана, перфекціоністська манера гномського креслярства майже зовсім незбагненна для гоблінського інженера, звиклого до грубої сили, дешевих деталей і некерованих вибухів пального."}},faq={{q="Хто такий Зіз Фіззікс?",a="Зіз Фіззікс — гоблін-інженер, що живе в Горах Кам'яного Кігтя. Нещодавно Венчурна Компанія його звільнила, але його швидко найняв Спаттервалв, впливовий ділок у цих краях, і тепер Зіз прагне поквитатися з колишніми наймачами.",al={"зіз фіззікс","хто дає завдання","зіз"}},{q="Що таке Супержнець 6000?",a="Супержнець 6000 — величезна механічна лісоповальна машина, яку сконструював Ґерензо Ренчвісл для лісозаготівель Венчурної Компанії на Кручі Вітрорізу.",al={"супержнець 6000","що таке супержнець","що за машина"}},{q="Хто сконструював Супержнеця 6000?",a="Його сконструював Ґерензо Ренчвісл — гном-майстер, найнятий Венчурною Компанією, і цей факт глибоко ображає гоблінів-інженерів, які раніше керували розкопом.",al={"хто зробив супержнеця","хто збудував машину","ґерензо ренчвісл"}},{q="Навіщо Спаттервалву креслення?",a="Спаттервалв прагне доступу до передових технологій важкого лісоповалу, які розробила Венчурна Компанія, а Зіз Фіззікс охоче їх роздобуде, щоб довести новому наймачеві свою корисність.",al={"навіщо спаттервалву креслення","чому красти креслення"}},{q="Де знайти креслення?",a="Креслення носять оператори машин Венчурної Компанії, що наглядають за лісозаготівельною технікою на Кручі Вітрорізу.",al={"де креслення","звідки креслення"}},{q="Чому Зіз ледве може прочитати здобуті креслення?",a="Гоблінська й гномська школи інженерії сумнозвісно несумісні. Педантичні, заплутані схеми Ґерензо Ренчвісла здаються Зізові надто складними, і з першого погляду їх не розібрати.",al={"чому зіз не може прочитати","гномські креслення гоблін"}}},fp="17,395,38.548.0,31.520.1,19.241.0,30.166.0,35.162.0,42.190.0,31.123.0,60.200.1"}
P.entries["quest:1094"] = {n="Подальші вказівки",s="«Подальші вказівки» — завдання з доставки, що пов'язує безладну лісорозробку в Горах Кам'яного Кігтя з торговим вузлом Раджетом. Невдоволений майстер Зіз Фіззікс відсилає посланця з викраденими кресленнями й внутрішніми документами до свого спільника Спаттервалва, щоб обернути корпоративне шпигунство на особисту вигоду.",h="«Подальші вказівки» — завдання з доставки, що пов'язує безладну лісорозробку в Горах Кам'яного Кігтя з...",kw={"подальші вказівки","зіз фіззікс","спаттервалв","раджет","креслення","шпигунство"},ang={["faction:Horde"]="Доставка викрадених планів Венчурної Компанії до Раджета підживлює тліючі торгові війни, які стримують небезпечне промислове вторгнення поблизу земель Орди.",["profession:Engineering"]="Цей конверт — класичний приклад гоблінської промисловості в дії: безжальне корпоративне шпигунство, крадіжка патентів і розбирання складних лісозаготівельних машин, щоб збагнути, як вони влаштовані."},sec={{t="Корпоративне шпигунство",b="Коли Зіза Фіззікса вигнали з лісорозробки Венчурної Компанії на Кручі Вітрорізу, він пішов не з порожніми руками. Ображений звільненням, Фіззікс прихопив цілу купу секретних документів, внутрішніх інструкцій і технічних схем, а на додачу — цінні креслення експериментального Супержнеця 6000. Відчайдушно шукаючи покупця чи спільника, який захоче цими даними скористатися, він запечатав зібрані таємниці в конверт із позначкою «Раджет»."},{t="Ниточка до Раджета",b="Викрадені документи призначено Спаттервалву — інженерові, що працює в нейтральному порту Раджет у Пустках. Хоча Спаттервалв не має до Фіззікса ні особливої симпатії, ні довіри, суперництво з Венчурною Компанією не дає відмовитися від такої пропозиції. Гобліни, що тримаються картелю Стімвідл, постійно шукають способів урізати вплив свого безжального конкурента — і залюбки розбирають до гвинтика будь-які кращі механічні винаходи, що трапляються їм під руку."}},faq={{q="Що в Запечатаному Конверті?",a="У конверті — внутрішні документи Венчурної Компанії, технічні посібники й креслення Супержнеця 6000, які Зіз Фіззікс викрав, коли його вигнали з лісозаготівель компанії.",al={"що в конверті","що зіз надсилає","вкрадені документи"}},{q="Хто такий Спаттервалв?",a="Спаттервалв — гоблін-інженер, що живе в Раджеті в Пустках. Хоч він і не надто довіряє Зізові Фіззіксу, йому дуже хочеться послабити Венчурну Компанію й дослідити її механічні здобутки.",al={"спаттервалв","хто отримувач","інженер раджета"}},{q="Чому Зіз Фіззікс діє проти Венчурної Компанії?",a="Фіззікса безцеремонно вигнали з лав Венчурної Компанії в Горах Кам'яного Кігтя. Сповнений злоби й жаги помсти, він почав зливати її торговельні таємниці суперникам.",al={"чому зіз проти венчурної компанії","мотив фіззікса"}},{q="Де знайти Спаттервалва?",a="Спаттервалв перебуває в нейтральному портовому містечку Раджет на східному узбережжі Пусток.",al={"де спаттервалв","місце спаттервалва","знайти спаттервалва"}},{q="Чи довіряє Спаттервалв Зізові Фіззіксу?",a="Ні, Спаттервалв відверто визнає, що не довіряє Фіззіксу, але цінність технічних посібників і креслень переважує його насторожене ставлення до посланця.",al={"чи спаттервалв довіряє зізу","стосунки спаттервалва й зіза"}},{q="Що таке Супержнець 6000?",a="Це вдосконалений промисловий подрібнювач, який Венчурна Компанія розробила, щоб розчищати ліси й переробляти деревину на великій швидкості, тож його креслення — ласий шматок.",al={"супержнець 6000","що за машина","жнець венчурної компанії"}}},fp="20,331,19.466.0,22.486.0,35.189.0,20.198.0,55.162.0,32.110.0,36.152.0,30.159.0"}
P.entries["quest:1096"] = {n="Ґерензо Ренчвісл",s="Це завдання за винагороду доручає шукачам пригод усунути Ґерензо Ренчвісла — свавільного гнома-наглядача, що засів високо над Озером Скельної Заводі в Горах Кам'яного Кігтя. Ґерензо щедро доповнив свою гниючу плоть шестернями, годинниковими механізмами й штучними кінцівками. Гоблінський інженер Зіз Фіззікс хоче отримати його механічну руку як незаперечний доказ смерті, щоб заслужити жадане підвищення від начальства.",h="Це завдання за винагороду доручає шукачам пригод усунути Ґерензо Ренчвісла — свавільного гнома-наглядача, що...",kw={"ґерензо ренчвісл","механічна рука","озеро скельної заводі","зіз фіззікс","спілка винахідників","протези"},ang={["faction:Horde"]="Допомога гоблінським підрядникам у Горах Кам'яного Кігтя дає змогу здобути цінні ресурси й землі та водночас приборкати небезпечних свавільних інженерів серед круч.",["profession:Engineering"]="Моторошна будова механічної руки Ґерензо — тривожна крайність гномської біонічної інженерії, що різко контрастує з практичним гоблінським конструюванням.",["race:Gnome"]="Ґерензо — дивакуватий і зловісний відступ від звичної гномської винахідливості: щоб зберегти немічне тіло, він вдається до радикального самовдосконалення."},sec={{t="Жахливий гібрид",b="Ґерензо Ренчвісл сумно відомий навіть серед бувалих майстрів своїми моторошними тілесними перетвореннями. Як розповідають ті, хто його бачив, його власна плоть ніби гниє, а поверх неї — приживлені шестерні, залізні пластини й дзижчасті годинникові протези. Засівши біля величезного водяного колеса високо над Озером Скельної Заводі, гном наглядає за роботами з механічною точністю й моторошною байдужістю до власного смертного тіла."},{t="Гоблінські амбіції",b="Зіз Фіззікс, гоблін, що працює на Спаттервалва, бачить у падінні Ґерензо свій золотий квиток із глухих закутків Гір Кам'яного Кігтя. Не маючи сили ні видертися на кручі, ні самотужки здолати вдосконаленого наглядача, Зіз наймає шукача пригод, щоб той повалив Ґерензо й приніс його механічну руку. З цим трофеєм Зіз сподівається довести, чого вартий, і домогтися переведення до престижних майстерень Спілки Винахідників у Ґаджетзані чи Андермайні."},{t="Зіткнення філософій",b="Механічна рука Ґерензо яскраво показує глибоку ідейну прірву між гоблінською та гномською інженерними традиціями. Ґерензо вдався до крайнього, суто гномського кроку — відтяв немічну плоть, щоб приладнати складні протези, — а гобліни такої жертви просто не розуміють. Як зауважує Зіз, справжній гоблінський винахідник не викидав би живу руку — він просто приробив би поряд із двома іншими третю, вибухову."}},faq={{q="Хто такий Ґерензо Ренчвісл?",a="Ґерензо Ренчвісл — гном-ренегат і наглядач у Горах Кам'яного Кігтя. Він сумнозвісний тим, що замінює частини свого тіла й кінцівки, які гниють, механічними протезами й шестернями, і пильнує промислові роботи високо над Озером Скельної Заводі.",al={"ґерензо","хто такий ґерензо","лор ґерензо"}},{q="Де знайти Ґерензо Ренчвісла?",a="Ґерензо на північний схід від табору Зіза Фіззікса, високо над водами Озера Скельної Заводі, біля великого промислового водяного колеса.",al={"місце ґерензо","знайти ґерензо","де ґерензо"}},{q="Чому Зіз Фіззікс хоче смерті Ґерензо?",a="Зіз Фіззікс діє з наказу Спаттервалва. Усунувши Ґерензо, Зіз доведе свою вправність і сподівається, що за це його переведуть до великої майстерні Спілки Винахідників у Ґаджетзані чи Андермайні.",al={"чому зіз хоче вбити ґерензо","мотив зіза","ціль зіза фіззікса"}},{q="Який доказ вимагає Зіз?",a="Зіз вимагає прищеплену механічну руку Ґерензо — речовий, незаперечний доказ, що наглядача-кіборга остаточно виведено з ладу.",al={"який доказ","доказ ґерензо","предмет завдання"}},{q="Чому Ґерензо частково механічний?",a="Живе тіло Ґерензо, схоже, гнило, тож він прищепив шестерні, залізні пластини й механічні кінцівки просто до свого тіла, щоб підтримувати й посилювати себе.",al={"чому ґерензо кіборг","ґерензо робот","тіло ґерензо"}},{q="Хто такий Спаттервалв?",a="Спаттервалв — помітний гоблін-керівник, що наглядає за роботами й спрямовує підлеглих на кшталт Зіза Фіззікса з іншого кінця Калімдору.",al={"спаттервалв","хто такий спаттервалв"}}},fp="21,399,18.462.0,16.460.0,21.423.0,29.259.0,41.139.0,39.200.0,28.137.0,33.171.0,20.137.0"}
P.entries["quest:1097"] = {n="Доручення Елмора",s="«Доручення Елмора» — завдання гінця для Альянсу, яке дає Коваль Арґус у Ґолдширі. Угледівши у вас надійного мандрівника, Арґус відсилає вас до Дворфійського Кварталу Стормвінда на допомогу майстрові-зброярю Ґріманду Елмору. Це доручення показує тісні зв'язки й торгові шляхи між людьми Елвінна та їхніми союзниками-дворфами.",h="«Доручення Елмора» — завдання гінця для Альянсу, яке дає Коваль Арґус у Ґолдширі.",kw={"доручення елмора","коваль арґус","ґріманд елмор","дворфійський квартал","ґолдшир","айронфордж"},ang={["faction:Alliance"]="Це завдання уособлює щоденну життєво важливу співпрацю між людським королівством Стормвінд і дворфійськими кланами Каз Модану, що підтримує спільну торгівлю й довіру в усьому Альянсі.",["profession:Blacksmithing"]="Хоч доручення відкрите для всіх шукачів пригод, воно поєднує двох помітних майстрів — Коваля Арґуса з Ґолдширу й Ґріманда Елмора зі Стормвінда, — яких єднає ремесло ковадла.",["race:Dwarf"]="Мандрівникам-дворфам буде приємно бачити, як люди визнають майстерність ковалів Айронфорджа й допомагають доправляти припаси назад у північні гори."},sec={{t="Звістка з кузні",b="У Ґолдширі місцевий коваль Арґус пильно виглядає надійних шукачів пригод, здатних не лише розганяти вовків і кобольдів. Ґріманд Елмор, вправний дворф-зброяр, що працює в Стормвінді, розіслав звістку: йому потрібна допомога з важливою доставкою для родичів у північних горах Каз Модану. Побачивши у вас мандрівника з потрібним завзяттям, Арґус скеровує вас до міської брами — відгукнутися на поклик."},{t="Узи, що єднають",b="Для Альянсу вкрай важливо зберігати вільну торгівлю й добру волю між королівством Стормвінд і гірською твердинею Айронфордж. Арґус наголошує: хоч Лісу Елвінн завжди бракує захисників, дотримання зобов'язань перед дворфами-побратимами забезпечує обидва краї припасами й тримає їх у єдності. Ступивши до гамірного, закіптюженого Дворфійського Кварталу на північному сході Стормвінда, ви опиняєтеся просто біля майстерні Елмора — і на порозі мандрівки далеко за межі лісу."}},faq={{q="Хто дає завдання «Доручення Елмора»?",a="Завдання дає Коваль Арґус — місцевий коваль, що працює в кузні в селищі Ґолдшир, трохи на південь від Стормвінда в Лісі Елвінн.",al={"де взяти доручення елмора","хто дає доручення елмора","давець доручення елмора"}},{q="Де знайти Ґріманда Елмора?",a="Ґріманд Елмор працює у зброярні в Дворфійському Кварталі, у північно-східній частині Стормвінда.",al={"місце ґріманда елмора","де ґріманд елмор","знайти елмора в стормвінді"}},{q="Яка мета цього доручення?",a="Коваль Арґус посилає вас до Ґріманда Елмора, бо дворфові-ковалю потрібен надійний посланець, щоб доставити вантаж на його батьківщину на півночі. Це доручення — вступ до ширших мандрів землями Альянсу.",al={"мета доручення","чому до елмора","чого хоче елмор"}},{q="Яке завдання йде після «Доручення Елмора»?",a="Розмова з Ґрімандом Елмором завершує це коротке доручення й одразу відкриває наступне завдання — «Доставка для Стормпайка», у якому треба віднести виготовлений ним вантаж на північ, до Лох Модану.",al={"наступне після доручення елмора","продовження доручення елмора","що після доручення елмора"}},{q="Чому Коваля Арґуса обходять дворфійські доставки?",a="Коваль Арґус зауважує: хоч місцевому ополченню й знадобився б кожен боєздатний у Лісі Елвінн, добрі стосунки й торговельні зв'язки з дворфійськими союзниками в Каз Модані вкрай важливі для безпеки й постачання Стормвінда.",al={"чому арґус допомагає дворфам","коваль арґус дворфійські зв'язки"}},{q="Чи треба бути ковалем, щоб узяти це завдання?",a="Ні. Хоч завдання дає один коваль, а здають його іншому, це звичайне доручення посланця, доступне будь-якому шукачеві пригод з Альянсу, готовому вирушити до Стормвінда.",al={"чи треба бути ковалем","доручення елмора лише для ковалів"}}},fp="13,340,21.449.0,18.485.0,35.162.0,34.124.0,33.227.0,33.199.0,51.232.0,50.182.0"}
P.entries["quest:1098"] = {n="Смертолови в Шадовфенгу",s="Верховний Екзекутор Гадрек посилає шукачів пригод з Орди у Фортецю Шадовфенг, щоб знайти двох зниклих розвідників — Скрадача Смерті Адаманта й Скрадача Смерті Вінсента. Військо Відступників покладається на зібрані ними відомості, щоб спланувати напад на Архімага Аруґала та його зграї воргенів. Прорвавшись у фортецю, мандрівники бачать похмуру правду шпигунства у ворожому тилу.",h="Верховний Екзекутор Гадрек посилає шукачів пригод з Орди у Фортецю Шадовфенг, щоб знайти двох зниклих...",kw={"скрадачі смерті в шадовфенгу","фортеця шадовфенг","гадрек","скрадачі смерті","адамант","вінсент"},ang={["class:Rogue"]="Зникнення скрадачів смерті показує, як ризиковано вести розвідку за лініями добре укріпленого ворога.",["faction:Horde"]="Верховний Екзекутор Гадрек покладається на поборників Орди там, де звичайні війська не можуть прорватися в прокляту фортецю Аруґала.",["race:Undead"]="Для Відступників відвоювати Срібнолісся в Аруґалових звірів — вкрай важливо, щоб убезпечити Лордерон. Зниклі розвідники показують, наскільки небезпечна ця боротьба."},sec={{t="У лігво воргенів",b="Срібнолісся лишається спірною землею: дикі воргени Архімага Аруґала тримають височенну твердиню — Фортецю Шадовфенг. Прагнучи зняти цю облогу зі своїх південних кордонів, командування Відступників у Гробниці влаштувало розвідувальну операцію. Верховний Екзекутор Гадрек послав двох досвідчених скрадачів смерті — Адаманта й Вінсента — пробратися у фортецю й скласти мапу її оборони. Минали дні без жодної звістки, і Гадрек, відчайдушно чекаючи на їхні донесення, доручив вправним поборникам Орди проникнути в твердиню, щоб знайти агентів і врятувати місію."},{t="Гірка знахідка",b="Пробившись крізь нижні мури, шукачі пригод бачать, якою дорогою ціною обійшлося проникнення. Скрадач Смерті Адамант живий у полоні й допомагає відімкнути ворота подвір'я, а от Вінсента спіткала жорстока смерть. Його понівечене тіло нерухомо лежить у фортеці, а зібрані ним відомості загубилися в темних залах. У холодних пальцях лишилася стиснута тільки дрібничка — тихе свідчення про шпигуна, що віддав своє не-життя за завоювання Темної Леді."}},faq={{q="Навіщо скрадачів смерті послали до Фортеці Шадовфенг?",a="Верховний Екзекутор Гадрек наказав проникнути туди, щоб зібрати важливі тактичні відомості про сили й укріплення Архімага Аруґала, перш ніж кидати війська Відступників у повномасштабний штурм Фортеці Шадовфенг.",al={"навіщо скрадачів послали в шадовфенг","мета гадрека","мета скрадачів смерті"}},{q="Хто такі скрадачі смерті Адамант і Вінсент?",a="Це добірні агенти Відступників зі скрадачів смерті — розвідувального й диверсійного загону Андерсіті. Їх вислали вперед як розвідників, щоб нанести на мапу Фортецю Шадовфенг і простежити за обороною воргенів.",al={"хто такі адамант і вінсент","лор адаманта і вінсента"}},{q="Що сталося зі Скрадачем Смерті Вінсентом?",a="Вінсент так і не повернувся з Фортеці Шадовфенг із донесенням. Гадрекові потрібен хтось, хто проникне у фортецю й з'ясує, що з ним сталося.",al={"чи вінсент загинув","де вінсент","доля вінсента"}},{q="Яку роль Скрадач Смерті Адамант відіграє у фортеці?",a="Адамант — один зі зниклих скрадачів смерті, яких послали збирати відомості у Фортеці Шадовфенг. Що з ним, з'ясовується під час пошуків.",al={"що робить адамант","роль скрадача смерті адаманта"}},{q="Де починається це доручення?",a="Доручення дає Верховний Екзекутор Гадрек — воєначальник Відступників, що перебуває в Гробниці в Срібноліссі.",al={"де починається доручення","давець скрадачів смерті у шадовфенгу"}},{q="Чому провід Відступників хоче очистити Фортецю Шадовфенг?",a="Архімаг Аруґал зі своєї твердині у Фортеці Шадовфенг випускає лютих воргенів на все Срібнолісся, постійно загрожуючи володінням Відступників, їхнім шляхам постачання й безпеці Лордерона загалом.",al={"чому відступники очищають шадовфенг","відступники проти аруґала"}}},fp="27,374,19.582.0,18.476.1,47.208.0,42.234.0,38.129.1,57.139.1,30.126.0,62.201.0"}
P.entries["quest:11"] = {n="Винагорода за гнолів Річколапів",s="Винагорода за гнолів Річколапів — офіційна угода від Помічника Рейнера з Гарнізону Вестбрук: винищити гнолів, що насуваються на західні кордони Лісу Елвінн. Військо Стормвінда пропонує винагороду за розмальовані нараменні пов'язки, зняті зі зграй Річколапів, що заполонили ліси й водойми.",h="Винагорода за гнолів Річколапів — офіційна угода від Помічника Рейнера з Гарнізону Вестбрук: винищити гнолів...",kw={"винагорода","гноли","річколапи","помічник рейнер","гарнізон вестбрук","нараменні пов'язки"},ang={["faction:Alliance"]="Прикордонні винагороди підносять вашу репутацію у війську Стормвінда й водночас убезпечують життєво важливі торгові шляхи через серце королівства.",["race:Human"]="Для людей королівства полювання на Річколапів — прямий внесок у захист рубежів Елвінну й підтримку перевантаженої варти корони."},sec={{t="Загроза на кордоні",b="Гарнізон Вестбрук охороняє важливе прикордоння між Лісом Елвінн і Вестфолом. Та виснажені сили гарнізону ледве стримують агресивний наплив гнолів Річколапів. Ці дикі створіння влаштували табори одразу на південь від сторожової вежі й далі на схід, довкола берегів Озера Кам'яного Кургану, підступивши так близько, що загрожують мирним подорожнім і тутешнім садибам."},{t="Ціна порядку",b="Не маючи змоги виділити регулярну піхоту, щоб прочесати ліси, Помічник Рейнер призначає винагороду за нападників. Щоб підтвердити вбивства, Рейнер вимагає доказу бойової перемоги — розмальованих нараменних пов'язок гнолів, знятих із убитих тварюк. Наймаючи мандрівних шукачів пригод і новобранців проріджувати зграю, гарнізон сподівається притупити наступ Річколапів, перш ніж ті затоплять західні марки."}},faq={{q="Де в Лісі Елвінн знайти гнолів Річколапів?",a="Гноли Річколапів збираються в Елвінні переважно у двох місцях: у густому лісі просто на південь від Гарнізону Вестбрук біля берегів річки та далі на схід, довкола Озера Кам'яного Кургану.",al={"де гноли річколапи","місця гнолів","місця річколапів"}},{q="Чому гарнізон просить шукачів пригод допомогти з гнолами?",a="Гарнізонові Вестбрук бракує людей, а на кордонах Елвінна дедалі неспокійніше. Вартових замало, щоб і обходити околиці, і водночас ходити в наступ, тож Помічник Рейнер звертається до незалежних поборників, щоб ті полювали на гнолів.",al={"чому гарнізон наймає","чому помічник рейнер потребує допомоги"}},{q="Який доказ вимагає Помічник Рейнер?",a="Помічник Рейнер вимагає вісім розмальованих пов'язок гнолів як речовий доказ, що тварюк, які підступають, знищено.",al={"який доказ вимагає рейнер","що збирати для рейнера"}},{q="Хто такі гноли Річколапів?",a="Річколапи — сумнозвісно люте плем'я гієноподібних людиноподібних, відоме тим, що заполоняє річкові долини й прикордоння людських земель. Вони раз у раз грабують поселення, мандрівників і ферми заради їжі й здобичі.",al={"хто такі гноли річколапи","плем'я річколапів"}},{q="Чи пов'язане це завдання з іншими загрозами в Елвінні?",a="«Винагорода за гнолів Річколапів» завершує короткий ланцюжок тривоги Гарнізону Вестбрук, хоча Помічник Рейнер і гарнізон стежать і за іншими беззаконниками в окрузі, як-от за сумнозвісним розбійником Гоґґером.",al={"продовження завдання","що після винагороди за річколапів"}},{q="Хто платить винагороду за цих гнолів?",a="Винагороду офіційно затвердила й забезпечує армія Стормвінда, яка уповноважує місцеві гарнізони відзначати й винагороджувати тих, хто допомагає втихомирити королівські землі.",al={"хто платить винагороду","джерело нагороди"}}},fp="21,288,22.425.0,18.382.0,52.192.0,60.236.0,38.117.0,28.216.0,55.214.0,37.177.0"}
P.entries["quest:1100"] = {n="Щоденник Лоунброу",s="«Щоденник Лоунброу» — завдання Альянсу, яке починається з пошарпаної книжки в руці мертвого дворфа біля підніжжя Великого Підйомника в Тисячі Голок. Записи розповідають про його останню мандрівку й спонукають того, хто їх знайде, віднести щоденник на захід — до нічного ельфа-друїда, що несе службу на кордоні Фераласу.",h="«Щоденник Лоунброу» — завдання Альянсу, яке починається з пошарпаної книжки в руці мертвого дворфа біля...",kw={"щоденник лоунброу","генріґ лоунброу","фалфіндел вейвордер","таланаар","рейзорфен краул","великий підйомник"},ang={["class:Druid"]="Фалфіндел Вейвордер у Таланаарі стежить за неприродними змінами в місцевій природі, тож нотатки Лоунброу про шипогривів Рейзорфену прямо цікавлять Коло Кенарія.",["faction:Alliance"]="Між Терамором і Таланааром мало застав, тож знайдений щоденник Лоунброу гарантує, що важливі відомості дійдуть до союзників Альянсу, а не пропадуть у каньйоні.",["race:Dwarf"]="Загибель Генріґа Лоунброу — сумне нагадування про небезпеки, що чигають на дворфів-дослідників далеко від Айронфорджа, у диких закутках Калімдору."},sec={{t="Полеглий дослідник",b="Біля підніжжя Великого Підйомника — величезного механічного ліфта, що з'єднує Пустки з дном каньйону Тисячі Голок, — лежить тіло Генріґа Лоунброу. У руці він стискає власний щоденник із розповіддю про мандри цим суворим краєм. Покинутий у ворожій пустелі, де панують кентаври й таурени, його труп — похмуре застереження про те, яким безжальним може бути каньйон до самотніх мандрівників."},{t="Останнє прохання",b="Щоденник Генріґа розкриває задуманий ним шлях і його останню волю. Дослідник не хотів, щоб його знахідки зотліли в каньйоні, — він сподівався, що записи потраплять у дружні руки. Дорога просто на захід через Тисячу Голок виводить із сухих ярів до Таланаара — застави нічних ельфів, що стереже кордон Фераласу. Там на вісті про мандрівника чекає друїд Фалфіндел Вейвордер."},{t="Таємниця Краулу",b="Коли Фалфіндел Вейвордер переглядає нотатки Лоунброу, доля дослідника сплітається з більшою загрозою на півдні Калімдору. Спостереження Генріґа вказують на зарослі ожиною нори Рейзорфен Краулу на півночі й виявляють, що шипогривами всередині керує небезпечна стара відьма."}},faq={{q="Де знайти тіло Генріга Лоунброу?",a="Його тіло лежить біля підніжжя Великого Підйомника в Тисячі Голок. Від нижнього краю західного пандуса підйомника пройдіть метрів сім-вісім уперед до низького скельного уступу: там лежить його труп зі щоденником у руці.",al={"де тіло генріга лоунброу","місце щоденника лоунброу","тіло лоунброу","знайти лоунброу"}},{q="Кому віднести щоденник?",a="Віднесіть щоденник Фалфінделу Вейвордеру — друїдові з нічних ельфів, що служить у Таланаарі. Таланаар стоїть при головній західній дорозі просто на кордоні між Тисячею Голок і Фераласом.",al={"кому віднести щоденник","кому здати щоденник лоунброу","здача лоунброу","місце фалфіндела"}},{q="Хто такий Генріг Лоунброу?",a="Генріг Лоунброу — дворф-мандрівник, що подорожував центральним Калімдором. Він загинув біля підніжжя Великого Підйомника, лишивши потертий щоденник із записами про довколишні землі й небезпечні пересування шипогривів.",al={"хто такий генріг лоунброу","минуле лоунброу","хто такий лоунброу"}},{q="До чого веде це завдання?",a="Коли ви здаєте щоденник Фалфінделу Вейвордеру, відкривається завдання «Стара з Краулу», яке посилає шукачів пригод з Альянсу в підземелля Рейзорфен Краул.",al={"продовження лоунброу","завдання після щоденника лоунброу","ланцюжок лоунброу"}},{q="Чи можуть гравці Орди підібрати щоденник?",a="Ні. Щоденник і подальший ланцюжок завдань — лише для гравців Альянсу: вони ведуть просто до прикордонної застави Альянсу в Таланаарі.",al={"чи щоденник лише для альянсу","чи орда може виконати щоденник лоунброу","орда лоунброу"}},{q="Чому Лоунброу йшов до Таланаара?",a="Таланаар — найближча застава Альянсу в краї, прихисток між Тисячею Голок і нетрями Фераласу. Лоунброу хотів поділитися своїми спостереженнями з нічними ельфами, що там служать.",al={"чому таланаар","чому книгу друїду","мета лоунброу"}}},fp="18,299,17.419.0,15.417.0,20.301.1,39.222.0,32.194.0,24.240.0,29.168.1,38.140.0,42.221.0"}
P.entries["quest:1101"] = {n="Стара з Краулу",s="«Стара з Краулу» — завдання Альянсу від Фалфіндела Вейвордера в Таланаарі, на межі Фераласу й Тисячі Голок. Прочитавши знайдений щоденник полеглого дворфа Генріґа Лоунброу, Фалфіндел доручає шукачам пригод пробратися в Рейзорфен Краул і вбити стару відьму шипогривів — Чарлґу Рейзорфленк.",h="«Стара з Краулу» — завдання Альянсу від Фалфіндела Вейвордера в Таланаарі, на межі Фераласу й Тисячі Голок.",kw={"стара з краулу","чарлґа рейзорфленк","фалфіндел вейвордер","таланаар","рейзорфен краул","шипогриви","аґамаґґан"},ang={["class:Druid"]="Друїди високо шанують Аґамаґґана як поважного Древнього природи й прагнуть очистити темну скверну, що спотворює його колючий спадок.",["faction:Alliance"]="Це завдання — головний похід Альянсу проти загрози шипогривів на півдні Пусток, що вирушає з застави Таланаар.",["race:Dwarf"]="Помста за дослідника Генріґа Лоунброу дає дворфам особисту причину штурмувати твердиню шипогривів.",["race:NightElf"]="Нічні ельфи з тривогою дивляться на осквернення місця спочинку Аґамаґґана, бо пам'ятають Древнього-вепра як полеглого союзника з Війни Прадавніх."},sec={{t="Благання на кордоні",b="На відлюдній заставі нічних ельфів у Таланаарі Фалфіндел Вейвордер оплакує втрату свого розвідника Гералата й дворфа Генріґа Лоунброу. Лоунброу вирушив глибоко в Пустки розвідати вулики шипогривів, але поліг у бою, лишивши пошарпаний щоденник, де описано дедалі більшу загрозу з Рейзорфен Краулу. Розуміючи, що немає часу слати гінця до Дарнасуса по військове підкріплення, Фалфіндел звертається до мандрівних шукачів пригод, щоб ударити просто в серце колючих лігв."},{t="Удар по ватажку",b="Мета походу — Чарлґа Рейзорфленк, стародавня геомантка й безжальна матріархиня, що об'єднала розсварених шипогривів Рейзорфену під своєю залізною рукою. З глибин Краулу вона збирає наїжачене військо, яке загрожує сусіднім землям. Шукачі пригод мають прорубатися крізь густі колючі лабіринти, бойові мури й зграї фанатичних воїнів-шипогривів, щоб загнати Чарлґу в кут і зняти з її бездиханного тіла медальйон як доказ її падіння."},{t="Глибше зіпсуття",b="Смерть Чарлґи притуплює безпосередню загрозу шипогривів, але її поразка породжує глибші тривоги в нічних ельфів. Краул утворили живі колючі хащі, що проросли там, де під час Війни Прадавніх поліг Древній-вепр Аґамаґґан. Коли медальйон повертають, Фалфіндел зауважує, що загибель Чарлґи дає змогу вченим нічних ельфів пильніше вивчити зіпсуття цієї місцини, хоча й відчуває, що за раптовою скверною, яка охопила священні рештки Аґамаґґана, може стояти підступна зрада."}},faq={{q="Хто дає завдання «Стара з Краулу»?",a="Завдання дає Фалфіндел Вейвордер — нічний ельф із Таланаара. Таланаар — застава Альянсу на високому гірському перевалі між Фераласом і Тисячею Голок.",al={"давець завдання стара з краулу","де взяти стару з краулу","завдання фалфіндела вейвордера"}},{q="Що треба виконати, перш ніж братися за це завдання?",a="Спершу треба виконати завдання «Щоденник Лоунброу»: забрати щоденник Генріга Лоунброу з його останків біля Великого Підйомника в Тисячі Голок і доставити його Фалфінделу в Таланаар.",al={"передумова старої з краулу","як відкрити стару з краулу","щоденник лоунброу передумова"}},{q="Хто така Чарлґа Рейзорфленк?",a="Чарлґа Рейзорфленк — верховна відьма й матріарх шипогривів Рейзорфену. Вона могутня геомантка, що об'єднала ворожі племена в Рейзорфен Краулі й спрямовує їхню агресію на сусідні землі.",al={"хто стара","лор чарлґи","чарлґа рейзорфленк"}},{q="Де знайти Чарлґу Рейзорфленк?",a="Вона в самому кінці Рейзорфен Краулу, у дальньому південному куті Пусток біля Великого Підйомника. Вона чекає на вівтарі глибоко в підземеллі.",al={"де чарлґа","місце чарлґи рейзорфленк","де стара в краулі"}},{q="Чому Фалфінделу потрібні шукачі пригод, а не військо з Дарнасуса?",a="Таланаар — віддалена прикордонна застава, далеко від північного Калімдору. Чарлґа щосили збирає сили, тож поки звістка дійде до Дарнасуса й звідти вирушить військо, буде запізно, щоб відвернути небезпеку.",al={"чому не кличуть дарнас","чому наймати шукачів"}},{q="Якого доказу смерті старої вимагає Фалфіндел?",a="Фалфіндел вимагає Медальйон Рейзорфланка — амулет, який носила сама Чарлґа і який незаперечно свідчить, що стару вбито.",al={"що падає","предмет доказу смерті","медальйон рейзорфленка"}}},fp="22,326,20.490.0,22.458.0,19.509.1,43.187.0,63.223.0,26.225.0,38.167.0,74.217.0,54.144.0"}
P.entries["quest:1103"] = {n="Поклик Води",s="Це завдання дає другий шанс шаманам, що проходять свої духовні випробування на узбережжі Срібнолісся. Якщо духовний зір шамана згасне раніше, ніж він поспілкується з очищеним проявом води, Тієв Мордун готовий знову розпалити причастя. Принісши ще одну Водяну Сапту, прохач може знову побачити обряд і завершити своє причастя.",h="Це завдання дає другий шанс шаманам, що проходять свої духовні випробування на узбережжі Срібнолісся.",kw={"поклик води","тієв мордун","водяна сапта","малий прояв води","шамани","тотем води","срібнолісся"},ang={["class:Shaman"]="Цей обряд уособлює товариство шаманів, що йдуть виснажливим шляхом до свого Тотема Води: жоден учень не лишиться напризволяще через згасле видіння.",["faction:Horde"]="Шаманські традиції Орди тримаються на взаємодопомозі й шані до духів природи — навіть у примарних землях Лордерона."},sec={{t="Помічна рука в імлі",b="Шлях до опанування води вимагає тонкого духовного чуття часу. Шамани п'ють сильний напій, відомий як Водяна Сапта, щоб бачити духів, що витають довкола стихійних святинь. Якщо чари напою згаснуть раніше, ніж шаман поговорить із Малим Проявом Води, він опиняється замкненим поза царством духів і не може завершити випробування. На щастя, побратим-шаман Тієв Мордун чекає на оповитих туманом берегах Срібнолісся, щоб допомогти тим, чиї видіння скінчилися зарано."},{t="Оновлення обряду",b="Тієв Мордун, що вже здолав зіпсованого водяного духа біля узбережжя, чекає з рештками зібраних для обряду речей. Як доказ готовності він вимагає свіжу Водяну Сапту від Іслена Вотерсіра з Пусток. Отримавши сапту, Тієв кидає в жаровню святині зібрані наручі й краплі й знову викликає чистий прояв, щоб побратим-шаман міг поговорити з ним і скріпити свій зв'язок зі стихією."}},faq={{q="Хто такий Тієв Мордун?",a="Тієв Мордун — шаман Орди, ваш побратим, що стоїть на узбережжі Срібнолісся. Він уже переміг місцевого зіпсованого елементаля й лишається на березі, щоб допомагати іншим посвячуваним, які втратили духовний зір, не завершивши єднання.",al={"тієв мордун","хто такий тієв","тієв сільверпайн"}},{q="Навіщо мені для цього завдання Водяна Сапта?",a="Водяна Сапта дає розумові шамана змогу переступити поріг світу духів. Тієвові потрібно, щоб ви випили свіжої сапти від Іслена Вотерсіра: тоді ви матимете зір, потрібний, щоб побачити елементаля, коли він знову його закличе.",al={"навіщо водяна сапта","сапта тієва","де взяти сапту"}},{q="Що робити, якщо я не встиг поговорити з духом води?",a="Якщо дія напою духу минула або Малий Прояв Води зник, перш ніж ви встигли з ним поговорити, самотужки завершити випробування не вийде. Тоді втручається Тієв Мордун: він знову розпалює жаровню своїми трофеями, щоб ви могли поєднатися з духом.",al={"пропустив духа води","невдалий прояв води","прояв води зник"}},{q="Де відбувається цей обряд?",a="Випробування відбувається на західному узбережжі Срібнолісся, біля святилища стихій над Великим Морем.",al={"місце водяного святилища","святилище води сільверпайн"}},{q="Хто посилає шаманів у це паломництво?",a="Іслен Вотерсір, таурен-шаман, що живе біля рибальської хатини на східному узбережжі Пусток, веде посвячуваних крізь випробування «Поклик Води» й варить потрібні сапти.",al={"хто дав поклик води","іслен вотерсір"}},{q="Що таке Малий Прояв Води?",a="Це очищений дух стихії, якого закликають біля святилища, коли скверну, що отруювала місцеві води, вже очищено. Єднання з ним означає, що шаман успішно пройшов цей етап своїх випробувань стихій.",al={"що таке дух води","малий прояв"}}},fp="13,364,26.514.0,19.452.0,20.261.0,43.222.0,54.262.0,34.114.0,36.179.0,41.217.0"}
P.entries["quest:1104"] = {n="Отрута Соляних Рівнин",s="На сліпучих соляних просторах Мерехтливих Низин гном-інженер Фіззл Брассболтс шукає незвичних складників, щоб надати своєму ракетному автомобілю надпотужності. Переконаний, що надзвичайно солона отрута місцевих скорпідів дасть пальне, яке горітиме пекельним жаром, він доручає мандрівним шукачам пригод зійтися з цими жалкими звірами.",h="На сліпучих соляних просторах Мерехтливих Низин гном-інженер Фіззл Брассболтс шукає незвичних складників, щоб...",kw={"отрута соляних рівнин","фіззл брассболтс","скорпіди","пальне","перегони міражу","мерехтливі низини"},ang={["profession:Engineering"]="Органічні отрути, оброблені каталізаторами на кшталт «скіпер-отомерів», показують, якими винахідливими й вибуховими бувають експерименти в змагальному машинобудуванні.",["race:Gnome"]="Фіззл — утілення класичних гномських амбіцій: невтомне майстрування, сумнівна хімічна безпека, загублені нотатки й постійне прагнення затьмарити гоблінських механіків."},sec={{t="Вибуховий рецепт",b="Перегони Міражу — нескінченна битва за технічну першість на шаленій швидкості між гномською точністю й гоблінською зухвалістю. Фіззлові Брассболтсу звичайних вуглеводнів і годинникових деталей просто замало, щоб обійти суперників. Він мріє про особливу паливну суміш, що горітиме куди гарячіше за звичайне пальне й пожене їхні ракетні автомобілі висохлим соляним озером із запаморочливою швидкістю."},{t="Солона отрута солончаків",b="Прорив Фіззла залежить від небезпечної місцевої фауни Мерехтливих Низин. Тутешні скорпіди пристосувалися до життя в посушливій, вкритій сольовою кіркою пустці, і їхня отрута стала надзвичайно солоною. Фіззл не боїться її смертельної отруйності — він бачить у ній сировинний хімічний заряд. Виварена, очищена й оброблена екзотичними каталізаторами, солона отрута, на його думку, дасть вибухове згоряння, потрібне, щоб лишити гоблінських механіків ковтати пил."}},faq={{q="Навіщо Фіззлові Брассболтсу отрута скорпідів?",a="Фіззл винаходить нове пальне для ракетного болида, що горить надзвичайно гаряче. Він вважає, що незвично висока солоність отрути місцевих скорпідів Мерехтливих Низин — саме той хімічний складник, якого бракує його вибуховій суміші.",al={"навіщо отрута скорпідів","для чого отрута","рецепт пального фіззла"}},{q="Де знайти потрібних скорпідів?",a="Скорпіди блукають усіма відкритими просторами Мерехтливих Низин, особливо на західних рівнинах і пустельних пісках подалі від центрального треку.",al={"місця скорпідів","де скорпіди","скорпіди соляних рівнин"}},{q="Що Фіззл робитиме із зібраною отрутою?",a="Фіззл збирається виварити отруту, обробити її скіперотомером і змішати з негакаталізатором, щоб отримати високооктанове ракетне пальне, — якщо, звісно, знайде, куди подів свої записи.",al={"як отрута стає пальним","процес пального"}},{q="Чи можуть допомогти Фіззлові і Альянс, і Орда?",a="Так. Перегони Міражу діють за нейтральним перемир'ям між гномами й гоблінами, тож шукачі пригод з обох фракцій можуть допомагати ремонтним бригадам без політичних перешкод.",al={"чи нейтральне завдання","орда чи альянс"}},{q="Чому гноми й гобліни влаштовують перегони в Тисячі Голок?",a="Мерехтливі Низини — величезне, ідеально рівне й вільне від перешкод дно з утрамбованої солі, тож це найкращий полігон для дослідних швидкісних ракетних болидів і драгстерів.",al={"чому перегони в тисячі голок","чому траса міражу"}},{q="Чи справді від цього пального машина полетить?",a="Хоча Фіззл захоплено запевняє, що машина «полетить», гномські ракетні апарати на соляних рівнинах створені, щоб мчати над самою землею на шаленій швидкості, — хоча катастрофічні злети й аварії ніколи не виключені.",al={"чи справді машина полетить","результат ракетного авто фіззла"}}},fp="15,323,17.404.0,30.473.0,46.240.0,42.163.0,50.202.0,55.183.0,54.185.0,40.223.0"}
P.entries["quest:1105"] = {n="Затверділі панцирі",s="На Перегонах Міражу в Мерехтливих Низинах гном-майстер Віззл Брассболтс побоюється, що потужне нове ракетне пальне його брата роз'їсть їхній болід зсередини. Щоб запобігти катастрофі на солончаках, Віззл просить перехожих зібрати затверділі панцирі місцевих черепах і змайструвати з них непроникний паливний бак.",h="На Перегонах Міражу в Мерехтливих Низинах гном-майстер Віззл Брассболтс побоюється, що потужне нове ракетне...",kw={"затверділі панцирі","віззл брассболтс","черепахи","паливний бак","перегони міражу","мерехтливі низини"},ang={["profession:Engineering"]="Тримати вибухові сполуки в органічних бронепластинах — незвично, і це добре показує дивакуватий метод спроб і помилок, на який гномські майстри покладаються, коли тиснуть обставини.",["race:Gnome"]="Тут лоб у лоб зіштовхуються братня винахідливість і безрозсудні наукові амбіції — уся гномська жага перевершити суперників-гоблінів, хай які перепони стоять на шляху."},sec={{t="Вибухові новації",b="У сліпучій спеці Мерехтливих Низин суперництво гномських і гоблінських інженерів доводить механічні амбіції до безрозсудних крайнощів. Віззл Брассболтс і його брат сповнені рішучості панувати на Перегонах Міражу зі своїм саморобним ракетним автомобілем. Але експериментальна паливна суміш брата, схоже, аж надто потужна. Боячись, що їдке вариво проплавить звичайні шасі й баки машини наскрізь, Віззл гарячково шукає посудину, досить міцну, щоб пережити заїзд."},{t="Пустельна броня",b="Замість покладатися на очищені метали, які можуть розчинитися під хімічним навантаженням, Віззл звертається до того, що виробила сама природа солончаків. Місцеві черепахи, що блукають Тисячею Голок, мають панцирі, напрочуд стійкі до суворої негоди й механічного зносу. Зібравши ці затверділі щити, Віззл сподівається змайструвати особливі паливні баки, досить витривалі, щоб утримати нестійку суміш і не рознести ракетний автомобіль на шматки."}},faq={{q="Чому Віззлові потрібні черепашачі панцирі, а не метал?",a="Його брат варить дослідне ракетне пальне, таке їдке, що розчиняє метал. Віззл вважає, що природні, надтверді панцирі місцевих черепах витримають хімічну дію краще за звичайні баки.",al={"чому черепашачі панцирі","чому панцирі черепах","панцир паливного бака"}},{q="Хто такий Віззл Брассболтс?",a="Віззл — гном-інженер на Перегонах Міражу на Мерехтливих Низинах. Разом із братом він будує й доводить до ладу їхній швидкісний ракетний болид, щоб обігнати суперників-гоблінів.",al={"віззл","хто такий віззл брассболтс"}},{q="Де знайти черепах?",a="Черепахи вільно блукають величезною соляною рівниною Мерехтливих Низин, а найбільше їх гріється на сонці біля старого корабельного остова в північно-східній частині.",al={"місце черепах","де черепахи","де взяти панцирі"}},{q="Це завдання Альянсу чи Орди?",a="Воно цілком нейтральне. Перегони Міражу існують поза війною фракцій і зосереджені на інженерних змаганнях, тож допомагати Віззлові можуть шукачі пригод і з Альянсу, і з Орди.",al={"нейтральне завдання панцирів","альянс чи орда"}},{q="Що буде, коли доставиш панцирі?",a="Віззл радо береться робити з них зміцнені паливні баки, але швидко розуміє, що панцирі такі міцні, що, вирізаючи їх, він, мабуть, зіпсує цілу скриньку інструментів.",al={"результат панцирів віззла","що віззл робить з панцирями"}},{q="Чому відмова паливного бака — така небезпека на рівнинах?",a="Ракетні болиди мчать соляною рівниною з жахливою швидкістю. Якщо бак не витримає їдкого пального, воно спалахне просто на ходу, знищивши машину й спопеливши пілота.",al={"небезпека паливного бака","чому турбуватися про паливо"}}},fp="15,330,20.523.0,24.429.0,54.225.0,25.202.0,33.172.0,35.179.0,43.182.1,53.166.0"}
P.entries["quest:111"] = {n="Поговори з бабусею",s="Це доручення посилає шукача пригод до Бабусі Стоунфілд від імені її онука Томмі Джо. Затиснутий у гіркій ворожнечі між родинами Стоунфілдів і Маклурів, Томмі Джо сподівається, що літня матріарх знає спосіб, як йому побачити Мейбелл Маклур.",h="Це доручення посилає шукача пригод до Бабусі Стоунфілд від імені її онука Томмі Джо.",kw={"бабуся стоунфілд","томмі джо","мейбелл маклур","ворожнеча","кохання","ферма"},ang={["faction:Alliance"]="Поки Стормвінд протистоїть заворушенням Дефіас і нападам звірів, мандрівники Альянсу часто опиняються в ролі посередників у дрібних домашніх сварках між сусідами-фермерами.",["race:Human"]="Для людей, що мандрують Елвінном, конфлікт Стоунфілдів і Маклурів — нагадування про те, як глибоко сягають місцеві образи в серці Стормвінда навіть у тіні ширших криз королівства."},sec={{t="Ворожнеча й заборонене кохання",b="Стоунфілди й Маклури роками живуть у гіркому фермерському суперництві, перетворивши сусідні садиби на ворожу територію. Між двома вогнями опинилися молодий Томмі Джо Стоунфілд і Мейбелл Маклур, чий роман доводиться тримати в цілковитій таємниці. Відчайдушно шукаючи способу зустрітися з коханою, не розпаливши насильства між рідними, Томмі Джо звертається по пораду до бабусі."},{t="Бабусина хитрість",b="Хоч вік тримає Бабусю Стоунфілд у чотирьох стінах, вона розуміє природу ворожнечі краще за будь-кого. Вона визнає, що справжній союз двох родин неможливий, доки живе стара неприязнь, та аж ніяк не збирається дозволити сусідським образам цілком розчавити молоде кохання. Замість закликати до обережності, вона починає вигадувати дрібні нагоди звести двох закоханих разом."}},faq={{q="Чому Томмі Джо хоче, щоб я поговорив із його бабусею?",a="Томмі Джо до нестями закоханий у Мейбелл Маклур, але через ворожнечу їхніх родин зустрічатися їм неможливо. Він вірить, що бабуся має досить мудрості, співчуття й хитрості, щоб допомогти їм влаштовувати таємні побачення, не здіймаючи галасу.",al={"чому до бабусі","томмі джо бабуся","мета розмови з бабусею"}},{q="Де знайти Бабусю Стоунфілд?",a="Бабуся Стоунфілд сидить у головному будинку ферми Стоунфілдів, на схід від берега річки, де ховається Томмі Джо, на південь від Ґолдширу.",al={"місце бабусі стоунфілд","де бабуся","знайти бабусю стоунфілд"}},{q="Що за ворожнеча між Стоунфілдами й Маклурами?",a="Дві сусідні фермерські родини давно ворогують через особисті образи й межі. Звинувачення в крадіжках, суперництво за врожаї й взаємна недовіра тримають обидві родини на межі бійки, тож їхнім дітям доводиться спілкуватися потай.",al={"ворожнеча стоунфілдів і маклурів","чому вони б'ються","ворожнеча родин елвінн"}},{q="Чи Бабуся Стоунфілд проти стосунків Томмі Джо?",a="Ні. Хоча вона й визнає, що через ворожнечу довге спільне майбутнє зараз навряд чи можливе, у неї слабкість до молодих закоханих, і вона охоче вигадує хитрощі, щоб допомогти їм побачитися.",al={"чи бабуся проти мейбелл","чи бабуся підтримує закоханих"}},{q="Що буде після розмови з бабусею?",a="Бабуся береться обмірковувати, як потай звести Томмі Джо й Мейбелл, і посилає шукача пригод із дорученнями, щоб приготувати лікер невидимості й прослизнути повз пильні очі родичів.",al={"що після розмови з бабусею","продовження бабусі"}},{q="Хто така Мейбелл Маклур?",a="Мейбелл — донька з ворожої родини Маклурів, що живе через дорогу від Стоунфілдів. Вона потай зустрічається з Томмі Джо Стоунфілдом.",al={"хто така мейбелл","мейбелл маклур"}}},fp="17,236,25.402.0,16.391.0,52.231.0,37.134.0,58.259.0,55.178.0,38.173.1,23.149.0"}
P.entries["quest:1110"] = {n="Деталі Ракетного Авто",s="«Деталі ракетного авто» — доручення від спритного дворфа-торговця Кравела Колбірда на сліпучих солончаках Мерехтливих Низин. Не бажаючи, щоб розкидані уламки швидкісних аварій пропадали марно, Колбірд платить мандрівникам, аби ті прочісували дно пустелі й збирали розбиті механізми, які він перепродує суперницьким командам гномів і гоблінів.",h="«Деталі ракетного авто» — доручення від спритного дворфа-торговця Кравела Колбірда на сліпучих солончаках...",kw={"деталі ракетного авто","кравел колбірд","уламки","перегони міражу","мерехтливі низини","брухт"},ang={["profession:Engineering"]="Прочісуючи солончаки, ви бачите безрозсудну винахідливість суперницьких гоблінських і гномських конструкцій, де нестійкі ракетні прискорювачі й саморобні шасі часто закінчуються ефектним руйнуванням.",["race:Dwarf"]="Чимало дворфів з Айронфорджа дивляться на перегони заради механічних новацій чи розкопок, а Кравел Колбірд уособлює суто корисливу жилку — його цікавить лише монета, яку приносить збирання брухту.",["race:Gnome"]="Зібрані деталі показують невтомне — хоч часом і згубне — прагнення гномських інженерів обігнати й перевершити своїх гоблінських суперників на відкритій трасі."},sec={{t="Уламки на солончаках",b="Мерехтливі Низини — полігон запеклого технологічного суперництва гоблінських і гномських інженерів. Надшвидкісні експериментальні ракетні автомобілі раз у раз зазнають катастрофічних поломок, лишаючи покручені шестерні, циліндри й гострі листи металу розкиданими по всій неосяжній білій пустелі. Поки механіки зосереджені лише на тому, щоб збудувати й налаштувати наступну машину, дно пустелі тихенько перетворилося на звалище експериментальної інженерії."},{t="Брухтова справа Колбірда",b="Замість змагатися на трасі, дворф-підприємець Кравел Колбірд розгледів на Перегонах Міражу вигідну нагоду стати посередником. Гномські й гоблінські механіки палять деталі шаленими темпами й повсякчас відчайдушно шукають запасних механізмів, щоб приліпити до своїх машин. Колбірд наймає мандрівників зібрати тридцять в'язок розтрощених уламків, обертаючи нищівні аварії на свіжий товар і спритно наживаючись на невдачах водіїв."}},faq={{q="Хто такий Кравел Колбірд?",a="Кравел Колбірд — кмітливий дворф-торговець на Перегонах Міражу на Мерехтливих Низинах. Довкола треку він проворачує різні оборудки, здебільшого збирає мотлох, береться за випадкову роботу й обертає суперництво гномів і гоблінів на власний зиск.",al={"кравел колбірд","хто дає деталі ракетного авто","дворф траси"}},{q="Чому на землі валяється стільки деталей ракетних авто?",a="Перегони Міражу — робочий випробувальний і гоночний трек, де гоблінські й гномські інженери доводять дослідні ракетні машини до небезпечних меж. Жахливі аварії й раптові вибухи на соляних рівнинах трапляються постійно, і уламки конструкцій, шестерні й циліндри розлітаються навсібіч.",al={"чому деталей ракетних авто багато","уламки мерехтливих низин","розбиті ракетні авто"}},{q="Що Кравел робить із деталями з розбитих машин?",a="Колбірд очищує зібраний брухт і продає його назад гномським і гоблінським командам. Бригади постійно витрачають матеріали й охоче купують будь-які пристрої й обрізки металу, які можна прикрутити до наступного прототипу.",al={"що кравел робить з деталями","навіщо збирати деталі авто"}},{q="Де лежать ці деталі?",a="Деталі розкидані по відкритій пустельній рівнині Мерехтливих Низин довкола центрального гоночного табору: це купи викинутого механічного брухту, покручені шестерні, циліндри й сплющені металеві пластини.",al={"де деталі","де шукати деталі ракетного авто","деталі на мерехтливих низинах"}},{q="Чи пов'язане це завдання з іншими дорученнями довкола треку?",a="Так. Збирати мотлох на рівнинах зручно разом із полюванням на місцеву звірину для інших завсідників треку: можна збирати отруту з жал скорпідів, черепашачі панцирі й заразом проріджувати місцевих стерв'ятників і василісків, мандруючи широкими соляними рівнинами.",al={"чи пов'язані завдання траси","завдання полювання на низинах","завдання з деталями"}},{q="Що стається з пілотами, що потрапляють у ці аварії?",a="Перегони ракетних болидів сумнозвісно смертоносні. Перебираючи зібраний брухт, Колбірд мимохідь помічає відірване вухо, затиснуте між металевими пластинами, — похмуре свідчення того, що чимало пілотів не повертаються зі швидкісних випробувань.",al={"чи виживають пілоти","роздавлене вухо","смерті пілотів траси"}}},fp="16,378,24.464.0,30.467.0,24.272.0,63.294.0,43.255.0,30.225.0,56.256.0,53.243.0"}
P.entries["quest:112"] = {n="Збір водоростей",s="«Збір водоростей» — доручення аптекаря Вільяма Пестла з Ґолдшира, що має допомогти двом юним закоханим, яким не судилося бути разом. Щоб зварити зілля невидимості для Мейбелл Маклур, Пестл посилає шукачів пригод відбирати рідкісні морські водорості в мурлоків, що гніздяться довкола Кришталевого Озера.",h="«Збір водоростей» — доручення аптекаря Вільяма Пестла з Ґолдшира, що має допомогти двом юним закоханим, яким...",kw={"водорості","мурлоки","кришталеве озеро","ґолдшир","пестл","зілля невидимості","закохані"},ang={["faction:Alliance"]="Зачищаючи табори мурлоків довкола Кришталевого Озера за дивним дорученням Пестла, ви заразом угамовуєте агресивну загрозу, що причаїлася надто близько до східного шляху з Ґолдшира.",["profession:Herbalism"]="Для збирачів трав кришталеві водорості — рідкісна дивовижа: океанська рослина, яку добувають не з ґрунту чи морського дна, а просто з торбин прісноводних мурлоків-збирачів."},sec={{t="Ліки від забороненого кохання",b="Запекла ворожнеча між фермерськими родинами Стоунфілдів і Маклурів не дає юним Томмі Джо Стоунфілду та Мейбелл Маклур зустрічатися відкрито. У відчаї, прагнучи навідати коханого й не спричинити збройної бійки між ріднею, Мейбелл шукає незвичного виходу: прослизнути через долину непоміченою. Вільям Пестл, химерний травник і аптекар, що влаштувався в Корчмі «Лев'яча Гордість» у Ґолдширі, береться зварити лікер невидимості. Та для такого рідкісного напою потрібні інгредієнти, яких у шафах «Лев'ячої Гордості» не знайти."},{t="Збирачі з Кришталевого Озера",b="Головна складова для варива Пестла — кришталеві водорості. Зазвичай вони ростуть далеко в солоних океанських водах, але прісні береги Кришталевого Озера, що лежить одразу на схід від Ґолдшира, захопили племена мурлоків. Із причин, відомих лише їхнім дивним інстинктам, ці прибережні збирачі натягали оберемки морських кришталевих водоростей у свої грубі табори на суходолі. Щоб назбирати досить стебел, доведеться прорубати собі шлях крізь кубла лютих земноводних, вирвати рослини з їхніх лап і повернутися до Ґолдшира, де Пестл перегонить лікер."}},faq={{q="Навіщо Вільямові Пестлу кришталева ламінарія?",a="Кришталева ламінарія потрібна Вільямові Пестлу як головний реагент, щоб зварити лікер невидимості. Цей напій має допомогти Мейбелл Маклур непомітно вислизнути з родинного виноградника й побачитися з Томмі Джо Стоунфілдом.",al={"навіщо вільяму пестлу ламінарія","для чого ламінарія","складники вільяма пестла"}},{q="Чому морська ламінарія росте біля прісного Кришталевого Озера?",a="Кришталева ламінарія росте в океані, але плем'я мурлоків, що заполонили Кришталеве Озеро, збирає й переносить її вглиб суходолу. Вони складають листя в своїх таборах на березі, тож поблизу Ґолдширу це єдине джерело.",al={"чому ламінарія біля прісного озера","ламінарія в прісній воді","лор ламінарії мурлоків"}},{q="Хто такі Мейбелл Маклур і Томмі Джо Стоунфілд?",a="Мейбелл і Томмі Джо — молоді закохані з ворожих фермерських родин на півдні Лісу Елвінн. Їхні родини ненавидять одна одну, тож парі доводиться вдаватися до таємниць і алхімічних хитрощів, щоб просто поговорити.",al={"мейбелл маклур і томмі джо","хто такі закохані","ворожнеча маклурів і стоунфілдів"}},{q="Де розташоване Кришталеве Озеро?",a="Кришталеве Озеро лежить просто на схід від містечка Ґолдшир у центральному Лісі Елвінн. Його води й береги аж кишать ворожими мурлоками.",al={"місце кришталевого озера","де кришталеве озеро","знайти кришталеве озеро"}},{q="Що буде, коли збереш ламінарію?",a="Коли ви доставите чотири листки кришталевої ламінарії, Вільям Пестл переганяє їх на Лікер Невидимості. Тоді він доручає вам віднести напій Мейбелл Маклур, щоб та могла таємно втекти.",al={"що після ламінарії","що вільям пестл робить"}},{q="Хто такий Вільям Пестл?",a="Вільям Пестл — аптекар і аматор алхімії, що живе в Корчмі «Лев'яча Гордість» у Ґолдширі. Він допомагає місцевим народними ліками, дивними зіллями й делікатними послугами.",al={"хто такий вільям пестл","пестл ґолдшир"}}},fp="15,282,27.576.0,30.581.0,42.211.0,53.225.0,49.224.0,30.150.0,39.206.0,22.182.0"}
P.entries["quest:1130"] = {n="Звістка від Мелора",s="«Звістка від Мелора» — поклик, який Джорн Скайсір у Пустках передає від імені славетного мисливця Мелора Стоунгуфа. Шукачів пригод, що вже довели свою витривалість у Калімдорі, скеровують на Узвишшя Мисливців у Тандер Блафі, де на них чекає значно суворіше випробування.",h="«Звістка від Мелора» — поклик, який Джорн Скайсір у Пустках передає від імені славетного мисливця Мелора...",kw={"звістка від мелора","мелор стоунгуф","джорн скайсір","узвишшя мисливців","тандер блаф","мисливець","полювання"},ang={["class:Hunter"]="Мелор Стоунгуф — взірець звіриного ремесла тауренів: він вимагає точності, терпіння й безмежної поваги до небезпечної здобичі.",["faction:Horde"]="Табір Тауражо й Тандер Блаф покладаються на вправних польових бійців, які дають раду небезпечним хижакам, що підбираються до шляхів постачання й застав Орди.",["race:Tauren"]="Для тауренів відгукнутися на поклик Мелора — традиційний обряд дорослішання й здобуття поваги, що доводить майстерність у Полюванні й приносить честь Узвишшю Мисливців."},sec={{t="Поклик до Тандер Блафа",b="Чутки на рівнинах ширяться швидко. Коли шукач пригод набирається досвіду в Пустках і сусідніх краях, знані мисливці помічають тих, хто справді подає надії. Джорн Скайсір, що наглядає за переправами й таборами, служить посланцем старійшин Узвишшя Мисливців. Він перехоплює здібних мисливців і воїнів, щоб повідомити: Мелор Стоунгуф, шанований наставник серед тауренів, накреслив для них особливий шлях."},{t="Дорога до полювання",b="Піднявшись на висоти Узвишшя Мисливців у Тандер Блафі, шукач зустрічає самого Мелора. Старий мисливець не розсипається в похвалах, а натомість питає, чи вистачить шукачеві пригод рішучості вирушити в небезпечні далекі нетрі. Відгукнувшись на поклик, мисливець відкриває для себе випробування далеко за межами безпечного Малгору, де йому доведеться змагатися з найлютішими хижаками континенту."}},faq={{q="Хто такий Мелор Стоунгуф?",a="Мелор Стоунгуф — досвідчений таурен-мисливець на Узвишші Мисливців у Тандер Блафі. Він оцінює молодих слідопитів і воїнів Орди й посилає гідних по всьому Калімдору вистежувати й полювати на сумнозвісних звірів.",al={"мелор","хто такий мелор","лор мелора стоунгуфа"}},{q="Хто приносить цей виклик?",a="Звістку несе Джорн Скайсір — таурен-приборкувач звірів із Табору Тауражо в Пустках. Він придивляється до мандрівників і посилає тих, хто виявив відвагу, у Тандер Блаф — поговорити з Мелором особисто.",al={"хто приносить виклик","йорн скайсір","хто послав по мене"}},{q="Де знайти Мелора Стоунгуфа?",a="Мелор на Узвишші Мисливців — південному плато Тандер Блафу, присвяченому мисливцям, слідопитам і приборкувачам звірів серед тауренів.",al={"місце мелора","де мелор","підвищення мисливців тандер блафф"}},{q="Який шлях Мелор приготував для мене?",a="Мелор перевіряє вашу витривалість і мисливське чуття, посилаючи у важкі походи за слідом, і починає з полювання в Тисячі Голок на лютого гієнового тирана Стілснепа.",al={"який шлях приготував мелор","чого хоче мелор","наступне завдання мелора"}},{q="Чому Мелор набирає шукачів пригод у Пустках?",a="Хто вижив серед суворих хижаків, шипогривів і кентаврів Пусток, той довів, що має чуття, потрібне для полювань найвищого ґатунку. Мелор шукає тих, хто здатен вистежити невловиму й смертельну здобич у незнайомих краях.",al={"чому мелор набирає в пустках","чому я"}},{q="Чи це випробування лише для мисливців?",a="Хоча воно бере початок на Узвишші Мисливців і перевіряє чесноти слідопита, Мелор пропонує його будь-якому шукачеві пригод з Орди, що довів свою силу й винахідливість у дикій природі.",al={"чи лише для мисливців","мисливське завдання"}}},fp="16,268,26.447.0,20.401.0,23.232.0,26.218.0,33.137.0,35.190.0,52.216.0,36.187.0"}
P.entries["quest:1131"] = {n="Стілснеп",s="«Стілснеп» — мисливське доручення від Мелора Стоунгуфа з Узвишшя Мисливців у Тандер Блафі. Це полювання відходить від звичних для тауренів причин убивати: його мета — знищити лютого ватажка гієн, чия зграя тероризує звірів Тисячі Голок.",h="«Стілснеп» — мисливське доручення від Мелора Стоунгуфа з Узвишшя Мисливців у Тандер Блафі.",kw={"стілснеп","мелор стоунгуф","гієни","тисяча голок","табір е'ток","узвишшя мисливців","мисливець"},ang={["class:Hunter"]="Вполювати Стілснепа — перевірка вміння слідопита відокремити лютого ватажка зграї від його мандрівного супроводу на дні каньйону.",["faction:Horde"]="Безпечніший шлях крізь Тисячу Голок захищає важливі шляхи постачання й мандрівників, що спускаються з Пусток до Мерехтливих Низин.",["race:Tauren"]="Для шу'гало позбавити звіра життя — справа духовна. Полювання на Стілснепа — повчальний урок того, як прибирати з дикої природи те, що чинить безглузду жорстокість і лишається поза милістю Земної Матері."},sec={{t="Полювання поза благословенням",b="Традиція тауренів велить, щоб відібране життя служило священній або практичній меті: полювання заради прожитку, заради честі чи заради мудрості від Земної Матері. Мелор Стоунгуф пропонує цю здобич як виняток із правила. Стілснепа вважають потворою, що руйнує природну рівновагу, — жорстоким тираном, який сіє безглузде насильство й страх, а не підтримує коло життя."},{t="Напасть Тисячі Голок",b="Стілснеп блукає каньйонами північної частини Тисячі Голок, тримаючись на південь від поселення кентаврів у Таборі Е'ток. На відміну від самотніх падальників, цей грізний звір збирає довкола себе лютих товаришів по зграї й керує нападами, що розганяють і винищують сумирніших звірів на дні каньйону. Убивши його й забравши ребро, ви очищаєте каньйони Тисячі Голок від його лютого впливу."}},faq={{q="Чому Мелор Стоунгуф хоче смерті Стілснепа?",a="Мелор Стоунгуф вважає Стілснепа виродком, що існує поза благословенням Земної Матері. На відміну від полювань заради прожитку, честі чи природної рівноваги, це полювання — очищення, щоб зупинити тиранічного хижака, який тероризує мирних звірів.",al={"чому мелор хоче вбити стілснепа","причина мелора","мотив стілснепа"}},{q="Де знайти Стілснепа?",a="Стілснеп никає курним дном каньйону Тисячі Голок, на південь від поселення кентаврів у Таборі Е'ток у північно-західній частині краю.",al={"де стілснеп","місце стілснепа","знайти стілснепа"}},{q="Який доказ треба принести до Тандер Блафа?",a="Треба забрати Ребро Стілснапа з убитого звіра й показати його Мелорові Стоунгуфу на Узвишші Мисливців.",al={"який доказ нести до тандер блафа","трофей стілснепа","що лутити"}},{q="Чи б'ється Стілснеп сам?",a="Ні. Стілснеп ходить у супроводі інших гієн, що йдуть за ним, тож сутичка з ним — небезпечний бій із кількома супротивниками.",al={"чи стілснеп сам","зграя стілснепа","приспішники стілснепа"}},{q="Чим це полювання відрізняється від традиційних полювань тауренів?",a="Зазвичай таурени полюють лише заради прожитку, бойової честі чи духовного прозріння, а це полювання суто запобіжне: треба позбутися жорстокого звіра, який порушує природну гармонію краю.",al={"чим полювання відрізняється","філософія полювання тауренів","уроки полювання"}},{q="Де живе Мелор Стоунгуф?",a="Мелор Стоунгуф живе на Узвишші Мисливців у Тандер Блафі, де навчає мисливців і випробовує досвідчених слідопитів.",al={"де мелор","місце мелора стоунгуфа","координати мелора"}}},fp="9,247,27.409.0,26.372.0,47.256.0,29.146.0,49.103.0,27.129.0,56.195.0,33.112.0"}
P.entries["quest:1132"] = {n="Фіора Лонґірс",s="Це доручення знайомить шукачів пригод Альянсу зі Східних Королівств з неприборканим континентом Калімдор. За вказівкою запального вербувальника Рудого Джека Флінта з Гавані Менетіл мандрівники перепливають Велике Море, щоб доповісти його знайомій — високій ельфійці Фіорі Лонґірс у корчмі Терамору.",h="Це доручення знайомить шукачів пригод Альянсу зі Східних Королівств з неприборканим континентом Калімдор.",kw={"фіора лонґірс","рудий джек флінт","терамор","гавань менетіл","калімдор","велике море","завдання"},ang={["faction:Alliance"]="Ця подорож — міст між Східними Королівствами й землями нічних ельфів у Калімдорі, що єднає східні й західні рубежі Альянсу.",["race:NightElf"]="Фіора Лонґірс офіційно вітає союзників зі сходу, що прибувають до Терамору, і готує їх до давніх диких країв північного Калімдору."},sec={{t="Поклик Заходу",b="Для багатьох людей, дворфів і гномів Східні Королівства обтяжені давніми чварами й пошрамованою землею. У гамірному порту Гавані Менетіл моряк Рудий Джек Флінт цілими днями вмовляє охочих до пригод мандрівників сісти на корабель, що вирушає через Велике Море. Описуючи Калімдор як незвідані краї багатства й можливостей, Флінт посилає сміливців до Терамору — до своєї знайомої, ельфійки на ім'я Фіора Лонґірс."},{t="Прибуття до Терамору",b="Переплинувши океан, мандрівники прибувають до Терамору — порту Альянсу на узбережжі Багна Пилоброду. У міській корчмі Фіора Лонґірс зустрічає прибулих, яких порекомендував Флінт. Довіряючи Флінтовому вмінню розпізнавати людей, Фіора вітає новоприбулих героїв Альянсу й готується спрямувати їх углиб материка, до давніх лісів Ашенвалю."}},faq={{q="Хто така Фіора Лонґірс?",a="Фіора Лонґірс — висока ельфійка, що зупинилася в корчмі Терамора в Багні Пилоброду. Вона — напарниця й довірена особа Рудого Джека Флінта: вітає мандрівників з Альянсу, які прибувають зі Східних Королівств.",al={"хто така фіора","фіора лонґірс"}},{q="Хто дає це завдання?",a="Завдання дає Рудий Джек Флінт — завзятий моряк-людина з Гавані Менетіл на узбережжі Багнокраю.",al={"хто дає завдання","де взяти завдання фіори","давець фіори"}},{q="Як дістатися від Гавані Менетіл до Фіори Лонґірс?",a="Сядьте на пасажирське судно біля пристані Гавані Менетіл, що пливе на захід через Велике Море просто до Терамора в Багні Пилоброду.",al={"як дістатися від менетілу до фіори","корабель до терамору","човен із менетілу"}},{q="Що буде після зустрічі з Фіорою Лонґірс?",a="Привітавши вас у Тераморі, Фіора схвалює рекомендацію Флінта й пропонує наступний відтинок шляху — посилає вас углиб суходолу, до Астранаару в Ашенвалі.",al={"що після фіори","продовження","завдання подорож до астранаару"}},{q="Які стосунки між Рудим Джеком Флінтом і Фіорою Лонґірс?",a="Флінт називає Фіору своєю напарницею за морем. Поки Флінт шукає завзятих шукачів пригод у Східних Королівствах, Фіора приймає їх у Калімдорі, сприяючи справам Альянсу й подорожам углиб краю.",al={"рудий джек флінт і фіора","чи флінт і фіора партнери"}},{q="Чому Альянс набирає мандрівників до Калімдору?",a="Калімдор — це величезні нові землі й ресурси для Альянсу, а також фронт, де союзникам-нічним ельфам потрібна допомога, щоб боронити землі предків від загроз на кшталт Орди й залишків демонічних сил.",al={"чому альянс набирає в калімдор","чому терамор"}}},fp="14,298,18.431.0,20.337.0,22.211.0,22.125.0,51.136.0,42.156.0,67.199.0,53.213.0"}
P.entries["quest:1133"] = {n="Подорож до Астранаару",s="«Подорож до Астранаару» — вступне завдання для Альянсу, що веде новоприбулих з узбережжя Калімдору в глибину, до серця Ашенвалю. За вказівкою Фіори Лонґірс із Терамора мандрівники вирушають на північ, до Ашенвалю, щоб доповісти Шіндрелл Свіфтфайр в Астранаарі. Так шукач пригод уперше потрапляє в розпал конфліктів довкола родового лісу нічних ельфів.",h="«Подорож до Астранаару» — вступне завдання для Альянсу, що веде новоприбулих з узбережжя Калімдору в глибину...",kw={"подорож до астранаару","фіора лонґірс","терамор","шіндрелл свіфтфайр","ашенваль","завдання"},ang={["faction:Alliance"]="Ця мандрівка — пряме перекидання новобранця Альянсу з відносно безпечних портів Багна Пилоброду в спірну глушину Ашенвалю.",["race:Human"]="Щойно зійшовши з корабля з Гавані Менетіл, мандрівники-люди роблять перші кроки вглиб Калімдору, дотримуючись обітниці Альянсу допомагати нічним ельфам.",["race:NightElf"]="Для нічних ельфів ця подорож — повернення до обложеного серця рідного краю, щоб боронити священне гілля Ашенвалю разом із чужоземними союзниками."},sec={{t="Від узбережжя до лісів",b="Мандрівники Альянсу, що прибувають у Багно Пилоброду поромом із Гавані Менетіл, часто шукають собі справи на півночі Калімдору. У Тераморі Фіора Лонґірс посилає вправних помічників углиб суходолу, до Астранаару — головного поселення нічних ельфів в Ашенвалі. Шлях в'ється під прадавнім затіненим лісовим покровом і веде просто в ліс, виснажений війною й неспокоєм."},{t="Рекомендація без імені",b="Дивно, але Фіора радить мандрівникам навіть не згадувати її ім'я в Астранаарі, бо, як вона прямо каже, Шіндрелл Свіфтфайр її не знає. Її справа — просто спрямовувати свіжі сили Альянсу туди, де вони найпотрібніші. Шіндрелл охоче вітає кожного здатного захисника й визнає: хоч Ашенваль і досі захоплює подих, він уже не той мирний притулок, яким був колись."}},faq={{q="Де починається завдання «Подорож до Астранаару»?",a="Завдання дає Фіора Лонґірс у Тераморі на узбережжі Багна Пилоброду. Вона пропонує його мандрівникам з Альянсу, що прибувають зі Східних Королівств і хочуть допомогти в Калімдорі.",al={"хто дає подорож до астранаару","початок подорожі до астранаару","де взяти подорож"}},{q="З ким треба поговорити в Астранаарі?",a="Вам треба поговорити із Шіндрелл Свіфтфайр — нічною ельфійкою, що служить в Астранаарі, головному містечку Альянсу в Ашенвалі.",al={"з ким говорити в астранаарі","кінець подорожі до астранаару","хто шіндрелл свіфтфайр"}},{q="Чому Фіора просить не згадувати її ім'я?",a="Фіора Лонґірс прямо радить шукачам пригод не казати, хто їх послав, просто тому, що Шіндрелл не знає її особисто. Вона лише спрямовує завзятих новачків до застави, якій конче потрібна допомога.",al={"чому фіора просить не згадувати ім'я","фіора й шіндрелл"}},{q="Яка мета цього завдання?",a="Воно веде персонажів Альянсу з Багна Пилоброду в Ашенваль і знайомить їх з Астранааром — головною опорою для дій у лісі.",al={"мета завдання","навіщо подорож до астранаару"}},{q="Що за біда коїться в Ашенвалі?",a="Як зауважує Шіндрелл Свіфтфайр, коли ви прибуваєте, Ашенваль уже не той тихий гай, що колись. Лісу загрожують вторгнення Орди, демонічна скверна, що лишилася з Третьої війни, і місцева звірина, збурена недавніми сутичками.",al={"біда в ясенлісі","чому астранаару потрібна допомога"}},{q="Яке завдання веде до «Подорожі до Астранаару»?",a="Перед ним іде коротке вступне завдання «Фіора Лонґірс», яке спрямовує мандрівників, що прибули до Багна Пилоброду, поговорити з нею в Тераморі.",al={"передумова подорожі","ланцюжок фіори лонґірс"}}},fp="20,378,29.398.0,26.407.0,48.198.0,38.116.0,43.220.0,34.172.0,47.251.0,43.173.0"}
P.entries["quest:1134"] = {n="Ґордокрили Кам'яного Кігтя",s="Шіндрелл переказує непідтверджені відомості: стривожені таємними нападами Орди, вартові в Астранаарі прагнуть перехопити смертоносну зброю, перш ніж вона вдарить по їхньому народу. Розвідка з Терамора повідомляє, що орківські вбивці добувають отруту з віверн Гір Кам'яного Кігтя для таємних нальотів. Щоб захистити свій тендітний кордон, розвідників Альянсу посилають на південь зібрати отруйні мішечки першими й позбавити ворога смертельної отрути.",h="Шіндрелл переказує непідтверджені відомості: стривожені таємними нападами Орди, вартові в Астранаарі прагнуть...",kw={"ґордокрили","шіндрелл свіфтфайр","астранаар","отрута","гори кам'яного кігтя","терамор"},ang={["class:Druid"]="Друїди часто оплакують марно загублене природне життя, шкодуючи, що безневинних створінь доводиться винищувати лише для того, щоб їхня отрута не дісталася паліям війни.",["class:Rogue"]="Розбійники здатні оцінити смертоносну користь отрути ґордокрилів, бо добре знають, якими руйнівними бувають змащені отрутою клинки в таємних засідках серед дикої природи.",["faction:Alliance"]="Ця місія показує тиху розвідувальну мережу, що пов'язує поселення Джайни в Тераморі із заставами вартових в Ашенвалі, щоб зірвати задуми Орди.",["race:NightElf"]="Нічні ельфи важко переживають похмуру необхідність убивати диких ґордокрилів, зважуючи своє духовне служіння природі на тлі суворої дійсності прикордонної війни."},sec={{t="Крихке перемир'я",b="Хоч відкритої війни між Альянсом і Ордою на півночі Калімдору не оголошено, мир між ними тонкий, як лезо. Під густим лісовим покровом спалахують сутички, а замість великих армій тепер діють тихі удари, від яких завжди можна відхреститися. Командувачки вартових в Астранаарі невпинно пильнують таємні пересування ворога, знаючи, що безтурботність може коштувати їм притулку."},{t="Отрута з-поміж скель",b="Шіндрелл переказує непідтверджені відомості: таємні зв'язкові з Терамора принесли звістку про зловісну справу, що коїться серед скель Кам'яного Кігтя. Орківські слідопити збирають отруту з диких ґордокрилів довкола Озера Міркфаллон і змащують цією сильною природною отрутою клинки для смертельних засідок на людей Альянсу. Щоб відвернути загрозу, Шіндрелл Свіфтфайр посилає звитяжців винищити звірів і забрати отруйні мішечки, перш ніж їх зберуть агенти Орди."},{t="Болісний обов'язок",b="Наказ нищити тутешніх звірів тяжко лягає на серце нічних ельфів, які глибоко шанують дику природу Калімдору. Шіндрелл і сама шкодує, що безневинні створіння мусять страждати через війну, яку вони не обирали. Та в похмурому розрахунку прикордонної оборони позбавити ворога смертельної зброї важливіше, ніж берегти природу."}},faq={{q="Хто такі ґордокрили?",a="Ґордокрили — небезпечні отруйні летючі звірі, споріднені з віверном, що гніздяться на високих скелях, особливо довкола Озера Міркфаллон у Горах Кам'яного Кігтя. Сильна отрута робить їх смертоносними хижаками й бажаною здобиччю для отруйників.",al={"хто такі ґордокрили","лор ґордокрилів","ґордокрили стоунталона"}},{q="Чому Альянс на них полює?",a="Шіндрелл переказує непідтверджені відомості: розвідка Альянсу повідомляє, що вбивці Орди збирають отруту ґордокрилів, щоб змащувати нею зброю для таємних нападів на позиції Альянсу. Винищуючи звірів і першим забираючи їхні отруйні мішечки, Альянс позбавляє Орду цієї смертоносної отрути.",al={"чому вбивати ґордокрилів","мета завдання","альянс отрута ґордокрилів"}},{q="Хто доповів про орків-убивць?",a="Попередження надійшло від таємних інформаторів Альянсу в Тераморі, які пильно стежать за пересуванням Орди та її мережами постачання в південних Пустках і Горах Кам'яного Кігтя.",al={"хто попередив про орків-убивць","шпигун терамору","джерело розвідки шіндрелл"}},{q="Де розташоване Озеро Міркфаллон?",a="Озеро Міркфаллон лежить на півночі Гір Кам'яного Кігтя, трохи на південь від прикордонної стежки, що веде з Ашенвалю.",al={"місце озера міркфаллон","де ґордокрили","знайти ґордокрилів"}},{q="Чи ведуть Альянс і Орда відкриту війну в Ашенвалі?",a="Офіційно обидві фракції тримають хиткий мир і уникають оголошеної відкритої війни. Насправді ж таємні вбивства, сутички за ресурси й прикордонні конфлікти безперестанку спалахують під кронами лісу.",al={"чи війна орди й альянсу в ясенлісі","статус війни ясенлісся","мир ясенлісся"}},{q="Що Шіндрелл Свіфтфайр думає про вбивство звірів?",a="Шіндрелл тяжко наказувати вбивати звірів, які не з власної волі втягнуті в конфлікт. Та як офіцерка, що відповідає за оборону Астранаару, вона вважає це трагічною необхідністю, щоб уберегти свій народ.",al={"що шіндрелл думає про вбивство звірів","друїдська провина","нічні ельфи вбивають звірів"}}},fp="24,459,15.398.0,21.505.0,14.350.0,20.242.0,33.316.0,54.186.0,33.128.0,52.213.0,59.216.0"}
P.entries["quest:1135"] = {n="Отрута Високосіда",s="Фіора Лонґірс в Обердайні посилає шукачів пригод Альянсу далеко на південь, до каньйонів Тисячі Голок. Там, на високих урвищах Високосіду, гніздяться небезпечні віверни, яких цінують за надзвичайно сильну отруту.",h="Фіора Лонґірс в Обердайні посилає шукачів пригод Альянсу далеко на південь, до каньйонів Тисячі Голок.",kw={"отрута високосіда","фіора лонґірс","високосід","віверни","тисяча голок","обердайн"},ang={["class:Rogue"]="Розбійники добре розуміють темну привабливість екзотичних отрут. Добуваючи чисту, неочищену отруту віверн, ви по-справжньому оціните найсмертоносніші природні речовини Калімдору.",["faction:Alliance"]="Вирушаючи до Тисячі Голок, шукачі пригод Альянсу опиняються глибоко в тилу ворога, просто під пильним оком дозорів Орди — тауренів та орків.",["race:NightElf"]="Для калдореїв Обердайна те, що мисливців посилають аж у посушливі пустки Тисячі Голок, показує, як далеко за межі Ашенвалю й Темного Узбережжя сягають торговельні інтереси й цікаві реагенти."},sec={{t="Вигідна експедиція",b="Відпочиваючи в приморському порту Обердайн, мандрівники можуть зустріти Фіору Лонґірс. Орки зазвичай ловлять і приручають віверн як летючих скакунів, але Фіора вказує на куди потаємнішу торгівлю — смертоносну отруту цих істот. Дехто з покупців у Калімдорі цінує свіжі отруйні мішечки значно більше, ніж самих звірів, тож Фіора наймає мисливців, готових до далеких мандрів і небезпечних висот."},{t="Скелі Високосіду",b="Здобич гніздиться далеко на південь від Темного Узбережжя, серед височенних пісковикових столових гір Тисячі Голок. У гніздовищі, відомому як Високосід, місцеві віверни мають незвично концентровану отруту. Щоб дістатися їхніх гнізд, доведеться пройти ворожими землями Орди й видертися підступними схилами, де мисливці мусять убивати віверн, добувати цілі отруйні мішечки й нести здобич назад на Темне Узбережжя."}},faq={{q="Де знайти вівернів для цього завдання?",a="Віверни живуть на Високосіді — високому плато в західній частині Тисячі Голок, далеко на південь від Темного Узбережжя.",al={"де віверни","місце високосіду","місце вівернів"}},{q="Хто така Фіора Лонґірс?",a="Фіора Лонґірс — довірена особа Альянсу в Обердайні на узбережжі Темного Узбережжя. Вона наймає відважних шукачів пригод, щоб здобувати рідкісні й цінні природні реагенти по всьому Калімдору.",al={"фіора лонґірс","хто дає отруту високосіду"}},{q="Чому отрута вівернів така цінна?",a="Отрута вівернів надзвичайно сильна й високо цінується в певних тіньових колах, серед аптекарів і в торговельних мережах. Для Орди віверни — передусім їздові летючі тварини, а от їхні отруйні залози алхіміки й отруйники купують за чималі гроші.",al={"чому отрута вівернів цінна","використання отрути вівернів"}},{q="Чому завдання з Обердайна посилає мене так далеко на південь?",a="Фіора — заповзятлива торговка, що шукає екзотичних зразків, яких не знайти на тихих берегах Темного Узбережжя. На Високосіді в Тисячі Голок живе особлива, численна порода вівернів, якої немає в північних лісах.",al={"чому оберін посилає на південь","чому тисяча голок"}},{q="Що буде, коли повернеш отруйні мішечки?",a="Фіора оглядає мішечки й помічає, що вони аж повні отрути, — мовляв, така якість буває лише в молодих вівернів чи плідних самиць, — і вітає вас із вдалим полюванням.",al={"реакція фіори","завершення отрути високосіду"}},{q="Чи безпечний Високосід для мандрівників з Альянсу?",a="Ні. У Тисячі Голок сильна присутність Орди, зосереджена довкола сусідніх поселень на кшталт Застави Вільного Вітру. Видираючись на Високосід, доведеться мати справу і з дикими хижаками, і з ворожими розвідниками Орди.",al={"чи безпечний високосід","альянс у тисячі голок"}}},fp="15,231,22.422.0,22.390.0,43.120.0,22.184.0,32.245.0,50.227.0,44.181.0,41.193.0"}
P.entries["quest:1138"] = {n="Дари моря",s="«Дари моря» — завдання Альянсу, яке дає рибалка Ґуббер Бламп на пристанях Обердайна. Палкий шанувальник страв із ракоподібних, Ґуббер просить мандрівників пошукати на березі Темного Узбережжя Вишукані Шматочки Краба, поки він доглядає свої вудки.",h="«Дари моря» — завдання Альянсу, яке дає рибалка Ґуббер Бламп на пристанях Обердайна.",kw={"дари моря","ґуббер бламп","вишукані шматочки краба","краби","кулінарія","обердайн"},ang={["faction:Alliance"]="Обердайн — важливий пункт висадки для дослідників Альянсу, що прибувають до Калімдору, і тут вистачає дрібних послуг на кшталт допомоги місцевим рибалкам облаштуватися.",["profession:Cooking"]="Захоплений перелік крабових рецептів Ґуббера надихне кожного кухаря, що хоче якнайкраще використати місцевий прибережний улов.",["race:Dwarf"]="Почути, як хтось на півночі Калімдору мріє приготувати «краба-сюрприз по-айронфордзьки», — миле нагадування про дім для мандрівних горян із Каз Модану."},sec={{t="Пристрасть до ракоподібних",b="Ґуббер Бламп, що закидає вудку з довгих дерев'яних пристаней Обердайна, має майже нав'язливу кулінарну пристрасть до крабового м'яса. Вважаючи крабів справжнім скарбом океану, Ґуббер уявляє нескінченний перелік рецептів — від запеченого, смаженого на грилі й вареного краба до вишуканих місцевих делікатесів на кшталт краба з батогокоренем і краба-сюрпризу по-айронфордзьки."},{t="Прочісуючи припливні калюжі",b="Ґуббер не може відірватися від вудки, тож покладається на шукачів пригод, які зберуть інгредієнти на оповитих імлою пляжах Темного Узбережжя. Берег кишить рифовими й оброслими припливними повзунами, що снують серед прибою, — доступне, хоч часом і щипливе, джерело м'яса для кухаря-початківця на узбережжі."}},faq={{q="Хто дає завдання «Дари моря»?",a="Завдання дає Ґуббер Бламп — рибалка з Альянсу, що працює на пристанях Обердайна на Темному Узбережжі.",al={"хто дає дари моря","давець плід моря","завдання ґуббера бламп"}},{q="З яких істот падають Вишукані Шматочки Краба?",a="Вишукані Шматочки Краба здобувають із рифових повзунів і оброслих припливних повзунів, що ходять берегами й мілким прибоєм уздовж узбережжя Темного Узбережжя.",al={"де падає краб","що падає з крабів","які краби дають шматочки"}},{q="Чому Ґуббер не збирає крабове м'ясо сам?",a="Ґуббер повністю зайнятий риболовлею з причалів Обердайна й не може покинути вудку, щоб полювати на крабів на пляжі.",al={"чому ґуббер сам не збирає","чому ґуббер потребує допомоги"}},{q="Які страви хоче приготувати Ґуббер?",a="Ґуббер вихваляється безліччю способів приготування: салат із краба, юшка, рагу, краб із перцем, краб із лимоном, краб із хлистокоренем і місцевий рецепт, який він називає «краб-сюрприз по-айронфорджськи».",al={"страви ґуббера","рецепти крабів","крабові страви"}},{q="Чи на щось натякає промова Ґуббера Бламп?",a="Так. Його монолог із переліком усіх мислимих способів приготувати краба — явна данина Бенджамінові Бьюфорду «Баббі» Блу з фільму «Форрест Ґамп», який виголосив таку саму знамениту промову про креветки.",al={"посилання в мові ґуббера","поп-культура ґуббер"}},{q="Де відбувається це завдання?",a="Завдання починається й здається в портовому селищі Обердайн, а полювання відбувається на берегах Темного Узбережжя на півночі Калімдору.",al={"місце дарів моря","яка зона дарів моря"}}},fp="16,260,25.370.0,21.355.0,37.107.0,41.150.0,48.128.0,37.196.0,47.202.0,33.145.0"}
P.entries["quest:114"] = {n="Втеча",s="«Втеча» — розв'язка забороненого роману Мейбелл Маклур і Томмі Джо Стоунфілда в Лісі Елвінн. Зібравши інгредієнти по всьому краю, ви приносите Мейбелл зварений Вільямом Пестлом Лікер Невидимості, щоб вона непомітно прослизнула повз рідню. Це коротка таємна перемога юного кохання над закоренілою сільською ворожнечею.",h="«Втеча» — розв'язка забороненого роману Мейбелл Маклур і Томмі Джо Стоунфілда в Лісі Елвінн.",kw={"втеча","мейбелл маклур","томмі джо","лікер невидимості","пестл","ліс елвінн","кохання"},ang={["faction:Alliance"]="Для юних шукачів пригод, що починають шлях у Лісі Елвінн, допомога Томмі Джо й Мейбелл — легкий перепочинок між боями з бандитами Дефіас і гнолами. Вона показує, що буденні сільські чвари живуть навіть на порозі Стормвінда.",["race:Human"]="Місцеві люди-поселенці Елвінну добре знають, якими глибокими бувають уперті родинні образи, тож дрібна таємна сусідська допомога тут — запорука миру."},sec={{t="Вариво для справжнього кохання",b="Ворожнеча Маклурів і Стоунфілдів тягнеться поколіннями й не лишає місця для злагоди, а тим паче для залицянь. Обидві родини пильно бережуть своїх і люто ненавидять сусідів, тож Бабуся Стоунфілд звернулася до Вільяма Пестла, алхіміка з Корчми «Лев'яча Гордість» у Ґолдширі. З кришталевих водоростей, зібраних на ближніх озерах, Пестл склав Лікер Невидимості — достатньо сильний, щоб приховати втечу Мейбелл із садиби Маклурів."},{t="Зникнути в лісі",b="Отримавши пляшку, Мейбелл Маклур може вислизнути поміж дерев до Томмі Джо. Її мучить провина за обман рідних, та відданість коханому сильніша за страх викриття. Випивши лікер, вона зникає просто у вас на очах — і закохані здобувають кілька дорогоцінних хвилин наодинці, подалі від пильних поглядів ворогуючих старших."}},faq={{q="Хто дає завдання «Втеча»?",a="Вільям Пестл — аптекар і помічник-алхімік із Корчми «Лев'яча Гордість» у Ґолдширі — дає вам Лікер Невидимості, щойно ви принесете йому кришталеву ламінарію.",al={"хто дає втечу","давець завдання втеча","де взяти втечу"}},{q="Для чого потрібен Лікер Невидимості?",a="Лікер дає Мейбелл Маклур змогу стати цілком невидимою на досить довгий час, щоб вислизнути з родинної ферми й навідати Томмі Джо Стоунфілда, не накликавши гніву рідні.",al={"навіщо лікер невидимості","що робить зілля","призначення лікеру"}},{q="Чому Мейбелл і Томмі Джо мусять приховувати свої стосунки?",a="Родини Маклурів і Стоунфілдів — запеклі суперниці, що досі ворогують. Через глибоку ворожнечу між цими домами будь-яке відкрите залицяння їхніх дітей суворо заборонене.",al={"чому закохані ховаються","ворожнеча стоунфілдів і маклурів","чому мейбелл і томмі не можуть бути разом"}},{q="Що стається, коли приносиш зілля Мейбелл?",a="Мейбелл дякує вам, зізнається, що відчуває і провину, і хвилювання, і одразу випиває напій. Вона зникає просто у вас на очах, щоб непомітно прослизнути до Томмі Джо.",al={"що буде в кінці","чи мейбелл зникне","завершення втечі"}},{q="Яке завдання веде просто до «Втечі»?",a="«Втеча» йде одразу після завдання «Збір водоростей», у якому ви забираєте кришталеву ламінарію в мурлоків біля Кришталевого Озера, щоб Вільям Пестл зварив зілля невидимості.",al={"передумова втечі","завдання перед втечею","що веде до втечі"}},{q="Чи це завдання кладе край ворожнечі родин?",a="Ні. Зілля дає закоханим лише тимчасове таємне побачення. Ширша ворожнеча між Бабусею Стоунфілд і Маклурами лишається такою ж запеклою й нерозв'язаною, як і раніше.",al={"чи кінець ворожнечі","чи родини помиряться","кінець ворожнечі родин"}}},fp="10,366,26.442.0,24.354.1,31.186.0,41.182.0,61.208.0,52.172.1,42.177.0,54.175.1"}
P.entries["quest:1140"] = {n="Вежа Альталакса",s="Це завдання — шостий розділ хрестового походу проти культистів Вежі Альталакса, яким керує Делґрен Очищувач із Посту Маестри. Делґрен розшифровує орківські записи, відібрані в посланців культу, і з'ясовує, що чорнокнижник Атрікус Нарассін сховав два самоцвіти душі з ув'язненими Високородними в демонічних твердинях сатирів глибоко в Ашенвалі. Звитяжців посилають до Нічного Потоку й Сатирнаара, щоб розбити ці вмістища, звільнити змучених давніх духів і знищити темне джерело сили Атрікуса.",h="Це завдання — шостий розділ хрестового походу проти культистів Вежі Альталакса, яким керує Делґрен Очищувач...",kw={"вежа альталакса","делґрен очищувач","атрікус нарассін","самоцвіти душі","нічний потік","сатирнаар"},ang={["class:Paladin"]="Делґрен Очищувач — прагматичний святий хрестоносець: він користується мовою ворогів, щоб викривати демонічну порчу й очищати змучених мерців.",["class:Priest"]="Розбиваючи кола ув'язнення, ви даруєте спокій змученим духам, що століттями терпіли демонічні тортури.",["race:NightElf"]="Звільнити предків-Високородних від наруги сатирів — урочистий обов'язок, що ставить вас віч-на-віч із трагічними рештками давнього минулого вашого народу."},sec={{t="Розшифровуючи каракулі",b="Зарубавши орка-кур'єра Ілкруда Маґтрулла, Делґрен Очищувач нарешті знаходить застосування своєму суперечливому вивченню орківської мови. Його побратими у Святому Світлі часто глузували з бажання вивчати мову ворогів, та прагматичне чуття Делґрена допомагає розплутати таємну торгівлю культу. Записи свідчать, що Атрікус Нарассін здобув два могутні самоцвіти душі з сутностями давніх Високородних і сховав їх далеко на північному сході — в осквернених гаях Нічного Потоку й Сатирнаара."},{t="Нечестиві союзи",b="Самоцвіти душі Високородних у таборах сатирів викривають мерзенне злиття темної кліки Атрікуса з демонічними нащадками Палаючого Легіону. Прикуті над обрядовими колами ув'язнення, ці давні духи зазнають нескінченних мук, які живлять темне чаклунство. Щоб дістатися закривавлених вівтарів сатирів, доведеться зіткнутися не лише з дикою демонічною порчею, а й із кинджалами прихованих сатирів-скрадачів, що присягнули стерегти ці тайні провідники."},{t="Послабити Атрікуса",b="Розбивши багряні камені й звільнивши душі Високородних із кіл муки, шукачі пригод завдають нищівного удару по запасах містичної сили Атрікуса. Делґрен зауважує, що зі знищенням самоцвітів очільник культу Альталакса тяжко ослаб. Водночас святого хрестоносця непокоїть тиха тривога нічних ельфів щодо сатирів, і він вирішує звернути увагу очільників Обердайна на демонічну пошесть, що не відступає."}},faq={{q="Звідки Делґрен уміє читати орківською?",a="Делґрен сам узявся вивчати мову орків, хоч інші в його святому ордені з нього й глузували. Він переконаний, що знати мову ворога вкрай важливо для тактичного розуміння, — і саме це дає йому змогу перекласти знайдені записи Ілкруда Маґтрулла.",al={"звідки делґрен читає орківською","делґрен орківська","переклад делґрена"}},{q="Що таке камені душ і чому вони в сатирів?",a="Камені душ — багряні фокусувальні кристали, що тримають у полоні давніх духів Високородних ельфів; вони висять над обрядовими колами ув'язнення. Атрікус Нарассін чи то виміняв, чи то розмістив їх у святилищах сатирів на кшталт Нічного Потоку й Сатирнаару, живлячи магічну силу культу їхніми муками.",al={"камені душ альталакса","чому камені душ у сатирів","затримані душі"}},{q="Де розташовані Нічний Потік і Сатирнаар?",a="Обидва місця — демонічні твердині сатирів серед лісистих висот північно-східного Ашенвалю, на схід від Посту Маестри.",al={"де нічний потік","де сатирнаар","табори сатирів"}},{q="Чому нічні ельфи неохоче говорять про сатирів?",a="Делґрен помічає, що його господарі-ельфи уникають розмов про сатирів, бо ці істоти колись самі були нічними ельфами. Під час давньої Війни Прадавніх, піддавшись демонічній скверні, вони перетворилися на козлоногих чортів, і саме їхнє існування — незгасне джерело горя й сорому для калдореїв.",al={"чому нічні ельфи не люблять говорити про сатирів","зв'язок нічних ельфів і сатирів","історія сатирів"}},{q="Як звільнення цих душ допомагає зупинити культ Вежі Альталакса?",a="Атрікус Нарассін значною мірою покладається на викрадену духовну енергію, що зберігається в каменях душ Високородних. Розбиваючи ширяючі камені й звільняючи ув'язнених привидів, ви позбавляєте його обряди сили й робите його вразливим до прямого штурму вежі.",al={"навіщо розбивати камені душ","джерело сили атрікуса","ослабити атрікуса"}},{q="Хто така Елісса, з якою хоче поговорити Делґрен?",a="Елісса Старбриз — помітна вартова з нічних ельфів в Обердайні, що керує місцевою обороною Темного Узбережжя. Делґрен хоче порадитися з нею щодо сатирів, які окопалися й загрожують північному Калімдору.",al={"хто така елісса","делґрен елісса","елісса оберін"}}},fp="22,530,27.504.0,16.470.1,18.489.1,41.284.0,54.289.0,42.127.0,59.327.0,67.248.0,48.226.0"}
P.entries["quest:1141"] = {n="Родина і вудка",s="Ґуббер Бламп, дворф, що живе на пристанях Обердайна, просить допомогти наловити місцевих окунів Темного Узбережжя. Ворожі мурлоки, що нишпорять узбережжям, порушили роботу невеликих рибальських човнів містечка, тож Ґуббер застряг на березі й пропонує родинну вудку кожному, хто закине волосінь.",h="Ґуббер Бламп, дворф, що живе на пристанях Обердайна, просить допомогти наловити місцевих окунів Темного...",kw={"родина і вудка","ґуббер бламп","вудка родини блампів","окунь темного узбережжя","мурлоки","обердайн"},ang={["faction:Alliance"]="Обердайн — важливий порт Альянсу в Калімдорі, де народи з материка й нічні ельфи щодня співпрацюють проти прибережних небезпек на кшталт мурлоків.",["profession:Cooking"]="Окунь Темного Узбережжя — надійний і поживний улов на північному узбережжі Калімдору, основний інгредієнт для простих страв у прикордонних таборах.",["race:Dwarf"]="Зустріти побратима-дворфа, який палко віддався рибальству, а не підземному ковальству чи пивоварінню, — дивне нагадування про те, якими різними справами захоплюється ваш народ."},sec={{t="Дворф далеко від Айронфорджа",b="Ґуббер Бламп дуже пишається своїм родом і заявляє, що прізвище Бламп здавна означає мистецтво рибальства. Хоча Обердайн переважно заселяють нічні ельфи, дворфи й гноми облаштувалися на його пристанях і в гамірному порту. Замість довбати камінь Ґуббер днями вдивляється в імлисті води Прихованого Моря й прагне витягти місцеві щедроти."},{t="Навала мурлоків і окунь Темного Узбережжя",b="Окунь Темного Узбережжя — цінна прибережна риба: з нею можна приготувати будь-що, а на гачку вона славиться завзяттям. Зазвичай місцеві рибалки виходили на невеликих човнах у глибші води, щоб його наловити. Але агресивна навала прибережних мурлоків зупинила рух цивільних човнів. Боячись, що ці істоти пожирають усю місцеву рибу, Ґуббер шукає мандрівників, готових рибалити з берега."},{t="Спадщина Блампів",b="Тим, хто принесе йому добрий улов, Ґуббер віддає Вудку Родини Блампів. На його думку, кожен, хто зможе наловити гору завзятих окунів, дорівнює легендарним рибалкам його роду — зокрема бородатому кузенові Ґраунові Блампу з гострим запахом. Для дворфа з такими ексцентричними смаками віддати родинну вудку — найвищий знак поваги."}},faq={{q="Хто такий Ґуббер Бламп?",a="Ґуббер Бламп — дворф-рибалка, що працює на пристанях Обердайна на Темному Узбережжі. Він походить із гордої родини рибалок, навчає основ риболовлі й передає фірмові родинні вудки багатонадійним рибалкам.",al={"хто такий ґуббер","лор ґуббера бламп","рибалка-дворф оберін"}},{q="Чому з Обердайна не виходять рибальські човни?",a="Ворожі мурлоки заполонили великі ділянки узбережжя Темного Узбережжя. Через їхню агресію спускати на воду невеликі власні човни стало надто небезпечно, тож місцеві рибалки не відходять від причалів і мілин.",al={"чому немає човнів","рибальські човни темного узбережжя","біда човнів оберіна"}},{q="Що таке ґрупер Темного Узбережжя?",a="Це місцева морська риба, що водиться біля туманного узбережжя Темного Узбережжя. Рибалки цінують ґрупера і за те, як важко його витягти, і за те, що він годиться для багатьох ситних прибережних страв.",al={"що таке ґрупер","ґрупер темного узбережжя"}},{q="Хто така Ґраун Бламп?",a="Ґраун — кузина Ґуббера Бламп. За словами Ґуббера, вона має пишну бороду, пахне доволі різко й належить до найкращих рибалок, яких будь-коли дала їхня родина.",al={"ґраун бламп","кузен ґуббера"}},{q="Чому в містечку нічних ельфів на кшталт Обердайна є дворфи?",a="Після Третьої війни й укладення Альянсу дворфи й гноми з Айронфорджа перепливли море до Калімдору, щоб торгувати, налагоджувати морське сполучення й допомагати новим союзникам-нічним ельфам із портовим господарством.",al={"чому дворфи в оберіні","дворфи на темному узбережжі"}},{q="Що таке Вудка Родини Блампів?",a="Це міцна вудка, яку виготовляє й якою користується рід Блампів. Ґуббер дарує ці цінні вудки мандрівникам, які доведуть, що мають справжній рибальський хист на водах Темного Узбережжя.",al={"вудка блампів","вудка родини блампів","нагорода вудка ґуббера"}}},fp="31,291,26.389.0,41.419.0,16.375.0,20.227.0,50.222.0,28.188.0,19.171.0,57.223.0,38.183.0"}
P.entries["quest:1142"] = {n="Тлінне минає",s="Глибоко у ворожих хащах Рейзорфен Краулу вмирущий нічний ельф Гералат Фелловбрук шепоче своє останнє прохання шукачам пригод з Альянсу. Позбавлений сил і майже життя, він просить лише одного: повернути вкрадений амулет подружнього зв'язку його дружини й віднести його додому в Дарнасус разом зі звісткою про його смерть.",h="Глибоко у ворожих хащах Рейзорфен Краулу вмирущий нічний ельф Гералат Фелловбрук шепоче своє останнє прохання...",kw={"тлінне минає","гералат фелловбрук","трешала феллоубрук","рейзорфен краул","амулет","дарнасус","завдання"},ang={["faction:Alliance"]="Для поборників Альянсу, що вирушають у серце Пусток, де панує Орда, віднести останній знак Гералата до Дарнасуса — сумний обов'язок честі.",["race:Dwarf"]="Передсмертні слова Гералата вшановують хоробрість дворфа Лоунброу, що ризикнув життям, аби винести нагальне попередження з твердині шипогривів.",["race:NightElf"]="Нічні ельфи болісно відчувають, як один з їхнього роду гине самотнім і забутим серед диких будяків південних Пусток."},sec={{t="Останній подих серед колючок",b="Рейзорфен Краул — небезпечна твердиня, заполонена дикими шипогривами й темною магією, далеко від земель Альянсу. Серед цих підступних хащів лежить смертельно поранений Гералат Фелловбрук, і сили швидко полишають його. Останніми зусиллями він ледве шепоче уривчасті слова: хоробрий дворф на ім'я Лоунброу пішов уперед, щоб донести попередження Фалфінделові. А сам Гералат знає, що з Краулу живим уже не вийде."},{t="Амулет подружнього зв'язку",b="Перш ніж померти від ран, Гералат тримається за одне останнє бажання — повернути знак свого шлюбу. Амулет, що символізує його вічний зв'язок із дружиною Трешалою, зірвав із нього один із мерзенних нападників лігва. Він благає кожного мандрівника, який зупиниться біля нього, повернути амулет і віднести його через увесь Калімдор до Дарнасуса — щоб Трешала дізналася правду про його самотню смерть, а не чекала марно."},{t="Горе в Дарнасусі",b="Отримавши повернену реліквію в Дарнасусі, Трешала Феллоубрук приголомшена звісткою про смерть чоловіка. Зіткнувшись із жорстокістю світу, вона присягається, що праця Гералата не загине разом із ним. Лишившись оплакувати його в тихій самоті, вона бере на себе тягар його спадку, борючись із раптовим горем."}},faq={{q="Хто такий Гералат Фелловбрук?",a="Гералат Фелловбрук — нічний ельф з Альянсу, якого знаходять смертельно пораненим у Рейзорфен Краулі. Швидко згасаючи від ран, він просить перехожих шукачів пригод повернути вкрадений кулон заручин його дружини й передати звістку про його смерть у Дарнасус.",al={"хто такий гералат","гералат фелловбрук","вмираючий ельф рейзорфен"}},{q="Де знайти Гералата Фелловбрука?",a="Гералат у Рейзорфен Краулі — оплоті шипогривів, що заріс колючими хащами, на півдні Пусток.",al={"місце гералата","де гералат","де знайти гералата"}},{q="Хто такий Лоунброу?",a="Лоунброу — відважний дворф, якого Гералат згадує в останні хвилини. Схоже, Лоунброу послали з нагальним дорученням вибратися з колючих хащ і попередити Фалфіндела про небезпеку, що назріває в Краулі.",al={"дворф лоунброу","хто такий лоунброу","попередження лоунброу"}},{q="Хто така Трешала Феллоубрук?",a="Трешала — дружина Гералата, що живе в столиці нічних ельфів Дарнасусі. Вона отримує повернутий кулон і мусить пережити трагічну звістку про смерть чоловіка.",al={"трешала феллоубрук","хто така трешала","дружина гералата"}},{q="Що таке кулон заручин?",a="Кулон заручин — дорога пам'ятка, що знаменує шлюб Гералата й Трешали Феллоубрук. Його вкрали в Гералата нападники-шипогриви в Рейзорфен Краулі ще до його смерті.",al={"кулон заручин","що таке кулон","кулон зв'язку"}},{q="Як Трешала сприймає звістку?",a="Трешала вбита горем і нарікає на жорстокість світу. Попри глибоку скорботу, вона вирішує, що справу Гералата продовжить вона сама, і просить залишити її на самоті, щоб оплакати чоловіка.",al={"реакція трешали","що буде при доставці кулона"}}},fp="15,314,28.416.0,22.427.0,18.349.1,28.252.0,38.125.0,17.196.0,28.167.0,31.202.0,36.199.1"}
P.entries["quest:1143"] = {n="Вежа Альталакса",s="Це завдання — безпосередній штурм Атрікуса Нарассіна, давнього темного чаклуна, що засів на вершині Вежі Альталакса. За вказівкою Балтула Шедовстрайка посланець Альянсу мусить прорватися в зруйновану твердиню й стратити господаря кліки. Знищення Атрікуса завдає нищівного удару демонопоклонству, що отруює північ Темного Узбережжя.",h="Це завдання — безпосередній штурм Атрікуса Нарассіна, давнього темного чаклуна, що засів на вершині Вежі...",kw={"вежа альталакса","атрікус нарассін","балтул шедовстрайк","чорнокнижник","культ","темне узбережжя"},ang={["class:Warlock"]="Атрікус орудує могутньою демонічною магією з вершини Альталакса — смертельний приклад того, як неприборкане поклоніння Скверні накликає смертельну увагу.",["faction:Alliance"]="Убезпечити північ Темного Узбережжя від демонічних культистів украй важливо, щоб захистити шляхи Альянсу між Обердайном і землями за ним.",["race:NightElf"]="Двобій з Атрікусом Нарассіном — гірке нагадування про тайну й демонічну порчу, яка колись спустошила цивілізацію нічних ельфів."},sec={{t="Прорив на вершину",b="Вежа Альталакса, що здіймається на зруйнованих висотах півночі Темного Узбережжя, стала мерзенним осередком демонічних викликань. Балтул Шедовстрайк, який стежить за руїнами неподалік, вирішує, що діяти треба негайно. На вершині вежі живе Атрікус Нарассін — давній і грізний чорнокнижник із нічних ельфів, що править темними обрядами під її розбитим кам'яним дахом."},{t="Вирішальний удар",b="Атрікус оточує себе відданими чорнокнижниками й темною магією, куди смертоноснішою, ніж культисти, що патрулюють схили внизу. Щоб здолати верховного культиста, доведеться прорубатися крізь його найближче оточення й забрати його відрубану голову як доказ. Балтул зауважує, що демонічні сили колись можуть спробувати зібратися знову, але смерть Атрікуса позбавляє культ його керівного розуму й дає Темному Узбережжю дорогоцінний перепочинок."}},faq={{q="Хто такий Атрікус Нарассін?",a="Атрікус Нарассін — давній чорнокнижник із нічних ельфів, що командує культистами у Вежі Альталакса. Він керує темними закликаннями й демонічними обрядами, що заполонили руїни на півночі Темного Узбережжя.",al={"атрікус","хто такий атрікус","бос альталакса"}},{q="Де знайти Атрікуса Нарассіна?",a="Атрікус перебуває на самій верхівці Вежі Альталакса під охороною гурту досвідчених чорнокнижників і закликаних поплічників.",al={"де атрікус","місце атрікуса нарассіна","вершина альталакса"}},{q="Хто дає це завдання?",a="Доручення вбити Атрікуса дає Балтул Шедовстрайк — розвідник Альянсу, що отаборився біля підніжжя Вежі Альталакса.",al={"давець завдання","балтуле","балтуле шадоустрайк"}},{q="Хто такий Делґрен, згаданий у завданні?",a="Делґрен Очищувач — союзник Альянсу неподалік, який послав вас узгодити дії з Балтулом, щоб знищити демонічну кліку.",al={"делґрен","делґрен очищувач"}},{q="Що буде, коли Атрікуса переможено?",a="Балтул підтверджує, що смерть Атрікуса завдала нищівного удару демонічним справам у краї, хоча й попереджає, що темні сили згодом знову зберуться докупи.",al={"що після атрікуса","кінець вежі альталакса"}},{q="Чим Вежа Альталакса небезпечна для Темного Узбережжя?",a="Культисти й чорнокнижники, що засіли у вежі, практикують чаклунство скверни й закликають демонів у землі нічних ельфів, загрожуючи дикій природі й сусіднім поселенням.",al={"чим небезпечна вежа","загроза альталакса"}}},fp="22,361,20.399.0,17.412.1,25.202.0,37.123.0,21.125.0,38.130.0,40.158.1,53.165.0"}
P.entries["quest:1149"] = {n="Випробування віри",s="«Випробування віри» — духовний обряд, який проводить відлюдник Дорн Плейнстокер високо над дном каньйону Тисячі Голок. Він кидає виклик шукачам пригод з Орди: довести свою рішучість, зійшовши з хисткої дерев'яної дошки просто в прірву.",h="«Випробування віри» — духовний обряд, який проводить відлюдник Дорн Плейнстокер високо над дном каньйону...",kw={"випробування віри","дорн плейнстокер","стрибок","віра","тисяча голок","обряд посвяти"},ang={["class:Priest"]="Жерцям, що день у день плекають віру у вищі сили, доводиться втілити свої переконання в буквальну дію.",["faction:Horde"]="Ці випробування відбивають головні цінності, що згуртовують молоду Орду в Калімдорі: непохитну віру, стійкість у ворожому краї й незламну волю.",["race:Tauren"]="Для шу'гало обряди посвяти по священних місцях Калімдору — давня традиція, а випробування Дорна вимагає всім єством довіритися невидимому."},sec={{t="Міра духу",b="Дорн Плейнстокер живе на відлюдному оглядовому місці над вивітреними шпилями Тисячі Голок і розмірковує про те, з чого складається жива істота: розум, тіло й дух. Не покладаючись лише на прості племінні традиції, Дорн проводить власні випробування, щоб зміряти, що насправді криється в шукачеві пригод. Він переконаний: віра буває різна, але суть у тому, щоб мати мужність повірити в щось так сильно, аби поставити на кін власне життя."},{t="Стрибок у порожнечу",b="Випробування оманливо просте. Посвячуваного переносять на стрімку вершину однієї з високих кам'яних голок, де він стоїть на вивітрених дерев'яних дошках, підвішених над порожнечею. Щоб пройти випробування, треба перемогти інстинкт самозбереження й ступити в безодню без жодної відчутної гарантії, що виживеш. Тих, хто стрибає, підхоплюють магічні чи духовні сили й повертають у безпечне місце: вони довели, що їхній дух досить загартований, аби зустріти непередбачені випробування попереду."}},faq={{q="Хто такий Дорн Плейнстокер?",a="Дорн Плейнстокер — таурен-самітник, що живе у віддаленому таборі на скелі над Тисячею Голок. Він — духовний екзаменатор, що шукає шукачів пригод з Орди, аби випробувати різні сторони їхньої смертної природи: віру, витривалість і силу.",al={"дорн плейнстокер","хто дає випробування віри","давець завдання тисяча голок"}},{q="Чи вб'ю я себе, стрибнувши з дошки?",a="Ні. Хоч падіння з кам'яного шпиля й здається неминуче смертельним, випробування — це акт довіри. Щойно ви ступаєте з дерев'яних дощок, магічний захист підхоплює вас у падінні й переносить просто назад до печери Дорна Плейнстокера цілим і неушкодженим.",al={"чи я помру стрибнувши","чи вб'є падіння","чи небезпечне випробування віри"}},{q="Що буде, коли пройдеш «Випробування віри»?",a="Довести віру — лише перший обряд у низці випробувань Дорна. Щойно він визнає ваш дух сприйнятливим, Дорн одразу перевіряє вашу фізичну стійкість у «Випробуванні витривалості».",al={"що після випробування віри","ланцюжок випробування віри","наступне завдання дорна"}},{q="Чому Дорн каже, що поразка означає усвідомити безмежність Нижнього Світу?",a="Це похмуре філософське нагадування Дорна про смертність. На його думку, ті, кому бракує внутрішнього вогню, щоб цілком віддатися випробуванню, ризикують утратити життя — і душу — в безкінечній порожнечі поза світом живих.",al={"безмежність нижнього світу","цитата дорна про нижній світ"}},{q="Чи можуть шукачі пригод з Альянсу пройти це випробування?",a="Ні. Дорн Плейнстокер ділиться мудрістю й духовними настановами лише з поборниками Орди, що мандрують небезпечними каньйонами південного Калімдору.",al={"чи лише орда може","чи альянс може виконати випробування віри"}},{q="Де відбувається «Випробування віри»?",a="Випробування починається в таборі Дорна серед стін каньйону Тисячі Голок, звідки магічний шлях веде на запаморочливий край відокремленого кам'яного шпиля, що стирчить над дном ущелини.",al={"місце випробування віри","де дошка тисячі голок"}}},fp="13,255,23.490.0,22.488.1,25.251.0,35.246.1,45.190.1,69.219.0,40.159.0,40.181.0"}
P.entries["quest:115"] = {n="Тіньова магія",s="Тіньова магія — відчайдушне завдання від Маршала Марріса: підірвати темне чаклунство, на яке спирається вторгнення Блекрок у Редрідж. Заклиначі тіні Блекрок принесли на поле бою опівнічні сфери, заражені демонічною скверною, і обернули темну енергію проти змучених захисників Лейкширу. Здобути й знищити ці прокляті реліквії вкрай важливо, щоб утримати оборону містечка.",h="Тіньова магія — відчайдушне завдання від Маршала Марріса: підірвати темне чаклунство, на яке спирається...",kw={"тіньова магія","опівнічна сфера","заклиначі тіні","блекрок","маршал марріс","лейкшир"},ang={["class:Paladin"]="Протистояти заклиначам тіні й забирати заражені демонами реліквії — пряме виконання священного обов'язку очищати світ смертних від демонічної скверни.",["class:Warlock"]="Опівнічні сфери показують, що клан Блекрок досі не відірвався від своїх коренів у скверні, і дають чорнокнижникам змогу побачити неприборкане демонічне чаклунство орківських заклиначів.",["faction:Alliance"]="Лейкшир на межі падіння, а підкріплення зі Стормвінда майже немає; позбавити клан Блекрок їхньої темної «артилерії» — питання виживання всього краю."},sec={{t="Зловісний арсенал",b="Груба сила завжди була відмітною рисою клану Блекрок, та нинішні вторгнення в Гори Редріджу несуть значно підступнішу загрозу. Загарбники поповнили свої лави заклиначами тіні, що володіють темними силами. Ці заклиначі покладаються не лише на чаклунство: вони спрямовують енергію скверни й тіні крізь заражені демонами артефакти, відомі як опівнічні сфери. Ці артефакти завдали місцевому ополченню страшних втрат і ще більше схилили й без того відчайдушну війну на бік загарбників."},{t="Стримати скверну",b="Marshal Marris, coordinating Lakeshire's strained defense from the town center, understands that ordinary steel cannot easily overcome dark relics. Allowing the Blackrock orcs to retain their midnight orbs risks the complete collapse of Redridge's eastern borders. By ordering adventurers to slay the shadowcasters and seize the orbs, Marris seeks not to repurpose this dangerous magic, but to have the demonic relics destroyed."}},faq={{q="Що таке опівнічні сфери?",a="Опівнічні сфери — осквернені демонами провідники сили, які носять тіньові заклиначі Блекрок. Вони зосереджують темну магію, щоб завдавати нищівних ударів смертним захисникам Редріджу.",al={"опівнічні сфери","що таке опівнічна сфера","що роблять сфери"}},{q="Навіщо Маршалові Маррісу ці сфери?",a="Маршал Марріс хоче цілком прибрати сфери з поля бою, щоб підрізати наступальну силу тіньових заклиначів Блекрок. Він має намір безпечно позбутися цих демонічних реліквій і знищити їх.",al={"навіщо маршалу маррісу сфери","збір сфер","план марріса"}},{q="Хто такі тіньові заклиначі Блекрок?",a="Це чарівники серед орків Блекрок, що практикують магію тіні, просякнуту скверною: вони забезпечують магічну підтримку й накладають прокляття на допомогу грубим воїнам клану.",al={"тіньові заклиначі блекрок","хто користується магією тіні","заклиначі блекрок"}},{q="Де трапляються тіньові заклиначі?",a="Тіньові заклиначі Блекрок розміщені в таборах і укріплених позиціях клану Блекрок по всій північно-східній частині Гір Редріджу.",al={"де заклиначі","місця тіньових заклиначів","табори заклиначів блекрок"}},{q="Чи Лейкшир вивчатиме чи використовуватиме сфери?",a="Ні. Маршал Марріс вважає їх небезпечними й оскверненими демонами і твердо каже, що світові без них буде краще. Його прямий намір — негайно їх знищити.",al={"чи лейкшир використає сфери","чи може альянс використати сфери","чи корисні сфери"}},{q="Чому в Редріджі з'являється демонічна магія?",a="Клан Блекрок давно знається з темними сутностями й сутностями скверни — ще з часів Старої Орди. Його чарівники й далі користуються демонічними реліквіями й магією тіні, щоб підкріпити свої завоювання.",al={"чому демонічна магія в редріджі","скверна блекрок","скверна в редріджі"}}},fp="12,378,18.523.0,20.428.0,23.169.0,40.202.0,36.166.0,34.139.0,37.176.0,43.208.0"}
P.entries["quest:1150"] = {n="Випробування витривалості",s="«Випробування витривалості» — другий обряд у низці духовних випробувань, які проводить Дорн Плейнстокер у Тисячі Голок. Довівши мужність духу, шукачі пригод з Орди мають випробувати свою фізичну витривалість до краю: проникнути в Лігво Диких Пер і виманити люту ватажку гарпій, Ґренку Бладскріч.",h="«Випробування витривалості» — другий обряд у низці духовних випробувань, які проводить Дорн Плейнстокер у...",kw={"випробування витривалості","дорн плейнстокер","лігво диких пер","ґренка бладскріч","гарпії","верескливий каньйон"},ang={["faction:Horde"]="Дорн пропонує ці випробування всім расам Орди, бо вірить, що молоді воїни з кожного племені мусять загартуватися в негодах, перш ніж зустрітися з небезпеками Калімдору.",["race:Tauren"]="Для мандрівників-тауренів випробування Дорна Плейнстокера відбивають традиційні обряди посвяти й перевіряють, чи відповідає фізична витривалість посвячуваного духовному проводу Земної Матері."},sec={{t="Випробування тіла",b="Дорн Плейнстокер, що живе у Вивітреному Закутку, вважає своїм обов'язком загартовувати молодих воїнів, перш ніж вони вийдуть у ширший і суворіший світ. Перший обряд довів, що мандрівник має непохитну віру й міцні нерви, а це випробування перевіряє фізичну стійкість. За Дорновою філософією, справжня готовність вимагає гармонії духовної відданості, розумової дисципліни й чистої витривалості, щоб вистояти під затяжним жорстоким натиском."},{t="Вторгнення в Лігво Диких Пер",b="Ареною для цього випробування обрано Лігво Диких Пер — підступну печеру у Верескливому Каньйоні на захід від Застави Вільного Вітру. Вона кишить ворожими гарпіями й смертельно небезпечна для самотніх мандрівників. Щоб пройти випробування, треба прорубатися глибоко в підземне гніздовище, зіпсувати зібрані гарпіями припаси й витримати люту відплату зграї, доки на бій не вийде сама матріарха — Ґренка Бладскріч."}},faq={{q="Хто дає «Випробування витривалості»?",a="Завдання дає Дорн Плейнстокер — таурен-старійшина, що перебуває в Обвітреному Закутку серед кручь каньйону Тисячі Голок.",al={"хто дає випробування витривалості","давець випробування витривалості","завдання дорна"}},{q="Де розташоване Лігво Диких Пер?",a="Лігво Диких Пер лежить високо на південних стінах каньйону Тисячі Голок, на захід від Застави Вільного Вітру. Мандрівникам треба піднятися звивистою стежкою через Вискливий Каньйон до схилу, що веде до входу в печеру.",al={"місце лігва диких пер","де печера гарпій","рампа вереску каньйону"}},{q="Як викликати Ґренку Бладскріч?",a="Ґренка Бладскріч з'являється, коли ви проб'єтеся до найглибших залів Лігва Диких Пер і сплюндруєте запаси їжі й припасів, які там склали гарпії, — так ви змусите її боронити своє гніздо.",al={"як викликати ґренку","викликати ґренку бладскріч","знайти ґренку"}},{q="Що йде після «Випробування витривалості»?",a="Коли ви повертаєте Дорнові Плейнстокеру відтятий кіготь Ґренки, ви доводите свою фізичну витривалість, і він посилає вас на наступне випробування — «Випробування сили».",al={"що після випробування витривалості","наступне після витривалості","наступне випробування дорна"}},{q="Чому Дорн випробовує шукачів пригод, які не є тауренами?",a="Дорн вважає своїм покликанням наставляти всю молодь Орди, незалежно від раси чи племені. Неперевірена гординя, на його думку, у великому світі — смертний вирок, тож кожен воїн має довести, що готовий тілом, розумом і духом.",al={"чому дорн допомагає не тауренам","філософія дорна","випробування тауренів для інших рас"}},{q="Яке випробування було перед цим?",a="Перш ніж перевіряти витривалість тіла, Дорн вимагає пройти «Випробування віри» — небезпечний стрибок відданості, що перевіряє, чи не похитнеться дух шукача пригод перед страхом.",al={"попереднє випробування","завдання перед витривалістю","перше випробування"}}},fp="17,345,16.431.0,31.455.0,32.132.0,34.208.0,38.210.0,39.169.0,49.240.0,35.197.0"}
P.entries["quest:1151"] = {n="Випробування сили",s="«Випробування сили» — третє випробування, яке проводить таурен-містик Дорн Плейнстокер у Тисячі Голок. Щоб довести свою фізичну міць, герої Орди мають вистежити Рок'Аліма Товкача — прадавнього кам'яного елементаля, що вільно блукає краєм, — і принести рештки його розтрощеного тіла.",h="«Випробування сили» — третє випробування, яке проводить таурен-містик Дорн Плейнстокер у Тисячі Голок.",kw={"випробування сили","рок'алім товкач","дорн плейнстокер","елементаль","древні боги","тисяча голок"},ang={["class:Shaman"]="Шамани бачать у Рок'Алімі не просто перешкоду, а небезпечне, нічим не скуте втілення землі, чия непокора порушує місцеву рівновагу духів.",["faction:Horde"]="Пройшовши обряди Вивітреного Закутка, ви здобуваєте повагу старійшин Тандер Блафа й утверджуєте свою славу по всьому Калімдору.",["race:Tauren"]="Для прочан-тауренів зійтися з неприборканим духом каменю — традиційне випробування гармонії й фізичної волі, що доводить здатність мисливця витримати й подолати найсуворіші сили Земної Матері."},sec={{t="Рештки Чорної Імперії",b="Колись давно, за панування Древніх Богів, первісні елементалі вкривали поверхню світу, служачи своїм темним володарям. Коли ці прадавні сутності скинули й запечатали під землею, духи стихій утратили зв'язок із цим світом і здебільшого зникли з тілесного буття — хіба що їх прив'язує й викликає сучасне чародійство. Та кілька істот виявилися досить упертими й могутніми, щоб лишатися в Азероті без жодних магічних якорів. Рок'Алім Товкач — одна з таких реліквій: він блукає посушливими каньйонами Тисячі Голок, мов живе відлуння тієї первісної доби."},{t="Товкач Тисячі Голок",b="Своє прізвисько Рок'Алім дістав від місцевих кланів кентаврів — за оглушливий гуркіт, схожий на землетрус, із яким його кам'яні кулаки б'ють об дно каньйону. Кожного, кому забракне розуму чи вистачить зухвалості опинитися на його шляху, він товче на порох. Оскільки Рок'Алім — утілення первісної, неприборканої фізичної маси, Дорн Плейнстокер посилає посвячуваних розтрощити цю істоту, щоб прямо зміряти їхній бойовий дух, і вимагає уламків кам'яного серця елементаля як доказ перемоги."}},faq={{q="Де починається й закінчується це завдання?",a="Завдання дає й приймає Дорн Плейнстокер — таурен-старійшина з Обвітреного Закутка, відлюдного табору в каньйоні високо серед шпилів Тисячі Голок.",al={"де починається завдання","де здати","місце дорна"}},{q="Хто такий Рок'Алім Товкач?",a="Рок'Алім — прадавній кам'яний елементаль, що живе в Калімдорі ще з доби Древніх Богів. На відміну від нинішніх закликаних елементалів, він має досить власної сили, щоб цілком самостійно лишатися у фізичній подобі на Азероті.",al={"хто такий рок'алім","що за моб рок'алім","лор елементаля"}},{q="Чому кентаври прозвали його Товкачем?",a="Племена кентаврів у каньйоні прозвали його Товкачем через громові ударні хвилі, які розходяться від його кам'яних кулаків, коли він трощить усе на своєму шляху.",al={"чому кентаври звуть товкачем","прізвисько товкач"}},{q="Де в каньйоні знайти Рок'Аліма?",a="Рок'Алім блукає північно-західною частиною Тисячі Голок, зазвичай обходячи відкриту місцевість на південь від головної дороги, що перетинає дно каньйону.",al={"де рок'алім","поява рок'аліма"}},{q="Яке місце це завдання посідає в ланцюжку випробувань?",a="«Випробування сили» — третє в ланцюжку. Воно йде після «Випробування віри» й «Випробування витривалості» і просто перед останнім — «Випробуванням знань».",al={"порядок ланцюжка випробувань","що далі","що перед цим"}},{q="Чому Дорн вимагає вбити елементаля, а не звіра чи ворога?",a="Дорн обирає Рок'Аліма, бо цей елементаль — чисте втілення живого каменю й незламної первісної сили. Подолавши такого супротивника, ви доводите фізичну перевагу над самою сирою, непохитною землею.",al={"чому вбивати елементаля","мета випробування сили"}}},fp="16,300,28.589.0,31.471.0,36.178.0,29.226.0,42.161.0,42.156.0,59.162.0,75.211.0"}
P.entries["quest:1152"] = {n="Випробування знань",s="Після випробувань віри, витривалості й сили в Тисячі Голок Дорн Плейнстокер відсилає героїв Орди на північ, до Гір Кам'яного Кігтя. Там на них чекає мудрий шаман Брауґ Дімспіріт, щоб провести Випробування знань. Це випробування переносить увагу з фізичної стійкості на розуміння глибокої історії світу й страждань, що його охопили.",h="Після випробувань віри, витривалості й сили в Тисячі Голок Дорн Плейнстокер відсилає героїв Орди на північ...",kw={"випробування знань","брауґ дімспіріт","дорн плейнстокер","стежка глибокого кігтя","історія азероту","шаман"},ang={["class:Shaman"]="Брауґ Дімспіріт уособлює шаманський світогляд, що читає страждання землі крізь безрозсудні вчинки смертних — від гоблінського визиску до давньої ельфійської відокремленості.",["faction:Horde"]="Випробування Брауґа змушує героїв Орди чесно поміркувати про славу власних союзників і нагадує, що ні орки, ні Відступники не єдині винні в бідах цієї землі.",["race:Tauren"]="Ці випробування втілюють традиційну тауренську філософію, що ставить духовну гармонію й розуміння історії вище за сліпу жагу крові."},sec={{t="Від віри до знань",b="У захищеному прихистку Вивітреного Закутка Дорн Плейнстокер проводить посвячуваних крізь суворі випробування, що перевіряють їхню духовну переконаність, фізичну витривалість і бойову вправність. Та сама лише груба сила й сліпа віра ще не роблять справжнього героя Орди. Дорн визнає межі своїх можливостей як наставника й посилає тих, хто довів свою вартість, до Гір Кам'яного Кігтя, де старий шаман може випробувати їхній розум і знання світу."},{t="Дорога до Кам'яного Кігтя",b="Шлях веде мандрівників на північ через сухі чагарники Пусток у кручі Гір Кам'яного Кігтя. Високо в горах, біля входу на Стежку Глибокого Кігтя — печеру, що прорізає скелю в бік Ашенвалю, — стоїть відлюдна оселя Брауґа Дімспіріта. Він пильнує неспокійне прикордоння, де гоблінські лісорозробки плюндрують ліси, а ворожі нічні ельфи запекло боронять кордони предків."},{t="Ширший погляд",b="Зустрівшись із Брауґом, герой збагне справжню мету випробування. Брауґ не вимагає сліпої гордості за свою фракцію — натомість він розмірковує про трагічний стан Азероту. Він зауважує, що хоч орків і Відступників безупинно звинувачують у війнах і скверні, майже кожен народ має свою частку провини за біди цієї землі. Гобліни валять прадавні ліси, а нічні ельфи плекають глибоку недовіру до молодших рас. Випробування знань вимагає від героя дивитися далі за сьогоднішню ворожнечу й осягнути ширшу історію пораненого світу."}},faq={{q="Що таке «Випробування знань»?",a="Це навчальне випробування в межах ширшого обряду посвяти, який уклали старійшини тауренів. Посвячувані мають довести, що мають не лише фізичну силу й віру, а й знання історії та розуміння спільного минулого Азероту.",al={"що таке випробування знань","про що це завдання"}},{q="Де знайти Брауґа Дімспіріта?",a="Брауґ Дімспіріт перебуває в Горах Кам'яного Кігтя, біля Кручі Вітрорізу, просто біля входу в печеру Стежки Глибокого Кігтя, що з'єднує Гори Кам'яного Кігтя з Ашенвалем.",al={"місце брауґа дімспіріта","де брауґ"}},{q="Чому Дорн Плейнстокер посилає вас деінде?",a="Дорн проводить випробування віри, витривалості й сили в Тисячі Голок, але визнає, що навчати знань про світ — не його царина. Гідних посвячуваних він спрямовує до Брауґа — шамана, якому вистачає мудрості, щоб випробувати розум.",al={"чому дорн посилає деінде","чому стоунталон"}},{q="Яких загроз варто остерігатися дорогою?",a="Дорн особливо застерігає, що на прикордонні біля Ашенвалю й Гір Кам'яного Кігтя никають нічні ельфи, які вважають присутність Орди вторгненням. До того ж довкола Кручі Вітрорізу кипить непередбачувана гоблінська лісозаготівля.",al={"небезпеки на шляху до брауґа","небезпеки стежки глибокого кігтя"}},{q="Як Брауґ Дімспіріт дивиться на конфлікти світу?",a="Брауґ вважає, що за страждання світу відповідальні всі смертні раси. Хоча суперники часто демонізують орків і Відступників, він наголошує, що гоблінська жадібність і пиха нічних ельфів завдали не меншої шкоди і Калімдору, і Лордерону.",al={"філософія брауґа дімспіріта","у що вірить брауґ"}},{q="Що таке Стежка Глибокого Кігтя?",a="Стежка Глибокого Кігтя — помітна система гірських тунелів, що з'єднує Кручу Вітрорізу в Горах Кам'яного Кігтя з давніми лісовими межами південного Ашенвалю.",al={"що таке стежка глибокого кігтя","печера глибокого кігтя"}}},fp="12,353,18.452.0,22.411.0,21.539.1,25.238.0,33.169.0,41.239.0,54.226.0,56.254.0,27.160.0"}
P.entries["quest:1153"] = {n="Новий зразок руди",s="Таттернак Стілфордж у Таборі Тауражо почув чутки про незвичний мінеральний поклад, шматки якого носять кобольди далеко на півдні. Сповнений рішучості задовольнити вимогу Вождя Тралла щодо міцнішої зброї, він посилає шукачів пригод з Орди в Тисячу Голок по необроблений зразок руди для випробувань.",h="Таттернак Стілфордж у Таборі Тауражо почув чутки про незвичний мінеральний поклад, шматки якого носять...",kw={"новий зразок руди","таттернак стілфордж","табір тауражо","тисяча голок","кобольди","руда"},ang={["faction:Horde"]="Табір Тауражо — важливий південний оплот, і кожен принесений матеріал прямо допомагає військовій готовності Вождя.",["profession:Blacksmithing"]="Для ковалів Орди нові, незвичні поклади металу — запорука того, що прикордоння буде озброєне проти загроз довкола.",["profession:Mining"]="Рудознавці знають ціну сирим, неочищеним жилам, які розкопують підземні істоти в недосліджених південних каньйонах."},sec={{t="Ковальське честолюбство",b="Працюючи в запорошеній заставі Табору Тауражо, коваль Таттернак Стілфордж перебуває під пильним наглядом Оргріммара. Він уже постачав зброю, перекувану з кентаврського озброєння, але досі прагне довести свою майстерність Вождеві Траллу. Коли мандрівники відмовилися продати йому дивний шматок руди, знайдений у вбитого кобольда на півдні, Таттернак сприйняв відмову як образу і для свого ремесла, і для Орди."},{t="Вилазка в Тисячу Голок",b="Це завдання веде розвідників Орди з рівних степів південних Пусток у високі лабіринти каньйонів Тисячі Голок. Там підземні шкідники риють ходи в скелях і урвищах. Відбираючи шматки неочищеного мінералу просто в місцевих кобольдів-копачів, шукачі пригод повертаються з сировиною, потрібною Таттернакові, щоб з'ясувати, чи можна викувати з цього нового каменю зброю, гідну воєнних зусиль Тралла."}},faq={{q="Хто такий Таттернак Стілфордж?",a="Таттернак Стілфордж — орк-зброяр із Табору Тауражо на півдні Пусток. Він віддано кує зброю для оборони прикордоння Орди й постійно шукає нових матеріалів, щоб вразити Вождя Тралла.",al={"таттернак","коваль табору таурахо","хто такий таттернак"}},{q="Звідки цей зразок руди?",a="Неочищений зразок руди носять кобольди, що живуть у звивистих каньйонах Тисячі Голок, просто на південь від Великого Підйомника на межі з Пустками.",al={"звідки руда","місце руди","руда тисячі голок"}},{q="Чому Таттернак сердиться на перехожих мандрівників?",a="Гурт мандрівників, що прийшли з півдня, показав Таттернакові дивний шматок мінералу, забраний з убитого кобольда, але відмовився йому продати. Таттернак вважав, що притримувати такі важливі матеріали — непатріотична образа для Вождя, і обізвав їх боягузами.",al={"чому таттернак сердитий","руда мандрівників","таттернак проти мандрівників"}},{q="Що Таттернак зробить із рудою?",a="Він хоче дослідити її металургійні властивості й перевірити міцність. Якщо метал виявиться досить міцним, він збирається викувати з нього дослідну зброю й піднести її просто Вождеві Траллу в Оргріммарі.",al={"що таттернак зробить з рудою","навіщо йому руда"}},{q="Що треба виконати перед цим дорученням?",a="Перш ніж братися за це доручення, треба виконати завдання «Зброя на вибір», у якому ви збираєте певну зброю з різних племен кентаврів, що загрожують Таборові Тауражо, щоб довести, що місцеве озброєння можна пустити в діло.",al={"попередній завдання","передумова","зброя на вибір"}},{q="Чому кобольди в Тисячі Голок носять цю руду?",a="Кобольди — невгамовні копачі й рудокопи, що невпинно риють ходи крізь скелі й підземні жили. У Тисячі Голок їхнє копання відкрило незвичні підземні поклади, яких мешканці поверхні майже не торкалися.",al={"чому кобольди носять руду","копальні кобольдів"}}},fp="16,283,18.447.0,29.418.0,29.231.0,37.169.0,49.265.0,37.211.0,53.208.0,54.227.0"}
P.entries["quest:1154"] = {n="Випробування знань",s="«Випробування знань» призначає Брауґ Дімспіріт біля входу на Стежку Глибокого Кігтя, і перевіряє воно не фізичну витривалість шукача пригод з Орди, а його розум. Щоб пройти його, треба спуститися глибоко в примарні підземні притулки Ашенвалю, знайти прадавній том з історії драконів і вивчити його зміст, перш ніж відповідати на запитання.",h="«Випробування знань» призначає Брауґ Дімспіріт біля входу на Стежку Глибокого Кігтя, і перевіряє воно не...",kw={"випробування знань","брауґ дімспіріт","спадок аспектів","дор'даніл","стежка глибокого кігтя","детвінг"},ang={["class:Druid"]="Спустившись у Притулок Дор'Даніл, мандрівники-друїди стають віч-на-віч із трагедією спотворених і вбитих побратимів — нічних ельфів, що колись спали в єднанні зі Смарагдовим Сном.",["faction:Horde"]="Це випробування відбиває потребу Орди у воїнах, які розуміють глибоку історію Калімдору й здатні пройти небезпечними ельфійськими руїнами Ашенвалю, не скорившись невіданню."},sec={{t="Поворот у випробуваннях",b="Тих, хто довів свою фізичну витривалість і непохитну віру на солончаках і плато Тисячі Голок, Дорн Плейнстокер відсилає на північ, до Брауґа Дімспіріта в Горах Кам'яного Кігтя. Брауґ, що стоїть біля входу на Стежку Глибокого Кігтя, зневажливо називає попередні випробування простими фізичними вправами. Щоб гідно служити Орді, шукачеві пригод потрібен гострий і дисциплінований розум, готовий осягати давню історію, а не лише валити звірів."},{t="Тіні Дор'Даніла",b="Брауґ скеровує претендентів крізь Стежку Глибокого Кігтя в лісисті краї південного Ашенвалю. Там, під лісовим пологом на південь від Застави Розщепленого Дерева, сховано Притулок Дор'Даніл. Цей підземний прихисток — небезпечні руїни, де блукають духи полеглих друїдів з нічних ельфів і лютують істоти, що їх вирізали. На кам'яному постаменті глибоко в нижніх залах лежить нагорода — «Спадок Аспектів», рідкісний рукопис про давнє створення великих Аспектів-драконів і про їхнє спотворення."},{t="Учися — або страждай",b="Здобути том — лише половина Брауґового випробування. Перш ніж віддати книгу, шукач мусить запам'ятати її науку. Щойно книгу принесено, Брауґ забирає її й одразу перевіряє, що шукач запам'ятав про захисників, створених титанами, і про нищівну зраду, що породила Детвінга. Хто не вивчив або вгадує невдало, того раптово відкидає через увесь Калімдор до Табору Тауражо на півдні Пусток, і йому доводиться з ганьбою чвалати назад до Гір Кам'яного Кігтя."}},faq={{q="Хто такий Брауґ Дімспіріт?",a="Брауґ Дімспіріт — таурен-старійшина й шаман, що стоїть біля входу на Стежку Глибокого Кігтя в Горах Кам'яного Кігтя. Він — екзаменатор, що продовжує випробування Дорна Плейнстокера й перевіряє, чи мають поборники Орди розум і знання, які доповнять їхню сиру бойову вправність.",al={"брауґ дімспіріт","хто дає випробування знань","давець у стоунталоні"}},{q="Де лежить книга «Спадок Аспектів»?",a="Книга лежить у Курганному Лігві Дор'Даніл у південному Ашенвалі, майже просто на південь від Застави Розщепленого Дерева. Вона на кам'яному постаменті на центральному майданчику в підземних глибинах курганів.",al={"де книга спадок аспектів","місце книги","місце книги дор'даніл"}},{q="Що таїться в Курганному Лігві Дор'Даніл?",a="Колись курганне лігво було святилищем друїдів із нічних ельфів, але ці печери спіткала трагедія. Тепер їх заполонили неприкаяні духи загиблих друїдів і смертоносні загарбники, що їх вирізали, — це смертельний лабіринт для кожного непроханого гостя.",al={"що в курганному лігві дор'даніл","вороги дор'даніл","хто охороняє книгу"}},{q="Чому Брауґ змушує мене прочитати книгу, перш ніж здати її?",a="Брауґ забирає книгу, щойно ви її приносите, і перевіряє, що ви запам'ятали. Він чекає, що ви вивчите її заздалегідь, бо це випробування перевіряє знання, а не просто вміння принести річ.",al={"навіщо читати спадок аспектів","вікторина випробування знань","що буде якщо провалю питання"}},{q="Яке місце це завдання посідає в ширшій низці випробувань?",a="Це випробування йде після «Випробування віри», яке починає Дорн Плейнстокер в Обвітреному Закутку в Тисячі Голок. Якщо Дорн перевіряв вашу відвагу й уміння вижити попри смертельні небезпеки, то Брауґ оцінює ваше знання переказів і історії.",al={"ланцюжок випробування віри","що перед випробуванням знань","випробування дорна"}},{q="Про що книга «Спадок Аспектів»?",a="Рукопис оповідає міфічну історію того, як титани наділили силою п'ятьох великих Аспектів драконів, щоб ті оберігали Азерот. Головне — у ній ідеться про падіння Нелтаріона Хранителя Землі й про те, як він перетворився на потворного руйнівника, відомого як Детвінг.",al={"про що книга спадок аспектів","історія книги","лор книги"}}},fp="12,326,21.528.0,24.518.0,15.477.1,23.306.0,48.223.0,39.236.0,58.180.1,54.232.0,56.260.0"}
P.entries["quest:1159"] = {n="Випробування знань",s="Цей етап Випробування знань посилає шукачів пригод з Орди через Велике Море до руїн Лордерона. Відповівши на першу загадку Брауґа Дімспіріта в Горах Кам'яного Кігтя, ви маєте розшукати колишнього вченого-людину серед Відступників в Андерсіті.",h="Цей етап Випробування знань посилає шукачів пригод з Орди через Велике Море до руїн Лордерона.",kw={"випробування знань","парквал фінталлас","андерсіті","апотекаріум","брауґ дімспіріт","лордерон"},ang={["faction:Horde"]="Це завдання показує співпрацю між континентами, що скріплює новостворену Орду: тауренські шукачі мудрості стають пліч-о-пліч із похмурими архіваріусами Лордерона.",["race:Tauren"]="Для посвячуваного таурена покинути відкриті рівнини й високі столові гори Калімдору й пробиратися отруйними, тісними стоками Андерсіті — випробування не менше культурне, ніж історичне.",["race:Undead"]="Зустріч із Парквалом показує: попри тлін і нежиття, учені-Відступники на кшталт нього зберегли величезні наукові традиції та записи загиблого королівства Лордерон."},sec={{t="Союз учених",b="Коли ви довели свою вартість і розібралися в історії Аспектів-драконів, записаній у «Спадку Аспектів», Брауґ Дімспіріт визнає, що його власні знання мають межі. Не обмежуючи випробування Калімдором, Брауґ показує, як широко й несподівано сягають зв'язки Орди: він скеровує вас до столиці нежиті під руїнами Лордерона."},{t="Недовірливий історик",b="У вогких коридорах Апотекаріуму мешкає Парквал Фінталлас. Колись шанований літописець північних королівств, він зберіг жагу знань, яка пережила і Погибель, і його перетворення на одного з Відступників. Коли перед ним постає чужинець, що заявляє, ніби пройшов духовні й фізичні випробування Тисячі Голок, Парквал не вірить, що ви щось більше, ніж найманець, який шукає наживи, — доки ви не доведете йому свою вартість особисто."}},faq={{q="Чому випробування тауренів посилає мене аж до Андерсіті?",a="Брауґ Дімспіріт визнає, що справжнє знання переказів не обмежується історією Калімдору. Він посилає вас до Парквала Фінталласа — знаного вченого-людини, чиї знання пережили падіння Лордерона в нежиття, — щоб перевірити ваше розуміння ширшої історії світу.",al={"чому до андерсіті","чому лордерон","брауґ посилає до нежиті"}},{q="Де саме знайти Парквала Фінталласа?",a="Парквал Фінталлас в Андерсіті: він стоїть на південному мосту в кварталі Апотекаріуму.",al={"де парквал","місце парквала","знайти фінталласа"}},{q="Ким був Парквал Фінталлас за життя?",a="За життя Парквал Фінталлас був знаним істориком-людиною в королівстві Лордерон. Скорившись Чумі нежиття й приєднавшись до Відступників Сильвани, він не покинув наукових пошуків, лише звернув свій розум на інші, темніші питання.",al={"минуле парквала","хто такий парквал","історія фінталласа"}},{q="Чому Парквал не вірить, що мене послав Брауґ?",a="Парквал глибоко недовірливий до чужинців. Йому здається неймовірним, що звичайний шукач пригод міг стрибнути зі шпилів Тисячі Голок, здолати прадавніх елементалів і здобути давні реліквії, тож він припускає, що ви просто наслухалися чуток у таверні.",al={"чому парквал не вірить","парквал грубий","реакція парквала"}},{q="Частиною якого більшого випробування є це завдання?",a="Це завдання — середина ланцюжка «Випробування знань», який, своєю чергою, виріс із випробування, що його розпочав Дорн Плейнстокер в Обвітреному Закутку. Воно перевіряє, чи має посвячуваний не лише бойову вправність і відвагу, а й розум та знання історії, гідні поборника Орди.",al={"який це ланцюжок","ланцюжок випробування віри","що таке випробування знань"}},{q="Що далі, коли дістанешся до Парквала?",a="Перш ніж Парквал зволить загадати вам свою історичну загадку, він вимагає виконати для нього доручення у Східних Королівствах, щоб переконатися, що ви справді той вправний герой, яким вас змальовує Брауґ.",al={"що далі після парквала","наступне завдання після андерсіті","після розмови з фінталласом"}}},fp="12,263,20.359.0,23.461.0,57.270.0,43.120.0,34.266.0,42.255.0,40.295.0,39.206.0"}
P.entries["quest:116"] = {n="Сухі часи",s="Сухі часи — завдання від Шинкаря Деніелса з Лейкширу: поповнити запаси трунків у міській корчмі під час облоги, що не вщухає. Вторгнення орків Блекрок перерізало торгові шляхи, тож Деніелс покладається на відважних гінців, які привезуть особливі напої з усіх куточків земель Стормвінда.",h="Сухі часи — завдання від Шинкаря Деніелса з Лейкширу: поповнити запаси трунків у міській корчмі під час...",kw={"сухі часи","шинкар деніелс","трунки","ґрімбуз тандербрю","лейкшир","доставка"},ang={["faction:Alliance"]="Це доручення показує, як занепад безпеки на дорогах Редріджу позначається на буденному житті: гінцям Альянсу доводиться знову зшивати розірвані торгові шляхи між Стормвіндом, Елвінном, Вестфолом, Сутінколіссям і Редріджем.",["race:Dwarf"]="Навіть під час вторгнення орків людські таверни покладаються на дворфійське пивоварне мистецтво й посилають гінців аж до Вестфолу по славетний лагер Ґрімбуза Тандербрю."},sec={{t="Містечко в облозі",b="Лейкшир опинився на передовій запеклого наступу орків клану Блекрок, що спускаються з Фортеці Кам'яної Варти. Звичні шляхи постачання перекриті, дороги небезпечні, і місцевий корчмар, Шинкар Деніелс, от-от залишиться з порожніми барилами. Щоб підтримати дух наляканих селян і виснаженої міської варти, він звертається до мандрівників, які зможуть обійти загородження на дорогах і поповнити його полиці."},{t="Велика мандрівка королівством",b="Поповнити погреб Деніелса — не проста доставка, а цілий похід через усе королівство Стормвінд. Гонець має роздобути барило мерло в самій столиці, солодкий ром у Корчмі «Лев'яча Гордість» у Ґолдширі, міцний самогон у похмурому Даркширі в Сутінколіссі та особливе барильце лагеру, який варить Ґрімбуз Тандербрю на пагорбах Вестфолу."}},faq={{q="Чому в Лейкширі закінчується випивка?",a="Вторгнення орків Блекрок у Редрідж геть порушило звичну торгівлю й рух караванів із припасами. Звичні поставки Шинкаря Деніелса давно запізнюються, і його таверна ось-ось лишиться сухою саме тоді, коли містечко живе у страшній воєнній напрузі.",al={"чому закінчується випивка в лейкширі","сухі часи","чому немає пійла"}},{q="Де знайти всі напої, потрібні Шинкареві Деніелсу?",a="Треба зібрати чотири речі з усього королівства: мерло з таверн Стормвінда, солодкий ром із Ґолдширу в Лісі Елвінн, самогон із Даркширу в Сутінколіссі й барило лагеру «Тандербрю» від Ґрімбуза Тандербрю з пагорбів Вестфолу.",al={"де взяти напої","де купити мерло самогон ром","де брати напої для деніелса"}},{q="Хто такий Ґрімбуз Тандербрю?",a="Ґрімбуз Тандербрю — дворф-пивовар, що живе на пагорбах Вестфолу. Шинкар Деніелс вважає його лагер «Тандербрю» обов'язковим у запасах, але щоб його здобути, треба виконати для Ґрімбуза окреме доручення й отримати свіже барило.",al={"де ґрімбуз","ґрімбуз тандербрю","тандербрю вестфол"}},{q="Хто такий Шинкар Деніелс?",a="Деніелс — шинкар, що тримає корчму в Лейкширі. Відчайдушно намагаючись утримати таверну з повними запасами, а відвідувачів — спокійними перед загрозою орків Блекрок, він наймає мандрівників, щоб ті самі доставили припаси.",al={"шинкар деніелс","корчмар лейкшира","хто дає сухі часи"}},{q="Навіщо Деніелсові напої з такої кількості різних країв?",a="Деніелс обслуговує строкатий люд — біженців, місцевих ополченців і мандрівних шукачів пригод, — тож йому потрібен широкий вибір: від дворфійського лагеру до вишуканого столичного вина й міцних місцевих трунків із Сутінколісся та Елвінна.",al={"чому стільки напоїв","чому в сутінколісся і вестфол"}},{q="Яку нагороду дає Шинкар Деніелс за цю подорож?",a="Окрім гаманця монет на покриття дорожніх витрат, Деніелс дарує плащ, пошитий власноруч його дружиною, — на знак вдячності за те, що ви не побоялися неспокійних доріг королівства.",al={"нагорода сухих часів","що дає деніелс"}}},fp="9,277,18.416.0,27.398.0,40.246.0,53.260.0,29.231.0,23.215.0,60.225.0,57.181.0"}
P.entries["quest:1167"] = {n="Вежа Альталакса",s="Це завдання — напружена пауза перед двобоєм з Атрікусом Нарассіном у Вежі Альталакса. Делґрен Очищувач посилає шукачів пригод на північ, до розвідника Балтула Шедовстрайка, щоб зібрати відомості про безладні темні явища, які стрясають вежу.",h="Це завдання — напружена пауза перед двобоєм з Атрікусом Нарассіном у Вежі Альталакса.",kw={"вежа альталакса","балтул шедовстрайк","делґрен очищувач","атрікус нарассін","розвідка","темне узбережжя"},ang={["class:Paladin"]="Виважений підхід Делґрена показує дисципліну, якої чекають від воїнів Світла: спершу пильна розвідка, а вже потім — удар по нечестивих святилищах.",["faction:Alliance"]="Злагоджена співпраця Делґрена й Балтула — практичне воєнне партнерство паладинів-людей і розвідників із нічних ельфів, що оберігає північ Калімдору.",["race:NightElf"]="Балтул Шедовстрайк боронить землі предків від чаклунства, що віддзеркалює ті самі безрозсудні тайні надмірності, які десять тисячоліть тому зруйнували цивілізацію нічних ельфів."},sec={{t="Донесення розвідника",b="Після того як ви очистили зіпсовані реліквії й послабили хватку культу на межі Темного Узбережжя, Делґрен Очищувач посилає вас назад на північ — порадитися з його напарником-вартовим Балтулом Шедовстрайком. Перш ніж штурмувати чаклуна Атрікуса, Делґрен розуміє, що потрібна свіжа розвідка, і довіряє невтомній варті Балтула з руїн, звідки видно вежу."},{t="Збурення у вежі",b="Коли ви дістаєтеся посту Балтула, розвідник розповідає про тривожне загострення у верхньому святилищі. Раптові спалахи сліпучого світла, моторошні крики, що прорізають імлу, і безладні удари блискавок почали жорстоко стрясати давню ельфійську вежу — передвісники нестабільної й небезпечної кульмінації темної роботи Атрікуса."}},faq={{q="Чому Делґрен посилає мене назад до Балтула?",a="Делґрен знає, що кидатися наосліп у лігво Атрікуса — нерозважливо. Балтул постійно стежить за Вежею Альталакса, тож лише він знає, що Атрікус і його культисти робили останнім часом.",al={"чому делґрен посилає до балтула","поговорити з балтулом","накази делґрена"}},{q="Де знайти Балтула Шедовстрайка?",a="Балтул тримає спостережний табір на пагорбах трохи на захід від Вежі Альталакса й стежить за руїнами на півночі Темного Узбережжя.",al={"місце балтула шедовстрайка","знайти балтула","де балтул"}},{q="Що Балтул нещодавно бачив біля вежі?",a="Балтул бачив, як із найвищої зали вежі вирвався сліпучий спалах, а потім узбережжям покотилися жахливі крики й у землю безладно били блискавки.",al={"що балтул бачив біля вежі","що сталося біля вежі","крики балтула"}},{q="Хто такий Атрікус?",a="Атрікус Нарассін — темний чаклун, що очолює культистів у Вежі Альталакса; Делґрен і Балтул сповнені рішучості зупинити його зловісні обряди.",al={"хто такий атрікус","атрікус нарассін","бос вежі"}},{q="Чи Делґрен Очищувач — місцевий нічний ельф?",a="Ні, Делґрен — паладин-людина й воїн Святого Світла, що служить на межі Темного Узбережжя й Ашенвалю й разом із розвідниками нічних ельфів викорінює демонічну скверну.",al={"чи делґрен нічний ельф","хто такий делґрен","раса делґрена"}},{q="Що за руїна — Вежа Альталакса?",a="Це шпиль Високородних чи давніх нічних ельфів на скелястих північних урвищах Темного Узбережжя, давно покинутий, перш ніж занепалі арканісти й демонічні культисти захопили його для заборонених обрядів.",al={"що за руїна вежа альталакса","історія альталакса","лор вежі"}}},fp="22,266,16.385.0,25.341.1,42.236.0,39.134.0,53.187.0,16.150.0,42.175.0,44.183.0"}
P.entries["quest:117"] = {n="Тандербрю",s="«Тандербрю» — просте пивоварське доручення для мандрівного дворфа Ґрімбуза Тандербрю у Вестфолі. Щоб нова партія не вийшла більше схожою на рагу, ніж на насичений дворфійський лагер, Ґрімбузові потрібен свіжий хміль із навколишніх полів. Ті, хто йому допоможе, отримують свіжий пінистий бочонок його міцного напою.",h="«Тандербрю» — просте пивоварське доручення для мандрівного дворфа Ґрімбуза Тандербрю у Вестфолі.",kw={"тандербрю","ґрімбуз тандербрю","хміль","лагер тандербрю","пивоваріння","вестфол"},ang={["profession:Cooking"]="Відчувати рівновагу між ячменем, солодом і хмелем — друга натура для кожного, хто шанує кулінарне мистецтво й класичне дворфійське бродіння.",["race:Dwarf"]="Зустріти родича, що береже горді традиції Хараносу на суворому прикордонні Вестфолу, — завжди приємно, особливо коли йдеться про бочонки."},sec={{t="Дворфійська пристрасть у Вестфолі",b="Навіть на неспокійних рівнинах Вестфолу дворфійська майстерність живе — особливо коли йдеться про пивоваріння. Ґрімбуз Тандербрю, представник славетного дворфійського пивоварського клану, продовжує родинну традицію далеко від крижаних залів Дун Мороґу. Щоб зварити добрий стаут і лагер, потрібні точні складники, і Ґрімбуз наполягає: без доброго хмелю його нинішнє вариво ризикує перетворитися на густе рагу, а не на освіжний ель."},{t="Мистецтво бочонка",b="Ґрімбуз береться до справи з ритмічним, римованим запалом, оспівуючи основу основ — хміль, ячмінь, дріжджі й солод. Отримавши свіжий хміль, він завершує бродіння просто на місці. Шукачі пригод, які постачають йому складники, отримують цілі бочонки Лагеру Тандербрю, що славиться справжнім штурмом смакових рецепторів."}},faq={{q="Хто такий Ґрімбуз Тандербрю?",a="Ґрімбуз Тандербрю — дворф-пивовар, що мандрує просторами Вестфолу. Вірний спадку свого славетного роду, він захоплено варить міцні лагери, де б не отаборився, і часто розмовляє й наспівує веселими віршиками.",al={"хто такий ґрімбуз","ґрімбуз","лор ґрімбуза"}},{q="Навіщо Ґрімбузові хміль?",a="Без свіжого хмелю нова варка Ґрімбуза ризикує вийти густою й важкою, як юшка, а не свіжим, міцним лагером. Хміль дає потрібну гірчинку й рівновагу смаку, без яких дворфійське пивоварство неможливе.",al={"навіщо ґрімбузу хміль","ґрімбуз хміль","для чого хміль"}},{q="Що таке лагер «Тандербрю»?",a="Лагер «Тандербрю» — міцний, славетний дворфійський напій, який варить родина Тандербрю. Ґрімбуз роздає його барилами й обіцяє такі відчуття, що смак ударить по піднебінню з неймовірною силою.",al={"що таке тандербрю","бочка тандербрю","пиво тандербрю"}},{q="Чи можна приносити Ґрімбузові хміль не раз?",a="Так. Пивоварський запал Ґрімбуза ніколи не вгасає, і він охоче приймає нові поставки хмелю в обмін на додаткові барила свого фірмового напою.",al={"повторюване завдання","чи тандербрю повторюване","більше бочок"}},{q="Де відбувається це доручення?",a="Доручення виконується цілком у Вестфолі, де Ґрімбуз отаборився серед ферм і збирає припаси.",al={"місце завдання","де ґрімбуз","зона завдання"}},{q="Чи Ґрімбуз родич Тандербрю з Дун Мороґу?",a="Так, Ґрімбуз має те саме прізвище й ремесло, що й знана пивоварська родина Тандербрю з Хараноса в Дун Мороґу, і несе їхню палку пристрасть до бродіння в ширші королівства.",al={"ґуральня тандербрю","клан ґрімбуза","рід тандербрю"}}},fp="11,357,29.443.0,18.348.0,29.240.0,29.204.0,26.211.0,44.157.0,32.127.0,55.190.0"}
P.entries["quest:1176"] = {n="Полегшення вантажу",s="Поззік, головний гоблінський інженер на Перегонах Міражу, шукає матеріали, щоб зрізати кожну зайву унцію з шасі свого ракетного автомобіля. Замість покладатися лише на важку металеву обшивку, гобліни збирають порожнисті кістки місцевих пустельних грифів, щоб будувати з них міцні й надлегкі кермові тяги та каркаси.",h="Поззік, головний гоблінський інженер на Перегонах Міражу, шукає матеріали, щоб зрізати кожну зайву унцію з...",kw={"полегшення вантажу","поззік","кістки грифів","перегони міражу","мерехтливі низини","ракетний автомобіль"},ang={["profession:Engineering"]="Пташині кістки в рамах Поззіка — квінтесенція гоблінської винахідливості: функціонально, саморобно й напрочуд дієво для зменшення власної ваги машини.",["race:Gnome"]="Видовище того, як гобліни буквально прив'язують до механічної кермової тяги кістки здохлих птахів, неодмінно обурить будь-якого інженера з Містечка Майстрів, вишколеного за класичними канонами."},sec={{t="Кожна унція на рахунку",b="На сліпучо-білих просторах Мерехтливих Низин суперництво гоблінських і гномських інженерів вирішують частки секунди. Сира тяга двигуна марна, якщо болід обтяжений зайвою масою. Поки гномські команди схибнулися на хитромудрих шестернях і латунній арматурі, гоблінська команда на чолі з Поззіком шукає безжальної прагматичної ефективності: виламує важкі залізні рами й заміняє їх легшими, порожнистими деталями скрізь, де дозволяє конструкція."},{t="Пустельне збиральництво заради швидкості",b="Замість везти до Тисячі Голок дорогі спеціальні композити, Поззік звертається до соляних пустищ довкола. Грифів на солончаках вдосталь, а їхні скелети, відточені польотом, мають порожнисте стільникове осердя, що дає велику міцність на розрив майже без ваги. Поставивши оброблені кістки грифів у кермову тягу й дрібні розпірки боліда, механіки Поззіка розраховують зберегти машини досить спритними, щоб обійти гномів у маневрах і не розсипатися на найвищій швидкості."}},faq={{q="Навіщо Поззікові кістки стерв'ятників для гоночної машини?",a="Гоблінська інженерія цінує винахідливість і матеріали, що трапляються під руку. Кістки стерв'ятників порожнисті й природно легкі, тож мають ідеальне співвідношення міцності й ваги, щоб зміцнити тендітні деталі на кшталт рульового механізму, не обтяжуючи болид.",al={"навіщо поззіку кістки","призначення кісток стерв'ятників","кістки поззіка"}},{q="Хто такий Поззік?",a="Поззік — головний гоблін-механік і ватажок гоночної команди на Перегонах Міражу на Мерехтливих Низинах. Він керує гоблінськими боксами в суперництві із запеклими супротивниками — гномами.",al={"хто такий поззік","лор поззіка","гоблін-інженер"}},{q="Де знайти цих стерв'ятників?",a="Падальники й стерв'ятники кружляють над відкритими просторами Мерехтливих Низин, особливо довкола велетенських скелетів, розкиданих у північно-східній частині соляної улоговини.",al={"де стерв'ятники","місце порожніх кісток","падальники мерехтливих низин"}},{q="Що таке Перегони Міражу?",a="Перегони Міражу — нейтральний гоночний трек на величезному висохлому соляному озері в Тисячі Голок. Гобліни й гноми змагаються тут у небезпечних швидкісних перегонах дослідних ракетних болидів.",al={"лор перегонів міражу","що таке перегони міражу","траса мерехтливих низин"}},{q="Чи гноми роблять те саме?",a="Гноми теж шукають, як полегшити свої болиди, але їхня інженерна традиція схиляється до точних годинникових механізмів і складних металів, а не до гоблінських кустарних переробок зі знайденого мотлоху.",al={"чи гноми роблять те саме","гномі гонщики","гноми проти гоблінів"}},{q="Чи допомагає ця робота ширшим гоночним зусиллям Поззіка?",a="Так. Довівши свою надійність полегшенням болида, ви здобуваєте довіру Поззіка, а це веде до подальшої роботи, пов'язаної із суперництвом на треку й офіційною гоблінською підтримкою на рівнинах.",al={"продовження","що далі","спонсорство гоблінів"}}},fp="15,297,18.473.0,27.492.0,50.239.0,14.182.0,31.185.0,27.198.0,36.206.0,55.175.0"}
P.entries["quest:1179"] = {n="Брати Брассболтс",s="Пілотові Лонґбірду в Айронфорджі потрібен посланець, щоб доставити за море, до Калімдору, ящик посилених шоломів від облогових машин. Його друзі, брати Брассболтс, випробовують швидкісні ракетні автомобілі в Мерехтливих Низинах і терміново потребують захисту для голів своїх водіїв-випробувачів, що раз у раз потрапляють в аварії.",h="Пілотові Лонґбірду в Айронфорджі потрібен посланець, щоб доставити за море, до Калімдору, ящик посилених...",kw={"брати брассболтс","пілот лонґбірд","шоломи","айронфордж","мерехтливі низини","ракетні автомобілі"},ang={["profession:Engineering"]="Класичний інженерний рейс із припасами, що поєднує дворфійське ремесло важкої броні з гномськими експериментами швидкісної тяги.",["race:Dwarf"]="Тільки міцна броня дворфійських облогових машин досить товста, щоб витримати зіткнення гномської ракети на повному ходу посеред солончаків.",["race:Gnome"]="Гонитва Брассболтсів за чистою швидкістю — класичний вияв гномських амбіцій, де механічні новації важать незрівнянно більше за такі дрібниці, як гальма чи довголіття водія."},sec={{t="Послуга на відстані",b="Перебуваючи серед своїх літальних машин в Айронфорджі, дворф-авіатор Пілот Лонґбірд отримав нагальне прохання з Мерехтливих Низин на півдні Калімдору. Його друзі, двоє винахідливих гномів, відомих як брати Брассболтс, оселилися на неосяжних солончаках, щоб ганяти експериментальні машини. Лонґбірда тримають військові й льотні обов'язки, тож доставити припаси сам він не може."},{t="Безпека на шаленій швидкості",b="Ракетний автомобіль Брассболтсів виявився надзвичайно швидким — настільки, що водії-випробувачі раз у раз злітають із траси на соляних руслах і дістають тяжкі струси мозку. Лонґбірд роздобуває ящик надміцних шоломів від дворфійських облогових машин, щоб захистити їхні черепи. Доставлений ящик дає гномам вагомий аргумент, щоб умовити неохочих пілотів знову сісти за кермо їхньої непередбачуваної швидкісної машини."}},faq={{q="Хто такий Пілот Лонґбірд?",a="Пілот Лонґбірд — дворф-льотчик з Айронфорджа. Знайомий братів Брассболтсів, він їхній постачальник у Східних Королівствах: дістає важке дворфійське спорядження, яке їм нелегко виготовити в польових умовах.",al={"пілот лонґбірд","давець завдання","хто дає завдання"}},{q="Хто такі брати Брассболтси?",a="Брати Брассболтси, серед них і Віззл Брассболтс, — честолюбні гноми-інженери, що влаштувалися на Перегонах Міражу на Мерехтливих Низинах. Цілими днями вони конструюють і налаштовують найсучасніші ракетні болиди, щоб обігнати суперників-гоблінів.",al={"брати брассболтси","віззл брассболтс","гномі брати"}},{q="Де розташовані Мерехтливі Низини?",a="Мерехтливі Низини — величезна, випалена сонцем соляна рівнина на півдні Калімдору, за високими кам'яними стовпами каньйону Тисячі Голок. Цей неосяжний простір без жодних перешкод — ідеальний полігон для дослідних швидкісних машин.",al={"місце мерехтливих низин","куди доставити","де траса"}},{q="Навіщо гномам шоломи облогових машин?",a="Ракетний болид Брассболтсів розвиває величезну швидкість, але кермування й стійкість у нього кульгають. Аварії й струси мозку в пілотів стали такими частими, що жоден випробувач не хотів сідати за кермо без надійного дворфійського захисту для голови.",al={"навіщо шоломи","шоломи для аварій","аварії ракетних авто"}},{q="Чому Лонґбірд не доставить їх сам?",a="Пілота Лонґбірда тримають військові обов'язки й служба в Айронфорджі. Довга подорож через Велике Море до південного Калімдору означала б покинути пост, тож він покладається на мандрівних шукачів пригод, щоб ті доправили важку скриню.",al={"чому лонґбірд сам не доставить","обов'язки лонґбірда"}},{q="Чи можуть гравці Орди виконати це доручення?",a="Ні. Це завдання дає Пілот Лонґбірд у столиці Альянсу Айронфорджі, і воно доступне лише посланцям Альянсу, хоча самі Перегони Міражу раді обом фракціям.",al={"чи завдання лише для альянсу","версія орди","фракція"}}},fp="23,296,21.426.0,23.411.0,23.242.0,32.258.0,30.242.0,44.260.0,43.238.0,37.181.0"}
P.entries["quest:118"] = {n="Ціна підків",s="Вернер Осґуд, коваль із Лейкширу, витратив усі запаси заліза, латаючи спорядження для виснаженої міської варти. Металу, щоб підкувати місцевих коней, не лишилося, тож він посилає гінця через Ліс Елвінн по допомогу до Коваля Арґуса в Ґолдширі.",h="Вернер Осґуд, коваль із Лейкширу, витратив усі запаси заліза, латаючи спорядження для виснаженої міської...",kw={"ціна підків","вернер осґуд","коваль арґус","підкови","ґолдшир","лейкшир"},ang={["faction:Alliance"]="Залежність Лейкширу від Ґолдширу підкреслює, наскільки розтягнута логістика королівства за регентства в Стормвінді.",["profession:Blacksmithing"]="Це прохання показує сувору матеріальну реальність ковальства на прикордонні, де кузня мусить насамперед дбати про те, щоб уціліли солдати, а вже потім — про звичайні ферми."},sec={{t="Прикордоння на межі сил",b="Лейкшир опинився під прицілом гнолів, орків і мурлоків, а Стормвінд надсилає мізерне підкріплення. Місцевий гарнізон щодня бореться, щоб містечко не впало, і ця безперервна боротьба швидко зношує спорядження. Вернер Осґуд мало не весь свій час вирівнює пом'яті нагрудники, переточує затуплені мечі й тримає міську варту в залізі, виснажуючи при цьому всі запаси сировини."},{t="Шляхи постачання до Елвінну",b="Коли в прикордонному поселенні зовсім закінчується залізо, зупиняються навіть буденні справи. Без підків гінці не можуть швидко передавати вісті, а тяглові тварини — возити припаси кам'янистими стежками Редріджу. Вернерові доводиться поступитися гордістю й звернутися до серця королівства: він посилає мандрівників на захід дорогою через Три Кути до Ґолдширу, де Коваль Арґус досі має постійний доступ до багатих рудних запасів королівства."}},faq={{q="Чому у Вернера скінчилося залізо?",a="Місцеві вартові в Лейкширі постійно відбивають напади ворожих звірів Редріджу, гнолів і орків Блекрок. Вернер пускає всі запаси заліза на лагодження їхніх побитих обладунків і зброї, і на потреби мешканців нічого не лишається.",al={"чому в вернера немає заліза","вернер без металу","нестача заліза лейкшира"}},{q="Хто такий Коваль Арґус?",a="Коваль Арґус — місцевий коваль Ґолдширу в Лісі Елвінн. Його кузня ближче до жвавого серця королівства, тож дістати злитки й припаси йому куди легше, ніж прикордонним містечкам на кшталт Лейкширу.",al={"коваль арґус ґолдшир","хто такий арґус","коваль у ґолдширі"}},{q="Чому Лейкширу бракує припасів зі Стормвінда?",a="Правителі Стормвінда загрузли в політичній бездіяльності, поки Король Варіан Рінн зник. Дім Вельмож притримує війська й кошти, тож прикордонні містечка на кшталт Лейкширу здебільшого мусять дбати про себе самі, покладаючись на ту місцеву торгівлю, яку вдасться налагодити.",al={"чому лейкширу бракує припасів","чому стормвінд не допомагає","стормвінд ігнорує лейкшир"}},{q="Чому підкови такі важливі в Редріджі?",a="Кам'янистий, суворий ґрунт Редріджу швидко нищить копита непідкованих тварин. Без підків коні гінців, вози з припасами й верхові тварини патрулів кульгають, і Лейкшир відрізаний від решти королівства.",al={"навіщо підкови","чому підкови важливі"}},{q="Що буде, коли дістанешся до Коваля Арґуса?",a="Арґус приймає записку Вернера й дає партію підків, які ви несете назад до Лейкширу, — це відкриває подальші доручення, щоб допомогти вберегти обложене поселення.",al={"що після арґуса","наступне завдання"}},{q="Де в Ґолдширі знайти Коваля Арґуса?",a="Він працює біля кузні надворі неподалік Корчми «Лев'яча Гордість» у Ґолдширі, трохи осторонь головної дороги через Ліс Елвінн.",al={"де арґус","місце арґуса"}}},fp="18,261,32.437.0,22.435.0,26.246.0,19.213.0,48.266.0,43.216.0,40.167.0,42.127.0"}
P.entries["quest:119"] = {n="Повернення до Вернера",s="«Повернення до Вернера» — доручення Альянсу: доправити громіздкий вантаж із п'ятдесяти свіжовикуваних підків назад до Лейкшира. Коваль Арґус із Ґолдшира доручає вам знову перетнути кордон із Редріджем і передати скриню нетерплячому Вернеру Осґуду.",h="«Повернення до Вернера» — доручення Альянсу: доправити громіздкий вантаж із п'ятдесяти свіжовикуваних підків...",kw={"підкови","вернер осґуд","коваль арґус","лейкшир","редрідж","доставка"},ang={["faction:Alliance"]="Налагоджені лінії постачання між Лісом Елвінн і Редріджем — запорука того, що обложені віддалені поселення на кшталт Лейкшира залишаться зв'язаними з серцем королівства.",["profession:Blacksmithing"]="Перевезення п'ятдесяти підків показує, якою виснажливою є логістика прикордоння: коней треба підковувати навіть тоді, коли місцеві ковадла перевантажені війною."},sec={{t="Кур'єр через кордон",b="Ви вже подолали шлях із Лейкшира до Лісу Елвінн, щоб роздобути необхідне «взуття» для місцевих коней, і тепер завдання завершується перевезенням готової скрині з п'ятдесятьма підковами назад на схід. Гори Редріджу й далі потерпають від нестачі припасів і нападів гнолів, тож кожен шмат заліза важливий, щоб коні й тяглова худоба могли ходити суворими гірськими дорогами."},{t="Записка на скрині",b="Вернер Осґуд щиро радіє, що підкови нарешті прибули, однак Коваль Арґус кував їх не з братньої доброти. До вантажу додано рахунок із вимогою сплати. Вернера помітно дратує, що ґолдширський коваль справді чекає на винагороду, та небезпеки, що нависли над Редріджем, не лишають часу сперечатися про борг — попереду значно грізніші клопоти."}},faq={{q="Куди віднести Ящик Підків?",a="Віднесіть ящик назад Вернерові Осґуду в Лейкшир, у Горах Редріджу, трохи на схід від мосту й причалів біля озера.",al={"де вернер","місце здачі","кому віддати підкови"}},{q="Хто послав цю доставку назад до Редріджу?",a="Ящик дає Коваль Арґус — місцевий коваль, що працює біля Корчми «Лев'яча Гордість» у Ґолдширі, щойно завершить кувати.",al={"хто послав назад до редріджу","давець завдання","коваль арґус"}},{q="Чому Вернер засмучений, коли отримує ящик?",a="Арґус доклав до поставки рахунок, вимагаючи сплатити повну ціну за п'ятдесят підків, що неабияк дратує Вернера: він, певно, сподівався на дружню послугу чи м'якші умови.",al={"чому вернер засмучений","записка арґуса","реакція вернера"}},{q="Які завдання відкриваються після цієї доставки?",a="Після цієї доставки Вернер дає бойові доручення проти місцевих загроз: «Виття гнолів» — полювання на гнолів Редріджу, а також доручення «Луска з пуза».",al={"наступне завдання","продовження","що відкривається"}},{q="Чому Лейкширу потрібні припаси, привезені з Ґолдширу?",a="Лейкшир у тяжкій облозі гнолів і орків Блекрок, і місцеві ремісники розриваються на частини. Звичні речі на кшталт залізних підків гуртом часто доводиться возити зі спокійніших поселень, як-от Ґолдшир.",al={"навіщо підкови з ґолдшира","чому ввозити підкови","припаси редріджу"}},{q="Чи Коваль Арґус іде з вами назад до Редріджу?",a="Ні. Коваль Арґус лишається біля своєї кузні в Ґолдширі, а доставку з краю в край цілком доручає мандрівним шукачам пригод.",al={"чи арґус іде з вами","супровід арґуса"}}},fp="16,266,27.389.0,21.401.0,40.129.0,40.143.0,47.177.0,51.188.0,57.205.0,48.123.0"}
P.entries["quest:1195"] = {n="Священне Полум'я",s="«Священне Полум'я» — завдання Орди, яке дає Занген Стоунгуф у Тандер Блафі. Прагнучи здобути прадавню реліквію, яку стережуть кентаври Ґалак у Тисячі Голок, Занген посилає шукачів пригод углиб Ашенвалю, щоб роздобути в місцевих дріад священну фіалу для води з місячного колодязя.",h="«Священне Полум'я» — завдання Орди, яке дає Занген Стоунгуф у Тандер Блафі.",kw={"священне полум'я","занген стоунгуф","ашенваль","дріади","місячний колодязь","кентаври","притулок рейнвуд"},ang={["class:Druid"]="Друїди-таурени стикаються в цьому завданні з тривожним парадоксом: доводиться вбивати дочок природи — дріад, — щоб набрати освяченої води для удару по стихійному полум'ю кентаврів.",["faction:Horde"]="Колотнеча довкола Притулку Рейнвуд загрожує розпалити напругу з нічними ельфами в Ашенвалі, але здобуті реліквії кентаврів у Тисячі Голок зміцнюють південні рубежі Орди.",["race:Tauren"]="Ворожнеча кентаврів поколіннями мучила тауренів. Реліквія з часів зародження їхнього народу дає племенам Малгору цінне знання й важіль проти найзапекліших ворогів."},sec={{t="Реліквії кентаврів і води ельфів",b="Плем'я кентаврів Ґалак, що живе на дні каньйону Тисячі Голок, запекло оберігає артефакт, що сягає часів появи їхнього народу. Щоб пробити їхній захист і загасити священне полум'я, Зангенові Стоунгуфу потрібна вода, якої торкнулася місячна божественність, — і погляд тауренів звертається на північ, до прадавніх лісів Ашенвалю."},{t="Без дозволу в Ашенвалі",b="Здобути чисту воду з місячного колодязя непросто. Неосвячені посудини не можуть утримати священну рідину, не зіпсувавши її чеснот, тож посланцям Орди доводиться полювати на Сміхотливих Сестер біля Притулку Рейнвуд, щоб здобути гравіровану фіалу. Потім фіалу треба занурити в місячний колодязь на західному березі Річки Фалфаррен і лише тоді нести назад до Малгору."}},faq={{q="Навіщо Зангенові Стоунгуфу вода з місячного колодязя?",a="Вода призначена для соратника Зангена, Рау Кліффраннера, з Тисячі Голок. Рау хоче скористатися могутніми магічними властивостями води з місячного колодязя, щоб погасити священне полум'я, яке стережуть ворожі кентаври Ґалак, і дати Орді змогу здобути давню реліквію.",al={"навіщо вода з місячного колодязя","мета води колодязя","чому вода з ясенлісся"}},{q="Де знайти гравіровану фіалу?",a="Гравіровану фіалу носять дріади, відомі як Регочучі Сестри, що блукають лісами довкола Притулку Рейнвуд у центральному Ашенвалі, трохи осторонь північної дороги, що веде на захід від Застави Розщепленого Дерева.",al={"де гравірована фіала","як отримати фіалу","місце фіали"}},{q="З якого місячного колодязя треба наповнити фіалу?",a="Потрібний місячний колодязь стоїть біля західного берега Річки Фалфаррен, на південь від головної дороги, що перетинає центральний Ашенваль.",al={"який місячний колодязь","місце колодязя","де наповнювати фіалу"}},{q="Хто такі кентаври Ґалак?",a="Ґалак — агресивний клан кентаврів, що живе на курних просторах Тисячі Голок. У них є давня реліквія з часів зародження їхнього роду, оточена священним вогнищем, яке Занген і Рау мають намір загасити.",al={"кентаври ґалак","плем'я ґалак","хто такі ґалак"}},{q="Хто отримує наповнену фіалу після Зангена?",a="Оглянувши наповнену фіалу в Тандер Блафі, Занген велить шукачеві пригод вирушити на південь, у Тисячу Голок, і доставити посудину просто Рау Кліффраннеру, який її й просив.",al={"хто такий рау","куди вода далі","наступний крок після зангена"}},{q="Навіщо вбивати дріад заради їхніх фіал?",a="Посудини дріад створені особливо для того, щоб зберігати чисті зачаровані рідини, не псуючи їх. У звичайних пляшках не можна безпечно перенести воду, наснажену небесною силою місячного колодязя нічних ельфів.",al={"навіщо вбивати дріад","сміхотливі сестри","посудини дріад"}}},fp="16,269,31.342.0,24.376.0,46.269.0,36.196.0,48.131.0,26.227.0,43.189.0,33.197.0"}
P.entries["quest:1196"] = {n="Священне Полум'я",s="Після небезпечної вилазки до місячного колодязя в Ашенвалі фіалу з освяченою водою треба доправити на південь, до Застави Вільного Вітру. Містикові-таурену Рау Кліффраннеру потрібна ця місячна сутність, щоб пробити вічне полум'я, яке стереже прадавню реліквію кентаврів у Тисячі Голок.",h="Після небезпечної вилазки до місячного колодязя в Ашенвалі фіалу з освяченою водою треба доправити на...",kw={"священне полум'я","рау кліффраннер","застава вільного вітру","фіала","кенарій","заетар","кентаври","дріади"},ang={["class:Druid"]="Рау Кліффраннер покладається на глибоке знання родоводів Кенарія, щоб розплутати магічний зв'язок між дріадами й кентаврами.",["faction:Horde"]="Доставка цієї фіали зміцнює Заставу Вільного Вітру — високу заставу Орди серед небезпечних каньйонних проходів Тисячі Голок.",["race:Tauren"]="Кожен удар по кентаврах захищає Малгор і щойно убезпечені кордони вашої батьківщини."},sec={{t="Довга дорога на південь",b="Доручення Зангена Стоунгуфа вимагає швидко перетнути центральний Калімдор. З гравірованою фіалою, повною очищеної води місячного колодязя, вам належить перетнути випалені сонцем простори Пусток, спуститися височенним Великим Підйомником і дістатися поселення на високій столовій горі — Застави Вільного Вітру. Там, над дном каньйону, чекає Рау Кліффраннер, що стежить за зухвалими кланами кентаврів унизу."},{t="Спільна кров і прадавні обереги",b="Отримавши фіалу, Рау Кліффраннер пояснює, чому свята вода нічних ельфів така важлива для операції тауренів проти кентаврів. Дріади й кентаври мають спільне походження від напівбога Кенарія, чий син Заетар став батьком кентаврів, тож священна вода місячних колодязів несе магічний відгук їхньої спорідненості. Саме цей зв'язок робить її єдиною силою, здатною пробити захисне вічне полум'я, що оберігає стережений артефакт кентаврів."}},faq={{q="Де знайти Рау Кліффраннера?",a="Рау Кліффраннер живе нагорі Застави Вільного Вітру в Тисячі Голок. Щоб дістатися до нього, ідіть на південь через Пустки, спустіться Великим Підйомником у каньйон і йдіть південно-східною стежкою до підйомника, що піднімає на прямовисну скелю-голку.",al={"де рау","місце рау кліффраннера","знайти рау","здача вільного вітру"}},{q="Навіщо Рау вода з місячного колодязя для боротьби з кентаврами?",a="Кентаври й дріади мають спільний родовід, що сягає нащадків Кенарія. Через цю спорідненість освячені води місячного колодязя нічних ельфів мають саме ту магічну гармонію, яка потрібна, щоб зруйнувати вічне полум'я, що захищає священну реліквію кентаврів.",al={"навіщо рау вода","вода колодязя й кентаври","дріади й кентаври"}},{q="Хто послав мене з фіалою?",a="Занген Стоунгуф доручив вам доставити Наповнену Гравіровану Фіалу, після того як ви набрали води зі стереженого місячного колодязя в Ашенвалі.",al={"хто дав завдання","занген стоунгуф","давець священного полум'я 2"}},{q="Що буде, коли віддаси фіалу Рау?",a="Переконавшись, що вода ціла, Рау доручає вам самим скористатися силою фіали, щоб загасити полум'я й забрати реліквію кентаврів у сусідньому каньйоні.",al={"що після фіали рау","наступне завдання","священне полум'я частина 3"}},{q="Як спуститися в Тисячу Голок?",a="Ідіть головною південною дорогою через Пустки, доки не дійдете до краю урвища. Там стоїть Великий Підйомник — пара дерев'яних підйомників на тауренських блоках, що спускають мандрівників на дно каньйону.",al={"як спуститися в тисячу голок","шлях до тисячі голок","напрямок великого ліфта"}},{q="Чому таурени шукають реліквію кентаврів?",a="Таурени й кентаври поколіннями ведуть жорстоку війну по всьому Калімдору. Зриваючи їхні обряди й захоплюючи священні артефакти, таурени послаблюють войовничі клани, що окопалися в каньйоні Тисячі Голок.",al={"чому таурени шукають реліквію","війна тауренів і кентаврів"}}},fp="16,265,20.390.0,30.438.1,33.244.0,51.278.0,27.131.0,43.166.1,40.218.0,43.211.0"}
P.entries["quest:1197"] = {n="Священне Полум'я",s="«Священне Полум'я» — останнє завдання в розслідуванні, яке Рау Кліффраннер веде щодо кентаврів Ґалак у Тисячі Голок. Озброївшись освяченою водою, шукач пригод Орди має проникнути до Твердині Розщепленого Копита, загасити шановану жаровню племені й забрати прадавню реліквію — Роздвоєне Копито.",h="«Священне Полум'я» — останнє завдання в розслідуванні, яке Рау Кліффраннер веде щодо кентаврів Ґалак у Тисячі...",kw={"священне полум'я","роздвоєне копито","твердиня розщепленого копита","круча розколотого копита","рау кліффраннер","кентаври","ґалак"},ang={["class:Shaman"]="Шамани, що візьмуть до рук Роздвоєне Копито, легко відчують дивну енергію талісмана — доказ того, що кентаври черпають силу з містичних джерел, а не лише з грубої дикості.",["race:Tauren"]="Для тауренів удар у саме серце лігва кентаврів і здобуття їхньої святині — і відплата за покоління набігів, і безцінна наукова здобич для Застави Вільного Вітру."},sec={{t="Удар по вогнищу",b="На північ від Застави Вільного Вітру лежить Круча Розколотого Копита — серце володінь кентаврів Ґалак у Тисячі Голок. Глибоко в її печерному лігві, Твердині Розщепленого Копита, горить вогонь, священний для кентаврів. Приготувавши гравіровану фіалу з очищеною водою, Рау Кліффраннер доручає союзникам проникнути до підземної твердині, на мить загасити полум'я водою й вихопити скарб, що там зберігається, — реліквію, відому як Роздвоєне Копито."},{t="Таємниці Копита",b="Роздвоєне Копито — не просто бойова прикраса: від нього йде дивна могутня енергія, яку Рау Кліффраннер відчуває своїм містичним чуттям, щойно реліквію приносять до нього. Таурени-вчені здавна протистоять кентаврам-грабіжникам по всьому Калімдору, але такі реліквії натякають на глибші, погано вивчені сили, що живлять їхній запал і племінну єдність."}},faq={{q="Де горить священне полум'я?",a="Полум'я горить у найдальшому кінці Твердині Розщепленого Копита — печери в таборі кентаврів на Кручі Розколотого Копита, просто на північ від Застави Вільного Вітру в Тисячі Голок.",al={"де горить полум'я","місце твердині розщепленого копита","печера полум'я"}},{q="Хто просить загасити полум'я?",a="Рау Кліффраннер, старійшина, що перебуває високо на Заставі Вільного Вітру, дає це доручення як вершину своїх досліджень кентаврів Ґалак.",al={"хто просить загасити","давець священного полум'я","місце рау кліффраннера"}},{q="Як загасити полум'я?",a="Треба скористатися Наповненою Гравірованою Фіалою від Рау Кліффраннера — у ній вода, набрана раніше в ланцюжку завдань, — щоб тимчасово загасити жаровню.",al={"як загасити полум'я","як отримати роздвоєне копито","предмет для гасіння"}},{q="Що таке Роздвоєне Копито?",a="Роздвоєне Копито — шанована реліквія племені, яку кентаври Ґалак зберігають у полум'ї. Рау Кліффраннер відчуває від неї незвичну магічну енергію й сподівається, що вона відкриє таємниці культури й сили кентаврів.",al={"що таке роздвоєне копито","реліквія кентаврів","що ми вкрали"}},{q="Навіщо тауренам ця реліквія?",a="Племена кентаврів поколіннями виганяли тауренів із мисливських угідь предків. Захопивши священну реліквію, таурени зривають дії Ґалак і водночас прагнуть збагнути магічну чи духовну природу жорстокості своїх ворогів.",al={"навіщо тауренам реліквія","чому красти копито"}},{q="Який клан кентаврів стереже Твердиню Розщепленого Копита?",a="Круча Розколотого Копита та її печерна твердиня під владою племені Ґалак — найчисленнішого клану кентаврів на дні каньйону Тисячі Голок.",al={"який клан кентаврів стереже","плем'я кентаврів тисячі голок"}}},fp="16,271,19.454.0,19.353.1,34.167.0,32.143.0,29.157.0,24.218.0,34.244.0,41.144.0"}
P.entries["quest:1198"] = {n="У пошуках Таелріда",s="«У пошуках Таелріда» — розвідувальне доручення Альянсу, яке дають у Дарнасусі від імені Срібного Світанку. Дозорець Світанку Шедласс посилає шукачів пригод у затоплені руїни Чорноглибинних Печер, щоб розшукати розвідника, який пропав, досліджуючи небезпечний союз наг і сектантів. Це одна з перших зустрічей із тим, як далеко сягає Срібний Світанок за межі своєї звичної північної варти.",h="«У пошуках Таелріда» — розвідувальне доручення Альянсу, яке дають у Дарнасусі від імені Срібного Світанку.",kw={"у пошуках таелріда","срібний вартовий таелрід","дозорець світанку шедласс","срібний світанок","чорноглибинні печери","дарнасус"},ang={["class:Paladin"]="Паладини, пов'язані зі Срібним Світанком, бачать у самотній варті Таелріда урочистий обов'язок захищати світ від тіні й скверни, що підкрадаються.",["faction:Alliance"]="Це завдання — одна з перших нагод для шукачів пригод з Альянсу здобути прихильність Срібного Світанку й послужити поруч із ним.",["race:NightElf"]="Осквернення прадавнього Храму Елуни в Чорноглибинних Печерах робить допомогу Срібному Світанку нагальною справою повернення священної спадщини нічних ельфів."},sec={{t="Очі в Дарнасусі",b="Хоч Срібний Світанок найбільше славиться тим, що стримує Погибель у зачумлених руїнах Лордерону, його пильність охоплює й Калімдор. Дозорець Світанку Шедласс, що стоїть у Дарнасусі, збирає чутки й відомості про неприродні загрози, що з'являються по всьому світу. Коли надійшли тривожні донесення, що морські наги й фанатики кінця світу з Молота Присмерку уклали союз у затоплених залах Чорноглибинних Печер на березі Ашенвалю, орден побачив можливу катастрофу."},{t="Зниклий розвідник",b="Щоб перевірити ці прибережні чутки, Шедласс послав Срібного Вартового Таелріда потай проникнути в підземні печери. Минали тижні без жодної звістки, а інші розвідники Дозорця були зайняті окремими справами. Побоюючись, що Таелрід або поліг у бою, або потрапив у полон до темних сил під хвилями, Шедласс залучає досвідчених мандрівників, досить відважних, щоб прорватися в Чорноглибинні Печери й повернути його живим."}},faq={{q="Чому Срібний Світанок цікавиться Чорноглибинними Печерами?",a="Срібний Світанок стежить за всіма загрозами існуванню й скверною по всьому Азероту, а не лише за нежиттю Східних Королівств. Можливий союз давніх наг із фанатиками-культистами Молота Присмерку в Калімдорі — це зло, що розхитує світ, і воно вимагає їхньої уваги.",al={"чому срібний світанок цікавиться чорноглибиною","срібний світанок чорноглибина","срібний світанок наги"}},{q="Хто такий Дозорець Світанку Шедласс?",a="Дозорець Світанку Шедласс — агент Срібного Світанку в столиці нічних ельфів Дарнасусі. Його головний обов'язок — збирати відомості: з'ясовувати, де ордену конче потрібна допомога, і посилати дослідників оцінити кризи на місцях.",al={"дозорець світанку шедласс","давець шедласса","роль шедласса"}},{q="Хто такий Срібний Вартовий Таелрід?",a="Срібний Вартовий Таелрід — агент Срібного Світанку, посланий на розвідку до Чорноглибинних Печер. Його завдання — з'ясувати справжню силу й наміри культистів і наг, що засіли в затоплених печерах.",al={"срібний вартовий таелрід","лор таелріда","зниклий розвідник"}},{q="Де знайти Таелріда?",a="Срібний Вартовий Таелрід успішно проник у підземні глибини Чорноглибинних Печер на Зорамському Узмор'ї в Ашенвалі, але лишається відрізаним глибоко в печерах і чекає підкріплення.",al={"місце таелріда","де таелрід","знайти таелріда"}},{q="Що буде, коли знайдеш Таелріда?",a="Коли його знаходять, Таелрід розкриває всю підступну суть обряду, що відбувається в руїнах, і одразу посилає шукачів пригод ударити по проводу культу в завданні «Лиходійство в Блекфатомі».",al={"що далі","продовження таелріда","наступне завдання після таелріда"}},{q="Чи можуть гравці Орди взятися за це доручення?",a="Доручення дає Дозорець Світанку Шедласс у Дарнасусі, і воно розраховане на шукачів пригод з Альянсу. Шукачі пригод з Орди теж можуть його взяти, якщо до нього доберуться.",al={"чи орда може виконати","орда в пошуках таелріда","орда таелрід"}}},fp="21,424,17.537.0,17.468.0,55.291.0,29.259.0,29.229.0,28.208.0,36.219.1,36.155.0"}
P.entries["quest:1199"] = {n="Падіння Сутінків",s="Срібний Вартовий Манадос у Дарнасусі закликає звитяжців Альянсу вдарити по сектантах Молота Присмерку, що зібралися в Чорноглибинних Печерах. Темний культ уклав союз зі зміїподібними нагами, щоб захопити затоплений храм нічних ельфів на узбережжі Ашенвалю. Збираючи амулети з полеглих сектантів, шукачі пригод завдають удару по їхніх підступних планах пробудити прадавнє зло.",h="Срібний Вартовий Манадос у Дарнасусі закликає звитяжців Альянсу вдарити по сектантах Молота Присмерку, що...",kw={"падіння сутінків","срібний вартовий манадос","молот присмерку","сутінковий амулет","чорноглибинні печери","срібний світанок"},ang={["class:Paladin"]="Як поборники Святого Світла, пов'язані з орденами на кшталт Срібного Світанку, паладини вважають розбещене поклоніння Молота Присмерку Древнім Богам мерзотою, що вимагає праведного очищення.",["class:Priest"]="Жерці гостро відчувають перекрученість колись священного місячного колодязя храму й божевільний тіньовий шепіт, що жене сектантів дедалі глибше в безумство.",["faction:Alliance"]="Молот Присмерку — загроза, що підступає трохи на південь від Темного Узбережжя, тож очищення Чорноглибинних Печер необхідне, щоб убезпечити північ Калімдору.",["race:NightElf"]="Осквернення священного храму й місячного колодязя підступними прислужниками Порожнечі й нагами — пряма образа Елуни й родових земель Ашенвалю."},sec={{t="Осквернене святилище",b="Під суворими кручами Зорамського Берега в Ашенвалі лежать руїни Чорноглибинних Печер. Колись це був священний храм нічних ельфів, присвячений Елуні, з могутнім місячним колодязем, але під час Розколу його було зруйновано, і він канув у глибини. Сьогодні священні води загнили й смердять, а храм заполонили кровожерливі наги й фанатичні сектанти, що шанують сили, куди темніші за море."},{t="Шепіт Древніх Богів",b="Молот Присмерку — апокаліптичний культ, відданий хаотичним Древнім Богам, що прагне повернення своїх первісних покровителів і хоче вкрити світ божевіллям і руїною. Донесення, що доходять до Дарнасуса, підтверджують: ці безумці об'єдналися з нагами, що живуть у Чорноглибинних Печерах. Глибоко в затоплених залах вони правлять блюзнірські обряди, використовуючи осквернені води потонулого храму, щоб живити відродження своїх темних господарів."},{t="Варта Срібного Світанку",b="Срібний Вартовий Манадос, що стоїть у Дарнасусі, уособлює пильність Срібного Світанку проти всіх напастей, що загрожують Азероту. Розуміючи, що мерзота в Чорноглибинних Печерах може накликати жахіття на всі цивілізовані народи, орден пропонує визнання й допомогу кожному героєві, готовому спуститися в затоплений лабіринт, винищити сектантів і зірвати з їхніх ший Сутінкові амулети як доказ їхньої загибелі."}},faq={{q="Хто такий Срібний Вартовий Манадос?",a="Срібний Вартовий Манадос — посланець Срібного Світанку в Дарнасусі. Він — очі й вуха свого ордену в Калімдорі: стежить за лиховісними культами й темними силами, що загрожують світу, і залучає шукачів пригод, щоб їх викорінити.",al={"срібний вартовий манадос","хто дає падіння сутінків","місце манадоса"}},{q="Чому Срібний Світанок турбують Чорноглибинні Печери?",a="Хоча Срібний Світанок найбільше відомий боротьбою з Погибеллю в Лордероні, його статут охоплює протистояння будь-якому неприродному злу, що загрожує існуванню світу. Відродження культу Древніх Богів і союз культистів із нагами в Калімдорі, якщо їх не зупинити, загрожують катастрофою для всього світу.",al={"чому срібний світанок дарнас","срібний світанок чорноглибина"}},{q="Що таке Молот Присмерку?",a="Молот Присмерку — фанатичний культ кінця світу, що поклоняється Древнім Богам — хаотичним первісним сутностям, давно ув'язненим під землею. Культисти прагнуть наблизити апокаліпсис, коли їхні темні господарі знову повстануть і переінакшать світ у жаху й божевіллі.",al={"культ молота присмерку","хто молот присмерку","молот присмерку"}},{q="Для чого були Підвіски Присмерку?",a="Підвіски Присмерку — темні талісмани, які носять члени Молота Присмерку на знак вірності хаотичним сутностям, яким поклоняються. Срібний Світанок збирає їх як надійний доказ, що культиста вбито й знешкоджено.",al={"лор підвісок присмерку","що за підвіски"}},{q="Чим спочатку були Чорноглибинні Печери?",a="Задовго до осквернення Чорноглибинні Печери були величним храмом нічних ельфів, присвяченим місячній богині Елуні. Він славився надзвичайно могутнім місячним колодязем, доки Великий Розкол не розколов землю й не затопив його зали морем.",al={"історія чорноглибини","історія храму чорноглибини","місячний колодязь чорноглибини"}},{q="Чому Молот Присмерку співпрацює з нагами?",a="І наги, і Молот Присмерку глибоко й темно віддані хаотичним силам глибин. У Чорноглибинних Печерах співпраця дає культистам безпечний доступ до давніх затоплених залів, а наги користаються з мерзенного чаклунства й жертвоприношень культу.",al={"союз молота присмерку з нагами","наги й культисти"}}},fp="14,384,17.393.0,24.443.0,28.423.0,28.243.0,57.285.0,30.278.0,41.246.0,38.262.0,52.286.0"}
P.entries["quest:12"] = {n="Народне ополчення",s="Це завдання — ваше перше офіційне випробування під началом Ґраяна Стаутмантла в Сентінел Гіллі: ви маєте довести, що гідні вступити до Народного ополчення. Поки трон Стормвінда зайнятий іншим, а його військо далеко, місцеві добровольці взялися до зброї, щоб захистити Вестфол від зухвалого Братства Дефіас. Перше ж доручення відправляє вас північними полями й копальнями — прорідити розбійників, що душать місцеві ниви.",h="Це завдання — ваше перше офіційне випробування під началом Ґраяна Стаутмантла в Сентінел Гіллі: ви маєте...",kw={"народне ополчення","ґраян стаутмантл","сентінел гілл","братство дефіас","шахта джанґолод","вестфол"},ang={["class:Paladin"]="Служба в Народному ополченні втілює головне покликання паладина — захищати беззахисних і чинити праведний суд над розбійниками, що визискують слабких.",["faction:Alliance"]="Це завдання показує глибокий розкол у королівстві: поки знать Стормвінда ховається за мурами столиці, шукачі пригод з Альянсу мусять стати пліч-о-пліч із простими поселенцями, щоб урятувати Вестфол від руїни.",["race:Human"]="Для людей королівства лихо Вестфолу — глибоко особиста справа: робітничі родини й ферми, що переходили з покоління в покоління, стають жертвами розбійників, поки королівська влада відводить очі."},sec={{t="Ціна миру",b="Колись Вестфол був родючою житницею Стормвінда, а нині його заполонили розбійники, волоцюги й злодії. Столиця відмовляється посилати королівських солдатів патрулювати сільські землі, тож Ґраян Стаутмантл зібрав Народне ополчення — відчайдушну місцеву самооборону з осередком у Сентінел Гіллі. Стаутмантл переконаний: щоб відвоювати край, потрібні рішучі дії, і кожен, хто хоче носити знак ополчення, мусить показати і бойову готовність, і цілковиту відданість захисту невинних поселенців."},{t="Очистити житницю",b="Перш ніж новобранцям довірять складніші бойові операції, їх відправляють зламати присутність Дефіасу, що підбирається до північних господарств. Трапери й контрабандисти Дефіасу відкрито орудують біля Шахти Джанґолод, Ферми Молсена й Гарбузового Поля Фурлброу, грабують комори й влаштовують засідки на мандрівників. Вибиваючи цих розбійників, майбутні ополченці зривають злодіям постачання на передовій і доводять розвідникам Стаутмантла, що мають досить твердості для затяжної війни зі злочинністю."}},faq={{q="Що таке Народне ополчення?",a="Народне ополчення — добровольче військо, яке зібрав Ґраян Стаутмантл із осідком на Сентінел Гіллі. До нього увійшли місцеві фермери, ветерани й прості люди, які боронять Вестфол від Братства Дефіас, бо королівська армія Стормвінда відмовилася чи не спромоглася поставити тут гарнізон.",al={"що таке народне ополчення","хто ополчення","народне ополчення"}},{q="Чому Стормвінд не посилає королівську армію?",a="Відколи Король Варіан Рінн зник, знать Стормвінда в Домі Вельмож і рада спрямовують ресурси королівства деінде, а віддалені сільські краї на кшталт Вестфолу лишилися самі проти розбійницьких ватаг, яких дедалі більшає.",al={"де армія","чому немає варти у вестфолі","гарнізон стормвінда"}},{q="Де знайти Ловців і Контрабандистів Дефіас?",a="Вони орудують переважно на півночі Вестфолу, особливо довкола Гарбузової Ферми Фурлброу, Ферми Молсена й біля входу до Шахти Джанґолод.",al={"місце ловців","місце контрабандистів","де ловці"}},{q="Хто такий Ґраян Стаутмантл?",a="Ґраян Стаутмантл — бувалий ветеран і командир Народного ополчення на Сентінел Гіллі. Відданий захистові поселенців Вестфолу, він згуртовує добровольців, щоб вигнати Братство Дефіас і навести лад у краї.",al={"хто такий стаутмантл","ґраян стаутмантл","лідер ополчення"}},{q="Чи веде це завдання до інших доручень ополчення?",a="Так. Це завдання — лише вступне випробування. Добровольці, які з ним упоралися, отримують подальші доручення проти дедалі небезпечніших ланок Братства Дефіас, розкиданих рівнинами Вестфолу.",al={"чи це ланцюжок","наступне завдання","прогрес ополчення"}},{q="Що коїться на Гарбузовій Фермі Фурлброу?",a="Фурлброу вигнали з їхньої садиби, коли Братство Дефіас захопило ці землі, і тепер розбійники й мародери плюндрують поля й тероризують північні дороги.",al={"ферма фурлброу","що сталося з фурлброу","гарбузова ферма"}}},fp="20,400,18.517.0,24.511.0,29.277.0,43.237.0,47.148.0,25.254.0,49.207.0,45.196.0"}
P.entries["quest:120"] = {n="Гонець до Стормвінда",s="Магістрат Соломон із Лейкширу відчайдушно потребує військової допомоги: гноли й орки Блекрок оточують містечко. Не маючи змоги виділити бійців гарнізону, він доручає шукачеві пригод доставити «Становище Лейкширу» просто Генералові Маркусу Джонатану в Стормвінд.",h="Магістрат Соломон із Лейкширу відчайдушно потребує військової допомоги: гноли й орки Блекрок оточують...",kw={"гонець до стормвінда","магістрат соломон","становище лейкширу","генерал маркус джонатан","стормвінд","лейкшир"},ang={["class:Paladin"]="Нести благання знедолених до правителів, скутих придворною політикою, — випробування ключових чеснот: обов'язку, захисту й праведної дії.",["faction:Alliance"]="Це доручення оголює дедалі глибший розлам між заможною столицею й занедбаними прикордонними поселеннями, що борються за виживання на околицях королівства.",["race:Human"]="Редрідж — споконвічна земля Стормвінда; бачити, як співвітчизників кидають напризволяще через бюрократичну тяганину, боляче для кожного патріота королівства."},sec={{t="Крик через гори",b="Лейкшир на межі загибелі. Зграї гнолів оспорюють кожну дорогу, орки Блекрок нападають із півночі, а місцеві вартові вкрай виснажені. Магістрат Соломон не може дозволити собі послати бійців у багатоденну дорогу до столиці, тож нести до міської брами його офіційне прохання про регулярні війська доводиться незалежному мандрівникові."},{t="Бюрократія й королівський престол",b="Доставивши доповідь магістрата, шукач пригод опиняється віч-на-віч із Генералом Маркусом Джонатаном, командувачем оборони Стормвінда. Джонатан поважає Соломона як провідника громади й визнає нагальність справи, проте військовий статут не дозволяє йому рушати війська без королівського наказу. Оборона Редріджу мусить чекати на офіційну нараду з юним королем Андуїном і регентською радою."}},faq={{q="Навіщо Магістратові Соломону гонець?",a="Лейкшир у постійній облозі орків Блекрок і гнолів. Кожен місцевий вартовий потрібен, щоб боронити місто й утримувати міст, тож Соломон довіряє свої нагальні прохання про допомогу мандрівним шукачам пригод.",al={"навіщо гонець","навіщо мене посилає","гонець соломона"}},{q="Що в донесенні «Становище Лейкширу»?",a="Це офіційний звіт про кризу, що охопила Гори Редріджу: у ньому описано, як зростає кількість ворогів, які втрати й що місто неминуче впаде, якщо зі столиці не пришлють регулярне військо.",al={"становище лейкширу","звіт соломона","що в листі"}},{q="Хто такий Генерал Маркус Джонатан?",a="Генерал Маркус Джонатан — командувач Міської варти Стормвінда й один із вищих воєначальників армії Стормвінда. Він пильнує міську браму й звітує безпосередньо Верховному Лордові Болвару Фордрагону й короні.",al={"маркус джонатан","хто такий генерал","генерал стормвінда"}},{q="Чому Генерал Джонатан не посилає вояків одразу?",a="Генерал Джонатан не може розгорнути армію з власної волі. Він мусить подати донесення Соломона королю й регентській раді й отримати офіційний королівський наказ, перш ніж війська рушать.",al={"чому джонатан не посилає військ","де підкріплення","відповідь джонатана"}},{q="Чи безпечна дорога між Лейкширом і Стормвіндом?",a="Ні. Шляхи через Редрідж в Елвінн заполонили агресивні ватаги гнолів і розбійники Дефіас, тож подорож небезпечна для самотніх гінців.",al={"чи безпечна дорога","шлях до стормвінда","безпечна подорож"}},{q="Чи Стормвінд зрештою посилає допомогу?",a="Політична бездіяльність і безлад у столиці затримують будь-яку справжню відповідь армії, тож Лейкширу та його магістратові доводиться покладатися майже лише на найманців і добровольців.",al={"чи прийде допомога","чи стормвінд допоможе"}}},fp="22,259,26.356.0,29.384.0,45.212.0,43.206.0,31.211.0,54.197.0,49.156.0,35.166.1"}
P.entries["quest:1200"] = {n="Лиходійство в Блекфатомі",s="«Лиходійство в Блекфатомі» — доручення Альянсу, яке дає Срібний Вартовий Таелрід глибоко в зруйнованому підземному храмі Чорноглибинних Печер. Щоб зупинити жахливі жертвоприношення, що живлять прадавнє жахіття, героям доручено стратити ватажка культу, сутінкового володаря Келріса, і принести доказ Срібному Світанку в Дарнасус.",h="«Лиходійство в Блекфатомі» — доручення Альянсу, яке дає Срібний Вартовий Таелрід глибоко в зруйнованому...",kw={"лиходійство в блекфатомі","сутінковий володар келріс","срібний вартовий таелрід","аку'май","чорноглибинні печери","срібний світанок"},ang={["class:Paladin"]="Відгукнутися на заклик Срібного Світанку й убити сектанта, що приносить невинних у жертву первісним жахіттям, — саме втілення святої відплати.",["class:Priest"]="Зупинивши Келріса, ви кладете край блюзнірському оскверненню вод, що колись були священними й присвяченими божественному.",["faction:Alliance"]="Допомагаючи Срібному Світанку проти Келріса, Альянс захищає вразливі кордони Ашенвалю від підступного проникнення культу.",["race:NightElf"]="Помста за осквернення прадавнього храму Елуни й очищення його отруєного місячного колодязя — удар у саме серце спадщини калдореїв."},sec={{t="Споганена святиня",b="Затоплена печера, відома нині як Чорноглибинні Печери, колись була незайманим підземним храмом Елуни. Те священне минуле зруйнувалося, коли скверна прадавнього Древнього Бога просочилася крізь скелю, зіпсувала місячний колодязь храму й вивільнила Аку'мая — ненажерливого слугу тієї первісної темряви. Після цієї наруги культ Молота Присмерку уклав нечестивий союз із місцевими нагами й перетворив святі зали на кубло обрядових убивств."},{t="Благання пораненого вартового",b="Срібний Вартовий Таелрід вирушив у Чорноглибинні Печери від імені свого ордену, але був тяжко поранений і знесилений. Опинившись серед ворогів, Таелрід розуміє, що сам не завершить своєї місії. Він благає кожного відважного мандрівника з Альянсу, що до нього дістанеться, убити сутінкового володаря Келріса — лиховісного сектанта, що приносить невинних у жертву Аку'маю в обмін на темну силу."},{t="Правосуддя в Дарнасусі",b="Відтята голова Келріса, принесена Дозорцеві Світанку Селґорму на Терасу Ремісників у Дарнасусі, нарешті завершує довге й тривожне полювання. Срібний Світанок вважав Келріса мертвим чи зниклим у тінях, хоча той раз у раз виринав щоразу, як у Калімдорі ворушилися темні сили. Його смерть — важлива перемога над задумами культу в Ашенвалі."}},faq={{q="Хто такий Срібний Вартовий Таелрід?",a="Таелрід — агент Срібного Світанку, посланий розслідувати тінь, що згущується в Чорноглибинних Печерах. Тяжко поранений у глибинах, він настільки виснажений, що мусить залучати перехожих шукачів пригод, щоб зупинити Келріса.",al={"хто такий таелрід","лор таелріда","срібний вартовий"}},{q="Чому мішенню став сутінковий володар Келріс?",a="Келріс — ватажок культистів Молота Присмерку в Чорноглибинних Печерах. Він раз у раз приносить безневинних полонених у жертву Аку'маю, мерзенному чудовиську, пов'язаному з Древніми Богами, в обмін на лиховісну силу.",al={"хто такий келріс","чому вбивати келріса","сутінковий володар келріс"}},{q="Хто такий Дозорець Світанку Селґорм?",a="Дозорець Світанку Селґорм — представник Срібного Світанку на Терасі Ремісників у Дарнасусі. Він керує зусиллями ордену протидіяти скверні, що підступає до північного Калімдору.",al={"селґорм дарнас","хто такий селґорм","срібний світанок дарнас"}},{q="Яка історія Чорноглибинних Печер?",a="Перш ніж стати затопленим лігвом чудовиськ і культистів, ці печери ховали великий храм нічних ельфів, присвячений богині Елуні. Він занепав, коли злоба одного з Древніх Богів просочилася нагору й осквернила його священний місячний колодязь.",al={"історія чорноглибини","що було чорноглибинними печерами","храм елуни чорноглибина"}},{q="Хто такий Аку'май?",a="Аку'май — потворний, схожий на гідру слуга одного з Древніх Богів, що виповз із осквернених вод під Чорноглибинними Печерами. Молот Присмерку шанує цю істоту й згодовує їй полонених, щоб здобути темні благословення.",al={"що таке аку'май","лор аку'май","звір аку'май"}},{q="Чому Молот Присмерку й наги діють разом?",a="Обидві сили віддані темним давнім господарям, пов'язаним із глибинами. У Чорноглибинних Печерах вони об'єдналися, щоб захопити руїни храму й єднатися з Аку'маєм.",al={"союз наг і культистів","чому наги в чорноглибині","молот присмерку й наги"}}},fp="20,322,19.464.0,23.408.0,20.360.1,29.222.0,43.224.0,27.195.0,41.223.0,15.214.0,56.178.0"}
P.entries["quest:1205"] = {n="Мертвобагно",s="«Мертвобагно» — мисливський обряд від таурена Мелора Стоунгуфа з Узвишшя Мисливців у Тандер Блафі. Завдання відсилає мисливців на схід, у Багно Пилоброду, щоб вистежити й убити прадавнього, змученого кроколіска на ім'я Мертвобагно й принести його зуб як доказ. Це водночас і непросте вистежування, і урок мисливського обов'язку милосердя.",h="«Мертвобагно» — мисливський обряд від таурена Мелора Стоунгуфа з Узвишшя Мисливців у Тандер Блафі.",kw={"мертвобагно","кроколіск","мелор стоунгуф","багно пилоброду","узвишшя мисливців","мисливець","милосердя"},ang={["class:Hunter"]="Для мисливців вистежування Мертвобагна втілює рівновагу між бойовою вправністю й духовною відповідальністю: почесне вбивство може бути актом милосердя.",["faction:Horde"]="Полювання на прохання старійшин Тандер Блафа допомагає мандрівникам Орди зріднитися із землею та духовними традиціями своїх союзників-тауренів.",["race:Tauren"]="Це полювання відображає головні цінності тауренів — гармонію з творіннями Земної Матері: справжній мисливець шанує здобич і поважає природне коло життя й смерті."},sec={{t="Полювання з милосердя",b="На Узвишші Мисливців у Тандер Блафі Мелор Стоунгуф навчає здібних слідопитів глибших духовних традицій полювання. На відміну від бездумної різанини чи збирання трофеїв, мисливська філософія тауренів учить шани й єднання з природою. Мелор доручає мисливцям вирушити далеко на схід, до каламутних боліт Багна Пилоброду, і розшукати Мертвобагно — прадавнього кроколіска велетенських розмірів, чиє довге життя обернулося нестерпним тягарем."},{t="Прадавній володар Багна",b="Мертвобагно — не звичайний звір: це величезний блідий кроколіск, що чатує в протоках на північ від Руїн Кам'яного Молота. Юнацька лють і фізична сила ще прориваються в ньому раптовими спалахами, але старе тіло зношене скрипучими кістками й невпинним болем. Мелор доручає мисливцям подарувати істоті почесний і швидкий кінець, дати спокій її духові й забрати лише один зуб на знак звільнення звіра."}},faq={{q="Хто такий Мертвобагно?",a="Мертвобагно — велетенський прадавній білий кроколіск, що живе на болотах Багна Пилоброду. Хоч він і досі небезпечно могутній, його старе, немічне тіло завдає йому нестерпних мук.",al={"що таке мертвобагно","лор мертвобагна","хто крокодил"}},{q="Чому Мелор Стоунгуф хоче смерті Мертвобагна?",a="Мелор бачить у цьому полюванні не завоювання, а милосердя. Старі кістки Мертвобагна завдають йому болю, що зводить з розуму, і таурен-мисливець вважає священним обов'язком звільнити дух шляхетного звіра й дарувати йому спокій.",al={"чому мелор хоче вбити мертвобагно","мотив мелора","мета полювання на мертвобагно"}},{q="Де знайти Мертвобагно?",a="Мертвобагно блукає каламутними водами й острівцями Багна Пилоброду; зазвичай він никає протоками трохи на північ від Руїн Кам'яного Молота.",al={"де мертвобагно","місце мертвобагна","пошук мертвобагна"}},{q="Який доказ полювання вимагає Мелор?",a="Мелор просить принести Зуб Мертвої Багнюки як доказ, що муки могутньої істоти нарешті скінчилися.",al={"предмет завдання мертвобагна","чого хоче мелор","доказ мертвобагна"}},{q="Чого це полювання вчить молодих мисливців?",a="Полювання вчить, що шлях мисливця — не бездумне вбивство, а духовне єднання з природою. Частина цього покликання — розпізнати, коли життя істоти обернулося стражданням, і дати їй милосердну, почесну смерть.",al={"філософія мисливця","урок полювання тауренів","сенс полювання"}},{q="Хто дає це завдання?",a="Завдання дає Мелор Стоунгуф — таурен-мисливець на Узвишші Мисливців над Тандер Блафом.",al={"хто дає мертвобагна","давець завдання","місце мелора стоунгуфа"}}},fp="8,340,15.467.0,24.413.0,16.198.0,46.218.0,28.140.0,44.127.0,43.238.0,21.116.0"}
P.entries["quest:122"] = {n="Луска з пуза",s="Вернерові Осґуду потрібна луска з пуза чорних дракончиків, щоб розрахуватися з торговим боргом перед Ковалем Арґусом із Ґолдширу. Щоб зібрати її, доведеться полювати на молодих драконів, що блукають скелями на південь від Лейкширу. Луска закриє рахунок Вернера, а ще з неї лишиться досить сировини, щоб виготовити щось зі спорядження.",h="Вернерові Осґуду потрібна луска з пуза чорних дракончиків, щоб розрахуватися з торговим боргом перед Ковалем...",kw={"луска з пуза","чорні дракончики","вернер осґуд","коваль арґус","борг","редрідж"},ang={["faction:Alliance"]="Загроза Чорного драконячого роду, що підкрадається з півдня до Лейкширу, — ще один тягар для й без того виснаженого гарнізону, який ледве втримує Редрідж.",["profession:Blacksmithing"]="Вимога Коваля Арґуса показує, як рідкісні реагенти на кшталт драконячої луски стають цінним засобом обміну між ковалями, коли звичайних монет бракує.",["race:Human"]="Торгові шляхи між Елвінном і Редріджем підтримують постачання містечок на кшталт Лейкширу, але прикордонні ремісники часто мусять платити міським купцям чималу ціну."},sec={{t="Прикордонний борг",b="Тримати кузню на околиці Лейкширу без рідкісних припасів неможливо, тож Вернер Осґуд часто торгує з ремісниками за межами Гір Редріджу. Отримавши партію підків від Коваля Арґуса з Ґолдширу, Вернер виявив, що звичайних монет йому бракує. Натомість Арґус вимагає плати цінною драконячою шкірою — а саме м'якшою й дуже цінованою лускою з пуза чорних дракончиків, що гніздяться в краї. Без неї Вернерові загрожує, що з Лісу Елвінн пришлють збирачів боргів."},{t="Виводок Чорного роду",b="Поява чорних дракончиків у Горах Редріджу — тривожний знак для місцевих захисників. Поки гноли й орки відкрито борються за дороги, виводок Чорного драконячого роду гніздиться на високих вершинах і кружляє в небі на південь від Озера Незрушного. Луска з пуза цих молодих хижаків міцна й водночас гнучка, тож її високо цінують бронярі, ковалі й шкіряники по всьому королівству — ті, кому вистачає сміливості її здобути."}},faq={{q="Навіщо Вернерові Осґуду драконяча луска?",a="Вернер винен Ковалю Арґусу з Ґолдширу за партію підків. Арґус зажадав плати не монетою, а лускою з пуза дракончат чорних драконів. Вернерові треба швидко доставити луску, поки Арґус не прислав збирачів боргів.",al={"навіщо вернеру луска","борг вернера","луска арґуса"}},{q="Де в Редріджі знайти дракончат чорних драконів?",a="Дракончата чорних драконів зазвичай блукають скелястими кручами й долинами на південь від Лейкширу. Вони вільно никають південними передгір'ями, тож мисливцям часто доводиться обходити стежки й гребені, щоб помітити їх у польоті.",al={"де дракончата редріджу","місця дракончат","місця чорних дракончат редріджу"}},{q="Хто такий Коваль Арґус?",a="Коваль Арґус — місцевий коваль у Ґолдширі в Лісі Елвінн. Він постачає металеві вироби довколишнім поселенням, зокрема підкови для Вернера Осґуда в Редріджі.",al={"коваль арґус","арґус ґолдшир","хто такий арґус"}},{q="Звідки в Горах Редріджу дракончата чорних драконів?",a="Рід чорних драконів присутній по всіх Палаючих Степах і на довколишніх вершинах Редріджу. Їхні дракончата полюють і мандрують на південь гірськими перевалами в передгір'я Редріджу.",al={"чому дракони в редріджі","чорні дракони редріджу","чорний виліт редрідж"}},{q="Чим особлива луска з пуза?",a="Спинна луска драконів товста й тверда, а луска з пуза — гнучка й еластична, але так само добре тримає жар і проколи. Тому вона ідеальна для особливої обробки шкіри, підсилення одягу й екзотичної торгівлі.",al={"чому луска з пуза","цінність луски","якість драконової шкіри"}},{q="Чи сплата цього боргу веде до інших доручень Вернера?",a="Це доручення — одне з прохань Вернера Осґуда, після того як ви принесете йому підкови. Окрім цього необов'язкового збирання, Вернер посилає шукачів пригод протидіяти дедалі більшій загрозі гнолів у Редріджі — полювати на їхніх розвідників і ватажків.",al={"що після боргу","ланцюжок вернера","продовження осґуда"}}},fp="17,309,15.533.0,25.469.0,42.260.0,52.222.0,19.198.0,50.209.0,37.247.0,55.246.0"}
P.entries["quest:1221"] = {n="Синьолисті бульби",s="«Синьолисті бульби» — угода на добування, яку укладає гоблінський торговець Мебок Міззірікс у Раджеті. Прагнучи заробити на рідкісному підземному делікатесі, Міззірікс дає шукачам пригод навчених ховрахів-нюхоносів, щоб ті знаходили й викопували бульби, закопані в колючих глибинах Рейзорфен Краулу.",h="«Синьолисті бульби» — угода на добування, яку укладає гоблінський торговець Мебок Міззірікс у Раджеті.",kw={"синьолисті бульби","мебок міззірікс","раджет","ховрахи-нюхоноси","рейзорфен краул","делікатес","шипогриви"},ang={["faction:Alliance"]="Експедиції Альянсу, що прибувають до нейтрального порту Раджет, можуть скористатися торговою угодою Міззірікса як приводом вирушити на ворожі землі поблизу Орди.",["faction:Horde"]="Воїни Орди, що захищають Пустки від набігів шипогривів, легко можуть принагідно заробити, поводивши навчених ховрахів Міззірікса Краулом.",["profession:Cooking"]="Майстри кулінарії знають, що синьолисті бульби — один із найрідкісніших делікатесів Азероту, і їх скуповують вибагливі покупці, що цінують їхній особливий землистий смак.",["profession:Herbalism"]="На відміну від звичайних наземних рослин, синьолисті бульби ростуть лише під землею, серед колючого коріння Рейзорфену, сховані від сонця."},sec={{t="Цінний підземний делікатес",b="Синьолисті бульби по всьому світу цінують як рідкісний і розкішний делікатес. Попри високу ціну, добувати їх украй важко, бо вони не ростуть ні в чистому полі, ні у звичайних диких гаях. Їх знаходять майже винятково глибоко в безсонячній землі під південними Пустками, серед лабіринту коріння Рейзорфен Краулу."},{t="Винахідливість Міззірікса",b="Бульби цілком закопані, і звичайні люди й інші гуманоїди майже не можуть їх помітити, тож раджетський торговець Мебок Міззірікс вигадав незвичний вихід. Він навчив місцевих ховрахів-нюхоносів — звірят, що чують закопану бульбу за п'ятдесят кроків, — і перетворив шкідників на знаряддя для пошуку. Збирачам він видає командний жезл, провітрюваний ящик і посібник з інструкціями, щоб вести звірят землями шипогривів."},{t="Збирання серед колючок",b="Щоб добути бульби, треба спуститися на землі ворожого племені шипогривів Мертвої Голови. Збирачі мають захищати своїх навчених ховрахів від диких звірів і колючих хащів Краулу, наказуючи гризунам відкопувати сховані бульби, а потім пакувати їх для доставки до Раджета, де на них чекають щедрі заморські покупці Міззірікса."}},faq={{q="Для чого потрібні синьолисті бульби?",a="Їх вважають рідкісним і дуже бажаним делікатесом у всьому світі. Заможні покупці платять за свіжі бульби чималі гроші, тож для гоблінів на кшталт Мебока Міззірікса це вигідний товар.",al={"призначення бульб","що таке синьолисті бульби","навіщо збирати бульби"}},{q="Де ростуть синьолисті бульби?",a="Вони ростуть закопані в підземному ґрунті й серед колючого коріння під південними Пустками, а саме — у твердині шипогривів Рейзорфен Краулі.",al={"де ростуть бульби","місце синьолистих бульб","де вони ростуть"}},{q="Навіщо для їх пошуку Ховрах-нюхоніс?",a="Бульби цілком сховані під землею, і звичайним оком їх не побачити. Ховрах-нюхоніс має гострий нюх, що вчуває закопані бульби з відстані до п'ятдесяти кроків, і може викопати їх із землі.",al={"навіщо ховрахи","ховрахи-нюхоноси","як ховрахи шукають бульби"}},{q="Хто такий Мебок Міззірікс?",a="Мебок Міззірікс — заповзятливий гоблін-торговець із нейтрального портового містечка Раджет у Пустках. Він спеціалізується на дресируванні місцевих тварин і здобуванні екзотичних товарів для торгівлі за кордоном.",al={"хто дає синьолисті бульби","мебок міззірікс","гоблін раджета давець"}},{q="Яке спорядження дає Міззірікс для цієї роботи?",a="Міззірікс дає шукачам пригод Ящик з дірками з навченим ховрахом, Командний Жезл Нюхоноса, щоб наказувати тварині копати, і Посібник Власника Нюхоноса з настановами, як із нею поводитися.",al={"спорядження для бульб","палиця для ховраха","ящик з дірками"}},{q="Чому Мебок не може зібрати бульби сам?",a="Рейзорфен Краул пильно стережуть агресивні племена шипогривів, колючі лози й небезпечні підземні хижаки. Міззірікс воліє ризикувати життям найманців, аніж самому лізти в ці небезпечні нори.",al={"чому мебок сам не збере","чому найняв шукачів"}}},fp="15,300,30.371.0,20.475.0,24.358.0,34.213.0,32.160.0,50.237.0,22.207.0,49.205.0,42.209.0"}
P.entries["quest:124"] = {n="Виття гнолів",s="Вернер Осґуд, власник стайні в Лейкширі, бачить, що його справа опинилася в облозі: гноли роблять набіги на південь із передгір'їв Редріджу. І без того виснажений нападами орків Блекрок, він просить мандрівників винищити громил і містиків, що загрожують його худобі.",h="Вернер Осґуд, власник стайні в Лейкширі, бачить, що його справа опинилася в облозі: гноли роблять набіги на...",kw={"виття гнолів","вернер осґуд","гноли","стайня","лейкшир","редрідж"},ang={["class:Hunter"]="Без належного відстрілу дикі звірі й здичавілі зграї Редріджу зухвалішали й стали непередбачуваною загрозою для свійських тварин і подорожніх.",["faction:Alliance"]="Кожна маленька громада південного королівства відчуває на собі байдужість Стормвінда, тож скромні ремісники на кшталт Вернера змушені власним коштом наймати допомогу, щоб захистити найважливіші шляхи постачання."},sec={{t="Коні на хребті",b="Тримати стайню в Лейкширі стає дедалі небезпечніше. Орки Блекрок панують на висотах краю, а довколишніми хребтами нишпорять зграї гнолів. Для Вернера Осґуда терпець урвався, коли зухвалі ватаги гнолів підкралися до північних меж його загонів і почали полювати на коней, що підходили надто близько до урвищ."},{t="Злагоджена загроза",b="Це не просто розрізнені падальники. Зграї, що діють просто на північ від містечка, поєднують дику силу з примітивним чаклунством: дужі громили валять здобич, а містики орудують дикою магією. Проріджуючи їхні лави, можна дати поселенню короткий перепочинок, хоча невдовзі стає ясно, що за їхньою агресією стоїть якась більша сила, що ховається вище в пагорбах."}},faq={{q="Чому Вернерові Осґуду потрібна допомога з гнолами?",a="Гноли з північних кряжів почали підбиратися до Вернерових стаєнь і крадуть коней, щойно ті відійдуть від загонів. Через цю загрозу й навалу орків Блекрок він не може вберегти своїх тварин без сторонньої допомоги.",al={"проблема вернера з гнолами","чому вернер хоче вбити гнолів","гноли біля стайні лейкшира"}},{q="Де ці гноли?",a="Громили й містики Редріджу никають піднятими кряжами й передгір'ями просто на північ і схід від Лейкширу, звідки видно містечко й дорогу до мосту через Незрушне.",al={"де гноли","де редріджські бугаї","гноли на північ від стайні"}},{q="Чому гноли — проблема на додачу до орків Блекрок?",a="Хоча клан Блекрок — головна військова сила, що загрожує Редріджу, місцеві зграї гнолів користаються з метушні. Захисників Лейкширу обмаль, Стормвінд майже не шле підкріплень, тож місцеві хижаки безперешкодно розплодилися аж до околиць селища.",al={"чому гноли додаткова проблема","орки й гноли редрідж"}},{q="Що далі, коли розберешся з цими гнолами?",a="Коли громил і містиків поменшає, Вернер зауважує, що виття в пагорбах не вщухає, — а це вказує на загрозу від ватажка, з яким доведеться розібратися на довколишніх висотах.",al={"що після виття гнолів","продовження виття"}},{q="Чому містики особливо небезпечні?",a="Містики Редріджу практикують примітивну магію природи й стихій і обертають проти непроханих гостей непередбачувані, дикі закляття. Те, що вони є серед громил, свідчить про організований клан, а не про самотніх диких падальників.",al={"чому містики небезпечні","містики редріджу"}},{q="Чи посилає Стормвінд вояків захищати стайні Лейкширу?",a="Ні. Королівський двір Стормвінда серед тривалого політичного безладу й нестачі військ здебільшого лишив Редрідж боронитися самотужки, тож Магістратові Соломону й мешканцям на кшталт Вернера Осґуда доводиться наймати мандрівних шукачів пригод.",al={"чи стормвінд захищає стайні","вартові стормвінда редрідж"}}},fp="18,257,19.373.0,20.393.1,45.234.0,31.178.0,53.285.0,43.190.1,39.225.0,61.215.0"}
P.entries["quest:1241"] = {n="Зниклий дипломат",s="Після того як дипломат Альянсу так і не прибув на Острів Терамор, у Стормвінді починається термінове й потайне розслідування. Єпископ ДеЛаве підозрює підступи Дефіас і відсилає довірених агентів порадитися з Йорґеном — тихим зв'язковим, що тримається в Долині Героїв.",h="Після того як дипломат Альянсу так і не прибув на Острів Терамор, у Стормвінді починається термінове й...",kw={"зниклий дипломат","єпископ делаве","йорґен","острів терамор","братство дефіас","розслідування"},ang={["class:Priest"]="Єпископ ДеЛаве використовує церковні зв'язки, щоб потай розслідувати державні злочини, коли звичні королівські канали можуть бути скомпрометовані.",["class:Rogue"]="Пошуки зниклих посланців через непомітних інформаторів на кшталт Йорґена оголюють підпільне шпигунство, що вирує під бездоганними вулицями Стормвінда.",["faction:Alliance"]="Зникнення королівського дипломата ставить під загрозу делікатні перемовини між королівством Стормвінд і твердинею Леді Джайни Праудмур у Тераморі.",["race:Human"]="Загроза з боку Братства Дефіас б'є просто в стабільність людського королівства — вона сягає далеко за межі Вестфолу, аж до самої столиці."},sec={{t="Зникнення в тіні",b="Високопоставлений дипломат вирушив зі Східних Королівств на Острів Терамор, щоб провести делікатні перемовини з Леді Джайною Праудмур. Та посланець зник, так і не ступивши на берег. Поки королівські слідчі прочісують Стормвінд у пошуках слідів, зникнення тримають у суворій таємниці — щоб не здійняти паніки й не сполохати змовників, які, можливо, стежать за кожним кроком корони."},{t="Приватні розпити",b="Певний, що до викрадення дипломата причетне Братство Дефіас, Єпископ ДеЛаве вирішує не покладатися лише на офіційну королівську варту. Натомість він звертається до неофіційних і потайних каналів — до Йорґена, давнього знайомого, що непомітно рибалить у Долині Героїв одразу за міською брамою."},{t="Неохочий інформатор",b="Йорґен тримається похмуро й ховається за непримітною личиною біля міських вод, проте шанує давні зобов'язання перед ДеЛаве. Розуміючи, наскільки небезпечна ця загадка, Йорґен ясно дає зрозуміти: хто піде слідом дипломата, той ризикує життям, — і вимагає цілковитого мовчання від кожного, кого втягнуто в розслідування."}},faq={{q="Хто такий зниклий дипломат?",a="Церква Світла й трон Стормвінда ретельно приховують, хто цей посланець, і офіційно називають його лише важливим дипломатом, посланим через Велике Море до Терамора.",al={"хто зниклий дипломат","хто зник","ким є дипломат","особа дипломата"}},{q="Навіщо дипломат їхав до Терамора?",a="Дипломатові доручили зустрітися з Леді Джайною Праудмур для важливих перемовин про безпеку й стан Альянсу між Східними Королівствами й Калімдором.",al={"навіщо дипломат до терамору","чому терамор","мета дипломата"}},{q="Кого підозрює Єпископ ДеЛаве?",a="Єпископ ДеЛаве підозрює, що викрадення влаштувало Братство Дефіас, хоча як саме вони діяли й хто їхні спільники в місті, досі невідомо.",al={"кого підозрює делаве","хто забрав дипломата","хто викрав дипломата"}},{q="Хто такий Йорґен?",a="Йорґен — агент і давній довірений знайомий Єпископа ДеЛаве, що непримітно сидить із вудкою біля води в Долині Героїв у Стормвінді.",al={"де йорґен","хто такий йорґен","хто рибалка"}},{q="Чому справу приховують від людей?",a="Звістка, що важливого посланця викрали під самим носом у трону, посіяла б хаос і попередила б змовників, що королівські агенти вже на них полюють.",al={"чому справу приховують","чому таємниця","чому не сказати місту"}},{q="Куди веде це розслідування?",a="Йорґен дає подальші настанови: копнути глибше в злочинний світ і приховані мережі довкола Стормвінда, щоб з'ясувати, де перехопили дипломата.",al={"куди веде розслідування","що далі"}}},fp="20,268,26.386.0,17.332.0,21.313.1,28.183.0,44.170.0,32.146.0,14.154.0,46.161.0,35.152.0"}
P.entries["quest:1243"] = {n="Зниклий дипломат",s="Цей етап розслідування зникнення посланця Стормвінда веде вас на південь, у похмурий край Сутінколісся. Спираючись на сліди, здобуті в столиці, знавець сирів Еллінг Тріас доручає вам розшукати Вартового Бакуса біля Даркширу й з'ясувати, що там затівають Дефіас.",h="Цей етап розслідування зникнення посланця Стормвінда веде вас на південь, у похмурий край Сутінколісся.",kw={"зниклий дипломат","еллінг тріас","вартовий бакус","сутінколісся","нічна варта","братство дефіас"},ang={["class:Rogue"]="Еллінг Тріас показує, як бувалі агенти керують мережами: збирати розвіддані відсилають незалежних виконавців, а власні руки лишаються чистими.",["faction:Alliance"]="Зникнення дипломата б'є в саме серце королівських інтересів Стормвінда й змушує героїв діяти злагоджено з королівськими шпигунами, вільними пройдисвітами й місцевими ополченнями."},sec={{t="Біганина в сутінках",b="Після невтішної розмови з Йорґеном сироторговець Еллінг Тріас вирішує вдатися до ширшої мережі своїх інформаторів. Замість того щоб марнувати власні гроші на професійних агентів, він доручає всю біганину вам. Ви маєте віднести запечатаного листа через кордон у Сутінколісся — темний край, який облягають звірі, нежить і дещо гірше."},{t="Дружня душа в Нічній Варті",b="Ваша мета — Вартовий Бакус, член Нічної Варти, що патрулює північні підступи до Даркширу. Хоч Сутінколісся й небезпечне для звичайних мандрівників, Тріас покладається на Бакуса як на надійне джерело відомостей про незаконні пересування. Запечатана депеша відчиняє вам доступ до записів місцевої варти й до чуток про діяльність Братства Дефіас на півдні."}},faq={{q="Чому Еллінг Тріас посилає мене в Сутінколісся?",a="Еллінг Тріас перевіряє кожну можливу зачіпку щодо зниклого дипломата й підозрілих дій Братства Дефіас. Щоб заощадити гроші, поки задіює свої зв'язки, він посилає вас розпитати Вартового Бакуса в Сутінколіссі про новини з місця.",al={"чому тріас посилає в сутінколісся","доручення тріаса в сутінколіссі","чому даркшир"}},{q="Де знайти Вартового Бакуса?",a="Вартовий Бакус патрулює північну ґрунтову дорогу одразу за Даркширом у Сутінколіссі, пильнуючи шлях до Редріджу й Лісу Елвінн.",al={"місце бакуса","де бакус","знайти вартового бакуса"}},{q="Хто такий Вартовий Бакус?",a="Вартовий Бакус — вояк міського ополчення Даркширу, Нічної Варти. Він також особистий знайомий Еллінга Тріаса й готовий поділитися спостереженнями про підозрілих мандрівників і злочинців у краї.",al={"лор бакуса","хто такий бакус"}},{q="Що в запечатаній записці для Бакуса?",a="У записці — таємні запити Еллінга Тріаса про будь-які відомості щодо появи чи пересувань Братства Дефіас у Сутінколіссі.",al={"вміст запечатаної записки","що в записці","записка вартовому бакусу"}},{q="Що спільного в Сутінколісся з Братством Дефіас?",a="Хоча осередок Дефіас у Вестфолі, а сховок — під Мертвими Копальнями, вони мають осередки, гінців і схованки по всіх південних людських провінціях, зокрема й на темних околицях Сутінколісся.",al={"дефіас у сутінколіссі","чи є дефіас у сутінколіссі"}},{q="Чому Тріас нарікає на Йорґена?",a="Раніше під час розслідування Йорґен упирався чи вимагав надто багато, і це так дратує Тріаса, що він посилає Йорґена до Викривленого Нижнього Світу, а сам звертається до інших своїх людей на місцях.",al={"хто такий йорґен","тріас і йорґен"}}},fp="20,284,21.390.0,33.415.0,43.250.0,32.150.0,22.215.0,43.170.0,58.213.0,37.190.0"}
P.entries["quest:1244"] = {n="Зниклий дипломат",s="Цей етап розслідування веде агентів Альянсу в тіні Сутінколісся слідом за зниклим посланцем Стормвінда. Спираючись на відомості Вартового Бакуса, слідчі мають обшукати занедбаний Хутір Аддла й знайти папери Дефіас.",h="Цей етап розслідування веде агентів Альянсу в тіні Сутінколісся слідом за зниклим посланцем Стормвінда.",kw={"зниклий дипломат","реєстр дефіас","хутір аддла","сутінколісся","вартовий бакус","дефіас"},ang={["class:Rogue"]="Орієнтуватися в злочинних мережах і розплутувати підкинуті паперові сліди — означає вміти відрізнити справжні розвіддані від хитрих обманок Дефіас.",["faction:Alliance"]="Зникнення посланця королівства б'є в саме серце безпеки Стормвінда й доводить, що інтриги Дефіас сягають куди далі за дрібний розбій на дорогах Вестфолу."},sec={{t="Слід у сутінках",b="Шепіт про змову веде пошуки зниклого дипломата за мури Стормвінда — аж до Нічної Варти в Сутінколіссі. Вартовий Бакус зауважує: хоча розбійники Дефіас зазвичай тримаються свого боку кордону, кілька тижнів тому на Хуторі Аддла їх зібралося незвично багато. Для організації, що діє переважно у Вестфолі, таке скупчення в темних лісах свідчить: на тій покинутій фермі сталося щось дуже важливе."},{t="Реєстр Дефіас",b="Обшук захопленого хутора приносить замкнену скриню, а в ній — Реєстр Дефіас. Папери підтверджують причетність Братства, та Бакус застерігає: з такими змовниками треба бути насторожі — документи цілком можуть виявитися підробкою, покликаною завести надокучливих слідчих у глухий кут."}},faq={{q="Де розташований Хутір Аддла?",a="Хутір Аддла лежить у західному Сутінколіссі, трохи на південь від головної дороги, що веде в край із Вестфолу. Це занедбана садиба, яку зараз зайняли ворожі агенти Дефіас.",al={"місце хутора аддла","де хутір аддла","знайти хутір аддла"}},{q="Що таке Реєстр Дефіас?",a="Реєстр Дефіас — стос офіційних на вигляд паперів, що лежить у скрині в будинку на Хуторі Аддла. У ньому описано деякі подробиці недавніх таємних дій Братства в краї.",al={"реєстр дефіас","що в реєстрі","документ хутора аддла"}},{q="Хто такий Вартовий Бакус?",a="Вартовий Бакус — член Нічної Варти в Сутінколіссі. Маючи знайомих у місті й пильнуючи загрози на кордоні, він допомагає вистежувати незвичні пересування Дефіас уздовж межі з Вестфолом.",al={"вартовий бакус","хто такий бакус","бакус сутінколісся"}},{q="Що Дефіас роблять у Сутінколіссі?",a="Хоча їхня твердиня за кордоном, у Вестфолі, агенти Дефіас частенько тихо пробираються в західне Сутінколісся. Хутір Аддла править їм за відлюдний, затишний перевалочний пункт, далеко від патрулів Стормвінда.",al={"чому дефіас у сутінколіссі","дефіас на хуторі аддла"}},{q="Чи можна довіряти тому, що в Реєстрі Дефіас?",a="Сам Вартовий Бакус, оглянувши його, радить обережність. Документ виглядає справжнім, але Дефіас — хитрі змовники, здатні підкинути фальшиві сліди, щоб збити слідчих з пантелику.",al={"чи реєстр справжній","підробка реєстру","чи це липа"}},{q="Хто першим скерував розслідування до Вартового Бакуса?",a="Вартовий Бакус зауважує, що розслідування до Нічної Варти в Сутінколіссі скерував Еллінг Тріас — торговець сиром і таємний посередник у торгівлі відомостями в Стормвінді.",al={"хто послав до бакуса","зв'язок тріаса"}}},fp="20,274,19.478.0,17.315.1,31.175.0,26.202.0,22.210.0,41.219.0,49.205.0,59.182.0"}
P.entries["quest:1247"] = {n="Зниклий дипломат",s="Цей етап розслідування зникнення посланця Стормвінда настає після допиту Дешела Стоунфіста в Старому Місті. Вибивши з головоріза зізнання, ви несете звістку про запасний план викрадення назад до майстра шпигунства, що вдає знавця сирів, — Еллінга Тріаса.",h="Цей етап розслідування зникнення посланця Стормвінда настає після допиту Дешела Стоунфіста в Старому Місті.",kw={"зниклий дипломат","дешел стоунфіст","еллінг тріас","гавань менетіл","худий","багнокрай"},ang={["class:Rogue"]="Для агента тіні робота між провулковими громилами на кшталт Дешела й майстрами шпигунства на кшталт Тріаса показує, яка тонка межа між звичайним вуличним злочином і великою державною грою.",["faction:Alliance"]="Розкрити зникнення посланця — життєво важливо для стабільності всього Альянсу, адже диверсія на найвищому рівні загрожує верхівці Стормвінда.",["race:Human"]="Змова розгортається просто в межах столиці й доводить, що зрада загніздилася в королівстві Стормвінд, поки на троні сидить юний король."},sec={{t="Тріщина в мурі",b="Дешел Стоунфіст не з тих, хто забирає таємниці в могилу, — надто коли переконається, що на кону його здоров'я. Притиснутий до стіни за дешевою крамничкою в Старому Місті, Дешел здається й визнає: його роль у викраденні пішла прахом, щойно перший план змовників розвалився. Відчайдушно намагаючись зняти з себе провину, він розповідає про таємну зустріч кількатижневої давнини на Хуторі Аддла в Сутінколіссі й видає єдину ниточку до їхнього запасного плану: спільника в Гавані Менетіл, відомого лише як «Худий»."},{t="Звіт знавцеві сирів",b="Еллінг Тріас скромно стоїть за прилавком крамниці «Сири Тріаса» в Торговому Кварталі, але справжнє його ремесло — збирати таємниці для Корони. Поки ви витрушували подробиці з Дешела, Тріас вивчав перехоплені листи про змову. Зізнання Дешела збігається з письмовими розвідданими: ціллю був безіменний дипломат, головна засідка зірвалася, і запасний план запустили через Багнокрай. Тепер, коли відоме прізвисько «Худий», пошуки переходять із темних провулків Стормвінда на північ, до боліт."}},faq={{q="Хто такий Дешел Стоунфіст?",a="Дешел Стоунфіст — місцевий громило й ділок зі Старого Міста в Стормвінді. Заплутаний у злочинному світі, пов'язаному з Дефіас, він був рядовим виконавцем у першому задумі захопити посланця Стормвінда, а коли його приперли до стіни, став інформатором.",al={"дешел стоунфіст","хто такий дешел","стоунфіст стормвінд"}},{q="Чому до цього розслідування причетний Еллінг Тріас?",a="Для всіх Еллінг Тріас — знавець вишуканих сирів, а насправді він один із досвідчених розвідників Стормвінда. Свою крамницю в Торговому Кварталі він використовує як прикриття для таємних розслідувань, що потребують більшої делікатності, ніж може дати офіційна міська варта.",al={"чому тріас у розслідуванні","торговець сиром шпигун","розвідка тріаса"}},{q="Що сталося на Хуторі Аддла?",a="Хутір Аддла — покинута садиба в західному Сутінколіссі, де змовники за кілька тижнів до того збиралися, щоб узгодити свої плани викрадення, після того як їхній перший хід зірвався.",al={"що сталося на хуторі аддла","зустріч на хуторі аддла","зустріч у вестфолі"}},{q="Кого саме вони намагалися викрасти?",a="Офіційні документи й вуличні головорізи називають ціль лише безіменним дипломатом, що прямував до Терамора. Хто цей посланець насправді, на цьому етапі розслідування ретельно приховують.",al={"кого намагалися викрасти","хто зниклий дипломат","кого викрали"}},{q="Хто такий Слім?",a="Слім — посередник, якого назвав Дешел Стоунфіст: агент, що відповідає за «План Б» у Гавані Менетіл у Багнокраї, — запасний шлях змовників.",al={"хто такий слім","слім менетіл","контакт у менетілі"}},{q="Куди веде слід далі?",a="Знаючи ім'я Сліма й маючи підтвердження Еллінга Тріаса, розслідування переноситься на північ, до портового містечка Гавань Менетіл у Багнокраї, щоб вистежити цього посередника.",al={"наступний крок зниклого дипломата","куди після дешела","що далі"}}},fp="20,273,19.518.0,25.547.1,24.256.0,51.254.0,31.184.0,47.203.2,12.183.0,37.173.0"}
P.entries["quest:125"] = {n="Загублені інструменти",s="Лейкшир під тиском ворожих сил, і лад та оборона в містечку тримаються лише на місцевих руках. Важливі інструменти Бригадира Ослоу, привезені з Ґолдширу, пропали, коли катапульта Блекрок потопила човен, що перевозив їх через Озеро Незрушне. Дістати затонулу скриню з дна озера вкрай важливо, щоб відбудувати зруйнований міст містечка.",h="Лейкшир під тиском ворожих сил, і лад та оборона в містечку тримаються лише на місцевих руках.",kw={"загублені інструменти","бригадир ослоу","озеро незрушне","мурлоки","міст","лейкшир"},ang={["faction:Alliance"]="Лейкшир — східний бастіон Альянсу проти клану Блекрок; щоб утримати рубежі королівства Стормвінд, цивільні будівельники мусять мати своє знаряддя.",["profession:Blacksmithing"]="В облозі добрі інструменти викувати важко, тож повернення особливого ковальського й будівельного знаряддя з Ґолдширу для містечка незамінне."},sec={{t="Невдала доставка",b="Зруйнування Великого мосту перерізало Лейкширу життєво важливий зв'язок із Лісом Елвінн. Коли з Ґолдширу суходолом відправили новий набір мулярських і теслярських інструментів, вантаж не міг потрапити просто в містечко. Візники перевантажили припаси в човен, щоб переправитися через Озеро Незрушне, але катапульта орків Блекрок поцілила просто в нього. Човен розтрощило, а важка, окута залізом скриня Ослоу пішла на саме дно глибокого озера."},{t="Небезпеки глибин",b="Дістати скриню значно небезпечніше, ніж просто пірнути. У водах Озера Незрушного кишать агресивні племена мурлоків, що нишпорять на мілинах, а в каламутних глибинах полюють хижі молотильники. Попри небезпеку, інструменти треба повернути, якщо Бригадир Ослоу має відновити ремонт мосту й не дати Лейкширу остаточно перетворитися на руїну."}},faq={{q="Чому інструменти взагалі відправили човном?",a="Головна дорога в Лейкшир перетинає кам'яний міст через Озеро Незрушне, але орки Блекрок висадили в повітря великий його проліт. Вози з припасами з Ґолдширу вже не могли переїхати, тож робітники мусили вивантажити інструменти й спробувати переправити їх водою.",al={"чому інструменти човном","як потонули інструменти","чому озером"}},{q="Як потонув човен?",a="Коли човен перепливав озеро, його обстріляли орки Блекрок: снаряд катапульти з довколишніх висот влучив просто в нього, і човен разом із вантажем миттю пішов на дно.",al={"як потонув човен","хто знищив човен"}},{q="Хто такий Бригадир Ослоу?",a="Бригадир Ослоу — головний будівничий і наглядач Лейкширу. Він відповідає за громадські роботи й лад у місті, а найнагальніше — за відбудову зруйнованого мосту.",al={"бригадир ослоу","роль ослоу"}},{q="Які загрози таяться в Озері Незрушному?",a="Озеро населяють ворожі племена мурлоків, що патрулюють біля берегів і руїн, а також люті хижі озерні молотильники, що полюють на відкритій воді й у глибинах.",al={"що в озері незрушному","озерні чудовиська","небезпека озера"}},{q="Чому Лейкширу так конче потрібні ці інструменти?",a="Лейкшир фактично в облозі, відрізаний від швидкого підкріплення й звичних поставок. Без важких інструментів Ослоу не може ні відбудувати міст, ні полагодити укріплення, потрібні, щоб стримувати орків і гнолів.",al={"чому інструменти потрібні","інструменти для ремонту мосту"}},{q="Куди веде це завдання далі?",a="Коли ящик з інструментами повернуто, Бригадир Ослоу залучає шукачів пригод зібрати будівельні матеріали для ремонту Великого Мосту в наступному завданні — «Міст Незрушного».",al={"куди далі","що після загублених інструментів"}}},fp="14,350,20.485.0,19.373.0,51.268.0,22.202.0,21.191.0,35.178.0,45.220.0,31.182.1"}
P.entries["quest:126"] = {n="Виття серед пагорбів",s="Виття серед пагорбів — нагорода Альянсу, яку Вернер Осґуд у Лейкширі призначив за Йоулера, грізного ватажка гнолів Редріджу. Військо Стормвінда надто розпорошене боротьбою з орками Блекрок, щоб захищати місцеві кордони, тож Лейкшир покладається на мандрівних шукачів пригод, які мають позбавити зграю гнолів проводу.",h="Виття серед пагорбів — нагорода Альянсу, яку Вернер Осґуд у Лейкширі призначив за Йоулера, грізного ватажка...",kw={"виття серед пагорбів","йоулер","вернер осґуд","гноли","лейкшир","редрідж"},ang={["class:Hunter"]="Щоб вистежити такого ватажка, як Йоулер, у його гірському лігві, потрібне гостре око на мітки території й знання звичок зграї.",["class:Warrior"]="Вийти проти Йоулера — означає зітнутися із супротивником, який править своєю лютою зграєю завдяки самій лише фізичній перевазі; тут вирішує груба сила в чесному двобої.",["faction:Alliance"]="Те, що Лейкшир покладається на найманців, а не на королівських солдатів, оголює глибоку управлінську кризу, яка нині послаблює королівство Стормвінд."},sec={{t="Голос на висотах",b="Навіть після того, як дрібніших гнолів, що грабували стежки довкола Лейкширу, проріділи, їхнє зловісне виття й далі лунає хребтами Редріджу. Вернер Осґуд, працьовитий коваль-підковувач Лейкширу, розуміє: убивством розвідників і падальників навалу не спинити, доки живий ватажок зграї. Над цим збіговиськом височіє Йоулер — надзвичайно хитрий і величезний гнол, чиє виття спрямовує зграю пагорбами. Вернер доручає шукачам пригод вистежити звіра й відрубати йому лапу, щоб виття затихло раз і назавжди."},{t="Містечко, яке покинуло військо",b="Це доручення висвітлює похмуру дійсність, що спіткала східні кордони королівства Стормвінд. Король Варіан Рінн зник, суперечки довкола регентства паралізували верховне командування, і королівські солдати зосередилися майже виключно на кланах орків Блекрок, що окопалися на півночі. Звичайні поселення на кшталт Лейкширу лишилися зовсім беззахисними перед місцевими загрозами, як-от гноли, тож містяни на кшталт Вернера Осґуда самі призначають нагороди, щоб їхні домівки не захопили."}},faq={{q="Хто такий Йоулер?",a="Йоулер — лютий ватажок гнолів Редріджу, що никають пагорбами довкола Лейкширу. Вернер Осґуд зауважує, що Йоулер куди сильніший і небезпечніший за звичайних шавок: він — вожак, що згуртовує зграю й спрямовує її проти мандрівників і місцевих садиб.",al={"йоулер","хто бос гнолів","лор йоулера","гноль йоулер"}},{q="Чому винагороду призначає Вернер Осґуд, а не міська варта?",a="Офіційний провід Лейкширу й місцеве ополчення цілком поглинуті натиском орків Блекрок. Вернер Осґуд — місцевий ремісник і доглядач стаєнь, чий прожиток залежить від безпечних доріг, — частенько сам наймає мандрівних найманців, щоб позбутися нагальних місцевих небезпек.",al={"чому вернер а не варта","чому не соломон","чому осґуд наймає"}},{q="Де вояки Стормвінда, які мали б захищати Лейкшир?",a="Постійне військо Стормвінда зайняте деінде. Сили армії в Редріджі прикуті до того, щоб стежити за орками клану Блекрок вище в горах і стримувати їх, тож мешканцям не лишається жодної підтримки проти місцевої звірини, мурлоків і гнолів.",al={"де армія стормвінда","чому немає вартових стормвінда","військо стормвінда лейкшир"}},{q="Що буде з гнолами Редріджу, коли Йоулер загине?",a="Смерть Йоулера розладнає командування зграї гнолів і притупить злагоджені напади на околиці міста. Проте гноли лишаються впертою й довготривалою напастю на скелястих висотах Редріджу.",al={"чи залишили гноли","що буде після йоулера"}},{q="Які завдання ведуть до цього доручення?",a="Ланцюжок починається з того, що Вернер Осґуд посилає вас по спорядження для коней у завданнях «Ціна підків» і «Повернення до Вернера». Після луски з пуза й проріджування зграї у «Виття гнолів» Вернер доручає вам полювати просто на Йоулера.",al={"передумови йоулера","відкрити виття серед пагорбів","ланцюжок виття серед пагорбів"}},{q="Навіщо Вернерові лапа Йоулера як доказ?",a="Винагороду за небезпечних звірів платять лише за незаперечний речовий доказ. Відтята лапа Йоулера доводить Вернерові й стривоженим мешканцям Лейкширу, що жахливий звір, чиє виття лунало пагорбами, справді впав.",al={"навіщо лапа йоулера","лапа йоулера як доказ"}}},fp="20,327,24.551.0,28.490.0,14.268.0,67.294.0,68.259.0,56.213.0,50.271.0,43.255.0"}
P.entries["quest:127"] = {n="Торгівля рибою",s="Доглядач Пристані Барен порядкує на жвавій пристані Лейкширу, але знайти свіжий товар для торгівлі стає дедалі важче. Він платить мандрівникам за плямисту рибу-сонце — цінний місцевий улов Озера Незрушного, по який тепер небезпечно ходити через мурлоків, що підступають усе ближче.",h="Доглядач Пристані Барен порядкує на жвавій пристані Лейкширу, але знайти свіжий товар для торгівлі стає...",kw={"торгівля рибою","доглядач пристані барен","плямиста риба-сонце","озеро незрушне","мурлоки","лейкшир"},ang={["faction:Alliance"]="Королівство Стормвінд майже не допомагає Редріджу військом, тож навіть прохарчування містечка тримається на незалежних мандрівниках Альянсу, що підставляють плече.",["profession:Cooking"]="Лейкшир славиться вишуканими прісноводними стравами на кшталт плямистої риби-сонця, тож місцеві води завжди приваблюють кухарів-початківців."},sec={{t="Окраса Озера Незрушного",b="Озеро Незрушне славиться на всю округу плямистою рибою-сонцем — ніжним уловом, на який завжди є попит серед містян і заїжджих купців. Та попри достаток під поверхнею озера, запаси містечка раз у раз вичерпуються. Лейкшир виснажений місцевими загрозами, тож навіть звичайна торгівля не обходиться без вільних шукачів пригод."},{t="Біда на мілинах",b="Зазвичай місцеві рибалки без зусиль виконували б замовлення Доглядача Пристані Барена. Однак агресивні племена мурлоків, що розплодилися на мілинах і берегах, відігнали простих містян від води. Мандрівникам, які візьмуться за прохання Барена, доведеться або закидати вудки самим, пильнуючи спину, або відбирати улов просто в мурлоків, що нишпорять узбережжям."}},faq={{q="Хто такий Доглядач Пристані Барен?",a="Доглядач Пристані Барен відає причалами й рухом човнів на Озері Незрушному в Лейкширі. Він керує торгівлею з води й покладається на вправних мандрівників, щоб здобувати свіжу рибу й прибирати загрози довкола озера.",al={"доглядач пристані барен","барен","хто доглядач пристані"}},{q="Чому плямиста сонячна риба така затребувана?",a="Озеро Незрушне славиться плямистою сонячною рибою, тож це основний делікатес і важливий товар для Лейкширу. Запаси Доглядача Пристані Барена тануть, бо звичайні міські рибалки не можуть безпечно рибалити, поки озеро кишить ворогами.",al={"чому сонячна риба затребувана","плямиста сонячна риба","чому лейкшир хоче рибу"}},{q="Як сонячна риба опиняється в мурлоків?",a="Племена мурлоків на Озері Незрушному збирають їжу й полюють на мілинах. Убиваючи чи проганяючи місцевих рибалок, вони складають рибу у своїх таборах, і ці запаси так і просяться до рук шукачам пригод, яким битися миліше, ніж закидати вудку.",al={"як риба в мурлоків","мурлоки крадуть рибу","мурлоки з рибою"}},{q="Де знайти плямисту сонячну рибу?",a="Плямиста сонячна риба живе у водах Озера Незрушного в Горах Редріджу. Її можна виловити вудкою або забрати в мурлоків, що живуть на берегах і мілинах озера.",al={"де сонячна риба","рибу озера незрушного","як отримати плямисту рибу"}},{q="Як це завдання пов'язане з «Мурлоками-браконьєрами»?",a="Доглядач Пристані Барен дає обидва завдання водночас. Мурлоки никають озером і браконьєрствують, тож, розбираючись із браконьєрами, ви заразом повертаєте плямисту сонячну рибу, яку вони витягли з води.",al={"зв'язок із мурлоками-браконьєрами","інше завдання барена","завдання доглядача пристані"}},{q="Чи треба рибалити, щоб допомогти Доглядачеві Пристані Барену?",a="Ні, вудка чи навичка рибальства не потрібні. Риболовля — мирний спосіб здобути плямисту сонячну рибу, але Доглядач Пристані Барен відверто радить відібрати її силою в племен мурлоків, що полюють на озері.",al={"чи потрібне рибальство","без вудки","рибальство обов'язкове"}}},fp="12,269,26.402.0,23.397.0,24.218.0,44.251.0,39.261.0,35.199.0,45.218.0,45.198.0"}
P.entries["quest:1274"] = {n="Зниклий дипломат",s="«Зниклий дипломат» — перший крок одного з найважливіших і найделікатніших розслідувань Стормвінда. Справа, про яку вам потай повідомляють просто на міській вулиці, веде прямо до Єпископа ДеЛаве у Фортеці Стормвінда. Церкві й короні потрібні вправні руки для справи, надто небезпечної, щоб довірити її відкритим каналам.",h="«Зниклий дипломат» — перший крок одного з найважливіших і найделікатніших розслідувань Стормвінда.",kw={"зниклий дипломат","єпископ делаве","томас","фортеця стормвінда","розслідування","варіан рінн"},ang={["faction:Alliance"]="Розгадати таємницю зниклого дипломата — життєво важливо для цілісності й оборони Альянсу: це викриває глибокі загрози, що вкоренилися при самому дворі Стормвінда.",["race:Human"]="Для людей Стормвінда це доручення зачіпає саму стабільність вашої батьківщини в час хиткого регентства."},sec={{t="Тихий виклик",b="Надійним шукачам пригод, що мандрують Стормвіндом, може трапитися непримітний служка на ім'я Томас із тихим проханням. Єпископу ДеЛаве, шанованому служителю Церкви Святого Світла у Фортеці Стормвінда, потрібна допомога когось стороннього. Справу описують лише як делікатну й нагальну: вона вимагає цілковитої таємності, щоб не посіяти паніки серед людей."},{t="Шепіт у Фортеці",b="Коли ви відгукуєтеся на виклик у Фортеці Стормвінда, Єпископ ДеЛаве пояснює, звідки така таємність. Високопоставлений сановник королівства зник за загадкових обставин. У час, коли всередині країни назріває невдоволення, а король Варіан Рінн загадково зник, будь-який натяк на злочин на найвищому рівні загрожує розхитати крихкий мир королівства."}},faq={{q="Хто такий Томас?",a="Томас — юний служка в Соборі Світла, що виконує доручення Єпископа ДеЛаве. Він пильно придивляється до вправних шукачів пригод на вулицях міста й тихо спрямовує їх до Фортеці Стормвінда, щойно делікатні справи Церкви чи держави потребують надійних посередників.",al={"хто такий томас","томас стормвінд","давець томас"}},{q="Хто такий Єпископ ДеЛаве?",a="Єпископ ДеЛаве — високий духовний сан Церкви Святого Світла у Фортеці Стормвінда. Разом із королівським двором він займається делікатними питаннями безпеки королівства й розслідуваннями, яких звичайна міська варта не може вести відкрито.",al={"хто такий делаве","єпископ делаве","делаве"}},{q="Чому цю справу ведуть таємно?",a="Стормвінд і так на нервах: Король Варіан Рінн зник, а Братство Дефіас роздмухує заколот по всьому Вестфолу. Якщо пошириться звістка, що зник ще один помітний дипломат чи урядовець, це може посіяти загальну паніку чи відкрити ворогам слабкі місця двору.",al={"чому таємно","чому секретність","чому конфіденційно"}},{q="Куди веде це розслідування?",a="Зустріч із Єпископом ДеЛаве у Фортеці Стормвінда починає довге розслідування, що заводить вас у саме серце політики королівства — вулицями Стормвінда, довколишніми людськими землями й далі, у підступні краї за морем.",al={"куди веде розслідування","зниклий дипломат далі"}},{q="Хто такий зниклий дипломат?",a="На початку розслідування Єпископ ДеЛаве ретельно приховує, хто цей дипломат. Розголос загрожував би розслідуванню й наражав би на небезпеку і зниклого урядовця, і королівство.",al={"хто дипломат","особа зниклого дипломата"}}},fp="20,334,15.391.0,20.366.1,14.280.0,22.255.0,37.274.0,35.275.0,28.229.0"}
P.entries["quest:1275"] = {n="Дослідження скверни",s="Ґершала Найтвіспер в Обердайні шукає уражені стовбури мозку істот, що заполонили Чорноглибинні Печери. Стривожений чутками, що ельфи крові за морем бавляться з демонічною магією, він хоче простежити, як занепадали тіла наг і сатирів, щоб передбачити — а може, й відвернути — нову згубну переміну ельфів.",h="Ґершала Найтвіспер в Обердайні шукає уражені стовбури мозку істот, що заполонили Чорноглибинні Печери.",kw={"ґершала найтвіспер","обердайн","чорноглибинні печери","сатири","наги","ельфи крові","високородні"},ang={["class:Druid"]="Друїди відчувають вроджену відразу до сатирів, чия Скверна паплюжить сон природи й калічить саму землю.",["class:Mage"]="Похмуре розслідування Ґершали суворо нагадує, якою фізичною й духовною ціною обертається безрозсудна, неприборкана залежність від магії.",["faction:Alliance"]="Альянс насторожено стежить за звістками про те, як ельфи крові за морем поринають у темні мистецтва, і боїться появи нової демонічної загрози.",["race:NightElf"]="Для нічних ельфів це дослідження торкається найболючішої рани їхньої історії — згубного переродження родичів на сатирів і наг, що досі терзають Калімдор."},sec={{t="Пересторога з минулого",b="Для нічних ельфів Калімдору загибель їхніх давніх родичів — жива пам'ять, викарбувана в подобі чудовиськ. Десять тисяч років тому Високородні піддалися спокусі демонічних енергій і спотворили самих себе: одні стали рогатими сатирами, інші пішли на дно й обернулися зміїстими нагами. Тож коли високі ельфи називають себе ельфами крові й беруться за темну магію, Ґершала Найтвіспер бачить у цьому не далеку дивовижу, а історію, якій судилося повторитися."},{t="У глибини",b="Чорноглибинні Печери — ідеальне місце для похмурих пошуків Ґершали. Під Зорамським Узмор'ям в Ашенвалі ховаються руїни підземного храму, де аж кишить сатирами-культистами та звитими в кільця нагами. Ґершала посилає шукача пригод добути стовбури мозку з тих і тих чудовиськ: він сподівається розтином з'ясувати, що пов'язує пристрасть до тайної магії, демонічну скверну й згубну переміну тіла."},{t="Відчайдушні ліки",b="Хоч методи Ґершали моторошно анатомічні, сам він каже, що прагне запобігти лиху. Він вірить: якщо розгадати, які саме зміни тіла спільні для сатирів і наг, можна здобути знання, що допоможуть відвести ельфів крові від остаточної загибелі. Чи здатні дослідження на Темному Узбережжі справді вплинути на зневірених ельфів Кель'Таласу — питання відкрите."}},faq={{q="Чому Ґершалу Найтвіспера турбують ельфи крові?",a="Ґершала боїться, що загравання ельфів крові з демонічними силами породить ще одну расу спотворених чудовиськ, які загрожуватимуть Азероту, — так само як колись ельфійська пиха породила сатирів і наг.",al={"чому ґершала допомагає кривавим ельфам","ґершала кривавоельфійський зв'язок","криваві ельфи оберін"}},{q="Де зібрати зіпсовані стовбури мозку?",a="Їх збирають із сатирів і наг, що живуть у Чорноглибинних Печерах — давньому храмовому комплексі, похованому на Зорамському Узмор'ї на північно-західному узбережжі Ашенвалю.",al={"де стовбури мозку","місце стовбурів мозку","падіння зіпсованих стовбурів мозку"}},{q="Чому йому потрібні саме зразки сатирів і наг?",a="І сатири, і наги походять від ельфів, спотворених неприродними силами: сатири — через угоди з демонами, наги — через Розкол. Ґершала хоче порівняти зміни їхнього мозку, щоб зрозуміти, як тіло ельфа занепадає під дією темної сили.",al={"чому сатири й наги","зв'язок сатирів і наг"}},{q="Хто веде до цього завдання?",a="До Ґершали Найтвіспера в Обердайні може привести вступне завдання «Скверна на чужині», хоча він пропонує це розслідування й безпосередньо.",al={"передумова завдання","зв'язок скверни за морем"}},{q="Що Ґершала збирається робити зі зразками?",a="Він хоче вивчити, як пов'язані між собою ці два види скверни в тілі, сподіваючись, що здобуте знання допоможе запобігти подальшому перетворенню ельфів крові на ще страхітливіших потвор.",al={"дослідження стовбурів мозку","мета досліджень ґершали"}},{q="Чи Чорноглибинні Печери прямо загрожують Обердайну?",a="Хоча Чорноглибинні Печери лежать одразу за південним кордоном, в Ашенвалі, нічні ельфи з Обердайна стежать за всім узбережжям, виглядаючи ознаки того, що скверна демонів і Присмерку посилюється.",al={"чому оберін турбується","чорноглибина загрожує темному узбережжю"}}},fp="26,328,22.436.0,14.404.0,16.379.1,58.190.0,46.171.0,53.260.0,27.175.0,49.187.0,54.194.0"}
P.entries["quest:128"] = {n="Винагорода за голови Блекроку",s="Винагорода за голови Блекроку — оборонне доручення, яке Вартовий Гоу в Лейкширі видає від імені Магістрата Соломона. Стормвінд не надсилає підкріплення, тож містечко платить незалежним шукачам пригод за знищення добірних поборників Блекрок, що збираються в північних горах. Убиваючи цих польових командирів, захисники прагнуть зламати злагоджений наступ орківського клану на Редрідж.",h="Винагорода за голови Блекроку — оборонне доручення, яке Вартовий Гоу в Лейкширі видає від імені Магістрата...",kw={"винагорода за голови блекроку","поборники блекрок","вартовий гоу","магістрат соломон","орки","лейкшир"},ang={["class:Warrior"]="Поборники Блекрок — важкоозброєні, досвідчені рубаки, з якими кожен бій випробовує дисципліну й витривалість воїна.",["faction:Alliance"]="Лейкшир — східний щит Стормвінда; якщо орки Блекрок прорвуться з цих гірських таборів, серцевинні ниви Альянсу опиняться просто під ударом.",["race:Human"]="Клан Блекрок зруйнував давнє королівство Стормвінд у Першій війні. Для людей-захисників не дати йому повернутися на південь — гірка необхідність, успадкована від предків."},sec={{t="Утримати рубіж королівства",b="Редрідж здавна перебуває під владою королівства Стормвінд, та клан Блекрок людських кордонів не визнає. Ринувши гірськими перевалами з Палаючих Степів, орки облаштували на півночі Редріджу добре укріплені табори. Король Варіан Рінн зник, регентство в Стормвінді не дає королівських солдатів, тож місцеві очільники на кшталт Магістрата Соломона змушені призначати нагороди з дедалі біднішої міської скарбниці, щоб захистити Лейкшир."},{t="Ціль — поборники",b="Вартовий Гоу вважає поборників Блекрок хребтом авангарду загарбників. Ці загартовані в боях ветерани очолюють загони у своїх військах, керують пересуванням бійців і женуть уперед рядових вояків. Призначивши ціну за їхні голови, захисники Лейкширу сподіваються позбавити клан тактичного проводу й зупинити великий наступ на південь, доки не впали зовнішні рубежі містечка."}},faq={{q="Чому Вартовий Гоу призначає винагороди, а не посилає міську варту?",a="Місцевий гарнізон Лейкширу напружений до краю. Між патрулюванням Озера Незрушного, охороною мостів і відбиттям нападів гнолів і орків вартові не можуть виділити досить сил, щоб штурмувати укріплені табори орків, не лишивши місто беззахисним.",al={"чому вартовий гоу призначає нагороди","де міська варта","нагорода вартового гоу"}},{q="Де знайти Поборників Блекрок?",a="Вони стоять у розлогих таборах Блекрок на півночі Гір Редріджу, трохи на захід від гірської дороги, що піднімається до Палаючих Степів.",al={"де поборники","місце поборників","табір поборників блекрок"}},{q="Чому орки Блекрок вторглися в Редрідж?",a="Клан Блекрок, що діє з Гори Блекрок на півночі, вважає довколишні пагорби стратегічною територією, яку треба завоювати й пограбувати. Оборона Стормвінда роздроблена, тож вони прагнуть вигнати людські поселення й заволодіти гірськими перевалами.",al={"чому блекрок вторглися в редрідж","чому орки нападають на лейкшир","вторгнення блекрок"}},{q="Чому Стормвінд не посилає королівських вояків, щоб їх вигнати?",a="Король Варіан Рінн зник, а королівський двір під регентством Болвара Фордрагона й Леді Престор наполягає, що королівство не може виділити військ. Лейкшир раз у раз просив у столиці допомоги, але йому відмовляли, і він мусить наймати перехожих найманців.",al={"чому немає армії стормвінда","де допомога стормвінда","підкріплення магістрата соломона"}},{q="Яку роль поборники відіграють у клані Блекрок?",a="Поборники — польові командири на передовій. Кожен бойовий загін Блекрок покладається на поборника, який спрямовує атаки, тримає жорстоку дисципліну й веде наступ на землі Альянсу.",al={"що таке поборники блекрок","ранг поборника","одиниця блекрок"}},{q="Хто затвердив цю винагороду?",a="Винагороду затвердив Магістрат Соломон, цивільний очільник Лейкширу, доручивши Вартовому Гоу набрати вправних бійців для цієї роботи.",al={"хто платить нагороду","хто хоче смерті поборників","нагорода магістрата соломона"}}},fp="16,386,26.506.0,23.435.0,70.285.0,42.157.0,45.266.0,60.261.0,55.181.0,36.153.0"}
P.entries["quest:129"] = {n="Дармовий обід",s="Дармовий обід — доручення Альянсу, що починається в Лейкширі: Дарсі з корчми просить шукача пригод віднести приготовану їжу Вартовому Паркеру. Паркер патрулює небезпечну південну дорогу до Сутінколісся й не підпускає до Лейкширу ворожих гнолів та орків Блекрок.",h="Дармовий обід — доручення Альянсу, що починається в Лейкширі: Дарсі з корчми просить шукача пригод віднести...",kw={"дармовий обід","дарсі","вартовий паркер","обід","лейкшир","сутінколісся"},ang={["faction:Alliance"]="Доставка обіду від Дарсі показує, як тяжко доводиться простим людям і рядовим вартовим у віддалених поселеннях Альянсу, здебільшого покинутих напризволяще.",["profession:Cooking"]="Теплий, добре приготований пайок у полі — часто єдине, що тримає на ногах самотнього вартового на ворожому роздоріжжі."},sec={{t="Обід у дорогу",b="Буденне життя в Редріджі сповнене тривоги, та Дарсі, мешканка Лейкширу, по-своєму намагається підтримати захисників містечка. Вона зібрала ситний обід для Вартового Паркера, але сама віднести його не може. Глушина одразу за міською брамою кишить агресивними гнолами Редріджу й мандрівними загонами орків, тож виходити за околиці міста цивільній без обладунків надто небезпечно. Натомість вона покладається на подорожніх, які віднесуть пайок дорогою на Даркшир."},{t="Варта на кордоні",b="Вартовий Паркер несе службу на дорозі на південь від Лейкширу й пильнує шлях, що з'єднує Редрідж із Сутінколіссям. Варта в Редріджі небезпечно поріділа: військо Стормвінда не надсилає досить підкріплення проти дедалі численніших зграй гнолів Редріджу та клану Блекрок, що окопався в горах. Самотня варта серед ворожих земель геть виснажує вартових на кшталт Паркера, тож проста турбота містян і гаряча їжа неабияк підтримують бойовий дух."}},faq={{q="Де знайти Вартового Паркера?",a="Вартовий Паркер патрулює південну ґрунтову дорогу, що веде з Лейкширу до кордону із Сутінколіссям і містечка Даркшир.",al={"місце вартового паркера","де паркер","знайти вартового паркера"}},{q="Чому Дарсі не віднесе обід сама?",a="Дарсі — звичайна мешканка й вважає околиці Лейкширу надто небезпечними, щоб ходити там самій. Ворожі гноли й орки Блекрок никають просто біля доріг за містом.",al={"чому дарсі не піде сама","дарсі редрідж"}},{q="З якими загрозами має справу Вартовий Паркер?",a="Паркер мусить утримувати південну дорогу від бродячих зграй місцевих гнолів Гір Редріджу, а також від агресивних бойових загонів орків Блекрок.",al={"вороги паркера","загрози редріджу"}},{q="Що буде, коли Вартовий Паркер отримає обід?",a="Обід від Дарсі сповнює Паркера вдячністю, і зрештою він доручає шукачеві пригод нові побутові справи між вартовими й містянами — почати з візиту до місцевої травниці.",al={"наступне завдання дармового обіду","продовження паркера"}},{q="Чому вартовим Стормвінда так важко вберегти Редрідж?",a="Король Варіан Рінн зник, а політичний провід королівства зайнятий справами в Стормвінді, тож віддалені поселення на кшталт Лейкширу майже не отримують військової підтримки, і окремі міські вартові лишаються самі.",al={"чому стормвінд не береже редрідж","лейкшир без захисту"}},{q="Яку нагороду обіцяє Дарсі?",a="За те, що ви пронесете обід Паркера небезпечною місцевістю, Дарсі обіцяє приготувати й подати вам безкоштовний обід, коли повернетеся до міста.",al={"що таке дармовий обід","нагорода дарсі"}}},fp="12,287,19.526.0,19.536.0,32.125.0,44.188.0,42.147.0,47.208.1,58.230.0,32.159.0"}
P.entries["quest:13"] = {n="Народне ополчення",s="Це завдання — новий етап кампанії добровольців Ґраяна Стаутмантла, що прагнуть вибити Братство Дефіас із Вестфолу. Злодії перейшли від дрібного розбою на шляхах до організованого пограбування важливих місць, як-от Мунбрук і Кар'єр Золотого Узбережжя, тож Народне ополчення вимагає жорсткішої відплати.",h="Це завдання — новий етап кампанії добровольців Ґраяна Стаутмантла, що прагнуть вибити Братство Дефіас із...",kw={"народне ополчення","ґраян стаутмантл","мунбрук","кар'єр золотого узбережжя","хутір алекстона","братство дефіас"},ang={["class:Paladin"]="Ґраян Стаутмантл прямо закликає Світло очистити Вестфол від злочинної скверни, тож для паладинів ця кампанія — справжня місія справедливості.",["faction:Alliance"]="Ця боротьба оголює гіркий розлом між затишними мурами Стормвінда та його голодними прикордонними землями, полишеними напризволяще.",["race:Human"]="Для людей королівства бій тут — трагічне протистояння з колишніми каменярами й сусідами, що жорстоко обернулися проти власного народу."},sec={{t="Насильство наростає",b="Перші сутички з Дефіасом стосувалися дрібних бандитів, що чіплялися до мандрівників на шляхах, але загроза стрімко глибшає. Мародери Дефіасу й грабіжники, що жбурляють вогонь, заполонили важливі господарські осередки Вестфолу: цілковито захопили Мунбрук, обібрали Хутір Алекстона й прибрали до рук Кар'єр Золотого Узбережжя. Ґраян Стаутмантл розуміє: якщо ці розбійники закріпляться в цих осередках, відвоювати край без справжнього королівського війська стане неможливо."},{t="Переконання ополчення",b="Не маючи ні офіційних солдатів, ні ресурсів зі Стормвінда, Ґраян Стаутмантл закликає на поміч Святе Світло й моральну стійкість останніх фермерів Вестфолу. Виснажлива війна ополчення цілком тримається на добровольцях, які несуть бій просто до твердинь Дефіасу. Вигнання мародерів має позбавити Братство ресурсів і водночас показати наляканим жителям, що ще є захисники, готові битися за мир і добробут Вестфолу."}},faq={{q="Що таке Народне ополчення?",a="Народне ополчення — озброєні добровольчі загони самооборони, які зібрав Ґраян Стаутмантл. Здебільшого до них увійшли фермери Вестфолу, що втратили домівки, і співчутливі мандрівники; вони постали, щоб боронити провінцію від Братства Дефіас, коли королівський двір у Стормвінді відмовився прислати міську варту.",al={"що таке народне ополчення","хто ополчення","ополчення вестфола"}},{q="Хто такий Ґраян Стаутмантл?",a="Ґраян Стаутмантл — досвідчений командир-людина, що керує обороною Вестфолу з твердині на вершині Сентінел Гілла. Відданий Світлу й рідному краю, він веде Народне ополчення у відчайдушному опорі владі розбійників.",al={"ґраян","хто такий стаутмантл","лор стаутмантла"}},{q="Чому Дефіас грабують ферми й кар'єри?",a="Братство Дефіас прагне підірвати постачання харчів у Вестфолі й захопити сировину. Кар'єр Золотого Узбережжя дає їм камінь і мінерали, а захоплення Мунбрука й хуторів проганяє чесних людей і дає злочинному угрупованню опорні пункти.",al={"чому дефіас грабують","дефіас у мунбруку","грабіжники в кар'єрі"}},{q="Чому Стормвінд не прислав вояків до Вестфолу?",a="Король Варіан Рінн загадково зник, і на троні опинився хлопчик-король Андуїн під регентством Верховного Лорда Болвара Фордрагона. Дім Вельмож Стормвінда загруз у чварах, ресурси корони розпорошені, і віддалені краї на кшталт Вестфолу цілком покинуті на місцевих захисників.",al={"де вояки стормвінда","чому стормвінд не допомагає","король варіан вестфол"}},{q="Де знайти Грабіжників і Мародерів Дефіас?",a="Вони зосередилися довкола захоплених поселень на півдні й заході Вестфолу — передусім у покинутому містечку Мунбрук, у Кар'єрі Золотого Узбережжя на західних кручах і на зруйнованому Хуторі Алекстона.",al={"місце грабіжників","де мародери","місця дефіас"}}},fp="20,306,19.490.0,24.453.0,29.296.0,25.242.0,46.285.0,47.305.0,45.207.0"}
P.entries["quest:130"] = {n="Відвідати травницю",s="Отримавши обід на своєму віддаленому посту, Вартовий Паркер просить вас про послугу, перш ніж ви повернетеся до корчми Лейкширу. Сподіваючись висловити свої почуття до Дарсі, він посилає вас до місцевої травниці купити квітів. Паркер наполягає, щоб травниці не казали, хто їх замовив і кому вони призначені.",h="Отримавши обід на своєму віддаленому посту, Вартовий Паркер просить вас про послугу, перш ніж ви повернетеся...",kw={"відвідати травницю","вартовий паркер","марті джейнроуз","дарсі","букет","лейкшир"},ang={["faction:Alliance"]="Навіть коли зграї гнолів і орки Блекрок раз у раз вдираються в Редрідж, серед захисників Лейкширу й далі розгортаються маленькі історії кохання.",["profession:Herbalism"]="Завітавши до Марті Джейнроуз, збирачі трав знайомляться з головною торговкою травами й алхімічним крамом Лейкширу на західному краю містечка."},sec={{t="Таємне прохання вартового",b="Стоячи на самотньому південному підході до Лейкширу, Вартовий Паркер видивляється орків Блекрок і гнолів. Коли ви приносите йому гарячий обід від Дарсі з Корчми Лейкшира, він користується нагодою, щоб віддячити їй за доброту. Замість того щоб просто відпустити вас назад, він просить зайти до крамниці місцевої травниці на західному краю містечка й купити для Дарсі букет квітів."},{t="Плітки й таємне залицяння",b="У маленькому Лейкширі важко щось приховати, тож Паркер прямо застерігає вас не розповідати травниці, Марті Джейнроуз, від кого ці квіти й кому вони призначені. Коли ви приходите до її крамниці, Марті не втримується, щоб не покепкувати з вас: вона думає, що ви вже встигли знайти собі в містечку кохану людину. У краї, де лютують орки й розбійники, навіть скромний романтичний жест — бажана розрада."}},faq={{q="Хто посилає вас до травниці?",a="Це доручення дає Вартовий Паркер. Він охороняє південну дорогу, що веде в Гори Редріджу, трохи на північ від кордону із Сутінколіссям.",al={"хто дає це завдання","давець завдання","вартовий паркер"}},{q="Хто травниця в Лейкширі?",a="Марті Джейнроуз — місцева травниця й квіткарка в Лейкширі. Її крамниця в західному кінці містечка.",al={"хто травниця лейкшира","марті джейнроуз","де травниця"}},{q="Навіщо Вартовому Паркеру квіти?",a="Паркер хоче надіслати квіти Дарсі, служниці з Корчми Лейкшира, яка прислала йому безкоштовний обід, — на знак прихильності й вдячності.",al={"навіщо паркеру квіти","кому квіти","мотив паркера"}},{q="Чому Паркер хоче, щоб покупку тримали в таємниці?",a="Лейкшир — маленьке, згуртоване містечко, де новини розлітаються миттю. Паркер соромиться свого залицяння до Дарсі й не хоче пліток від Марті Джейнроуз та інших містян.",al={"чому таємниця","чому приховувати кому квіти","не кажи марті"}},{q="Що буде після розмови з Марті Джейнроуз?",a="Марті складає букет нарцисів, і далі треба доставити квіти просто Дарсі в Корчму Лейкшира.",al={"що після марті","доставка нарцисів","після травниці"}},{q="Яке місце це завдання посідає в ланцюжку?",a="Це завдання — місток між «Дармовим обідом», де ви несете обід Вартовому Паркеру, і «Доставкою нарцисів», де ви несете квіти назад до Дарсі.",al={"місце в ланцюжку","ланцюжок завдань","ланцюжок дармового обіду"}}},fp="19,303,24.413.0,31.449.0,37.153.0,34.116.0,35.148.0,46.173.0,46.127.1,39.158.1"}
P.entries["quest:131"] = {n="Доставка нарцисів",s="Доставка нарцисів завершує невелике побутове доручення, що веде від вартового посту до міської площі Лейкширу. Віднісши обід Вартовому Паркеру й забравши букет у травниці Марті Джейнроуз, ви вручаєте квіти Дарсі в Корчмі Лейкшира — і несподівано потрапляєте в самий вир незручного місцевого суперництва.",h="Доставка нарцисів завершує невелике побутове доручення, що веде від вартового посту до міської площі Лейкширу.",kw={"доставка нарцисів","дарсі","марті джейнроуз","вартовий паркер","нарциси","лейкшир"},ang={["faction:Alliance"]="Допомагаючи міській варті й корчмі Лейкширу, ви підтримуєте дух містян, поки містечко потерпає від набігів Блекрок і гнолів.",["profession:Cooking"]="Дарсі віддячує вам за доставку приправленою смаженою рибою-сонцем — прикладом простої домашньої кухні з берегів озера в Редріджі.",["profession:Herbalism"]="Це доручення спирається на ботанічні знання Марті Джейнроуз і її вміння вибрати свіжі квіти з берегів озера, показуючи мирний бік травництва."},sec={{t="Запашне доручення",b="Те, що почалося як проста послуга — віднести гарячий обід Вартовому Паркеру, — обертається делікатним романтичним жестом. Вдячний за обід, Паркер просить вас узяти квіти в Марті Джейнроуз, щоб зробити сюрприз Дарсі, яка готувала йому їжу. Марті складає свіжий букет зі своїх улюблених квітів — нарцисів, не знаючи, кому він призначений."},{t="Містечкове суперництво",b="Коли ви приносите букет до Корчми Лейкшира, перша радість Дарсі швидко змінюється підозрою. Упізнавши улюблені квіти Марті, Дарсі одразу здогадується, що Паркер мав справу з жінкою, яку вона вважає ревнивою лисицею. Хоч Дарсі й побоюється, що Марті, знай вона, кому букет, могла б зі злості отруїти стебла, вас вона ні в чому не звинувачує й дає за клопіт гарячу порцію смаженої риби-сонця."}},faq={{q="Хто така Дарсі?",a="Дарсі працює в Корчмі Лейкшира в Горах Редріджу й готує їжу для місцевих і міських вартових. Це вона прислала обід Вартовому Паркеру, і той на знак вдячності відправив їй букет квітів.",al={"дарсі","хто така дарсі","кухарка лейкшира дарсі"}},{q="Хто така Марті Джейнроуз?",a="Марті Джейнроуз — місцева травниця й шанувальниця квітів у Лейкширі. Вартовий Паркер посилає вас до неї купити гарний букет, і Марті радо складає нарциси, зауваживши, що це якраз її улюблені квіти.",al={"марті джейнроуз","травниця лейкшира","хто дав квіти"}},{q="Чому нарциси засмучують Дарсі?",a="Дарсі одразу впізнає в нарцисах улюблені квіти Марті. Вона вважає Марті заздрісною суперницею й боїться, що та отруїла б стебла, якби знала, що букет для Дарсі.",al={"чому нарциси засмутили дарсі","чому дарсі сердита","суперечка дарсі й марті"}},{q="Чи Марті справді отруїла букет?",a="Ні. Марті й гадки не мала, що квіти для Дарсі: Паркер просто попросив вас забрати букет, і Марті між іншим поклала в нього свої улюблені.",al={"чи марті отруїла букет","чи нарциси отруєні"}},{q="Які завдання ведуть до цієї доставки?",a="Ланцюжок починається із «Дармового обіду», де ви несете обід Дарсі Вартовому Паркеру. Далі Паркер дає завдання «Відвідати травницю», щоб купити подарунок у Марті Джейнроуз, а завершується все «Доставкою нарцисів».",al={"ланцюжок завдань","передумови нарцисів","ланцюжок доставки нарцисів"}},{q="Яку нагороду дають за доставку квітів?",a="Дарсі дякує вам щедрою порцією смаженої сонячної риби, кількома мідяками й досвідом, а також репутацією в королівстві Стормвінд.",al={"нагорода за квіти","нагороди нарцисів"}}},fp="20,322,17.358.0,14.430.1,13.214.0,23.223.0,39.196.1,39.173.1,37.203.0,50.136.0"}
P.entries["quest:132"] = {n="Братство Дефіас",s="Це доручення — доставити Ґраянові Стаутмантлу в Сентінел Гілл важливі відомості з підпілля від Вайлі Чорного. Послання Вайлі розкриває, що Братство Дефіас — не просто розпорошена зграя розбійників, а організована сила, яка змовилася з місцевими гнолами, кобольдами й гоблінами. Стаутмантл покладається на ці відомості, щоб оцінити справжній розмах змови, яка душить Вестфол.",h="Це доручення — доставити Ґраянові Стаутмантлу в Сентінел Гілл важливі відомості з підпілля від Вайлі Чорного.",kw={"братство дефіас","вайлі чорний","ґраян стаутмантл","гноли","кобольди","гобліни"},ang={["class:Rogue"]="Вайлі Чорний — приклад агента, що балансує між розбійником і корисним донощиком, і він показує, як зв'язки в підпіллі живлять розвідку воєнного часу.",["faction:Alliance"]="Злагоджені дії людських розбійників, гнолів і гоблінів оголюють небезпечну прогалину в обороні західних кордонів Стормвінда.",["race:Human"]="Для людей Вестфолу й Редріджу записка підтверджує: розбійники, що грабують їхні родинні господарства, ведуть продуману, злагоджену кампанію."},sec={{t="Небезпечне послання",b="Вайлі Чорний запевняє, що розкриття того, що він знає про Дефіас, може коштувати йому життя. Орудуючи на околицях Редріджу й Вестфолу, Вайлі прочув про справу значно масштабнішу за розбій на шляхах. Його запечатана записка розповідає, як Братству вдалося узгодити дії різних, зазвичай ворожих одне одному угруповань по всьому краю."},{t="Несподівані союзи",b="Суть застереження Вайлі — тривожна мережа, яку зібрало Братство Дефіас. Замість діяти самотужки, розбійники в червоних масках залучили зграї гнолів, кобольдів-копачів і гоблінських інженерів, що шукають наживи. Поєднання грубої сили, підземної праці й механічної хитрості свідчить про задум, що значно перевершує все, на що спершу чекало Народне ополчення."},{t="Вимушена довіра Стаутмантла",b="Ґраян Стаутмантл не надто любить Вайлі й відверто шкодує, що не дав цьому пройдисвітові згнити, коли мав нагоду. Та Вестфол не може дозволити собі гордість. Стормвінд ігнорує благання про військову допомогу, тож Народне ополчення мусить брати корисні відомості звідусіль, де їх можна знайти."}},faq={{q="Про що Записка Вайлі?",a="У записці — попередження Вайлі Чорного, що Братство Дефіас діє разом із гнолами, кобольдами й гоблінськими інженерами. Вона повідомляє Народне ополчення, що розбійники готують велику операцію, що далеко виходить за межі дрібного розбою.",al={"записка вайлі","що в записці","записка вайлі чорного"}},{q="Хто такий Вайлі Чорний?",a="Вайлі Чорний — темний знайомий, що сидить у Лейкширі в Редріджі. Хоч Ґраян Стаутмантл і вважає його ненадійним пройдисвітом, Вайлі має широкі зв'язки в злочинному світі й важливі відомості про дії Дефіас.",al={"вайлі чорний","хто такий вайлі","вайлі лейкшир"}},{q="Навіщо Дефіас союз із гнолами й кобольдами?",a="Дефіас використовують місцевих істот, щоб контролювати землі й мати дешеву робочу силу. Гноли — грубі бійці, що відволікають місцевих захисників, кобольди риють ходи в місцевих копальнях, а гобліни-майстри дають важкі машини й підривне знаряддя.",al={"чому дефіас у союзі з гнолами","кобольди й дефіас","союзники дефіас"}},{q="Чому Ґраян Стаутмантл не любить Вайлі?",a="Ґраян Стаутмантл — дисциплінований колишній вояк, що бачить у Вайлі звичайного кишенькового злодія й злочинця. Стаутмантл шкодує, що колись урятував його від в'язниці, хоч і визнає, що Вайліві вуха в злочинному світі незамінні.",al={"стаутмантл і вайлі","чому не любить вайлі"}},{q="Яке місце це повідомлення посідає в розслідуванні ополчення?",a="Ця доставка — місток між місцевою розвідкою й викриттям глибшої змови Дефіас. Повернене повідомлення Вайлі спонукає Стаутмантла копати далі — до проводу змовників і їхніх опорних пунктів.",al={"етап ланцюжка дефіас","що це за завдання"}},{q="Чому Стормвінд не бореться з цією загрозою?",a="Відколи Король Варіан Рінн зник, Дім Вельмож Стормвінда відмовляється відрядити королівських вояків чи кошти на захист Вестфолу. Край мусить боронитися сам силами строкатого Народного ополчення на чолі зі Стаутмантлом.",al={"допомога стормвінда вестфолу","де вартові"}}},fp="22,388,20.367.0,18.378.0,29.299.0,27.241.0,23.242.0,50.257.0,41.224.0,61.224.0,41.217.0"}
P.entries["quest:133"] = {n="Опудало проти гулів",s="Глибоко в похмурій глушині Сутінколісся дивакуватий відлюдник Аберкромбі запевняє, що його самотню хижу взяли в облогу ходячі мерці. Щоб захистити свій дім, він доручає перехожим шукачам пригод назбирати ребер гулів для дивного захисного опудала.",h="Глибоко в похмурій глушині Сутінколісся дивакуватий відлюдник Аберкромбі запевняє, що його самотню хижу взяли...",kw={"опудало проти гулів","аберкромбі","гулі","ребра","сутінколісся","нічна варта"},ang={["class:Paladin"]="Полюючи на трупоїдів і кістогризів, ви очищаєте ґрунт Сутінколісся від скверни, хоч віддавати їхні рештки відлюдникові й видається вкрай тривожним.",["class:Priest"]="Допомогти наляканому відлюдникові, що опинився серед темних духів, — шляхетна справа, хоча майструвати опудала із зібраних решток — випробування для шлунка.",["faction:Alliance"]="Нічна Варта ледве встигає захищати шляхи, тож самотні лісові мешканці на кшталт Аберкромбі мусять покладатися на мандрівників Альянсу, щоб уберегтися від неспокійних мерців."},sec={{t="Біда відлюдника",b="Аберкромбі живе далеко за межами охоронюваних околиць Даркшира, сам-один серед темних дерев Сутінколісся. Тут безкарно блукають гулі — трупоїди й кістогризи. Наляканий відлюдник запевняє, що ненажерливі мерці нещодавно ледь не розвалили йому стіни, і просить ребер цих потвор, щоб змайструвати відлякувач: він сподівається, що моторошне опудало триматиме голодних мерців подалі."},{t="Дивний захист",b="Здоровий глузд підказав би тікати під захист Нічної Варти чи зміцнити дерев'яну хижу, але Аберкромбі наполягає на моторошних методах. Він вірить, що опудало з решток гулів налякає інших мерців-нишпорок. Хоч ідея змайструвати опудало з порубаної нежиті й бентежить, мандрівники в Сутінколіссі часто вірять дивакуватому відлюдникові на слово, щоб заробити трохи потрібних монет."}},faq={{q="Де живе Аберкромбі?",a="Аберкромбі живе у відлюдній халупі в західному Сутінколіссі, трохи на північний схід від Цвинтаря Воронячого Пагорба, далеко від захисту Даркширу.",al={"місце аберкромбі","де хатина аберкромбі","хатина відлюдника сутінколісся"}},{q="Навіщо Аберкромбі ребра гулів?",a="Аберкромбі запевняє, що зграї гулів гупають у стіни його халупи. Він збирається зробити з кісток моторошне опудало, щоб відлякати нежить, що никає в пошуках поживи.",al={"навіщо ребра гулів","призначення ребер гулів","для чого опудало"}},{q="З яких істот падають Ребра гулів?",a="Ребра можна зібрати з будь-якої місцевої нежиті, що блукає дорогами й цвинтарями Сутінколісся, а саме з Плотоїдів, Кісткогризів, Мозкоїдів, Гнилих і Розносників Чуми.",al={"де взяти ребра","падіння ребер гулів","які гулі дають ребра"}},{q="Чи справді опудало з нежиті відлякує гулів?",a="Нежить рідко відчуває страх, тож досвідченим мисливцям на чудовиськ задум Аберкромбі здається сумнівним. Та самітник уперто тримається свого дивного проєкту, а в таких відчайдушних лісах мало хто сперечається з тим, хто платить.",al={"чи опудало відлякує гулів","логіка опудала проти гулів"}},{q="Чому Аберкромбі просто не переїде до Даркширу?",a="Аберкромбі обирає жити відлюдно, подалі від Нічної Варти й міської влади. Попри очевидні небезпеки диких нетрів Сутінколісся, він воліє сам доглядати свою халупу з власним дивним захистом.",al={"чому аберкромбі не переїде","чому живе в лісі","безпека даркшира"}},{q="Що далі, коли зібрано ребра?",a="Отримавши ребра гулів, Аберкромбі знаходить нову химерну клопітку справу й посилає шукачів пригод далі в нетрі розібратися з місцевими ограми, що вкрали його речі.",al={"що далі","наступне завдання"}}},fp="15,258,17.392.0,17.409.0,28.140.0,37.170.0,36.186.0,56.197.0,53.208.0,41.182.0"}
P.entries["quest:1338"] = {n="Наказ Стормпайка",s="Горянин Стормпайк, що несе службу серед засніжених скель Лох Модану, бажає мати щит роботи знаного майстра обладунків Фурена Лонґбірда. Оскільки Фурен відкрив майстерню далеко на півдні, у Стормвінді, горянин просить мандрівного шукача пригод доставити замовлення.",h="Горянин Стормпайк, що несе службу серед засніжених скель Лох Модану, бажає мати щит роботи знаного майстра...",kw={"наказ стормпайка","горянин стормпайк","фурен лонґбірд","лох модан","дворфійський квартал","щит"},ang={["faction:Alliance"]="Ця доставка показує тісні торгові й культурні зв'язки між дворфійськими твердинями Каз Модану й людською столицею Стормвінд, які поєднує Глибинний трамвай.",["profession:Blacksmithing"]="Фурена Лонґбірда визнають винятковим майстром обладунків навіть за межами королівств, тож для молодих ковалів, що мандрують Стормвіндом, його майстерня — помітна зупинка.",["race:Dwarf"]="Для дворфів ця доставка показує, як далеко сягає слава кланів на кшталт Стормпайків, і жартома запитує, чому майстер обладунків обрав людський камінь замість Айронфорджа."},sec={{t="Щит, вартий дороги",b="Навіть на віддалених заставах на кшталт Лох Модану дворфи-горяни мають тверді погляди на майстерність. Горянин Стормпайк наполягає: його наступний щит може викувати лише один коваль — Фурен Лонґбірд. Певний, що Лонґбірдові немає рівних, Стормпайк готовий щедро заплатити, аби замовлення потрапило до рук майстра, хоч їх і розділяє величезна відстань."},{t="Від Айронфорджа до Дворфійського Кварталу",b="Найбільше Стормпайка спантеличує, де осів Фурен. Замість того щоб лишатися біля Великої Кузні Айронфорджа поруч із родичами, Лонґбірд заробляє на життя далеко на півдні, у Дворфійському Кварталі Стормвінда. Стормпайк гадає, що люди, певно, платять йому королівський викуп, аби виманити такого майстра з батьківщини. Коли лист нарешті доходить до Фурена, той над ковадлом пишається, що отримав звістку від шанованого клану Стормпайк, і завзято береться кувати щит."}},faq={{q="Хто такий Горянин Стормпайк?",a="Він вартовий Альянсу в Лох Модані з дворфійського загону горян, що охороняє гірські перевали й долини. Він належить до гордого й впливового клану Стормпайк.",al={"горянин стормпайк","хто дає завдання","давець завдання"}},{q="Хто такий Фурен Лонґбірд?",a="Фурен Лонґбірд — знаний дворф-зброяр, що живе в Дворфійському Кварталі Стормвінда. Слава про його чудові щити й обладунки сягає аж Каз Модану на півночі.",al={"фурен лонґбірд","хто такий фурен","бронник"}},{q="Чому Фурен живе в Стормвінді, а не в Айронфорджі?",a="Поки прихильники традицій на кшталт Горянина Стормпайка дивуються, навіщо дворфові-майстрові покидати Айронфордж, Фурен працює в Дворфійському Кварталі Стормвінда для людської знаті, міської варти й мандрівних шукачів пригод і, мабуть, непогано заробляє людською монетою.",al={"чому фурен у стормвінді","чому дворфійський квартал","фурен покинув айронфордж"}},{q="Яку роль у доставці цього наказу відіграє Глибинний трамвай?",a="Мандрівники з посланням Стормпайка зазвичай ідуть з Лох Модану на південь через Айронфордж, а там сідають на підземний Глибинний трамвай, що везе просто в Дворфійський Квартал Стормвінда, де кузня Фурена.",al={"глибинний трамвай","як дістатися стормвінда","дорога до стормвінда"}},{q="Яке завдання йде перед цим?",a="Перш ніж доручити вам доставку до Стормвінда, Горянин Стормпайк перевіряє вашу відвагу й надійність у Лох Модані в завданні «Доручення горянина Стормпайка».",al={"передумови","попереднє завдання","завдання горянина стормпайка"}},{q="Чи Фурен Лонґбірд кує щит одразу?",a="Отримавши лист і віддаючи належне славному імені Стормпайків, Фурен радо береться за замовлення й обіцяє почати кувати щит ще до кінця дня.",al={"що далі","продовження","реакція фурена"}}},fp="17,286,26.381.0,38.486.0,29.187.0,23.203.0,54.272.0,57.217.0,29.168.0,50.188.0"}
P.entries["quest:1339"] = {n="Доручення горянина Стормпайка",s="«Доручення горянина Стормпайка» — коротке завдання Альянсу в Лох Модані, де треба бути гінцем. Горянин Кадрелл посилає мандрівних шукачів пригод до північної сторожової вежі, де Горянинові Стормпайку потрібен надійний посланець для справи за межами долини. Це завдання — вступ до довшого доручення, що сягає сусідніх земель.",h="«Доручення горянина Стормпайка» — коротке завдання Альянсу в Лох Модані, де треба бути гінцем.",kw={"доручення горянина стормпайка","горянин стормпайк","горянин кадрелл","лох модан","гонець","завдання"},ang={["faction:Alliance"]="Беручи доручення гінця від місцевих горян, ви допомагаєте залогам Айронфорджа мати припаси й злагоджено діяти по всіх східних землях.",["race:Dwarf"]="Допомогти побратимові-дворфу зі славетного роду Стормпайків — природний обов'язок кожного мандрівника, що шанує клановий зв'язок по всьому Каз Модану."},sec={{t="Вартовому потрібен посланець",b="Горяни патрулюють дороги й застави Лох Модану, і сил їм ледве вистачає проти навали трогів і мандрівної звірини. Горянин Кадрелл часто посилає вправних мандрівників до вартових, які не можуть покинути пост. Горянин Стормпайк, що служить високо на північній сторожовій вежі, прикутий до варти саме тоді, коли нагальна особиста справа вимагає послати гінця далеко за межі краю."},{t="Від вежі до далеких доріг",b="Щоб дістатися до Стормпайка, треба піднятися на північну сторожову вежу, що височіє над долиною. Як член знаного клану Стормпайк, він має справи, що виходять далеко за межі щоденної оборони порубіжжя біля Телсамара. Узявшись за його доручення, ви погоджуєтеся переносити за нього звістки й припаси через кордони краю — і для недосвідчених шукачів пригод це перший великий крок за межі озерного краю, на широкі шляхи Каз Модану."}},faq={{q="Де знайти Горянина Стормпайка?",a="Горянин Стормпайк стоїть на самій верхівці північної вартової вежі в Лох Модані й пильнує довколишні стежки.",al={"місце стормпайка","де стормпайк","знайти вежу стормпайка"}},{q="Хто дає це завдання?",a="Завдання дає Горянин Кадрелл, що патрулює довкола Телсамара в Лох Модані: він вказує вам на вежу Стормпайка.",al={"хто дає доручення горянина стормпайка","початок завдання","місце кадрелла"}},{q="Навіщо Стормпайкові шукач пригод?",a="Як горянин на службі, Стормпайк не може покинути свій пост на вежі. Його особисте доручення вимагає мандрувати далеко за межі Лох Модану, тож вільний шукач пригод — ідеальний посланець.",al={"навіщо стормпайку гінець","проблема стормпайка","чого хоче стормпайк"}},{q="Що буде, коли доповіси Стормпайкові?",a="Розмова зі Стормпайком завершує цей вступний крок і відкриває його наступне доручення — «Наказ Стормпайка», яке посилає вас із доставкою в інший край.",al={"наступне завдання","що після доручення стормпайка","продовження стормпайка"}},{q="Чи це пов'язано з Вартою Стормпайків в Альтераку?",a="Горянин Стормпайк має ім'я й кров славетного клану Стормпайк, відомого Вартою Стормпайків і гірничими експедиціями, але це доручення — скромна місцева справа.",al={"зв'язок із кланом стормпайк","стормпайки альтерак","чи це варта стормпайків"}},{q="Чи мають гравці Орди тут подібне завдання?",a="Ні. Лох Модан — суверенна дворфійська територія, цілком віддана Альянсу, і горяни нападають на мандрівників з Орди, щойно їх побачать.",al={"версія орди","чи орда може виконати"}}},fp="28,332,30.440.0,27.414.0,38.136.0,22.124.0,38.194.0,42.167.0,50.198.0,47.140.0"}
P.entries["quest:134"] = {n="Огри-злодії",s="Аберкромбі, дивакуватий відлюдник із західного Сутінколісся, просить мандрівників вирушити до огрської твердині — Огрського Кургану Вул'Ґол. Він запевняє, що огри напали на нього, поки він збирав рослини, і забрали ящик із його незамінними травами й інструментами.",h="Аберкромбі, дивакуватий відлюдник із західного Сутінколісся, просить мандрівників вирушити до огрської...",ang={["class:Paladin"]="Потаємна, нетерпляча радість Аберкромбі через повернений ящик має насторожити кожного слугу Святого Світла: не варто сліпо допомагати цьому відлюдникові.",["class:Warlock"]="Чорнокнижники, обізнані із забороненими мистецтвами, легко впізнають в обмовці Аберкромбі оду темному чаклунству, а не простий ботанічний запал.",["profession:Herbalism"]="Аберкромбі запевняє, що в ящику лише трави, але травник неодмінно замислиться: що ж то за дивна рослинність, заради якої треба так відчайдушно лізти в огрський курган?"},sec={{t="Загублені речі відлюдника",b="Старий відлюдник Аберкромбі, що живе на відлюдді при сирих шляхах західного Сутінколісся, розповідає, ніби на нього напали, коли він збирав припаси в глушині. За його словами, громили з південного огрського кургану прогнали його, і йому довелося покинути міцний дерев'яний ящик, напханий дорогоцінними травами й тендітними інструментами."},{t="Загроза Вул'Ґолу",b="The Vul'Gol Ogre Mound in southern Duskwood is a fortified hive of hostile ogres who harass unwary wanderers. The crate sits right near the entrance of their cavernous mound, daring outsiders to step past roaring brutes and spell-weaving magi to haul it back to the hermit."},{t="Обмовка",b="Отримавши назад свої речі, дивакуватий Аберкромбі аж нестямиться від збудження. Він мало не вигукує хвалу «Нек…», але квапливо схаменувається й дякує шукачеві пригод — йому не терпиться замкнутися й пустити повернені припаси в хід у темряві."}},faq={{q="Хто такий Аберкромбі?",a="Аберкромбі — дивакуватий самітник, що живе в старій халупі в західному Сутінколіссі. Хоч він і вдає кволого, безпорадного й потребуючого допомоги, його гарячкова поведінка й дивні прохання натякають на темніші, тривожні наміри.",al={"лор аберкромбі","хто дав завдання","хто відлюдник"}},{q="Куди огри занесли ящик Аберкромбі?",a="Ящик принесли до Огрського Кургану Вул'Ґол на півдні Сутінколісся. Він лежить на відкритій землі просто біля входу до печери огрів.",al={"де ящик","місце ящика","ящик вул'ґола"}},{q="Звідки в Сутінколіссі огри?",a="Огри клану Вул'Ґол закріпилися на суворих південних пагорбах Сутінколісся після Другої війни. Агресивні й ласі до легкої наживи, вони раз у раз грабують перехожих, нападають на самотніх мандрівників і складають награбоване довкола свого кургану.",al={"огри сутінколісся","походження вул'ґола","чому тут огри"}},{q="Що насправді в ящику?",a="Аберкромбі запевняє, що в ящику рідкісні трави й особливе знаряддя для їх збирання, яке він покинув під час нападу, і він не тямиться з радості, що все повернулося.",al={"що в ящику","що втратив аберкромбі"}},{q="Що Аберкромбі мало не сказав, отримавши ящик?",a="Отримавши ящик назад, Аберкромбі починає дякувати комусь іншому, але раптом схаменувся й дякує шукачеві пригод, а тоді радісно чекає ночей, що наближаються.",al={"подякуй некромантові","що говорив аберкромбі","цитата аберкромбі"}},{q="Чи пов'язане це завдання з іншими дорученнями біля кургану огрів?",a="Adventurers traveling to Vul'Gol Ogre Mound may also be collecting ogre monocles for Viktori Prism'Antras.",al={"завдання біля кургану огрів","завдання біля вул'ґола"}}},fp="12,265,21.316.0,18.273.0,20.291.1,19.227.0,45.140.0,32.251.0,34.152.1,57.189.1,57.106.0"}
P.entries["quest:135"] = {n="Братство Дефіас",s="Це завдання — переломний момент у кампанії Вестфолу проти розбійників, що терзають сільський край. Ґраян Стаутмантл відправляє вас до Стормвінда, щоб доставити цікаву записку Майстрові Матіасу Шоу: він підозрює, що зграя Дефіасу пов'язана з давньою Гільдією Каменярів.",h="Це завдання — переломний момент у кампанії Вестфолу проти розбійників, що терзають сільський край.",kw={"братство дефіас","матіас шоу","si:7","гільдія каменярів","записка вайлі","старе місто"},ang={["class:Rogue"]="У штабі SI:7 ви зустрічаєтеся віч-на-віч із Матіасом Шоу, великим майстром розбійників і шпигунів Стормвінда, — і місцеві негаразди Вестфолу постають частиною значно більшої гри.",["faction:Alliance"]="Завдання оголює внутрішні тріщини в головному королівстві Альянсу: не всі загрози походять від чудовиськ ззовні — деякі народжуються серед зраджених громадян.",["race:Human"]="Для людей Стормвінда це доручення пов'язує беззаконне прикордоння Вестфолу з гіркими, досі не розв'язаними політичними скандалами, що спалахнули після відбудови їхньої столиці."},sec={{t="Обмовка",b="Розслідуючи хаос у Вестфолі, Ґраян Стаутмантл помічає в посланнях Вайлі цікаву подробицю — згадку про каменярів. Гільдію будівничих, що відбудувала Стормвінд після Першої війни, давно вважали розпорошеною чи розпущеною. Якщо Братство Дефіас пов'язане з нею, то це сільське повстання — далеко не безладний натовп розбійників."},{t="Таємниці Старого Міста",b="Із Сентінел Гілла Стаутмантл не може перевірити свої підозри. По справжні відомості королівського рівня він відсилає вас до Майстра Матіаса Шоу, очільника таємної розвідки Стормвінда — SI:7. Діючи з Казарми в Старому Місті, Шоу збирає чутки й таємниці з усього королівства, тож лише він здатен розплутати походження Дефіасу."},{t="Тінь над Короною",b="Побачивши Записку Вайлі, Шоу одразу розуміє, наскільки серйозне становище. Він підтверджує, що повстання у Вестфолі сягає набагато глибше й має значно складніше політичне підґрунтя, ніж здатен збагнути простий селянський командир ополчення на кшталт Стаутмантла, — і веде просто до бурхливого минулого самого Стормвінда."}},faq={{q="Чому Ґраян Стаутмантл посилає вас до Стормвінда?",a="Стаутмантл знаходить у записці Вайлі згадку про каменярів. Зрозумівши, що це вказує на можливі політичні інтриги, а не на звичайний розбій, він посилає вас до Майстра Матіаса Шоу, голови розвідки Стормвінда, щоб підтвердити зв'язок.",al={"чому ґраян посилає до стормвінда","чому завдання стормвінд","доручення стаутмантла"}},{q="Хто такий Матіас Шоу?",a="Майстер Матіас Шоу — голова SI:7, таємної розвідки й шпигунської служби Королівства Стормвінд. Він працює зі штабу, схованого в Казармі Старого Міста.",al={"хто такий шоу","матіас шоу","лідер таємної служби"}},{q="Де знайти Матіаса Шоу?",a="Шоу на другому поверсі штабу SI:7 у Казармі Старого Міста в Стормвінді.",al={"місце шоу","де шоу","знайти матіаса шоу"}},{q="Що пов'язує Дефіас із каменярами?",a="Гільдія Каменярів відбудувала Стормвінд після його руйнування в Першій війні. Після запеклої суперечки з Домом Вельмож щодо плати гільдію ошукали, і озлоблені каменярі згодом таємно перетворилися на Братство Дефіас, щоб помститися.",al={"дефіас і каменярі","чи дефіас каменярі","зв'язок з каменярами"}},{q="Що таке Записка Вайлі?",a="Це записка від Вайлі Чорного — пройдисвіта, з яким Ґраян Стаутмантл уже мав справу, — що попереджає: Дефіас змовляються з гнолами, кобольдами й гоблінами. Одна обмовка в ній ненавмисно пов'язує дії Братства Дефіас із колишньою Гільдією Каменярів.",al={"що таке записка вайлі","записка до шоу"}},{q="Чи знають про це Верховний Лорд Болвар чи хлопчик-король?",a="Питання таємної державної безпеки проходять через Матіаса Шоу й SI:7, перш ніж дістатися Верховного Лорда Болвара Фордрагона й трону. Шоу відповідає лише, що справа, можливо, складніша, ніж гадає Стаутмантл.",al={"чи знає король","чи знає болвар","знання уряду стормвінда"}}},fp="22,277,20.377.0,16.350.0,25.321.1,49.239.0,20.188.0,29.105.0,62.270.1,21.277.0,53.222.0"}
P.entries["quest:1358"] = {n="Зразок для Гелбріма",s="«Зразок для Гелбріма» — доручення для гінця Орди, що поєднує алхімічні досліди Андерсіті із заставами Відступників у центральному Калімдорі. Його дає Аптекар Зінґе: гінець має переправити через море уражене поморою вовче серце Аптекареві Гелбріму на Перехресті.",h="«Зразок для Гелбріма» — доручення для гінця Орди, що поєднує алхімічні досліди Андерсіті із заставами...",kw={"зразок для гелбріма","аптекар гелбрім","аптекар зінґе","зразок вовчого серця","королівське аптекарське товариство","перехрестя"},ang={["faction:Horde"]="Орки й таурени раді допомозі Відступників в обороні Перехрестя, але тихі розтини заражених чумою решток, які проводять аптекарі, вносять у мирні Пустки темну, тривожну ноту.",["race:Undead"]="Перевезення заражених зразків через увесь світ показує далекосяжні задуми Королівського Аптекарського Товариства — забезпечити Відступникам зверхність завдяки хімічній перевазі."},sec={{t="Зараза за морем",b="Королівське Аптекарське Товариство рідко тримає свої моторошні досліди в межах руїн Лордерону. Отримавши уражені органи від Аптекаря Ренферрела в Срібноліссі, аптекарка Зінґе в Андерсіті вирішила поширити дослідження на весь світ. Вона довірила шукачеві пригод Зразок вовчого серця, який треба переправити за море Аптекареві Гелбріму — алхімікові, що працює на посушливій савані Пусток."},{t="Задум Гелбріма",b="Зі своєї вежі на Перехресті Аптекар Гелбрім вивчає, як місцеві звірі Калімдору реагують на згубні сполуки, народжені в Чумних Землях. Доставлене вовче серце дає цінне уявлення про крайню отруйність. Гелбрім вірить, що, розтинаючи й випробовуючи зразок разом із місцевими істотами, він неабияк поглибить владу Відступників над отрутами й неприродними недугами."}},faq={{q="Що за посилку доставляють Гелбріму?",a="У посилці — Зразок Вовчого Серця, який Аптекар Ренферрел добув із зіпсованих вовків Срібнолісся, а Аптекар Зінґе дослідила в Андерсіті.",al={"що за посилка","зразок","серце вовка пакунок"}},{q="Навіщо Аптекарю Гелбріму отруєне вовче серце?",a="Гелбрім досліджує, як отрути з Лордерона впливають на звірину Калімдору. Він хоче вивчити надзвичайну отруйність серця, щоб створити сильніші варива й отрути для Королівського Аптекарського Товариства.",al={"навіщо гелбріму серце","дослідження гелбріма","мета гелбріма"}},{q="Де знайти Аптекаря Гелбріма?",a="Гелбрім на Перехресті в Пустках. Його можна знайти на верхньому зовнішньому ярусі центральної вартової вежі над поселенням.",al={"де гелбрім","місце гелбріма","знайти гелбріма"}},{q="Як мандрівникові дістатися з Андерсіті до Перехрестя?",a="Мандрівники сідають на цепелін біля вежі за Андерсіті й летять до Оргріммара в Дуротарі. З Оргріммара йдіть на південь через Дуротар, перетніть Річку Південної Люті в Пустки й рушайте головною дорогою на захід до Перехрестя.",al={"подорож до перехрестя","як дістатися гелбріма","андерсіті до пусток"}},{q="Хто такі Аптекар Ренферрел і Аптекар Зінґе?",a="Обоє — дослідники Королівського Аптекарського Товариства. Ренферрел працює в Гробниці в Срібноліссі, а Зінґе проводить свої дослідження в Апотекаріумі в Андерсіті.",al={"хто ренферрел","хто зінґе","лор зінґе й ренферрела"}},{q="Яку фракцію обслуговують ці дослідження?",a="Ці дослідження безпосередньо служать Відступникам і Королівському Аптекарському Товариству під владою Леді Сильвани Віндраннер, просуваючи їхні загальні зусилля зі створення смертоносної хімічної й біологічної зброї.",al={"кому слугують дослідження","чи це для сильвани","мета аптекарів"}}},fp="18,268,26.408.0,18.395.0,47.184.0,54.223.0,36.151.0,57.235.0,50.195.0,38.195.0"}
P.entries["quest:1359"] = {n="Посилка для Зінґе",s="«Посилка для Зінґе» — доручення гінця, яке дає Аптекар Ренферрел у Склепі в Срібноліссі. Треба доставити дивовижно отруйну тканину вовчих сердець Аптекареві Зінґе в Андерсіті, щоб Королівське Аптекарське Товариство ґрунтовно її дослідило.",h="«Посилка для Зінґе» — доручення гінця, яке дає Аптекар Ренферрел у Склепі в Срібноліссі.",kw={"посилка для зінґе","аптекар зінґе","аптекар ренферрел","склеп","вовчі серця","андерсіті","срібнолісся"},ang={["faction:Horde"]="Гінці з біологічними реагентами поєднують віддалені застави на кшталт Склепу з проводом і дослідницькими осередками Андерсіті.",["race:Undead"]="Польові зразки, зібрані в Лордероні, надходять просто до головних алхімічних лабораторій під руїнами Столиці й примножують наукову міць Відступників."},sec={{t="Отруйна аномалія",b="Вивчаючи місцевих тварин у Срібноліссі, Аптекар Ренферрел помітив тривожну фізіологічну особливість вовків, що блукають зруйнованими лісами. Їхні серця були такі отруйні, що за будь-яких звичайних обставин мали б убити самих звірів. Замість того щоб викинути тканину, Ренферрел запакував кілька зразків, щоб поділитися ними з колегами в Апотекаріумі Андерсіті."},{t="Очі Апотекаріуму",b="Законсервовані органи доставляють просто Аптекареві Зінґе — дослідниці, що працює в підземному осідку Королівського Аптекарського Товариства. Для Товариства, чия головна мета — створювати сильнодійні чуми й нові алхімічні сполуки, природні отрути, що підтримують життя, а не вбивають, становлять величезний інтерес. Зінґе вітає посилку як основу для подальших лабораторних дослідів у всій алхімічній мережі Відступників."}},faq={{q="Що таке зразки вовчих сердець?",a="Це законсервовані біологічні тканини вовків зі Срібнолісся. Аптекар Ренферрел виявив, що в серцях природні отрути, настільки смертельні, що тварини не мали б із ними вижити.",al={"вовчі серця","що таке зразки серць","зразки ренферрела"}},{q="Хто такий Аптекар Ренферрел?",a="Аптекар Ренферрел — член Королівського Аптекарського Товариства, що працює в Гробниці в Срібноліссі. Він керує польовими дослідженнями місцевої флори й фауни, збираючи складники й біологічні відомості для алхімії Відступників.",al={"аптекар ренферрел","ренферрел сільверпайн"}},{q="Хто така Аптекар Зінґе?",a="Аптекар Зінґе — дослідниця-алхімік в Апотекаріумі в Андерсіті. Вона експериментує з біологічними зразками, що надходять, щоб знаходити нові отрути й алхімічні засоби для Відступників.",al={"аптекар зінґе","зінґе андерсіті","лор аптекаря зінґе"}},{q="Куди веде ця доставка далі?",a="Коли Зінґе отримує й оглядає дивну тканину серця, дослідження тривають: зразки пересилають на інші алхімічні застави, як-от Аптекарю Гелбріму за морем, у Пустках.",al={"наступне завдання","що після доставки зінґе","продовження"}},{q="Чому Королівське Аптекарське Товариство цікавлять вовчі серця?",a="Королівське Аптекарське Товариство невпинно шукає екзотичних отрут, хвороб і біологічних аномалій. Звір, що виживає, попри смертельну самоотруту, має унікальні хімічні процеси, які можуть допомогти у створенні нових чум і сполук.",al={"чому аптекарі хочуть серця","навіщо вовчі серця"}},{q="Де в Андерсіті Апотекаріум?",a="Апотекаріум — південно-західне крило Андерсіті. Це головний лабораторний комплекс і керівний осідок Королівського Аптекарського Товариства.",al={"місце апотекаріума","де зінґе","карта апотекаріума"}}},fp="16,250,15.439.0,28.454.0,32.221.0,28.237.0,24.213.0,35.201.1,62.237.0,39.166.0"}
P.entries["quest:136"] = {n="Захований скарб капітана Сандерса",s="«Захований скарб капітана Сандерса» — перший крок багатоетапних пошуків скарбу на узбережжі Вестфолу. Усе починається з потертої пергаментної карти, що веде шукачів скарбів уздовж берега до особистої скрині покійного капітана. Знайдена закопана скриня дає початок гонитві за його схованою здобиччю по всьому краю.",h="«Захований скарб капітана Сандерса» — перший крок багатоетапних пошуків скарбу на узбережжі Вестфолу.",kw={"скарб капітана сандерса","капітан сандерс","карта скарбів","іржавий якір","вестфол","пірат"},ang={["class:Rogue"]="Піратські пошуки скарбу — звична справа для шахраїв і каперів, які знають, чого варта карта мертвого моряка на беззаконному узбережжі.",["faction:Alliance"]="Узбережжя Вестфолу кишить мурлоками й уламками, тож кожен статок, вирваний у моря, — маленька перемога серед негараздів на прикордонні королівства."},sec={{t="Останній заповіт моряка",b="Море біля західного берега Вестфолу всіяне уламками кораблів, розбитими корпусами й неспокійними духами потопельників. Серед тих, кого забрала безодня, був і капітан Сандерс — старий мореплавець, що знайшов могилу у хвилях. Не бажаючи, щоб його тяжко здобуті статки поглинуло Велике Море чи просто розікрали падальники, старий морський вовк записав низку загадкових вказівок і залишив слід, яким пройде лише наполегливий шукач пригод."},{t="Іржавий якір",b="Перший крок пошуків веде до самотнього іржавого якоря, що лежить у прибої на західному узбережжі. Наполовину закопана в пісок біля уламків корабля, стара капітанська скриня вистояла під ударами хвиль. Усередині — не золото, а морська вода, пісок і несподіваний охоронець: метушливий краб, що стискає наступну частину головоломки Сандерса."}},faq={{q="Хто такий Капітан Сандерс?",a="Капітан Сандерс — моряк, чий корабель розбився біля підступних берегів Вестфолу. Знаючи, що йому судилася смерть у морі, він лишив мапу й низку підказок, що ведуть до його захованої здобичі.",al={"лор капітана сандерса","хто такий сандерс","минуле сандерса"}},{q="Де стоїть скриня?",a="Скриня напівзасипана піском на західному узбережжі Вестфолу. Уздовж пляжів чимало корабельних остовів, але Сандерс зазначив, що вона лежить біля приміткого самотнього іржавого якоря на березі.",al={"місце скрині","де іржавий якір","знайти скриню сандерса"}},{q="Чи є в скрині скарб капітана?",a="Мапа веде вас до скрині й до наступної підказки в довшому полюванні за скарбом.",al={"чи є скарб у скрині","що в скрині","де золото"}},{q="Скільки підказок у полюванні за скарбом Капітана Сандерса?",a="Полювання охоплює чотири кроки узбережжям і околицями Вестфолу: воно починається з мапи й завершується знахідкою справжньої закопаної скрині зі скарбом Капітана Сандерса.",al={"скільки підказок","довжина завдання сандерса","ланцюжок сандерса"}},{q="Чому Капітан Сандерс закопав скарб у Вестфолі?",a="Корабель Сандерса розбився біля узбережжя Вестфолу. Перед лицем неминучої смерті капітан сховав скриню й розкидав підказки біля знайомих прибережних прикмет, щоб гідний шукач міг забрати його добро.",al={"чому сандерс закопав у вестфолі","чому узбережжя вестфолу"}},{q="Чи можуть гравці Орди йти за цією мапою?",a="Так. Мапа Капітана Сандерса й подальші підказки нейтральні, тож за його слідом може піти будь-який шукач пригод, якого викинуло на берег чи який наважився дослідити узбережжя Вестфолу.",al={"чи орда може йти за мапою","завдання сандерса орди","нейтральний скарб"}}},fp="32,330,23.445.0,16.355.1,24.207.0,32.215.0,51.84.1,53.176.0,54.218.0,43.168.0"}
P.entries["quest:1361"] = {n="Реґтар Дезґейт",s="Це доручення посилає бувалих поборників Орди з великих столиць посилити заставу в західних Пустках. Досвідчений воїн Реґтар Дезґейт збирає вправних добровольців для майбутнього походу через гори, у посушливі пустища Пустограю. Він шукає тих, хто готовий понести сталь Орди проти кланів кентаврів, що окопалися там і тероризують прикордоння.",h="Це доручення посилає бувалих поборників Орди з великих столиць посилити заставу в західних Пустках.",kw={"реґтар дезґейт","пустограй","кентаври","колкари","перехрестя","пустки"},ang={["class:Warrior"]="Реґтар цінує пряму бойову вправність і непохитну дисципліну, тож його поклик до зброї — природне випробування для воїнів передової, що прагнуть перевірити себе у ворожих безплідних землях.",["faction:Horde"]="Це доручення — приклад активної оборони кордонів Орди: войовничих кентаврів у сусідньому Пустограї треба приборкати, перш ніж вони почнуть нападати вглиб Пусток.",["race:Tauren"]="Поколіннями зазнаючи жорстоких війн із кентаврами в центральному Калімдорі, таурени-воїни мають особисті рахунки, тож охоче допоможуть Реґтарові вдарити по колкарах."},sec={{t="Поклик соратників Вождя",b="По всьому Калімдору впливові провідники Орди — серед них Тіньовий Мисливець Вол'джин, Назґрел і бувалі командири на кшталт Белґрома Рокмола — пильно стежать за загрозами на кордонах. У Пустках досвідчений воїн на ім'я Реґтар Дезґейт облаштував оборонний пост, що стереже західні перевали. Розуміючи, що для місцевих сутичок потрібні загартовані бійці, а не зелені новобранці, офіцери Орди посилають перевірених шукачів пригод на захід від Перехрестя — на поклик Реґтара."},{t="Дорога до Пустограю",b="Реґтар Дезґейт стоїть в укріпленому редуті, що вріс у хребти на захід від Перехрестя. Звідти він стежить за західними гірськими стежками, що в'ються до спустошених безплідних земель Пустограю. Його наказ прямий і непохитний: зібрати передовий загін, здатний подолати ворожі терени й ударити просто в серце колкарів та інших войовничих кланів кентаврів, перш ніж їхнє жорстоке розширення загрожуватиме землям Орди."}},faq={{q="Хто такий Реґтар Дезґейт?",a="Реґтар Дезґейт — орк-воїн і командир Орди в Пустках. Відповідаючи за безпеку прикордоння, він організовує розвідку й військові удари вглиб небезпечних, засипаних попелом просторів Пустограю.",al={"хто такий реґтар","лор реґтара дезґейта","хто давець"}},{q="Де знайти Реґтара Дезґейта?",a="Він у Пустках, в укріплених бункерах Орди на стежці на пагорбі просто на захід від Перехрестя, звідки видно західний гірський перевал.",al={"де реґтар","місце реґтара","знайти реґтара дезґейта"}},{q="Хто дає завдання розшукати Реґтара?",a="Це доручення дають кілька помітних провідників і воєначальників Орди: мисливець тіней Вол'джин, Назґрел і Белґром Рокмол в Оргріммарі та Краск у Таррен Міллі.",al={"хто дає завдання розшукати реґтара","де взяти завдання реґтара"}},{q="Яка головна мета доручення Реґтара?",a="Реґтар набирає вправних воїнів, щоб перейти гори в Пустограй і почати наступ на ворожі клани кентаврів, передусім на колкарів.",al={"мета доручення реґтара","чого хоче реґтар"}},{q="Чому Орду турбує Пустограй?",a="Пустограй — спустошений війною дикий край, який заполонили агресивні клани кентаврів. Якщо їх не стримати, їхні набіги можуть перекинутися через гірські перевали в Пустки й на сусідні поселення Орди.",al={"чому орду турбує пустограй","навіщо в пустограй"}},{q="Що далі після розмови з Реґтаром Дезґейтом?",a="Щойно ви доповідаєте Реґтарові, він одразу розповідає про становище за західними горами й доручає вам перший удар за кордоном — у завданні «Колкари Пустограю».",al={"що після реґтара","наступне завдання після реґтара"}}},fp="17,377,34.505.0,20.468.0,25.215.0,35.165.0,40.177.0,51.166.0,41.204.0,54.193.0"}
P.entries["quest:1362"] = {n="Колкари Пустограю",s="Це завдання поєднує військові дії Орди в Пустках і на похмурих просторах Пустограю. За наказом оркського воїна Реґтара Дезґейта звитяжці Орди вирушають на захід через гори, щоб посилити розвідника Фелґура Тукатса на Заставі Духоходів.",h="Це завдання поєднує військові дії Орди в Пустках і на похмурих просторах Пустограю.",kw={"колкари пустограю","колкари","кентаври","пустограй","реґтар дезґейт","застава духоходів"},ang={["faction:Horde"]="Це завдання знаменує важливий стратегічний поворот для Орди: від захисту молодих поселень у Дуротарі й Пустках до наступальних військових кампаній глибоко на ворожих чужих рубежах.",["race:Orc"]="Закріпившись у східному Калімдорі, орки вважають неприборкані кентаврські клани постійною небезпекою, яку треба впокорити, щоб уберегти шляхи постачання Орди.",["race:Tauren"]="Ще до союзу з Траллом кентаврська агресія поставила кочові племена тауренів на межу знищення. Перенести бій просто на рідні землі кентаврів у Пустограї — для кожного тауренського воїна глибоко особиста справа."},sec={{t="Загроза за горами",b="Поки Орда відбивається від зграй кентаврів-мародерів у Пустках, командири на кшталт Реґтара Дезґейта розуміють: обрізаючи гілки, дерева не вб'єш. Сила клану Колкар сягає корінням просто в спустошені скелі західного узбережжя Калімдору. Доки їхня родова твердиня неприборкана, нескінченні хвилі нападників просочуватимуться крізь перевали на землі Орди. Щоб знешкодити Колкарів, треба вдарити по самому джерелу."},{t="Застава Духоходів",b="Щоб протистояти серцю кентаврських земель, Орда тримає суворе передове укріплення — Заставу Духоходів. Глибоко в Пустограї розвідник Фелґур Тукатс збирає відомості про ворогуючі між собою кентаврські клани. Реґтар відсилає ветеранів Пусток на захід, щоб вони віддали свої клинки під командування Фелґура, — так Орда переходить від пасивної оборони до активної кампанії, що розхитує ворога."}},faq={{q="Хто посилає мене з цим дорученням?",a="Реґтар Дезґейт, орк-воїн із бункера на захід від Перехрестя в Пустках, велить вам перенести бій просто на землі предків колкарів.",al={"хто посилає","давець завдання","реґтар"}},{q="Де розташована Застава Духоходів?",a="Застава Духоходів — відлюдний табір Орди при скелястих стежках Пустограю, на західному боці гірського пасма Калімдору.",al={"де застава духоходів","місце фелґура тукатса","табір пустограю"}},{q="Чому Орда зосередилася на Пустограї?",a="Колкари, що грабують Пустки, походять із більших кланів кентаврів, які вкоренилися в Пустограї. Реґтар розуміє, що оборона в Пустках ніколи не зупинить набігів назавжди, доки не підірвано твердиню колкарів у Пустограї.",al={"чому орда в пустограї","чому воювати з колкарами","зв'язок із кентаврами"}},{q="Хто такий Фелґур Тукатс?",a="Фелґур Тукатс — розвідник Орди на Заставі Духоходів, якому доручено стежити за ворожими між собою кланами кентаврів у Пустограї й організовувати удари проти них.",al={"фелґур тукатс","хто такий фелґур"}},{q="Чи доведеться в цьому завданні битися?",a="Ні. Це перехідне завдання посланця, що веде шукачів пригод з Орди від конфліктів середніх рівнів у Пустках до складніших випробувань Пустограю.",al={"чи треба битися","бій у завданні"}},{q="Проти якого клану кентаврів це завдання?",a="Воно спрямоване саме проти клану колкарів — одного з головних кланів кентаврів із Пустограю, що агресивно поширився в Пустки й Дуротар.",al={"проти якого клану кентаврів","який кентавр","клан колкар"}}},fp="22,256,29.454.0,17.373.0,29.169.0,35.153.0,38.241.0,22.168.0,31.169.0,42.163.0"}
P.entries["quest:138"] = {n="Захований скарб капітана Сандерса",s="Це завдання — другий етап пошуків скарбу, які загадковий пірат капітан Сандерс розкидав по всьому Вестфолу. Ідучи за вказівками з покинутої приморської скрині, шукачі мають рушити на схід від узбережжя, щоб знайти ще одну підказку, сховану в старій бочці біля кам'яних руїн.",h="Це завдання — другий етап пошуків скарбу, які загадковий пірат капітан Сандерс розкидав по всьому Вестфолу.",kw={"скарб капітана сандерса","капітан сандерс","підказка","бочка","руїни","вестфол"},ang={["class:Rogue"]="Розгадувати піратські шифри й нишпорити покинутими руїнами в пошуках забутої здобичі — звична справа для тих, хто цінує скритність, хитрість і швидкий зиск.",["faction:Alliance"]="Поки місцеве ополчення Вестфолу бореться з організованими розбійниками, слід Сандерса дарує рідкісну розвагу, що веде і беззаконним узбережжям, і занедбаними дорогами вглибині краю."},sec={{t="Загадки вглибині суходолу",b="Капітан Сандерс не закопав свою здобич під єдиним хрестиком на піщаному пляжі — він розкидав загадки по всьому краю. Тим, хто розгадав його перший шифр на березі, велено покинути вируючий приплив і видертися скелястими кручами вглиб суходолу шляхом, що невпинно піднімається до головних доріг Вестфолу."},{t="Руїни край дороги",b="Підказка веде шукачів просто до старого димаря серед придорожніх руїн, де в покинутій, вивітреній бочці сховано наступне послання. Пірат, вочевидь, добре знав прикмети Вестфолу й використав рештки зруйнованих господарств, щоб уберегти віхи своїх хитромудрих пошуків."}},faq={{q="Хто такий Капітан Сандерс?",a="Капітан Сандерс — піратський капітан, що орудував біля узбережжя Вестфолу. Замість сховати награбоване у звичайному сховку, він розкидав по краю ланцюжок підказок і загадок — виклик кожному, хто захоче заволодіти його захованим багатством.",al={"лор капітана сандерса","хто такий сандерс","пірат сандерс"}},{q="Куди веде ця підказка?",a="Підказка веде шукачів просто на схід, угору кручами від західного моря, аж до дороги. Там, біля старого зруйнованого кам'яного комина, стоїть розбита бочка, у якій схована наступна частина загадки.",al={"куди веде підказка","куди йти","місце димаря"}},{q="Чому Сандерс сховав скарб частинами?",a="Пірати зазвичай ховали нечесно здобуте, щоб воно не дісталося суперникам і владі. Сандерс подбав ще більше: розбив свої вказівки на багатоступеневі загадки, щоб лише наполегливий і кмітливий шукач дійшов слідом до останнього сховку.",al={"чому сховав частинами","чому підказки"}},{q="Чи небезпечно йти за цими підказками?",a="Самі підказки — лише пергамент і старі посудини, але, мандруючи Вестфолом, шукачі натрапляють на бродячих звірів, гнолів, що никають довкола, і ворожих членів Братства Дефіас, які тримають довколишні поля й покинуті садиби.",al={"чи небезпечно","небезпеки вестфолу"}},{q="Біля яких руїн схована бочка?",a="Бочка стоїть біля розваленого кам'яного комина зруйнованої будівлі при дорозі — однієї з багатьох садиб Вестфолу, покинутих чи зруйнованих за останні неспокійні роки.",al={"які руїни з бочкою","руїни димаря"}},{q="Чи це завдання відкриває сам скарб?",a="Ні. Цей крок дає лише ще одну підказку. Сандерс задумав своє полювання так, щоб провести шукачів кількома етапами через увесь край, перш ніж вони знайдуть справжню нагороду.",al={"чи це скриня","чи отримаю здобич"}}},fp="32,303,25.357.0,20.310.0,24.250.0,30.214.0,44.284.0,41.257.0,45.190.0,43.168.0"}
P.entries["quest:139"] = {n="Захований скарб капітана Сандерса",s="Це завдання — третій етап пошуків скарбу капітана Сандерса узбережжям Вестфолу. Знайдений у розбитій бочці пергамент скеровує шукачів скарбів на північ, до старого глека біля прибережного вітряка. Ці загадкові вказівки ведуть шукачів пригод далі слідом покійного пірата — до його легендарної схованки.",h="Це завдання — третій етап пошуків скарбу капітана Сандерса узбережжям Вестфолу.",kw={"скарб капітана сандерса","капітан сандерс","вітряк","глек","підказка","вестфол"},ang={["class:Rogue"]="Іти за слідом шахрая — таємними схованками й прихованими посланнями вздовж круч — звична справа для кожного розбійника, що знається на прибережній контрабанді.",["faction:Alliance"]="Поки Вестфол потерпає від голоду й розбійників Дефіасу, загублена піратська здобич Сандерса — бажаний несподіваний зиск для вільних шукачів пригод."},sec={{t="Піратський слід із хлібних крихт",b="Капітан Сандерс ніколи не записував місце своєї схованки на одному аркуші пергаменту. Натомість він розбив свої вказівки на послідовні пошуки, розкидані західним узбережжям Вестфолу. Кожна знайдена підказка вказує лише на наступну проміжну схованку, тож будь-якому охочому до чужого добра доведеться власними ногами пройти кручі, де повно піратів, щоб забрати здобич."},{t="На північ, до круч",b="Підказка з розбитої бочки велить шукачам іти просто на північ, навпростець, як летить ворона, до морських скель. На цих кручах самотньо стоїть вітряк, а біля нього покинутий глек ховає наступну ланку піратської головоломки. Для мандрівників на узбережжі Вестфолу йти за підказками Сандерса — означає пробиратися землею, де кишать і мурлоки, і падальники з Дефіасу."}},faq={{q="Що таке Захований скарб Капітана Сандерса?",a="Капітан Сандерс — буканір, що сховав свої багатства на узбережжі Вестфолу. Замість звичайної мапи він лишив слід із записаних загадок у бочках, скринях і глечиках, розкиданих по всьому краю.",al={"що таке скарб сандерса","що це за завдання","хто такий сандерс"}},{q="Куди веде ця третя підказка?",a="Пергамент велить іти просто на північ від розбитої бочки до круч над океаном. Там, біля самотнього вітряка, стоїть старий глечик з останньою підказкою.",al={"куди третя підказка","куди йти","де вітряк"}},{q="Чому Сандерс сховав свої вказівки частинами?",a="Пірати Великого Моря часто вживали хитромудрих заходів, щоб уберегти здобич від бунтівних товаришів по команді й суперників-грабіжників. Розбивши шлях на кілька схованих позначок, Сандерс подбав, щоб знахідка однієї підказки ще не означала втрати скарбу.",al={"чому сховав частинами","чому не повна мапа"}},{q="Чи можуть гравці Орди пройти цим слідом?",a="Підказки й предмети, пов'язані зі сховком Капітана Сандерса, нейтральні: з ними може взаємодіяти будь-який шукач пригод, що їх знайде, хоча Вестфол лежить глибоко на землях Альянсу.",al={"чи лише альянс","скарб сандерса орда"}},{q="Чи ця підказка прямо вказує на скриню?",a="Ні. У глечику біля прибережного вітряка ще одна підказка, яка вказує на справжнє місце, де лежить скриня Сандерса, — тож це передостанній крок полювання.",al={"чи скарб у глечику","останній крок"}},{q="Які небезпеки чатують на шляху до вітряка?",a="Західними кручами й пляжами Вестфолу никають гноли Річколапів, прибережні мурлоки й бродячі бандити Дефіас, тож простий марш на північ небезпечний для необачних.",al={"небезпеки до вітряка","небезпеки на стрімчаках"}}},fp="32,342,27.414.0,23.407.0,41.218.0,32.179.0,46.266.0,38.186.0,41.170.0,48.184.0"}
P.entries["quest:14"] = {n="Народне ополчення",s="Це завдання — кульмінація кампанії Ґраяна Стаутмантла, що прагне очистити шляхи й ниви Вестфолу від Братства Дефіас. Полюючи на досвідчених розбійників, що окопалися на півдні, у Кинджальних Пагорбах, добровольці доводять свою відданість і стають повноправними членами Народного ополчення Сентінел Гілла.",h="Це завдання — кульмінація кампанії Ґраяна Стаутмантла, що прагне очистити шляхи й ниви Вестфолу від Братства...",kw={"народне ополчення","ґраян стаутмантл","кинджальні пагорби","братство дефіас","сентінел гілл","вестфол"},ang={["class:Paladin"]="Стаутмантл закликає благословення Світла на нових членів ополчення, і в цьому відбиваються святі ідеали справедливості й захисту беззахисних від хижих розбійників.",["faction:Alliance"]="Неспроможність Стормвінда захистити Вестфол змушує простий люд Альянсу проливати власну кров, щоб підтримувати лад на рідній землі.",["race:Human"]="Для людей Стормвінда це доручення означає стати на захист забутих співвітчизників, чий хліб покинула напризволяще політична верхівка столиці."},sec={{t="Очищення Кинджальних Пагорбів",b="Північні ниви Вестфолу тяжко потерпіли від Братства Дефіас, але розбійники, що вислизнули з перших облав Стаутмантла, відступили на південь, у скелясті урвища Кинджальних Пагорбів. Звідти, з непривітної місцевості, грабіжники з великої дороги, слідопити й кастетники Дефіасу й далі нападають на сільські господарства й перехоплюють мандрівників. Щоб зламати їхню владу над південною частиною краю, Народне ополчення відправляє в пагорби загартованих новобранців — розгромити ці зграї просто на місці."},{t="Похід Стаутмантла",b="Ґраян Стаутмантл заснував Народне ополчення, коли повернувся додому з війни проти Погибелі в Лордероні й побачив, що королівський гарнізон Стормвінда цілком покинув Вестфол. Зіткнувшись із нестримним злочинним угрупованням і голодними фермерами, вигнаними зі своєї землі, він закликав місцевих добровольців до зброї. Хто повністю виконає цей останній етап патрульної служби, той офіційно вступає до ополчення з благословенням Стаутмантла у Світлі — а боротьба з братством тим часом лише глибшає."}},faq={{q="Де Кинджальні Пагорби?",a="Кинджальні Пагорби лежать на півдні Вестфолу, на південний захід від Сентінел Гілла. Скелясті кряжі й покинуті шахтні входи тут правлять за опорний пункт і сховок для найзапекліших бійців Братства Дефіас.",al={"місце кинджальних пагорбів","де кинджальні пагорби","де розбійники"}},{q="Чому Народне ополчення воює з Дефіас самотужки?",a="Король Варіан Рінн зник, ресурси розпорошені, і Дім Вельмож у Стормвінді відмовляється відрядити королівську армію на захист сільського Вестфолу. Ґраянові Стаутмантлу й місцевим фермерам не лишалося нічого іншого, як створити власні добровольчі загони, щоб боронити свої домівки.",al={"чому ополчення само воює","де армія стормвінда","чому вестфол покинуто"}},{q="Чого досягає виконання цього доручення?",a="Знищивши розбійників із великої дороги, слідопитів і кастетників, ви ламаєте владу Дефіас над дорогами південного Вестфолу й офіційно вступаєте до Народного ополчення під командуванням Ґраяна Стаутмантла.",al={"чого досягаю завершенням","завершення ополчення","нагорода за ополчення"}},{q="Хто такий Ґраян Стаутмантл?",a="Ґраян Стаутмантл — досвідчений вояк, що воював у Третій війні в Лордероні. Повернувшись додому, у Вестфол, і побачивши, як Королівство Стормвінд покинуло своїх селян, він заснував Народне ополчення на Сентінел Гіллі, щоб дати відсіч Дефіас.",al={"хто такий ґраян","історія ґраяна","керівник сентінел гілла"}},{q="Які Дефіас ховаються в Кинджальних Пагорбах?",a="У Кинджальних Пагорбах переховуються досвідчені Розбійники з великої дороги Дефіас, смертоносні Слідопити й жорстокі Кастетники, які влаштовують напади на південь Вестфолу й стережуть глибші твердині Братства.",al={"які дефіас у кинджальних пагорбах","дефіас півдня вестфолу","хто в кинджальних пагорбах"}},{q="Як це пов'язано з Лордероном?",a="Ґраян Стаутмантл згадує, що нещодавно повернувся з «осквернених земель Лордерона», де Альянс бився з Погибеллю. Пережите на тому похмурому театрі війни дало йому рішучість організувати оборону Вестфолу, коли місцева влада не впоралася.",al={"ґраян лордерон","скверні землі лордерону","історія воєн ґраяна"}}},fp="20,306,24.514.0,21.516.0,27.203.0,54.268.0,39.204.0,25.272.0,45.198.0,35.250.0"}
P.entries["quest:140"] = {n="Захований скарб капітана Сандерса",s="Це завершення пошуків скарбу капітана Сандерса у Вестфолі. Ідучи за просякнутою віскі запискою, знайденою в старому глеку, шукачі статків вирушають від західного узбережжя по давно закопану схованку. Пригода веде у відкрите море, далеко від негараздів суходолу, — до віддаленого прибережного острівця.",h="Це завершення пошуків скарбу капітана Сандерса у Вестфолі.",kw={"скарб капітана сандерса","капітан сандерс","острівець","скриня","вестфол","пірат"},ang={["class:Rogue"]="Іти слідом шахрая безлюдними пляжами й далі в море — звична справа для кожного розбійника, що цінує піратську контрабанду.",["race:Human"]="Для людей, що боронять Вестфол від розбійників Дефіасу й гнолів, пошуки забутої схованки місцевого пірата — приємний перепочинок від патрулювання ферм."},sec={{t="Слід моряка",b="Капітан Сандерс залишив низку підказок, розкиданих узбережжям Вестфолу, і кинув виклик кожній відчайдушній душі, що наважиться скласти їх докупи. Останній пергамент, витягнутий з осаду на дні його улюбленого глека з-під віскі, дає завершальний напрямок. Розмите чорнило, виразний запах трунку — а вказівки капітана прості: іти просто на захід до самої води й пірнути у хвилі."},{t="Самотній острівець",b="Біля узбережжя Вестфолу з бурхливого Великого Моря здіймаються невеликі скелясті острівці. Якщо пливти точно на захід, потрапиш просто до одного з них — саме там капітан Сандерс сховав свій скарб. Наполовину прихована скриня роками терпіла солоний прибій, але її іржаві завіси зрештою піддаються тим, хто має досить упертості, щоб довести гру буканьєра до кінця."}},faq={{q="Куди веде остання підказка?",a="Просякнута віскі записка в Старому Глечику велить шукачам скарбів іти просто на захід до берега Вестфолу й пливти далі в океан. Скриня чекає на маленькому острівці посеред води.",al={"куди остання підказка","де скриня","місце скарбу сандерса"}},{q="Хто такий Капітан Сандерс?",a="Капітан Сандерс — буканір, що плавав водами біля Вестфолу. Замість тримати здобич у банку чи твердині, він проклав уздовж узбережжя слід із загадками й закопав свою скриньку на віддаленому острівці біля берега.",al={"хто такий сандерс","лор сандерса","капітан сандерс минуле"}},{q="Чому остання підказка пахне віскі?",a="Останні вказівки були вкладені в покинутий глечик з-під віскі Капітана Сандерса біля узбережжя. Від вологи й трунку чорнило з часом розпливлося, але вказівки досі можна розібрати.",al={"чому підказка пахне віскі","записка віскі"}},{q="Скільки кроків у цьому полюванні за скарбом?",a="Полювання має чотири етапи. Воно починається з побитої морем мапи скарбів, знайденої на узбережжі, веде через кілька схованих посудин — скриню, бочку й глечик з-під віскі — і завершується закопаною скринею.",al={"скільки кроків","довжина завдання сандерса","ланцюжок капітана сандерса"}},{q="Чи небезпечно дістатися до острова?",a="Головне випробування — довгий заплив у Велике Море. Хоча прибережні води Вестфолу часто непокоять агресивні мурлоки й морські звірі, сам острівець правив Сандерсові передусім за особистий сховок.",al={"чи небезпечно до острова","пливти до скрині","мурлоки біля скрині"}},{q="У якому стані скриня зі скарбом?",a="Від вологого морського повітря й прибою скриня постраждала. Її завіси геть заіржавіли, але, трохи піддавши, її можна відкрити й забрати те, що лишилося всередині.",al={"стан скрині","чи скриня замкнена","іржава скриня"}}},fp="32,327,16.393.0,16.359.1,31.208.0,24.246.0,44.209.0,41.246.0,33.220.0,36.204.0"}
P.entries["quest:141"] = {n="Братство Дефіас",s="Доручення — доставити таємний звіт Матіаса Шоу зі Стормвінда Ґраянові Стаутмантлу в Сентінел Гілл. Шоу дослідив колишню Гільдію Каменярів, щоб допомогти Стаутмантлові з'ясувати, звідки взялося Братство Дефіас.",h="Доручення — доставити таємний звіт Матіаса Шоу зі Стормвінда Ґраянові Стаутмантлу в Сентінел Гілл.",kw={"братство дефіас","звіт шоу","едвін венкліф","гільдія каменярів","матіас шоу","ґраян стаутмантл"},ang={["class:Rogue"]="Розслідування щодо колишніх ремісників Стормвінда показує, як чвари всередині королівства можуть відгукнутися лихом у його далеких поселеннях.",["faction:Alliance"]="Бунт каменярів оголює глибокі тріщини в королівстві: ті самі робітники, що відбудували кам'яні мури Стормвінда, тепер погрожують їх зруйнувати.",["race:Human"]="Для людей Стормвінда це відкриття — дуже болюче. Стіни їхніх домівок і навіть Собор звели ті самі люди, що тепер плюндрують сільський Вестфол."},sec={{t="Будівничий, що став розбійником",b="Місяцями Ґраян Стаутмантл і Народне ополчення билися з наче безликим повстанням грабіжників, злодіїв і горлорізів по всьому Вестфолу. Коли Майстер Матіас Шоу з SI:7 вивчає Записку Вайлі, він складає докупи приголомшливу правду: гільдія архітекторів і каменярів, що відбудувала білі мури Стормвінда, так і не розпалася. Натомість її ватажок, Едвін Венкліф, повів її в підпілля."},{t="Гіркота й зрада",b="Після спустошення Першої війни Стормвінд лежав у попелі. Гільдія Каменярів Венкліфа взялася за велетенську працю — відбудувати столицю королівства й знову зробити її перлиною людства. Та коли роботу завершили, спалахнула гірка суперечка про плату. Невдоволені тим, як із ними повелися корона й Дім Вельмож, Венкліф і його майстри взялися за кинджали й червоні бандани — і від мирного ремесла перейшли до кривавого бунту проти трону."},{t="Недовіра Стаутмантла",b="Коли звіт Шоу доходить до Сентінел Гілла, Ґраянові Стаутмантлу важко змиритися з цією звісткою. Він пам'ятає Венкліфа не горлорізом, що ховається в тінях сільської глушини, а працьовитим і обдарованим майстром, чия праця дала прихисток тисячам городян, що поверталися додому. Почувши таке тривожне звинувачення, командир ополчення вимагає незаперечних доказів, перш ніж повірити, що головний архітектор Стормвінда стоїть за руйнуванням Вестфолу."}},faq={{q="Що таке Звіт Шоу?",a="У ньому — висновки Матіаса Шоу щодо колишньої Гільдії Каменярів і Дефіас. Доставте таємний звіт Ґраянові Стаутмантлу.",al={"що таке звіт шоу","документ шоу","звіт до стаутмантла"}},{q="Хто такий Едвін Венкліф?",a="Едвін Венкліф очолював Гільдію Каменярів, що відбудувала Стормвінд. Звіт досліджує подальшу історію гільдії.",al={"хто такий венкліф","особа венкліфа","едвін венкліф"}},{q="Чому Ґраян Стаутмантл недовірливо ставиться до звіту?",a="Стаутмантлові важко повірити в звинувачення Шоу, і він хоче більше доказів. Подробиці з'ясовуються, коли він читає звіт.",al={"чому ґраян не вірить звіту","реакція стаутмантла","чому потрібні докази"}},{q="Чому каменярі обернулися проти Стормвінда?",a="Каменярі відбудували Стормвінд, але посварилися зі знаттю через плату. Звіт Шоу досліджує, що було далі.",al={"чому каменярі проти стормвінда","чому дефіас лютують","мотив венкліфа"}},{q="Яку роль у цьому завданні відіграє SI:7?",a="Шоу розслідує можливі зв'язки між колишньою гільдією й розбійниками й надсилає свої висновки Стаутмантлові.",al={"роль таємної служби","чому матіас шоу","гільдія розбійників стормвінда"}},{q="Куди веде це розслідування далі?",a="Доставте звіт, а тоді допоможіть Стаутмантлові шукати нових доказів у розслідуванні щодо Дефіас.",al={"що далі","наступне завдання дефіас","після звіту шоу"}}},fp="22,214,23.409.1,23.489.1,23.463.1,22.137.0,22.127.0,49.136.0,47.138.0,39.110.0,40.102.1"}
P.entries["quest:142"] = {n="Братство Дефіас",s="Це важливе доручення веде шукачів пригод курними шляхами Вестфолу на полювання за мандрівним Посланцем Дефіасу. Перехоплені донесення дають Ґраянові Стаутмантлу й Народному ополченню змогу здобути вкрай важливі відомості про розбійницьке повстання.",h="Це важливе доручення веде шукачів пригод курними шляхами Вестфолу на полювання за мандрівним Посланцем...",kw={"братство дефіас","посланець дефіасу","едвін венкліф","мунбрук","ґраян стаутмантл","вестфол"},ang={["class:Rogue"]="Полювання на гінців Дефіасу показує, як вправні розвідники й злодюжки координують розгалужену тіньову мережу просто під носом в ополчення.",["faction:Alliance"]="Мовчання Стормвінда змушує Народне ополчення Вестфолу самотужки здобувати відомості в краї, вистежуючи гінців на безлюдних ґрунтових дорогах без підтримки королівського гарнізону.",["race:Human"]="Для людей королівства слід донесень, що веде до Едвіна Венкліфа, оголює гіркі, досі відчутні наслідки політичних і трудових суперечок Стормвінда."},sec={{t="Перехопити гінця",b="Розвідники Ґраяна Стаутмантла помітили невловимого Посланця Дефіасу, що курсує між головними розбійницькими осередками — Мунбруком, Кар'єром Золотого Узбережжя й Шахтою Джанґолод. На відміну від звичайних головорізів, що тримають сільську місцевість, цей гонець возить по краю важливі письмові накази. Стаутмантл велить схопити або вбити гінця, щоб Народне ополчення прочитало вміст його торби й зрозуміло, звідки братство командує своїми силами."},{t="Чорнильний слід",b="Послання, відібране в гінця, незаперечно підтверджує, що Едвін Венкліф — легендарний колишній ватажок Гільдії Каменярів — особисто керує заколотом Дефіасу. Хоч перехоплена записка й засвідчує владу Венкліфа над місцевими осередками, вона все ж не вказує точно, де його таємна база."},{t="Щасливий поворот",b="Саме тоді, коли накази посланця підтверджують провідну роль Венкліфа, Народному ополченню щастить. Зневірений розбійник, якого спіймали на спробі вкрасти віз фермера Салдіна, погоджується стати зрадником в обмін на життя. Маючи на руках письмовий доказ, Стаутмантл зосереджується на цьому перебіжчикові й сподівається, що той приведе загін просто в серце схованки Дефіасу."}},faq={{q="Куди ходить Посланець Дефіасу?",a="Посланець Дефіасу починає обхід у Мунбруку біля кузні. Звідти він іде дорогами на північ, щоб навідатися до Кар'єру Золотого Узбережжя й Шахти Джанґолод, заходить в обидві підземні виробки, а тоді тим самим шляхом повертається до Мунбрука.",al={"де ходить посланець","де посланець дефіас","знайти посланця"}},{q="Що відкриває перехоплене повідомлення?",a="Стаутмантл сподівається, що письмові накази посланця розкриють будову командування Братства й допоможуть знайти його сховок. Що в них, з'ясується, коли повідомлення здобудуть.",al={"що в повідомленні","текст таємного повідомлення","записка венкліфа"}},{q="Хто такий Ґраян Стаутмантл?",a="Ґраян Стаутмантл — польовий командир Народного ополчення зі штабом на Сентінел Гіллі. Розчарований відсутністю королівської варти Стормвінда, він організовує добровольців і шукачів пригод, щоб боронити Вестфол від нападників Дефіас.",al={"роль стаутмантла","хто дає завдання"}},{q="Навіщо посланець навідується до копалень?",a="Братство захопило мінеральні багатства Вестфолу й використовує такі місця, як Шахта Джанґолод і Кар'єр Золотого Узбережжя, для сировини, сховку й опорних пунктів. Посланець тримає ці розрізнені операції вкупі за вказівками Венкліфа.",al={"чому посланець у копальнях","шахта золотого узбережжя"}},{q="Чи впіймання посланця відкриває сховок Дефіас?",a="Стаутмантл хоче скористатися перехопленими наказами, щоб просунутися в пошуках сховку. Наступний слід ви дізнаєтеся, коли повернетеся до нього.",al={"чи сховок знайдено","де сховок"}},{q="Хто такий Едвін Венкліф?",a="Едвін Венкліф був Великим Каменярем Гільдії Каменярів, що відбудувала Стормвінд. Розслідування Стаутмантла з'ясовує його можливий зв'язок із Братством.",al={"хто такий венкліф","вожак дефіас"}}},fp="22,252,24.443.0,14.340.1,17.366.1,39.250.0,41.184.1,25.227.0,40.244.0,54.137.1,22.164.0"}
P.entries["quest:143"] = {n="Гонець до Вестфолу",s="Гонець до Вестфолу — доручення Альянсу: доставити через Елвінн до Вестфолу термінове прохання Магістрата Соломона з Редріджу. Стормвіндське військо цілком покинуло Лейкшир напризволяще, тож його провід шукає взаємодопомоги в щойно створеного Народного ополчення Ґраяна Стаутмантла.",h="Гонець до Вестфолу — доручення Альянсу: доставити через Елвінн до Вестфолу термінове прохання Магістрата...",kw={"гонець до вестфолу","магістрат соломон","ґраян стаутмантл","народне ополчення","вестфол","братство дефіас"},ang={["faction:Alliance"]="Ця депеша свідчить про цілковитий занепад централізованої оборони в королівстві Стормвінд: прикордонні містечка змушені самі укладати угоди про взаємний захист.",["race:Human"]="Послання показує спільну біду людських поселенців Редріджу й Вестфолу, які мусять покладатися на добровольців і найманців, поки столиця сидить склавши руки."},sec={{t="Відчайдушне звернення",b="Магістрат Соломон бачить, що Лейкшир у відчайдушному становищі. Гори Редріджу в облозі орків Блекрок і гнолів, а військо Стормвінда так і не прибуло. Розуміючи, що на міській варті й нерегулярних загонах Лейкшир не встоїть, Соломон пише офіційне прохання про допомогу. Королівських резервів не видно, тож він звертає погляд на захід: до нього дійшли чутки, що за Лісом Елвінн збирається громадянська оборона."},{t="Через кордони",b="Адресат депеші — Ґраян Стаутмантл, досвідчений командир, що почав збирати добровольців під прапором Народного ополчення. Посилаючи гінця просто через усе королівство, Соломон сподівається, що організовані добровольці Вестфолу зможуть виділити бійців для захисту кордонів Лейкширу, доки війська Корони нарешті не рушать. Проте, як невдовзі з'ясовують гінці, Вестфол загруз у власній катастрофічній боротьбі з Братством Дефіас."}},faq={{q="Чому Магістрат Соломон просить допомоги у Вестфолу?",a="Стормвінд так і не прислав військового підкріплення, якого Лейкшир конче потребує проти орків і гнолів. Почувши, що у Вестфолі збираються озброєні загони мешканців, Соломон сподівається, що Ґраян Стаутмантл зможе виділити бійців на підмогу Редріджу.",al={"чому соломон просить вестфол","прохання соломона","чому питає ґраяна"}},{q="Хто такий Ґраян Стаутмантл?",a="Ґраян Стаутмантл — досвідчений вояк на Сентінел Гіллі у Вестфолі. Без влади й захисту корони він організував і очолив Народне ополчення, щоб боронити місцеві хутори від розбійників і Братства Дефіас.",al={"хто такий ґраян","роль стаутмантла","хто править вестфолом"}},{q="Куди веде ця доставка?",a="Послання треба віднести від ратуші в Лейкширі аж на захід через Редрідж і Ліс Елвінн, до Сентінел Гілла в центральному Вестфолі.",al={"куди доставка","де стаутмантл","з редріджу до вестфолу"}},{q="Чому армія Стормвінда не прийшла на допомогу Лейкширу?",a="Магістрат Соломон зауважує, що з армією коїться щось дивне: обіцяні війська так і не з'явилися. Провід Стормвінда загруз у безладі під регентством Болвара Фордрагона й Леді Престор, і віддалені краї мусять дбати про себе самі.",al={"чому армія стормвінда не прийшла","де королівська варта","армія стормвінда зникла"}},{q="Чи справді Вестфол може виділити бійців для Редріджу?",a="Ні. Прибувши на Сентінел Гілл, ви бачите, що Вестфол ледве тримається проти Братства Дефіас. Народному ополченню нема кого виділити, і воно насилу боронить власні кордони.",al={"чи вестфол допоможе","чи прийде ополчення","чи ґраян допоможе"}},{q="Що далі, коли лист доставлено?",a="Ґраян Стаутмантл отримує послання й одразу пише відповідь, де пояснює скрутне становище Вестфолу, і посилає вас назад із відповіддю для Магістрата Соломона.",al={"що далі","наступне завдання","після гінця до вестфолу"}}},fp="21,278,18.449.0,23.482.0,51.252.0,25.241.0,37.156.0,49.255.0,52.211.1,39.184.1"}
P.entries["quest:1431"] = {n="Відносини з Альянсом",s="Відносини з Альянсом — вступне завдання, яке дає Малодушний Дрок в Оргріммарі. Воно скеровує бувалих шукачів пригод Орди до Келдрана — містика, що тихо діє біля західного виходу з міста. Так починається розмова про делікатну закулісну дипломатію й розвідку, без яких не втримати хиткого миру Тралла з Альянсом.",h="Відносини з Альянсом — вступне завдання, яке дає Малодушний Дрок в Оргріммарі.",kw={"відносини з альянсом","келдран","малодушний дрок","тралл","дипломатія","оргріммар"},ang={["class:Rogue"]="Келдран цінує таємність і вміння впливати на сприйняття, тож його доручення особливо пасують тим, хто заробляє на життя в тіні.",["faction:Horde"]="Це доручення показує ідейну суперечність усередині Орди: традиційна груба сила проти тонкої, дипломатичної державної мудрості Тралла.",["race:Orc"]="Для орків, звиклих розв'язувати суперечки сокирою, підхід Келдрана вимагає незвичної дисципліни — терпіння й тактичної тонкості."},sec={{t="Дипломатична дилема",b="Багато орків віддають перевагу грубій силі й прямолінійним завоюванням, але Вождь Тралл розуміє, що нескінченна війна з Альянсом занапастить його молоду державу. Вирісши в людській неволі, Тралл засвоїв тонкощі людського державного мистецтва й військової стратегії. Малодушний Дрок помічає воїнів і поборників, яким, можливо, вистачить терпіння на тонший підхід, і радить їм дивитися далі за грубу силу."},{t="Халупа Келдрана",b="Біля західної брами Оргріммара притулилася скромна оселя Келдрана — знавця магії й таємних мистецтв. На відміну від галасливих воїнів, що п'ють у Долині Сили, Келдран має справу з враженнями, сприйняттям і державними справами. Він шукає агентів, здатних діяти обачно від імені Вождя й лавірувати в напруженому протистоянні Орди з її запеклими суперниками."}},faq={{q="Хто дає завдання «Відносини з Альянсом»?",a="Це завдання дає Малодушний Дрок в Оргріммарі шукачам пригод з Орди, які досягли тридцятого рівня досвіду.",al={"хто дає відносини з альянсом","давець відносин з альянсом","де взяти"}},{q="Де знайти Келдрана?",a="Келдран живе в невеликій халупі біля західного виходу з Оргріммара, подалі від гамірного центру міста.",al={"місце келдрана","де келдран","келдран оргріммар"}},{q="Яка роль Келдрана в Оргріммарі?",a="Келдран — учень магії й містичних мистецтв, що допомагає Вождеві Траллу в делікатних справах, особливо пов'язаних із дипломатією, розвідкою й тим, як Орду сприймають інші.",al={"роль келдрана","хто такий келдран"}},{q="Чому Траллу важлива дипломатія з Альянсом?",a="Тралл виріс серед людей і добре знає їхню політику й військову силу. Розуміючи, що відкрита війна може знищити його молодий народ, він обирає розважливість і виважене державництво, щоб уберегти майбутнє Орди.",al={"чому траллу важлива дипломатія","мир орди з альянсом","тралл і люди"}},{q="Чи веде це завдання до подальших доручень?",a="Так, коли ви здаєте це доручення Келдранові, починається глибша розмова про становище Орди серед інших фракцій, що веде просто до наступних завдань, пов'язаних із дипломатією й розвідкою в краях.",al={"подальші доручення","що після відносин з альянсом"}},{q="Чому в цьому дорученні така важлива потайність?",a="Відкритий конфлікт з Альянсом загрожує величезними втратами й розхитуванням Калімдору. Тралл покладається на непомітних агентів, щоб гасити делікатні дипломатичні тертя, перш ніж вони вибухнуть відкритою війною.",al={"чому важлива потайність","потайність келдрана"}}},fp="18,359,20.415.0,15.401.0,39.118.0,25.120.0,36.193.0,55.229.0,41.201.0,45.191.0"}
P.entries["quest:1432"] = {n="Відносини з Альянсом",s="Відносини з Альянсом — доручення Орди, що веде з Оргріммара до Пустограю, щоб відвернути небезпечні політичні наслідки. Поки Альянс просувається вглиб центрального Калімдору, Орда завчасно вичищає місцеві сили Палаючого Легіону, перш ніж суперники встигнуть звинуватити народ Тралла в новому демонічному зіпсутті.",h="Відносини з Альянсом — доручення Орди, що веде з Оргріммара до Пустограю, щоб відвернути небезпечні політичні...",kw={"відносини з альянсом","пустограй","келдран","таката стілблейд","застава духоходів","палаючий легіон"},ang={["class:Warlock"]="Хоч звичайні вояки на кшталт Такати Стілблейд дивляться на темні сили з підозрою, операції проти диких демонів часто перетинаються з прагматичним використанням чорнокнижників в Орді.",["faction:Horde"]="Це доручення відбиває постійну боротьбу Вождя Тралла за визнання нової Орди й за те, щоб поховати спадок демонічного рабства, перш ніж ворожі сусіди скористаються ним.",["race:Orc"]="Для орків, що прагнуть шанувати Траллове бачення спокути, будь-який слід демонічної скверни в Калімдорі — гірка загроза їхній тяжко здобутій свободі."},sec={{t="Питання сприйняття",b="Поки розвідники й експедиції Альянсу мандрують Калімдором, провід Орди стикається з делікатною дипломатичною загрозою. Рештки демонів, розпорошені центральним Калімдором, можуть підтвердити давні упередження, ніби орки та їхні союзники досі в змові з Палаючим Легіоном. Діючи з дозволу Вождя Тралла, Келдран в Оргріммарі керує прицільними операціями, щоб ці демонічні рештки знищили, перш ніж ворожі сили Альянсу перекрутять їхню присутність на привід для війни."},{t="Застава серед пустищ",b="Щоб доставити накази на південь, треба пройти крізь Обвуглену Долину Гір Кам'яного Кігтя й спуститися в похмурі простори Пустограю. Там, трохи на північ від величезного Цвинтаря Кодо, стоїть Застава Духоходів. Агенти Орди, як-от Таката Стілблейд, стежать за спустошеною глушиною, лавіруючи між розгуляними племенами кентаврів і всепроникною демонічною скверною, що загрожує заполонити край."},{t="Прагматичні союзи",b="Таката Стілблейд сприймає доручення з похмурим прагматизмом. Хоч винищення місцевих демонів неминуче полегшить життя жорстоким тубільним племенам кентаврів і навіть допоможе тутешнім чорнокнижникам Орди, обов'язок понад усе. Знищення плацдармів Палаючого Легіону служить загальній безпеці Орди, хоч би хто ще виграв від цієї розправи."}},faq={{q="Чому Орду тут турбує Альянс?",a="Сили Альянсу просуваються Калімдором, і провід Орди побоюється, що гнізда демонів можуть використати як доказ того, що Орда досі знається з Палаючим Легіоном. Активно винищуючи місцевих демонів, Орда хоче позбавити ці звинувачення ґрунту.",al={"чому орда турбується про альянс","відносини орди й альянсу в пустограї","звинувачення альянсу"}},{q="Хто такий Келдран?",a="Келдран — агент Орди в Оргріммарі, що зі схвалення Вождя керує особливими дорученнями, спрямованими на знищення демонічних сил, які шкодять становищу Орди.",al={"келдран","хто такий келдран","келдран оргріммар"}},{q="Де розташована Застава Духоходів?",a="Застава Духоходів — табір у центральному Пустограї, просто на південь від перевалу з Обвугленої Долини в Горах Кам'яного Кігтя й трохи на північ від Цвинтаря Кодо.",al={"місце застави духоходів","де таката стілблейд","пошук застави духоходів"}},{q="Хто такий Таката Стілблейд?",a="Таката Стілблейд — вояк Орди на Заставі Духоходів у Пустограї, якому доручено від імені Вождя стримувати місцеві загрози на кшталт демонів і ворожих кентаврів.",al={"таката стілблейд","хто такий стілблейд","стілблейд пустограй"}},{q="Чому Таката згадує про допомогу кентаврам?",a="Кентаври вважають Пустограй своєю землею, але не мають сил стримати дедалі більшу загрозу демонів. Винищуючи місцевих демонів, Орда мимохіть допомагає кентаврам вижити, і Таката мириться з цим компромісом лише заради більшої безпеки Орди.",al={"допомога кентаврам","кентаври пустограю","чому допомагати кентаврам"}},{q="Як із цим дорученням пов'язані чорнокнижники?",a="Хоча доручення спрямоване на диких демонів, Таката з певною відразою зауважує, що прибирання демонічних реагентів і впливу неминуче перетинається зі справами суперечливих чорнокнижників Орди й допомагає їм.",al={"чорнокнижники в завданні","навіщо допомагати чорнокнижникам","чорнокнижники в орді"}}},fp="18,314,22.507.0,21.393.0,19.377.1,51.256.0,15.187.0,35.179.0,25.185.0,43.255.0,38.213.0"}
P.entries["quest:144"] = {n="Гонець до Вестфолу",s="«Гонець до Вестфолу» — дипломатичне доручення: доставити стриману відповідь Ґраяна Стаутмантла із Сентінел Гілла Магістратові Соломону в Лейкшир. Соломон, якого обсіли місцеві загрози в Редріджі, просив у Народного ополчення військового підкріплення — лише щоб дізнатися, що корона так само покинула й Вестфол.",h="«Гонець до Вестфолу» — дипломатичне доручення: доставити стриману відповідь Ґраяна Стаутмантла із Сентінел...",kw={"гонець до вестфолу","магістрат соломон","лейкшир","ґраян стаутмантл","редрідж","даркшир"},ang={["faction:Alliance"]="Це листування оголює глибокий розлом між правителями у Фортеці Стормвінда й віддаленими провінціями: Вестфол і Редрідж полишені напризволяще.",["race:Human"]="Для людських мандрівників доставка цього послання показує трагічну самотність провінційних містечок, де простолюд і ветерани стікають кров'ю, утримуючи землі, які вельможі Стормвінда відмовляються захищати."},sec={{t="Благання через хиткі кордони",b="Магістрат Соломон із Лейкширу зіткнувся з дедалі гострішими кризами в Горах Редріджу без підтримки королівського гарнізону Стормвінда. Шукаючи союзників у південних землях королівства, він звернувся до Ґраяна Стаутмантла, командира Народного ополчення у Вестфолі. Соломон сподівався, що організовані добровольці, які тримають Сентінел Гілл, зможуть виділити загін на підмогу обороні Лейкширу, — не знаючи, яка похмура дійсність панує на західних рівнинах."},{t="Гірка відмова",b="Відповідь Ґраяна Стаутмантла — недвозначна відмова, написана з важким серцем. Вестфол поглинула власна відчайдушна війна з Братством Дефіас і гнолами-мародерами — боротьба, яка стала потрібною лише тому, що Дім Вельмож і корона покинули свою житницю. Стаутмантл чітко дає зрозуміти: Народне ополчення існує заради чистого виживання; щодня воно втрачає добрих людей і не може виділити жодного бійця, щоб рятувати Редрідж."},{t="Королівство, що розпадається",b="Відповідь Стаутмантла, доставлена до Лейкширу, розвіює ілюзії Соломона. Магістрат усвідомлює, що прикордонні землі королівства покинуті однаково: місцеві магістрати й народні ополчення мусять самі давати собі раду, поки Армію Стормвінда з незрозумілих причин тримають осторонь. Розчарування змушує Соломона звернути погляд на південь — до Даркширу в Сутінколіссі."}},faq={{q="Чому Магістрат Соломон просив допомоги у Вестфолу?",a="Магістрат Соломон протистоїть дедалі більшим загрозам у Лейкширі без підтримки армії Стормвінда. Знаючи, що Ґраян Стаутмантл зібрав Народне ополчення на захист Вестфолу, Соломон сподівався, що ці прикордонні сили зможуть виділити допомогу Редріджу.",al={"чому соломон просив допомоги","прохання до вестфолу","лист соломона стаутмантлу"}},{q="Чому Ґраян Стаутмантл відмовляється допомогти?",a="Народне ополчення й так виснажене до краю боротьбою з Братством Дефіас і обороною ферм Вестфолу. Стаутмантл пояснює, що якби Стормвінд не покинув Вестфол, ополчення взагалі не довелося б створювати, і вояків у нього зайвих немає.",al={"чому ґраян відмовляється","ополчення відмовило лейкширу","відповідь стаутмантла"}},{q="Де армія Стормвінда під час цих криз?",a="Королівська армія зосереджена довкола Стормвінда, і правляча рада не випускає її в сільські краї. І Соломон, і Стаутмантл висловлюють подив і образу на те, що столиця лишає свої віддалені провінції без захисту.",al={"де армія стормвінда","чому стормвінд не допомагає","втеча стормвінда"}},{q="Що буде, коли повернеш лист Стаутмантла Соломонові?",a="Зрозумівши, що Вестфол не допоможе, Магістрат Соломон звертає погляд на Сутінколісся й посилає гінця далі, до Даркширу, сподіваючись, що допомогу натомість може надіслати Нічна Варта мера Елло Ебонлока.",al={"що після повернення листа","наступне після гінця до вестфолу"}},{q="Що таке Народне ополчення?",a="Народне ополчення — добровольче військо, яке зібрав Ґраян Стаутмантл, з осідком на Сентінел Гіллі. До нього входять місцеві фермери, ветерани й мешканці, які боронять Вестфол від розбійників і гнолів за цілковитої відсутності військ корони.",al={"що таке народне ополчення","ополчення вестфола"}},{q="Хто такий Ґраян Стаутмантл?",a="Ґраян Стаутмантл — досвідчений вояк, що взяв на себе оборону Вестфолу. Діючи з вежі на Сентінел Гіллі, він згуртовує добровольців і керує війною проти Братства Дефіас.",al={"хто такий ґраян","лор стаутмантла"}}},fp="21,319,32.470.0,16.441.0,30.395.1,49.262.0,46.273.0,48.236.0,61.195.1,29.234.0,25.204.0"}
P.entries["quest:1442"] = {n="У пошуках Самоцвіту Кор",s="«У пошуках Самоцвіту Кор» — завдання для паладинів Альянсу, яке посилає новачка глибоко в давні руїни на півночі Калімдору. За вказівкою нічного ельфа Тундріса Віндвівера з Обердайна паладини вирушають до Чорноглибинних Печер, щоб вирвати могутній Самоцвіт Кор у наг, які його псують. Здобутий камінь — ключовий матеріал для ремесла Джордана Стілвелла.",h="«У пошуках Самоцвіту Кор» — завдання для паладинів Альянсу, яке посилає новачка глибоко в давні руїни на...",kw={"самоцвіт кор","тундріс віндвівер","джордан стілвелл","чорноглибинні печери","наги","паладин"},ang={["class:Paladin"]="Це завдання — важливе випробування характеру й витривалості для паладина Альянсу: воно перевіряє вашу готовність спуститися у ворожі глибини Калімдору, щоб викувати освячену зброю Світла.",["faction:Alliance"]="Ця місія — єдність Альянсу в дії: коваль-людина покладається на мудрість нічних ельфів і дворфську сталь, щоб викувати зброю проти темряви, що насувається.",["race:NightElf"]="Співпраця Тундріса Віндвівера показує крихкий, але дедалі міцніший міст між давніми калдореями та новими союзниками — служителями Святого Світла зі Східних Королівств."},sec={{t="Довіра союзника",b="Коли паладини-учні шукають матеріали, потрібні ковалеві-людині Джорданові Стілвеллу, їхній шлях перетинає межі континентів і веде на Темне Узбережжя. Там, в Обердайні, Тундріс Віндвівер з повагою згадує коваля. Попри природну відстороненість нічних ельфів і злочини деяких занепалих людей, Тундріс вірить у паладинів, що йдуть праведним шляхом, і охоче розповідає, де шукати такі давні самоцвіти."},{t="У глибини",b="Пошуки ведуть просто до підземного храмового комплексу Чорноглибинних Печер на туманному північно-західному узбережжі Ашенвалю. Окрім культистів Молота Присмерку й підступних морських мешканців, у водяних глибинах живуть жриці наг, що спрямовують мерзенну магію крізь давні Самоцвіти Кор. Паладин мусить пройти цими темними залами, здолати чарівниць і здобути самоцвіт, просякнутий зміїною злобою."},{t="Очищення каменя",b="Коли паладин повертає Зіпсутий Самоцвіт Кор Тундрісові Віндвіверу, стає зрозуміло, навіщо було шукати ельфійського містика. Наги наповнюють самоцвіт сирою магічною силою, але їхні чари схиляють його до зла. Перш ніж Джордан Стілвелл зможе викувати з нього священну зброю, Тундріс мусить вирізати з каменя темряву, щоб його сила лишилася чистою й стабільною для священного ковальського обряду."}},faq={{q="Хто посилає шукати Самоцвіт Кор?",a="Завдання дає Тундріс Віндвівер — нічний ельф із прибережного порту Обердайн на Темному Узбережжі. Він спрямовує паладинів від імені зброяра Джордана Стілвелла.",al={"хто посилає шукати самоцвіт кор","давець самоцвіту кор","завдання тундріса віндвівера"}},{q="Де Самоцвіт Кор?",a="Самоцвіт — у Чорноглибинних Печерах, давньому підземеллі на узбережжі північно-західного Ашенвалю. Його носять жриці-наги, що живуть у руїнах.",al={"де самоцвіт кор","місце самоцвіту кор","де зіпсований самоцвіт"}},{q="Навіщо Джорданові Стілвеллу Самоцвіт Кор?",a="Самоцвіт має могутню магічну енергію, яка потрібна як складник для виготовлення вдосконаленої зброї Джордана під час випробування паладинів, відомого як «Випробування праведності».",al={"навіщо джордану стілвеллу самоцвіт","для чого самоцвіт кор","самоцвіт стілвелла"}},{q="Чому Тундріс мусить очистити самоцвіт?",a="Наги наснажують самоцвіти Кор значною таємною силою, але їхня мерзенна природа псує магію. Тундріс очищує самоцвіт від скверни, щоб його силу можна було безпечно вкласти у зброю Світла.",al={"чому очистити самоцвіт","очищення самоцвіту","очищений самоцвіт"}},{q="Чому Тундріс згадує «занепалих»?",a="Тундріс, певно, натякає на гучні зради людей, як-от Принца Артаса Менетіла, чиє падіння в темряву заплямувало репутацію Срібної Длані по всьому Азероту. Попри це, Тундріс воліє судити кожного паладина за його власними заслугами.",al={"хто занепалі","тундріс занепалі","згадка падшого паладина"}},{q="Чи потрібен гурт, щоб здобути Самоцвіт Кор?",a="Тундріс прямо застерігає шукачів пригод не йти самотою. Самоцвіт падає з добірних наг глибоко в Чорноглибинних Печерах, тож іти туди дуже радять зі злагодженим загоном шукачів пригод.",al={"чи потрібна група","самоцвіт кор соло","чорноглибинні печері група"}}},fp="19,352,18.444.0,14.411.0,19.377.1,34.175.0,29.185.0,40.162.0,41.222.0,42.260.0,37.188.0"}
P.entries["quest:1447"] = {n="Зниклий дипломат",s="Це напружене протистояння — ключовий крок до розгадки таємниці зниклого дипломата. Ідучи слідом крізь підчерев'я Стормвінда, слідчий заганяє Дешела Стоунфіста в кут у Старому Місті, щоб силою вибити відповіді з упертого головоріза.",h="Це напружене протистояння — ключовий крок до розгадки таємниці зниклого дипломата.",kw={"зниклий дипломат","дешел стоунфіст","старе місто","бійка","головорізи","стормвінд"},ang={["class:Rogue"]="Старе Місто — ваше природне середовище, а мати справу з бугаями на кшталт Дешела Стоунфіста — звична робота, коли витрушуєте з інформаторів вуличні розвіддані.",["faction:Alliance"]="Кожен слід у справі зниклого дипломата важливий, щоб викрити внутрішню зраду, яка загрожує стабільності верхівки Альянсу.",["race:Human"]="Відкриття, що місцеві головорізи в самій столиці Стормвінда активно заважають пошукам зниклого дипломата, б'є в саме серце безпеки королівства."},sec={{t="Дружня бесіда в Старому Місті",b="Пошуки зниклого дипломата ведуть глибоко в тіні Старого Міста, де кишенькові злодії й темні ділки водяться подалі від пильного ока Собору. Відомо, що Дешел Стоунфіст має зв'язки з сумнівними угрупованнями міста й знає чимало цінного про викрадення, але зовсім не горить бажанням ділитися цим з агентами, які ставлять делікатні запитання."},{t="Бійка в провулку",b="Щойно до нього підходять, Дешел одразу облишає будь-яке вдавання, що готовий співпрацювати. Разом із вірними головорізами зі Старого Міста він намагається побити допитливих мандрівників і назавжди поховати розслідування. Здолати Дешела й порішити його підмогу — єдина мова, яку він поважає: він швидко міняє пісню й відчиняє двері до наступного сліду змови."}},faq={{q="Хто такий Дешел Стоунфіст?",a="Дешел Стоунфіст — темна особа, що вештається в Старому Місті й має зв'язки зі злочинним світом Стормвінда. Він — місцевий посередник, що знає про незаконні справи в місті набагато більше, ніж показує.",al={"дешел стоунфіст","хто такий стоунфіст","дешел"}},{q="Чому з Дешелом доводиться битися, а не просто говорити?",a="Дешел зовсім не хоче співпрацювати зі слідчими. Щойно ви питаєте про зниклого дипломата, він вирішує, що вас легко залякати, і кличе своїх головорізів, щоб змусити вас замовкнути. Лише добряча прочуханка переконує його заговорити.",al={"чому битися з дешелом","чи можна поговорити","чому бити дешела"}},{q="Чи треба вбивати Дешела Стоунфіста?",a="Ні. Мета — не стратити його, а відлупцювати до покори. Щойно його здоров'я досить знизиться, він здається, відкликає своїх поплічників і погоджується відповісти на ваші запитання.",al={"чи вбивати дешела","стоунфіст живий","чи дешел мертвий"}},{q="Де відбувається ця бійка?",a="Сутичка відбувається просто неба в Старому Місті, біля провулків за таверною «Свиня і свисток» і місцевими тренувальними залами, де зазвичай вештається Стоунфіст.",al={"місце бійки","де дешел","бійка в старому місті"}},{q="Що буде, коли здолаєш Дешела?",a="Переможений і впокорений, Дешел просить вибачення й охоче викладає все, що знає про змову, вказуючи наступну ланку ланцюжка вже за межами столиці.",al={"що після дешела","наступне завдання стоунфіста","ланцюжок дипломата далі"}},{q="Про що насправді ланцюжок «Зниклий дипломат»?",a="Офіційно це пошуки зниклого посла, але ланцюжок завдань розкриває павутиння обману довкола викрадення дипломата й темних постатей, що його влаштували.",al={"про що ланцюжок зниклого дипломата","лор зниклого дипломата","зниклий король"}}},fp="20,242,27.380.0,18.363.1,24.210.0,61.230.0,35.179.0,33.173.0,34.184.1,50.181.2"}
P.entries["quest:145"] = {n="Гонець до Даркширу",s="Гонець до Даркширу — термінова дипломатична місія, з якою Магістрат Соломон із Лейкширу посилає гінця до Лорда Елло Ебонлока в Сутінколісся. Відчайдушно потребуючи військового підкріплення проти орків Блекрок і гнолів, що загрожують Редріджу, Соломон просить допомоги в сусіднього поселення. Гонцеві доведеться пройти темними шляхами Сутінколісся, щоб доставити офіційне прохання Соломона мерові Даркширу.",h="Гонець до Даркширу — термінова дипломатична місія, з якою Магістрат Соломон із Лейкширу посилає гінця до...",kw={"гонець до даркширу","магістрат соломон","елло ебонлок","нічна варта","даркшир","сутінколісся"},ang={["faction:Alliance"]="Гарячкові листи Соломона показують, наскільки роз'єднаними й занедбаними стали віддалені містечка Альянсу, поки королівський двір Стормвінда паралізований.",["race:Human"]="Ця місія показує спільну біду південних людських поселень: після того як королівство відкликало регулярні патрулі, кожне з них мусить покладатися на нерегулярне місцеве ополчення."},sec={{t="Відчайдушний заклик про допомогу",b="Королівський двір у Стормвінді ігнорує його прохання, сусідній Вестфол загруз у власному повстанні, тож Магістрат Соломон дивиться на південь, на Сутінколісся. Редрідж дедалі щільніше облягають клани орків Блекрок і агресивні зграї гнолів, і місцева варта Лейкширу виснажена до краю. У відчаї Соломон пише листа просто мерові Елло Ебонлоку, сподіваючись найняти чи позичити славетну Нічну Варту Даркширу, щоб зміцнити оборону містечка."},{t="Дорога в морок",b="Щоб доставити листа Соломона, треба перетнути кордони королівства й увійти в Сутінколісся — лісистий край, оповитий надприродним мороком. Соломон застерігає гінців триматися лише доріг, бо глушина між Лейкширом і Даркширом стала сумно відомою своїми небезпеками. У Ратуші Даркширу послання потрапляє до рук Лорда Ебонлока, хоча чи має Сутінколісся хоч якісь сили, щоб поділитися, — зовсім інше питання."}},faq={{q="Чому Лейкшир просить допомоги в Даркширу?",a="Стормвінд не дає офіційної військової допомоги, і містечка на кшталт Лейкширу мусять самі боронитися від переважних загроз, як-от орків Блекрок. Магістрат Соломон звертається до кожного сусіднього союзника Альянсу, сподіваючись, що Нічна Варта, міське ополчення Даркширу, має навчених бійців, яких може позичити.",al={"чому лейкшир просить даркшир","чому даркшир","прохання соломона до даркшира"}},{q="Хто такий Лорд Елло Ебонлок?",a="Лорд Елло Ебонлок — мер Даркширу й помітний цивільний очільник Сутінколісся. Він керує містечком із ратуші й веде міські справи разом із Командиром Алтеєю Ебонлок, яка командує Нічною Вартою.",al={"лорд елло ебонлок","хто такий ебонлок","мер даркшира"}},{q="Що таке Нічна Варта?",a="Нічна Варта — незалежне цивільне ополчення Даркширу, створене, щоб патрулювати околиці й відбиватися від нежиті, звірів і тіней, що прокрадаються Сутінколіссям, коли гарнізону Стормвінда немає.",al={"що таке нічна варта","нічна варта сутінколісся"}},{q="Чому Соломон застерігає мене не сходити з доріг?",a="Нетрі Сутінколісся аж кишать жахіттями нежиті, павуками й здичавілими звірами. Зійшовши з битого шляху в хащі, мандрівник наражається на агресивних хижаків і засідки.",al={"чому соломон застерігає не сходити з доріг","попередження про дороги"}},{q="З чого почалася ця низка завдань?",a="Це завдання — частина низки відчайдушних послань Магістрата Соломона. Воно йде після його попереднього прохання до Ґраяна Стаутмантла у Вестфолі й продовжує його вперті спроби знайти допомогу для Лейкширу.",al={"початок ланцюжка","попереднє завдання"}},{q="Чи справді Даркшир має вартових, яких може виділити?",a="Сутінколісся переживає власну смертельну кризу: його облягають повсталі мерці, здичавілі воргени й потвори, що чатують у хащах. Нічній Варті ледве вистачає бійців, щоб боронити сам Даркшир, тож прохання Соломона — гірка й майже марна надія.",al={"чи даркшир має вартових","чи ебонлок пришле вартових"}}},fp="22,397,24.474.0,23.445.0,43.299.0,27.230.0,24.213.0,46.185.0,31.203.0,45.237.0"}
P.entries["quest:1453"] = {n="Справи Відновлювачів у Десоласі",s="«Справи Відновлювачів у Десоласі» — завдання-перехід Альянсу, що веде шукачів пригод з Айронфорджа до суворих безплідних земель Пустограю. Його дає Роеттен Стоунгаммер: він посилає новобранців через море до Крелдіґа Унґора на Мисі Ніджела, щоб ті за плату допомагали Відновлювачам повертати втрачені скарби й реліквії.",h="«Справи Відновлювачів у Десоласі» — завдання-перехід Альянсу, що веде шукачів пригод з Айронфорджа до суворих...",kw={"справи відновлювачів у десоласі","роеттен стоунгаммер","крелдіґ унґор","мис ніджела","пустограй","компанія «відновлювачі»"},ang={["faction:Alliance"]="Мис Ніджела — головний прихисток Альянсу в західних пустках центрального Калімдору, плацдарм, оточений ворожими кланами кентаврів.",["race:Dwarf"]="Чи то через Лігу Дослідників, чи через незалежні компанії на кшталт Відновлювачів — дворфійська заповзятливість сягає навіть найпохмуріших куточків Калімдору."},sec={{t="Поклик пустки",b="Айронфордж вирує ремісниками й дворфійськими справами, а далекий Калімдор досі лишається диким прикордонням. Роеттен Стоунгаммер — міський зв'язковий Відновлювачів, заповзятливої компанії, що прагне заробити на забутих руїнах і безплідних землях. Він вербує завзятих шукачів пригод, які проходять через велике гірське місто, і попереджає, що Пустограй — жахливий край, де ворогують клани кентаврів, але для тих, хто наважиться на подорож, там повно вигідних нагод."},{t="Мис Ніджела й Відновлювачі",b="Шлях веде далеко на захід, через Гори Кам'яного Кігтя, до північного Пустограю, де Альянс тримає Мис Ніджела — укріплений прихисток високо серед скель. Там Крелдіґ Унґор приймає нових помічників. Відновлювачі працюють за простим принципом: у світі, роздертому війнами, люди постійно гублять родинні реліквії, магічні артефакти й сімейні скарби. Маючи досить витримки й за належну ціну, Крелдіґ і його спільники дбають, щоб ці втрачені цінності повернули з дикої глушини."}},faq={{q="Хто дає це завдання?",a="Це завдання дає Роеттен Стоунгаммер в Айронфорджі. Він посилає шукачів пригод, що шукають чесної й прибуткової роботи, до Калімдору — зв'язатися з його соратником.",al={"хто дає це завдання","початок справ відновлювачів","місце роеттена стоунгаммера"}},{q="Де Мис Ніджела?",a="Мис Ніджела розташований серед північно-східних скель Пустограю. Ідучи з Гір Кам'яного Кігтя на південь у Пустограй, тримайтеся урвищ на схід, доки не знайдете освітлену смолоскипами гірську стежку, що в'ється вгору до застави Альянсу.",al={"де мис ніджела","знайти мис ніджела","місце мису ніджела"}},{q="Хто такі Відновлювачі?",a="Відновлювачі — заповзятливе підприємство на чолі з дворфійськими агентами на кшталт Крелдіґа Унґора. Вони спеціалізуються на тому, щоб на замовлення клієнтів повертати загублені родинні реліквії, рідкісні старожитності й магічні артефакти з небезпечних закутків світу.",al={"хто такі відновлювачі","фракція відновлювачів","лор відновлювачів"}},{q="Які загрози чекають у Пустограї?",a="Пустограй — посушлива, похмура пустка, де панують ворожі між собою племена кентаврів, рештки нежиті й ворожа звірина. Це суворий полігон для досвідчених мандрівників, що вирушають далі Гір Кам'яного Кігтя.",al={"загрози пустограю","що в пустограї"}},{q="Хто такий Крелдіґ Унґор?",a="Крелдіґ Унґор — дворф на Мисі Ніджела в Пустограї. Він організовує розкопки й пошуки реліквій у краї й залучає вправних шукачів пригод, щоб ті не боялися руїн і таборів кентаврів.",al={"хто такий крелдіґ","лор крелдіґа унґора"}},{q="Чи обов'язкове це завдання, щоб виконувати завдання в Пустограї?",a="Ні, це необов'язкове завдання-вказівка. До Мису Ніджела можна дістатися й самотужки, але розмова з Роеттеном Стоунгаммером дає зручну передісторію й напрямок, перш ніж вирушати.",al={"чи обов'язкове завдання","чи потрібні справи відновлювачів"}}},fp="32,321,23.489.0,32.515.0,21.152.0,23.241.0,23.239.0,31.198.0,21.197.0,44.196.0"}
P.entries["quest:146"] = {n="Гонець до Даркширу",s="«Гонець до Даркширу» завершує відчайдушне дипломатичне листування між Лейкширом і Даркширом. Лорд Елло Ебонлок твердо відхиляє прохання Магістрата Соломона про військове підкріплення, і відкривається гірка правда: Стормвінд покинув обидва міста напризволяще.",h="«Гонець до Даркширу» завершує відчайдушне дипломатичне листування між Лейкширом і Даркширом.",kw={"гонець до даркширу","елло ебонлок","магістрат соломон","лейкшир","даркшир","нічна варта"},ang={["faction:Alliance"]="Це послання оголює глибокі тріщини, що розколюють південне королівство: віддалені поселення Альянсу опиняються відкинутими й беззахисними.",["race:Human"]="Для людей-мандрівників це листування — тверезе свідчення того, наскільки відрізаними стали міста королівства, поки королівський двір дивиться в інший бік."},sec={{t="Відчайдушне прохання відхилено",b="Під натиском орків Блекрок і гнолів Магістрат Соломон із Редріджу сподівався, що його давній колега в Сутінколіссі зможе виділити війська. Але Лорд Елло Ебонлок ледь не обурений. Даркшир ледве стримує ходячих мерців, ненажерливих звірів і прокляту магію, що тиснуть на нього з усіх кутків лісу. Ебонлок прямо заявляє: Нічна Варта існує лише тому, що Стормвінд першим покинув Сутінколісся. Позбавити Даркшир захисників означало б приректи поселення на загибель ще до того, як загін перетне узлісся."},{t="Покинуті напризволяще",b="Читаючи відповідь Ебонлока, Соломон усвідомлює сувору правду про стан королівства. Армія Стормвінда пішла з Вестфолу, лишила Даркшир самотужки боронитися, а тепер ще й знехтувала закликами Лейкшира про допомогу. Соломонові доводиться визнати те, про що вже шепочуться місцеві очільники по всьому королівству: це не просто бюрократична недбалість чи невміння, а, схоже, зрада, що зачаїлася в самому серці Стормвінда."}},faq={{q="Чому Лорд Ебонлок не посилає Нічну Варту на допомогу Лейкширу?",a="Даркшир обложений з усіх боків нежиттю, звірами й мерзенним чаклунством. Нічна Варта — нерегулярне місцеве ополчення, створене саме тому, що Стормвінд вивів свої гарнізони. Якби Ебонлок послав своїх вартових до Редріджу, Даркшир упав би раніше, ніж загін вийшов би за узлісся.",al={"чому ебонлок не посилає нічну варту","чому відмова","даркшир відмовив"}},{q="Що усвідомлює Магістрат Соломон, прочитавши відповідь?",a="Соломон розуміє, що біда Лейкширу — частина кризи всього королівства. Армія відступила з Вестфолу, варти в Даркширі геть немає, і Соломон підозрює вже не просто недбалість, а відверту зраду в проводі Стормвінда.",al={"що усвідомлює соломон","реакція соломона"}},{q="Хто створив Нічну Варту?",a="Нічну Варту зібрали знесилені мешканці й провідники Сутінколісся на чолі з Лордом Елло Ебонлоком, коли офіційні сили Стормвінда покинули край на поталу темряві й тліну.",al={"хто створив нічну варту","походження нічної варти"}},{q="Куди Соломон звертається далі по допомогу?",a="Даркшир відмовив, Вестфол заполонило Братство Дефіас, і Лейкшир лишився геть сам. Соломонові доводиться пильніше придивитися до палацового двору в Стормвінді, щоб з'ясувати, чому корона відмовляється захищати свої віддалені землі.",al={"куди соломон звертається далі","що робить соломон"}},{q="Чи Стормвінд офіційно вивів війська із Сутінколісся й Вестфолу?",a="Так. Коли темна магія осквернила Сутінколісся, а у Вестфолі спалахнули заворушення, регулярні сили Стормвінда відступили, і прикордонні містечка мусили для виживання збирати місцеві ополчення на кшталт Нічної Варти й Народного ополчення.",al={"чи стормвінд вивів війська","чому стормвінд пішов"}},{q="Що пов'язує Соломона й Ебонлока?",a="Вони давні колеги — очільники прикордонних містечок королівства. Просячи вояків, Соломон розраховував на ці особисті стосунки, але небезпеки Сутінколісся настільки тяжкі, що виконати прохання було неможливо.",al={"соломон і ебонлок","чи вони друзі"}}},fp="22,292,26.542.0,24.418.1,64.301.0,63.257.0,27.189.0,44.245.0,59.213.0,51.234.0"}
P.entries["quest:1462"] = {n="Земляна Сапта",s="«Земляна Сапта» — обряд поповнення, який пропонує Віщун Рейвенфезер у Таборі Нарачі. Молодим шаманам, що проходять посвяту для єднання з духами каменю, потрібен цей напій, щоб відкрити внутрішній зір. Якщо новачок загубить чи проллє приготоване вариво, не завершивши обряду, віщунка готує нове, щоб випробування могло тривати.",h="«Земляна Сапта» — обряд поповнення, який пропонує Віщун Рейвенфезер у Таборі Нарачі.",kw={"земляна сапта","сапта","шаман","рейвенфезер","табір нарачі","малгор","таурени"},ang={["class:Shaman"]="Сапта — основне знаряддя вашого раннього вишколу, духовний каталізатор, що вперше відкриває вам очі на сили стихій, які ведуть світ.",["faction:Horde"]="Опору Орди на шаманські традиції плекають у таких місцях, як Малгор, де племінні віщуни терпляче ростять нове покоління духовних провідників.",["race:Tauren"]="Шанування Матері-Землі починається з уміння чути землю, і старійшини Табору Нарачі ретельно дбають, щоб жодного юнака не відвернули від священного шляху."},sec={{t="Напій видінь",b="Шлях шамана починається з налаштування смертних чуттів на сили поза фізичним зором. Щоб побачити духів стихій землі, посвячуваний має випити сильнодійне обрядове вариво, відоме як сапта. Насичена природними есенціями, пов'язаними зі стихією каменю й ґрунту, Земляна Сапта піднімає завісу між фізичним світом і духовним планом і дає новачкові єднатися просто з елементалями землі Малгору."},{t="Другий шанс на зір",b="Духовні мистецтва вимагають дисципліни, та досвідчені віщуни знають, що молоді посвячувані часто помиляються чи гублять священні реагенти, блукаючи нетрями. Табір Нарачі ніколи не відмовляє в другому шансі: Віщун Рейвенфезер пильно вартує тут, щоб кожен учень, який загубить вариво до єднання біля кам'яного монумента, міг відновити приготування. З тихим терпінням вона дає нову посудину, щоб новачок міг постати перед духами незламним."}},faq={{q="Що таке Земляна Сапта?",a="Земляна Сапта — священний трав'яний напій, який варять старійшини-шамани. Коли його п'є посвячуваний, він пробуджує внутрішні чуття й дає духовний зір, потрібний, щоб бачити земляних елементалів, невидимих звичайному оку, і спілкуватися з ними.",al={"що таке земляна сапта","лор земляної сапти","що робить варево"}},{q="Навіщо посвячуваному ще одна Земляна Сапта?",a="Учні, що проходять випробування в дикій природі, часом гублять, розливають чи передчасно випивають свій напій, не дійшовши до призначеного священного місця. Віщун Рейвенфезер дає ще одну порцію, щоб через просту помилку їхнє духовне навчання не спинилося назавжди.",al={"навіщо ще одна земляна сапта","загубив сапту","загублена земляна сапта"}},{q="Хто така Віщун Рейвенфезер?",a="Віщун Рейвенфезер — тауренська духовна наставниця в Таборі Нарачі в Малгорі. Вона проводить найперші випробування молодих тауренів-шаманів і веде їх крізь перше єднання з духами землі.",al={"рейвенфезер","хто така віщун рейвенфезер","віщун табору нараче"}},{q="Чому шамани мусять пити сапту, щоб бачити елементалів?",a="Шамани-початківці ще не відточили свого вродженого зв'язку зі стихіями настільки, щоб бачити їх за власним бажанням. Сапта — місток: вона змінює духовне сприйняття того, хто її п'є, доки він не навчиться чути стихії й спілкуватися з ними власною силою.",al={"чому шамани п'ють сапту","навіщо зілля щоб бачити духів"}},{q="Де відбувається випробування із Земляною Саптою?",a="Обрядове випробування проводять на пагорбах Плато Червоної Хмари в Малгорі, біля Табору Нарачі. Новачки несуть напій до священного кам'яного пам'ятника, де живуть місцеві духи землі.",al={"де випробування сапти","де використати сапту"}},{q="Чи всі шамани користуються саптами?",a="І тауренська, і орківська шаманські традиції вживають сапти під час перших посвят у стихії. Кожна стихія, з якою шаман уперше єднається, — земля, вогонь, вода, — має власну сапту, що допомагає налаштувати його чуття на відповідне стихійне царство.",al={"чи всі шамани п'ють сапти","чи орки використовують сапти"}}},fp="11,355,19.433.0,24.422.0,23.266.0,47.265.0,25.214.0,48.248.0,51.181.0,25.255.0"}
P.entries["quest:1463"] = {n="Земляна Сапта",s="Це доручення — перевірка відповідальності для посвячуваного шамана в Долині Випробувань. Якщо послушник загубить освячену Земляну Сапту до єднання з духами землі, Канаґа Ерткаллер дає заміну разом із суворим нагадуванням поводитися зі священними напоями обережно.",h="Це доручення — перевірка відповідальності для посвячуваного шамана в Долині Випробувань.",kw={"земляна сапта","сапта","шаман","ерткаллер","долина випробувань","дуротар"},ang={["class:Shaman"]="Для посвячуваного втрата сапти — ранній урок дисципліни: єднання зі стихіями потребує твердої зосередженості, а не недбалих рук.",["race:Orc"]="У посушливих скелях Дуротару молоді орки, що опановують давні шляхи шаманізму, мають довести свою відданість предкам і землі під ногами.",["race:Troll"]="Тролі Темного Списа, що йдуть шляхом стихій у Долині Випробувань, учаться поєднувати традиційне шанування лоа з прямою шаною до духів стихій."},sec={{t="Другий шанс зі стихіями",b="Шлях шамана вимагає цілковитої уважності й поваги до духів світу. Приготована особливими обрядами, Земляна Сапта — стихійне вариво, що має стоншити завісу між фізичним світом і духами каменю та ґрунту. Коли посвячуваний ненароком губить чи проливає цей напій, мандруючи Дуротаром, Канаґа Ерткаллер готовий щиро приготувати ще один — та не без застереження новачкові бути значно пильнішим зі священними дарами."},{t="Настанова Канаґи",b="Канаґа Ерткаллер наглядає за шаманами-початківцями, що виходять із Лігва в Долині Випробувань. Розуміючи, що молоді орки й тролі схильні до безладу перших випробувань, він наголошує: духи стихій не терплять недбалості. Прийняти другу сапту — маленький урок смирення, що нагадує молодому шаману: силу, дану землею, треба берегти й шанувати."}},faq={{q="Що таке Земляна Сапта?",a="Земляна Сапта — особливо приготований обрядовий напій для посвячуваних шаманів. Вона дає духовний зір, і той, хто її випив, може бачити духів землі, невидимих звичайному оку, і говорити з ними.",al={"що таке земляна сапта","використання сапти","призначення сапти"}},{q="Чому Канаґа Ерткаллер дає це завдання?",a="Канаґа Ерткаллер дає заміну, якщо посвячуваний загубив чи кудись подів свою Земляну Сапту, не завершивши обряду єднання під час випробувань «Поклику Землі». Він по-доброму дає ще одну, щоб учень міг довести свою духовну справу до кінця.",al={"чому канаґа дає завдання","чому канаґа дає сапту"}},{q="Де відбувається цей обряд?",a="Усе відбувається в Долині Випробувань — випаленому сонцем каньйоні на південному заході Дуротару, де молоді орки й тролі починають свій шлях дисципліни й честі.",al={"де канаґа","місце обряду"}},{q="Чи духи погано сприймають утрату сапти?",a="Духи терплячі, але Канаґа нагадує посвячуваним, що недбале ставлення до священних напоїв свідчить про брак зосередженості. Справжній шаман мусить шанувати кожен дар стихій з цілковитим благоговінням.",al={"чи духи ображаються","втрата сапти"}},{q="Хто може пройти це єднання?",a="Готувати й пити Земляну Сапту можуть лише шамани, що прагнуть налаштуватися на свій перший тотем стихії — Тотем Землі.",al={"хто може пройти єднання","хто отримує сапту"}},{q="Що стається, коли посвячуваний вип'є сапту?",a="Напій відкриває посвячуваному внутрішній зір, і він може знайти місцевий прояв духу землі, схований серед скель Долини Випробувань, і поговорити з ним.",al={"що буде після випиття","після земляної сапти"}}},fp="11,293,33.494.0,17.415.0,23.229.0,45.248.0,34.167.0,47.197.0,33.161.0,48.189.0"}
P.entries["quest:147"] = {n="Полювання на людину",s="«Полювання на людину» — завдання Альянсу від Маршала Дуґана з Ґолдшира: знищити посильного Дефіас, відомого як «Колекціонер». Діючи із захопленої Гарбузової Ділянки Брекуеллів, цей посередник спрямовує крадене золото з шахт Лісу Елвінн просто до скарбниці Братства.",h="«Полювання на людину» — завдання Альянсу від Маршала Дуґана з Ґолдшира: знищити посильного Дефіас, відомого...",kw={"полювання","колекціонер","дефіас","гарбузова ділянка","каменярі","маршал дуґан","перстень"},ang={["class:Rogue"]="Потаємна оборудка Колекціонера на гарбузовій ділянці викриває дедалі ширшу мережу розбійників і кишенькових злодіїв, що пускає коріння по всьому Лісі Елвінн.",["faction:Alliance"]="Захист місцевих ресурсів Стормвінда — справа першорядна: знищення Колекціонера перекриває потік королівського золота, яким мали оплатити повстання просто біля столиці.",["race:Human"]="Знайдений перстень каменяра зачіпає болючу струну в недавній історії Стормвінда — нагадує про гіркі суперечки з робітниками, що розкололи королівство після відбудови столиці."},sec={{t="Правосуддя на гарбузовій ділянці",b="Після того як у гнолів Елвінну знайшли графік збору золота, Маршал Дуґан посилає шукачів пригод на Гарбузову Ділянку Брекуеллів. Колись тиху садибу захопили бандити Дефіас і гноли. Серед зарослого гарбузиння переховується Колекціонер — посередник, який краде королівську руду й організовує відправлення для повстання, що набирає сили."},{t="Печатка ремісника",b="Убивши Колекціонера, шукачі пригод забирають його перстень і приносять Маршалу Дуґану. На подив маршала, на персні — не звичайний злодійський герб, а знак старої Гільдії каменярів Стормвінда. Знахідка натякає на неприємну правду: розбійники, що душать Ліс Елвінн, — не просто пройдисвіти, а колишні майстри, які стали запеклими злочинцями після відбудови Стормвінда."}},faq={{q="Де знайти Колекціонера?",a="Колекціонер ховається на Гарбузовій Ділянці Брекуеллів у південно-східній частині Лісу Елвінн, трохи на схід від Виноградників Маклюрів і на північ від річки.",al={"місце колекціонера","де колекціонер","точка колекціонера"}},{q="Чому Колекціонер краде золото з копалень Елвінна?",a="Він збирає контрабандну руду й вимагацькі побори з копалень Фарґодіп і Джасперлоуд, заполонених кобольдами, щоб фінансувати таємні операції Братства Дефіас по всьому королівству.",al={"чому колекціонер краде золото","дефіас шахти","що робить колекціонер"}},{q="Що означає перстень Колекціонера?",a="Перстень належав Гільдії Каменярів — ремісникам, що відбудували Стормвінд після Першої й Другої воєн. Те, що він опинився в руках агента Дефіас, прямо пов'язує розбійників з ображеними ремісниками, яких Дім Вельмож ошукав із платою.",al={"перстень колекціонера","перстень каменярів","що означає перстень"}},{q="Чи Маршал Дуґан з'ясовує, хто стоїть за Братством?",a="Не одразу. Маршал Дуґан упізнає на персні знак ремісничої гільдії, але не розуміє, звідки в простого злодія печатка гільдії майстрів, тож ширша змова в Ґолдширі лишається відкритим питанням.",al={"чи дуґан знає","реакція дуґана","дуґан каменярі"}},{q="Хто посилає вас на це полювання?",a="Маршал Дуґан, командир гарнізону в Корчмі «Лев'яча Гордість» у Ґолдширі, дає це завдання, після того як ви здобудете графік збору Дефіас.",al={"хто посилає на полювання","давець полювання","завдання маршала дуґана"}},{q="Що сталося з родиною Брекуеллів?",a="Гарбузова Ділянка Брекуеллів занепала: господарі її покинули, а тепер там засіли розбійники й бандити Дефіас, а ще гноли Річколапів, що підбираються зі східних лісів і никають південно-східною частиною краю.",al={"родина брекуеллів","хто володіє полем гарбузів","ферма брекуеллів"}}},fp="7,280,28.376.0,17.413.1,31.158.0,55.176.0,49.268.1,61.217.1,30.149.0,38.183.0"}
P.entries["quest:1470"] = {n="Крізь завісу",s="«Крізь завісу» — вступне випробування для чорнокнижників від Вені Мартанд у Похоронному Подзвоні. Воно перевіряє рішучість щойно піднятого чорнокнижника, посилаючи його збирати черепи сусідніх безтямних скелетів. Виконавши завдання, новачок здобуває знання, потрібне, щоб прикликати й прив'язати до себе біса-прислужника.",h="«Крізь завісу» — вступне випробування для чорнокнижників від Вені Мартанд у Похоронному Подзвоні.",kw={"крізь завісу","чорнокнижник","веня мартанд","біс","скелети","похоронний подзвін"},ang={["class:Warlock"]="Цей обряд переходу — ваш перший справжній крок у демонологію, що показує основний урок: хаотичну магію треба гнути залізною волею.",["race:Undead"]="Чорнокнижники Відступників спираються на свою моторошну відстороненість від смертності, щоб безстрашно вивчати хаотичну й темну магію в тінях Похоронного Подзвону."},sec={{t="Перший крок новачка",b="Щойно пробуджені чорнокнижники Відступників починають свій шлях у Похоронному Подзвоні під настановами Вені Мартанд. Вона навчає, що справжня сила — не в грубій силі, а в знанні й точному володінні хаотичними силами. Щоб довести, що мають зосередженість і хист пройти крізь завісу між світами й підкорити істот Нижнього Світу, новачків посилають збирати черепи неспокійних скелетів Гримучих Кісток, що блукають біля покинутої кузні Похоронного Подзвону."},{t="Підкорення Нижнього Світу",b="Коли скелетні рештки зібрано, Веня вважає посвяченого готовим ступити далі простих темних заклять. Здобуті матеріали слугують обрядом переходу й доводять, що новачок здатен здолати безтямну нежить і витримати похмуру дійсність свого ремесла. Натомість Веня передає ритуали, потрібні, щоб зігнути біса під волю прикликача, застерігаючи: попри дрібний зріст демона, його хитрість і вогонь зроблять його небезпечним союзником."}},faq={{q="Хто дає завдання «Крізь завісу»?",a="Завдання дає Веня Мартанд — наставниця чорнокнижників у склепі Похоронного Подзвону на Галявинах Тірісфалю.",al={"хто дає крізь завісу","давець крізь завісу","завдання веньї мартанд"}},{q="Що треба зібрати, щоб виконати це завдання?",a="Треба зібрати три черепи брязкунів — їх здобувають, знищуючи скелетів-брязкунів, що блукають біля зруйнованої кузні в Похоронному Подзвоні.",al={"що збирати","ціль крізь завісу","що збирати для завіси"}},{q="Навіщо Вені Мартанд черепи скелетів?",a="Полювання на безмозких скелетів перевіряє самовладання, рішучість і основні магічні вміння чорнокнижника-початківця, перш ніж Веня довірить йому небезпечніші демонічні обряди.",al={"навіщо черепи скелетів","призначення черепів"}},{q="Яку силу чи прислужника вчишся закликати?",a="Завершений урок готує чорнокнижника до того, щоб закликати й прив'язати біса — першого демонічного супутника, яким учиться командувати чаклун.",al={"яку силу закликати","закляття нагороди","який демон"}},{q="Де скелети-брязкуни?",a="Вони блукають околицями Похоронного Подзвону, особливо довкола розваленої покинутої кузні на північний захід від центральної галявини поселення.",al={"де скелети-брязкуни","де скелети похоронного подзвону","покинута кузня"}},{q="Хто може взятися за це завдання?",a="Це завдання доступне лише чорнокнижникам-Відступникам, які пройшли потрібний рівень початкового навчання в Похоронному Подзвоні.",al={"хто може взяти","чи інші класи","чи лише чорнокнижник"}}},fp="17,294,21.468.0,22.460.0,38.117.0,45.148.0,45.165.0,44.131.0,43.144.0,40.126.0"}
P.entries["quest:1471"] = {n="Зв'язування",s="«Зв'язування» — завершальний обряд для чорнокнижників-Відступників, які прагнуть керувати блукачем Порожнечі. У Магічному Кварталі Андерсіті Карендін Галґар вимагає від учнів викликати, здолати й навіки підкорити створіння Порожнечі.",h="«Зв'язування» — завершальний обряд для чорнокнижників-Відступників, які прагнуть керувати блукачем Порожнечі.",kw={"зв'язування","блукач порожнечі","карендін галґар","чорнокнижник","магічний квартал","біс","андерсіті"},ang={["class:Warlock"]="Цей обряд знаменує ваш перехід від дрібних хитрощів із бісами до справжньої влади над істотами, здатними витримати на полі бою величезну кару.",["race:Undead"]="Для Відступників підкорити створіння тіні — природне продовження їхньої стійкості й того, що заборонена магія не викликає в них жодних моральних вагань."},sec={{t="Обряд підкорення",b="На відміну від дрібних бісів, яких легко змусити до угоди з темною магією, створіння Порожнечі ненавидять реальність і мають грізну фізичну силу. Щоб здобути право викликати блукача Порожнечі, молодий чорнокнижник в Андерсіті мусить довести, що цілковито ним володіє. У затіненому осередку Магічного Кварталу наставник-Відступник Карендін Галґар дає містичні руни, потрібні, щоб вирвати блукача Порожнечі з Нижнього Світу у світ матеріальний."},{t="Усередині кола",b="Обряд відбувається в сяйливому колі виклику, викарбуваному під помостом наставника. Щойно руни пробуджено, з'являється розлючений неприборканий блукач Порожнечі. Приборкати його — не справа дипломатії: заклинач мусить зламати істоту самою лише магічною силою й непохитною волею. Лише коли створіння остаточно розчавлене, Карендін відкриває справжню формулу виклику, що навіки прив'язує сутність істоти до чорнокнижника."}},faq={{q="Яка мета цього обряду?",a="Обряд перевіряє здатність молодого чорнокнижника здолати істоту Порожнечі. Перемігши в бою неприв'язаного блукача Порожнечі, закликач доводить, що його воля досить сильна, щоб ним керувати, і тоді Карендін Галґар може навчити його постійного заклинання закликання.",al={"мета обряду","навіщо зв'язування","нагорода зв'язування"}},{q="Де відбувається закликання?",a="Воно відбувається просто в пурпуровому колі закликання, вирізьбленому в підлозі під помостом Карендіна Галґара в Магічному Кварталі Андерсіті.",al={"де відбувається закликання","де призвати блукача порожнечі","коло закликання андерсіті"}},{q="Хто такий Карендін Галґар?",a="Карендін Галґар — головний наставник чорнокнижників у Магічному Кварталі Андерсіті, що керує навчанням і темними посвятами щойно повсталих чаклунів-Відступників.",al={"хто такий карендін","карендін галґар"}},{q="Чи мусять чорнокнижники перемагати кожного демона, якого хочуть закликати?",a="Чорнокнижники мусять утвердити владу над могутніми істотами з інших вимірів, перш ніж ними командувати. Дрібних істот на кшталт бісів зв'язують простими угодами й обрядами, а блукачі Порожнечі коряться лише після фізичної й магічної переваги над ними.",al={"чи завжди битися з демоном","чому битися з блукачем порожнечі"}},{q="Що буде, якщо чорнокнижник не зможе приборкати блукача Порожнечі?",a="Неприв'язаний блукач Порожнечі безжально лупцюватиме й знищить кожного поблизу. Як попереджає Галґар, не виправдати його сподівань — ніщо порівняно з небезпекою бути розірваним неприборканою істотою в колі.",al={"що як не вдасться","провал зв'язування"}},{q="Хто такий блукач Порожнечі?",a="Блукачі Порожнечі — тіньові істоти з інших вимірів, що походять із Порожнечі. Вони мають величезну фізичну стійкість і вроджене прагнення гасити живе світло й енергію, тож ідеально правлять за захисний щит для чаклунів темної магії.",al={"хто такий блукач порожнечі","лор блукача порожнечі"}}},fp="11,234,21.440.0,17.447.0,35.262.0,36.154.0,23.182.0,59.255.0,57.218.0,21.246.0"}
P.entries["quest:1472"] = {n="Пожирач Душ",s="«Пожирач Душ» — перший крок на шляху чорнокнижника-Відступника до виклику й підкорення сукуба. За вказівкою Карендіна Галґара з Храму Проклятих в Андерсіті учень має порадитися з його помічником, Ґодріком Фарсаном, щоб дізнатися, як виманити таку істоту з Викривленого Нижнього Світу. Обряд потребує неодмінної приманки — сердець чистих і люблячих смертних.",h="«Пожирач Душ» — перший крок на шляху чорнокнижника-Відступника до виклику й підкорення сукуба.",kw={"пожирач душ","сукуб","карендін галґар","ґодрік фарсан","храм проклятих","чорнокнижник","андерсіті"},ang={["class:Warlock"]="Підкорити сукуба — важливий рубіж у навчанні чорнокнижника: так ви опановуєте темне мистецтво грати на вроджених вадах і апетитах демона, щоб поневолити його.",["race:Undead"]="Наставники чорнокнижників-Відступників у Храмі Проклятих не знають моральних обмежень: живу чистоту й відданість вони спокійнісінько вважають витратними реагентами для обрядів Нижнього Світу."},sec={{t="Приманка для Нижнього Світу",b="Карендін Галґар навчає, що сукуба не можна просто перетягти через поріг за наказом — його треба спокусити. Невситима жага руйнувати чесноту й пожирати сутність смертних робить цього демона вибагливим до приманки. Задум чорнокнижника — зіграти саме на цьому бажанні, підсунувши як наживку серця справді доброчесних, люблячих чоловіків. Галґар відсилає учнів до Ґодріка Фарсана, який знає, де можна здобути таку рідкісну здобич."},{t="Сліпий помічник",b="Ґодрік Фарсан, що перебуває глибше в Храмі Проклятих, допомагає Карендінові з практичною підготовкою до зв'язування демонів. Хоч Фарсан утратив тілесний зір, він запевняє, що натомість здобув глибокий внутрішній зір — і з моторошною ясністю бачить приховані духовні течії й далекі душі. Він підказує, де шукати чисті серця, потрібні, щоб виманити демона."}},faq={{q="Яка мета цього завдання?",a="Це завдання з'єднує перший виклик Карендіна Галґара з практичним етапом полювання, потрібним, щоб прив'язати сукуба. Воно посилає чорнокнижника до Ґодріка Фарсана, який розповідає про моторошні складники для обряду.",al={"мета завдання","навіщо пожирач душ","завдання сукуби андерсіті"}},{q="Навіщо для закликання сукуба чисті серця?",a="Сукуб живиться тим, що розбещує доброчесність, спокушає смертні серця й пожирає праведні душі. Карендін Галґар пояснює, що демонові нелегко проникнути в цей світ без непереборної принади, тож незаплямована відданість добрих людей — ідеальна приманка, щоб виманити його сюди.",al={"навіщо чисті серця","приманка сукуби"}},{q="Хто такий Ґодрік Фарсан?",a="Ґодрік Фарсан — чорнокнижник-нежить, послушник, що допомагає Карендінові Галґару в Храмі Проклятих. Хоч тілом він сліпий, містичні чуття дають йому змогу бачити духовні істини й знаходити придатну здобич по всіх Східних Королівствах.",al={"хто такий ґодрік фарсан","фарсан"}},{q="Де здається це завдання?",a="Завдання здають просто в Храмі Проклятих в Андерсіті, за кілька кроків від Карендіна Галґара, де чекає Ґодрік Фарсан.",al={"де здати","де ґодрік фарсан"}},{q="Що йде після «Пожирача Душ»?",a="Фарсан одразу дає завдання «Серця чистих», доручаючи чорнокнижникові вирушити в Багнокрай і до Стіни Ґреймейна в Срібноліссі, щоб забрати серця двох доброчесних смертних.",al={"що після пожирача душ","наступне завдання"}},{q="Чи може будь-яка раса пройти цей обряд?",a="Хоча обряд проходить в Андерсіті й ним керують чаклуни-Відступники, кроки, які дають Галґар і Фарсан, може виконати будь-який чорнокнижник Орди, що хоче прив'язати сукуба з допомогою наставників Андерсіті.",al={"яка раса може","хто може пройти пожирача душ"}}},fp="17,385,18.458.0,19.420.0,34.211.0,52.283.0,22.257.0,30.162.0,35.200.0,35.210.0"}
P.entries["quest:1473"] = {n="Створіння Порожнечі",s="«Створіння Порожнечі» — переломний обряд посвяти для чорнокнижників-Відступників: вони мають повернути втрачений магічний текст, який захопив Багряний Хрестовий Похід. Щоб навчитися викликати й підкоряти хаотичного блукача Порожнечі, учень мусить вирушити на захід Галявин Тірісфалю й відібрати Гримуар Еґаліна у ворожих фанатиків.",h="«Створіння Порожнечі» — переломний обряд посвяти для чорнокнижників-Відступників: вони мають повернути...",kw={"створіння порожнечі","блукач порожнечі","гримуар еґаліна","перрін","багряний хрестовий похід","карендін галґар","чорнокнижник"},ang={["class:Warlock"]="Це завдання знаменує ваш перехід від забав із бісами до керування важкими тіньовими істотами передової, здатними витримати величезну кару.",["faction:Horde"]="Темні мистецтва Андерсіті тримаються на суворій науковій методі: вона перетворює небезпечні сили інших світів на надійну опору Орди в прикордонних війнах.",["race:Undead"]="Удар по Багряному Хрестовому Походу заради повернення темних знань підкреслює запеклу боротьбу між Відступниками й живими фанатиками, що засіли серед руїн Лордерона."},sec={{t="Спадок учителя",b="У темних нішах Храму Проклятих в Андерсіті Карендін Галґар наглядає за зростанням молодих заклиначів-Відступників. Коли учень доводить, що здатен владарювати над силою, більшою за дрібних бісів, Галґар спрямовує його до підкорення істоти, викуваної з чистої тіні й хаосу, — блукача Порожнечі. Відступники не покладаються на саме лише чуття: свої виклики вони будують на ретельних дослідженнях Еґаліна, колишнього вчителя самого Галґара, який першим записав обряди, потрібні, щоб скорити цих жахливих мешканців Порожнечі."},{t="Викрадений гримуар",b="Опанувати блукача Порожнечі неможливо без Гримуара Еґаліна, де описано точні способи спрямовувати таку нестійку магію. Та цінний фоліант викрав агент Багряного Хрестового Походу — фанатик на ім'я Перрін, що засів у сторожовій вежі на заході. Перрін і його хрестоносці, певно, вважали гримуар лише блюзнірською контрабандою, яку слід конфіскувати й заховати, але Відступникам конче потрібно повернути книгу й заволодіти таємницями обряду, перш ніж пробувати прорвати завісу."}},faq={{q="Що таке Гримуар Еґаліна?",a="Гримуар Еґаліна — магічний посібник, який написав чорнокнижник Еґалін, наставник Карендіна Галґара. У ньому описано складні прийоми спрямування сили й закляття, потрібні, щоб пробити Порожнечу й закликати блукача Порожнечі під цілковитою владою заклинача.",al={"гримуар еґаліна","що це за книга","хто був еґалін"}},{q="Чому Багряний Хрестовий Похід викрав книгу?",a="Багряний Хрестовий Похід вважає будь-яку демонічну й тіньову магію зіпсованою за самою природою. Агентка на ім'я Перрін захопила гримуар під час сутички чи проникнення й сховала його в західній вартовій вежі на Галявинах Тірісфалю, схоже, не знаючи, яка сила закликання в ньому.",al={"чому багряні викрали книгу","гримуар перріна","західна вежа багряних"}},{q="Хто такий Карендін Галґар?",a="Карендін Галґар — майстер-наставник чорнокнижників у Храмі Проклятих в Андерсіті. Він веде новачків-Відступників, навчаючи їх поваги до мінливих космічних сил і обережності, яку сам набув через власні помилки під час закликань.",al={"карендін галґар","тренер чорнокнижників андерсіті","тренер храму проклятих"}},{q="Що буде, якщо чорнокнижник утратить владу над блукачем Порожнечі?",a="Блукачі Порожнечі — істоти чистого хаосу й тіні. Як попереджає Карендін Галґар, якщо посвячуваний спробує закликати такого без бездоганної дисципліни й волі, що зв'язує, істота люто розірве свого закликача.",al={"чи блукач порожнечі вб'є","небезпека блукача порожнечі","провал закликання"}},{q="Що далі, коли гримуар повернуто?",a="Отримавши книгу, Галґар вивчає текст, щоб передати вам обрядові руни. Це одразу веде до завдання «Зв'язування», де посвячуваний має скористатися колом закликання, щоб закликати блукача Порожнечі й перемогти його в двобої, утвердивши свою владу.",al={"що після гримуара","наступне завдання","ритуал зв'язування"}},{q="Де розташована застава Багряного Хрестового Походу?",a="Гримуар схований у вартовій вежі Багряного Хрестового Походу на заході Галявин Тірісфалю, яку стережуть хрестоносці під командуванням Перрін.",al={"де застава багряних","де перрін","місце багряної вежі"}}},fp="20,302,18.549.0,19.515.0,26.244.0,43.285.0,23.242.0,56.210.0,41.253.1,45.154.0"}
P.entries["quest:1474"] = {n="Зв'язування",s="«Зв'язування» — останнє посвячення на шляху чорнокнижника з Андерсіті до виклику й підкорення сукуба. За вказівкою Карендіна Галґара заклинач за допомогою чистих сердець витягає демона з Викривленого Нижнього Світу в обрядове коло й скоряє його волю в бою.",h="«Зв'язування» — останнє посвячення на шляху чорнокнижника з Андерсіті до виклику й підкорення сукуба.",kw={"зв'язування","сукуб","карендін галґар","чисті серця","чорнокнижник","магічний квартал","викривлений нижній світ"},ang={["class:Warlock"]="Цей обряд — важливий крок на вашому темному шляху: він доводить, що ви здатні опанувати звабливі сили, які діють на розум, і підкорити своїй волі підступних породжень Нижнього Світу.",["race:Undead"]="Заклиначі-Відступники ставляться до підкорення демонів прагматично: вони беруться за будь-які темні знаряддя, аби забезпечити собі виживання й владу в Лордероні."},sec={{t="Випробування волі",b="У темних нішах Магічного Кварталу чорнокнижники-Відступники відточують владу над демонічними істотами. Виклик сукуба вважають важливим обрядом посвяти. На відміну від грубої сили блукача Порожнечі чи дрібної злоби біса, сукуб володіє звабливими чарами, що діють на розум і можуть полонити самого заклинача. Карендін Галґар вимагає від учнів довести, що їхній розум і магія непохитні, перш ніж довірити їм вічну владу над такою істотою."},{t="Підкорення в колі",b="Скориставшись Чистими Серцями, зібраними з невинних душ у Багнокраї та Срібноліссі, чорнокнижник відчиняє прохід у Викривлений Нижній Світ. Викликаний у коло зв'язування, демон одразу нападає, прагнучи здолати або зачарувати заклинача. Лише зруйнувавши його тілесну подобу й відкинувши його сутність назад у безодню, чорнокнижник утверджує повну владу й здобуває знання, потрібне, щоб кликати демона, коли забажає."}},faq={{q="Яка мета цього завдання?",a="Цей обряд дає чорнокнижникам-Відступникам змогу довести владу над вищими демонами. Закликавши й здолавши сукуба в Магічному Кварталі, чорнокнижник доводить, що його не зваблять чари, і здобуває закляття, щоб закликати сукуба й командувати ним у бою.",al={"мета завдання","навіщо зв'язування","нагорода зв'язування"}},{q="Хто такий Карендін Галґар?",a="Карендін Галґар — наставник чорнокнижників у Магічному Кварталі Андерсіті. Він керує навчанням і випробуваннями чаклунів-Відступників, перевіряючи їхню стійкість розуму й темне мистецтво, перш ніж довірити їм небезпечніші обряди закликання.",al={"хто дає зв'язування","карендін галґар"}},{q="Навіщо для закликання демона були потрібні чисті серця?",a="Демони роду сукубів живляться почуттями, чистотою й розбещенням. Чисті Серця, здобуті в попередніх завданнях, — непереборна потойбічна приманка, що спонукає демона з'явитися в царстві смертних просто через коло закликання.",al={"навіщо чисті серця","призначення сердець чистих"}},{q="Де відбувається закликання?",a="Закликання відбувається просто в Магічному Кварталі Андерсіті, в особливому обрядовому колі біля Карендіна Галґара й наставників-чорнокнижників.",al={"де закликання сукуби","місце кола закликання андерсіті"}},{q="Чому сукуба треба вбити?",a="Чорнокнижники не домовляються зі своїми прислужниками — вони їх підкоряють. Розбивши тіло демона в колі закликання, чорнокнижник схиляє його дух під свою владу, щоб той повертався покірним рабом, а не господарем.",al={"чому вбивати сукубу","навіщо бити викликану сукубу"}},{q="Чи небезпечні сукуби для чорнокнижників Андерсіті?",a="Так. Хоча Відступники мають неабияку стійкість розуму проти страху й сну, Карендін Галґар прямо попереджає, що чари сукуба поневолили чимало сильних розумів. Недбалість під час обряду закінчується смертю чи рабством.",al={"чи небезпечні сукуби","сукуба чарує нежить"}}},fp="11,266,14.469.0,25.459.1,34.250.0,23.245.0,48.246.0,36.155.0,39.237.0,44.240.0"}
P.entries["quest:1476"] = {n="Серця чистих",s="«Серця чистих» — зловісне випробування для чорнокнижника, яке в Андерсіті дає Ґодрік Фарсан від імені Карендіна Галґара. Щоб підготувати обрядову приманку для підкорення сукуба, молодий заклинач мусить вистежити й зарізати двох надзвичайно праведних чоловіків. Їхні чисті серця — непереборна спокуса для демона-спокусника, що чекає на виклик.",h="«Серця чистих» — зловісне випробування для чорнокнижника, яке в Андерсіті дає Ґодрік Фарсан від імені...",kw={"серця чистих","ґодрік фарсан","далін форджрайт","комар віллард","сукуб","чорнокнижник","стіна ґреймейна"},ang={["class:Warlock"]="Цей обряд посвяти вчить: чорнокнижник має вміти обертати на зброю не лише горе й страх, а й саму шляхетність інших, щоб підкоряти демонів своїй волі.",["faction:Alliance"]="Жертви — трагічні постаті серед людей Альянсу й уцілілих Лордерона: один опікується голодними біженцями, перед якими Ґілнеас зачинив ворота, другий марно шукає в болотах зниклу дружину.",["race:Undead"]="Це завдання показує моторошний світогляд Відступників: останніх уцілілих Лордерона з їхніми незгасними чеснотами вони спокійно вважають зручною худобою для обрядового заколювання."},sec={{t="Приманка для демона",b="Щоб підкорити сукуба, треба розуміти, що спокуса — палиця з двома кінцями. Сирени Нижнього Світу полюють на бажання й руйнацію, та ніщо так не виманює їх із Викривленого Нижнього Світу, як незаплямована чеснота, що аж проситься бути зіпсованою. У Храмі Проклятих майстер виклику Карендін Галґар доручає підготовчу роботу Ґодрікові Фарсану, а той шукає в людських землях душі, чия доброта лишається чистою й незламною."},{t="Здобич",b="Фарсан вирізняє два взірці чесноти. Перший — Далін Форджрайт, шляхетний чоловік, що допомагає зневіреним біженцям із Лордерона, яких не пустили за замкнену Стіну Ґреймейна на півдні Срібнолісся. Другий — Комар Віллард, вірний чоловік, що невтомно шукає бодай слід своєї зниклої дружини в небезпечних болотах Багнокраю. Для чорнокнижника-Відступника їхня відданість, співчуття й вірність роблять їх ідеальними жертвами."},{t="Погляд Відступника",b="Полювання вимагає від заклинача пройти небезпечними землями — і тими, що належать Альянсові, і дикими, — а завершується воно різаниною обох чоловіків. Коли закривавлені трофеї приносять до Храму Проклятих, Карендін Галґар з темною іронією зауважує, що серце доброї людини на вигляд нічим не відрізняється від решток будь-якого іншого трупа. Та в темному мистецтві демонології духовна чистота, що ще тримається їхньої плоті, досить сильна, щоб заманити сукуба в полон."}},faq={{q="Навіщо чорнокнижникам чисті серця, щоб закликати сукуба?",a="Сукуб живиться тим, що розбещує невинність і чесноти смертних. Щоб виманити його крізь Нижній Світ і впіймати в коло зв'язування, Карендінові Галґару потрібна приманка, перед якою той не встоїть. Серця справді чистих і самовідданих людей — саме така непереборна духовна спокуса.",al={"навіщо чисті серця","приманка сукуби","чому вбивати каліна й комара"}},{q="Хто такий Далін Форджрайт?",a="Далін Форджрайт — шляхетний вершник-людина, що патрулює вздовж замкненої брами Стіни Ґреймейна на півдні Срібнолісся. Він присвятив життя турботі про біженців із Лордерона й захистові тих, кого відкинуло й не впустило королівство Ґілнеас.",al={"далін форджрайт","хто такий далін","чолов'яга зі стіни ґреймейна"}},{q="Хто такий Комар Віллард?",a="Комар Віллард — відданий мандрівник-людина, що блукає північною дорогою Багнокраю трохи на південь від Мосту Тандол. На відміну від звичайних подорожніх, ним рухають лише горе й незламна любов: він не припиняє шукати свою зниклу дружину.",al={"комар віллард","хто такий комар","людське серце мокрих земель"}},{q="Куди веде цей ланцюжок завдань?",a="Коли ви доставляєте обидва серця Карендінові Галґару, він може підготувати коло закликання в Храмі Проклятих. Це одразу веде до завдання «Зв'язування», де чорнокнижник закликає й приборкує сукуба, щоб той став його постійним прислужником.",al={"що далі","після сердець чистих","нагорода сукуби"}},{q="Хто дає це завдання?",a="Доручення дає Ґодрік Фарсан — помічник у Храмі Проклятих у Магічному Кварталі Андерсіті. Він показує чорнокнижникові магічні ілюзії Даліна й Комара, щоб той точно знав, на кого полювати.",al={"хто дає серця чистих","ґодрік фарсан завдання"}},{q="Чому Карендін Галґар байдужий до вигляду сердець?",a="Коли завдання виконано, Карендін з похмурою байдужістю зауважує, що серце доброї людини на вигляд майже не відрізняється від будь-якого іншого шматка м'яса. Для нежиті, що практикує темні мистецтва, моральність тіла мало що важить, окрім її користі як магічного реагенту.",al={"діалог карендіна","вигляд сердець"}}},fp="18,365,16.415.0,10.449.0,22.470.1,54.268.0,25.283.0,21.250.0,33.240.1,21.215.0,62.282.0"}
P.entries["quest:1478"] = {n="Галґар кличе",s="«Галґар кличе» — офіційний виклик для молодих чорнокнижників-Відступників, що досягли важливого рубежу у своєму темному ремеслі. Майстер Карендін Галґар чекає їх у Магічному Кварталі Андерсіті, щоб розпочати суворе поглиблене навчання. Відгукнувшись на його поклик, учень готується до виклику й підкорення небезпечних істот із Нижнього Світу.",h="«Галґар кличе» — офіційний виклик для молодих чорнокнижників-Відступників, що досягли важливого рубежу у...",kw={"галґар кличе","карендін галґар","аґерон карґал","магічний квартал","храм проклятих","чорнокнижник","брілл"},ang={["class:Warlock"]="Цей обряд посвяти стає мостом між початковим навчанням і справжнім поневоленням істот з інших світів — і ви потрапляєте під пильне око найвидатнішого майстра темних мистецтв Андерсіті.",["race:Undead"]="Чорнокнижники-Відступники прагнуть влади над тінню й скверною з безжальною, нестримною амбіцією, а святилище Галґара — взірець їхнього прагматичного нехтування обережністю живих."},sec={{t="Увага майстра",b="Коли чорнокнижник, що діє довкола Брілла чи в нетрях Тірісфалю, показує достатню владу над основами енергії скверни, звістка доходить до глибоких підземних зал Андерсіті. Досвідчені заклиначі на кшталт Аґерона Карґала шукають таланти й передають виклик тим, хто справді подає надії. Отримати виклик від Карендіна Галґара — і рідкісна честь, і небезпечна справа: це означає, що дрібних бісів і простих прокльонів для навчання вже замало."},{t="Магічний Квартал",b="Галґар наглядає за обрядами чорнокнижників із затінених закутків Магічного Кварталу, неподалік зловісного вівтаря, відомого як Храм Проклятих. Темні заклиначі-Відступники не знають гидливих моральних обмежень живих, та навіть вони вимагають суворої дисципліни, коли беруться викликати істот з інших світів. Галґар не терпить вагань і сентиментів: його виклик вимагає негайної покори й повної готовності зустрітися з ворожими жахіттями Викривленого Нижнього Світу."}},faq={{q="Хто такий Карендін Галґар?",a="Карендін Галґар — головний наставник чорнокнижників у Магічному Кварталі Андерсіті. Він керує темним розвитком закликачів-Відступників і перевіряє їхню рішучість, перш ніж навчити прив'язувати могутніх істот Нижнього Світу.",al={"карендін галґар","майстер галґар","хто такий галґар"}},{q="Хто направляє мене до Галґара?",a="Аґерон Карґал, досвідчений наставник чорнокнижників у Бріллі, посилає вас, отримавши звістку, що Майстер Галґар особисто зацікавився вашими успіхами.",al={"хто направляє до галґара","кличе галґар","айджерон каргал"}},{q="Де в Андерсіті знайти Карендіна Галґара?",a="Галґар у Магічному Кварталі Андерсіті, неподалік темного помосту, відомого як Храм Проклятих.",al={"місце галґара","де галґар","галґар магічний квартал"}},{q="Чому цей виклик важливий?",a="Цей виклик знаменує ваш перехід від простих заклять до ризикованого підкорення демонів, а саме — початок випробувань, потрібних, щоб прив'язати до себе блукача Порожнечі.",al={"навіщо цей виклик","мета завдання","куди веде виклик галґара"}},{q="Чи Галґар готовий навчати будь-кого?",a="Галґар зосереджує увагу саме на багатонадійних чорнокнижниках. Він не марнує часу на порожні люб'язності й вимагає, щоб кожен учень, якого до нього приводять, уже довів, що здатен упоратися з мінливим мистецтвом скверни.",al={"чи навчатиме галґар будь-кого","вимоги галґара"}},{q="Що буде, коли доповіси Галґарові?",a="Щойно ви доповідаєте Галґарові, він одразу перевіряє ваші магічні здібності, доручаючи здобути складники, потрібні, щоб закликати й прив'язати потойбічного тіньового прислужника.",al={"що далі","після виклику галґара"}}},fp="16,349,17.484.0,17.481.0,23.229.0,25.171.0,46.129.0,30.181.0,34.208.0,39.177.0"}
P.entries["quest:1483"] = {n="Зіз Фіззікс",s="Це завдання відсилає мандрівників з Орди провідати Зіза Фіззікса — невдоволеного гоблінського інженера, що отаборився на західному гребені Кручі Вітрорізу. Ображений тим, що Венчурна Компанія віддала перевагу гномові-інженерові, Зіз перекинувся до Спілки Винахідників під вимогливу руку Спаттервалва.",h="Це завдання відсилає мандрівників з Орди провідати Зіза Фіззікса — невдоволеного гоблінського інженера, що...",kw={"зіз фіззікс","спаттервалв","спілка винахідників","ґерензо ренчвісл","круча вітрорізу","венчурна компанія"},ang={["faction:Horde"]="Шукачі пригод з Орди в Горах Кам'яного Кігтя часто допомагають агентам Спілки Винахідників, як-от Спаттервалву й Зізові, підточувати панування Венчурної Компанії на Кручі Вітрорізу.",["profession:Engineering"]="Запекла ворожнеча Зіза й Ґерензо точнісінько відбиває давнє, вибухове суперництво гоблінської та гномської інженерних філософій."},sec={{t="Справа професійної гордості",b="Венчурна Компанія тримається на нещадній експлуатації й механічних новаціях, але для Зіза Фіззікса вона перейшла межу, коли взяла до себе гнома-інженера Ґерензо Ренчвісла. Глибоко ображений тим, що доведеться працювати пліч-о-пліч із гномом-суперником, Зіз одразу почав шукати, як вибратися. Він звернувся до Спаттервалва, свого знайомого зі Спілки Винахідників, і благав перевести його кудись подалі від нагляду Ґерензо."},{t="З вогню та в полум'я",b="Нове місце в Спілці Винахідників не подарувало Зізові легкого життя, на яке він розраховував. Опинившись на західному краю Кручі Вітрорізу, він швидко збагнув, що Спаттервалв — такий самий визискувач, як будь-який десятник Венчурної Компанії. І все ж Зіз вважає, що тяжко гарувати під вимогливим гоблінським начальником куди краще, ніж ділити інженерну майстерню з гномом."}},faq={{q="Хто такий Зіз Фіззікс?",a="Зіз Фіззікс — гоблін-інженер, що колись працював на Венчурну Компанію в Горах Кам'яного Кігтя. Він перейшов до Спілки Винахідників, після того як його колишні наймачі взяли на роботу гнома-інженера.",al={"зіз фіззікс","хто такий зіз","про зіза фіззікса"}},{q="Чому Зіз Фіззікс пішов із Венчурної Компанії?",a="Він пішов на знак протесту, коли Венчурна Компанія найняла гнома-інженера Ґерензо Ренчвісла. Не бажаючи працювати пліч-о-пліч із гномом-суперником, Зіз випросив у Спаттервалва нову роботу.",al={"чому зіз пішов з венчурної компанії","чому покинув","зіз і венчурна компанія"}},{q="Де знайти Зіза Фіззікса?",a="Він на західному краю Кручі Вітрорізу в Горах Кам'яного Кігтя, звідки видно лісозаготівлі й розкопки Венчурної Компанії.",al={"місце зіза","де зіз","знайти зіза фіззікса"}},{q="Хто такий Спаттервалв?",a="Спаттервалв — гоблін-агент, пов'язаний зі Спілкою Винахідників, що переманює вправних інженерів із Венчурної Компанії й залучає їх до конкурентних проєктів.",al={"хто такий спаттервалв","роль спаттервалва"}},{q="Хто такий Ґерензо Ренчвісл?",a="Ґерензо — гном-інженер, якого Венчурна Компанія привела на Кручу Вітрорізу; це призначення обурило Зіза й розпалило запеклу професійну ворожнечу.",al={"ґерензо ренчвісл","хто гном-інженер"}},{q="Що таке Спілка Винахідників?",a="Спілка Винахідників — знане гоблінське інженерне торговельне об'єднання. Вона завзято змагається із суперниками на кшталт Венчурної Компанії й за кожної нагоди переманює чи повертає найкращих фахівців.",al={"спілка винахідників","гоблінська спілка винахідників"}}},fp="11,281,30.405.0,21.383.0,19.190.0,46.185.0,31.150.0,20.176.0,29.153.0,27.186.0"}
P.entries["quest:1485"] = {n="Мерзенні прислужники",s="У посушливій Долині Випробувань наставник чорнокнижників Рузан доручає майбутнім практикам темних мистецтв довести свою вправність у бою з мерзенними фамільярами. Щоб здобути знання прикликання демонів, посвячувані мають зустріти цих бісівських створінь у бою й забрати їхні відрубані голови. Це скромний, небезпечний перший крок до влади над силою Скверни під пильним оком Орди.",h="У посушливій Долині Випробувань наставник чорнокнижників Рузан доручає майбутнім практикам темних мистецтв...",kw={"мерзенні прислужники","фамільяри","чорнокнижник","рузан","біс","долина випробувань","скверна"},ang={["class:Warlock"]="Це випробування — ваш перший обряд переходу як чорнокнижника: ви доводите, що здатні підкорити демонічний вогонь, перш ніж здійснити обряд прикликання власного біса.",["faction:Horde"]="Хоч Орда дозволяє чорнокнижникам навчатися в Дуроторі, їхні темні мистецтва тримають під щільним замком у відокремлених місцях на кшталт Лігва.",["race:Orc"]="Орчі чорнокнижники щодня стикаються з темною історією свого народу, доводячи самовладання й вірність у суспільстві, яке пам'ятає жахи скверни."},sec={{t="Хистке місце в Орді",b="Чорнокнижники посідають непевне місце в щойно викуваній Орді Тралла. Спадщина демонічної скверни та кривавих угод, що колись принесли орчому роду руїну, лишила глибокі шрами й невигаслу недовіру. Хоч практиків магії Скверни в Дуроторі терплять, їх не люблять і не вітають. Багато хто обирає відлюдне життя в тінистих закутках на кшталт Лігва, практикуючи своє мистецтво подалі від цікавих очей і навчаючи тих рідкісних посвячуваних, що наважуються ступити на цей шлях."},{t="Випробування влади",b="Перш ніж дати учневі небезпечні обряди, потрібні, щоб підкорити біса своїй волі, Рузан вимагає доказу переваги. Біля печери на північний схід від Лігва мерзенні фамільяри скрадаються й жбурляють вогняними кулями в кожного, хто наблизиться. Убиваючи цих менших демонів і забираючи їхні голови, посвячуваний доводить, що здатен здолати вогняних супротивників, якими прагне керувати, — і що його не поглине та сама магія, якою він має намір повелівати."}},faq={{q="Чому Рузан посилає чорнокнижників битися з мерзенними прислужниками?",a="Рузан вимагає, щоб посвячувані зійшлися з мерзенними прислужниками, — тоді вони зрозуміють вогняну природу й небезпеку бісів, перш ніж намагатися закликати одного з них. Чорнокнижників мало, і їм не довіряють, тож він не ризикує життям учня, навчаючи закликати демонів, доки той не доведе, що може здолати таких істот у прямому бою.",al={"чому рузан посилає на прислужників","випробування рузана","випробування біса"}},{q="Де знайти мерзенних прислужників?",a="Вони збираються біля печери й у ній на північний схід від Лігва в Долині Випробувань, за кабанами й скорпідами, що никають довкола. Ця печера — табір зловісного Ковену Палаючого Клинка.",al={"де мерзенні прислужники","місце прислужників","печера рузана"}},{q="Як Орда ставиться до чорнокнижників у Дуротарі?",a="По всій Орді на чорнокнижників дивляться з глибокою підозрою й недовірою через демонічну історію, що колись зіпсувала орківський народ. Уряд Тралла терпить їх і визнає їхню бойову користь, але тримає на відстані, тож багато чаклунів живуть відлюдно.",al={"чи ненавидять чорнокнижників","лор чорнокнижників орди","чому не довіряють чорнокнижникам"}},{q="Яку нагороду дає це випробування?",a="Убивши цих істот і принісши Рузанові їхні відтяті голови, ви доводите, що маєте дисципліну й силу, потрібні, щоб командувати демонами, і це веде просто до навчання, як закликати біса-прислужника.",al={"нагорода випробування","чого я навчусь","закляття біса"}},{q="Чи мерзенні прислужники — справжні демони?",a="Так, мерзенні прислужники — дрібні демонічні біси, пов'язані з магією скверни. Хоч вони й малі на зріст, це грізні супротивники, що жбурляють у ворогів вогняні кулі.",al={"хто такі мерзенні прислужники","чи вони біси","тип демона прислужника"}},{q="Хто такий Рузан?",a="Рузан — орк, наставник чорнокнижників у Лігві в Долині Випробувань. Він навчає нових чорнокнижників-орків і тролів безпечно підкоряти енергію скверни й керувати закликаними слугами.",al={"рузан","хто такий рузан","чорнокнижник долини випробувань"}}},fp="14,398,31.472.0,20.441.0,53.326.0,35.202.0,44.315.0,45.197.0,33.174.0,13.190.0"}
P.entries["quest:1486"] = {n="Шкури девіантів",s="«Шкури девіантів» — доручення від Налпака, учня Наралекса, що стоїть на варті над входом до Печер Стогонів. Поки Наралекс у полоні спотвореного кошмару, Налпак намагається видобути щось корисне з мутованих звірів, породжених під Пустками. Збираючи шкури цих хижаків-девіантів, він сподівається знайти практичне застосування їхнім дивним, потойбічним властивостям.",h="«Шкури девіантів» — доручення від Налпака, учня Наралекса, що стоїть на варті над входом до Печер Стогонів.",kw={"шкури девіантів","налпак","наралекс","печери стогонів","девіанти","шкірництво"},ang={["class:Druid"]="Табір Налпака — похмура варта Кола Кенарія над задумом, що жахливо зійшов на манівці, тож стримати мутації печер для друїдів — справа особиста.",["profession:Herbalism"]="Ненормальний ріст, що живить звірів-девіантів, прямо пов'язаний зі спотвореною флорою й підземними джерелами, що в'ються мережею печер."},sec={{t="Скверна у плоті",b="Коли друїд із нічних ельфів Наралекс спробував дістатися підземних джерел під Пустками, щоб повернути буйне життя посушливим рівнинам, його розум поринув у страхітливий кошмар. Це темне марення просочилося в дійсність і перетворило тваринний світ Печер Стогонів на лютих звірів-девіантів. Раптори, кроколіски, гадюки й шкандибаючі жахи постали спотвореними й агресивними — їх змінила смарагдова скверна, що сочилася від їхнього сплячого господаря."},{t="Практичний друїд",b="Зі скелі над входом до печери Налпак спостерігає за лихом зі страхом і водночас із практичною цікавістю. Хоч він і визнає девіантних істот за своєю суттю зловісними й неприродними, він вірить, що їхні спотворені тіла можуть дати незвичайні матеріали. Особливо цупкі, спотворені шкури мають стійкість, що стане в пригоді вправним шкірникам, — так плоди трагічного кошмару обернуться на міцне спорядження."}},faq={{q="Де знайти Налпака?",a="Налпак і його товариші-учні влаштували невеликий табір високо в скелі, схожій на череп, над входом до Печер Стогонів. Не йдіть просто в головний тунель: видеріться схилами гори за входом до печери й обережно спустіться на верхній уступ печери-очниці, з якого видно оазу.",al={"місце налпака","де налпак","як знайти налпака","давець шкур девіантів"}},{q="Хто такі девіантні істоти?",a="Девіантні істоти — місцеві звірі, перетворені Смарагдовим Жахіттям, що вирвалося зі сплячого розуму Наралекса. Ящери, змії, кроколіски й вітряні змії, що живуть у Пустках, спотворилися на темніших, лютих потвор із дивними магічними властивостями й плямистою, неприродною шкурою.",al={"що таке девіанти","девіантні звірі","чому звірі мутували"}},{q="Навіщо Налпакові ці шкури?",a="Налпак розуміє, що хоч ці звірі й породжені злою скверною, їхні шкури мають незвичну, потойбічну міцність. Він вважає, що, вивчаючи й обробляючи хутра, шкірники можуть обернути скверну Жахіття на міцне спорядження.",al={"навіщо налпаку шкури","що налпак робить зі шкурами","призначення шкур"}},{q="Чи будь-яка девіантна істота дає шкури?",a="Ці шкури мають спотворені звірі, що никають тунелями й нутрощами Печер Стогонів. Мисливці й шкірники часто виявляють, що, здираючи шкуру зі звірів, можна отримати більше хутра, ніж просто знайти на їхніх рештках.",al={"які моби дають шкури","хто дає шкури девіантів","ферма шкур девіантів"}},{q="За кого Налпак — за Орду чи за Альянс?",a="Налпак — учень Наралекса й член Кола Кенарія. Він лишається нейтральним і прийме допомогу будь-якого вправного шукача пригод, з Альянсу чи з Орди, якому досить відваги зайти в зіпсовані печери.",al={"чи налпак орди","чи альянс може","шкури девіантів альянс"}},{q="Що сталося з Наралексом?",a="Наралекс прагнув пробудити підземні джерела Пусток, поєднавши свою свідомість зі Смарагдовим Сном. Натомість його сон захопило Жахіття: система печер перетворилася на розплідник страхіть, а сам він лежить у непритомності глибоко в печерах.",al={"хто такий наралекс","кошмар наралекса","що сталося з друїдом"}}},fp="13,382,24.451.0,17.451.0,24.331.0,27.292.0,33.244.0,40.238.0,49.212.0,25.281.0"}
P.entries["quest:1487"] = {n="Винищення девіантів",s="«Винищення девіантів» — доручення від друїдки з нічних ельфів Ебру над входом до Печер Стогонів. Поки інші учні намагаються розбудити свого сплячого провідника, Ебру просить шукачів пригод очистити печери від мутованих звірів-девіантів, породжених його спотвореним видінням. Позбавити підземну оазу цих жахіть — важливий крок, щоб спинити скверну, яка загрожує Пусткам.",h="«Винищення девіантів» — доручення від друїдки з нічних ельфів Ебру над входом до Печер Стогонів.",kw={"винищення девіантів","ебру","наралекс","печери стогонів","учні наралекса","девіанти"},ang={["class:Druid"]="Спотворена природа печер — сумне застереження про те, що буває, коли єднання зі Смарагдовим Сном обертається лихом.",["faction:Horde"]="Печери Стогонів лежать у самому серці центральних рівнин Калімдору, тож винищення цих хижаків життєво важливе для захисту довколишніх поселень, як-от Перехрестя.",["race:NightElf"]="Бачити, як благородна мрія Наралекса обертається на породжене кошмаром страхіття, — важкий тягар для мандрівників-калдореїв, які відчувають обов'язок допомогти своїм відрізаним родичам."},sec={{t="Мрія, що обернулася лихом",b="Друїд із нічних ельфів Наралекс привів своїх послідовників до підземних джерел Пусток із великим задумом: черпнути сили зі Смарагдового Сну й обернути спраглі рівнини на буйний, квітучий ліс. Натомість Наралекс заплутався в Сні, і його сон обернувся на болісний кошмар. Сила, що вирувала печерами, не зцілила землю, а спотворила місцевих звірів і рослини, перетворивши їх на жахливих агресивних мутантів — звірів-девіантів."},{t="Ебру стоїть на своєму",b="Зі скельної печери над входом Ебру та жменька вцілілих Учнів Наралекса з відчаєм бачать, як їх стає дедалі менше. Поки дехто з них віддає сили на те, щоб розбудити полеглого наставника, Ебру бачить нагальнішу біду. Якщо їх не спинити, девіантні гадюки, шкандибаки, спустошувачі й жахоікли, що стрімко множаться, виллються в Пустки. Тож Ебру наймає мандрівних шукачів пригод спуститися в глибокі тунелі й винищити потвор там, де вони народжуються."}},faq={{q="Де знайти Ебру, щоб почати це завдання?",a="Ебру разом із кількома товаришами-Учнями Наралекса перебуває у відлюдній печері високо над головним входом до Печер Стогонів — у тому, що скидається на праву очницю скелі, схожої на череп. Щоб дістатися до неї, зазвичай треба обійти гірський гребінь і обережно спуститися на верхній уступ.",al={"місце ебру","де ебру","як дістатися ебру","печера ока печер стогонів"}},{q="Через що звірі стали девіантами?",a="Цих істот спотворили темні сили, що просочуються зі Смарагдового Сну. Коли друїд Наралекс поєднав свою свідомість із підземними джерелами, щоб оживити Пустки, його розум захопив кошмар, і цілющі сили обернулися на згубну, що перетворює місцеву звірину на девіантних чудовиськ.",al={"чому звірі девіанти","походження девіантів","що зіпсувало тварин"}},{q="Хто такі Учні Наралекса?",a="Учні Наралекса — коло послідовників-друїдів, що прийшли з Наралексом до Печер Стогонів, щоб допомогти відродити Пустки. Після того як він опинився в пастці Жахіття, багато з них здичавіли чи збожеволіли, і лишилася тільки жменька при здоровому глузді, що намагаються виправити лихо.",al={"учні наралекса","послідовники наралекса","друїди печер стогонів"}},{q="Чи можуть і Альянс, і Орда взяти це завдання?",a="Так. Ебру та її товариші — нейтральні друїди, яких турбує збереження природи й стримування Жахіття. Вони приймають допомогу вправних поборників і з Орди, і з Альянсу.",al={"чи альянс і орда можуть","винищення девіантів нейтральне"}},{q="Яких істот треба вбити для Ебру?",a="Ебру посилає вас глибоко в печери полювати на чотири види зіпсованої звірини: Девіантних Спустошувачів, Девіантних Гадюк, Девіантних Шкандибайл і Девіантних Жахоіклів — по семеро кожних.",al={"кого вбивати для ебру","цілі винищення девіантів","яких девіантів вбити"}},{q="Чи пробуджує виконання цього завдання Наралекса?",a="Ні. Доручення Ебру зводиться до винищення шкідників і зменшення шкоди: треба прорідити небезпечних звірів. Щоб пробудити Наралекса, потрібен окремий обряд глибоко в його святилищі, у серці печер.",al={"чи це пробуджує наралекса","як пробудити наралекса"}}},fp="19,393,27.477.0,12.537.0,41.337.0,41.324.0,33.299.0,44.210.0,44.194.0,40.219.0"}
P.entries["quest:1489"] = {n="Гамуул Рунтотем",s="Це завдання веде шукачів пригод з Орди від буйних, але неспокійних оаз Пусток на високі вершини Тандер Блафа. Тонга Рунтотем підозрює глибоку духовну скверну в Печерах Стогонів і посилає вас по пораду до архідруїда Гамуула Рунтотема.",h="Це завдання веде шукачів пригод з Орди від буйних, але неспокійних оаз Пусток на високі вершини Тандер Блафа.",kw={"гамуул рунтотем","тонга рунтотем","тандер блаф","узвишшя старійшин","печери стогонів","коло кенарія"},ang={["class:Druid"]="Для друїдів-тауренів доповідь архідруїдові Гамуулу Рунтотему — прочанство до наставника, що заснував сучасне тауренське друїдство за наукою Малфуріона Стормрейджа.",["faction:Horde"]="Пустки — перехрестя молодої Орди, тож розслідування скверни, що поширюється, захищає шляхи постачання між Дуротаром, Малгором і північними заставами.",["race:Tauren"]="Це доручення пов'язує тривоги мисливських угідь предків у Пустках із порадами племінних старійшин, що живуть на священних кручах Малгору."},sec={{t="Тривожний сон",b="Вивчаючи звірину Пусток, Тонга Рунтотем помітив дивну недугу, що вразила істот біля буйних оаз. Змінені звірі мали панцирі, позначені неприродною силою, і Тонга збагнув, що сама земля потрапила в полон марного, неспокійного сну. Переконаний, що джерело цієї гнилі — води, які витікають із підземних Печер Стогонів, Тонга знає: щоб спуститися туди, потрібно куди більше мудрості, ніж має самотній природознавець."},{t="Порада на Узвишші Старійшин",b="Щоб збагнути загрозу в печерах, Тонга посилає вас до Тандер Блафа порадитися з його родичем, архідруїдом Гамуулом Рунтотемом. Гамуул — найвищий за рангом друїд серед тауренів і шанований духовний провідник Кола Кенарія в Малгорі. З тихого Узвишшя Старійшин Гамуул стежить за неспокоєм по всьому Калімдору й підтверджує, що жахіття, яке просочується Пустками, — страшна загроза, що вимагає всієї сили героїв Орди."}},faq={{q="Чому Тонґа посилає мене до Гамуула?",a="Тонґа виявив, що оази Пусток уражені дивною недугою, яка йде з Печер Стогонів. Оскільки це схоже на кошмар, що стиснув землю, він посилає вас до архідруїда Гамуула Рунтотема на Узвишшя Старійшин по настанову друїдів найвищого рівня, перш ніж хтось спробує зайти в печери.",al={"чому тонґа посилає до гамуула","чому гамуул","мета гамуула"}},{q="Де знайти Гамуула Рунтотема?",a="Архідруїд Гамуул Рунтотем у Тандер Блафі — столиці тауренів у Малгорі. Він стоїть на Узвишші Старійшин, звідки видно довколишні рівнини, разом з іншими друїдами й шаманами.",al={"місце гамуула","де гамуул","знайти гамуула рунтотема"}},{q="Що є джерелом скверни, яку помітив Тонґа?",a="Скверна йде з підземних джерел Печер Стогонів. Дивні води псують місцеву звірину й рослини, і земля поводиться так, наче потрапила в пастку невідворотного кошмару.",al={"джерело скверни тонґи","що таке скверна","скверна оази"}},{q="Що буде після розмови з Гамуулом?",a="Гамуул вітає вас у Тандер Блафі й готує до випробувань, що чекають попереду. Він попереджає, що боротьба з кошмаром під Пустками — тяжка справа, і посилає вас до Нари Вайлдмейн, щоб підготуватися до спуску в Печери Стогонів.",al={"що після гамуула","наступне завдання","продовження гамуула"}},{q="Хто такий Гамуул Рунтотем?",a="Архідруїд Гамуул Рунтотем — головний провідник друїдів-тауренів, близький друг дитинства й порадник Верховного Вождя Кайрна Бладгуфа. Опанувавши шляхи дикої природи після Третьої війни, він веде друїдів-тауренів до єднання з природою й Колом Кенарія.",al={"хто такий гамуул","лор гамуула","верховний друїд гамуул"}},{q="Чи обов'язкове це завдання, щоб зайти в Печери Стогонів?",a="Щоб просто ввійти в Печери Стогонів, жодного допуску не треба, але це завдання — сюжетний місток для Орди, що пов'язує загадку пишних оаз Пусток з експедицією в підземелля.",al={"чи обов'язкове для печер стогонів","залучення до печер стогонів"}}},fp="16,269,18.485.0,21.447.0,33.311.0,34.200.0,46.204.0,40.241.0,24.284.0,52.200.0"}
P.entries["quest:149"] = {n="Нитка з Примарного Волосся",s="«Нитка з Примарного Волосся» — доручення для ворожки Мадам Єви в Даркширі. Щоб спрясти примарну нитку, мандрівників посилають на південь до Сліпої Мері — змученого духа, що живе в покинутій хаті. Подарувавши їй ефірний гребінь, можна зібрати потрібні пасма з її примарних кіс.",h="«Нитка з Примарного Волосся» — доручення для ворожки Мадам Єви в Даркширі.",kw={"нитка з примарного волосся","мадам єва","сліпа мері","примарний гребінь","даркшир","привид"},ang={["class:Priest"]="Дух, що вирвав собі очі з душевних мук, — свідчення глибокої трагедії й тіней, які не відпускають неспокійних мерців Сутінколісся.",["faction:Alliance"]="Трагічні примари, що блукають фермами довкола Даркшира, нагадують, як швидко квітуче Велике Селище поринуло в темряву й самотність.",["profession:Tailoring"]="Прясти нитку з безтілесних решток привида — рідкісна окультна техніка, дуже далека від звичайних прядок і ткацьких верстатів."},sec={{t="Прохання ворожки",b="Мадам Єві з Даркшира потрібні особливі, потойбічні матеріали, щоб спрясти Нитку з Примарного Волосся для Аберкромбі. Звичайні нитки з льону чи вовни не годяться для обрядів Сутінколісся — потрібні ефірні пасма, зібрані просто з духа. Щоб здобути цей моторошний складник без насильства, Єва дає тендітний Примарний Гребінь, здатний проходити крізь завісу смерті й збирати примарне волосся, що випадає."},{t="Печаль Сліпої Мері",b="На південь від Даркшира, серед темних пагорбів, ховається покинутий хутір, де блукає заплакана примара на ім'я Сліпа Мері. Поглинута ненавистю до себе, вона без упину нарікає на свою потворність і кричить на непроханих гостей, щоб ті відвели очі: у муках вона вирвала собі очі — чи то перед смертю, чи то в мить смерті. Подарований Примарний Гребінь дарує їй коротку мить розради й спонукає розчесати примарне волосся, попри нескінченні муки."}},faq={{q="Хто така Сліпа Мері?",a="Сліпа Мері — скорботна примара, що блукає покинутим фермерським будинком на пагорбах на південь від Даркширу. Доведена до божевілля відчаєм і власною уявною потворністю, вона вирвала собі очі, щоб більше ніколи себе не бачити. Попри сліпоту, вона гостро й болісно відчуває кожен погляд на собі.",al={"сліпа мері","лор сліпої мері","хто мері сутінколісся"}},{q="Навіщо Мадам Єві волосся примари?",a="Мадам Єві потрібні пасма примарного волосся, щоб спрясти примарну нитку. У моторошному Сутінколіссі звичайних ремісничих матеріалів часто замало, тож вона покладається на окультні складники для своїх обрядів і захисних чарів.",al={"навіщо єві волосся примари","для чого нитка","нитка єви"}},{q="Де знайти будинок Сліпої Мері?",a="Її зруйнована садиба стоїть на пагорбах просто на південь від Даркширу, за міським цвинтарем, серед хижих жахіть і нежиті, що поневіряють темні ліси.",al={"місце сліпої мері","де сліпа мері","ферма на південь від даркшира"}},{q="Як Примарний Гребінь діє на духа?",a="Створений чи зачарований для незримого світу, Примарний Гребінь може торкатися безтілесних примар. Він ковзає крізь духовну матерію, як звичайний гребінь крізь живе волосся, і збирає пасма, що зберігають примарну подобу.",al={"як діє гребінь","лор примарного гребеня","гребінь волосся примари"}},{q="Чи ворожа Сліпа Мері до мандрівників?",a="Ні. Попри моторошні крики й плач, Сліпа Мері не ворожа до живих гостей. Її мука звернена цілком усередину, хоча в довколишніх лісах і сусідніх будівлях повно агресивних істот і нежиті.",al={"чи сліпа мері ворожа","чи мері нападе"}},{q="Що буде, коли даси Мері гребінь?",a="Скориставшись гребенем, Мері повертає його з заплутаним у ньому примарним волоссям. Шукачі пригод мають віднести гребінь назад Мадам Єві в Даркшир, щоб вона спряла з пасм нитку з примарного волосся.",al={"що після гребеня","повернути гребінь","після нитки з волосся"}}},fp="17,359,25.430.0,24.467.0,18.307.0,36.240.0,38.172.0,44.246.0,35.232.0,40.187.0"}
P.entries["quest:1490"] = {n="Нара Вайлдмейн",s="Нара Вайлдмейн — юна друїдка-тауренка в Тандер Блафі, що прагне розплутати трагедію, яка розгортається глибоко в Печерах Стогонів. Коли Верховний Друїд Гамуул Рунтотем зазирнув у Смарагдовий Сон і відступив від скверни, що там гноїться, він відіслав шукачів пригод порадитися з Нарою, чий незламний дух протримався досить довго, щоб побачити, як жахіття опановує їхніх родичів. Вона — ключова зв'язкова Орди, що спрямовує героїв покласти край Друїдам Ікла.",h="Нара Вайлдмейн — юна друїдка-тауренка в Тандер Блафі, що прагне розплутати трагедію, яка розгортається...",kw={"нара вайлдмейн","гамуул рунтотем","смарагдовий сон","друїди ікла","печери стогонів","тандер блаф"},ang={["class:Druid"]="Друїди оцінять мужність Нари, що пробиралася підступними, спотвореними закутками Смарагдового Сну, де не наважувалися затримуватися навіть досвідчені наставники на кшталт Гамуула.",["faction:Horde"]="Пильність Нари захищає серце земель Орди, щоб темні сили, які спотворюють Пустки, не розповзлися без перешкод у Малгор.",["race:Tauren"]="Для тауренів, що нещодавно стали на шлях друїдства під проводом Гамуула, Нара уособлює молоде, незламне покоління, готове прямо зустріти неприродну пошесть."},sec={{t="Видіння скверни",b="Коли Пустками почали ширитися дивні, неприродні явища, Верховний Друїд Гамуул Рунтотем вирушив у Смарагдовий Сон, щоб збагнути причину. Там він побачив культ друїдів, які спершу прагнули повернути життя посушливій савані, але втратили розум через мерзенну скверну. Старий і нездатний довго опиратися натискові жахіття, Гамуул утік назад у світ яви. Та його молодша учениця, Нара Вайлдмейн, не здалася так легко. Її палка рішучість тримала її у світі снів куди довше, і вона на власні очі побачила, на що обернувся культ."},{t="Протистояння Жахіттю",b="Гамуул дає загальний провід Колу Кенарія в Тандер Блафі, а Нара Вайлдмейн має тактичне чуття, потрібне, щоб викорінити гниль. Подивившись просто в спотворені, вкриті зміїною лускою обличчя полеглих друїдів, вона знає їхні злочини й руйнування, які вони прагнуть обрушити на Калімдор. Її рішучість кладе початок наступу Орди на Печери Стогонів, щоб знищити ватажків, які зреклися священних обітниць."}},faq={{q="Хто така Нара Вайлдмейн?",a="Нара Вайлдмейн — молода й завзята друїдка-тауренка, що живе на Узвишші Старійшин у Тандер Блафі. Вона навчається у Верховного Друїда Гамуула Рунтотема й не боїться протистояти згубним кошмарам, що загрожують рівновазі природи.",al={"хто така нара","лор нари вайлдмейн","нара вайлдмейн тандер блафф"}},{q="Чому Гамуул Рунтотем посилає мандрівників до неї?",a="Гамуул визнає, що похилий вік і згасання сил не дали йому довго затриматися в зіпсованому сні, де перебувають Друїди Ікла. Нара молода й несамовито рішуча, тож вона пробула в царстві снів довше й зібрала важливі відомості про задуми культу.",al={"чому гамуул посилає до неї","говорити з нарою","навіщо гамуул відправив мене"}},{q="Що Нара побачила в Смарагдовому Сні?",a="Нара бачила занепалих друїдів, що живуть у Печерах Стогонів. Вона бачила їхні обличчя, спотворені в зміїні, вкриті лускою личини, і збагнула темні задуми й злочини, які вони мають намір учинити в Пустках.",al={"що нара побачила","видіння нари","сон лускатих друїдів"}},{q="Де знайти Нару Вайлдмейн?",a="Її можна знайти в друїдському наметі на Узвишші Старійшин у Тандер Блафі, навпроти Верховного Друїда Гамуула Рунтотема.",al={"місце нари","де нара вайлдмейн","знайти нару"}},{q="Що буде, коли доповіси Нарі Вайлдмейн?",a="Після розмови Нара велить вам вирушити в Печери Стогонів і знищити збунтованих Друїдів Ікла — так починається велике завдання підземелля «Ватажки Ікла».",al={"що після нари","чого хоче нара","лідери ікла далі"}},{q="Чому друїди в Печерах Стогонів зіпсовані?",a="Друїди на чолі з Наралексом увійшли в печери, сподіваючись черпати силу зі Смарагдового Сну й принести в Пустки буйне життя. Натомість сон Наралекса обернувся жахливим кошмаром, що поглинув його послідовників і перетворив їх на зміїподібних Друїдів Ікла.",al={"чому друїди зіпсовані","культ печер стогонів","чому друїди пусток злі"}}},fp="13,481,22.598.0,25.471.1,21.230.0,59.289.0,39.210.0,33.127.0,46.169.0,52.263.0"}
P.entries["quest:1491"] = {n="Розумні напої",s="«Розумні напої» — підприємницька оборудка, яку замислив гоблін-торговець Мебок Міззірікс у Раджеті. Не зумівши зварити трунок для підсилення розуму з рогів сонцелуских рапторів, Мебок тепер доручає шукачам пригод спуститися в Печери Стогонів і зібрати ектоплазмові рештки для своєї найновішої формули напою.",h="«Розумні напої» — підприємницька оборудка, яку замислив гоблін-торговець Мебок Міззірікс у Раджеті.",kw={"розумні напої","мебок міззірікс","скорботна сутність","ектоплазми","раджет","печери стогонів"},ang={["class:Druid"]="Поки друїди спускаються в Печери Стогонів, щоб очистити жахіття, яке спотворює смарагдовий світ снів, Мебок бачить у трагічній скверні лише дешевий сироп для свого крамарського підприємства.",["faction:Horde"]="Для мандрівників, що перетинають перехрестя Пусток, торговці Раджета пропонують чимало легкого заробітку — якщо не розпитувати надто багато, що вони збираються робити з частинами потвор, які ви приносите.",["profession:Cooking"]="Будь-який кулінар одразу помітить санітарну катастрофу, що розгортається в Раджеті: настоювати сиру, сплюндровану кошмаром ектоплазму просто в питний трунок — порушення всіх правил харчової безпеки."},sec={{t="Рецепт катастрофи",b="Мебок Міззірікс, що торгує в гамірному портовому містечку Раджеті, — утілення класичної гоблінської філософії: будь-яке химерне місцеве явище можна обернути на дзвінку монету. Переконаний, що трунок для підсилення розуму зробить його магнатом за одну ніч, спершу він вірив, що секрет — у товчених рогах рапторів. Коли та партія виявилася геть невдалою, він просто взявся за ще сумнівніший складник: спотворювальну сутність, що сочиться з сусідніх Печер Стогонів."},{t="Скорботна Сутність",b="Пустки переживають тривожні зміни в природі: раптом проростають буйні оази, а місцева звірина обертається на лютих страховиськ. Міззірікс припускає, що каталізатор цих раптових змін — дивна речовина, яку він називає «Скорботною Сутністю». Вирішивши, що все, що так сильно змінює живе, мусить бути потужним таємним складником, він посилає найманців знищувати слизькі ектоплазми глибоко в лабіринті печер і зливати їхню світну рідину просто в пляшки для напоїв."}},faq={{q="Хто такий Мебок Міззірікс?",a="Мебок Міззірікс — заповзятливий гоблін із портового містечка Раджет. Санітарні норми його не обходять: він одержимий ідеєю створити на продаж «розумний напій», торгувати ним по всьому Калімдору й розбагатіти.",al={"мебок міззірікс","хто дає розумні напої","давець розумних напоїв"}},{q="Чому роги ящерів не спрацювали?",a="Спершу Мебок вірив, що з розтертих рогів ящерів Сонячної Луски вийде могутнє вариво для розуму. Але напій не дав обіцяної геніальності, і йому довелося взятися за куди небезпечніший активний складник.",al={"чому роги не спрацювали","роги раптора"}},{q="Що таке Скорботна Сутність?",a="Скорботна Сутність — ектоплазмова речовина, що стікає з неприродних слизів глибоко в Печерах Стогонів. Мебок вважає, що саме ця нестійка речовина спричиняє химерні мутації рослин і тварин, які ширяться Пустками.",al={"скорботна сутність","що таке сутність"}},{q="Де знайти ектоплазми із сутністю?",a="Сутність збирають з ектоплазмових істот — мінливих, ненажерних і кошмарних ектоплазм, — що ховаються в підземних тунелях Печер Стогонів на захід від Раджета.",al={"де ектоплазми","моби розумних напоїв","хто дає сутність"}},{q="Чи безпечно пити розумний напій?",a="Зважаючи на те, що сутність добувають із кошмарних слизів, пов'язаних зі згубними мутаціями в Пустках, розливати її в пляшки як тонік на продаж — шалена безрозсудність. Як і личить гоблінській діловій етиці, Мебок куди більше переймається тим, чи товар продаватиметься, ніж здоров'ям покупців.",al={"чи безпечно пити","чи отруйний напій"}},{q="Що далі після завершення «Розумних напоїв»?",a="«Розумні напої» завершують нинішню напійну оборудку Мебока. Задоволений доставленою Скорботною Сутністю, він нагороджує вас і обіцяє поділитися майбутніми прибутками, щойно його сумнівний тонік принесе йому статки.",al={"що після розумних напоїв","продовження"}}},fp="12,312,21.488.0,19.518.0,22.207.0,33.250.0,24.258.0,54.194.0,35.266.0,41.203.0"}
P.entries["quest:1492"] = {n="Начальник пристані Діззівіг",s="«Начальник пристані Діззівіг» — доручення гінця: доставити ящик із зіллями й реагентами через Пустки до портового містечка Раджет. Вантаж вирушить за Велике море до Старого Світу на кораблі, зафрахтованому через місцеві пристані. Це завдання — пряме знайомство мандрівників із гамірною нейтральною торгівлею, що вирує на пристані Раджета.",h="«Начальник пристані Діззівіг» — доручення гінця: доставити ящик із зіллями й реагентами через Пустки до...",kw={"начальник пристані діззівіг","раджет","пристань","захищений ящик","доставка","східні королівства"},ang={["faction:Horde"]="Для шукачів пригод з Орди, що мандрують сухими рівнинами Пусток, доставка вантажу до Раджета — знайомство з важливими нейтральними морськими шляхами, що поєднують Калімдор зі Східними Королівствами."},sec={{t="Гінцем до порту",b="Коли товари треба перевезти через океан між Калімдором і Східними Королівствами, нейтральний порт Раджет — головні ворота для мандрівників із центрального Калімдору. Каравани вже вирушили, а алхімічні припаси чекають на відправку до колег у Старому Світі, тож мандрівників часто просять власноруч донести захищені ящики до самої води."},{t="Пристані Раджета",b="Начальник Пристані Діззівіг наглядає за морськими вантажами, що прибувають і відпливають, зі свого посту на дерев'яних пристанях Раджета. Зводячи рахункові книги, декларації й місця в трюмах, Діззівіг дбає, щоб приватні вантажі знаходили місце на кораблях, що прямують на схід через Велике море до портів на кшталт Бухти Чорної Води."}},faq={{q="Хто такий Начальник Пристані Діззівіг?",a="Начальник Пристані Діззівіг — гоблін-урядовець порту на головному причалі Раджета. Він веде реєстри суден і вантажів і відає переправами між Калімдором і портами за морем.",al={"діззівіг","хто такий діззівіг","де діззівіг"}},{q="Куди відправляють ящик?",a="Ящик із зіллями й реагентами відправляють до Старого Світу: місце на нього замовлено на найближчому судні з Раджета до Бухти Чорної Води.",al={"куди ящик","чорноводна бухта","місце призначення ящика"}},{q="Де розташований Раджет?",a="Раджет лежить на східному узбережжі Пусток, у захищеній затоці просто на схід від центрального перехрестя.",al={"де раджет","місце раджета"}},{q="Навіщо відправляти вантаж через гоблінський порт?",a="Раджет — нейтральний порт, відкритий і для Орди, і для незалежних торговців; звідси регулярно ходять судна через Велике Море, оминаючи військові блокади й політичну ворожнечу.",al={"навіщо гоблінський порт","чому раджет"}},{q="Що в захищеному ящику?",a="У ящику — набір готових зіль, ремісничих реагентів і різних алхімічних товарів для спільників у Східних Королівствах.",al={"що в ящику","вміст ящика"}},{q="Хто відправляє вантаж Діззівігові?",a="Вантаж відправляє алхімік із Пусток, який не встиг на звичайний караван і потребував надійного гінця, щоб дістатися причалу до наступного припливу.",al={"хто відправляє","давець завдання"}}},fp="20,347,21.359.0,15.294.0,28.192.0,30.152.0,25.123.0,37.185.0,32.148.0,35.181.0"}
P.entries["quest:1498"] = {n="Шлях оборони",s="«Шлях оборони» — обряд посвяти для молодих воїнів Орди, який доручає бувалий боєць Уззек на Далекій Дозорній Заставі. Новачки мають полювати на наелектризованих звірів Громового Хребта, щоб довести, що мають досить витривалості, аби стати щитом Орди.",h="«Шлях оборони» — обряд посвяти для молодих воїнів Орди, який доручає бувалий боєць Уззек на Далекій Дозорній...",kw={"шлях оборони","уззек","далека дозорна застава","громовий хребет","обпалена луска","воїн"},ang={["class:Warrior"]="Це завдання знаменує перехід новачка до науки оборони й учить: справжня бойова сила — у тому, щоб захистити союзників від загибелі.",["faction:Horde"]="Далека Дозорна Застава — важливий пропускний пункт, що боронить дорогу в Пустки, тож витривалість її вартових — запорука безпеки Орди."},sec={{t="Щит Орди",b="Війна в Орді — це не тільки шалений наступ із дикою люттю. На Далекій Дозорній Заставі, на кордоні між Пустками й Дуротаром, ветеран-воїн Уззек навчає молодих воїнів тверезого обов'язку оборони. Для Уззека найвище покликання воїна — стати між небезпекою і тими, хто не може себе захистити, і прийняти на себе нищівні удари, щоб Орда вистояла."},{t="Випробування громом",b="Щоб новачки довели, що мають витривалість і рішучість для дисциплінованої оборони, Уззек посилає їх на Громовий Хребет. У цій ущелині на півночі Дуротару, за Річкою Південної Люті, кишать громоящери й блискавошкурі. Пережити оглушливі розряди цих звірів і здобути їхню обпалену луску — означає показати, що новачок має досить стійкості, аби втримати передову."}},faq={{q="Хто дає завдання «Шлях оборони»?",a="Завдання дає Ветеран Уззек — досвідчений воїн біля Далекої Дозорної Застави, що стереже кордон, де Дуротар сходиться зі східним краєм Пусток.",al={"хто дає шлях оборони","початок шляху оборони","місце уззека"}},{q="Де розташований Громовий Хребет?",a="Громовий Хребет лежить за мостом через Річку Південної Люті, у західному Дуротарі, на північ від головної дороги. Ущелину населяють агресивні громоящери й блискавкошкурі.",al={"де громовий хребет","де громові ящери","місце обпаленої луски"}},{q="Чому Уззек вимагає саме обпалену луску?",a="Обпалену луску можна здобути, лише полюючи на звірів Громового Хребта, що б'ють блискавкою. Витримавши їхні електричні удари, воїн доводить, що має фізичну міцність і стійкість, потрібні, щоб опанувати складніші прийоми оборони.",al={"чому обпалена луска","призначення луски"}},{q="Який філософський урок цього випробування?",a="Уззек навчає, що бути воїном — це не лише вбивати, а й бути непробивним заслоном. Вистоявши проти люті диких звірів, посвячувані вчаться поєднувати товсту шкуру з розважливим рухом, щоб захищати слабших союзників.",al={"філософський урок","лор шляху оборони","лор оборонної стійки"}},{q="Що далі, коли завершено «Шлях оборони»?",a="Коли ви доведете Уззекові свою оборонну вправність, він посилає вас продовжити бойове навчання — розшукати Тун'ґріма Файрґейза.",al={"що після шляху оборони","наступне завдання","продовження"}},{q="Чи можуть це випробування пройти не-воїни?",a="Ні. «Шлях оборони» — обряд посвяти суто для воїнів, створений, щоб випробувати й навчити новобранців основ вартової служби й оборонного бою.",al={"чи не воїни можуть","лише воїни"}}},fp="15,278,23.412.0,16.391.0,36.169.0,31.197.0,49.235.0,51.239.0,49.129.0,38.155.0"}
P.entries["quest:1499"] = {n="Мерзенні прислужники",s="Це завдання завершує першу виправу молодого чорнокнижника проти демонічних прислужників, що ховаються в Долині Випробувань. Убивши мерзенних фамільярів під проводом Рузана, неофіт доповідає про свій учинок Зуріті Фарґейз, яка керує винищенням Палаючого Клинка, що насувається.",h="Це завдання завершує першу виправу молодого чорнокнижника проти демонічних прислужників, що ховаються в...",kw={"мерзенні прислужники","фамільяри","чорнокнижник","зуріта фарґейз","рузан","палаючий клинок","долина випробувань"},ang={["class:Warlock"]="Для посвячуваного в темні мистецтва зустріч із мерзенними фамільярами — необхідне випробування: ви доводите, що можете підкорювати й знищувати дикі сутності Скверни, а не ставати їхньою здобиччю.",["race:Orc"]="Присутність демонічних фамільярів — гидке нагадування про темні угоди, що колись поневолили орчий рід, тож їхнє вигнання з землі Дуротару — справа виживання культури.",["race:Troll"]="Тролі Темного Списа, що ділять Долину Випробувань, дивляться на демонічну магію з глибокою підозрою, тож молодим практикам важливо довести свою вірність у боротьбі з культистами-відступниками."},sec={{t="Питання дисципліни",b="Поки інших молодих воїнів і розвідників у Долині Випробувань Зуріта Фарґейз посилає просто стримувати навалу в Ковені Палаючого Клинка, посвячувані чорнокнижники спершу відповідають перед своїми тіньовими наставниками. Рузан вимагає доказу сили й влади над меншими демонами, перш ніж повернути учнів у лоно загальної оборони Орди, щоб їхні зусилля служили і колу чорнокнижників, і безпеці Лігва."},{t="Загроза Ковену",b="Зуріта Фарґейз пильно стежить за північною печерою над Долиною Випробувань. Мерзенні фамільяри, що скрадаються всередині, — лише найслабші улюбленці культистів Палаючого Клинка, та їхня відкрита присутність на священних тренувальних землях — зухвала образа і дедалі більша небезпека. Доповідь про ваш успіх проти них підтверджує: навіть ті, хто йде шляхом мистецтв Скверни, лишаються відданими захисту Дуротару від справжньої скверни."}},faq={{q="Чому Рузан посилає мене до Зуріти Фарґейз, а не нагороджує сам?",a="Зуріта Фарґейз керує загальною обороною й винищенням Палаючого Клинка в Долині Випробувань. Рузан спершу перевіряє, як ви даєте раду меншим істотам скверни, а тоді посилає вас до Зуріти, щоб вашу службу офіційно визнали й долучили до ширшої оборони Долини.",al={"чому рузан посилає до зуріти","рузан до зуріти","чому говорити із зурітою"}},{q="Хто такі мерзенні прислужники?",a="Мерзенні прислужники — дрібні демонічні біси й поплічники на службі Ковену Палаючого Клинка. Поодинці вони слабкі, але служать темнішим господарям, що ховаються глибоко в печері над Долиною Випробувань.",al={"хто такі прислужники","лор прислужників","прислужники палаючого клинка"}},{q="Де знайти Зуріту Фарґейз?",a="Зуріта Фарґейз стоїть просто неба біля центру Лігва в Долині Випробувань, за кілька кроків від табору наставників, де перебуває Рузан.",al={"де зуріта","місце зуріти фарґейз","карта зуріти"}},{q="Чому є ще одне завдання з точнісінько такою самою назвою?",a="Більшість шукачів пригод отримують завдання «Мерзенні прислужники» безпосередньо від Зуріти Фарґейз, щоб полювати на цих істот. А чорнокнижникам Рузан дає власне класове завдання, після якого їх ненадовго посилають назад до Зуріти.",al={"чому два завдання з однаковою назвою","дубль мерзенних прислужників","прислужники чорнокнижників"}},{q="Що Палаючий Клинок робить у Долині Випробувань?",a="Культ Палаючого Клинка таємно діє в закутках по всьому Дуротару, прагнучи підточити нову Орду Тралла зсередини. Вкорінившись у печері просто в Долині Випробувань, вони можуть полювати на необстріляних новачків і сіяти демонічну скверну просто на очах в орківських наглядачів.",al={"палаючий клинок долина випробувань","чому культисти в лігві"}},{q="Чи знищення цих прислужників викорінює культ?",a="Ні. Як зауважує Зуріта, мерзенні прислужники — лише улюбленці й розвідники темніших сил у ковені. Перемога над ними — тільки перший крок до того, щоб викрити й викорінити глибшу загрозу культистів, яка гніздиться в Долині.",al={"чи культ знищено","чи палаючий клинок переможено"}}},fp="14,288,22.439.0,23.442.0,75.298.0,27.216.0,34.169.0,52.245.0,56.294.0,47.225.0"}
P.entries["quest:15"] = {n="Розвідати Ехо-Рідж",s="«Розвідати Ехо-Рідж» — одне з перших військових доручень Маршала Макбрайда в Долині Нортширу. Новобранців посилають на північ, до Шахти Ехо-Рідж, аби винищити кобольдів-робітників, що лізуть із-під землі, і з'ясувати справжній розмах зарази, що загрожує мінеральним багатствам абатства.",h="«Розвідати Ехо-Рідж» — одне з перших військових доручень Маршала Макбрайда в Долині Нортширу.",kw={"ехо-рідж","кобольди","шахта","нортшир","маршал макбрайд","розвідка"},ang={["faction:Alliance"]="Кобольди, що підповзають так близько до духовного серця Стормвінда в Нортширі, показують, яким уразливим стало королівство, коли його регулярні сили розтягнуто до краю.",["profession:Mining"]="Шахта Ехо-Рідж — головне джерело міді для ковалів Нортширу, тож зачистка цих підземних тунелів для рудокопів — питання прямого економічного виживання.",["race:Human"]="Для молодих людей, що починають службу в Долині Нортширу, захист Ехо-Ріджу від підземних шкідників — одне з перших випробувань, у якому вони доводять свою цінність королівству."},sec={{t="Зараза, що глибшає",b="Перші сутички довкола Нортширу зводилися до розрізнених шкідників, що никали лісовим узліссям, та невдовзі розвідники донесли про значно організованішу загрозу. Кобольди не просто нишпорили лісами — вони великими силами зібралися біля Шахти Ехо-Рідж. Маршал Макбрайд наказує новобранцям рушати на північ, стати до бою з кобольдами-робітниками біля входу в шахту й оцінити, наскільки глибоко вкоренилися ці паразити."},{t="Загроза багатству абатства",b="Шахта Ехо-Рідж — важливе джерело руди й сировини для братства Нортширу та стормвіндської варти, розквартированої тут. Щуроподібні збирачі, захопивши тунелі, паралізують видобуток і оголюють, як тонко розтягнута місцева оборона. Знищення десяти робітників виявляється лише першим кроком: побоювання Макбрайда справджуються — зараза сягає значно глибше в штольні, ніж може зарадити звичайний патруль на поверхні."}},faq={{q="Хто посилає мене з цим дорученням?",a="Маршал Макбрайд, командир вартових Стормвінда в Абатстві Нортшира, наказує розвідати шахту, щойно розвідники виявляють, що на півночі збираються кобольди.",al={"хто посилає","давець завдання","маршал макбрайд"}},{q="Де розташована Шахта Ехо-Рідж?",a="Шахта Ехо-Рідж — на крайній півночі Долини Нортширу, просто в передгір'ях над абатством і його виноградниками.",al={"місце ехо-рідж","де шахта","знайти ехо-рідж"}},{q="Чому кобольди небезпечні для Нортширу?",a="Поодинці кобольди — боягузливі падальники, але вони швидко плодяться й зграями заполоняють підземні тунелі. Захопивши Шахту Ехо-Рідж, вони зупиняють важливий видобуток і загрожують затопити долину, якій бракує захисників.",al={"чому кобольди небезпечні","чому вбивати кобольдів","небезпека кобольдів"}},{q="Що буде, коли я переможу робітників надворі?",a="Повернувшись до Маршала Макбрайда, ви підтверджуєте його найгірші підозри: шахту геть заполонили. Він одразу знову залучає вас — тепер для глибшого наступу в підземні штольні в завданні «Сутичка біля Ехо-Рідж».",al={"що після робітників","наступне завдання","продовження"}},{q="Чому армія Стормвінда сама не очистить шахту?",a="Відколи Король Варіан Рінн зник, а сили розпорошені по Елвінну й сусідніх рубежах, місцевий гарнізон Нортширу надто малий, щоб відряджати цілі патрулі на винищення шкідників, тож він покладається на вправних новобранців, що щойно прибули.",al={"чому армія стормвінда не очистить","де вартові стормвінда","чому новобранці"}},{q="Які кобольди трапляються біля входу до шахти?",a="На поверхні й біля верхніх входів працюють кобольди-робітники — прості копачі, що риють тунелі й збирають свічковий віск для своєї підземної колонії.",al={"типи кобольдів","кого вбивати","кобольд-робітник"}}},fp="22,301,23.435.0,28.426.0,29.183.0,37.146.0,40.227.0,48.204.1,57.228.0,56.163.0"}
P.entries["quest:150"] = {n="Мурлоки-браконьєри",s="Доглядач Пристані Барен у Лейкширі просить шукачів пригод проріджувати дедалі численніших мурлоків на березі Озера Незрушного, поки ті не винищили головне джерело їжі містечка. Те, що починається як звичайна нагорода за боротьбу зі шкідниками, порушує тривожне питання: чому прибережні істоти оселяються так глибоко в горах, далеко від моря?",h="Доглядач Пристані Барен у Лейкширі просить шукачів пригод проріджувати дедалі численніших мурлоків на березі...",kw={"мурлоки-браконьєри","доглядач пристані барен","мурлоки","озеро незрушне","риба","лейкшир"},ang={["faction:Alliance"]="Лейкшир і так ледве стримує орків Блекрок і гнолів, тож у містечка Альянсу майже не лишається сил, щоб уберегти свої життєво важливі харчові запаси в Озері Незрушному.",["race:Human"]="Колись Редрідж був тихим місцем відпочинку для мешканців королівства Стормвінд; бачити, як його чисті гірські води заполонили ворожі мурлоки, — гірке свідчення того, наскільки занепав лад."},sec={{t="Загроза міській коморі",b="Озеро Незрушне — джерело життя Лейкширу: воно годує гірське містечко й постачає ринок свіжим уловом. Коли на мілинах осіли великі племена мурлоків, Доглядач Пристані Барен збагнув, що містечку загрожує справжнє лихо. Ненажерливі риболюди жадібно прочісували воду, і якби їх ніхто не зупинив, місцевій рибі загрожувало б повне винищення."},{t="Дивне переселення вглиб суходолу",b="Мурлоки зазвичай промишляють на морських узбережжях, тож їхня численна присутність високо в Горах Редріджу — видовище незвичне. Доглядач Пристані Барен відкрито дивується, чому вони забралися так далеко від відкритого океану. Чи загнали їх углиб суходолу морські хижаки, чи вони тікають від суперечок за територію, чи їх приваблюють щедрі води Озера Незрушного, — їхнє переселення натякає на глибші негаразди деінде в краї."}},faq={{q="Хто такий Доглядач Пристані Барен?",a="Доглядач Пристані Барен відає причалами й рибальським рухом на березі Озера Незрушного в Лейкширі. Він займається постачанням водою й наймає шукачів пригод, щоб боронити багатства озера від водяних загроз.",al={"доглядач пристані барен","барен","хто дає мурлоків-браконьєрів"}},{q="Звідки в Горах Редріджу мурлоки?",a="Мурлоки зазвичай живуть на морських узбережжях і в болотах, тож їхня поява на високогірному Озері Незрушному — незвична. Доглядач Пристані Барен припускає, що ці племена перебралися вглиб суходолу, тікаючи від чогось іще гіршого на узбережжях.",al={"чому мурлоки в редріджі","мурлоки в озері незрушному","риболюди в озері"}},{q="Чим мурлоки загрожують Лейкширу?",a="Лейкшир дуже залежить від риболовлі й торгівлі на Озері Незрушному. Племена мурлоків стрімко виловлюють рибу, загрожуючи залишити містечко без головного джерела їжі й підірвати місцеве господарство.",al={"чому мурлоки небезпечні","проблема мурлоків лейкширу","риби озера мало"}},{q="Навіщо Доглядач Пристані Барен збирає плавці мурлоків?",a="Барен збирає вісім плавців мурлоків як речовий доказ винищення. Плавці підтверджують, що шукачі пригод справді проріджують мурлоків на берегах і стримують племена, що насуваються.",al={"навіщо плавці мурлоків","нагорода за плавці"}},{q="Чи є інші завдання з мурлоками Озера Незрушного?",a="Так, Доглядач Пристані Барен дає й супутнє завдання, «Торгівля рибою», яке просить шукачів пригод здобути свіжу рибу з озера й у мурлоків, заразом очищаючи води.",al={"торгівля рибою зв'язок","інші завдання мурлоків редріджу"}},{q="Яку нагороду дає Доглядач Пристані Барен за очищення від браконьєрів?",a="Отримавши вісім плавців, Доглядач Пристані Барен нагороджує шукача пригод добротною Дворфійською Вудкою, щоб заохотити дбайливе ставлення до вод озера.",al={"нагорода за браконьєрів","завдання дворфійської вудки"}}},fp="15,317,29.394.0,24.401.0,24.209.0,38.253.0,45.211.0,46.189.0,57.169.0,65.166.0"}
P.entries["quest:1501"] = {n="Створіння Порожнечі",s="Створіння Порожнечі — переломний обряд посвяти для молодих чорнокнижників Орди, що навчаються в Оргріммарі. Щоб посвячений навчився прикликати блукача Порожнечі, Ґан'рул Бладай доручає йому повернути викрадену Скрижаль Верги в культистів-ренегатів Палаючого Клинка, що ховаються в Череп-скелі.",h="Створіння Порожнечі — переломний обряд посвяти для молодих чорнокнижників Орди, що навчаються в Оргріммарі.",kw={"створіння порожнечі","блукач порожнечі","скрижаль верги","ґан'рул бладай","палаючий клинок","череп-скеля","чорнокнижник"},ang={["class:Warlock"]="Це випробування — основоположний обряд посвяти для чорнокнижників Орди: від маленьких бісів вони переходять до тіньових слуг, здатних стояти на передовій.",["faction:Horde"]="Хоч Орда Тралла загалом не довіряє адептам Скверни, наставники на кшталт Ґан'рула дбають, щоб ті, хто вивчає темні мистецтва, служили своєю силою лише Вождеві.",["race:Orc"]="Для орків, яких переслідує минуле з Радою Тіней, полювання на Палаючий Клинок — певна відплата тим, хто й досі прагне демонічної згуби."},sec={{t="Хистке мистецтво",b="У підземних тінях Тіньової Розколини Оргріммара Ґан'рул Бладай наглядає за чорнокнижниками Орди. У новій державі Тралла на магію Скверни дивляться з глибокою пересторогою, бо її плямує темна історія оркських кланів. Ґан'рул визнає, що справжніх чорнокнижників в Орді лишилося небагато, проте наполягає: їхні небезпечні вміння необхідні для виживання Орди. Щоб бути корисним Вождеві, посвячений не може покладатися лише на хаотичний вогонь біса — він мусить навчитися повелівати істотами чистої тіні й витривалості."},{t="Викрадена скрижаль",b="Щоб прикликати блукача Порожнечі, потрібні особливі руни, викарбувані на Скрижалі Верги. На жаль, реліквію пограбував Палаючий Клинок — фанатичний тіньовий культ, що діє просто під носом у Вождя, в печері Череп-скелі. Ґан'рул посилає учня вдарити по лігву культистів, повернути скрижаль і завдати кривавого удару ренегатам, що плямують усіх чорнокнижників."}},faq={{q="Хто такий Ґан'рул Бладай?",a="Ґан'рул Бладай — старший наставник чорнокнижників у Тіньовій Розколині під Оргріммаром. Він керує навчанням молодих чорнокнижників Орди, вчить їх безпечно підкоряти темні сили й прив'язувати потойбічних прислужників, не піддаючись скверні.",al={"ґан'рул бладай","ґан'рул","хто дає завдання"}},{q="Що таке Скрижаль Верги?",a="Скрижаль Верги — реліквія з вирізьбленими особливими рунами закликання, потрібними, щоб викликати блукача Порожнечі з Нижнього Світу. Її викрав культ Палаючого Клинка, і її треба повернути, щоб Ґан'рул міг провести посвячуваного крізь обряд.",al={"скрижаль верги","що за скрижаль","скрижаль"}},{q="Де Череп-скеля?",a="Череп-скеля — темна печера просто на схід від Оргріммара, на скелястих кручах Дуротару. Вона править за таємний сховок культистів Палаючого Клинка.",al={"де череп-скеля","місце череп-скелі","де скрижаль"}},{q="Чому Ґан'рул Бладай зневажає Палаючий Клинок?",a="Культ Палаючого Клинка відкрито служить демонічним господарям і підточує Орду Тралла. Ґан'рул вважає їх нестерпною прикрістю для Вождя й безрозсудною пошестю, що накликає підозру й ганьбу на всіх чорнокнижників.",al={"чому ґан'рул ненавидить палаючий клинок","чорнокнижники палаючого клинка"}},{q="Навіщо чорнокнижникам закликати блукача Порожнечі?",a="Блукачі Порожнечі — істоти Нижнього Світу, здатні витримувати величезні удари й захищати свого закликача від шкоди. Опанувати прив'язування блукача Порожнечі — важливий стрибок у виживанні чорнокнижника й силі його закликань.",al={"навіщо блукач порожнечі","мета блукача порожнечі"}},{q="Що буде, коли скрижаль повернуто?",a="Отримавши Скрижаль Верги, Ґан'рул дає посвячуваному потрібні руни й кличе його завершити обряд у завданні «Зв'язування», де чорнокнижник має власноруч приборкати закликаного блукача Порожнечі, щоб опанувати його.",al={"що після скрижалі","наступне завдання"}}},fp="20,320,16.544.0,17.411.0,24.261.0,28.230.0,20.167.0,52.242.0,44.237.0,41.229.1"}
P.entries["quest:1502"] = {n="Тун'ґрім Файрґейз",s="Опанувавши перші уроки оборонної тактики, воїни Орди вирушають через Пустки на пошуки Тун'ґріма Файрґейза. Цей відлюдькуватий майстер-зброяр отаборився на суворих кряжах Тернистого Пагорба на схід від Перехрестя. Знайти його — обряд посвяти для бійців, що шукають зброю, гідну їхньої зростаючої майстерності.",h="Опанувавши перші уроки оборонної тактики, воїни Орди вирушають через Пустки на пошуки Тун'ґріма Файрґейза.",kw={"тун'ґрім файрґейз","тернистий пагорб","коваль","самітник","воїн","перехрестя"},ang={["class:Warrior"]="Кожного молодого воїна Орди посилають у дику глушину шукати Тун'ґріма, щоб здобути власну викувану зброю на додачу до бойового вишколу.",["faction:Horde"]="Орда тримається не лише на кількості, а й на вправних руках досвідчених майстрів, які кують добру сталь для солдатів передової, що боронять Калімдор.",["profession:Blacksmithing"]="Тун'ґрім уособлює самотню оркську ковальську традицію: попри відлюддя й сліпоту він не полишає мистецтва перетворювати розпечений метал на смертоносні знаряддя."},sec={{t="Самітник на кряжі",b="Щойно молодий воїн опанує оборонне мистецтво під наглядом наставників-ветеранів на кшталт Уззека, йому велять загострити бойову звитягу доброю сталлю. Звичайні зброярні можуть дати бійцеві передової не так уже й багато; справжня майстерність вимагає особистої зброї, викуваної майстром надзвичайної слави. На суворій савані Пусток такий коваль — Тун'ґрім Файрґейз, літній орк-самітник, що покинув життя в поселеннях і тримає самотню кузню високо над рівнинами."},{t="Життя у вогні горна",b="Щоб дістатися до Тун'ґріма, треба піднятися на Тернистий Пагорб — зубчасте узвишшя на схід від Перехрестя, де живуть дикі раптори й ворожі шипогриви. Живучи далеко від захисту міських мурів, коваль віддає свої самотні години лише обробці металу. Десятиліття, проведені за спогляданням пекучого полум'я горна, зіпсували йому зір, але чуття лишилося гострим. Коли мандрівник видирається на висоту й порушує його самоту, Файрґейз уже знає причину: прийшов воїн по ковану сталь."}},faq={{q="Хто посилає воїнів шукати Тун'ґріма Файрґейза?",a="Завдання дає Уззек — наставник воїнів, що стоїть при дорозі біля Далекої Дозорної Застави у східних Пустках, після того як ви покажете свою оборонну вправність.",al={"хто посилає воїнів","давець тун'ґріма файрґейза","хто дає завдання"}},{q="Де знайти Тун'ґріма Файрґейза?",a="Тун'ґрім живе у відлюдному таборі на вершині Тернистого Пагорба — високого кряжа просто на схід від Перехрестя в Пустках.",al={"місце тун'ґріма","де тун'ґрім","знайти файрґейза"}},{q="Чому Тун'ґрім живе в пагорбах сам?",a="Він присвятив життя суто ковальському ремеслу, подалі від міської метушні. Він працює біля свого ковадла на самоті на вершині Тернистого Пагорба, попри небезпечних звірів і шипогривів на довколишніх кряжах.",al={"чому тун'ґрім сам","тун'ґрім відлюдник"}},{q="Що сталося з очима Тун'ґріма Файрґейза?",a="Десятиліття невпинної роботи над розпеченим вугіллям і погляду просто в пекельний жар горна висушили й зіпсували йому зір.",al={"чи тун'ґрім сліпий","очі файрґейза"}},{q="Що далі після зустрічі з Тун'ґрімом Файрґейзом?",a="Коли ви доповідаєте Тун'ґрімові, він розуміє, що вам потрібна зброя, і дає завдання «Кована сталь» — зібрати сировину, щоб він міг викувати зброю.",al={"що після тун'ґріма","наступне завдання","продовження кованої сталі"}},{q="Чи може це завдання взяти будь-який клас?",a="Ні. Цей ланцюжок завдань задуманий саме як обряд посвяти для воїнів Орди, що шукають особливої зброї.",al={"чи будь-який клас","завдання воїна"}}},fp="18,344,23.514.0,24.488.0,46.169.0,36.117.0,47.206.0,43.140.0,44.162.0,30.111.0"}
P.entries["quest:1503"] = {n="Кована сталь",s="Оркський коваль Тун'ґрім Файрґейз потребує допомоги, щоб повернути вкрадений метал із сусіднього табору шипогривів. За повернення його цінних брусків кованої сталі він обіцяє викувати добру зброю для молодого воїна.",h="Оркський коваль Тун'ґрім Файрґейз потребує допомоги, щоб повернути вкрадений метал із сусіднього табору...",kw={"кована сталь","тун'ґрім файрґейз","гостромани","шипогриви","залізна скриня","воїн"},ang={["class:Warrior"]="Це завдання — важливий ранній обряд посвяти: воно вчить воїнів повертати вкрай потрібні військові припаси й доводити свою гідність, перш ніж отримати першу зброю, викувану на замовлення.",["faction:Horde"]="Плем'я Гостроманів постійно дошкуляє шляхам постачання й окремим таборам по всіх Пустках, тож відповідні рейди — необхідність, щоб убезпечити рубежі Орди.",["profession:Blacksmithing"]="Залежність Тун'ґріма від якісної кованої сталі показує невгамовний попит Орди на добрий метал на суворих, бідних на ресурси рубежах Калімдору."},sec={{t="Сліпа пляма",b="Тун'ґрім Файрґейз отаборився на суворих кряжах східних Пусток і живе як бронник і коваль далеко від гамірних кузень Оргріммара. Попри запальний дух, вік і суворі пустельні умови забрали в нього більшу частину зору. Помітивши цю слабкість, сусіди — шипогриви-Гостромани — під покровом темряви прокралися до його табору. Одні навмисно шуміли й рохкали з одного боку, щоб відвернути його затуманений погляд, а ватага злодіїв тим часом прослизнула з іншого й винесла залізну скриню з його запасом кованої сталі."},{t="Безцінний метал, безтямні злодії",b="Тун'ґріма розлютила зухвалість крадіжки, але він не надто боявся, що Гостромани справді знайдуть металу добре застосування. Ремесло шипогривів зазвичай тримається на грубому камені, нагострених іклах і колючому корінні, а не на складній металургії. Важка залізна скриня так і стояла ціла й неторкана в їхньому таборі біля поламаного воза — зовсім не потрібна шипогривам, але безцінна для оркського бронника, що чекав нагоди викувати бойове спорядження для молодих воїнів Орди."}},faq={{q="Хто такий Тун'ґрім Файрґейз?",a="Тун'ґрім Файрґейз — досвідчений орк-зброяр і коваль зброї, що живе в невеликому таборі у східних Пустках. Попри слабкий зір, він не кидає ремесла й допомагає навчати й озброювати молодих воїнів Орди.",al={"тун'ґрім файрґейз","хто коваль","тун'ґрім"}},{q="Чому шипогриви вкрали сталь?",a="Шипогриви Гостроманів — спритні падальники, що постійно грабують мандрівників і застави по всіх Пустках. Вони поцупили залізну скриню під час нічного відволікання просто щоб пограбувати безпорадного коваля, хоча й не мали ковальських знань, щоб працювати з кованою сталлю всередині.",al={"чому вкрали сталь","чому шипогриви вкрали","чого хотіли гостромани"}},{q="Де лежать бруски кованої сталі?",a="Сталеві бруски досі замкнені у Викраденій Залізній Скрині, покинутій біля зламаного воза на землях шипогривів Гостроманів на північний захід від табору Тун'ґріма.",al={"де скриня","місце вкраденої скрині","де бруски"}},{q="Яку зброю Тун'ґрім дає натомість?",a="За повернений запас доброї сталі Тун'ґрім пропонує молодим воїнам на вибір свіжовикувану зброю на допомогу в їхніх випробуваннях по всьому Калімдору.",al={"нагорода зброя","що отримаю","нагорода кованої сталі"}},{q="Як Гостромани примудрилися обдурити Тун'ґріма?",a="Шипогриви скористалися поганим зором Тун'ґріма. Кілька нападників трималися на відстані й гучно рохкали, щоб відвернути його увагу, а інші тим часом непомітно прокралися в табір і потягли скриню.",al={"як гостромани обдурили тун'ґріма","як його пограбували","відволікання тун'ґріма"}},{q="Чому Тун'ґрім живе в Пустках, а не в Оргріммарі?",a="Тун'ґрім тримає відлюдну заставу на посушливих пагорбах над торговими шляхами, де служить зброярем і наставником для воїнів, що вирушають із Дуротару на ширше випробувальне поле Пусток.",al={"чому тун'ґрім у пустках","чому табір у пустках"}}},fp="12,227,22.580.0,33.492.0,26.217.0,37.296.0,37.157.0,43.160.0,49.222.0,64.208.0"}
P.entries["quest:1504"] = {n="Зв'язування",s="Зв'язування — останній обряд посвяти в Оргріммарі для молодих чорнокнижників Орди, що прагнуть влади над блукачем Порожнечі. Під наглядом Ґан'рула Бладая прохач викладає гліфи зі Скрижалі Верги в колі прикликання Ніру Файрблейда, щоб прикликати, скорити й навіки поневолити істоту Порожнечі.",h="Зв'язування — останній обряд посвяти в Оргріммарі для молодих чорнокнижників Орди, що прагнуть влади над...",kw={"зв'язування","блукач порожнечі","скрижаль верги","ґан'рул бладай","ніру файрблейд","чорнокнижник"},ang={["class:Warlock"]="Цей обряд знаменує піднесення чорнокнижника від забав із дрібними бісами до влади над тіньовими жахіттями передової й утверджує безжальну філософію: силу треба завоювати й поневолити.",["faction:Horde"]="Хоч Орда Тралла офіційно відвернулася від демонічної скверни минулого, з практичної потреби магію чорнокнижників терплять під Оргріммаром — під пильним наглядом.",["race:Orc"]="Оркські чорнокнижники діють у прихованих закутках, як-от у Тіньовій Розколині, практикуючи темні мистецтва подалі від несхвального погляду Вождя Тралла й шаманського відродження."},sec={{t="Підкорення Порожнечі",b="Для чорнокнижника-початківця, що ховається в темних тунелях Тіньової Розколини, прикликати біса — дитяча забавка. Скорити блукача Порожнечі — перше справжнє випробування волі й магічної переваги. Чорнокнижники не укладають чемних угод і не ведуть бесід із цими потойбічними жахіттями: вони силоміць виривають їх крізь виміри й прив'язують до вічної служби. Ґан'рул Бладай вимагає, щоб посвячений скористався гліфами, переписаними зі Скрижалі Верги, прикликав страховисько просто в ритуальне коло Ніру Файрблейда й зламав його в поєдинку."},{t="Невсипуща пильність",b="Здолати сутність у тілесному й магічному бою — лише половина справи. Як застерігає Ґан'рул Бладай, прив'язаний блукач Порожнечі ніколи по-справжньому не змиряється з неволею. Хоч він і служить господареві міцним тіньовим заслоном у бою, він повсякчас вичікує, коли той утратить зосередженість. Чорнокнижник мусить невпинно тримати слугу в непохитних лещатах волі, бо щойно дисципліна похитнеться, блукач Порожнечі радо пожере душу того, хто його прив'язав."}},faq={{q="Яку істоту закликають?",a="Посвячуваний закликає блукача Порожнечі — височенну істоту з чистої космічної тіні й енергії Порожнечі. На відміну від бісів, пустотливих демонів, блукачі Порожнечі — грубі сутності, вирвані з Викривленого Нижнього Світу й Порожнечі, і чорнокнижники використовують їх передусім для того, щоб ті приймали на себе нищівні удари.",al={"яку істоту закликають","який демон","лор блукача порожнечі"}},{q="Де відбувається обряд закликання?",a="Обряд проводять у наметі Ніру Файрблейда в Тіньовій Розколині під Оргріммаром. Спеціальне коло закликання, накреслене на землі, зосереджує сили вимірів, потрібні, щоб вирвати блукача Порожнечі з Нижнього Світу.",al={"де закликання","місце кола закликання","місце ритуалу"}},{q="Для чого потрібна Скрижаль Верги?",a="На Скрижалі Верги — давні особливі гліфи, потрібні, щоб явити блукача Порожнечі й протягнути його крізь тканину реальності. Посвячуваний вивчає її написи, щоб створити Гліфи Прикликання для кола закликання.",al={"навіщо скрижаль верги","гліфи закликання"}},{q="Чому чорнокнижник мусить перемогти блукача Порожнечі?",a="Чорнокнижники керують істотами з інших планів буття самою лише владою. Перш ніж блукач Порожнечі віддасть свою суть і коритиметься наказам, закликач мусить довести свою майстерність, фізично й магічно збивши істоту до покори.",al={"чому вбивати блукача","навіщо битися","процес зв'язування"}},{q="Хто такий Ґан'рул Бладай?",a="Gan'rul Bloodeye is a senior warlock trainer of the Horde stationed in the shadowy caverns of Orgrimmar's Cleft of Shadows. He oversees the dark education of young Horde practitioners, teaching them how to enslave more potent demonic entities.",al={"ґан'рул бладай","хто такий ґан'рул"}},{q="Чи можна будь-коли цілком довіряти прив'язаному блукачеві Порожнечі?",a="Ніколи. Як зауважує Ґан'рул, навіть блукач Порожнечі, що роками служив без опору, лише чекає, коли господар утратить пильність. Цей зв'язок вимагає постійної насторожі, бо істота вічно таїть образу на свого поневолювача.",al={"чи можна довіряти блукачеві","чи блукач зрадить","чи демони бунтують"}}},fp="11,326,23.565.0,17.457.0,40.290.0,44.250.0,37.244.0,43.227.0,24.243.0,45.244.0"}
P.entries["quest:1506"] = {n="Ґан'рул кличе",s="Ґан'рул кличе — нагальний виклик, який Офек у Гострому Пагорбі передає молодим чорнокнижникам Орди. Старший чорнокнижник Ґан'рул Бладай чекає їх негайно в Тіньовій Розколині, щоб продовжити навчання. Це перший крок до опанування темного мистецтва прикликання блукача Порожнечі.",h="Ґан'рул кличе — нагальний виклик, який Офек у Гострому Пагорбі передає молодим чорнокнижникам Орди.",kw={"ґан'рул кличе","офек","ґан'рул бладай","тіньова розколина","блукач порожнечі","чорнокнижник"},ang={["class:Warlock"]="Цей виклик знаменує, що ви переросли просте прикликання бісів, і відкриває вам шлях до міцного захисту блукача Порожнечі.",["faction:Horde"]="Чорнокнижники займають у новій Орді Тралла непевне місце: їх терплять заради практичної сили, але тримають глибоко під Оргріммаром."},sec={{t="Виклик у тінь",b="Чорнокнижники-початківці, що діють у Дуротарі, недовго лишаються непоміченими. Щойно адепт доведе, що опанував свого першого біса, звістка сягає глибоких підземних закутків Оргріммара. Офек, що стоїть у Дуротарі, служить гінцем для старших темних заклиначів: він перестріває чорнокнижників із нагальною вимогою покинути всі справи й з'явитися до Тіньової Розколини."},{t="Старший чорнокнижник",b="Ґан'рул Бладай опікується вишколом молодих оркських чорнокнижників в Орді. Діючи з прихованих печер під Оргріммаром, він тримає хистку рівновагу: відточує смертоносну силу Скверни й водночас ховає ці небезпечні мистецтва від несхвального погляду Вождя. Коли Бладай кличе учня до свого кола, це знак, що простих вогняних заклять і бісів уже замало — час прив'язати істоту з Викривленого Нижнього Світу."}},faq={{q="Хто такий Офек?",a="Офек — соратник чорнокнижників, що перебуває в Дуротарі. Він стежить за багатонадійними чаклунами й передає накази від старших наставників на кшталт Ґан'рула Бладая.",al={"хто такий офек","давець завдання","початок завдання"}},{q="Де знайти Ґан'рула Бладая?",a="Ґан'рул Бладай живе в Тіньовій Розколині — темній підземній системі печер, схованій під скелястими плато Оргріммара.",al={"де ґан'рул","місце ґан'рула","знайти ґан'рула бладая"}},{q="Чому Ґан'рул Бладай хоче мене бачити?",a="Ґан'рул вирішив, що ви досить досвідчені, щоб продовжити навчання чорнокнижника й узятися за небезпечні обряди, потрібні, щоб закликати й прив'язати блукача Порожнечі.",al={"чому ґан'рул кличе","чого хоче ґан'рул","причина завдання"}},{q="Що буде, коли доповіси Ґан'рулу?",a="Доповідь Ґан'рулу починає завдання «Створіння Порожнечі», яке посилає вас по складники й знання, потрібні, щоб протягнути сутність Порожнечі в Азерот.",al={"що після ґан'рула","наступне завдання"}},{q="Чому чорнокнижники тримаються Тіньової Розколини?",a="Чорнокнижники практикують мінливу магію скверни, на яку Тралл і традиційна шаманська Орда дивляться з глибокою підозрою. Тіньова Розколина дає їм змогу проводити обряди подалі від людських очей.",al={"чому тіньова розколина","чому чорнокнижники ховаються","печера чорнокнижників оргріммар"}},{q="Чи може це завдання взяти будь-який клас?",a="Ні. Це завдання пропонують лише чорнокнижникам Орди, які досягли десятого кола навчання.",al={"чи будь-який клас","лише чорнокнижник"}}},fp="17,290,24.399.0,18.455.0,13.157.0,34.132.0,41.147.0,40.163.0,48.182.0,30.108.0"}
P.entries["quest:1507"] = {n="Пожирач Душ",s="Пожирач Душ — перше доручення на шляху чорнокнижника Орди до того, щоб прикликати сукуба й повелівати ним. Його дає Ґан'рул Бладай у глибинах Тіньової Розколини: завдання посилає адепта через усю печеру порадитися зі старезним чорнокнижником Казулом, як виманити й прив'язати такого підступного демона.",h="Пожирач Душ — перше доручення на шляху чорнокнижника Орди до того, щоб прикликати сукуба й повелівати ним.",kw={"пожирач душ","сукуб","казул","ґан'рул бладай","тіньова розколина","чорнокнижник"},ang={["class:Warlock"]="Це завдання знаменує ваш перехід до влади над демонами розумового панування й спокуси: тут потрібна не лише сира сила Скверни, а й душевна стійкість.",["faction:Horde"]="На відміну від шаманів і воїнів Орди Тралла, що діють відкрито, чорнокнижники мусять провадити ці небезпечні обряди потай, у вогких відлюдних щілинах Тіньової Розколини."},sec={{t="Крок у спокусливі тіні",b="Чорнокнижники Орди, що опанували нижчих демонів — біса й блукача Порожнечі, — згодом доходять до межі, де грубої сили вже замало. Ґан'рул Бладай, наглядач темних мистецтв під Оргріммаром, вирішує, коли чорнокнижник готовий сягнути у Викривлений Нижній Світ по сукуба — створіння, що славиться вмінням обертати розум слабких проти них самих. Щоб прив'язати таку потвору, потрібні тонкі методи, а не сама лише сила."},{t="Знання Казула",b="Сукуб живиться бажаннями смертних, тож його не прикликати самими лише закляттями: його треба заманити в наш світ річчю, просякнутою чистою любов'ю й відданістю. Не бажаючи чи не маючи змоги сам дати таку реліквію, Ґан'рул посилає заклинача до Казула — старезного чорнокнижника, що ховається в Тіньовій Розколині й чиї глибокі знання арканних і демонічних обрядів підкажуть наступний крок ритуалу."}},faq={{q="Яка мета цього завдання?",a="«Пожирач Душ» починає ланцюжок завдань Орди, потрібний, щоб вивчити обряд закликання сукуба-прислужника. Він зводить вас із наставниками в Тіньовій Розколині, які розповідають про природу цього демона й про те, як виманити його з Викривленого Нижнього Світу.",al={"мета завдання","навіщо пожирач душ","початок сукуби"}},{q="Де знайти Казула?",a="Казул у Тіньовій Розколині — підземній печері під Оргріммаром, де наставники розбійників і чорнокнижників міста практикують свої заборонені мистецтва подалі від очей Вождя.",al={"де казул","місце казула","знайти казула в оргріммарі"}},{q="Навіщо чорнокнижникові символ кохання, щоб закликати сукуба?",a="Сукуби — демонічні маніпулятори, що живляться почуттями, відданістю й слабкою волею смертних. Щоб виманити сукуба крізь завісу Викривленого Нижнього Світу, закликач мусить запропонувати як приманку сильний талісман справжньої відданості й прихильності, а тоді здолати й прив'язати істоту.",al={"навіщо символ кохання","приманка кохання для сукуби","лор закликання сукуби"}},{q="Хто такий Ґан'рул Бладай?",a="Ґан'рул Бладай — старший наставник чорнокнижників Орди в Тіньовій Розколині в Оргріммарі. Він веде молодих чаклунів крізь небезпечні прив'язування дедалі могутніших демонічних слуг.",al={"хто дає пожирача душ","ґан'рул","ґан'рул бладай"}},{q="Який рівень потрібен, щоб почати це завдання?",a="Чорнокнижник має досягти 20-го рівня, перш ніж Ґан'рул Бладай визнає його магічну вправність і силу духу достатніми, щоб узятися за обряд і вижити в торзі з сукубом.",al={"який рівень","рівень пожирача душ","рівень ланцюжка сукуби"}},{q="Що далі після розмови з Казулом?",a="Розмова з Казулом веде до завдання «Сліпий Казул», яке посилає закликача до Занкаджі в Оргріммарі, чий чоловік Доґран не повернувся зі служби на Перехресті. Саме з неї починаються пошуки придатного символу кохання.",al={"що після казула","наступне завдання","прогрес ланцюжка сукуби"}}},fp="17,310,29.439.0,17.417.0,34.243.0,22.207.0,63.268.0,24.207.0,43.181.0,39.224.1"}
P.entries["quest:1508"] = {n="Сліпий Казул",s="Сліпий Казул — перехідний крок у випробуванні чорнокнижника Орди, що прагне прив'язати сукуба. За порадою провідників ковену в Тіньовій Розколині посвячений шукає незрячого чорнокнижника Казула, а той вказує на річ, сповнену сильних почуттів, без якої ритуал неможливий.",h="Сліпий Казул — перехідний крок у випробуванні чорнокнижника Орди, що прагне прив'язати сукуба.",kw={"сліпий казул","казул","сукуб","занкаджа","тіньова розколина","чорнокнижник"},ang={["class:Warlock"]="Це завдання показує, що демонічне прикликання тримається на душевному відгуку не менше, ніж на магії Скверни: щоб виманити сукуба, потрібні провідники сильних смертних почуттів.",["faction:Horde"]="Темні мистецтва, яких навчають у глибинах Тіньової Розколини, діють просто під поверхнею столиці Орди й тихо торкаються життя звичайних городян, що живуть на столових горах над нею."},sec={{t="Питання принади",b="Щоб скорити демонічного слугу, мало самої сили волі: деяких істот Викривленого Нижнього Світу треба виманити крізь завісу їхніми ж уродженими жаданнями. Сукуб, якого називають пожирачем душ, жадібно відгукується на смертну тугу, скорботу й нездійснені бажання. Казул добре це розуміє й одразу збагне, навіщо до нього прийшов заклинач-початківець."},{t="Очі на кручах",b="Попри тілесну сліпоту, Казул чутко вловлює тихе життя й трагедії, що розгортаються за червоними валами Оргріммара. Замість одразу посилати чорнокнижника в бій, він скеровує його до орчихи на ім'я Занкаджа, що живе на кручі біля сідала вітрокрилів. Занкаджа з тривогою чекає повернення свого коханого, Доґрана, і плекає саме той розпач, перед яким не встоїть жоден демон."}},faq={{q="Хто такий Казул?",a="Казул — незрячий чорнокнижник, що тихо діє в Оргріммарі. Він допомагає чорнокнижникам Тіньової Розколини, визначаючи реагенти й провідники для демонічних закликань.",al={"сліпий казул","хто такий казул"}},{q="Чому Казул посилає вас до Занкаджі?",a="Щоб закликати й прив'язати сукуба, посвячуваному потрібна річ, просякнута сильною смертною тугою чи коханням. Занкаджа в тривозі чекає на свого зниклого чоловіка Доґрана, тож її особисті почуття — ключ до того, щоб здобути таку чуттєву приманку.",al={"чому до занкаджі","що в занкаджі"}},{q="Де в Оргріммарі знайти Занкаджу?",a="Занкаджа живе на високих кручах Оргріммара, на захід від гнізда вітрокрилів. До неї можна дістатися, перейшовши міст від льотної вежі й заглянувши в сусідні оселі праворуч.",al={"місце занкаджі","де занкаджа"}},{q="Що буде після розмови із Занкаджею?",a="Занкаджа стривожена, бо її чоловік Доґран зник. Розмова з нею веде чорнокнижника в Пустки шукати звісток про його долю — так починається ланцюжок, що веде до сильного символу кохання.",al={"що після занкаджі","продовження"}},{q="Якого демона це завдання готує вас закликати?",a="Це доручення — частина обряду посвяти, щоб закликати й поневолити сукуба, демонічного прислужника, що володіє спокусою й психічними муками.",al={"який демон","який улюбленець"}},{q="Чому чорнокнижники мусять використовувати чужі трагедії для своїх обрядів?",a="Менших демонів на кшталт сукуба вабить сила смертних почуттів — особливо пристрасть, відданість і розбите серце. Чорнокнижники навмисно беруть символи, просякнуті горем чи бажанням, як духовну приманку для обряду закликання.",al={"мораль чорнокнижників","навіщо використовувати доґрана"}}},fp="11,268,22.367.0,18.414.0,13.171.0,35.236.0,40.194.0,39.193.0,57.136.0,63.238.0"}
P.entries["quest:1509"] = {n="Вісті про Доґрана",s="Це завдання веде чорнокнижників Орди з ущелин Оргріммара в посушливі простори Пусток на пошуки зниклого піхотинця на ім'я Доґран. Його кохана, Занкаджа, після днів мовчання боїться найгіршого й посилає адепта розпитати командира Доґрана на Перехресті. З'ясувати долю Доґрана — важливий крок ритуалу чорнокнижника, що прагне прив'язати сукуба.",h="Це завдання веде чорнокнижників Орди з ущелин Оргріммара в посушливі простори Пусток на пошуки зниклого...",kw={"вісті про доґрана","доґран","занкаджа","ґазроґ","перехрестя","сукуб"},ang={["class:Warlock"]="Цей відрізок шляху переносить ваше навчання від темних текстів в Оргріммарі до справжнього використання смертної трагедії, щоб здобути сукуба.",["faction:Horde"]="Це доручення показує, якій постійній небезпеці піддаються піхотинці Орди, що намагаються вберегти небезпечні перехрестя Калімдору від ворожих місцевих загроз.",["race:Orc"]="Тихе горе Занкаджі відкриває особисту ціну, яку платять за розширення й оборону Орди в Дуротарі та Пустках."},sec={{t="Розпач коханої",b="На кручах Оргріммара Занкаджа чекає в тихому страху. Її коханого Доґрана з почесним підвищенням відрядили на Перехрестя, але строк його повернення давно минув, а від нього — ані слова. Не знаючи про темні мистецтва, що смикають за ниточки за лаштунками, вона просить співчутливого мандрівника дізнатися правду в його командира, Ґазроґа."},{t="Похмурі вісті з Пусток",b="На центральній заставі Перехрестя правда стає похмурою. Доґран не просто затримався на службі — він потрапив до рук лютих шипогривів, що кишать на рівнинах. Ґазроґ визнає: Доґран ще живий, але його полон — жорстока дійсність, про яку він вагається повідомити Занкаджі."},{t="Знаряддя прикликання",b="Для чорнокнижника-початківця трагедія Доґрана — не просто рятувальна місія. Шлях до прикликання й підкорення сукуба — створіння, що живиться сирою пристрастю, розпачем і мукою, — вимагає реліквій, яких торкнулися справжні почуття. Страждання Доґрана і його зв'язок із Занкаджею — саме той емоційний провідник, якого потребує ритуал зв'язування."}},faq={{q="Хто такий Доґран?",a="Доґран — орк-піхотинець у Пустках, якого нещодавно підвищили й призначили на Перехрестя. А ще він чоловік Занкаджі, орчихи, що живе в Оргріммарі.",al={"лор доґрана","хто такий доґран","піхотинець доґран"}},{q="Чому чорнокнижника обходить зниклий орк-вартовий?",a="Наставники-чорнокнижники в Тіньовій Розколині влаштовують ці пошуки, бо обряд прив'язування сукуба вимагає символів, просякнутих глибокими смертними почуттями — коханням, відданістю й стражданням.",al={"чому чорнокнижники","навіщо чорнокнижникам це","зв'язок із сукубою"}},{q="Де знайти Ґазроґа?",a="Ґазроґ на Перехресті в Пустках — один із головних провідників Орди, що керує обороною від місцевих загроз.",al={"місце ґазроґа","де ґазроґ","ґазроґ перехрестя"}},{q="Що сталося з Доґраном?",a="Доґран досі не повернувся до Занкаджі. Вона просить вас розпитати про нього Ґазроґа на Перехресті.",al={"чи доґран мертвий","де доґран","доля доґрана"}},{q="Хто дає це завдання?",a="Завдання дає Занкаджа на кручах Оргріммара, після того як до неї вас спрямував наставник чорнокнижників Казул.",al={"хто дає завдання","початок вістей про доґрана"}},{q="Що далі в ланцюжку?",a="Розпитуйте далі в Пустках, щоб дізнатися долю Доґрана й донести звістку далі.",al={"що далі","наступне завдання","продовження сукуби"}}},fp="14,360,16.351.0,27.315.1,26.330.1,14.164.0,50.192.0,24.141.0,24.96.1,21.115.0,29.88.1"}
P.entries["quest:151"] = {n="Бідолашна стара Бланчі",s="«Бідолашна стара Бланчі» — завдання від Верни Фурлброу на головному шляху Вестфолу. Під час спроби втечі віз Фурлброу зламався, і їхня стара кобила тепер виснажена й голодна. Шукачів пригод просять назбирати мішки вівса, розкидані покинутими фермами довкола, щоб нагодувати змучену тварину.",h="«Бідолашна стара Бланчі» — завдання від Верни Фурлброу на головному шляху Вестфолу.",kw={"бідолашна стара бланчі","стара білявка","верна фурлброу","фермер фурлброу","овес","вестфол"},ang={["class:Hunter"]="Турбота про знесилену тяглову тварину підкреслює зв'язок між трудовим людом і звірами, що вірно несуть їхній тягар.",["faction:Alliance"]="Застряглі в дорозі Фурлброу показують, як відчайдушно занедбані люди в сільських землях королівства, поки столиця скута політичним застоєм."},sec={{t="Родина посеред дороги",b="Мандруючи курним трактом Вестфолу, подорожні натрапляють на Верну й Фермера Фурлброу, що застрягли край дороги. Як і багато робітничих родин краю, Фурлброу втратили дім через нестримний розбій і здичавілих механічних жнивних големів. Вони намагалися вивезти своє нехитре майно в безпечне місце, але віз безнадійно зламався, і подружжя опинилося серед відкритого поля."},{t="Розрада для вірної кобили",b="У самому осередку їхньої біди — Стара Білявка, шанована робоча кобила, що довгі роки орала й возила для родини. Виснажена тим, що тягла перевантажений віз, і голодна через несподівану затримку, лагідна конячка швидко згасає. Верна благає перехожих прокрастися на сусідні захоплені ферми й пошукати вцілілі мішки зерна — наражаючись на ворожі молотарки й падальників-гнолів, аби лиш дати вірній тварині пристойно поїсти."}},faq={{q="Хто така Стара Білявка?",a="Стара Білявка — улюблена стара робоча кобила родини Фурлброу. Роками тягала вона їхні плуги й вози по всьому Вестфолу, а тепер виснажена й застрягла на узбіччі, після того як у їхнього воза зламалася вісь.",al={"стара білявка","хто така бланчі","лор бланчі"}},{q="Чому зламався віз Фурлброу?",a="Фурлброу намагалися втекти зі своєї ферми з усім добром, коли віз не витримав ваги. Вони застрягли при дорозі, беззахисні перед бандитами й хижими звірами.",al={"чому зламався віз","віз фурлброу","зламаний віз"}},{q="Звідки береться овес?",a="Мішки вівса досі розкидані по полях і господарських будівлях захоплених ферм Вестфолу — їх лишили селяни, що тікали від збунтованих жнивних машин і бандитів.",al={"де овес","знайти овес","мішки вівса"}},{q="Які загрози стережуть зерно на полях?",a="На полях на південний захід від дороги лютують збунтовані механічні Стражі Врожаю й бродячі ватаги гнолів Річколапів, що нишпорять покинутими коморами.",al={"хто стереже зерно","напади на ферми","небезпеки ферм"}},{q="Чому родина не відвела Стару Білявку в безпечне місце?",a="Стара Білявка геть знесилена й голодна, без харчу вона не здатна ні тягти, ні йти далеко, а Фурлброу не хочуть кидати ні свою вірну кобилу, ні своє добро.",al={"чому не відвели білявку","кінь іде пішки","чому не в сентінел гілл"}},{q="Чи Стормвінд допомагає фермерам на кшталт Фурлброу?",a="Королівський двір Стормвінда майже не дає селянам Вестфолу ні захисту, ні допомоги. Сільські мешканці здебільшого мусять дбати про себе самі або покладатися на знесилене Народне ополчення.",al={"чи стормвінд допомагає","допомога вестфолу","де вартові"}}},fp="16,322,20.393.0,27.460.0,19.210.0,38.200.0,28.167.0,43.163.0,50.179.0,54.190.0"}
P.entries["quest:1510"] = {n="Вісті про Доґрана",s="Це завдання відсилає шукачів пригод з Орди глибоко в передгір'я Гір Кам'яного Кігтя — розшукати троля з племені Темного Спису Кен'зіґлу в Малака'джині. Піхотинець із Табору Тауражо на ім'я Доґран лежить поранений, а перший гонець, якого послали по рятівний трав'яний трунок, так і не повернувся.",h="Це завдання відсилає шукачів пригод з Орди глибоко в передгір'я Гір Кам'яного Кігтя — розшукати троля з...",kw={"доґран","кен'зіґла","малака'джин","табір тауражо","сукуб","чорнокнижник"},ang={["class:Warlock"]="Те, що здається звичайною військовою місією милосердя, насправді — вирішальне випробування від Казула й чорнокнижників Оргріммара: воно веде вас до того душевного відгуку, без якого не підкорити сукуба.",["faction:Horde"]="Цей відтинок шляху показує, які тонкі й крихкі ланцюжки постачання пов'язують віддалені форпости на кшталт Табору Тауражо з відрізаними таборами, як-от Малака'джин, коли довкола ворожі шипогриви й гобліни."},sec={{t="Благання з прикордоння",b="Доґрана, піхотинця Орди з Табору Тауражо на півдні Пусток, тяжко поранили в сутичці з шипогривами, що окопалися неподалік. Товаришам вдалося вберегти його там, де він упав, але рани гноїлися, і будь-яке грубе перевезення через рівнини його вбило б. У відчайдушних пошуках сильних ліків із Тауражо послали звістку на північ, до Гір Кам'яного Кігтя, сподіваючись роздобути традиційний цілющий трунок, який готують джунглеві тролі Малака'джина."},{t="Кров у Малака'джині",b="Діставшись круч Малака'джина, мандрівники дізнаються, що рятувальна місія провалилася майже одразу. Першого гінця, посланого по ліки, підстерегли й убили місцеві гобліни Венчурної Компанії, перш ніж він устиг отримати трунок. Кен'зіґла досі має засіб, потрібний Доґранові, але щоб його здобути, доведеться впоратися з мінливими небезпеками прикордоння біля перевалів Гір Кам'яного Кігтя."}},faq={{q="Хто такий Доґран і чому він поранений?",a="Доґран — орк-піхотинець із Табору Тауражо. Коли він вів загін, щоб розчистити агресивні табори шипогривів на півдні Пусток, то дістав жорстокі гнійні рани, і перевозити його без негайного лікування стало неможливо.",al={"хто такий доґран","чому доґран поранений","історія доґрана"}},{q="Де розташований Малака'джин?",a="Малака'джин — невелика застава тролів Темного Списа біля скелястого підніжжя Гір Кам'яного Кігтя, одразу за північно-західним кордоном Пусток.",al={"місце малака'джина","де малака'джин","знайти кен'зіґлу"}},{q="Що сталося з першим гінцем, посланим по трунок?",a="Першого гінця, посланого з Тауражо по трунок Кен'зіґли, підстерегли й убили гобліни Венчурної Компанії, що орудують при дорозі біля передгір'їв Кам'яного Кігтя.",al={"що сталося з першим гінцем","перший гонець","мертвий кур'єр"}},{q="Чому наставників-чорнокнижників цікавить доля Доґрана?",a="Посвячуваних чорнокнижників спрямовують до біди Доґрана під приводом доручення від Сліпого Казула й Ґазроґа, але зрештою ця історія веде їх до артефакту, просякнутого коханням і розбитим серцем, що потрібен, щоб закликати й прив'язати сукуба.",al={"чому чорнокнижників цікавить доґран","зв'язок із завданням чорнокнижника","сукуба доґран"}},{q="Хто такий Кен'зіґла?",a="Кен'зіґла — троль-алхімік і травник із Темного Списа, що живе в поселенні Малака'джин у Горах Кам'яного Кігтя й знається на тому, як варити сильні трунки з дикої природи.",al={"кен'зіґла","хто такий кен'зіґла","кен'зіґла стоунталон"}},{q="Чому Доґрана не можна було просто перевезти до міста?",a="Після бою з шипогривами рани Доґрана тяжко загноїлися. Його бойові товариші боялися, що він помре, перш ніж його довезуть розбитими дорогами Пусток до справжнього цілителя.",al={"чому не перевезти доґрана","рани доґрана","чому табір таурахо залишив"}}},fp="14,283,26.445.0,23.407.1,33.256.0,28.150.0,58.181.0,49.233.1,17.160.0,49.213.0"}
P.entries["quest:1511"] = {n="Трунок Кен'зіґли",s="«Трунок Кен'зіґли» — нагальне завдання гінця в ланцюжку чорнокнижників Орди, що веде до виклику сукуба. Отримавши в Малака'джині, що в Горах Кам'яного Кігтя, сильний цілющий відвар, чорнокнижник мусить мчати через Калімдор до Табору Тауражо, щоб урятувати бійця на ім'я Доґран.",h="«Трунок Кен'зіґли» — нагальне завдання гінця в ланцюжку чорнокнижників Орди, що веде до виклику сукуба.",kw={"трунок кен'зіґли","доґран","табір тауражо","піхотинець лоґмар","сукуб","чорнокнижник"},ang={["class:Warlock"]="Цей відтинок вашого шляху — випробування терпіння й винахідливості: щоб повелівати істотою чистого бажання й спокуси, спершу треба вилікувати скаліченого смертного, у якого зберігається знак підкорення.",["faction:Horde"]="Тут видно, як розтягнуто сили молодої Орди по центральному Калімдору: відрізані форпости в Горах Кам'яного Кігтя й Пустках покладаються на мандрівників, щоб підтримувати життєво важливий зв'язок і доставляти ліки."},sec={{t="Рятівне вариво",b="Серед круч Гір Кам'яного Кігтя троль-аптекар Кен'зіґла передчував біду. Знаючи, що попередній посланець, якого відрядили по ліки для зниклого розвідника Доґрана, так і не повернувся, Кен'зіґла приготував другу порцію свого сильного відновлювального трунку. Вариво мінливе й потужне: половина дози дає смертельно пораненому воякові сили рушити з місця так, щоб рани не відкрилися кровотечею, а решту треба приберегти до наступного дня, щоб довершити одужання."},{t="Зустріч у Таборі Тауражо",b="Винісши трунок із гір на південь Пусток, чорнокнижник має розшукати Піхотинця Лоґмара в Таборі Тауражо. Лоґмар знає, де саме Доґран, але його гарнізон спорожнів: майже всі пішли в рейди по припаси. Доґран у пастці, стікає кров'ю на ворожій землі, тож доставка трунку до Тауражо — останні приготування перед рятувальною операцією."}},faq={{q="Для чого потрібен Трунок Кен'зіґли?",a="Це сильне лікувальне вариво, яке Кен'зіґла приготував, щоб поставити на ноги пораненого орка-агента Доґрана. Його п'ють за два рази: перша половина дає пораненому бійцеві досить сил, щоб рухатися, не роз'ятривши смертельних ран, а друга завершує зцілення.",al={"для чого трунок","призначення трунку кен'зіґли","навіщо варити трунок"}},{q="Хто такий Кен'зіґла?",a="Кен'зіґла — троль-аптекар у Горах Кам'яного Кігтя. Він постачає особливі алхімічні суміші й варива агентам Орди, що діють у краї.",al={"кен'зіґла","хто такий кен'зіґла"}},{q="Чому Піхотинець Лоґмар чекає в Таборі Тауражо?",a="Піхотинець Лоґмар служить у Таборі Тауражо на півдні Пусток. Він стежить за пересуванням місцевих розвідників і має останні відомості про те, де зник Доґран, але йому бракує вояків, щоб самому влаштувати порятунок.",al={"хто такий лоґмар","лоґмар таурахо","піхотинець лоґмар"}},{q="Як це завдання пов'язане із закликанням сукуба?",a="Щоб закликати й прив'язати сукуба, чорнокнижникам Орди в Оргріммарі потрібен амулет Доґрана — артефакт, просякнутий пристрастю й відданістю. Щоб здобути амулет, треба знайти Доґрана й урятувати йому життя трунком Кен'зіґли.",al={"чому сукуба","трунок і сукуба"}},{q="Чому перший гонець не доніс трунок?",a="Перший посланець, відряджений у Гори Кам'яного Кігтя, так і не виконав доручення, тож Кен'зіґла приготував запасну порцію для наступного шукача пригод, що йде слідами Доґрана.",al={"що сталося з гінцем","перший гонець"}},{q="Куди веде слід після Табору Тауражо?",a="Отримавши трунок, Піхотинець Лоґмар вказує чорнокнижникові на тих, хто захопив Доґрана на півдні Пусток, де розвідника, що помирає, тримають у полоні.",al={"де доґран","наступний крок після лоґмара"}}},fp="19,273,18.489.0,26.399.1,40.261.0,17.170.0,44.218.0,52.223.0,47.167.0,43.147.1"}
P.entries["quest:1512"] = {n="Дар кохання",s="Дар кохання — передостаннє завдання ланцюжка, у якому чорнокнижник Орди прикликає й прив'язує сукуба. Знайдений і приведений до тями в Пустках, умирущий Піхотинець Доґран віддає дорогу серцю пам'ятку, що стане приманкою для темного ритуалу.",h="Дар кохання — передостаннє завдання ланцюжка, у якому чорнокнижник Орди прикликає й прив'язує сукуба.",kw={"дар кохання","піхотинець доґран","занкаджа","амулет","кен'зіґла","сукуб"},ang={["class:Warlock"]="Зв'язування сукуба вчить чорнокнижників, що демонів не лише прикликають арканною силою — їх ловлять, граючи на їхньому голоді до сирих смертних пристрастей, як-от любов і горе.",["faction:Horde"]="Піхотинець Доґран утілює суворий бойовий дух Орди: краще загинути на полі бою, ніж жити калікою-тягарем для рідних."},sec={{t="Жертва піхотинця",b="Піхотинця Доґрана знаходять закатованим у полоні шипогривів племені Щетиноспинів у Пустках, і до тями його повертає настій Кен'зіґли. Знаючи, що його тіло покалічене безповоротно, Доґран вирішує зустріти смерть у славному бою, а не повертатися до своєї коханої, Занкаджі, калікою. Він віддає обліплений брудом амулет — дарунок, народжений чистою любов'ю, — і просить лише про одне: щоб вона ніколи не дізналася, від чого він відмовився."},{t="Приманка для демона",b="Щоб прикликати й скорити сукуба, чорнокнижникові потрібен талісман, сповнений сильних, незаплямованих почуттів. Сукуби живляться смертним бажанням і обертають щиру прихильність на муку. Амулет Доґрана несе вагу справжньої відданості й трагічної розлуки. Повернутий Ґан'рулові Бладаю в тінисті ущелини Оргріммара, талісман очищають і полірують, щоб його сяйливий емоційний відгомін виманив пожирача душ крізь Викривлений Нижній Світ."}},faq={{q="Навіщо чорнокнижникові амулет Доґрана?",a="Сукубів вабить глибока смертна пристрасть, яку вони спотворюють і пожирають. Амулет Доґрана уособлює самовіддане кохання й щиру жертву, тож це ідеальна містична приманка, щоб звабити сукуба в коло закликача.",al={"навіщо амулет","приманка сукуби","брудний кулон"}},{q="Хто такий Піхотинець Доґран?",a="Доґран — воїн Орди, якого захопили й жорстоко катували шипогриви Щетиноспинів на півдні Пусток. Хоча його врятували й підняли на ноги алхімічним тоніком, тяжкі каліцтва не дають йому жити як гордому воїнові.",al={"хто такий доґран","піхотинець доґран"}},{q="Хто така Занкаджа?",a="Занкаджа — молода дружина Доґрана, що з тривогою чекала звісток про нього. Щоб позбавити її горя й тягаря догляду за зламаною людиною, Доґран вирішує віддати її подарунок і шукати смерті воїна.",al={"хто така занкаджа","занкаджа лор"}},{q="Чому Доґран просить приховати це від Занкаджі?",a="Доґран не хоче прикувати молоду дружину до каліки, що помирає. Він віддає її амулет, знаючи, що той ніколи до неї не повернеться, але благає вберегти її від провини знати, яка доля його спіткала.",al={"чому не казати занкаджі","таємниця доґрана"}},{q="Хто чистить амулет і навіщо?",a="Амулет бере Ґан'рул Бладай, наставник чорнокнижників в Оргріммарі. Він очищує його від бруду й кіптяви, щоб яскравий, бездоганний вигляд і чуттєвий відгомін амулета стали непереборними для закликаного демона.",al={"роль ґан'рула","навіщо чистити амулет"}},{q="Що стається одразу після завершення цього завдання?",a="Ґан'рул Бладай велить вам принести очищений амулет у коло закликання під Оргріммаром, щоб провести обряд зв'язування й перемогти сукуба в двобої.",al={"що далі","наступне завдання після дару кохання"}}},fp="11,255,19.408.1,16.446.0,41.239.0,20.229.0,15.206.1,57.188.1,31.210.0,53.171.1"}
P.entries["quest:1513"] = {n="Зв'язування",s="Зв'язування — останнє випробування на шляху чорнокнижника Орди, що прагне поневолити сукуба в Оргріммарі. Використавши відданість, укладену в Амулеті Доґрана, у колі прикликання Ніру Файрблейда, чорнокнижник вириває демона з Викривленого Нижнього Світу й ламає його волю силою зброї та чарів.",h="Зв'язування — останнє випробування на шляху чорнокнижника Орди, що прагне поневолити сукуба в Оргріммарі.",kw={"зв'язування","сукуб","амулет доґрана","ніру файрблейд","ґан'рул бладай","чорнокнижник"},ang={["class:Warlock"]="Цей обряд знаменує перехід чорнокнижника до влади над хитрими, підступними демонами й доводить, що особиста сила волі здатна підкорити спокусливі небезпеки Нижнього Світу.",["faction:Horde"]="Цей ритуал, що відбувається потай у Тіньовій Розколині, показує, з якою неохочою терпимістю Орда Тралла ставиться до демонологів, прихованих від городян, які понад усе шанують честь.",["race:Orc"]="Для орків справи з демонічними сутностями несуть гіркий тягар минулого зіпсуття їхнього народу, тож дисципліна й самовладання, яких вимагає Ґан'рул, мають для них особливу вагу."},sec={{t="Якір для демона",b="Щоб сягнути крізь світи й підкорити сукуба, заклинач потребує якоря — провідника, налаштованого на особливу природу цього створіння. Цій темній меті служить амулет, який віддав покалічений орк Доґран. Пам'ятка його любові до Занкаджі, пронесена крізь полон і муки, ця дрібничка має той емоційний відгомін, що перекидає міст крізь Викривлений Нижній Світ і привертає увагу демона."},{t="Коло в тіні",b="Під ущелинами Оргріммара, глибоко в наметі Ніру Файрблейда, лежить коло прикликання, приготоване для такої небезпечної роботи. Під наглядом Ґан'рула Бладая чорнокнижник пробуджує коло, списане рунами, і б'ється з прикликаним демоном-спокусником. Чорнокнижник не може просто покликати демона на службу — він мусить здолати його в поєдинку й зігнути його злобний дух під свою владну волю."},{t="Підступи й сила волі",b="Як застерігає Ґан'рул, сукуби — небезпечні раби. Їхня присутність п'янить і спокушає чуття, але вони поволі висмоктують життєву силу й дух необачних господарів. Ґан'рул велить чорнокнижникові пам'ятати горе Доґрана й Занкаджі — як захист від підступів демона, бо гординя й самовпевненість згубили не одного обдарованого чорнокнижника. Справжня майстерність вимагає непохитної волі, що ніколи не піддається чарам демона."}},faq={{q="Що відбувається під час цього обряду?",a="Чорнокнижник приносить Амулет Доґрана в коло закликання в наметі Ніру Файрблейда в Тіньовій Розколині. Використовуючи відданість, ув'язнену в талісмані, закликач викликає сукуба з Викривленого Нижнього Світу й б'ється з ним, доки той не скориться, щоб утвердити над істотою повну владу.",al={"як працює ритуал","що робити у зв'язуванні","ритуал сукуби"}},{q="Де відбувається закликання?",a="Закликання відбувається в Тіньовій Розколині в Оргріммарі, а саме в наметі Ніру Файрблейда, де в підлогу врізано постійне обрядове коло.",al={"де коло","місце закликання","де викликати сукубу"}},{q="Хто такий Доґран і навіщо його амулет?",a="Доґран — піхотинець Орди, якого захопили й скалічили шипогриви в Пустках. Його амулет — пам'ятка, пов'язана з коханою Занкаджею, — слугує головною точкою зосередження, потрібною, щоб виманити й утримати сукуба.",al={"хто такий доґран","навіщо його амулет","історія доґрана"}},{q="Хто такий Ґан'рул Бладай?",a="Ґан'рул Бладай — старший наставник чорнокнижників у Тіньовій Розколині під Оргріммаром. Він наставляє багатонадійних чаклунів темного мистецтва й веде їх крізь небезпечні обряди підкорення демонів.",al={"хто дає завдання","хто такий ґан'рул","роль ґан'рула бладая"}},{q="Яку силу здобуває чорнокнижник, пройшовши це випробування?",a="Приборкання істоти завершує навчання чорнокнижника й дає йому таємне знання та рунічну майстерність, потрібні, щоб будь-коли закликати сукуба-прислужника собі на службу.",al={"яку силу здобуває чорнокнижник","навіщо сукуба","здібність улюбленця сукуби"}},{q="Чому закликання сукуба вважають особливо небезпечним?",a="Сукуби володіють могутніми чарами й маніпулюють бажаннями смертних. Самовпевнені чорнокнижники ризикують тим, що з них поволі висмокчуть душу і вони піддадуться тонкій підступності демона, замість ним командувати.",al={"небезпека сукуби","чому сукуби ризиковані","лор сукуби"}}},fp="11,305,16.391.1,25.401.0,19.425.1,32.298.0,36.173.0,45.203.1,24.210.0,58.171.0,60.203.0"}
P.entries["quest:1515"] = {n="Полон Доґрана",s="«Полон Доґрана» — важливе випробування у вишколі молодого чорнокнижника Орди: його посилають у саме серце табору шипогривів, щоб урятувати полоненого оркського воїна. Маючи при собі цілющий трунок, чорнокнижник мусить відшукати побитого Піхотинця Доґрана й дати йому сили, щоб утекти від полонителів.",h="«Полон Доґрана» — важливе випробування у вишколі молодого чорнокнижника Орди: його посилають у саме серце...",kw={"полон доґрана","піхотинець доґран","трунок кен'зіґли","шипогриви","чорнокнижник","сукуб"},ang={["class:Warlock"]="Цей порятунок — важливий крок до розуміння смертної пристрасті й жертви, без яких не викликати сукуба.",["faction:Horde"]="Халепа Доґрана показує, яку постійну небезпеку становлять шипогриви для патрулів і застав Орди в центральних Пустках.",["race:Orc"]="Навіть під тортурами й каліцтвом у полоні шипогривів Доґран показує ту люту витривалість, якої чекають від оркського піхотинця."},sec={{t="Самотній порятунок",b="Піхотинець Лоґмар у Таборі Тауражо не хоче ризикувати військами Орди в дорогому нападі на укріплених шипогривів, тож доля його товариша Доґрана цілком у руках заповзятливого чорнокнижника. Маючи при собі лише Трунок Кен'зіґли, рятівник мусить вирушити на північ, крізь хащі й ворожі табори, щоб знайти, де тримають Доґрана."},{t="Ціна крові",b="Доґрана знаходять жорстоко побитим, в оточенні ворожих шипогривів, серед скупчення хиж на північ від Тауражо. Гіркий трунок дає воїнові рівно стільки сили, щоб дошкандибати в безпечне місце, але порятунок коштує дорого: тяжкі рани назавжди калічать Доґрана — вони коштували йому руки й ноги."}},faq={{q="Де тримають Піхотинця Доґрана?",a="Піхотинця Доґрана тримають у полоні в невеликій групі з двох хижок шипогривів просто на північ від Табору Тауражо в Пустках.",al={"місце доґрана","де доґран","знайти доґрана в пустках"}},{q="Чому Піхотинець Лоґмар не пошле вояків на допомогу?",a="Піхотинець Лоґмар не може зняти жодного вояка з оборони Табору Тауражо: він вважає порятунок на добре стережених землях шипогривів надто ризикованим, щоб жертвувати ще чиїмись життями.",al={"чому лоґмар не пошле вояків","вояки лоґмара","підкріплення таурахо"}},{q="Що таке Трунок Кен'зіґли?",a="Це сильний, гидкий на смак відновлювальний тонік, зварений саме для того, щоб дати тяжко пораненому Доґранові досить сил, аби підвестися й утекти з полону шипогривів.",al={"що таке трунок кен'зіґли","ліки доґрана","зілля кен'зіґли"}},{q="У якому стані Доґран, коли його знаходять?",a="Доґран на межі смерті: шипогриви завдали йому численних ран і катували його. Навіть випивши трунок, він має руку й ногу, які вже не відновити.",al={"стан доґрана","поранення доґрана","рука й нога доґрана"}},{q="Як цей порятунок пов'язаний із закликанням сукуба?",a="У Доґрана є символ, пов'язаний із коханням і смертною відданістю, — почуттями й поняттями, якими чорнокнижники користуються, щоб закликати сукуба й прив'язати його до своєї волі.",al={"чому чорнокнижники","зв'язок із сукубою","завдання доґрана"}},{q="Хто захопив Доґрана?",a="Його захопили місцеві племена шипогривів, що живуть у колючих хащах на північ від Табору Тауражо.",al={"хто захопив доґрана","викрадачі доґрана","викрадачі пусток"}}},fp="18,321,15.354.0,18.331.1,27.115.0,45.191.0,28.166.0,39.183.1,52.148.1,20.97.0"}
P.entries["quest:1516"] = {n="Поклик Землі",s="«Поклик Землі» — перше випробування для шаманів-новачків Орди, що навчаються в Долині Випробувань. Дане Канаґою Ерткаллером, воно перевіряє витривалість і терпіння шамана: щоб приготувати обрядову сапту, треба вполювати демонічних переслідувачів Скверни.",h="«Поклик Землі» — перше випробування для шаманів-новачків Орди, що навчаються в Долині Випробувань.",kw={"поклик землі","шаман","ерткаллер","переслідувачі скверни","земляна сапта","долина випробувань","палаючий клинок"},ang={["class:Shaman"]="Цей обряд — ваше перше офіційне єднання зі стихіями, що закладає підвалини вашого Тотема Землі.",["race:Orc"]="В Орді Тралла повернення на шаманський шлях ушановує давні кланові традиції, що існували задовго до демонічної скверни.",["race:Troll"]="Відьмаки й духовидці Темного Списа приймають духів землі, щоб підтримати свій новознайдений дім поряд з орками."},sec={{t="Перший зв'язок",b="Перш ніж шаман зможе кликати стихії, він має встановити тривкий зв'язок із кожною з них по черзі. В орчій і тролячій культурі цей духовний шлях починається із землі — основи життя, витривалості й терпіння. Канаґа Ерткаллер — провідник початківців у Долині Випробувань; він учить, що земля вимагає найвищої поваги й стійкості, перш ніж дарує свій захист."},{t="Очисне полювання",b="Щоб довести готовність єднатися з упертими духами землі, посвячуваних посилають у північні яри, де гніздиться культ Палаючого Клинка. Полюючи на переслідувачів Скверни — осквернених потойбічних гончаків, прикликаних темною магією, — шаман доводить здатність боронити землю від неприродного тління. Здобуті копита Канаґа використовує як складники для Земляної Сапти — священного напою, що відкриває смертним очам план стихій."}},faq={{q="Яка мета цього випробування?",a="Випробування посвячує шамана в таїнства стихій: він доводить духам землі свою терплячість і духовну дисципліну, щоб згодом єднатися з ними напряму й заслужити Тотем Землі.",al={"мета випробування","навіщо поклик землі","що дає поклик землі"}},{q="Хто такий Канаґа Ерткаллер?",a="Канаґа Ерткаллер — троль, наставник шаманів у Долині Випробувань у Дуротарі. Він веде молодих шаманів-орків, тролів і тауренів-гостей їхніми першими кроками до опанування стихій.",al={"хто такий канаґа","лор канаґи ерткаллера"}},{q="Навіщо Канаґі копита скрадачів скверни?",a="Канаґа використовує копита як головний складник Земляної Сапти — особливого зілля, що дає чуттям смертного шамана змогу бачити духів стихій і говорити з ними.",al={"навіщо копита скрадачів скверни","призначення копит"}},{q="Де знайти скрадачів скверни?",a="Скрадачі скверни трапляються трохи на північ від тренувальних угідь у Долині Випробувань, біля печери й довколишніх круч, що належать Ковену Палаючого Клинка.",al={"де скрадачі скверни","місце скрадачів"}},{q="Чи можуть інші раси Орди пройти цю версію випробування?",a="Так. Хоча вона призначена передусім для шаманів-орків і тролів, що дорослішають у Дуротарі, шамани-таурени, які мандрують далеко від Плато Червоної Хмари, теж можуть пройти випробування Канаґи в Долині Випробувань.",al={"чи таурени можуть","чи це лише для орків"}},{q="Які чесноти уособлює для шамана земля?",a="За шаманською традицією, земля — основа життя, що втілює величезну силу, витривалість і вічну терплячість, хоча, коли її не шанують, вона буває вперто примхливою.",al={"чесноти землі","що означає земля для шамана"}}},fp="13,260,14.398.0,16.449.0,34.202.0,26.202.0,39.178.0,34.160.0,58.189.0,50.188.0"}
P.entries["quest:1517"] = {n="Поклик Землі",s="Цей священний обряд — перше духовне єднання посвячуваного зі стихіями в Дуроторі. Під проводом Канаґи Ерткаллера молоді шамани випивають сильнодійну Земляну Сапту на Камені Духів, щоб пронизати завісу й стати просто перед Малим Проявом Землі.",h="Цей священний обряд — перше духовне єднання посвячуваного зі стихіями в Дуроторі.",kw={"поклик землі","шаман","земляна сапта","камінь духів","прояв землі","прихована стежка","дуротар"},ang={["class:Shaman"]="Цей обряд — ваш найперший крок на шляху налаштування на стихії; він учить, що справжня майстерність починається з тихого терпіння землі.",["race:Orc"]="Для орків, що повертаються до шляхів предків після поколінь скверни, єднання через Земляну Сапту — священне віднайдення традиційного зв'язку їхнього народу з духами.",["race:Troll"]="Відьмаки й духовидці Темного Списа приймають ці земляні обряди, щоб пристосувати свої глибокі зв'язки з предками до суворого, випаленого сонцем краєвиду Дуротару."},sec={{t="Сила сапти",b="Сапта — містичне вариво, відоме лише небагатьом майстрам-шаманам. Зварений зі стихійною магією, напій служить мостом між смертним сприйняттям і духовним планом, даруючи сильним духом «зір сапти». Оскільки його сила прив'язує дух того, хто п'є, просто до стихії, традиція вимагає ніколи не пити його поза освяченою святою землею."},{t="Паломництво до Каменя Духів",b="Щоб єднатися із землею, посвячувані покидають Долину Випробувань і сходять Прихованою Стежкою в південні скелі Дуротару. Наприкінці стежки стоїть Камінь Духів — піднесене святилище над суворою пусткою. Випита тут сапта дає посвячуваному побачити те, чого не бачать буденні очі: присутність стихії, що тихо чекає серед каміння."},{t="Терпіння землі",b="Малий Прояв Землі не вимагає ні крові, ні підкорення — лише щоб прохач смиренно став перед світом. Поки інші сили стихій — вогонь, вода й повітря — мають бурхливих, мінливих і часто хаотичних духів, земля дарує сталість. Вона вітає прохача, нагадуючи, що гори дають витривалість, а рівнини — безмежне терпіння."}},faq={{q="Що таке Земляна Сапта?",a="Земляна Сапта — особливе зілля, яке варять досвідчені шамани, щоб тимчасово налаштувати дух того, хто його п'є, на стихію землі. Випивши його, отримуєш внутрішній зір, потрібний, щоб бачити прихованих духів стихій і говорити з ними.",al={"що таке земляна сапта","значення сапти","що робить сапта"}},{q="Де розташований Камінь Духів?",a="Камінь Духів стоїть серед скелястих гір на південний захід від Лігва в Долині Випробувань. Посвячувані дістаються до нього Прихованою Стежкою, що веде в пагорби на південь від дна долини.",al={"місце каменя духів","де камінь духів","як знайти камінь духів"}},{q="Чому сапту треба випити біля Каменя Духів?",a="Шаманська традиція велить пити сапту лише у визначених святих місцях. Священні місця на кшталт Каменя Духів — природні тонкі межі між світом смертних і духами стихій.",al={"чому пити біля каменя духів","чи можна пити сапту де завгодно"}},{q="Хто такий Малий Прояв Землі?",a="Це дух стихії землі, що живе біля Каменя Духів. Видимий лише загостреному сприйняттю під дією сапти, він вітає молодих шаманів, щоб перевірити їхню смиренність і дати перші основні уроки стихійної рівноваги.",al={"малий прояв землі","хто дух землі"}},{q="Чи може будь-який шаман Орди пройти це випробування?",a="Хоча це передусім обряд посвяти для молодих шаманів-орків і тролів Темного Списа, що навчаються в Дуротарі, шамани-таурени, які сюди прийдуть, теж можуть його пройти, хоча вони мають власний такий обряд на Плато Червоної Хмари.",al={"чи будь-який шаман орди","чи таурени можуть"}},{q="Як дух землі ставиться до посвячуваного?",a="На відміну від мінливих проявів вогню чи повітря, дух землі привітний і спокійний. Він приймає посвячуваних, що підходять зі смиренною повагою, і дає своє благословення, не вимагаючи двобою.",al={"що каже дух землі","чи дух землі ворожий"}}},fp="13,260,22.371.0,25.352.0,21.400.0,23.225.0,29.179.0,46.196.0,40.238.0,42.217.0,48.212.0"}
P.entries["quest:1518"] = {n="Поклик Землі",s="«Поклик Землі» — завершальний обряд випробування землі для молодих шаманів у Дуроторі. Поєднавшись із проявом духу землі, посвячуваний повертається до Канаґи Ерткаллера з грубим кварцом, щоб отримати свій перший стихійний тотем.",h="«Поклик Землі» — завершальний обряд випробування землі для молодих шаманів у Дуроторі.",kw={"поклик землі","шаман","грубий кварц","тотем землі","ерткаллер","прояв землі","долина випробувань"},ang={["class:Shaman"]="Цей обряд дає вам перший тотем і відкриває вміння закорінюватися в стихіях і кликати землю на допомогу.",["faction:Horde"]="Стихії Калімдору дикі й неприборкані, тож зв'язок, який кують шамани Орди, конче потрібен для виживання їхніх нових поселень.",["race:Orc"]="Випробування втілює тривале відродження орчого шаманізму в Дуроторі — повернення до рівноваги стихій після десятиліть демонічної скверни.",["race:Troll"]="Відьмаки й духовидці Темного Списа навчаються поряд з орками в Долині Випробувань, доповнюючи своє традиційне єднання чотирма стихійними шляхами."},sec={{t="Серце каменю",b="Щоб єднатися із землею, шаман-новачок має дивитися далі за грубу силу. Виявивши терпіння й смирення перед Малим Проявом Землі, посвячуваний отримує скромний знак — шматок грубого кварцу. Хоч на вигляд він непримітний, цей крихітний камінь — тривке зерно сили й доказ, що дух прийняв обітницю прохача."},{t="Перший із чотирьох шляхів",b="Повернення кварцу Канаґі Ерткаллеру в Долину Випробувань завершує випробування. Канаґа вправляє камінь у Тотем Землі — фізичне осердя, через яке шаман спрямовує непохитний захист і силу землі. Цей обряд знаменує офіційний вступ посвячуваного в першу з чотирьох стихійних дисциплін і закладає підвалини для цілого життя єднання з природним світом."}},faq={{q="Для чого потрібен грубий кварц?",a="Грубий кварц дарує Малий Прояв Землі як доказ, що ви поєдналися з духом. Канаґа Ерткаллер вправляє цей камінчик у ваш щойно вирізьблений Тотем Землі, де він стає серцем і осередком ваших земляних заклять.",al={"навіщо грубий кварц","що робить кварц","призначення кварцу"}},{q="Хто такий Канаґа Ерткаллер?",a="Канаґа Ерткаллер — наставник шаманів у Долині Випробувань у Дуротарі. Він веде молодих посвячуваних орків і тролів крізь їхні перші випробування, готує їх до єднання з духами стихій і виготовляє їхні перші тотеми.",al={"канаґа","канаґа ерткаллер","хто такий канаґа"}},{q="Чи можуть таурени виконати це завдання?",a="Так. Хоча таурени зазвичай проходять випробування землі зі своїми старійшинами на Плато Червоної Хмари в Малгорі, будь-який шаман Орди, що прийде до Долини Випробувань, може пройти обряд із Канаґою Ерткаллером.",al={"чи таурени можуть у дуротарі","тауренський шаман дуротар","поклик землі таурена"}},{q="Що означає отримати Тотем Землі?",a="Отримати Тотем Землі — значить, що дух землі вас визнав. Тотем — і знак вашого становища серед шаманів, і потрібне фізичне осердя, щоб накладати земляні благословення й захисні чари.",al={"що означає тотем землі","навіщо тотем землі"}},{q="Яких чеснот земля вимагає від шамана?",a="Дух просить посвячуваного бути терплячим, лишатися сильним і шукати мудрості. Він навчає, що навіть найменший камінчик може пережити гори, якщо витримає, і закликає шаманів шанувати землю, щоб і вона, своєю чергою, їх підтримувала.",al={"уроки духа землі","чого земля вимагає"}},{q="Куди веде шлях шамана після цього?",a="Земля — лише перша з чотирьох стихій, які шаман має опанувати. У міру навчання вас згодом покличуть шукати єднання з духами вогню, води й повітря.",al={"який тотем далі","після тотема землі","чотири шляхи шамана"}}},fp="13,246,18.371.0,23.408.0,34.245.0,26.235.0,25.210.0,44.216.0,49.228.0,41.184.0"}
P.entries["quest:152"] = {n="Узбережжя небезпечне",s="Уздовж зубчастого західного краю Вестфолу мілини всіяні уламками кораблів, а пляжі заполонили племена мурлоків. Примарний Капітан Ґрейсон на Маяку Вестфолу наймає вправних шукачів пригод, щоб вигнати цих водяних грабіжників, — тоді моряки, що пережили корабельну аварію, матимуть шанс уціліти й на березі.",h="Уздовж зубчастого західного краю Вестфолу мілини всіяні уламками кораблів, а пляжі заполонили племена...",kw={"узбережжя небезпечне","капітан ґрейсон","маяк вестфолу","мурлоки","велике море","вестфол"},ang={["faction:Alliance"]="Поки армії Стормвінда немає у Вестфолі, Народне ополчення ледве захищає ферми вглибині краю, тож оборона узбережжя цілком лягає на самотніх союзників на кшталт Капітана Ґрейсона.",["race:Human"]="Людські торгові судна й рибалки здавна ходили водами біля Вестфолу; бачити, як узбережжя стало смертельною пасткою, що кишить мурлоками, — гірке нагадування про занепалі рубежі королівства."},sec={{t="Цвинтар кораблів",b="Велике Море славиться підступністю біля західних меж Вестфолу. Рифи, раптові шквали й гострі скелі за ці роки розтрощили на тріски безліч суден. За звичних обставин ті, хто вцілів, могли б учепитися за уламки, виповзти на пісок і чекати порятунку. Та, на лихо для потерпілих моряків, узбережжя цілком опинилося під владою агресивних племен мурлоків, що не знають жалю до викинутих на берег бідолах."},{t="Примарний вартовий",b="На самотній скелі на південний захід від суходолу стоїть Маяк Вестфолу, який доглядає дух Капітана Ґрейсона. Хоч смерть прикувала його до цього посту, Ґрейсон і далі вважає своїм обов'язком безпеку кораблів, що пропливають повз, і заблуканих моряків. Розуміючи, що племена мурлоків — від простих береговиків на півночі до смертоносних мисливців припливу, воїнів і оракулів на півдні — перетворили пляжі на смертельну пастку, він закликає мандрівників планомірно очистити узбережжя."}},faq={{q="Хто такий Капітан Ґрейсон?",a="Капітан Ґрейсон — примарний морський капітан, що блукає Маяком Вестфолу. Попри те, що він нежить, він і далі відчуває обов'язок перед моряками, які ходять підступними водами біля узбережжя, і прагне вберегти береги для всіх, хто може вижити після корабельної аварії.",al={"капітан ґрейсон","привид на маяку","доглядач маяка вестфол"}},{q="Чому Ґрейсон хоче очистити узбережжя від мурлоків?",a="Води біля Вестфолу всіяні затонулими кораблями, і вцілілих моряків часто викидає на берег. Поки агресивні племена мурлоків кишать на пляжах від півночі до півдня, кожного потерпілого, що дістався суходолу, швидко вбивають, — хіба що узбережжя тримати чистим.",al={"чому ґрейсон очищує від мурлоків","чому вбивати мурлоків вестфол","причина очищення узбережжя"}},{q="Де знайти різних мурлоків?",a="Мурлоки-прибережники зазвичай живуть на північних ділянках узбережжя Вестфолу. Грізніші мурлоки-воїни, оракули й мисливці припливу зосереджені в поселеннях і таборах на південних пляжах.",al={"де мурлоки","місця прибережних бігунів","де припливні мисливці"}},{q="Чи ворожий Капітан Ґрейсон до Альянсу чи Орди?",a="Капітан Ґрейсон — нейтральна постать. Його зв'язують морські обов'язки, а не політична вірність, тож він звертається зі своїми проханнями й дає нагороди будь-якому вправному шукачеві пригод, готовому допомогти зробити узбережжя безпечнішим.",al={"чи ґрейсон ворожий","фракція ґрейсона","чи орда може виконати"}},{q="Чи треба спершу знову запалити маяк, щоб узяти це завдання?",a="Ні. Капітан Ґрейсон доручить вам очистити узбережжя незалежно від того, чи допомагали ви йому знову запалити Маяк Вестфолу.",al={"чи треба спершу запалити маяк","передумова узбережжя небезпечне"}},{q="Чи мурлоки працюють на Братство Дефіас?",a="Ні. Мурлоки діють самі, з ревнивої агресії до своїх земель. Хоча Братство Дефіас орудує поблизу, біля Мунбрука й у південних бухтах, прибережні племена мурлоків нападають на кожного, хто вдереться в їхні мисливські угіддя на березі.",al={"чи мурлоки з дефіас","зв'язок дефіас і мурлоків"}}},fp="21,304,20.443.0,19.490.0,23.275.0,57.284.0,42.221.0,52.213.0,56.141.0,51.246.0"}
P.entries["quest:1520"] = {n="Поклик Землі",s="Цей священний обряд знаменує духовне налаштування шамана-таурена на стихію землі. Випивши Земляну Сапту біля святого каменя на схід від Табору Нарачі, посвячені зазирають за межі тілесних чуттів, щоб безпосередньо поєднатися з Малим Проявом Землі.",h="Цей священний обряд знаменує духовне налаштування шамана-таурена на стихію землі.",kw={"поклик землі","земляна сапта","малий прояв землі","камінь кодо","шаман","табір нарачі"},ang={["class:Shaman"]="Цей обряд — духовне осердя зв'язку шамана-таурена із землею, обов'язковий міст до єднання з землею й отримання Тотема Землі.",["race:Tauren"]="Глибока шана до Матері-Землі робить ритуал сапти одним із найшанованіших у культурі випробувань дорослішання для духовних учнів тауренів на Плато Червоної Хмари."},sec={{t="Призначення сапти",b="Сапта — ретельно приготоване церемоніальне зілля, яке шаманські старійшини варять, щоб прив'язати смертний дух посвяченого безпосередньо до первісної стихії. Її готують магією предків, і таємниці варіння зберігає лише дехто з тауренів. Випитий у призначеному священному місці, напій розширює розум і прориває завісу між тілесним світом і духовним планом, щоб стихії можна було побачити в їхній первісній подобі."},{t="Єднання біля Каменя Кодо",b="Табір Нарачі лишається позаду: на схід від нього височіє Камінь Кодо — грізний кам'яний стовп, що слугує святим прихистком. Випита тут сапта відкриває Малий Прояв Землі, що чекає на прочанина. На відміну від мінливих, вогняних чи шалених ликів природи, які шаман зустріне далі на своєму шляху, дух землі просить лише, щоб посвячений підійшов у тихому смиренні, і дарує незламну силу гір і спокійне терпіння рівнин усім, хто шанує землю."}},faq={{q="Що таке Земляна Сапта?",a="Земляна Сапта — алхімічний і духовний напій, який варять старійшини-шамани. Його магія відкриває сприйняття, і посвячуваний може бачити духів стихії землі й спілкуватися з ними напряму.",al={"що таке земляна сапта","значення земляної сапти","що робить напій"}},{q="Де розташований Камінь Кодо?",a="Камінь Кодо — величний природний кам'яний моноліт просто на схід від Табору Нарачі, по той бік Плато Червоної Хмари.",al={"місце каменя кодо","де камінь кодо","де святилище"}},{q="Хто приготував Земляну Сапту для цього обряду?",a="Зілля приготувала й дала Віщун Рейвенфезер — старійшина-шаманка з Табору Нарачі, що керує навчанням молодих духовних провідників.",al={"хто приготував сапту","хто дає сапту"}},{q="Чому сапту треба випити у святому місці?",a="Сапта священна за своєю природою й небезпечна, якщо вжити її неналежно. Тауренська традиція вимагає пити її лише в освячених святилищах, де природно живуть духи стихій і можуть безпечно прийняти прохача.",al={"чому пити у святому місці","чи можна пити сапту де завгодно"}},{q="Що стається, коли вип'єш зілля біля Каменя Кодо?",a="Зілля знімає завісу буденності, і з'являється Малий Прояв Землі. Розмова з цією істотою завершує поєднання шамана зі стихією землі.",al={"що з'являється","поява малого прояву землі"}},{q="Якого уроку дух землі навчає посвячуваних?",a="Дух навчає, що земля вимагає смиренної терплячості, а не бою. Тоді як стихії на кшталт вогню чи повітря бувають хаотичні й буйні, земля дарує душі шамана силу, витривалість і тиху основу.",al={"урок духа землі","значення обряду землі"}}},fp="13,245,24.449.0,22.456.0,23.205.0,27.115.0,42.151.0,46.204.0,52.165.0,54.210.0"}
P.entries["quest:1521"] = {n="Поклик Землі",s="Цей обряд завершує перше єднання молодого шамана-таурена з духами землі в Малгорі. Випивши Земляну Сапту й поговоривши безпосередньо з проявом духа, посвячений отримує уламок сирого каменю, щоб принести його додому. Повернення туди, де на нього чекає Табір Нарачі, знаменує офіційний зв'язок містика-початківця з першою з чотирьох стихій.",h="Цей обряд завершує перше єднання молодого шамана-таурена з духами землі в Малгорі.",kw={"поклик землі","грубий кварц","тотем землі","малий прояв землі","віщун рейвенфезер","шаман","табір нарачі"},ang={["class:Shaman"]="Цей обряд знаменує здобуття вашого найпершого тотема. Він заземлює вашу духовну сутність і відкриває вам змогу творити основні обереги землі.",["faction:Horde"]="Шамани — життєво важливі духовні опори й радники нової Орди, що поєднують смертні раси з мінливими силами стихій Калімдору.",["race:Tauren"]="Культура тауренів ставиться до Матері-Землі з глибокою шаною. Це випробування прив'язує посвяченого безпосередньо до живого каменю й ґрунту його прабатьківської землі."},sec={{t="Дар від гори",b="Коли посвячений єднається з Малим Проявом Землі на скелях біля Плато Червоної Хмари, дух дарує простий Грубий Кварц. Хоч камінь непоказний на вигляд, він уособлює угоду зі стихією й витривалість самого каменю. Дух нагадує молодому шаману, що терпіння й сила — головні чесноти, яких вимагає земля, і обіцяє, що взаємна повага подарує гармонію з землею."},{t="Перший тотем",b="Коли посвячений повертається до Табору Нарачі, Віщун Рейвенфезер із подарованого кварцу виготовляє найперший Тотем Землі шамана. Це значно більше, ніж оздобний знак становища: тотем — постійний тілесний і духовний якір. Через це різьблене осердя посвячений спрямовує заземлювальну, захисну магію самої землі й робить перший справжній крок на чотирьох стихійних шляхах."}},faq={{q="Для чого потрібен Грубий Кварц?",a="Кварц — знак, який Малий Прояв Землі дає особисто як доказ єднання. Віщун Рейвенфезер робить його духовним серцем вашого щойно вирізьбленого Тотема Землі.",al={"навіщо мені грубий кварц","для чого кварц","грубий кварц призначення"}},{q="Чому Тотем Землі такий важливий для шамана?",a="Тотеми — провідники, крізь які шаман спрямовує силу стихій. Без Тотема Землі як осердя шаман не може просити духів землі втілювати його закляття й захисні чари.",al={"навіщо мені тотем землі","що робить тотем землі","тотем землі лор"}},{q="Хто така Віщун Рейвенфезер?",a="Віщун Рейвенфезер — духовна провідниця й наставниця шаманів у Таборі Нарачі на Плато Червоної Хмари. Вона проводить стихійні випробування молодих тауренів, веде їх крізь перші видіння й виготовляє їхні священні знаряддя.",al={"хто такий рейвенфезер","віщун рейвенфезер лор","віщун табору нараче"}},{q="Про які чотири шляхи говорить Віщун Рейвенфезер?",a="Вона має на увазі чотири первісні стихії, які шаман мусить опанувати: Землю, Вогонь, Воду й Повітря. Земля — основа, що уособлює витривалість і непохитність, і з неї починається перше випробування посвячуваного.",al={"чотири шляхи","чотири стихії шамана","які ці шляхи"}},{q="Де відбувається це єднання?",a="Малий Прояв Землі живе на скелястих урвищах на межі Плато Червоної Хмари в Малгорі, і дістатися до нього можна лише після того, як вип'єш особливу Земляну Сапту.",al={"де знайти духа землі","де відбувається прояв","де дух"}},{q="Чи проходять подібний обряд інші шамани Орди?",a="Так. Орки й тролі Темного Списа в Дуротарі проходять власну версію «Поклику Землі» в Долині Випробувань, шукаючи єднання з місцевими проявами стихій, щоб вирізьбити свої перші тотеми.",al={"чи орки проходять поклик землі","тролі поклик землі","чи всі шамани отримують тотем землі"}}},fp="13,352,24.402.0,15.387.0,40.178.0,47.203.0,25.241.0,51.205.0,37.157.0,48.198.0"}
P.entries["quest:1524"] = {n="Поклик вогню",s="Це паломництво — друге випробування на шляху шамана до єднання з вогнем. Кранал Фісс посилає молодого шамана з Пусток із незапаленим Смолоскипом Сплячого Полум'я до відлюдного святилища на гірській вершині, що здіймається високо над Річкою Південної Люті в Дуротарі.",h="Це паломництво — друге випробування на шляху шамана до єднання з вогнем.",kw={"поклик вогню","кранал фісс","смолоскип сплячого полум'я","святиня приспаного полум'я","телф джулам","вогняний тотем"},ang={["class:Shaman"]="Шлях до Вогняного Тотема вимагає прямого єднання зі стихійними силами Калімдору — не простих уроків, а паломництва до віддалених святинь.",["faction:Horde"]="Спільні шаманські вчення орків, тауренів і тролів єднають їхні духовні традиції й ведуть учнів від рівнин Пусток до священних скель Дуротару."},sec={{t="Перевірка готовності",b="Новачок може показати сиру містичну силу, але вогонь вимагає куди більшого, ніж міць: стриманості, зосередженості й шани. Кранал Фісс довіряє шаманові Смолоскип Сплячого Полум'я. Цей предмет — водночас і обрядове знаряддя, і рекомендація: він показує охоронцеві святині, що власника офіційно визнано готовим до випробування."},{t="Прихована вершина",b="Мета лежить за Річкою Південної Люті, серед південних скель Дуротару. Відзначена лише вивітреним каменем із вогняною руною, непримітна стежка здіймається до однієї з найвищих вершин краю. На вершині стоїть Святиня Приспаного Полум'я, яку стереже троль-самітник Телф Джулам. Телф раз у раз проганяє цікавих мандрівників і шукачів скарбів, оберігаючи священну жаровню від буденних очей, доки не прийде справжній прохач із незапаленим смолоскипом."}},faq={{q="Для чого потрібен Смолоскип Сплячого Полум'я?",a="Незапалений смолоскип — знак наміру, який дає Кранал Фісс. Він показує Телфу Джуламу, доглядачеві святині, що той, хто його несе, — гідний посвячуваний шаман, бо інакше той проганяє випадкових блукачів і шукачів скарбів.",al={"навіщо нести смолоскип","смолоскип сплячого полум'я","що означає смолоскип"}},{q="Хто такий Телф Джулам?",a="Телф Джулам — шаман-самітник з Орди, що пильнує Святиню Приспаного Полум'я на вершинах південного Дуротару. Він оберігає жаровню від тих, хто не розуміє й не шанує природи духів.",al={"телф джулам","хранитель святині","хто той троль біля святині"}},{q="Де починається прихована стежка?",a="Стежка починається в Дуротарі, на південь від мосту через Річку Південної Люті. На березі річки, там, де гори сходяться з узбережжям, стоїть кам'яна брила з вогняною руною — вона позначає вузьку стежку, що підіймається на високий кряж.",al={"де прихована стежка","як знайти святиню сплячого полум'я","стежка в гору"}},{q="Чому смолоскип треба нести незапаленим?",a="Вогонь не можна просто взяти — його треба пробудити й приборкати належним обрядом. Незапалений смолоскип символізує сплячий стан полум'я, перш ніж шаман пройде єднання, потрібне, щоб його розпалити.",al={"чому смолоскип незапалений","ритуал сплячого смолоскипа","чому спляче полум'я"}},{q="Що буде, коли дійдеш до Телфа Джулама?",a="Перевіривши смолоскип, Телф Джулам веде посвячуваного до суворіших і небезпечніших обрядів, потрібних, щоб розпалити спляче полум'я й довести владу над стихією вогню.",al={"наступний крок поклику вогню","що після телфа джулама"}},{q="Чому цю святиню приховують від решти Орди?",a="Сили стихій мінливі й небезпечні в ненавчених руках. Шаманські традиції тримають священні місця подалі від звичайних поселень, щоб шукачі скарбів і цікаві не тривожили спочилих духів і не накликали лиха.",al={"чому святиня таємна","чи прихована святиня"}}},fp="12,269,19.369.0,15.481.0,54.221.0,19.227.0,33.234.0,36.219.0,40.173.0,58.227.0"}
P.entries["quest:1525"] = {n="Поклик вогню",s="Це випробування — вирішальна підготовка до єднання шамана з вогнем: посвячуваний має зібрати леткі складники для Вогняної Сапти. Телфу Джуламу потрібні компоненти, насичені жаром і магічною силою: смола геомантів Гостроманів і мішечок темних реагентів від культистів Палаючого Клинка, що ховаються в Дуроторі.",h="Це випробування — вирішальна підготовка до єднання шамана з вогнем: посвячуваний має зібрати леткі складники...",kw={"поклик вогню","шаман","вогняна сапта","телф джулам","вогняна смола","гострогриви","палаючий клинок"},ang={["class:Shaman"]="Цей обряд перевіряє здатність молодого шамана врівноважувати протилежні сили й показує, що полум'я — не просто пальне для гніву, а знаряддя життя і світла, коли його веде мудрість.",["faction:Horde"]="Випробування посилає захисників Орди вдарити по двох нагальних загрозах просто на їхніх кордонах: шипогривах Гостроманів, що насуваються в Пустках, і підступних культистах Палаючого Клинка, що зарилися в Дуроторі.",["race:Orc"]="Для орків мати справу з Палаючим Клинком — гірке нагадування про темну магію чорнокнижників, що колись осквернила їхній народ, тож повернути вогонь як чисту природну стихію — важливий акт відновлення культури."},sec={{t="Приготування Вогняної Сапти",b="Щоб бачити духів вогню й говорити з ними, шаман не може покладатися лише на смертний зір. Як земля вимагала власного напою, так і відкрити чуття Вічному Полум'ю можна лише особливою Вогняною Саптою. Для зілля потрібні реагенти, від природи пов'язані з жаром і полум'ям. Відлюдник Телф Джулам посилає посвячуваних через Дуротар і у східні Пустки здобути ці складники в тих, хто володіє первісним жаром і згубним чаклунством."},{t="Вороги і стихії",b="Потрібні складники показують, як по-різному сторони черпають вогонь. Чаклуни-шипогриви Гостроманів зі східних Пусток носять вогняну смолу — в'язкий горючий побічний продукт їхніх земляних обрядів. Натомість мішечок реагентів треба відібрати в культистів Палаючого Клинка, що причаїлися в Печері Пилового Вітру серед ярів на північний схід від Гострого Пагорба. Хоч культисти-чорнокнижники вживають вогонь як знаряддя руйнування й демонічного хаосу, сирі реагенти в їхніх мішечках і далі природно відгукуються на саму стихію."},{t="Природа полум'я",b="Коли сапту зварено, Телф Джулам відкриває важливу істину про стихії: вогонь — щось значно більше, ніж руйнування й загибель. Він палить і пожирає, та водночас він — серце тепла, світла і творення. Справжня рівновага вимагає розуміти, що протилежні сили надають одна одній сенсу, і мудрий шаман уживає протилежні сили стихій разом, а не має вогонь лише за зброю."}},faq={{q="Що таке Вогняна Сапта?",a="Сапта — обрядовий напій, який шамани готують зі складників, пов'язаних із певною стихією. Вогняна Сапта тимчасово налаштовує дух і зір шамана на царство вогню, і він може бачити духів вогню, невидимих звичайним чуттям, і говорити з ними.",al={"що таке вогняна сапта","що значить вогняна сапта","навіщо пити саму"}},{q="Де знайти Вогняну Смолу?",a="Вогняну Смолу носять чарівники шипогривів Гостроманів, що живуть на східних рівнинах Пусток, одразу за Річкою Південної Люті від Дуротару. Геоманти, провидці, містики й терноткачі часто мають при собі горщики цієї густої займистої суміші для своїх племінних обрядів.",al={"де вогняна смола","хто дає вогняну смолу","вогняна смола шипогриви"}},{q="Де знайти Торбинку для Реагентів?",a="Торбинку для Реагентів носять культисти Палаючого Клинка в Печері Пилового Вітру. Ця печера — над ярами на північний схід від Гострого Пагорба в Дуротарі; не плутайте її з Череп-скелею далі на півночі, біля узбережжя.",al={"де торбинка для реагентів","в якій печері торбинка","торбинка палаючого клинка"}},{q="Чому шаман користується речами чорнокнижників?",a="Для сапти потрібні складники, природно насичені потрібною стихією. Культисти Палаючого Клинка постійно закликають руйнівне демонічне полум'я, тож їхні торбинки для заклинань напхані сильними реагентами, тісно пов'язаними з вогнем, — саме тим каталізатором, якого потребує Телф Джулам, щоб зварити напій.",al={"чому реагенти палаючого клинка","речі чорнокнижників для шамана","вогонь чорнокнижників"}},{q="Хто такий Телф Джулам?",a="Телф Джулам — троль-шаман, що живе самотою на скелях Дуротару, на південь від Гострого Пагорба. Він проводить суворі випробування вогнем для посвячуваних Орди, навчаючи їх тримати небезпечну рівновагу між руйнуванням і творенням.",al={"телф джулам лор","хто такий телф джулам"}},{q="Що буде після цього завдання?",a="Коли Телф Джулам зварить Вогняну Сапту із зібраних реагентів, він посилає вас на вогняні висоти сусідньої приспаної вершини. Там треба випити напій, щоб зустрітися з духом стихії й заслужити свій тотем вогню.",al={"наступне завдання поклику вогню","що після реагентів","що робити з вогняною саптою"}}},fp="12,343,22.442.0,20.527.0,19.406.1,21.302.0,29.275.0,33.219.0,42.311.0,19.245.0,30.223.1"}
P.entries["quest:1526"] = {n="Поклик вогню",s="Це випробування — вирішальна мить налаштування шамана на вогонь на вершинах Дуротару. Під проводом відлюдника Телфа Джулама посвячуваний має випити сильнодійну вогняну сапту, щоб побачити Малий Прояв Вогню й стати з ним на герць. Перемога над духом дає сяйливий жар, яким розпалюють жаровню в Святилищі Вічного Полум'я й запалюють обрядовий смолоскип.",h="Це випробування — вирішальна мить налаштування шамана на вогонь на вершинах Дуротару.",kw={"поклик вогню","шаман","вогняна сапта","прояв вогню","телф джулам","сяйливий жар","святилище вічного полум'я"},ang={["class:Shaman"]="На відміну від твердої, непіддатливої землі, вогонь мінливий і руйнівний. Це випробування вчить, що вогонь поглине нерішучого закликача й вимагає непохитної зосередженості та влади, щоб його опанувати.",["faction:Horde"]="Орки й тролі-шамани здійснюють паломництво на червоні скелі Дуротару, щоб довести своє єднання з вогняними духами землі."},sec={{t="Очі полум'я",b="Духи вогню рідко лишаються на видноті для невтаємничених. Щоб єднатися з ними, шаман має змінити своє сприйняття вогняною саптою — стихійним напоєм, настояним на реагентах, зібраних у пустищах і на узбережжі. Випитий напій відкриває чуття незримому, являючи менших духів і прояви, що танцюють на скелях вершини."},{t="Герць із проявом",b="Вогонь не кориться пасивній відданості; він вимагає сили, рішучості й поваги. На вершині гори чекає Малий Прояв Вогню. Відчувши пронизливий погляд шамана, щойно сапта подіє, дух чекає на початок виклику. Посвячуваних учать бити швидко й без вагань, бо стихійний вогонь живиться затяжним боєм і що довше триває герць, то лютішим і гарячішим стає."},{t="Жаровня Сплячого Полум'я",b="Коли прояв підкорено, шаман забирає його останній жар у вигляді сяйливого жару. Повернувшись до святилища на вершині, він кладе жар у Жаровню Сплячого Полум'я. Хоч її відкрито суворому сонцю й вітрам Дуротару, карбований метал лишається чистим і холодним, доки жар не торкнеться чаші, — а тоді вона вибухає ритмічним білим полум'ям, що запалює обрядовий смолоскип."}},faq={{q="Яка мета цього випробування?",a="Це випробування перевіряє, чи гідний молодий шаман командувати стихією вогню. Зійшовшись із проявом стихії й увібравши його первісний жар в обрядовий смолоскип, посвячуваний доводить свою силу й здобуває право виготовити Вогняний Тотем.",al={"навіщо поклик вогню","що означає завдання тотема вогню","випробування поклику вогню"}},{q="Навіщо мені пити вогняну сапту?",a="Духи стихій часто перебувають трохи поза межами звичайного смертного зору. Вогняна сапта стоншує завісу, і шаман може бачити вогняних елементалів, що зібралися на вершині гори, і фізично з ними взаємодіяти.",al={"що робить вогняна сапта","навіщо сапта","не бачу вогняного елементаля"}},{q="Де знайти Малого Прояву Вогню?",a="Прояв перебуває на самій вершині гірського кряжа над пристановищем Телфа Джулама в Дуротарі, біля Святині Вічного Полум'я.",al={"де прояв вогню","де вогняний елементаль","куди мені йти"}},{q="Хто такий Телф Джулам?",a="Телф Джулам — дивакуватий шаман-самітник, що живе високо на скелястому кряжі в Дуротарі. Він веде молодих посвячуваних Орди крізь небезпечні й примхливі обряди, потрібні, щоб зрозуміти вогонь.",al={"роль телфа джулама","телф джулам лор","хто той відлюдник"}},{q="Чому прояв стає сильнішим під час бою?",a="Вогонь за своєю природою з часом наростає, шириться й живиться енергією. Шаманів застерігають бити рішуче, бо довге вагання дає духові змогу набрати сили й палати дедалі жаркіше.",al={"чому вогняний елементаль такий сильний","прояв посилюється","швидкий удар вогню"}},{q="Що буде, коли жаровню розпалено?",a="Розпалена жаровня запалює обрядовий смолоскип. Посвячуваний несе це священне полум'я вниз із гори, щоб завершити виготовлення свого Вогняного Тотема.",al={"що після спящого полум'я","наступне завдання поклику вогню","куди нести запалений смолоскип"}}},fp="12,363,17.359.0,29.427.0,32.403.1,34.232.0,38.217.0,47.140.0,19.189.0,58.193.0,38.158.0"}
P.entries["quest:1529"] = {n="Поклик води",s="«Поклик води» — обряд посвяти, що скеровує молодих шаманів Орди з висот Тандер Блафа до східних берегів Пусток. Щоб поєднатися з очищувальною стихією води, учень має розшукати відлюдницю Іслен Вотерсір. Ця зустріч — перший крок духовної подорожі, що завершується здобуттям Тотема Води.",h="«Поклик води» — обряд посвяти, що скеровує молодих шаманів Орди з висот Тандер Блафа до східних берегів...",kw={"поклик води","шаман","іслен вотерсір","ксаніс флеймвівер","тотем води","тандер блаф","пустки"},ang={["class:Shaman"]="Цей обряд знаменує перехід від перших випробувань стихій до опанування плинних сил очищення, зцілення й припливу.",["faction:Horde"]="Шаманізм лишається підвалиною нової Орди, поєднуючи прадавні традиції орків, тролів і тауренів, що шанують духів.",["race:Tauren"]="Це завдання, що починається в Тандер Блафі, виводить юних шаманів-шу'гало із затишних рівнин Малгору на широкі простори Калімдору."},sec={{t="Поклик із круч",b="Опанувавши незламну землю й неприборкане полум'я, молодий шаман рано чи пізно стає готовим вивчати глибші таємниці стихій. У Тандер Блафі наставники, як-от Ксаніс Флеймвівер, помічають, коли учень проявив досить дисципліни, щоб наблизитися до плинного, очищувального духу води. Для цієї подорожі треба залишити продувані вітрами столові гори Малгору й вирушити на схід через випалені сонцем рівнини Пусток."},{t="Самітниця узбережжя",b="Шлях веде до Іслен Вотерсір — тихої містикині, що живе подалі від гамірних поселень, у скромній рибальській хижі на східному узбережжі, на південь від Раджета й гирла Річки Південної Люті. Стоячи на краю великого океану, Іслен визначає готовність мандрівників за тим, як довкола них тримаються стихії. Побачивши, що стійка земля, жвавий вітер і тепло вогню вже пов'язані з духом шукача, вона готує його до випробувань, без яких не збагнути чистоти води."}},faq={{q="Хто посилає мене в цю подорож?",a="Наставники шаманів у Тандер Блафі, як-от Ксаніс Флеймвівер, дають це завдання, коли посвячуваний просунувся в духовному навчанні досить далеко, щоб узятися за обряди води.",al={"хто дає завдання","хто починає поклик води","де взяти поклик води"}},{q="Де знайти Іслен Вотерсір?",a="Іслен Вотерсір живе у відлюдній рибальській хатині на східному узбережжі Пусток. Її оселя стоїть на березі на південь від Раджета й на південь від місця, де Річка Південної Люті впадає в море.",al={"де іслен вотерсір","де іслен","знайти іслен"}},{q="Яка мета випробування «Поклик Води»?",a="Це випробування — неодмінний обряд посвяти для кожного шамана, що прагне єднання з водою. Воно перевіряє, як посвячуваний розуміє чистоту стихії, і веде просто до здобуття Тотема Води.",al={"навіщо поклик води","мета поклику води","завдання шамана на тотем води"}},{q="Чи отримують таке саме напучення інші раси Орди?",a="Хоча вступний виклик у Тандер Блафі зазвичай отримують таурени, шамани-орки й тролі в Оргріммарі та Сен'джині отримують подібні заклики розшукати Іслен Вотерсір на узбережжі Пусток.",al={"чи це лише для тауренів","орки поклик води","тролі поклик води"}},{q="Які стихії шаман має опанувати перед водою?",a="Шаман єднається з непохитною землею й руйнівним, але життєдайним вогнем, перш ніж шукати плинної природи води. Як зауважує Іслен, коли ви прибуваєте, земля, вітер і вогонь уже мають торкнутися вашого духу, перш ніж вода відкриє свою чистоту.",al={"що спершу","які тотеми спершу","порядок стихій"}},{q="Що буде, коли знайдеш Іслен Вотерсір?",a="Розмова з Іслен завершує першу подорож із Тандер Блафа. Вона одразу дає вам нові випробування по всьому Калімдору, щоб ви збагнули й очистили стихію води безпосередньо.",al={"що далі","після зустрічі з іслен","поклик води частина 2"}}},fp="13,329,24.438.0,23.499.0,29.177.0,33.187.0,47.195.0,51.195.0,48.246.0,43.195.0"}
P.entries["quest:153"] = {n="Червоні шкіряні бандани",s="«Червоні шкіряні бандани» — завдання на винагороду від Розвідника Ґаліаана в Сентінел Гіллі у Вестфолі. Поки Народне ополчення насилу стежить за Братством Дефіас на рівнинах, Ґаліаан обіцяє винагороду кожному, хто прорідить їхні лави й принесе характерні червоні маски, які носять розбійники.",h="«Червоні шкіряні бандани» — завдання на винагороду від Розвідника Ґаліаана в Сентінел Гіллі у Вестфолі.",kw={"червоні шкіряні бандани","розвідник ґаліаан","братство дефіас","сентінел гілл","народне ополчення","вестфол"},ang={["class:Rogue"]="Багряні маски грабіжників Дефіасу — похмуре нагадування про те, як вправні розбійники й злодюжки згуртувалися в цілу армію на порозі Стормвінда.",["faction:Alliance"]="Виконуючи замовлення Народного ополчення, ви безпосередньо підтримуєте місцеву оборону Вестфолу там, де королівська влада Стормвінда не надсилає допомоги."},sec={{t="Знак вірності",b="По всьому Вестфолу червона бандана стала безпомильною візитівкою Братства Дефіас. Хоч ця зграя набирає звичайних злодюжок, мародерів і зрадників з усіх верств, вона згуртовує свої лави під цим багряним знаменом. Для Розвідника Ґаліаана й знесиленого Народного ополчення в Сентінел Гіллі ці трофеї служать двом цілям: підтверджують знищення розбійників і дають відомості про те, як зміщуються їхні позиції в краї."},{t="Розвідка ополчення",b="Стормвінд відмовляє Вестфолу в належному військовому підкріпленні, тож Народне ополчення значною мірою покладається на досвідчених спостерігачів на кшталт Розвідника Ґаліаана, щоб стежити за діями Дефіасу. Ґаліаан днями відстежує розбійницькі патрулі з безпечного Сентінел Гілла, покладаючись на мандрівних шукачів пригод і добровольців ополчення, які виконують криваву роботу — вибивають грабіжників, що зігнали чесних фермерів з їхньої землі."}},faq={{q="Чому Дефіас носять червоні шкіряні бандани?",a="Червона шкіряна бандана — спільна уніформа й знак вірності Братству Дефіас. Вона приховує обличчя колишніх робітників, злодіїв і розбійників і сіє жах серед фермерів, що ще лишилися у Вестфолі.",al={"що означають червоні маски дефіас","чому червоні маски","бандани дефіас лор"}},{q="Хто такий Розвідник Ґаліаан?",a="Розвідник Ґаліаан — член Народного ополчення на Сентінел Гіллі. Він стежить за пересуваннями й мінливими фронтами Братства Дефіас по всьому Вестфолу й призначає шукачам пригод винагороди, щоб приборкати розбій.",al={"розвідник ґаліаан","хто дає червоні шкіряні бандани","розвідник сентинел гілла"}},{q="Навіщо ополченню шукачі пригод, щоб збирати ці бандани?",a="Народне ополчення відчайдушно розпорошене й діє без королівських вояків і грошей зі Стормвінда. Призначаючи винагороди за докази вбитих бандитів, розвідники на кшталт Ґаліаана можуть потроху підточувати сили Дефіас, не оголюючи оборону Сентінел Гілла.",al={"навіщо збирати бандани","навіщо ополченню винагорода"}},{q="Де знайти бандитів із цими банданами?",a="Розбійники Дефіас никають майже в кожному закутку Вестфолу: засіли на покинутих хуторах, чатують на перехрестях і отаборилися на Золотому Узбережжі й довкола пагорбів Мунбрука.",al={"де знайти бандани дефіас","де дефіас у вестфолі"}},{q="Що буває з банданами, коли їх здаєш?",a="Розвідник Ґаліаан використовує їх як доказ знищених розбійників, щоб стежити за їхніми мінливими фронтами й оцінювати, наскільки походи ополчення зменшують чисельність Братства в краї.",al={"що ґаліаан робить з банданами"}},{q="Чи причетна до цієї винагороди армія Стормвінда?",a="Ні. Військо Стормвінда здебільшого покинуло Вестфол, зосередившись на інших внутрішніх клопотах, і місцева оборона цілком лягла на Ґраяна Стаутмантла й добровольців Народного ополчення.",al={"гвардія стормвінда у вестфолі","чи допомагає стормвінд сентинел гіллу"}}},fp="20,307,20.481.0,30.406.0,44.237.0,21.233.0,64.273.0,52.177.0,52.183.0,46.195.0"}
P.entries["quest:1530"] = {n="Поклик води",s="Цей етап шляху «Поклику води» веде молодих шаманів Орди у ворожі південні околиці Пусток. Іслен Вотерсір посилає мандрівників розшукати самітницю на ім'я Брайн, щоб поглибити їхнє розуміння очисної й цілющої природи води.",h="Цей етап шляху «Поклику води» веде молодих шаманів Орди у ворожі південні околиці Пусток.",kw={"поклик води","іслен вотерсір","брайн","шаман","водяна сапта","пустки"},ang={["class:Shaman"]="Єднання з водою — важлива віха в розвитку шамана: воно доповнює бойову землю й мінливий вогонь цілющою силою відновлення.",["faction:Horde"]="Новачки Орди мандрують неосяжними просторами Калімдору, щоб опанувати стихії, і виявляють шану духам, які дають шаманам Вождя їхню життєдайну магію."},sec={{t="Уроки припливу",b="Перш ніж дати доступ до водяної сапти, Іслен Вотерсір закарбовує в серці новачка головну істину: вода — це відродження. Її течія здатна точити камінь, змивати нечистоту й загоювати плоть, але її цілюща сила цілком залежить від чистоти. Забруднена вода несе пошесть, а не життя, — і цю тендітну рівновагу кожен шаман мусить збагнути, перш ніж пробувати єднатися зі стихією."},{t="Самітниця серед пилу",b="Щоб рушити далі, новачки мусять вирушити далеко на південь посушливих Пусток і знайти Брайн. Вона обрала самотнє життя серед невпинних набігів шипогривів і живе без варти й без страху, бо володіє тими знаннями й випробуваннями, які потрібні, щоб скріпити зв'язок новачка з водою."}},faq={{q="Хто така Іслен Вотерсір?",a="Іслен Вотерсір — майстриня-шаманка, що оселилася на узбережжі Пусток, на південь від Узбережжя Крамарів. Вона веде шаманів Орди крізь випробування, потрібні, щоб єднатися з духами води.",al={"іслен","вотерсір","хто дає це завдання"}},{q="Навіщо жити на півдні Пусток серед шипогривів?",a="Брайн живе сама в південних пустищах, попри постійні напади шипогривів. Вона визнає, що стороннім ця небезпека здається безглуздою, але про свої мотиви мовчить, перевіряючи, чи вистачить посвячуваним стійкості її розшукати.",al={"чому брайн там живе","брайн шипогриви","де брайн"}},{q="Для чого потрібна водяна сапта?",a="Сапта — обрядова суміш, що змінює сприйняття шамана й дає йому змогу бачити духів стихій, невидимих смертному оку, і спілкуватися з ними.",al={"сапта","навіщо водяна сапта","чому брати водяну сапту"}},{q="Якого головного уроку навчає шамана вода?",a="Вода втілює відродження, очищення й оновлення. Вона має неперевершену цілющу силу, але, коли зіпсована чи застояна, може спричинити нищівний тлін і спустошення.",al={"урок води","значення стихії води","відродження води"}},{q="Хто може вирушити в цю подорож?",a="До випробувань «Поклику Води» спрямовують лише шаманів Орди, які довели свою відданість і вже налаштувалися на духів землі й вогню.",al={"хто отримує поклик води","чи поклик води лише для орди"}},{q="Які загрози чатують на шляху до Брайн?",a="Південні Пустки небезпечні: тут лютують агресивні племена шипогривів, що боронять свої колючі лігва, і никають звірі, які полюють на необачних мандрівників далеко від безпечного Перехрестя чи Табору Тауражо.",al={"небезпеки півдня пусток","шлях до брайн"}}},fp="13,261,19.391.0,21.271.0,23.194.0,56.238.0,39.171.0,50.172.0,31.154.0,38.210.0"}
P.entries["quest:1532"] = {n="Поклик повітря",s="«Поклик повітря» — важлива віха на духовному шляху шамана Орди: він має шукати єднання з непередбачуваною стихією вітру. Це завдання дає Ксаніс Флеймвівер у Тандер Блафі; досвідчені учні вирушають на південь, до Тисячі Голок, щоб навчатися в Прейт Клаудсір. Опанувавши повітря, шаман здобуває священний тотем, потрібний, щоб спрямовувати найшвидші сили природи.",h="«Поклик повітря» — важлива віха на духовному шляху шамана Орди: він має шукати єднання з непередбачуваною...",kw={"поклик повітря","шаман","прейт клаудсір","ксаніс флеймвівер","тотем повітря","тисяча голок","вітер"},ang={["class:Shaman"]="Завершення набору стихій — глибокий переломний момент: вам відкриваються прудкі течії й оповиті блискавками сили Тотема Повітря.",["faction:Horde"]="Зв'язуючи дикі вітри Калімдору у священний тотем, шамани Орди зміцнюють духовний хребет свого молодого союзу.",["race:Tauren"]="Дивлячись униз із височенних круч Малгору, шу'гало шанують вітри як священних вісників, що несуть шепіт Земної Матері над рівнинами."},sec={{t="Шепіт вітрів",b="Уже налаштувавшись на стійкість землі, лютість вогню й цілющі глибини води, шаман сягає останньої опори стихій — повітря. Ксаніс Флеймвівер, що веде учнів із висот Тандер Блафа, визнає, що вітри значно мінливіші й важче піддаються контролю, ніж попередні стихії. Випробування вимагає смирення, зосередженості й вродженої поваги до бурхливої вдачі неба."},{t="Паломництво на південь",b="Щоб налаштуватися на вітри, шаман мусить пройти на південь повз широкі рівнини Пусток і спуститися в обточені вітром каньйони Тисячі Голок. Там, далеко на сході, живе містикиня-самітниця Прейт Клаудсір. У відлюдній печері на кручі, де протяги каньйону виють день і ніч, вона перевіряє готовність учня, а тоді вручає Тотем Повітря — знаряддя, без якого не прикликати поривів вітру, блискавок і прудких духів вітру."}},faq={{q="Хто посилає мене з цим завданням?",a="Ксаніс Флеймвівер, наставник шаманів у Тандер Блафі, пропонує це завдання, щойно посвячуваний набуде досить досвіду, щоб налаштуватися на стихію повітря.",al={"хто дає завдання","хто починає поклик повітря","ксаніс флеймвівер"}},{q="Де знайти Прейт Клаудсір?",a="Прейт Клаудсір живе в захищеній печері далеко на сході продуваного вітрами каньйону Тисячі Голок, трохи на південь від Пусток.",al={"де прейт клаудсір","де прейт","знайти прейт клаудсір"}},{q="Чому стихію повітря шукають останньою?",a="Повітря сумнозвісно мінливе, раптове й невловиме. Шаманська традиція вимагає, щоб посвячуваний спершу опанував заземлену непохитність землі, мінливий жар вогню й плинність води, а тоді вже намагався приборкати дикі, невидимі потоки вітру.",al={"чому повітря останнім","лор тотема повітря шамана","порядок стихій"}},{q="Що я отримаю, коли знайду Прейт Клаудсір?",a="Прейт Клаудсір вручає вам Тотем Повітря — духовний провідник, що дає змогу зосереджувати магію стихій і кликати на допомогу духів повітря.",al={"нагорода тотема повітря","що дає прейт","нагорода поклику повітря"}},{q="Чи це завдання лише для тауренів?",a="Хоча воно починається в столиці тауренів Тандер Блафі, будь-який шаман Орди, що налаштувався на перші три стихії, може вирушити цим шляхом до Тисячі Голок по свій Тотем Повітря.",al={"чи можуть орки це виконати","чи це лише для тауренів","завдання повітря шамана орди"}},{q="Що буде після завершення цього завдання?",a="Прейт Клаудсір вручає вам Тотем Повітря, щойно ви прибуваєте, і ви одразу можете закликати тотеми вітру, а вона пропонує подальше навчання й випробування, щоб зміцнити ваш зв'язок із небом.",al={"що далі","після поклику повітря","завдання прейт клаудсір"}}},fp="11,391,20.426.0,18.452.0,27.160.0,33.135.0,38.258.0,47.159.0,34.179.0,40.183.0"}
P.entries["quest:1534"] = {n="Поклик води",s="Це завдання — останнє випробування зі збирання на шляху шамана до «Поклику води». За вказівкою самітниці Брайн із південних Пусток новачки вирушають далеко на північ, у чужі сутінкові гаї Ашенвалю, щоб набрати чистої води з прадавнього фонтана в Руїнах Зоряного Пилу.",h="Це завдання — останнє випробування зі збирання на шляху шамана до «Поклику води».",kw={"поклик води","брайн","руїни зоряного пилу","ашенваль","тотем води","шаман"},ang={["class:Shaman"]="Цей обряд перевіряє, чи готовий шаман перетинати небезпечні кордони заради рівноваги й здобути останню рідку суть, потрібну, щоб скріпити Тотем Води.",["faction:Horde"]="Щоб потрапити в Ашенваль, доведеться заглибитися в прадавні землі калдореїв, де Дозорці Пісні Війни ведуть затяжну війну за деревину з ворожими Вартовими нічних ельфів.",["race:Tauren"]="Паломництво поєднує посушливу батьківщину в центральному Калімдорі зі священними, вкритими росою гаями, про які пам'ятають міфи й пісні старійшин."},sec={{t="Подорож у Сутінковий Гай",b="Набравши зразки і з водопою під її хатиною в Пустках, і з чистого колодязя Таррен Мілла, шаман має знайти третю, останню суть. Брайн посилає новачка за північний кордон сухих рівнин, в Ашенваль — густий прадавній ліс, священний для нічних ельфів. Контраст між посушливими Пустками й глибоким лісовим наметом Ашенвалю підкреслює стихійне розмаїття, яке шаман мусить збагнути, щоб справді жити в злагоді з водою."},{t="Руїни Зоряного Пилу",b="Біля гірського перевалу, що відділяє Ашенваль від Гір Кам'яного Кігтя, за мерехтливою гладдю Озера Містраль, ховаються Руїни Зоряного Пилу. Це відлюдне ельфійське святилище плекає незайманий фонтан серед тихих вод і прадавнього каміння. Хоч тут панує дикий спокій, руїни стережуть неприборкані духи стихій і природи, які не люблять зайд, тож шаманові доводиться ступати обережно, щоб набрати священної води з фонтана."},{t="Напій найчистішої води",b="Повернення до Брайн із наповненим синім бурдюком завершує паломництво через Калімдор і Східні Королівства. Поєднавши чистий зразок з ельфійського фонтана з водою з водопою в Пустках і з Таррен Мілла, Брайн готує фіал довершеної чистоти. Цей напій стає каталізатором наступного випробування — єднання з духами водяних елементалів за посередництвом Іслен Вотерсір."}},faq={{q="Де розташовані Руїни Зоряного Пилу?",a="Руїни Зоряного Пилу лежать у південно-західному Ашенвалі. Перейшовши з Пусток на північ, ідіть дорогами на захід повз Озеро Містраль до передгір'їв на межі з Горами Кам'яного Кігтя.",al={"де руїни зоряного пилу","де зоряний пил","як дістатися руїн зоряного пилу"}},{q="Навіщо Брайн вода з ельфійських руїн?",a="Щоб єднатися з духами води, шаман має зібрати воду, що уособлює різні прояви цієї стихії. Фонтан у Руїнах Зоряного Пилу береже давню, магічно чисту воду, не торкнуту посушливою пошестю Пусток, і вона доповнює трійцю сутностей, потрібних для обрядової суміші Брайн.",al={"чому вода з ашенвалю","чому руїни зоряного пилу","навіщо вода зі зоряного пилу"}},{q="Які загрози чатують довкола Руїн Зоряного Пилу?",a="Руїни й довколишні води стережуть звірі-захисники й духи природи, зокрема ревниві до своїх володінь водяні елементалі й звірі з нетрів Ашенвалю, що нападають на кожного, хто потривожить гай.",al={"вороги зоряного пилу","чи небезпечний зоряний пил","хто охороняє фонтан"}},{q="Хто така Брайн і чому вона допомагає?",a="Брайн — орчиха-шаманка й аскетка, що живе у відлюдній хатині на півдні Пусток. Вона — старша провідниця, що допомагає Іслен Вотерсір, перевіряючи майбутніх шаманів на терплячість, витривалість і розуміння багатьох облич води, перш ніж дарувати благословення цієї стихії.",al={"хто така брайн","брайн лор","яка роль брайн"}},{q="Що буде, коли принесеш цю воду Брайн?",a="Отримавши третій зразок, Брайн поєднує їх у напій найчистішої води. Тоді вона посилає шамана назад до Іслен Вотерсір на східному узбережжі Пусток, щоб розпочати єднання з елементалями у видінні.",al={"наступний крок поклику води","що буде далі","куди йти після брайн"}},{q="Чи безпечний Ашенваль для шаманів Орди низьких рівнів?",a="Ашенваль — спірна територія, де сходяться нічні ельфи й Орда. Хоча шлях південними лісами оминає великі поселення нічних ельфів на кшталт Астранаару, бродячі звірі, агресивні елементалі й патрулі Альянсу становлять для посвячуваного справжню небезпеку.",al={"чи небезпечний ашенваль","рівень для ашенваля"}}},fp="13,306,31.489.0,21.457.0,27.423.1,40.204.0,45.299.0,48.209.0,36.268.0,48.224.1,46.268.0"}
P.entries["quest:1535"] = {n="Поклик води",s="Це завдання — перше випробування зі збирання, яке дає Брайн у Пустках під час налаштування шамана на воду. Щоб зварити водяну сапту, Брайн посилає новачків набрати зразок із пильно стереженого водопою під її хатиною й закликає замислитися над священною і спірною природою життєдайної води в пустелі.",h="Це завдання — перше випробування зі збирання, яке дає Брайн у Пустках під час налаштування шамана на воду.",kw={"поклик води","брайн","водопій","шипогриви","шаман","пустки"},ang={["class:Shaman"]="Це випробування вчить шаманів, що стихія води — це не лише зцілення й відновлення, а й причина сутичок і відчайдушної боротьби життя за виживання.",["faction:Horde"]="Розподіл і контроль води лишаються найбільшим викликом освоєння Пусток, де ворожі племена й звірі постійно б'ються за кожну цівку."},sec={{t="Урок у пустелі",b="Перш ніж дати водяну сапту, потрібну для розмови з духами, самітниця Брайн вимагає від новачків-шаманів вивчити воду в усіх її формах по всьому світу. У посушливих Пустках вода — це межа між виживанням і голодною смертю. Брайн велить шаманам спостерігати не лише за самою рідиною, а й за довкіллям: як ліси буяють у її обіймах, як пустелі марніють без неї і як живі істоти готові вбивати, щоб захистити навіть найскромніше джерельце."},{t="Скарб шипогривів",b="Водопій під пагорбом Брайн люто стережуть місцеві шипогриви. Для них кожна калюжа — безцінний скарб, і щоразу, як небо зласкавиться на дощ, вони влаштовують бенкети. Брайн шкодує про неминуче насильство, яке породжує ця жадібність, але зауважує, що замкнена в собі жадоба й розбрат між кланами не дають загрозі шипогривів поширитися, — так зберігається хитка рівновага для інших народів, що намагаються вижити на рівнинах."}},faq={{q="Навіщо збирати воду для Брайн?",a="Брайн потрібні зразки чистої води з різних куточків світу, щоб зварити обрядову водяну сапту. Цей напій відкриває посвячуваному сприйняття й дає змогу єднатися з духами стихії води напряму.",al={"навіщо брати воду","завдання брайн з водою","мета третього поклику води"}},{q="Чому за водопій під хатиною Брайн так запекло борються?",a="У посушливих Пустках вода — найцінніший скарб. Місцеві шипогриви шанують кожну водойму як священне багатство й люто б'ються з кожним, хто спробує з неї набрати.",al={"чому шипогриви охороняють воду","водойма шипогривів","водопій пусток"}},{q="Хто така Брайн?",a="Брайн — літня самітниця, що живе у відлюдній хатині над південними Пустками. Вона має глибоку мудрість щодо води й духів стихій і веде шаманів Орди їхнім шляхом єднання.",al={"хто така брайн","брайн пустки","нпц брайн"}},{q="Що буде, коли повернеш наповнений коричневий бурдюк?",a="Коли ви повертаєтеся зі зразком із водопою, Брайн розширює ваше паломництво й посилає вас далі — набрати незайманої води в зовсім інших краях, як-от із колодязя Таррен Мілла в Передгір'ї Гілсбреда.",al={"що далі поклик води","після водопою","наступний крок брайн"}},{q="Чому Брайн говорить про роз'єднаність шипогривів?",a="Брайн помічає, що люта ревнивість шипогривів до своїх земель і ворожнеча кланів лише множать їхні власні нещастя. Якби вони колись об'єднали сили, замість битися за відокремлені джерела, то становили б куди більшу небезпеку для решти Пусток.",al={"що брайн каже про шипогривів","чому шипогриви б'ються між собою"}},{q="Що таке сапта?",a="Сапта — містичний еліксир, який шамани готують із зібраних реагентів і вод, налаштованих на стихію. Випивши його, отримуєш ширший духовний зір, що відкриває істот стихій, зазвичай схованих від смертних очей.",al={"що таке сапта","що значить водяна сапта"}}},fp="13,326,22.466.0,20.449.0,50.215.0,58.187.0,13.203.0,56.227.1,49.248.0,16.208.0"}
P.entries["quest:1536"] = {n="Поклик води",s="Це паломництво веде молодого шамана з посушливих Пусток за море, у спірне Передгір'я Гілсбреда. Там, у селищі Таррен Мілл, яке тримають Відступники, є невеликий колодязь, що дивом лишився чистим серед довколишнього тліну. Набираючи з нього воду, новачок пізнає, як чистота й надія можуть вистояти навіть серед найтемніших місць.",h="Це паломництво веде молодого шамана з посушливих Пусток за море, у спірне Передгір'я Гілсбреда.",kw={"поклик води","таррен мілл","передгір'я гілсбреда","брайн","водяна сапта","тралл"},ang={["class:Shaman"]="Принести воду з іншого кінця світу — випробування відданості: воно вчить вас шукати злагоди й життя навіть серед гірких земель Східних Королівств.",["faction:Horde"]="Подорож до Таррен Мілла зводить молодих воїнів і шаманів Орди, народжених у Калімдорі, віч-на-віч із їхніми непевними новими союзниками — Відступниками — і з війною проти людських оборонців Гілсбреда.",["race:Orc"]="Це випробування дає нагоду замислитися над незламною спадщиною Тралла — його вмінням вижити й силою — і нагадує оркам про високу ціну їхньої свободи."},sec={{t="Дивовижне джерело",b="Готуючи складники для Водяної Сапти, самітниця Брайн посилає новачків далеко за море, до Таррен Мілла в Передгір'ї Гілсбреда. Серед людського опору й зачумленої присутності нових союзників-Відступників невеликий колодязь посеред селища напрочуд дає чисту, неосквернену джерельну воду. Для Брайн це джерело — священний пережиток, острівець чистоти посеред оскверненого моря."},{t="Витривалість у темряві",b="Для Брайн чистий колодязь Таррен Мілла — більше, ніж складник: це глибокий урок стійкості. Вона порівнює його вцілілість із самим Вождем Траллом, який наперекір усьому пережив тяжкі злигодні, неволю й горе, перш ніж очолив оркський народ. Як Тралл став для Орди маяком відродженої надії, так і колодязь Таррен Мілла доводить, що життя й чистота можуть вистояти серед трагедії та скверни."}},faq={{q="Де набирають зразок води?",a="Зразок набирають просто з міського колодязя в центрі Таррен Мілла — старого людського поселення в Передгір'ї Гілсбреда, яке тепер зайняли Відступники.",al={"вода таррен мілл","де колодязь","де колодязь поклику води"}},{q="Чому Брайн посилає вас по воду так далеко?",a="Брайн потрібні особливі сутності води, щоб зварити Водяну Сапту — напій, що дає шаманам змогу бачити духів стихій. Вона знайшла це джерело під час давньої подорожі до Гілсбреда й вважає, що його незмінна чистота посеред тліну Відступників має силу стихії й повчальна для духу.",al={"чому таррен мілл","чому вода хілсбрада","навіщо брайн ця вода"}},{q="Що таке Таррен Мілл?",a="Колись Таррен Мілл був скромним людським містечком на півночі Передгір'я Гілсбреда. Після Третьої війни й падіння Лордерона він опинився під владою Відступників Сильвани Віндраннер, які тепер тримають його як укріплену заставу Орди проти людських сил у краї.",al={"історія таррен мілл","кому належить таррен мілл"}},{q="Як це завдання пов'язане з Траллом?",a="Брайн порівнює незіпсований колодязь із Вождем Траллом. Як колодязь зберігає свіжу чистоту, хоч довкола чума й смерть, так і Тралл пережив рабство й тяжкі страждання, зберігши моральну стійкість і далекоглядність, потрібні, щоб вести нову Орду.",al={"діалог брайн і тралла","зв'язок з траллом"}},{q="Що буде, коли повернеш наповнений бурдюк?",a="Брайн приймає наповнений червоний бурдюк і повідомляє, що потрібен ще лише один окремий зразок води, і тоді вона зможе завершити суміш реагентів для вашої Водяної Сапти.",al={"що далі поклик води","після води таррен мілл"}},{q="Чому чистота колодязя вважається незвичною?",a="Більша частина Лордерона зазнала катастрофічного осквернення від чуми нежиття, яку поширила Погибель, а поселення Відступників рідко асоціюються зі свіжими, живими джерелами. Те, що центральний колодязь Таррен Мілла досі дає чисту воду, робить його рідкісним незіпсованим залишком минулого.",al={"чому вода таррен мілл чиста","занедбані отруїли колодязь"}}},fp="13,377,19.416.0,21.435.0,36.167.0,46.297.0,20.265.0,38.277.0,50.173.0,44.269.0"}
P.entries["quest:154"] = {n="Поверни гребінь",s="«Поверни гребінь» — доручення Альянсу в Сутінколіссі, що завершує моторошну угоду з духом Сліпої Мері. Отримавши гребінь, яким мали зібрати пасма її примарного волосся, змучена привидиця впадає у відчай через утрачену вроду й відкидає його. Повернений гребінь із волоссям дає Мадам Єві змогу спрясти ефірну Нитку з Примарного Волосся.",h="«Поверни гребінь» — доручення Альянсу в Сутінколіссі, що завершує моторошну угоду з духом Сліпої Мері.",kw={"поверни гребінь","сліпа мері","мадам єва","нитка з примарного волосся","даркшир","привид"},ang={["class:Priest"]="Болісна ненависть Сліпої Мері до себе — похмурий урок про муки неспокійних духів, яких прив'язує до смертного світу горе, а не злоба.",["faction:Alliance"]="Мандруючи похмурими шляхами між Даркширом і безлюдною оселею Мері, ви бачите, як глибоко розклад охопив саме серце Сутінколісся.",["profession:Tailoring"]="Прядіння Нитки з Примарного Волосся відкриває моторошні ремесла Сутінколісся й доводить, що примарну сировину можна зібрати й вичесати на міцну надприродну тканину."},sec={{t="Гірке відображення",b="Сліпа Мері блукає в напівзруйнованій хатині на південь від Даркшира, вічно оплакуючи свою трагічну смерть і змінену подобу. Коли до неї підходять із гребенем Мадам Єви, нагадування про буденне розчісування лише поглиблює її печаль. Усвідомивши, що тепер вона лише примара — потвора, позбавлена земної краси, яку вже ніхто й ніколи не покохає, — Мері з жахом відсахується й тицяє гребінь разом із примарним волоссям, що заплуталося в зубцях, назад у руки мандрівника."},{t="Ткання надприродного",b="Мадам Єва чекає на гребінь у Даркширі, добре розуміючи моторошну природу доручення. Здобувши примарне волосся, ворожка має рідкісний духовний матеріал, щоб спрясти котушку Нитки з Примарного Волосся. Єва пряде з цих ефірних волокон нитку й платить мандрівникам за всі волосинки, що лишилися після тонкої роботи."}},faq={{q="Чому Сліпа Мері з жахом реагує на гребінь?",a="Гребінь нагадує Сліпій Мері про її смертне життя й красу. Усвідомлення, що вона перетворилася на висохлу примарну подобу, викликає вибух горя: вона відкидає гребінь і нарікає, що стала чудовиськом, якого ніхто вже ніколи не плекатиме.",al={"чому мері засмучена","чому сліпа мері кричала","реакція мері на гребінь"}},{q="Що Мадам Єва робить із волоссям на гребені?",a="Мадам Єва пряде з пасм, зібраних гребенем, Нитку з Примарного Волосся — містичну нитку на тисячу ладів: від зв'язування лихих духів до вшивання життя в неживі предмети.",al={"навіщо примарне волосся","що єва робить з примарним волоссям","мадам єва нитка"}},{q="Де знайти Сліпу Мері?",a="Сліпа Мері блукає покинутою, напівзруйнованою хатиною трохи на південь від Даркширу, біля Цвинтаря Тихих Садів у Сутінколіссі.",al={"де сліпа мері","місце сліпої мері"}},{q="Хто така Мадам Єва?",a="Мадам Єва — загадкова містикиня й віщунка-людина з Даркширу. Вона ворожить, дає туманні настанови й виготовляє магічні дрібнички та реагенти для тих, хто долає небезпеки Сутінколісся.",al={"хто така мадам єва","єва даркшир"}},{q="Що далі, коли повернеш гребінь Мадам Єві?",a="Коли Мадам Єва забирає гребінь і готує моток Нитки з Примарного Волосся, вона просить вас доставити готову нитку Аберкромбі — самітникові, що живе біля Цвинтаря Воронячого Пагорба.",al={"що далі","наступне завдання після гребеня"}},{q="Чому Мадам Єва дає вам монети наприкінці?",a="Єва зауважує, що гребінь дав примарного волосся більш ніж досить на потрібний моток нитки, і платить вам кілька монет, викуповуючи зайві пасма для власного вжитку.",al={"чому я отримую монети","гроші за пасма"}}},fp="15,389,19.452.0,24.362.0,50.248.0,50.180.0,28.126.0,18.209.0,52.182.1,51.189.0"}
P.entries["quest:155"] = {n="Братство Дефіас",s="На цьому вирішальному етапі розслідування Народне ополчення здобуває прорив завдяки розбійникові-перебіжчику. В обмін на захист Зрадник Дефіасу погоджується провести героїв Альянсу просто до схованої бази Братства. Шлях пролягає крізь захоплене місто-привид Мунбрук — до таємного лігва Едвіна Венкліфа.",h="На цьому вирішальному етапі розслідування Народне ополчення здобуває прорив завдяки розбійникові-перебіжчику.",kw={"братство дефіас","зрадник дефіасу","мунбрук","мертві копальні","едвін венкліф","вестфол"},ang={["class:Rogue"]="Пліч-о-пліч із колишнім розбійником Дефіасу ви бачите сувору ціну зради в злочинному підпіллі, де на порушені клятви відповідають кинджалами.",["faction:Alliance"]="Викриття схованки — великий військовий прорив для знесиленого Народного ополчення, що дає першу справжню нагоду завдати вирішального удару злочинному заколоту у Вестфолі.",["race:Human"]="Для людей Стормвінда вид Мунбрука, що поринув у беззаконня й опинився в руках колишніх каменярів, показує, як глибоко розкололося королівство після Третьої війни."},sec={{t="Угода перебіжчика",b="Кампанія Ґраяна Стаутмантла проти Братства Дефіас досягає переломного моменту, щойно схоплений розбійник погоджується говорити. Перед загрозою страти чи ножа від колишніх побратимів Зрадник Дефіасу укладає угоду з Народним ополченням: його безпечно проведуть ворожою землею, а він покаже, де переховуються Едвін Венкліф і його ватажки. Знаючи, що злодійська мережа безжально змушує замовкнути кожного, хто розпускає язика, перебіжчик потребує озброєної охорони на кожному кроці."},{t="Дорога крізь Мунбрук",b="Шлях до схованки веде від Сентінел Гілла просто на південний захід, до Мунбрука — містечка, цілком захопленого Братством. Зрадник веде своїх охоронців повз покинуту міську площу й фонтан, накликаючи лють кожного грабіжника, мародера й розбійника з великої дороги, що патрулює руїни. Перебіжчик приводить їх просто до входу в розлогі Мертві Копальні під Мунбруком — і найгірші побоювання ополчення справджуються: Венкліф облаштував підземну твердиню просто під носом у Вестфолу."}},faq={{q="Хто такий Зрадник Дефіас?",a="Це колишній член Братства Дефіас, що став інформатором Ґраяна Стаутмантла й Народного ополчення. Боячись смерті від рук колишніх товаришів, він виміняв таємницю, де підземний сховок Едвіна Венкліфа, на супровід у безпечне місце.",al={"хто той зрадник","особа зрадника дефіас","щур дефіас"}},{q="Куди веде вас зрадник?",a="Він веде вас від Сентінел Гілла дорогою до Мунбрука, просто через зруйновану міську площу повз фонтан до входу в тунелі Мертвих Копалень під містечком.",al={"де схованка дефіас","шлях зрадника","куди він іде"}},{q="Навіщо ці відомості Ґраянові Стаутмантлу?",a="Хоча Народне ополчення билося з розбійниками по всьому Вестфолу, воно не знало, звідки Едвін Венкліф керує своїми справами. Знайдений вхід до його підземного лігва дає ополченню чітку ціль, щоб ударити в саме серце заколоту.",al={"навіщо супроводжувати зрадника","мета стаутмантла","навіщо шукати сховок"}},{q="Чому в Мунбруку аж кишить Дефіас?",a="Колись Мунбрук був квітучим хліборобським осередком, але коли Королівство Стормвінд занепало й прийшли бандити, мешканці покинули містечко. Братство Дефіас зайняло порожні будинки як наземний заслін, що стереже вхід до Мертвих Копалень.",al={"чому в мунбруку дефіас","захоплення мунбрука","кому належить мунбрук"}},{q="Що буде, коли знайдеш сховок?",a="Коли зрадник показує вхід до Мертвих Копалень, ви доповідаєте Ґраянові Стаутмантлу на Сентінел Гіллі. Маючи доказ, де Венкліф, ополчення готує прямий штурм підземного лігва.",al={"що далі","після супроводу дефіас","розвиток завдання"}},{q="Чому Братство хоче смерті зрадника?",a="Дефіас тримаються на таємності: вони діють із прихованих тунелів, керуючи справами по всіх землях Стормвінда. Перекинчик, що показує парадні двері їхнього головного осідку, загрожує розвалити всю змову.",al={"чому вбивати зрадника","дефіас нападають на зрадника"}}},fp="22,374,20.505.0,26.517.1,26.274.0,32.187.0,49.257.0,38.285.0,44.214.1,47.235.0"}
P.entries["quest:156"] = {n="Назбирай гнильоцвіт",s="Шинкареві Смітсу з Даркшира потрібен гнилоцвіт, щоб зварити партію його сумнозвісного «зомбі-соку». Ці моторошні рослини проростають просто з черепів кістяних жахіть і кістяних виродків, що нишпорять неспокійними цвинтарями Сутінколісся.",h="Шинкареві Смітсу з Даркшира потрібен гнилоцвіт, щоб зварити партію його сумнозвісного «зомбі-соку».",kw={"гнилоцвіт","шинкар смітс","зомбі-сік","кістяки","цвинтар тихих садів","цвинтар воронячого пагорба"},ang={["faction:Alliance"]="Полювання на нежить на цвинтарях Сутінколісся дає так потрібний перепочинок змученій Нічній Варті Даркшира, що щодня б'ється, аби місто не впало.",["profession:Herbalism"]="На відміну від звичайних трав, що буяють на родючому ґрунті під сонцем, гнилоцвіт — темна ботанічна аномалія, цілком укорінена в некромантичному тлінні й оживлених кістках."},sec={{t="Дивний інгредієнт",b="Більшість шинкарів пишаються витриманим елем і добрими винами, але Шинкар Смітс із Таверни «Багряний Крук» час від часу варить щось моторошніше. Його рецепт «зомбі-соку» вимагає гнилоцвіту — бридкої мертвотної рослинності, що пускає коріння в порожніх черепах оживлених кістяків. Сам Смітс достатньо розважливий, щоб ніколи не підходити до нежиті, тож моторошний збір лишає перехожим найманцям."},{t="Цвинтарна санітарія",b="Щоб зібрати ці квіти, доведеться порубати кістяні жахіття й виродків, що блукають зарослими ділянками Цвинтаря Тихих Садів чи просторами Цвинтаря Воронячого Пагорба. Місцеве ополчення Сутінколісся, Нічна Варта, завжди ледве встигає відбивати жахіття, що підкрадаються з лісу. Смітс подбає, щоб кожного шукача пригод, який наважиться пройтися поміж надгробків, належно відрекомендували Командирові Алтеї Ебонлок за винищення неспокійних мерців."}},faq={{q="Що таке гнильоцвіт?",a="Гнильоцвіт — гидка рослина, що проростає там, де все просякнуте темною магією й тліном. У Сутінколіссі вона росте просто в черепах ожилих скелетів-жахіть і скелетів-виродків.",al={"гнильоцвіт","що таке гнильоцвіт","звідки гнильоцвіт"}},{q="Навіщо Шинкареві Смітсу гнильоцвіт?",a="Смітс використовує квіти як головний складник для варива, відомого як «зомбі-сік», — міцного напою, якого просять деякі завсідники в цих краях.",al={"навіщо смітсу квіти","інгредієнти зомбі-соку","напій смітса"}},{q="Де знайти скелетів, на яких росте гнильоцвіт?",a="Скелети-жахіття й скелети-виродки збираються по всіх цвинтарях Сутінколісся, особливо на Цвинтарі Тихих Садів біля Даркширу й на просторому Цвинтарі Воронячого Пагорба на заході.",al={"де скелети","де гнильоцвіт","скелети тихих садів"}},{q="Чи допомагає це доручення обороні Даркширу?",a="Так. Даркшир виживає завдяки Нічній Варті, що відбиває безперервні напади нежиті. Смітс зауважує, що полювання на скелетів заради квітів допомагає Командирові Алтеї Ебонлок, проріджуючи чудовиськ, які загрожують містечку.",al={"чи допомагає нічна варта","олтея ебонлок вбивство скелетів"}},{q="Що далі, коли доставиш квіти?",a="Отримавши квіти й зваривши зомбі-сік, Смітс просить вас доставити готовий напій Аберкромбі — дивакуватому самітникові, що живе біля Цвинтаря Воронячого Пагорба.",al={"наступне завдання після гнильоцвіту","що після доставки соку"}},{q="Чи зомбі-сік — звичайний напій у Даркширі?",a="Ні. У Таверні «Багряний Крук» зазвичай подають звичайні місцеві страви. Зомбі-сік — химерне особливе вариво, яке Смітс готує лише тоді, коли отримує чудернацьке замовлення з некротичними складниками.",al={"чи зомбі-сік звичайний","напої багряного ворона"}}},fp="19,236,20.415.0,22.438.0,22.190.0,45.148.0,56.204.0,45.230.0,46.176.1,54.199.0"}
P.entries["quest:157"] = {n="Доправ нитку",s="«Доправ нитку» — доручення Альянсу в Сутінколіссі: котушку Нитки з Примарного Волосся треба перенести від Мадам Єви в Даркширі через проклятий ліс до Аберкромбі. Дивакуватий відлюдник, що живе біля Цвинтаря Воронячого Пагорба, запевняє, що зачарована нитка потрібна йому, аби вберегти благеньку хатину від неспокійних духів. Проте похмурі натяки Мадам Єви про нитку підказують, що в неї може бути значно зловісніше застосування.",h="«Доправ нитку» — доручення Альянсу в Сутінколіссі: котушку Нитки з Примарного Волосся треба перенести від...",kw={"доправ нитку","нитка з примарного волосся","мадам єва","аберкромбі","воронячий пагорб","сутінколісся"},ang={["class:Priest"]="Захищати дім від неспокійних мерців годиться святими обрядами Світла; покладатися ж на сплетені рештки самих мерців означає, що Аберкромбі ступає значно темнішою стежкою.",["faction:Alliance"]="Безпека Даркшира тримається на пильності, а кожна допомога самотньому відлюдникові через кишучі чудовиськами західні ліси ще більше розтягує й без того тонкий рубіж Нічної Варти.",["profession:Tailoring"]="Прясти з примарного волосся придатні котушки — не звичайне ткацтво: тут голкове ремесло поєднується з сільською некромантією, і виходить матеріал, здатний зшивати матерію поза межами фізичного світу."},sec={{t="Перехід у темряві",b="Щойно Мадам Єва допряде примарне волосся, зібране з привида Сліпої Мері, вона довіряє Нитку з Примарного Волосся кожному мандрівникові, готовому віднести її на захід. Дорога веде через темні простори Сутінколісся, повз павуків, що чатують у засідці, і блукаючу нежить, — до напівзруйнованої хижі Аберкромбі на північ від просторого цвинтаря."},{t="Нитки життя і смерті",b="Аберкромбі наполягає, що сплетене примарне пасмо потрібне йому, щоб обвести вікна й одвірок і не пустити в дім голосливих мерців Воронячого Пагорба. Але Мадам Єва прохоплюється, що нитка з примарного волосся має тисячу застосувань: нею можна сковувати лихих духів — а можна й вшивати подобу життя в мертву й неживу матерію. Відлюдник зустрічає котушку з величезною радістю — йому не терпиться пустити в хід своє потаємне ремесло."}},faq={{q="Що таке нитка з примарного волосся?",a="Це зачарований моток, який спряла Мадам Єва в Даркширі з волосся примари Сліпої Мері. За словами Єви, нитка має могутні окультні властивості: може зв'язувати духів чи вшивати життя в неживі предмети.",al={"примарне волосся","що за нитка","примарна нитка"}},{q="Хто такий Аберкромбі?",a="Аберкромбі — відлюдькуватий старий, що живе у відлюдній халупі трохи на північ від Цвинтаря Воронячого Пагорба. Він видає себе за нешкідливого, кволого самітника, що вічно жахається нежиті, яка никає біля його дому.",al={"відлюдник","хто такий аберкромбі","чоловік із халупи"}},{q="Навіщо, за словами Аберкромбі, йому нитка?",a="Аберкромбі розповідає гостям, що хоче протягнути примарне волосся вздовж вікон і дверей. Він запевняє, що його духовні властивості стануть оберегом, який не впустить небажаних гулів і духів, що блукають Сутінколіссям.",al={"навіщо нитка","відмовка аберкромбі","захист від духів"}},{q="Де знайти Аберкромбі?",a="Він живе у відлюдній дерев'яній халупі на північ від головної частини Цвинтаря Воронячого Пагорба, трохи осторонь західної дороги через Сутінколісся.",al={"де аберкромбі","де халупа","халупа відлюдника"}},{q="Що буде, коли віддаси нитку Аберкромбі?",a="Отримавши нитку, Аберкромбі нагороджує посланця й одразу починає нарікати на інші нагальні потреби, посилаючи мандрівників по дивні алхімічні складники на кшталт зомбі-соку.",al={"наступне завдання","що буде після","після доставки нитки"}},{q="Чи знає Мадам Єва, що замислив Аберкромбі?",a="Єва прямо не звинувачує Аберкромбі в лихих намірах, але в її загадкових прощальних словах ідеться про те, що примарним волоссям можна вшити життя в неживі предмети. Схоже, вона добре знає про некромантичну силу нитки, хоч і виконує замовлення без заперечень.",al={"чи єва знає","мадам єва поплічниця","застереження єви"}}},fp="18,414,22.355.0,25.386.1,26.228.0,19.212.0,47.217.0,29.147.0,52.207.0,47.261.0"}
P.entries["quest:1578"] = {n="Постачання фронту",s="Постачання фронту — раннє завдання для дворфійських ковалів-початківців, яке дає Тормус Діпфордж в Айронфорджі. Воно доручає ковалям кувати зброю й броню на підтримку горян, що стоять у Лох Модані проти невпинних набігів трогів.",h="Постачання фронту — раннє завдання для дворфійських ковалів-початківців, яке дає Тормус Діпфордж в...",kw={"постачання фронту","ковальство","тормус діпфордж","торвальд діпфордж","лох модан","горяни","мідна зброя"},ang={["faction:Alliance"]="Безпека кордонів Каз Модану береже гірські дороги, що з'єднують Айронфордж зі Стормвіндом і операціями Альянсу на півдні.",["profession:Blacksmithing"]="Це завдання — ранній обряд посвяти для майбутніх ковалів, що перевіряє їхнє вміння виготовляти надійну, однакову мідну зброю й броню для справжнього військового вжитку.",["race:Dwarf"]="Оборона Лох Модану напряму залежить від дворфійської майстерності, доводячи, що ремісник біля міхів не менш важливий для виживання королівства, ніж горянин із рушницею."},sec={{t="Озброюючи горян",b="У великих кузнях Айронфорджа майстер-коваль Тормус Діпфордж пильно стежить за кордонами королівства Каз Модан. Горянам, що боронять долини Лох Модану, доводиться сутужно через раптові напади трогів, які вириваються з розкопаних руїн і печер. Щоб їхні оборонні лінії мали все потрібне, необхідна безперервна зміна свіжих клинків, поясів і кріплень, тож до справи долучаються й місцеві ремісники."},{t="Рід Діпфорджів",b="Щоб постачати оборону, не відриваючи досвідчених майстрів від міських кузень, Тормус посилає учнів на схід до Лох Модану. Там його колега Торвальд Діпфордж тримає польовий арсенал у південній сторожовій вежі. Доправивши міцні мідні сокири й мідні ланцюгові пояси просто Торвальдові, ковалі доводять свою надійність і здобувають досконаліші ковальські прийоми."}},faq={{q="Хто дає це завдання і що потрібно?",a="Тормус Діпфордж, коваль із Великої Кузні в Айронфорджі, дає це доручення учням-ковалям із навичкою щонайменше тридцять. Треба викувати шість мідних сокир і шість мідних кольчужних поясів.",al={"хто дає постачання фронту","хто дає завдання","вимоги ковальського завдання"}},{q="Де знайти Торвальда Діпфорджа?",a="Торвальд Діпфордж у південній вартовій вежі Лох Модану. Щоб дістатися до нього, ідіть головною дорогою на південь повз Телсамар до кордону з Пустищами, де вежа стоїть біля гірського перевалу.",al={"де торвальд","місце торвальда","південна вартова вежа лох модан"}},{q="Навіщо горянам стільки мідного спорядження?",a="Горяни в Лох Модані постійно сходяться в сутичках із лютими трогами. У тяжких боях їхнє спорядження швидко щербиться, тупиться й ламається, тож потрібен нескінченний приплив простої зброї й кольчуг.",al={"навіщо їм сокири","навіщо мідь"}},{q="Ким Торвальд доводиться Тормусові?",a="Тормус називає Торвальда своїм колегою, а оскільки обидва носять родове ім'я Діпфордж, вони — тісно пов'язані майстри, що разом поєднують промислову міць Айронфорджа з польовою обороною.",al={"чи торвальд і тормус родичі","колега тормуса"}},{q="Яку нагороду дає Торвальд?",a="На знак вдячності за те, що ви полегшили постачання південної вартової вежі, Торвальд ділиться ремісничими знаннями й дає креслення нових обладунків.",al={"нагорода за завдання","чого навчає торвальд"}},{q="Чому троги саме зараз такі дошкульні в Лох Модані?",a="Недавні дворфійські розкопки відкрили підземні склепи й порожнини по всьому Каз Модану й ненароком розбудили й вивільнили зграї агресивних трогів, які тепер загрожують довколишнім поселенням і вартовим вежам.",al={"чому троги нападають","проблема трогів лох модан"}}},fp="19,259,23.405.0,21.389.0,43.205.0,36.215.0,53.221.0,36.194.0,40.146.0,57.219.0"}
P.entries["quest:1579"] = {n="Електромуфти",s="Візбанґ Кранктоґґл, гном-винахідник, що лікує похмілля в Обердайні, просить допомогти повернути ящик деталей, який він упустив у море. Утікши від гуркоту Айронфорджа до тихих берегів Калімдору, він під час подорожі впустив за борт свої незамінні електромуфти. Кожен, хто має вудку й терпіння, може виловити ці загублені деталі біля берега.",h="Візбанґ Кранктоґґл, гном-винахідник, що лікує похмілля в Обердайні, просить допомогти повернути ящик деталей...",kw={"електромуфти","візбанґ кранктоґґл","стінтлові кілочки","рибальство","обердайн","айронфордж"},ang={["profession:Engineering"]="Кожен інженер знає, яка це мука — бракує однієї крихітної нестандартної деталі, щоб завершити калібрування делікатного пристрою.",["race:Gnome"]="Візбанґ утілює непосидючу ексцентричність гномських майстрів, хоча навіть інших гномів може пересмикнути від його безрозсудного поєднання високоточних деталей і рясної випивки.",["race:NightElf"]="Тихі священні ліси Темного Узбережжя — дивне місце для грубуватого гнома-винахідника з похмілля, і це випробовує легендарне терпіння Вартових Обердайна."},sec={{t="Захаращений розум у тихій гавані",b="Шукаючи тиші й спокою подалі від оглушливого гуркоту Великої Кузні Айронфорджа, ексцентричний гном-винахідник Візбанґ Кранктоґґл переплив Велике Море до Темного Узбережжя. На жаль, під час переправи Візбанґ трохи перебрав з випивкою. Перехилившись через поручні в хмільному тумані, він примудрився впустити в прибережні води біля Обердайна цілий ящик особливих металевих деталей, відомих як електромуфти."},{t="Налаштування стінтлових кілочків",b="Звичайним перехожим електромуфти можуть видатися незрозумілими металевими уламками, але для Візбанґа це незамінні точні інструменти. Без них, каже він, неможливо як слід відкалібрувати стінтлові кілочки чи продовжити будь-яку тонку роботу. Не маючи бажання лізти в холодний морський прибій самому, гном покладається на місцевих рибалок, які закидають вудки біля берегів Темного Узбережжя й виловлюють розкидані деталі."}},faq={{q="Що таке електромуфти?",a="Електромуфти — невеликі гномські механічні кріплення й деталі. За словами Візбанґа Кранктоґґла, це вкрай потрібні спеціальні інструменти, якими він налаштовує стінтлові штифти у своїх винаходах.",al={"що таке електромуфта","навіщо електромуфти","предмет електромуфти"}},{q="Як електромуфти опинилися в морі?",a="Візбанґ Кранктоґґл трохи перебрав, пливучи кораблем зі Східних Королівств до Калімдору. Напідпитку він ненароком упустив за борт скриньку з припасами біля узбережжя Темного Узбережжя.",al={"як він їх загубив","чому вони у воді","навіщо виловлювати електромуфти"}},{q="Чому Візбанґ Кранктоґґл в Обердайні, а не в Айронфорджі?",a="Візбанґ обрав Обердайн саме заради тиші й спокою. Безупинний гуркіт, дзвін ковадл і галасливі майстерні Айронфорджа здавалися йому нестерпними, особливо коли він лікувався від постійного похмілля після важких пиятик.",al={"чому візбанґ в обердайні","чому візбанґ покинув айронфордж"}},{q="Де можна виловити загублені електромуфти?",a="Їх можна виловити у відкритій солоній воді вздовж узбережжя Темного Узбережжя біля Обердайна. Рибалки витягують їх, закидаючи вудку у звичайну прибережну воду, а не в окремі зграї риби.",al={"де ловити електромуфти","місце електромуфт"}},{q="Що буде, коли повернеш електромуфти?",a="Коли Візбанґ отримує електромуфти, щоб налаштувати штифти, він зізнається, що загубив у морі ще один важливий набір спорядження — свої електропеллери, які доведеться виловлювати чи діставати пірнаючи.",al={"що далі після електромуфт","завдання після електромуфт"}},{q="Чому Візбанґові потрібні шукачі пригод, а не дістати їх самому?",a="Через гостре похмілля й відсутність морського рибальського спорядження Візбанґ воліє безпечно сидіти на сухому на пристанях Обердайна, лишаючи марудну роботу будь-якому перехожому з вудкою.",al={"чому візбанґ сам не дістане","чому візбанґ не рибалить"}}},fp="12,380,33.436.0,23.442.0,22.203.0,43.225.0,61.243.0,45.182.0,47.219.1,69.189.0"}
P.entries["quest:158"] = {n="Зомбі-сік",s="«Зомбі-сік» — доручення для Аберкромбі, дивакуватого відлюдника з проклятої глушини Сутінколісся. Запевняючи, що його доймає гнітючий опівнічний холод, він посилає мандрівників до таверни Даркшира по надзвичайно міцне вариво.",h="«Зомбі-сік» — доручення для Аберкромбі, дивакуватого відлюдника з проклятої глушини Сутінколісся.",kw={"зомбі-сік","аберкромбі","шинкар смітс","багряний крук","даркшир","трунок"},ang={["faction:Alliance"]="Шукачі пригод з Альянсу, що підтримують обложений Даркшир, часто стають гінцями для дивакуватих відлюдників, які ховаються при небезпечних дорогах Сутінколісся."},sec={{t="Холодне прохання",b="Живучи сам-один серед жахіть темного лісу, відлюдник Аберкромбі часто посилає співчутливих мандрівників із дивними дорученнями. Нарікаючи, що вечірні сутінки висмоктують із нього тепло й силу, він просить шукача пригод вирушити на схід, до Даркшира. Там треба знайти Шинкаря Смітса з Таверни «Багряний Крук» і взяти в нього пляшку міцного трунку зі зловісною назвою Зомбі-Сік, щоб знову розпалити вогонь у жилах."},{t="У «Багряному Круку»",b="У таверні Даркшира чимало втомлених вартових і наляканих містян, але навіть Шинкар Смітс рідко чує, щоб хтось просив Зомбі-Сік. Цей трунок має славу небезпечно міцного. Смітс знає це вариво, але спрага Аберкромбі до такого моторошного питва викликає тихий подив у краї, і без того обложеному неспокійними мерцями."}},faq={{q="Що таке зомбі-сік?",a="Це надзвичайно міцний трунок із моторошною назвою, який продає Шинкар Смітс у Таверні «Багряний Крук» у Даркширі. Звичайні відвідувачі його рідко замовляють.",al={"напій зомбі-сік","що за напій","зомбі-сік лор"}},{q="Хто посилає вас по зомбі-сік?",a="Самітник Аберкромбі, що живе відлюдно в халупі в західному Сутінколіссі, просить мандрівників принести його, щоб зігріти свої холодні кістки.",al={"хто дає завдання зомбі-сік","завдання аберкромбі напій","відлюдник просить напій"}},{q="Де здається це завдання?",a="Поговоріть із Шинкарем Смітсом у Таверні «Багряний Крук» — головній корчмі Даркширу у східному Сутінколіссі.",al={"де смітс","здати зомбі-сік","місце смітса"}},{q="Навіщо він Аберкромбі?",a="Аберкромбі запевняє, що від похмурих, темних ночей Сутінколісся його тіпає і що йому потрібен вогняний напій, щоб зігріти кров.",al={"навіщо аберкромбі зомбі-сік","аберкромбі застуда","чому він п'є зомбі-сік"}},{q="Чи дивується Шинкар Смітс замовленню?",a="Так. Смітс зауважує, що зомбі-сік — надзвичайно міцна штука і що від постійних відвідувачів таких замовлень він зазвичай не отримує.",al={"реакція смітса","чи є в смітса зомбі-сік","діалог смітса"}},{q="Чи доведеться в цьому завданні битися з чудовиськами?",a="Ні. Саме доручення вимагає лише пройти дорогою від відлюдної хатини Аберкромбі до Даркширу й поговорити з Шинкарем Смітсом, хоча на дорогах Сутінколісся завжди повно бродячих звірів і нежиті.",al={"бої в завданні зомбі-сік","чи небезпечний зомбі-сік","монстри зомбі-соку"}}},fp="12,261,16.437.0,20.360.0,21.164.0,36.130.0,31.115.0,29.131.0,44.157.0,46.226.0"}
P.entries["quest:1580"] = {n="Електропеллери",s="«Електропеллери» — веселе доручення для ексцентричного гнома-майстра Візбанґа Кранктоґґла в Обердайні. Загубивши торбу з дослідними деталями в прісних струмках Темного Узбережжя під час халепи з вибуховою качкою-приманкою, Візбанґ просить рибалок, що проходять повз, виловити їх.",h="«Електропеллери» — веселе доручення для ексцентричного гнома-майстра Візбанґа Кранктоґґла в Обердайні.",kw={"електропеллери","візбанґ кранктоґґл","качка-приманка","рибальство","річка дикого закруту","обердайн"},ang={["profession:Engineering"]="Електропеллери — цікавий приклад мініатюрного гномського рушія: вони мають рухати механічні приманки, перш ніж бурхливо вибухнути.",["race:Gnome"]="Хаотичне прагнення Візбанґа будувати вибухові качки-приманки знайоме кожному гномові, хоч загубити дорогі деталі в річці, яку стережуть ельфи, трохи соромно.",["race:NightElf"]="Місцеві нічні ельфи дивляться на гучні, задимлені винаходи Візбанґа й річкове сміття після його халеп із тихим несхваленням: вони волять, щоб струмки Темного Узбережжя лишалися природними."},sec={{t="Хмільний винахід",b="Візбанґ Кранктоґґл, гном-майстер, що живе в тихому порту нічних ельфів — Обердайні, якось увечері подався вглиб Темного Узбережжя шукати місце для випробувань. Його найновішим захопленням стала самохідна вибухова качка-приманка. На жаль, зайва чарка обернулася невчасною непритомністю. Візбанґ прокинувся за кілька годин у містечку — з обсмаленим волоссям і геть порожньою торбою: свою дорогоцінну торбину з електропеллерами він ненароком упустив в одну з прибережних річок."},{t="Виловлюючи з води",b="Замість самому вирушати в нетрі по розкидані механічні деталі Візбанґ кличе місцевих рибалок прочесати прісні струмки Темного Узбережжя. Ті, хто закидає вудки в річки на кшталт Річки Дикого Закруту чи Річки Скельного Джерела, часто витягають разом із місцевою рибою ці плавучі металеві штуковини. Повернувши деталі, безтурботний гном може знову взятися за свої небезпечно непередбачувані експерименти з водоплавними."}},faq={{q="Де знайти електропеллери?",a="Їх треба виловлювати в прісноводних річках і озерах Темного Узбережжя, як-от у Річці Скельного Джерела чи Річці Дикого Закруту. У морських водах біля узбережжя їх не буде.",al={"де електропеллери","як дістати електропеллери","місце електропеллерів"}},{q="Хто такий Візбанґ Кранктоґґл?",a="Візбанґ — дивакуватий гном-інженер, що живе в Обердайні. Відомий химерними й вибуховими винаходами, він покладається на відважних мандрівників, щоб ті збирали загублені деталі й дивовижі для його дослідів.",al={"хто дає електропеллери","візбанґ кранктоґґл"}},{q="Що Візбанґ намагався збудувати?",a="Він працював над самохідною вибуховою качкою-приманкою. Випробування пішли шкереберть, коли він трохи перебрав і ненароком підірвав ранній прототип: обпалив собі волосся й загубив у воді торбу з деталями.",al={"вибухова качка-приманка","проєкт візбанґа"}},{q="Чи можна знайти електропеллери в зграях риби?",a="Ні, електропеллери витягують, закидаючи вудку у відкриту прісну воду. Якщо закидати просто в особливі зграї, як-от Малого Оліїстого Чорнорота, механічних деталей не виловиш.",al={"електропеллери в зграях риби","чи можна ловити зграї"}},{q="Яке завдання йде перед цим?",a="Спершу треба виконати завдання «Електромуфти» — попереднє рибальське доручення, яким Візбанґ перевіряє вашу рибальську вдачу в місцевих водах.",al={"що перед електропеллерами","передумова електропеллерів"}},{q="Чи падають електропеллери з чудовиськ?",a="Ні. Їх не можна забрати з ворогів чи знайти в скринях на землі — їх треба виловити з річок вудкою.",al={"чи падають електропеллери з мобів","хто дропає електропеллери"}}},fp="14,289,17.479.0,19.429.0,35.178.0,27.202.0,33.229.0,44.184.0,29.124.0,39.130.0"}
P.entries["quest:1581"] = {n="Еліксири для Блейдліфів",s="У вітті Доланаара Сірал Блейдліф шукає алхіміка, щоб поповнити запаси родинної справи, яка стрімко росте. Її чоловік просиджує безкінечні години над казанами, і Сірал сподівається, що партія свіжих еліксирів полегшить його працю, а помічник дістане в'язку рідкісних трав.",h="У вітті Доланаара Сірал Блейдліф шукає алхіміка, щоб поповнити запаси родинної справи, яка стрімко росте.",kw={"еліксири","блейдліфи","сірал блейдліф","алхімія","доланаар","трави","тельдрассил"},ang={["faction:Alliance"]="Коли Доланаар добре забезпечений відновлювальними й захисними напоями, його захисники й мандрівні союзники готові до лісових загроз.",["profession:Herbalism"]="Багатий ґрунт Тельдрассила рясніє Срібнолистом і Земнокоренем, тож назбирати сировини для замовлення Сірал неважко.",["race:NightElf"]="Підтримка тутешніх ремісників на кшталт Блейдліфів допомагає молодому поселенню Доланаар рости під шатром Тельдрассила."},sec={{t="Тягар добробуту",b="Поселення Доланаар — важливе перехрестя для мандрівників, вартових і друїдів, що прокладають шлях шатром Тельдрассила. Із такою кількістю подорожніх торгівля травами й алхімією, яку ведуть Сірал Блейдліф із чоловіком, розквітла. Та великий попит має свою ціну. Її чоловік проводить майже весь час, схилившись над пляшечками й казанами, щоб полиці не порожніли, і подружжю майже не лишається часу одне для одного."},{t="Обмін торговки",b="Замість дозволити своєму партнерові згоріти під лавиною замовлень, Сірал звертається до перехожих травників і зіллєварів. Замовляючи готові напої — Еліксири Левової Сили й Малого Захисту, — вона поповнює запаси крамниці, а навзаєм пропонує свіжозібрані нечасті трави. Для алхіміка-початківця, що вправляється в ремеслі під Великим Деревом, це чудова нагода обернути звичайну лісову рослинність на жадані місцеві трави."}},faq={{q="Навіщо Сірал Блейдліф ці зілля?",a="Їхня родинна крамниця трав і алхімії в Доланаарі завалена роботою. Її чоловік увесь час варить зілля, щоб устигати за попитом, і на особисте життя в них часу не лишається. Якщо доручити роботу стороннім, він нарешті матиме перепочинок.",al={"навіщо еліксири","мотив сірал блейдліф","проблема крамниці блейдліфів"}},{q="Які зілля потрібні для цього доручення?",a="Сірал просить шість Еліксирів Левової Сили й два Еліксири Малого Захисту. Обидва — ходові напої, які часто купують шукачі пригод і місцеві вартові на Тельдрассилі.",al={"які еліксири","що треба зварити","які потрібні зілля"}},{q="Які трави потрібні, щоб зварити ці еліксири?",a="Щоб зварити замовлене, потрібні Срібнолист і Земнокорінь, що рясно ростуть по всьому лісовому ґрунту Тельдрассилу, а також звичайні Кришталеві флакони.",al={"потрібні інгредієнти","матеріали для еліксирів","які трави збирати"}},{q="Хто може взятися за це прохання?",a="Це доручення пропонують лише тим, хто практикує Алхімію й має базову вправність у ремеслі. Сірал шукає для своєї крамниці надійних, добре змішаних ліків, а не аматорських варив.",al={"вимога до рівня","вимога до професії","чи кожен може виконати"}},{q="Що Сірал дає в обмін на еліксири?",a="Сірал нагороджує алхіміків, що допомогли, в'язкою свіжозібраних незвичайних трав, які нелегко випадково знайти на лісових стежках Тельдрассилу.",al={"нагорода лор","що дає сірал","обмін блейдліфів"}},{q="Де знайти Сірал Блейдліф?",a="Її можна знайти біля північного будинку в Доланаарі, неподалік центральної дороги, що проходить лісовим селищем.",al={"де сірал","місце блейдліф","куди це здати"}}},fp="26,276,22.435.0,19.467.0,44.238.0,39.175.0,51.165.0,31.185.0,50.161.0,33.119.0"}
P.entries["quest:1582"] = {n="Жилет Місячного Сяйва",s="«Жилет Місячного Сяйва» — ремісниче завдання від Лотеріас, шкірниці нічних ельфів у Дарнасусі. Не встигаючи за постійними потребами молодих шукачів пригод, що вирушають у дикі краї Калімдору, вона ділиться викрійкою особливої ельфійської туніки в обмін на великі партії тисненого шкіряного спорядження.",h="«Жилет Місячного Сяйва» — ремісниче завдання від Лотеріас, шкірниці нічних ельфів у Дарнасусі.",kw={"жилет місячного сяйва","лотеріас","шкірництво","дарнасус","викрійка","тиснена шкіра"},ang={["faction:Alliance"]="Спорядження для новобранців у Дарнасусі допомагає Альянсові втримувати хиткі позиції на півночі Калімдору, де множаться дикі й ворожі загрози.",["race:NightElf"]="Жилет Місячного Сяйва — приклад вишуканої майстерності ремісників Тельдрассилу: він дає розвідникам і Вартовим легкий захист під лісовим покровом."},sec={{t="Спорядження для калдореїв",b="У захищеному гіллі Дарнасуса ремісники невтомно працюють, щоб одягнути дедалі більші лави Вартових і молодих лісових розвідників. Молоді нічні ельфи та їхні мандрівні союзники вирушають за межі Тельдрассилу в неспокійний Калімдор, тож на надійну броню шалений попит. Тягар постачання прикордоння міцною шкірою лягає на плечі майстрів-шкірників на кшталт Лотеріас."},{t="Опанування ремесла",b="Щоб переконатися, що її учні мають і витривалість, і технічну точність, Лотеріас вимагає доказів їхньої роботи — кількох однакових виробів: тиснених рукавиць, чобіт і плащів. Виконавши цю норму, учень здобуває її довіру, і вона ділиться особливою ельфійською викрійкою Жилета Місячного Сяйва — одягу, який цінують за поєднання гнучкого захисту зі спритністю в русі."}},faq={{q="Хто така Лотеріас?",a="Лотеріас — вправна наставниця шкірництва з нічних ельфів у Дарнасусі. Вона навчає ремесла майстрів Альянсу й дає складніші викрійки шкірникам, які доведуть свою відданість.",al={"лотеріас дарнас","хто дає жилет місячного сяйва"}},{q="Навіщо Лотеріас стільки шкіряних виробів?",a="Дарнасус вирує новонавченими шукачами пригод, що готуються вирушити в світ. Ремісники ледве встигають за безупинним попитом на похідне спорядження, тож Лотеріас доручає звичайні тиснені вироби вправним учням.",al={"навіщо стільки чобіт","навіщо тиснена шкіра"}},{q="Що таке Жилет Місячного Сяйва?",a="Жилет Місячного Сяйва — вдосконалений шкіряний обладунок. Лотеріас навчає його викрійки як нагороди, коли ви доведете, що вмієте виготовляти якісні тиснені вироби у великій кількості.",al={"рецепт жилета місячного сяйва","що я отримаю"}},{q="Які речі потрібні, щоб виконати це доручення?",a="Треба принести одну пару Тиснених Шкіряних Рукавичок, п'ять пар Тиснених Шкіряних Чобіт і п'ять Тиснених Шкіряних Плащів. Усе має бути зроблено власноруч і доставлено просто Лотеріас.",al={"що мені треба","речі для жилета місячного сяйва"}},{q="Чи можуть шкірники Орди вивчити тут цю викрійку?",a="Ні. Лотеріас живе в Дарнасусі й навчає лише майстрів Альянсу. Ремісникам Орди треба шукати власних наставників по всьому Калімдору й Східних Королівствах, щоб розвивати своє ремесло.",al={"чи може орда це виконати","жилет місячного сяйва лише для альянсу"}},{q="Чи потрібен для цього завдання певний рівень ремесла?",a="Так, майстер має досягти навички шкірництва щонайменше 70, перш ніж Лотеріас визнає його досить умілим, щоб узятися за замовлення й вивчити викрійку жилета.",al={"потрібний рівень шкірництва","коли взяти жилет місячного сяйва"}}},fp="13,317,22.381.0,19.376.0,17.208.0,46.256.0,26.199.0,50.189.0,49.204.0,53.168.0"}
P.entries["quest:159"] = {n="Доставка соку",s="«Доставка соку» — доручення, що веде від Даркшира до західного краю Сутінколісся. Шинкар Смітс довіряє вам міцне вариво під назвою Зомбі-Сік, яке треба доставити відлюдникові Аберкромбі. Нібито воно має зігріти змерзлого старого, але надзвичайна міцність трунку викликає підозри.",h="«Доставка соку» — доручення, що веде від Даркшира до західного краю Сутінколісся.",kw={"доставка соку","зомбі-сік","шинкар смітс","аберкромбі","даркшир","сутінколісся"},ang={["faction:Alliance"]="Мешканці Даркшира покладаються на відважних гінців Альянсу, що пробираються небезпечними шляхами Сутінколісся, та довіряти кожному відлюдникові в лісі — вірний шлях до непередбаченої біди.",["profession:Cooking"]="Рецепт Зомбі-Соку від Шинкаря Смітса тримається на їдких, незвичних інгредієнтах — і ставить під сумнів, що взагалі можна вважати напоєм для таверни."},sec={{t="Сумнівне вариво",b="Шинкар Смітс із Даркшира варить легендарний трунок, що його в народі звуть Зомбі-Соком. Коли замовлення нарешті готове, Смітс передає пляшку із суворим застереженням поводитися з нею обережно: мовляв, це вариво таке міцне, що й мертвого підніме. Для втомленого шукача пригод, що бігає з дорученнями по проклятому лісі, віднести міцну самогонку дивакуватому самітникові — звичайна добра справа."},{t="Обмовка самітника",b="Шлях із небезпечним варивом на захід, повз виючих воргенів і неспокійних мерців, веде просто до хижі Аберкромбі на узліссі. Отримавши пляшку, кволий самітник запевняє, що трунок потрібен йому лише зігріти ниючі кістки в морозні, оповиті туманом ночі Сутінколісся. Та, взявши пляшку до рук, він мало не дякує мандрівникові за «дурість», а тоді хутко виправляється й хвалить за «доброту». Ця мимовільна обмовка натякає, що в голові відлюдника вариться щось значно більше, ніж звичайна вечірня чарка."}},faq={{q="Що таке зомбі-сік?",a="Зомбі-сік — надзвичайно міцне вариво, яке готує Шинкар Смітс у Таверні «Багряний Крук» у Даркширі. Хоча його й вважають міцним трунком, Смітс зауважує, що вариво таке забористе, що й мертвого підніме, тож воно куди небезпечніше за звичайні напої.",al={"зомбі-сік лор","що за сік смітса","напій аберкромбі"}},{q="Хто замовляє зомбі-сік?",a="Доставку просить Аберкромбі — дивакуватий старий самітник, що живе у відлюдній халупі біля західної межі Сутінколісся.",al={"хто хоче сік","кому доставка соку"}},{q="Навіщо Аберкромбі цей напій?",a="Аберкромбі запевняє, що напій потрібен йому, щоб зігрітися холодними, сирими ночами в Сутінколіссі. Проте обмовка, яка в нього вихоплюється, коли він отримує пляшку, натякає, що для цього варива він має куди зловісніші задуми.",al={"навіщо аберкромбі сік","аберкромбі застуда"}},{q="Хто варить зомбі-сік?",a="Шинкар Смітс, що тримає Таверну «Багряний Крук» у серці Даркширу, особисто варить напій, щойно отримає потрібні смердючі складники.",al={"хто робить зомбі-сік","смітс шинкар"}},{q="Де халупа Аберкромбі?",a="Халупа Аберкромбі стоїть відлюдно в західному Сутінколіссі, на північний захід від цвинтарних пагорбів і трохи на схід від гірського перевалу, що веде до Вестфолу.",al={"де аберкромбі","де халупа аберкромбі"}},{q="Що Аберкромбі робить далі, отримавши сік?",a="Здобувши зомбі-сік, Аберкромбі й далі експлуатує довірливих мандрівників: посилає їх на Цвинтар Воронячого Пагорба збирати ребра гулів для моторошного опудала, яке нібито відлякуватиме нежить.",al={"наступне завдання після соку","що буде далі"}}},fp="14,317,20.410.0,17.548.1,21.267.0,28.133.0,36.222.0,27.171.0,29.146.0,56.205.0"}
P.entries["quest:1598"] = {n="Викрадений фоліант",s="«Викрадений фоліант» — випробування-посвята для чорнокнижників-початківців із людей, що навчаються в Долині Нортширу. За дорученням наставниці Друзілли Ла Салль адепт має пробратися в сусідній табір Дефіас і повернути заборонену книгу «Сили Порожнечі». Так чорнокнижник-новачок доводить свою вправність і здобуває знання, потрібні, щоб зв'язати першого демонічного слугу.",h="«Викрадений фоліант» — випробування-посвята для чорнокнижників-початківців із людей, що навчаються в Долині...",kw={"чорнокнижник","фоліант","сили порожнечі","друзілла ла салль","дефіас","біс","нортшир"},ang={["class:Warlock"]="Цей обряд посвяти перевіряє, чи зможе чорнокнижник-новачок пройти небезпечною територією, не здригнувшись. Повернувши фоліант, ви отримуєте таємні обряди, потрібні, щоб прикликати свого першого біса.",["faction:Alliance"]="Працюючи просто під носом у паладинів і кліриків Нортширу, чорнокнижники Альянсу мусять ступати тихо й користатися з промахів злочинців, щоб здобути заборонені окультні знання.",["race:Human"]="Завдання показує, як глибоко Братство Дефіас проникло в Нортшир: воно спокушає навіть відлюдних учнів абатства красти священні тексти й приставати до заколоту."},sec={{t="Заборонена нагода",b="У володіннях Стормвінда чорнокнижники ступають обережно: вправляються у своєму небезпечному ремеслі по затишних кутках і ховають дослідження від сторонніх очей. Абатство Нортшира зберігає в архівах стародавні знання, зокрема заборонені гримуари під замком. Друзілла Ла Салль, наставниця чорнокнижників, що причаїлася на землях абатства, давно жадала одного з таких томів — «Сил Порожнечі», — та не наважувалася накликати підозру кліриків і паладинів абатства, вламуючись до охоронюваного крила бібліотеки власноруч."},{t="Нагода для Дефіас",b="Нагода для Ла Салль випала, коли один із послушників абатства пристав до Братства Дефіас. Тікаючи у Виноградники Нортшира до бандитів, книжник-відступник дорогою поцупив кілька цінних текстів. Злодії отаборилися в таборі Дефіас серед виноградників і сховали здобич у польовому наметі, навіть не здогадуючись про справжню небезпеку темних мистецтв, захованих у книзі."},{t="Перше зв'язування",b="Для майбутнього чорнокнижника повернення фоліанта — водночас випробування на витримку й короткий шлях до темніших таємниць. Той, хто наважиться пройти через табір бандитів і принести книгу, задовольняє честолюбство Друзілли й доводить свою готовність. Отримавши гримуар до рук, вона винагороджує учня темними обрядами, потрібними, щоб прикликати й зв'язати біса — найпершого демона, якого вчиться підкорювати підмайстер."}},faq={{q="Що таке «Сили Порожнечі»?",a="Це заборонений гримуар, що описує поняття темної магії й владу над іншими планами буття. Спершу він зберігався в охоронюваному, захищеному крилі бібліотеки Абатства Нортшира, і в ньому таємні знання, яких прагнуть для власних студій і навчання наставниці чорнокнижників на кшталт Друзілли Ла Салль.",al={"книга сили порожнечі","що за книга","що вкрав послушник"}},{q="Чому Друзілла Ла Салль не вкрала книгу сама?",a="Друзілла мусить бути обережною, щоб не втратити свого становища біля Абатства Нортшира. Якби вона прокралася до замкнених сховищ бібліотеки, жерці одразу зняли б тривогу. Коли невдоволений послушник украв фоліант і пристав до Дефіас, вона дістала ідеальну нагоду чисто заволодіти ним руками учня.",al={"чому друзілла не вкрала сама","чому посилають мене"}},{q="Де схований викрадений фоліант?",a="Бандити Дефіас сховали фоліант у наметі табору у Виноградниках Нортшира, трохи на схід від абатства, де оселилися їхні розвідники й ренегати.",al={"де книга","місце фоліанта","намет викраденого фоліанта"}},{q="Чому послушник із Нортширу пристав до Братства Дефіас?",a="Невдоволення й суспільні чвари охопили все королівство, штовхаючи на бік Братства Дефіас робітників, фермерів і навіть церковних учнів. Послушник зрікся обітниць, прихопив із бібліотеки кілька важливих книг як здобич і втік до бандитів у виноградниках.",al={"чому послушник пристав до дефіас","абатство зрадник дефіас","хто вкрав книгу"}},{q="Яку нагороду отримує чорнокнижник за повернений фоліант?",a="Повернена книга переконує Друзіллу, що учень має досить сміливості й стійкості, щоб займатися темними мистецтвами. Вона дає основні знання, потрібні, щоб закликати біса, — це перша успішна угода учня з демоном.",al={"чого навчишся","нагорода чорнокнижника","навіщо це завдання"}},{q="Чи знають Дефіас, як користуватися книгою?",a="Бандити бачать у викрадених книгах передусім цінну здобич з абатства. Хоча Дефіас і мають на службі чарівників-ренегатів, послушник і його товариші просто сховали книгу в ящику в наметі, а не опановували її темні таємниці.",al={"чи дефіас можуть користуватися фоліантом","що дефіас роблять з книгою"}}},fp="15,377,23.518.0,18.420.0,17.410.0,31.286.0,52.312.0,32.181.0,56.276.0,55.237.0,39.246.0"}
P.entries["quest:1599"] = {n="Початок",s="Початок — обряд посвяти для чорнокнижників-початківців Альянсу, що розпочинають шлях у Дун Мороґу. Під неохочим наставництвом Аламара Грімма новачків посилають зібрати магічні талісмани з пера в сусідніх новачків тролів Морозогривів, щоб довести свою вправність, перш ніж опанувати мистецтво призову біса.",h="Початок — обряд посвяти для чорнокнижників-початківців Альянсу, що розпочинають шлях у Дун Мороґу.",kw={"початок","чорнокнижник","аламар грімм","біс","талісман з пера","морозогриви","анвілмар"},ang={["class:Warlock"]="Це завдання — визначальний перший крок у подорожі чорнокнижника Альянсу в Дун Мороґу, що відкриває вам змогу прикликати першого демонічного слугу.",["race:Gnome"]="Гноми-чорнокнижники, що вчаться ремесла в Долині Холодного Хребта, мусять довести свій розум і магічну перевагу, перехитривши місцевих тролів Морозогривів."},sec={{t="Неохочий наставник",b="У безпечному притулку Анвілмара темну магію відкрито не вітають, але терплять із необхідності. Аламар Грімм, досвідчений чорнокнижник, веде свої окультні дослідження відносно непомітно. Коли нові практики виявляють сирий хист, невідомі покровителі з темніших кіл Айронфорджа переконують Грімма відірватися від студій і особисто оцінити новобранців."},{t="Іскра темної магії",b="Перш ніж відкрити новачкові таємниці поневолення менших демонів, Грімм вимагає практичного доказу і фізичної витривалості, і магічної спорідненості. Сусідні новачки тролів Морозогривів, що збираються в печері на південний захід від Анвілмара, носять примітивні талісмани з пера, насичені ледь відчутною первісною магією. Зібрати ці талісмани — довести, що майбутній чорнокнижник здатен подолати магічного супротивника, а заразом дати Гріммові цікаві зразки для подальших досліджень."},{t="Призов біса",b="Повернення з талісманами переконує Грімма, що новачок має достатньо волі, щоб вижити. Випробування завершується навчанням призову біса — найосновнішого поплічника чорнокнижника. Разом із ритуалом Грімм дає суворе застереження: попри крихітний зріст, біси володіють хаотичною вогняною магією, яка легко може взяти гору над недисциплінованим господарем."}},faq={{q="Хто дає завдання «Початок»?",a="Завдання дає Аламар Грімм — наставник чорнокнижників в Анвілмарі в Долині Холодного Хребта, у Дун Мороґу.",al={"хто дає початок","хто дає завдання початок","де аламар грімм"}},{q="Для чого потрібні пір'яні обереги?",a="Пір'яні обереги мають подвійне призначення: вони доводять, що молодий чорнокнижник може зійтися з вправними в магії ворогами й перемогти їх, і дають Аламарові Грімму цікаві зачаровані тролівські дрібнички для досліджень.",al={"навіщо пір'яні обереги","призначення пір'яних оберегів","обереги морозогривів"}},{q="Де знайти новачків Морозогривів?",a="Вони живуть у печері на південний захід від Анвілмара в Долині Холодного Хребта, де закріпилися тролі Морозогривів.",al={"де тролі-новачки","печера морозогривів","місце новачків морозогривів"}},{q="Яку нагороду отримує чорнокнижник, виконавши це доручення?",a="Виконане доручення здобуває схвалення Аламара Грімма й дає знання, потрібні, щоб закликати біса — першого демонічного супутника чорнокнижника.",al={"чого навчає початок","нагорода за початок","завдання на закляття біса"}},{q="Чому Аламар Грімм навчає нових чорнокнижників?",a="Грімм згадує, що молодим чорнокнижником зацікавилися впливові особи, і це переконало його відкласти власні окультні студії, щоб випробувати й наставити новобранця.",al={"чому аламар мене навчає","хто звелів аламару навчати мене"}},{q="Чи небезпечний біс для чорнокнижника-новачка?",a="Так. Аламар Грімм прямо застерігає, що попри малий зріст біса його вогонь скверни й хитрість роблять його непередбачуваним, і недосвідчений закликач легко може втратити над ним владу.",al={"небезпека біса","чи можуть біси вбити","застереження про біса"}}},fp="10,299,18.378.0,23.446.0,17.354.0,31.110.0,37.212.0,40.127.0,58.138.0,42.170.0,42.178.0"}
P.entries["quest:16"] = {n="Напоїти Джерарда",s="«Напоїти Джерарда» — проста послуга для Джерарда Тіллера, фермера, що гарує на Виноградниках Маклюрів у Лісі Елвінн. Спраглий під пекучим сонцем, він міняє звичайний урожай на пляшки свіжої джерельної води. Для юних шукачів пригод це ранній урок обміну й підтримки місцевих трударів.",h="«Напоїти Джерарда» — проста послуга для Джерарда Тіллера, фермера, що гарує на Виноградниках Маклюрів у Лісі...",kw={"джерард тіллер","джерельна вода","яблука","виноградники","обмін","ліс елвінн"},ang={["faction:Alliance"]="Підтримка фермерів Нортширу дає певність, що гарнізон і жерці абатства не голодуватимуть у неспокійний час оборони королівства.",["race:Human"]="Для людей, що починають свій шлях у Нортширі, допомога сусідам на кшталт Джерарда Тіллера — ранній приклад духу спільноти, який тримає Елвінн укупі."},sec={{t="Спрагла праця на виноградниках",b="Ферми Лісу Елвінн дають більшу частину зерна, фруктів та овочів, які споживають містяни й гарнізони Стормвінда. Доглядати ряди посівів просто неба — важка й спекотна праця. Джерард Тіллер цілими днями порається в землі на Виноградниках Маклюрів, відганяє шкідників і дбає про врожай. Бігати туди-сюди до міських колодязів йому ніколи, тож він покладається на новобранців, що проходять повз, аби ті принесли чистої джерельної води."},{t="Господарство на обмін",b="Замість монет Джерард воліє чесний і простий обмін харчами. Мандрівники, що мають при собі зайві пляшки Освіжаючої Джерельної Води, можуть виміняти їх на свіжі яблука, щойно зірвані в саду. У королівстві, що з останніх сил підтримує лад і годує армію, прямий обмін між дрібними господарями й новобранцями лишається практичним способом зводити кінці з кінцями в сільському Елвінні."}},faq={{q="Хто такий Джерард Тіллер?",a="Джерард Тіллер — скромний фермер, що обробляє ділянки у Виноградниках Маклюрів на півдні Лісу Елвінн. Він доглядає поля й сади, що годують місцевих мешканців.",al={"джерард тіллер","хто такий тіллер","джерард"}},{q="Навіщо Джерардові вода?",a="Цілий день працювати в полі під сонцем — виснажлива праця. Джерард покладається на перехожих мандрівників, щоб ті приносили йому свіжу джерельну воду, — так він не страждає від спраги й не кидає роботи.",al={"навіщо джерельна вода","джерард хоче пити","навіщо напій"}},{q="Де знайти Освіжаючу Джерельну Воду?",a="Освіжаючу Джерельну Воду зазвичай продають торговці їжею й напоями та корчмарі по всьому Лісу Елвінн, зокрема Брат Даніл в Абатстві Нортшира.",al={"де взяти воду","джерело води","як дістати воду"}},{q="Чи можна обмінюватися кілька разів?",a="Так. Джерард постійно працює в полі й охоче міняє свіжі садові яблука на нові пляшки води, доки вони у вас є.",al={"завдання повторюване","чи можна повторити","здати ще води"}},{q="Що Джерард дає в обмін на напій?",a="За свіжу воду Джерард дає Блискуче Червоне Яблуко.",al={"нагорода джерарда","що я отримаю","нагорода за обмін"}},{q="Де знайти Джерарда?",a="Він біля стодоли у Виноградниках Маклюрів на півдні Лісу Елвінн.",al={"де джерард тіллер","де джерард","де ферма"}}},fp="19,325,35.446.0,21.394.0,21.183.0,27.192.0,43.155.0,25.160.0,47.61.0,24.84.0"}
P.entries["quest:160"] = {n="Записка для мера",s="«Записка для мера» — доручення Альянсу в Сутінколіссі, що пов'язує дивакуватого відлюдника Аберкромбі з проводом Даркшира. Після допомоги старому самітникові шукачів пригод просять особисто доставити його послання меру, Лорду Елло Ебонлоку. Проте лист одразу викликає підозру, а не теплі почуття.",h="«Записка для мера» — доручення Альянсу в Сутінколіссі, що пов'язує дивакуватого відлюдника Аберкромбі з...",kw={"записка для мера","аберкромбі","елло ебонлок","даркшир","огрський курган вул'ґол","сутінколісся"},ang={["faction:Alliance"]="Виживання Даркшира залежить від того, чи вдасться розплутати дивні збурення, перш ніж вони прорвуть периметр Нічної Варти, тож цей підозрілий лист — нагальна справа безпеки для агентів Альянсу.",["race:Human"]="Люди-гінці, що служать Нічній Варті й домові Ебонлоків, швидко розуміють: дивакуватий старий відлюдник з околиць Сутінколісся їх ошукав."},sec={{t="Дружнє послання?",b="Після того як ви допомогли Аберкромбі повернути вкрадену скриню в огрів з Огрського Кургану Вул'Ґол, відлюдник посилає вас назад оповитими туманом дорогами до міста. Хихочучи від задоволення, Аберкромбі запевняє, що вони з мером, Лордом Елло Ебонлоком, давні друзі. Він наполягає: дізнавшись, що зробив шукач пригод, мер радітиме не менше за нього самого."},{t="Спантеличений мер",b="Прибувши до ратуші Даркшира, ви бачите, що дійсність суперечить словам Аберкромбі. Лорд Елло Ебонлок не пам'ятає нікого на ім'я Аберкромбі. А розгорнутий пергамент лише поглиблює таємницю: замість щирого привітання між давніми товаришами — текст, написаний стародавнім, нерозбірливим письмом, що вкрай спантеличує мера Даркшира."}},faq={{q="Хто передає Записку для мера?",a="Аберкромбі, дивакуватий самітник із відлюдної халупи на західному краю Сутінколісся, дає вам лист, після того як ви повернете йому речі, вкрадені місцевими ограми.",al={"хто дає записку для мера","хто починає записку для мера","відправник листа аберкромбі"}},{q="Чи справді Аберкромбі й мер Ебонлок друзі?",a="Ні. Хоча Аберкромбі запевняє, що вони давні знайомі, мер Лорд Елло Ебонлок ніколи про нього не чув і геть спантеличений, отримавши послання.",al={"чи вони знайомі","чи аберкромбі дружить з мером","стосунки аберкромбі й елло ебонлока"}},{q="Що написано в записці?",a="Записка написана давньою, маловідомою мовою, яку не може розібрати ні посланець, ні мер Ебонлок, тож мер шукає, хто б її переклав.",al={"що в записці аберкромбі","чи може елло прочитати записку","якою мовою лист"}},{q="Де знайти Лорда Елло Ебонлока?",a="Мер Лорд Елло Ебонлок у Ратуші Даркшира — у східній частині містечка, при головній дорозі Сутінколісся.",al={"де мер","місце елло ебонлока","куди здати записку для мера"}},{q="Що буде, коли мер Ебонлок отримає лист?",a="Лорд Ебонлок не може прочитати загадкове письмо, тож просить вас розшукати когось, хто зможе розтлумачити текст, — так починається завдання «Перекласти записку Аберкромбі».",al={"що далі після записки для мера","що йде після записки для мера"}},{q="Чому Аберкромбі сміявся, віддаючи вам лист?",a="Зловтішний сміх Аберкромбі натякає, що його наміри куди темніші за просту зустріч зі старим знайомим, і віщує Даркширу зловісну біду.",al={"чому аберкромбі сміється","чи аберкромбі злий","сміх аберкромбі записка"}}},fp="17,319,19.373.0,18.368.1,32.178.0,53.164.0,28.159.0,37.126.0,55.168.0,57.165.1"}
P.entries["quest:161"] = {n="Насувається темна загроза",s="Підозрюючи диверсію на Каменетесній Греблі, Головний Інженер Гіндервір VII посилає гінця на північ, до небезпечного Багнокраю, щоб там дослідили зразок нестійкого порошку. Гінець має пройти підступним шляхом повз Браму Алґаз і доставити зразок знавцеві вибухівки Ешланові Стоунсмерку в Дун Модр.",h="Підозрюючи диверсію на Каменетесній Греблі, Головний Інженер Гіндервір VII посилає гінця на північ, до...",kw={"насувається темна загроза","гіндервір","каменетесна гребля","ешлан стоунсмерк","дун модр","вибухівка","темне залізо"},ang={["faction:Alliance"]="Шлях через Лох Модан і Багнокрай — важлива військова артерія між Айронфорджем і північними володіннями Альянсу по той бік Мосту Тандол.",["profession:Engineering"]="Щоб розпізнати рештки потужної вибухівки, потрібне досвідчене око сапера — і навіть звичайнісінький порошок може видати технічну вишуканість ворожого диверсанта.",["race:Dwarf"]="Каменетесна Гребля — одна з перлин інженерії Бронзбірдів. Будь-який знак змови зруйнувати її кладку б'є по гордості й безпеці всього Каз Модану."},sec={{t="Порошок лихих намірів",b="Після заворушень довкола Каменетесної Греблі Головному Інженерові Гіндервіру VII приносять дивно пахучий порошок з підозрілої бочки біля східного схилу греблі, де він помітив саперів Темного Заліза. Розуміючи, якою нищівною може бути диверсія, Гіндервір підозрює, що це очищена вибухівка, створена, щоб розтрощити дворфійську кладку. На греблі немає спеціального обладнання для хімічних випробувань, тож він наполягає на тому, щоб порадитися з військовим підривником, перш ніж робити висновки."},{t="Шлях на північ",b="Для нагального аналізу треба вирушити крізь Браму Алґаз униз, до просяклих водою низовин Багнокраю. Болота кишать ворожою звіриною, агресивним драконовим поріддям і лазутчиками Темного Заліза, тож шлях сповнений небезпек. Гіндервір закликає мандрівників не сходити з брукованої дороги аж до Дун Модру — укріпленої дворфійської застави, що тримає південний підступ до Мосту Тандол."},{t="Підривник із Дун Модру",b="Ешлан Стоунсмерк, що служить на передовій північного Каз Модану, — полковий знавець потужної вибухівки. Напівглухий після десятиліть оглушливих вибухів, Стоунсмерк гострим оком і нюхом одразу підтверджує найгірші побоювання Гіндервіра: суміш справді виявляється спеціальним підривним зарядом, а отже, хтось замислив добре сплановану змову, спрямовану просто в серце дворфійської інженерії."}},faq={{q="Що це за дивний на запах порошок?",a="Це алхімічний вибуховий заряд, знайдений біля Каменетесної Греблі. Головний Інженер Гіндервір VII підозрює, що диверсанти хочуть пробити ним стіни греблі.",al={"що за порошок","порошок гіндервіра","дивний порошок"}},{q="Навіщо посилати порошок аж до Дун Модру?",a="У Дун Модрі стоїть військовий загін Айронфорджа, що захищає Міст Тандол, зокрема підривник Ешлан Стоунсмерк. Як досвідчений знавець вибухівки, він має технічні знання, щоб розпізнати особливі вибухові суміші.",al={"чому дун модр","чому ешлан стоунсмерк","чому йти у вологі землі"}},{q="Де знайти Ешлана Стоунсмерка?",a="Ешлан Стоунсмерк у військовому таборі Дун Модр, на крайній півночі Багнокраю, трохи на південь від Мосту Тандол.",al={"де стоунсмерк","знайти ешлана","місце стоунсмерка"}},{q="Чому Гіндервір радить триматися дороги?",a="Дорога, що спускається від Брами Алґаз через Багнокрай, пролягає просто через землі, де аж кишить ворожими звірами, ящерами, гнолами й диверсантами Темного Заліза, тож для гінців сходити з дороги вкрай небезпечно.",al={"чому триматися дороги","небезпеки вологих земель","дорога у вологі землі"}},{q="Хто влаштовує диверсії на Каменетесній Греблі?",a="Вибухівка належить дворфам Темного Заліза, які прагнуть підірвати господарство клану Бронзбірд і зруйнувати Каменетесну Греблю, щоб затопити долини внизу.",al={"хто зробив порошок","диверсанти греблі","винуватець темної загрози"}},{q="Чому Ешлан Стоунсмерк недочуває?",a="Роки служби військовим сапером і знавцем вибухівки на передовій лишили Ешланові постійний дзвін у вухах і тяжку втрату слуху від ударних хвиль.",al={"стоунсмерк глухий","чому ешлан не чує"}}},fp="19,321,22.504.0,14.414.0,28.390.1,36.162.0,44.236.0,35.149.0,46.223.0,39.158.1,41.171.0"}
P.entries["quest:1618"] = {n="Спорядження Червоногір'я",s="Ковальське торгове завдання Альянсу від Тормуса Діпфорджа в Айронфорджі. Майбутні ковалі кують міцне мідне спорядження, щоб полегшити становище обложеного гарнізону Лейкширу й допомогти місцевому ковалеві Вернерові Осґуду захищати Редрідж від ворожих орків і гнолів.",h="Ковальське торгове завдання Альянсу від Тормуса Діпфорджа в Айронфорджі.",kw={"спорядження червоногір'я","тормус діпфордж","вернер осґуд","ковальство","айронфордж","лейкшир","редрідж"},ang={["faction:Alliance"]="Ця доставка показує важливу взаємодопомогу між Айронфорджем і обложеними людськими містечками півдня — там, де роз'єднане керівництво Стормвінда не встигає.",["profession:Blacksmithing"]="Це завдання — обряд посвяти для учнів-ковалів: воно перевіряє, чи здатні ви на замовлення швидко виготовити багато міцної зброї й обладунків для фронту.",["race:Dwarf"]="Дворфійська майстерність — хребет воєнних зусиль Альянсу, і Тормус дбає, щоб обдаровані учні Айронфорджу використовували своє ремесло на допомогу союзникам у скруті.",["race:Human"]="Для людей південних королівств металеві вироби, викувані в Каз Модані, — вкрай потрібна підмога проти зухвалих решток Блекрок."},sec={{t="Прохання через кордони королівств",b="Велика Кузня Айронфорджу майже ніколи не спить, і дворфійські ковалі розуміють, що боротьба Альянсу на передовій сягає далеко за межі Дун Мороґа. Унизу, в Горах Редріджу, людське поселення Лейкшир постійно відбивається від ворогів: орки Блекрок раз у раз виходять із Фортеці Кам'яної Варти, а зграї гнолів кишать на північних хребтах. Королівське підкріплення зі Стормвінда не поспішає, тож місцеві запаси небезпечно виснажені."},{t="Ковадла Лейкширу",b="Місцевий коваль Лейкширу, Вернер Осґуд, майже сам-один працює біля своєї кузні просто неба, лагодячи розбиті обладунки й замінюючи зламану зброю. Бачачи, як тяжко доводиться його колезі-людині, Тормус Діпфордж доручає ковалям-початківцям доставити до Лейкширу чотири Рунічні Мідні Пояси й чотири Важкі Мідні Молоти. За поповнення оборонних запасів ополчення Вернер охоче ділиться з мандрівними ремісниками тоншими секретами ремесла."}},faq={{q="Хто дає завдання «Спорядження Червоногір'я»?",a="Тормус Діпфордж, дворф-коваль із Великої Кузні в Айронфорджі, пропонує це завдання ковалям Альянсу, що досягли достатньої вправності в ремеслі.",al={"хто дає спорядження червоногір'я","хто дає завдання спорядження червоногір'я","завдання тормуса"}},{q="Навіщо Лейкширу зброя й обладунки з Айронфорджа?",a="Лейкшир постійно відбиває напади орків Блекрок, що засіли у Фортеці Кам'яної Варти, а також агресивних місцевих гнолів. Єдиний коваль містечка, Вернер Осґуд, геть не встигає сам лагодити зброю й озброювати ополчення.",al={"чому редрідж потребує спорядження","чому лейкширу потрібна зброя","нестача припасів редріджа"}},{q="Хто отримує вантаж у Редріджі?",a="Вантаж доставляють Вернерові Осґуду — місцевому ковалеві, що працює біля кузні в приозерному містечку Лейкшир.",al={"куди здати спорядження червоногір'я","де вернер осґуд","коваль редріджа здати"}},{q="Яке спорядження треба викувати для цього доручення?",a="Треба принести чотири Рунічні Мідні Пояси й чотири Важкі Мідні Молоти. Вони показують майстерність і в захисному обладунку, і у важкій ударній зброї.",al={"потрібні речі спорядження червоногір'я","матеріали для спорядження червоногір'я","що кувати для тормуса"}},{q="Які загрози непокоять Редрідж у цей час?",a="Головні небезпеки, що тиснуть на Лейкшир, — клани орків Блекрок, що окопуються у Фортеці Кам'яної Варти, і люті зграї гнолів, що никають північними передгір'ями.",al={"вороги редріджа","хто нападає на лейкшир","загрози редріджа"}},{q="Яку нагороду дає Вернер Осґуд натомість?",a="Звільнившись від шаленого тягаря споряджати кожного вартового з нуля, Вернер знаходить час навчити вас складніших ковальських прийомів.",al={"навчання вернера осґуда","нагорода за спорядження червоногір'я","що я отримаю"}}},fp="16,277,22.481.0,23.464.0,38.157.0,57.240.0,38.124.0,43.144.0,49.188.0,47.146.0"}
P.entries["quest:163"] = {n="Воронячий Пагорб",s="Звістки про тіні, що ворушаться, і світло, що блимає у вікнах покинутого поселення Воронячий Пагорб, стривожили Нічну Варту. Елейн Керевін із Даркшира посилає мандрівників на захід через проклятий ліс — з'ясувати, яка зловісна сила знайшла притулок серед руїн.",h="Звістки про тіні, що ворушаться, і світло, що блимає у вікнах покинутого поселення Воронячий Пагорб...",kw={"воронячий пагорб","тремтій","елейн керевін","калор","нічна варта","сутінколісся"},ang={["class:Paladin"]="Паладин, навчений полювати на неспокійну нежить сусіднього цвинтаря, вирушає розслідувати чутки про зловісні примари — і несподівано знаходить живого, з плоті й крові, Тремтія, що лише скиглить від страху.",["faction:Alliance"]="Нічна Варта Сутінколісся майже не отримує допомоги від гарнізону Стормвінда, тож мусить покладатися на мандрівних героїв Альянсу, щоб розслідувати зловісні загрози в зруйнованих закутках краю."},sec={{t="Очі на заході",b="Для слідопитів Нічної Варти далекий західний край Сутінколісся давно відданий мерцям і глушині. Та цілковита пустка була б кращою за несподіване пожвавлення. Калор, вартовий, що патрулює похмурі дороги, дві ночі поспіль помічав рух між мовчазними хатами Воронячого Пагорба — і тривожне блимання ліхтаря у вікні. У краї, де кишать гулі, кістяки й звірі, будь-яку незрозумілу ознаку життя треба негайно перевірити."},{t="Наляканий самітник",b="Ті, хто сподівається зітнутися у Воронячому Пагорбі з демоном чи ватажком нежиті, знаходять значно жалюгіднішу правду. Серед напівзруйнованих руїн зіщулився від жаху Тремтій — цілком знетямлений волоцюга, що здригається від кожного шурхоту в темряві. Він гарячково запевняє, що тут немає жодної загрози, окрім «нешкідливого Тремтія», але його несамовите белькотіння видає: про кошмар, що поглинає Сутінколісся, він знає значно більше, ніж наважується сказати."}},faq={{q="Хто посилає вас розвідати Воронячий Пагорб?",a="Елейн Керевін, мешканка Даркширу, що допомагає Нічній Варті, просить мандрівників, небайдужих до безпеки Сутінколісся, перевірити тривожні звістки із заходу.",al={"хто дає завдання воронячий пагорб","дає завдання воронячий пагорб","завдання елейн каревін"}},{q="Що насправді бачив Калор на Воронячому Пагорбі?",a="Калор повідомив, що дві ночі поспіль бачив рухливі тіні в покинутому поселенні, а ніч перед тим — ліхтар чи свічку, що горіла в одному з вікон.",al={"що бачив калор","калор бачив воронячий пагорб","тіні на воронячому пагорбі"}},{q="Яке чудовисько блукає руїнами?",a="Саме це вам і доручено з'ясувати. Калор лише мигцем бачив рухливі тіні й світло у вікні; хай що ховається в занедбаних будинках Воронячого Пагорба, це треба знайти особисто.",al={"хто блукає воронячим пагорбом","що на воронячому пагорбі","чи справжнє чудовисько"}},{q="Хто такий Тремтій?",a="Тремтій — смикливий, параноїдальний волоцюга, що живе на межі жаху в західному Сутінколіссі. Хоч він і запевняє, що цілком нешкідливий, його надмірне почуття провини й гарячкове белькотіння натякають, що він заплутаний у темніші таємниці краю.",al={"тремтій лор","хто такий тремтій","чому тремтій ховається"}},{q="Де розташований Воронячий Пагорб?",a="Воронячий Пагорб лежить у крайній західній частині Сутінколісся, трохи на південь від величезного, заполоненого нежиттю цвинтаря з тією ж назвою.",al={"де воронячий пагорб","як знайти воронячий пагорб","мапа воронячого пагорба"}},{q="Чому Нічну Варту так турбують рухливі тіні?",a="Сили Даркширу виснажені боротьбою з повсталими скелетами, здичавілими воргенами й павуками, що чатують у хащах. Будь-яка ознака організованого руху чи дивних мешканців на покинутому заході може віщувати напад на поселення, де ще живуть люди.",al={"чому важливий воронячий пагорб","нічна варта воронячий пагорб"}}},fp="10,297,16.493.0,16.438.1,40.178.0,42.178.0,35.190.1,15.230.1,28.138.0,57.237.0"}
P.entries["quest:1638"] = {n="Навчання воїна",s="«Навчання воїна» — вступне класове завдання, що веде молодих перспективних воїнів із Ґолдширу до Стормвінда. За дорученням наставниці Лірії Дю Лак бійці вирушають до таверни «Свиня і Свисток» у Старому Місті, щоб розшукати ветерана Гаррі Барлґарда й перейняти від нього науку витривалості на полі бою.",h="«Навчання воїна» — вступне класове завдання, що веде молодих перспективних воїнів із Ґолдширу до Стормвінда.",kw={"навчання воїна","гаррі барлґард","лірія дю лак","старе місто","свиня і свисток","воїн"},ang={["class:Warrior"]="Цей обряд посвяти позначає ваш перехід від новобранця місцевого ополчення до визнаного воїна Альянсу й відкриває вам нові стійки та оборонні прийоми.",["faction:Alliance"]="Бувалі ветерани на кшталт Гаррі Барлґарда дбають, щоб новобранці, вирушаючи на спірні кордони, несли з собою практичну мудрість бійки, а не лише книжну тактику.",["race:Human"]="Цей шлях веде людських бійців від пасторальних оборонних рубежів Елвінна просто до Старого Міста — споконвічної робітничої колиски бойової спадщини Стормвінда."},sec={{t="З Елвінна до Старого Міста",b="Щойно молодий боєць доведе, що впевнено дає раду загрозам Лісу Елвінн, наставники розуміють: муштрувальники Ґолдширу вже мало чого можуть його навчити. Лірія Дю Лак відсилає новобранців у серце Стормвінда — до суворого кварталу Старе Місто. Там бувалі вояки сходяться, щоб обмінятися бойовим досвідом подалі від жорстких формальностей королівського гарнізону."},{t="Уроки ветерана",b="Зв'язковий у Старому Місті — Гаррі Барлґард, літній ветеран багатьох битв, що мешкає в таверні «Свиня і Свисток». Замість муштри на плацу Гаррі перевіряє гарт воїна шинковою завзятістю й практичною витривалістю. Перш ніж навчити оборонних прийомів, що рятують солдатам життя в небезпечних походах, Гаррі чекає від новоприбулих, що ті не поступляться йому в питті й дадуть раду місцевим забіякам."}},faq={{q="Хто дає це завдання?",a="Завдання дає Лірія Дю Лак — наставниця воїнів, що стоїть за кузнею в Ґолдширі, щойно боєць доведе свою початкову бойову вправність.",al={"хто дає завдання","хто починає навчання воїна","завдання ліріа дю лак"}},{q="Де знайти Гаррі Барлґарда?",a="Гаррі Барлґард сидить у Таверні «Свиня і свисток», що притулилася в кварталі Старе Місто в Стормвінді.",al={"де гаррі барлґард","місце гаррі барлґарда","таверна свиня і свисток"}},{q="Чого навчає Гаррі Барлґард?",a="Гаррі — старий ветеран, що навчає воїнів практичних прийомів і стійок, які допомагають довше лишатися живим у полі, і починає з кількох барвистих випробувань на витривалість.",al={"чого навчишся","нагорода воїна десятого рівня","урок гаррі барлґарда"}},{q="Чому навчання проходить у таверні, а не в казармі?",a="Старе Місто — традиційне, грубіше серце Стормвінда, де збираються відставні вояки й загартовані ветерани. Гаррі воліє навчати за кухлем елю й із дисципліною голих кулаків, а не за задушливим військовим статутом.",al={"чому свиня і свисток","чому навчання в таверні","казарма стормвінда"}},{q="Що далі після розмови з Гаррі?",a="Гаррі одразу втягує новобранця у виклик із місцевим забіякою Бартлбі П'яницею, щоб перевірити його фізичну стійкість, перш ніж завершити навчання.",al={"яке наступне завдання","після навчання воїна","наступний крок"}},{q="Чи можуть це завдання отримати не-воїни?",a="Ні. Це завдання — частина особливого ланцюжка навчання воїнів, і його пропонують лише персонажам класу воїн.",al={"чи лише для воїнів","чи можуть паладини це виконати","класове завдання воїна"}}},fp="20,312,23.407.0,22.408.0,21.161.0,35.113.0,32.180.0,57.228.0,35.164.1,36.124.0"}
P.entries["quest:1639"] = {n="Бартлбі П'яниця",s="«Бартлбі П'яниця» — одне з перших випробувань для воїнів Альянсу, що навчаються в Стормвінді. На вказівку Гаррі Барлґарда в таверні «Свиня і Свисток» молодий боєць мусить зійтися з упертим п'яничкою й забрати в нього улюблений кухоль. Це простий тест на гарт, який доводить, що воїн здатен витримати бійку, перш ніж перейти до справжньої бойової науки.",h="«Бартлбі П'яниця» — одне з перших випробувань для воїнів Альянсу, що навчаються в Стормвінді.",kw={"бартлбі п'яниця","бартлбі","гаррі барлґард","свиня і свисток","старе місто","воїн"},ang={["class:Warrior"]="Ця сутичка — практичне випробування, якого вимагають наставники Стормвінда, перш ніж навчити вас оборонної тактики й майстерності стійок.",["faction:Alliance"]="Шинкова бійка показує суворий, неприкрашений бік Старого Міста Стормвінда, далекий від королівського двору у Фортеці."},sec={{t="Шинкове випробування",b="Перш ніж передати глибшу бойову науку в таверні Старого Міста, Гаррі Барлґард вимагає доказу, що новачок має справжній хребет. Замість упорядкованого тренувального двобою Гаррі киває через залу на Бартлбі — задиристого відвідувача, що потягує трунок у дальньому кінці стійки. Доручення просте: забрати в нього кухоль. Барлґард чудово знає, що Бартлбі радше битиметься, ніж віддасть свій ель, тож сутичка одразу стає випробуванням рішучості воїна."},{t="Етикет Старого Міста",b="«Свиня і Свисток» приймає солдатів, робітників і шибайголів з околиці, тож вишуканих манер тут не терплять. Замість розмови Бартлбі відповідає глузуванням: п'яничка одразу висміює будь-якого новачка як надто чепуристого для шинкової бійки. Ця сварка переростає в бійку просто на дощаній підлозі — і показує, що шлях угору в бойових колах Стормвінда часто починається зі звичайної шинкової колотнечі."}},faq={{q="Хто такий Бартлбі?",a="Бартлбі — упертий завзятий пияк, що вештається біля шинквасу в Таверні «Свиня і свисток» у кварталі Старе Місто в Стормвінді.",al={"хто такий бартлбі","нпц бартлбі","бартлбі п'яниця"}},{q="Чому Гаррі Барлґард посилає мене до Бартлбі?",a="Гаррі Барлґард хоче подивитися, на що ви здатні, перш ніж узятися навчати вас складніших прийомів воїна. Вимога віддати кухоль Бартлбі гарантує бійку й перевіряє, чи готові ви витримати удар і встояти.",al={"чому битися з бартлбі","випробування гаррі барлґарда","навіщо брати кухоль"}},{q="Де відбувається ця зустріч?",a="Зустріч відбувається в Таверні «Свиня і свисток» у Старому Місті, у східній частині Стормвінда.",al={"де бартлбі","місце свині і свистка"}},{q="Що стається, коли заговориш із Бартлбі?",a="Бартлбі ображає вас, обзиває чепуруном і пещеним і радить не зламати нігтика в такому грубому закладі, як «Свиня і свисток», — і швидко спалахує бійка.",al={"що каже бартлбі","діалог бартлбі"}},{q="Що далі після розмови з Бартлбі?",a="Сутичка з Бартлбі одразу переходить у бійку в таверні, де ви маєте здолати його власноруч, щоб забрати його кухоль і повернути Гаррі Барлґарду.",al={"наступне завдання після бартлбі","що після бартлбі п'яниці"}},{q="Чи доступне це завдання будь-якому класу?",a="Ні, це завдання — частина класового навчання лише для воїнів Альянсу, що досягли 10-го рівня.",al={"чи кожен може виконати бартлбі","лише воїн"}}},fp="18,363,18.491.0,18.433.0,16.142.0,45.216.0,37.114.0,40.167.0,37.143.0,37.104.0"}
P.entries["quest:164"] = {n="Доставка Свену",s="«Доставка Свену» — завдання Альянсу від Елейн Керевін у Даркширі: треба доправити життєво потрібні припаси до самотнього табору на північно-західному прикордонні Сутінколісся. Там Свен Йорґен і жменька його прибічників ведуть відчайдушну самотню боротьбу проти жахіть проклятого лісу. Це доручення пов'язує містян, що борються з темрявою, із відрізаним загоном на краю глушини.",h="«Доставка Свену» — завдання Альянсу від Елейн Керевін у Даркширі: треба доправити життєво потрібні припаси до...",kw={"доставка свену","свен йорґен","елейн керевін","каревіни","даркшир","сутінколісся"},ang={["class:Paladin"]="Елейн говорить про Свена як про людину, що чинить справжню справу Світла, тож доставка припасів — це вияв солідарності з братом в облозі.",["faction:Alliance"]="Віддалені вартові на кшталт Свена — ознака того, як слабко Альянс тримається в Сутінколіссі: тут виживання залежить від добровольців-гінців, а не від регулярного постачання гарнізонів.",["race:Human"]="Каревіни й прибічники Свена показують уперту стійкість сільського люду Стормвінда, що не хоче покидати Сутінколісся, попри невідступну темряву."},sec={{t="Рятівна нитка до глушини",b="Даркшир ледве втримує власні мури від вовків, павуків і неспокійних мерців, але дехто відмовляється ховатися за частоколом. Свен Йорґен і жменька товаришів заснували самотній табір уздовж північно-західних рубежів Сутінколісся. Небезпека тисне на них так невпинно, що вони не можуть відпустити жодної людини в небезпечний шлях до міста по припаси. Тож допомогу організовує Елейн Керевін — і покладається на хоробрих мандрівників, щоб ці бійці з прикордоння не голодували."},{t="Зв'язок із Каревінами",b="Родина Каревінів високо шанує Свена й бачить у його запеклому опорі справжню відданість Світлу. Готовність Елейн збирати й відправляти припаси показує ті тихі мережі виживання, що не дають Сутінколіссю остаточно поринути в тінь. Отримавши ящик, Свен відчуває незмінну підтримку Каревінів, хоча його думки й далі поглинає похмура битва, що триває."}},faq={{q="Хто такий Свен Йорґен?",a="Свен Йорґен — житель прикордоння, що тримає озброєний табір на північно-західному краю Сутінколісся. Такі, як Елейн Керевін, бачать у ньому чесного бійця, що чинить справу Світла, а Свен із невеликим загоном бореться з незліченними жахіттями, що поневіряють довколишні ліси.",al={"хто такий свен","свен лор","свен йорґен інфо"}},{q="Чому Свенові треба доставляти припаси?",a="Загін Свена надзвичайно малий і постійно напоготові проти загроз довкола. Вони не можуть відпустити жодної людини в небезпечну дорогу до Даркширу й назад, тож цілком залежать від співчутливих містян і перехожих гінців.",al={"чому свен не може взяти припаси","припаси свена","навіщо доставка"}},{q="Хто дає припаси?",a="Припаси дає Елейн Керевін із Даркширу. Її родина близька зі Свеном і глибоко шанує його відданість, тож регулярно влаштовує допомогу для його табору.",al={"хто надсилає припаси","елейн каревін","родина каревін"}},{q="Де розташований табір Свена?",a="Табір Свена притулився до північно-західних гір Сутінколісся, далеко за дорогою й на північ від спустошених ферм, просто на прикордонних нетрях.",al={"де свен","місце свена","табір свена"}},{q="Чи обов'язкова ця доставка, щоб далі допомагати Свенові?",a="Ні. Хоча Елейн Керевін дає це доручення, щоб спрямувати мандрівників до Свена, заповзятливі мандрівники, які самі натраплять на його табір, можуть допомагати йому й без ящика від Елейн.",al={"чи обов'язкова доставка свенові","чи треба доставка свенові","передумова доставок"}},{q="Що Свен робить, отримавши доставку?",a="Свен щиро дякує родині Керевін за підтримку, але його думки одразу перескакують на страшні загрози його табору й історії його родини, і він шукає вправних бійців, щоб допомогли йому помститися.",al={"що буде далі","після доставки свенові","наступне завдання свена"}}},fp="18,417,28.505.0,22.404.0,19.277.0,43.268.0,26.196.0,29.173.0,55.189.0,47.207.0"}
P.entries["quest:1640"] = {n="Побий Бартлбі",s="«Побий Бартлбі» — пряме випробування бойового гарту для молодих воїнів Альянсу в Стормвінді. Щоб виконати посвятне доручення, учень мусить побитися з упертим міським п'яничкою, який не віддасть свого улюбленого кухля без бійки. Здолавши його, воїн здобуває і неохочу пошану п'янички, і посудину, якої вимагають наставники.",h="«Побий Бартлбі» — пряме випробування бойового гарту для молодих воїнів Альянсу в Стормвінді.",kw={"побий бартлбі","бартлбі","кухоль","бійка","воїн","стормвінд"},ang={["class:Warrior"]="Ця шинкова бійка — знакове раннє випробування для воїнів Альянсу, що вчить суворого уроку: сила волі й важкий кулак часто розв'язують суперечки там, де дипломатія безсила.",["faction:Alliance"]="Ця сутичка на столичних вулицях Стормвінда дає барвистий погляд на грубе підчерев'я міста поруч із його величними кам'яними мурами."},sec={{t="Бійцівський виклик",b="Наставники воїнів у Стормвінді не приймають виправдань і не вчать, що бій завжди буде шляхетним і величним. У межах офіційного навчання молоді воїни мають забрати певний кухоль у Бартлбі — сумнозвісного пияка, що вилежується в місті. Коли до нього підходять, Бартлбі глузує з будь-яких чемних прохань і присягається, що його улюблений кухоль заберуть лише з холодних мертвих пальців. Для молодого воїна слова швидко поступаються голим кулакам."},{t="П'яний урок",b="Хоч Бартлбі й гучно обіцяє битися на смерть, щоб протверезити його, досить доброго прочухана. Побитий і впокорений, він утрачає всю свою браваду й мимоволі пройнявшись повагою, визнає: суперник куди міцніший, ніж здається. Він мирно здається й нарешті віддає переможцеві кухоль — випробування для зали наставників завершено."}},faq={{q="Хто такий Бартлбі?",a="Бартлбі — задиркуватий п'яниця, що часто вештається Стормвіндом. Відомий тим, що не випускає з рук улюбленого кухля, він мимоволі стає перепоною й спаринг-випробуванням для молодих воїнів, яких посилають довести свою фізичну рішучість.",al={"бартлбі","хто такий бартлбі","нпц бартлбі"}},{q="Чому я мушу битися з Бартлбі?",a="Наставники воїнів Альянсу посилають новобранців забрати певний кухоль, що належить Бартлбі. Оскільки той уперто не віддає його без бійки, учень мусить здолати його врукопашну, щоб розтиснути йому пальці.",al={"чому битися з бартлбі","причина побити бартлбі","навіщо його бити"}},{q="Чи вбиваю я Бартлбі в цьому завданні?",a="Ні. Хоч Бартлбі й хвалиться, що кухоль доведеться виривати з його холодних мертвих пальців, він здається, щойно його здоров'я вичерпано, і охоче визнає, що ви куди міцніші, ніж він думав.",al={"чи бартлбі помирає","вбити бартлбі","чи бартлбі мертвий"}},{q="Де відбувається це завдання?",a="Сутичка відбувається в Стормвінді, де Бартлбі можна знайти за випивкою й безділлям.",al={"місце побити бартлбі","де бартлбі","місце бартлбі"}},{q="Що буде, коли я його переможу?",a="Переможений Бартлбі здається й говорить із вами вже по-дружньому. Тоді ви можете забрати його кухоль і віднести наставникам воїнів, щоб завершити посвяту.",al={"після того як побив бартлбі","що далі бартлбі"}},{q="Який етап навчання становить це випробування?",a="Ця бійка — рання віха для молодих воїнів приблизно на десятому рівні досвіду, практична перевірка базової витривалості в ближньому бою.",al={"рівень завдання бартлбі","коли битися з бартлбі"}}},fp="13,374,21.537.0,16.389.0,16.222.0,32.223.0,42.188.0,33.111.0,32.163.0,49.158.0"}
P.entries["quest:1641"] = {n="Фоліант Божественності",s="«Фоліант Божественності» — важливий обряд посвяти для молодих паладинів королівства Стормвінд. Під проводом Дуторіана Ралла в Соборі Світла новачків випробовують на розуміння чесноти, відданості й урочистої відповідальності, яку несе володіння Святим Світлом.",h="«Фоліант Божественності» — важливий обряд посвяти для молодих паладинів королівства Стормвінд.",kw={"фоліант божественності","дуторіан ралл","собор світла","паладин","святе світло","посвята"},ang={["class:Paladin"]="Цей обряд позначає перехід від простого учня-зброєносця до справжнього служителя Святого Світла й закладає головні засади самопожертви й милосердя, що визначають орден.",["faction:Alliance"]="Навчання стійких паладинів зміцнює серце Стормвінда: праведні захисники завжди готові заступити Альянс від темряви, що підіймається.",["race:Human"]="Для людей Стормвінда цей обряд вшановує пам'ять полеглих лицарів Лордерона й продовжує горду традицію Срібної Длані в південному королівстві."},sec={{t="Покликання паладина",b="У спокійних мармурових залах Собору Світла Дуторіан Ралл опікується навчанням тих, хто бере на себе мантію паладина. Перші вправи присвячено бойовій дисципліні й ратним обрядам, але просування в ордені вимагає глибшої духовної відданості. Випробування, пов'язані з Фоліантом Божественності, спонукають новачків зазирнути далі за бій і збагнути вагу морального обов'язку в королівстві, яке облягають небезпеки і зсередини, і ззовні."},{t="Шлях чесноти",b="Прийняти Книгу Божественності — означає укласти угоду служіння й самопожертви. Дуторіан доручає молодим звитяжцям вивчити святий текст, щоб збагнути, чого Світло вимагає від своїх захисників. Уроки, що містяться в ньому, готують паладинів протистояти жахіттям Погибелі, які насуваються, й берегти простий люд, — доводячи, що праведною силою завжди мусять керувати справжня чеснота й співчуття."}},faq={{q="Для чого потрібен Фоліант Божественності?",a="Фоліант Божественності — основоположний святий текст і випробування для паладинів, що розвиваються. Він перевіряє, як посвячуваний розуміє священні засади, перш ніж йому довірять більші божественні вміння, щоб його сила спиралася на відданість і чесноти, а не на саму лише бойову міць.",al={"навіщо фоліант божественності","що таке фоліант божественності","завдання паладина книга"}},{q="Хто такий Дуторіан Ралл?",a="Дуторіан Ралл — високопоставлений наставник паладинів у Соборі Світла в Стормвінді. Він веде щойно посвячених паладинів, вручає їм Книгу Божественності й скеровує їхні випробування по всьому королівству.",al={"дуторіан ралл","тренер паладинів стормвінд","хто такий дуторіан"}},{q="Де відбувається це випробування?",a="Завдання починається на Соборній Площі Стормвінда, у величному Соборі Світла. Посвячувані з'являються просто до Дуторіана Ралла, виконавши попередні обов'язки в околичних селищах на кшталт Ґолдширу.",al={"де дуторіан","завдання собору світла","де почати фоліант божественності"}},{q="Чому в науці Стормвінда згадують Погибель?",a="Хоча Погибель спустошила Лордерон на півночі, нежить і далі загрожує існуванню всіх живих смертних. Паладинів Стормвінда від самого початку вчать розпізнавати нечестиву скверну Погибелі й боротися з нею, хай де вона з'явиться в Азероті.",al={"загроза погибелі стормвінд","чому тут погибель","паладини проти погибелі"}},{q="Що далі, коли прочитано Книгу Божественності?",a="Вивчення тексту — лише перший крок. Дуторіан Ралл перевіряє, чи справді посвячуваний засвоїв його уроки, посилаючи його допомагати тим, хто в біді, щоб він довів співчуття й стійкість ділами, а не словами.",al={"наступний крок фоліанта божественності","після прочитання книги","чого далі хоче дуторіан"}},{q="Хто зазвичай спрямовує кандидатів до Дуторіана Ралла?",a="Місцеві наставники й духовенство в околичних поселеннях Елвінна, як-от Брат Вільгельм у Ґолдширі, бачать, коли посвячуваний готовий до офіційних випробувань, і посилають його просто до Дуторіана в столицю.",al={"хто послав мене до дуторіана","попереднє завдання фоліант божественності","брат вільгельм"}}},fp="20,289,19.466.0,18.414.0,44.293.0,22.241.0,33.215.0,54.271.0,46.236.0,50.223.0"}
P.entries["quest:1645"] = {n="Фоліант Божественності",s="«Фоліант Божественності» — важлива віха в навчанні дворфійського паладина в Айронфорджі. Цей святий текст, який вручає Тіза Баттлфордж у Залі Таїнств, починає шлях випробувань, що перевіряють відданість посвячуваного Світлу та його готовність захищати Азерот від темних сил на кшталт Погибелі.",h="«Фоліант Божественності» — важлива віха в навчанні дворфійського паладина в Айронфорджі.",kw={"фоліант божественності","книга божественності","тіза баттлфордж","зала таїнств","паладин","айронфордж","святе світло"},ang={["class:Paladin"]="Цей обряд посвяти поєднує перші бойові уроки з глибшими чеснотами Святого Світла й веде посвячуваних шляхом, на якому вони спрямовуватимуть силу спокути й воскресіння.",["race:Dwarf"]="Для дворфійських звитяжців прийняти Фоліант Божественності — значить зміцнити союз віри, викуваний між королівством Бронзбірдів і людськими лицарями Срібної Длані."},sec={{t="Поклик до чесноти",b="Наставники паладинів по всіх Східних Королівствах скеровують обдарованих посвячуваних до Зали Таїнств в Айронфорджі, щойно ті опанують основи бою й духовної науки. Під пильним оком Тізи Баттлфордж молоді дворфійські паладини знайомляться з урочистими засадами, що відрізняють простого воїна від висвяченого звитяжця Святого Світла. Узятися за це завдання — значить свідомо присягнути на довічну самопожертву, обов'язок і духовну дисципліну."},{t="Книга Божественності",b="Прийнявши доручення, новачок отримує до рук Книгу Божественності. Цей текст викладає вимоги, чесноти й духовні засади, без яких не можна дієво спрямовувати священну силу проти лихих загроз. Вивчення її науки — лише перший крок: писання стає основою, перш ніж посвячуваного пошлють у Каз Модан і далі, щоб утілити його уроки в справжніх вчинках віри."}},faq={{q="Яка мета завдання «Фоліант Божественності»?",a="Це завдання — двері до поглибленого навчання паладинів для дворфійських поборників. Поговоривши з Тізою Баттлфордж, посвячувані отримують свій святий текст і вирушають на низку випробувань, що мають довести їхні чесноти й відкрити здатність повертати полеглих союзників зі смерті.",al={"що робить фоліант божественності","мета фоліанта божественності","навіщо це завдання"}},{q="Хто така Тіза Баттлфордж?",a="Тіза Баттлфордж — знана наставниця паладинів у Залі Таїнств в Айронфорджі. Їй доручено вести дворфійських паладинів до вищих чеснот, перевіряти їхню відданість Світлу й готувати їх до протистояння загрозам на кшталт Погибелі.",al={"тіза баттлфордж","хто тренер паладинів в айронфорджі","хто дає фоліант божественності"}},{q="Чому посвячувані мусять вивчати Книгу Божественності?",a="У Книзі Божественності — основні вчення про обов'язки й чесноти, яких вимагає Святе Світло. Вивчаючи її, посвячуваний збагне духовну дисципліну, потрібну, перш ніж володіти чудодійними священними силами.",al={"що таке книга божественності","навіщо читати книгу","книга божественності лор"}},{q="До боротьби з якими головними загрозами готуються дворфійські паладини?",a="Як пояснює Тіза Баттлфордж, паладини присвячують себе захистові Азероту від небезпек по всій землі, особливо пильнуючи нежить Погибелі, що насувається.",al={"з ким б'ються паладини","навіщо вчити паладинів айронфордж","призначення паладина"}},{q="Де відбувається це навчання?",a="Посвята починається в Залі Таїнств — тихому святилищі в північних кварталах Айронфорджа, де вчені, жерці, маги й паладини збираються для молитви й навчання.",al={"де тіза баттлфордж","паладин айронфорджа місце","паладин зали таємниць"}},{q="Що далі, коли отримаєш книгу?",a="Коли посвячуваний прочитає й обміркує Книгу Божественності, Тіза Баттлфордж дає практичні випробування, які вимагають від паладина виявити співчуття, обов'язок і жертовність поза безпечними міськими брамами.",al={"що далі","наступне завдання фоліант божественності","куди йти після отримання книги"}}},fp="20,325,19.469.0,20.423.0,50.272.0,24.259.0,46.230.0,59.213.0,36.186.0,41.215.0"}
P.entries["quest:1649"] = {n="Фоліант Звитяги",s="«Фоліант Звитяги» — священне перехідне випробування для паладинів, що набирають сили в Соборі Світла. Керуючись святими текстами й порадами досвідчених наставників, новачки шукають Дуторіана Ралла в Стормвінді, щоб довести свою непохитну віру, мужність і відданість чеснотам Церкви.",h="«Фоліант Звитяги» — священне перехідне випробування для паладинів, що набирають сили в Соборі Світла.",kw={"фоліант звитяги","дуторіан ралл","собор світла","паладин","звитяга","випробування"},ang={["class:Paladin"]="Це випробування — визначальний крок у зростанні паладина: воно доводить, що праведна бойова майстерність мусить триматися на дисциплінованій вірі й безкорисливому служінні.",["faction:Alliance"]="Випробування, які проводять у Стормвінді, допомагають зберегти серцевину оборонної й духовної сили Альянсу в неспокійні часи."},sec={{t="Гартування духу",b="За традиціями Святого Світла звитяга — не вроджена риса, що сама собою лишається чистою. Священний текст Фоліанта порівнює чесноти з дорогоцінною необробленою рудою: вона цінна вже тоді, як її знайдуть, але потребує ретельної виплавки й очищення, щоб витримати негоди. Лише через тяжкі випробування й щиру відданість паладин може сплавити віру, співчуття й мужність у сплав, здатний протистояти найтемнішому злу, що загрожує Азероту."},{t="Звернення до Церкви",b="Засвоївши мудрість, викладену у Фоліанті Звитяги, паладин вирушає до Дуторіана Ралла — шанованого провідника серед паладинів, що зібралися в Соборі Світла в Стормвінді. Дуторіан вирішує, хто з прохачів гідний пройти випробування звитяги. Він застерігає новачків: попереду не просто обряд — захищати невинних і стояти за Церкву означає бути готовим віддати життя, тож визнання в ордені здобувають лише справді непохитні."}},faq={{q="Яка мета цього завдання?",a="Це завдання з'єднує початкове вивчення святої науки посвячуваного з діяльними, небезпечними випробуваннями. Ознайомившись із Фоліантом Звитяги, молоді паладини з'являються до Дуторіана Ралла в Соборі Світла, щоб просити справжніх випробувань віри й відваги.",al={"що таке завдання фоліант звитяги","навіщо мені це завдання","мета фоліанта звитяги"}},{q="Хто такий Дуторіан Ралл?",a="Дуторіан Ралл — високопоставлений паладин і вчитель у Соборі Світла в Стормвінді. Він керує розвитком багатонадійних захисників і проводить суворі випробування, потрібні, щоб довести, що посвячуваний гідний перед Церквою.",al={"хто такий дуторіан ралл","дуторіан ралл лор","тренер паладинів собору"}},{q="Чому Церква так суворо випробовує своїх паладинів?",a="Церква Святого Світла чекає, що її паладини будуть непохитним оплотом проти відчаю й насильства. Слабка воля чи хистка віра можуть коштувати життів на полі бою, тож наставники загартовують і перевіряють дух посвячуваного, перш ніж посилати його на важливі святі доручення.",al={"чому випробування паладинів небезпечні","чому випробовують звитягу"}},{q="Де відбувається це випробування?",a="Посвячуваний подає своє прохання просто Дуторіанові Раллу в Соборі Світла, що велично стоїть у серці Соборної Площі в Стормвінді.",al={"куди здати фоліант звитяги","місце дуторіана ралла"}}},fp="17,283,20.449.0,22.486.0,34.272.0,22.254.0,50.292.0,33.171.0"}
P.entries["quest:165"] = {n="Самітник",s="Стурбована тим, що старий відлюдник давно не з'являється, Елейн Керевін із Даркшира просить мандрівників провідати його. Самотній старий на ім'я Аберкромбі живе в благенькій хижі на самому краю Цвинтаря Воронячого Пагорба.",h="Стурбована тим, що старий відлюдник давно не з'являється, Елейн Керевін із Даркшира просить мандрівників...",kw={"самітник","аберкромбі","елейн керевін","цвинтар воронячого пагорба","даркшир","сутінколісся"},ang={["faction:Alliance"]="Нічна Варта ледве встигає охороняти шляхи між Даркширом і Воронячим Пагорбом, тож віддалені самітники на кшталт Аберкромбі цілком відрізані від безпеки міста.",["race:Human"]="Родина Каревінів уособлює міцні сусідські зв'язки Сутінколісся: вони дбають навіть про дивакуватих старих громади, хоч увесь край поринає в тінь."},sec={{t="Провідати сусіда",b="У знесиленому поселенні на кшталт Даркшира легко забути про дивакуватих самітників, доки їхня відсутність не стане тривожною. Елейн Керевін згадує старого, що колись регулярно приходив до міста по припаси, а тоді раптом зник з очей. Зважаючи на невпинні небезпеки на шляхах Сутінколісся, вона посилає мандрівних шукачів пригод зазирнути до його хижі над проклятими просторами Цвинтаря Воронячого Пагорба й переконатися, що його не спіткала лиха доля."},{t="Самітник Воронячого Пагорба",b="Діставшись самотньої хатини, мандрівники бачать, що її мешканець — старий на ім'я Аберкромбі — досі живий. Почувши про Каревінів, він тихо посміюється й запевняє, що довго не показувався лише через старість і підступних чудовиськ, які нишпорять лісом. Зрадівши, що на порозі з'явився дужий мандрівник, Аберкромбі не гає часу й питає, чи не зміг би той виконати для нього кілька корисних доручень."}},faq={{q="Хто дає це доручення?",a="Доручення дає Елейн Керевін, мешканка Даркширу в Сутінколіссі, яка турбується за старого самітника, що колись купував припаси в містечку.",al={"хто дає самітника","де почати самітника","завдання елейн керевін"}},{q="Де живе самітник?",a="Аберкромбі живе в напівзруйнованій дерев'яній халупі на північному краю Цвинтаря Воронячого Пагорба в західному Сутінколіссі.",al={"де аберкромбі","де самітник у присмерковому лісі","халупа біля воронячого пагорба"}},{q="Чому Елейн Керевін за нього турбувалася?",a="Аберкромбі раніше регулярно приходив до Даркширу по припаси, але зовсім перестав з'являтися. Дорогами никають дикі звірі й нежить, тож вона боялася, що він загинув.",al={"чому перевірити аберкромбі","чому елейн хвилюється","що сталося зі старим"}},{q="Чи справді Аберкромбі в небезпеці, коли ви його знаходите?",a="Ні. Коли ви приходите до його халупи, Аберкромбі живий-здоровий і тихо тішиться турботою містян: він пояснює, що через небезпечні дороги й похилий вік подорожувати стало просто надто важко.",al={"чи аберкромбі цілий","чи самітник помирає","чи напали на самітника"}},{q="Чому хтось вирішує жити просто біля Цвинтаря Воронячого Пагорба?",a="Аберкромбі запевняє, що полюбляє відлюддя, хоча життя в тіні одного з найбільш осквернених некромантією цвинтарів Східних Королівств багатьох мандрівників бентежить.",al={"чому жити біля воронячого пагорба","халупа аберкромбі біля цвинтаря","чому самітник біля могил"}},{q="Про що просить Аберкромбі, коли ви до нього доходите?",a="Аберкромбі радо користається з того, що на його порозі опинився дужий шукач пригод, і одразу просить допомогти з різними дорученнями й справами в лісі.",al={"чого хоче аберкромбі","наступне завдання самітника","що після самітника"}}},fp="10,225,21.461.0,25.419.0,23.140.0,28.125.0,41.179.0,52.190.0,66.189.0,49.174.0"}
P.entries["quest:1650"] = {n="Фоліант Звитяги",s="Це завдання — друге випробування на шляху паладина до Фоліанта Звитяги. Дуторіан Ралл відсилає лицарів на далекі береги Вестфолу, щоб захистити Дафну Стілвелл — самотню хуторянку, беззахисну перед розбійниками Дефіас, що оточили її.",h="Це завдання — друге випробування на шляху паладина до Фоліанта Звитяги.",kw={"фоліант звитяги","дафна стілвелл","лонгшор","вестфол","дуторіан ралл","паладин"},ang={["class:Paladin"]="Це доручення — важливий обряд посвяти для молодих паладинів: вони мусять полишити безпеку Собору Стормвінда й довести свою звитягу, захищаючи беззахисних.",["faction:Alliance"]="Біда садиби Стілвеллів показує, як далеко Вестфол випав з-під прямого захисту Стормвінда: сільські мешканці мусять самотужки відбиватися від Дефіас."},sec={{t="Заклик до зброї",b="У Соборі Світла Дуторіан Ралл випробовує молодих паладинів не лише Писанням чи самотньою молитвою, а й безпосереднім захистом людей королівства. Прийнявши мантію звитяги, паладини одразу мусять втілювати свої ідеали в життя там, де влада й закон занепали."},{t="Небезпека на Лонгшорі",b="Мета — відлюдний Лонгшор у Вестфолі, де Дафна Стілвелл і її чоловік Джордан тримають садибу біля самого океану. Джордан поїхав до Айронфорджа порадитися з дворфійськими ковалями, тож Дафна лишилася сама серед розгулу Братства Дефіас. Дуторіан наказує паладинові рушати на захід і стати їй щитом, перш ніж злодії здолають її самотній хутір."}},faq={{q="Чому Дафна Стілвелл сама у Вестфолі?",a="Її чоловік, Джордан Стілвелл, — знаний коваль, що поїхав у дворфійське королівство Айронфордж порадитися з іншими ковалями. Через його відсутність Дафні доводиться самотужки боронити їхню прибережну садибу від дедалі частіших нападів Дефіас.",al={"де чоловік дафни","чому джордан стілвелл пішов","дафна стілвелл сама"}},{q="Хто доручає паладинові це завдання?",a="Наказ дає Дуторіан Ралл — провідний наставник паладинів і настоятель у Соборі Світла в Стормвінді, щойно ви доведете, що готові до випробувань звитяги.",al={"хто дає фоліант звитяги","дає завдання фоліант звитяги","завдання дуторіана ралла"}},{q="Де знайти Дафну Стілвелл?",a="Вона живе в невеликій хатинці на крайньому півдні Лонгшору, на узбережжі південно-західного Вестфолу.",al={"де дафна стілвелл","місце дафни стілвелл","знайти дафну стілвелл"}},{q="Чи Дафна цілком безпорадна, коли ви прибуваєте?",a="Аж ніяк. Поки паладин дістається до її ґанку, Дафна власноруч уже поклала своєю зброєю з пів дюжини бандитів Дефіас, утримуючи садибу.",al={"чи дафна може битися","чи дафна безпорадна","дафна стілвелл бій"}},{q="Яка загроза нависла над домом Стілвеллів?",a="Братство Дефіас заполонило більшу частину Вестфолу й постійно нападає на відлюдну прибережну садибу, намагаючись захопити землю й пограбувати те, що лишилося.",al={"хто нападає на дафну","дефіас у вестфолі","вороги на фермі стілвеллів"}},{q="Яке місце це доручення посідає в ланцюжку «Фоліант Звитяги»?",a="У паладинській традиції звитягу вимірюють діяльною жертовністю й захистом беззахисних. Ставши між Дафною й бандитами-грабіжниками, ви на ділі показуєте праведність у дії.",al={"чому я маю допомагати дафні","мета випробування фоліанта звитяги","сенс цього завдання"}}},fp="17,250,14.325.0,22.397.0,41.231.0,37.165.0,35.130.0,46.185.0,42.163.0,52.210.0"}
P.entries["quest:1651"] = {n="Фоліант Звитяги",s="Вирішальне випробування для паладинів, що зростають у силі: це завдання вимагає захистити садибу Дафни Стілвелл від злагодженого нападу Дефіасу. Опинившись у меншості серед відкритих полів Вестфолу, паладин мусить утримати позицію, щоб утілити головну чесноту — звитягу.",h="Вирішальне випробування для паладинів, що зростають у силі: це завдання вимагає захистити садибу Дафни...",kw={"фоліант звитяги","дафна стілвелл","паладин","звитяга","братство дефіас","вестфол"},ang={["class:Paladin"]="Ця битва випробовує вас як незламного захисника. Утримуючи позицію поруч із Дафною, ви показуєте головну чесноту — звитягу — і доводите, що святі воїни існують передусім для того, щоб заступати невинних від лиха.",["faction:Alliance"]="Гарнізон Стормвінда розпорошений і не може вберегти сільські садиби, тож захист вірних громадян Вестфолу лягає на плечі окремих героїв."},sec={{t="Оборона серед пилу",b="Прагнучи чеснот, записаних у Фоліанті Звитяги, паладин вирушає до обложеної садиби Дафни Стілвелл у Вестфолі. Ферма стоїть просто на землі, за яку бореться Братство Дефіас, що вже не раз намагалося захопити господарство й позбутися Дафни. Знаючи, що після попередніх сутичок от-от буде удар у відповідь, захисник мусить рішуче стати біля її дому, а не відступати в безпечніше місце."},{t="Випробування звитягою",b="Маючи лише власну рушницю й те благословення, яке може дати Святе Світло, Дафна й паладин зустрічають хвилю за хвилею нападників Дефіасу. На відміну від двобою, це випробування перевіряє здатність захисника берегти беззахисних під нищівним тиском. Вистояти під натиском — означає довести, що справжня звитяга не в гонитві за особистою славою, а в готовності стати між мирними людьми й безжальним насильством."}},faq={{q="Хто така Дафна Стілвелл?",a="Дафна Стілвелл — витривала поселенка-людина, що живе серед степів Вестфолу. Попри постійні напади Братства Дефіас, вона відмовляється покинути свою землю й рішуче відбивається від бандитських набігів.",al={"дафна стілвелл","хто така дафна","стілвелл вестфол"}},{q="Чому Дефіас нападають саме на цю ферму?",a="Братство Дефіас захопило більшу частину сільського Вестфолу, проганяючи чи підкоряючи місцевих фермерів. Поки її чоловік Джордан в Айронфорджі, Дафна сама й беззахисна, і Дефіас хочуть забрати її землю.",al={"чому дефіас нападають","дефіас напад на дафну","чому нападають на стілвеллів"}},{q="Що таке Фоліант Звитяги?",a="Фоліант Звитяги — священний навчальний текст, яким Церква Святого Світла наставляє молодих паладинів. Лицарі-учні проходять фізичні й духовні випробування по всьому королівству, щоб утілити чесноти, описані на його сторінках.",al={"що таке фоліант звитяги","завдання фоліант звитяги","фоліант звитяги паладин"}},{q="Що буде, якщо Дафна загине в бою?",a="Якщо Дафна Стілвелл загине, випробування провалено. Суть випробування звитяги — вберегти її життя разом зі своїм під час нападу бандитів.",al={"чи дафна може померти","дафна стілвелл гине"}},{q="Де відбувається цей напад?",a="Сутичка відбувається біля будинку Дафни Стілвелл — невеликої ферми на Кинджальних Пагорбах над Лонгшором на півдні Вестфолу.",al={"місце дафни стілвелл","де ферма"}},{q="Що далі, коли ферму захищено?",a="Коли ви доведете свою відвагу й відкинете нападників Дефіас, Дафна визнає вашу відданість і спрямовує вас до наступного етапу паладинських випробувань.",al={"наступне завдання фоліант звитяги","після захисту дафни"}}},fp="17,246,19.450.0,18.431.0,23.219.0,48.232.0,26.239.0,47.163.0,34.143.0,36.157.0"}
P.entries["quest:1652"] = {n="Фоліант Звитяги",s="Це завдання завершує випробування звитяги, які встановила Церква Святого Світла в Стормвінді. Захистивши відлюдний хутір Стілвеллів від розбійників у Вестфолі, молодий паладин повертається до Дуторіана Ралла з вісткою, що Дафна в безпеці. Так утверджується священний обов'язок паладина — бути безкорисливим щитом для невинних.",h="Це завдання завершує випробування звитяги, які встановила Церква Святого Світла в Стормвінді.",kw={"фоліант звитяги","дуторіан ралл","дафна стілвелл","джордан стілвелл","паладин","собор світла"},ang={["class:Paladin"]="Звіт Дуторіанові Раллу завершує ваш урок звитяги й доводить, що ви маєте досить безкорисливості, щоб служити святим захисником Альянсу.",["faction:Alliance"]="Біда родини Стілвеллів пов'язує людські ниви Вестфолу просто з дворфійськими майстернями Айронфорджа й показує, як на ділі залежать одне від одного члени Альянсу."},sec={{t="Священний щит",b="Шлях паладина визначає не лише бойова вправність, а й воля стати між небезпекою та беззахисними. Коли Дафна Стілвелл опинилася в облозі на своїй фермі у Вестфолі, Церква Святого Світла відрядила новачка тримати оборону. Повернувшись до Собору Світла в Стормвінді, новачок приносить вістку, що хутір вистояв, — і доводить, що його мужність не поступається його переконанням."},{t="Зв'язки між королівствами",b="Чоловік Дафни, Джордан Стілвелл, перебуває в Айронфорджі й допомагає Альянсу своєю знаною майстерністю. Тепер, коли хутір під захистом, а Дафна в безпеці, Дуторіан Ралл готує звістку для дворфійського гірського міста на півночі. Запевнення, що його родина під захистом, дасть майстрові змогу зосередитися на роботі — і це показує, як взаємодопомога й відданість паладинів єднають Альянс крізь далекі землі."}},faq={{q="Хто такий Дуторіан Ралл?",a="Дуторіан Ралл — старший наставник паладинів у Соборі Світла в Стормвінді. Він керує духовними й бойовими випробуваннями молодих паладинів, ведучи їх крізь уроки, записані у святих текстах, щоб вони втілювали чесноти звитяги, праведності й смирення.",al={"дуторіан ралл","хто такий дуторіан","тренер паладинів стормвінд"}},{q="Чому Дафна Стілвелл була в небезпеці?",a="Дафна Стілвелл живе на відлюдній садибі у Вестфолі. Довкола бандити Дефіас і беззаконня, тож ферма стала легкою мішенню, поки її чоловік Джордан працював в Айронфорджі.",al={"дафна стілвелл","ферма стілвеллів","хто напав на дафну"}},{q="Хто такий Джордан Стілвелл?",a="Джордан Стілвелл — вправний коваль і майстер, відданий Церкві Святого Світла й Альянсу. Нині він працює в Айронфорджі, віддаючи справі свою майстерність і покладаючись на Церкву, що та захистить його дружину вдома.",al={"джордан стілвелл","чоловік дафни","джордан айронфордж"}},{q="Що таке Фоліант Звитяги?",a="Фоліант Звитяги — це водночас свята книга уроків і низка практичних випробувань, які проводить Собор Світла. У цих випробуваннях паладини доводять, що мають відвагу протистояти темряві й захищати вразливих ціною великого особистого ризику.",al={"значення фоліанта звитяги","що таке фоліант звитяги"}},{q="Що далі, коли випробування пройдено?",a="Коли Дуторіан Ралл визнає вашу звитягу в захисті Дафни Стілвелл, він веде вас до наступного кроку духовного й бойового зростання — «Випробування праведності», що продовжує ваше просування в ордені.",al={"наступне завдання після фоліанта звитяги","що далі"}},{q="Чому Церкву обходить садиба Стілвеллів?",a="Дафна й Джордан Стілвелли давно допомагають Церкві Святого Світла вірною службою й майстерністю. Захистити Дафну, поки Джордана немає, — це відповідь честю на честь і милосердя, виконання обіцянки Церкви дбати про своїх.",al={"чому церква допомагає дафні","церква і стілвелли"}}},fp="17,347,15.427.0,21.438.0,22.283.0,34.192.0,23.245.0,26.263.0,39.224.0,54.255.0"}
P.entries["quest:1653"] = {n="Випробування праведності",s="«Випробування праведності» позначає перехід від захисту невинних у Вестфолі до створення священної зброї паладина. З доручення Дуторіана Ралла новачок вирушає до Айронфорджа, щоб принести добру звістку побожному ковалеві Джорданові Стілвеллу.",h="«Випробування праведності» позначає перехід від захисту невинних у Вестфолі до створення священної зброї...",kw={"випробування праведності","джордан стілвелл","дуторіан ралл","айронфордж","паладин","дун мороґ"},ang={["class:Paladin"]="Цей етап ваших випробувань позначає перехід від захисту слабких до створення священних знарядь, потрібних, щоб викорінювати зло в землях Альянсу.",["faction:Alliance"]="Біда родини Стілвеллів віддзеркалює дедалі більшу нестабільність у Вестфолі, де простий люд бореться з Дефіас, поки королівські радники в Стормвінді зволікають.",["profession:Blacksmithing"]="Джордан Стілвелл доводить, що щира відданість ковадлу може бути таким самим святим виявом віри, як і освячений клинок у руці на полі бою."},sec={{t="Вісник доброї звістки",b="Простоявши на варті біля Дафни Стілвелл під час страшної засідки Дефіас на її хутір у Вестфолі, новачок-паладин повертається на Соборну Площу з доповіддю. Дуторіан Ралл розуміє: звістка має дійти до її чоловіка, Джордана Стілвелла, який поїхав до Айронфорджа, вважаючи, що його родина в небезпеці. Ралл відсилає молодого лицаря особисто принести полегшення — це і вияв братерства, і передмова до значно глибшої справи."},{t="Коваль із Дун Мороґа",b="Джорданові Стілвеллу колись судилося вступити до святого ордену паладинів, але він обрав шанувати ремесло батька як майстер-зброяр, ніколи не зрікаючись віри. Він поставив ковадло за брамою Айронфорджа, щоб працювати на бадьорому гірському повітрі, і довіряє духовній відданості вести його молот. Дізнавшись, що дружина пережила напад Дефіас, Джордан, сповнений глибокої вдячності, береться допомогти паладинові викувати благословенну зброю праведності."}},faq={{q="Хто такий Джордан Стілвелл?",a="Джордан Стілвелл — побожний зброяр, що працює біля величезної головної брами Айронфорджа. Хоча колись він навчався шляхів Світла разом із паладинами, зрештою вирішив присвятити життя продовженню ковальського ремесла свого батька.",al={"джордан стілвелл","хто такий джордан","коваль в айронфорджі"}},{q="Чому дружина Джордана була в небезпеці?",a="Дафна Стілвелл живе на садибі у Вестфолі — непокірному краї, що аж кишить розбійниками Братства Дефіас. Її чоловік, вирушаючи до дворфійської столиці, боявся нападу, і страх справдився: бандити вдерлися на ферму, але посвячувані паладини їх відкинули.",al={"небезпека для дафни стілвелл","що сталося з дружиною джордана","чому дефіас напали"}},{q="Де знайти Джордана Стілвелла?",a="Джордан Стілвелл працює біля головної брами Айронфорджа, серед морозних снігів Дун Мороґу. Свіже гірське повітря він любить більше, ніж задушливий жар Великої Кузні всередині гірського міста.",al={"де джордан стілвелл","місце стілвелла","місце джордана в айронфорджі"}},{q="Чому Дуторіан Ралл посилає гравця до Айронфорджа?",a="Дуторіан Ралл хоче, щоб Джордан почув просто від рятівника своєї дружини, що вона пережила напад Дефіас. Ця подорож також зводить посвячуваного з майстром-ковалем, здатним провести його крізь створення священної паладинської зброї.",al={"чому йти в айронфордж","доручення дуторіана ралла","причина послання"}},{q="Що далі після розмови з Джорданом?",a="Відчувши полегкість від новини, Джордан пропонує свою майстерність, щоб викувати для посвячуваного чудовий святий бойовий молот, а для цього треба зібрати рідкісні матеріали й освячені реліквії, розкидані далекими краями.",al={"випробування праведності далі","чого хоче джордан","після розмови з джорданом"}},{q="Що Джордан думає про загрозу Дефіас?",a="Джордана обурює сліпа недбалість ради Стормвінда. Він зауважує, що Братство Дефіас уже давно поневіряє Вестфол, але сподівається, що напади на чесні садиби нарешті змусять регентів хлопчика-короля визнати кризу.",al={"що джордан думає про дефіас","стілвелл радники короля","дефіас у вестфолі"}}},fp="25,271,24.430.0,23.472.0,23.257.0,32.287.0,35.191.0,53.244.0,38.201.1,45.270.0"}
P.entries["quest:1655"] = {n="Постачання руди Бейлора",s="«Постачання руди Бейлора» — завдання для паладинів, які шукають очищений метал для освяченої зброї Джордана Стілвелла. Вантаж сплаву пограбували огри Мо'ґрош, напавши із засідки на дорозі з Багнокраю.",h="«Постачання руди Бейлора» — завдання для паладинів, які шукають очищений метал для освяченої зброї Джордана...",kw={"постачання руди бейлора","бейлор стоунгенд","джордан стілвелл","огри","мо'ґрош","паладин","сплав"},ang={["class:Paladin"]="Повернути сплав Бейлора — неодмінний обряд Випробування праведності: ви доводите, що здатні кинути виклик небезпечним звірюкам, аби здобути матеріали для свого священного бойового молота.",["faction:Alliance"]="Огри Мо'ґрош у північно-східному Лох Модані лишаються відкритою загрозою для шляхів постачання й валок, що йдуть перевалом із Багнокраю.",["profession:Blacksmithing"]="Особливий сплав Бейлора відповідає суворим металургійним вимогам, яких Джордан Стілвелл дотримується, коли кує легендарну зброю."},sec={{t="Валка в засідці",b="Коли Джорданові Стілвеллу знадобився особливий вантаж руди, очищеної його давнім другом Бейлором Стоунгендом, доставка так і не дісталася до рук Айронфорджа. Коли валка з припасами звивистим шляхом спускалася на південь з Багнокраю до Лох Модану, на неї напали й вирізали огри Мо'ґрош. Останній уцілілий охоронець, накульгуючи, дістався табору, але невдовзі помер від ран, і вантаж лишився на огрячих землях."},{t="Повернути сплав",b="Бейлор Стоунгенд, що отаборився в Лох Модані, посилає паладинів через води озера до північно-східних пагорбів. Там, серед таборів огрів Мо'ґрош, украдена скриня зі сплавом лежить покинутою серед здобичі. Повернувши скриню, паладин доводить, що не боїться вирушити на ворожі землі, а Бейлор може дотримати свого слова перед Джорданом Стілвеллом."}},faq={{q="Хто такий Бейлор Стоунгенд?",a="Бейлор Стоунгенд — дворф-майстер і давній друг Джордана Стілвелла, що працює в Лох Модані. Він відповідає за приготування й постачання особливого сплаву, потрібного для ремесла Джордана.",al={"бейлор стоунгенд","хто такий бейлор","бейлор"}},{q="Хто вкрав поставку руди Джордана?",a="Огри Мо'ґрош напали з засідки на караван із припасами, що йшов із Багнокраю в Лох Модан, убили охорону й потягли вантаж до своїх таборів.",al={"хто вкрав руду","хто забрав поставку","злодії руди"}},{q="Де сталася засідка?",a="На караван напали на гірській дорозі між Багнокраєм і Лох Моданом, перш ніж він дістався безпечних місцевих поселень.",al={"місце засідки","де напали на караван"}},{q="Де табори огрів Мо'ґрош?",a="Огри Мо'ґрош мають укріплені табори на скелястих пагорбах на північний схід від озера, через воду від західних поселень.",al={"де мо'ґрош","місце табору огрів","де поставка"}},{q="Навіщо потрібна ця поставка?",a="У поставці — особливий сплав, потрібний Джорданові Стілвеллу, щоб викувати святу зброю для паладинів, які проходять «Випробування праведності».",al={"навіщо руда","для чого поставка","призначення руди"}},{q="Що сталося з охороною каравану?",a="Майже всіх огри вбили на місці. Єдиний вартовий, якому вдалося втекти й дістатися допомоги, помер за кілька днів, перш ніж цілитель встиг його врятувати.",al={"охорона каравану","хто вижив з каравану"}}},fp="21,229,19.444.0,20.375.0,24.196.0,32.163.0,32.142.0,37.129.0,28.143.0,36.155.0"}
P.entries["quest:166"] = {n="Братство Дефіас",s="Це завдання вінчає довгу кампанію Ґраяна Стаутмантла, що прагне вирвати Вестфол із-під влади розбійників. Захисникам Альянсу належить проникнути в Мертві Копальні, прорватися до злочинного сховку й убити самого натхненника — Едвіна Венкліфа.",h="Це завдання вінчає довгу кампанію Ґраяна Стаутмантла, що прагне вирвати Вестфол із-під влади розбійників.",kw={"братство дефіас","едвін венкліф","мертві копальні","ґраян стаутмантл","вестфол","мунбрук"},ang={["class:Rogue"]="Венкліф — легендарний розбійник і майстер своєї справи; схрестити з ним клинки в його потаємному сховку — випробування вишколу для будь-якого таємного агента.",["faction:Alliance"]="Це завдання приносить Альянсу важливу ранню перемогу: житниця Вестфолу знову в безпеці, хоча трон Стормвінда не зміг виділити для цього власних військ.",["race:Human"]="Для людей королівства смерть Венкліфа — трагедія з гірким присмаком: гине той самий майстер, чиї руки відбудували їхню столицю з попелу."},sec={{t="Вирок винесено",b="Місяцями Ґраян Стаутмантл і знесилене Народне ополчення відчайдушно стримували Братство Дефіас по всьому Вестфолу. Тепер, коли справжнє місце злодійської твердині під Мунбруком розкрито, Стаутмантл оголошує останній, суворий наказ: Едвіна Венкліфа треба вбити, щоб раз і назавжди зламати хребет заколотові."},{t="У лабіринт",b="Щоб виконати вирок, бійцям доведеться спуститися глибоко у звивисті шахти Мертвих Копалень. За каменярами-ренегатами, гоблінськими інженерами й важкими залізними противибуховими дверима лежить центральний сухий док, де Венкліф наглядає за останніми роботами над своїм величезним бойовим кораблем. Смерть Венкліфа розриває ланцюг командування, на якому тримається вся розбійницька мережа."},{t="Тіні ширшої змови",b="Стаутмантл вірить, що смерть Венкліфа — початок кінця Братства, та тіло полеглого ватажка гільдії приховує тривожні таємниці. При ньому знаходять невідправлений лист, з якого видно, що заколот у Вестфолі ніколи не був поодиноким бунтом, а лише частиною ширшого й темнішого павутиння, яке сягає самої знаті Стормвінда."}},faq={{q="Яка мета цього завдання?",a="Ґраян Стаутмантл доручає вам вирушити в підземелля Мертві Копальні в Мунбруку, знищити Едвіна Венкліфа й повернутися з його відтятою головою на Сентінел Гілл.",al={"мета завдання","що робити","що за завдання"}},{q="Хто такий Едвін Венкліф?",a="Едвін Венкліф колись був Великим Каменярем Гільдії Каменярів, що керувала відбудовою Стормвінда після Першої й Другої воєн. Після запеклої суперечки з Домом Вельмож щодо плати він заснував Братство Дефіас, щоб помститися королівству.",al={"хто такий венкліф","особа венкліфа","едвін венкліф лор"}},{q="Чому Ґраян Стаутмантл наказує вбити ватажка?",a="Народному ополченню бракує підкріплення регулярної армії зі Стормвінда, щоб вести затяжну війну. Стаутмантл розуміє, що обезглавити провід — єдиний реальний шанс Вестфолу вирватися з лабет угруповання, що душить його поля.",al={"чому вбити венкліфа","мотив стаутмантла","чому смертна кара"}},{q="Де знайти Едвіна Венкліфа?",a="Він ховається глибоко в Мертвих Копальнях під Мунбруком. Ґраян Стаутмантл просить вас проникнути в сховок і розшукати його.",al={"де венкліф","де едвін венкліф","місце боса мертвих копалень"}},{q="Чи вбивство Венкліфа повністю знищує Дефіас?",a="Стаутмантл сподівається, що смерть Венкліфа зламає владу Братства над Вестфолом. Чим усе обернеться і що ще відкриється, покаже штурм.",al={"чи дефіас переможені","чи дефіас зникли","кінець братства"}},{q="Що примітного знаходять при Венкліфі після його поразки?",a="Стаутмантл вимагає голову Венкліфа як доказ. Інші знахідки в сховку відкриваються під час виконання доручення.",al={"що падає з венкліфа","невідправлений лист","що дропає венкліф"}}},fp="22,257,17.364.0,18.354.1,31.343.1,31.164.0,22.275.0,50.257.0,34.123.0,52.140.1,55.115.1"}
P.entries["quest:1665"] = {n="Кухоль Бартлбі",s="«Кухоль Бартлбі» — завершальне доручення в першому випробуванні гарту для молодого воїна Стормвінда. Здолавши задиристого забіяку Бартлбі в таверні «Свиня і Свисток», шукач пригод забирає його кухоль як доказ перемоги для свого наставника, Гаррі Барлґарда.",h="«Кухоль Бартлбі» — завершальне доручення в першому випробуванні гарту для молодого воїна Стормвінда.",kw={"кухоль бартлбі","бартлбі","гаррі барлґард","свиня і свисток","воїн","маршал гаґґард"},ang={["class:Warrior"]="Наставники Стормвінда вважають, що справжня бійка вчить того, чого не навчить жоден посібник: здобутий кухоль Бартлбі доводить, що ви вмієте стояти віч-на-віч і долати буйних супротивників.",["faction:Alliance"]="Підтримувати лад у Старому Місті часто означає давати раду буйним відвідувачам — тож Бартлбі давно став звичним місцевим головним болем для бойових наставників Стормвінда."},sec={{t="Трофей шинкової бійки",b="Наставникам воїнів у Стормвінді байдуже до витонченої теорії — вони хочуть бачити неприкрашену рішучість і вміння стояти на своєму. Гаррі Барлґард доручає молодим воїнам приборкати Бартлбі — упертого пияка біля стійки «Свині і Свистка» в Старому Місті. Упокорений, Бартлбі неохоче віддає свій улюблений кухоль — але тільки після того, як востаннє добряче ковтне, допиваючи останні краплі."},{t="Крок до майстерності",b="Повернувши кухоль Гаррі Барлґарду, новачок завершує випробування. Оцінивши вміння бійця переконувати голою силою, Барлґард визнає, що воїн готовий опановувати оборонне мистецтво, і скеровує його далі — по нову бойову науку до бувалого ветерана Маршала Гаґґарда в Лісі Елвінн."}},faq={{q="Навіщо Гаррі Барлґарду кухоль Бартлбі?",a="Кухоль — незаперечний доказ, що воїн-новачок справді бився з Бартлбі й переміг. Бартлбі страшенно прив'язаний до свого трунку, тож якщо він віддав свій кухоль, значить, його добряче відлупцювали до покори.",al={"навіщо кухоль бартлбі","навіщо барлґарду кухоль","доказ перемоги над бартлбі"}},{q="Хто такий Бартлбі?",a="Бартлбі — буйний відвідувач таверни, що сидить біля шинквасу «Свині і свистка» в Старому Місті Стормвінда. Відомий пияцтвом і лихою вдачею, він править місцевим наставникам воїнів за неофіційний обряд посвяти для молодих бійців.",al={"бартлбі лор","хто такий бартлбі п'яниця","бартлбі старе місто"}},{q="Де відбувається ця бійка?",a="Бійка відбувається в Таверні «Свиня і свисток» у Старому Місті в Стормвінді.",al={"де бартлбі","місце бартлбі","бійка свиня і свисток"}},{q="Що далі, коли повернеш кухоль Барлґарду?",a="Оглянувши кухоль і переконавшись у вашій перемозі, Барлґард навчає вас складніших оборонних бойових стійок, а тоді посилає за міську браму — розшукати Маршала Гаґґарда в Лісі Елвінн.",al={"що далі після кухля бартлбі","завдання після кухля бартлбі","завдання гаґґарда"}},{q="Чи Бартлбі зазнає в бійці тяжких каліцтв?",a="Ні. Це лише несмертельна шинкова бійка. Переможений Бартлбі здається, допиває свій трунок, віддає кухоль і лишається в таверні зализувати синці й уражену гордість.",al={"чи бартлбі мертвий","чи бартлбі помер","чи бартлбі вижив"}},{q="Чи може будь-який клас Альянсу виконати це завдання?",a="Це доручення призначене суто для воїнів Альянсу як частина класового навчання на 10-му рівні, щоб опанувати бойові стійки й оборонні прийоми.",al={"чи кухоль бартлбі лише для воїнів","хто може виконати бартлбі","класи завдання кухля"}}},fp="14,263,24.402.0,21.338.0,45.218.0,16.237.0,33.91.0,48.203.0,48.184.0,37.166.0"}
P.entries["quest:1666"] = {n="Маршал Гаґґард",s="«Маршал Гаґґард» — завдання Альянсу, яке Гаррі Барлґард у Стормвінді дає воїнам-новачкам, що шукають кращої зброї. Молодого бійця відсилають зі столиці до Лісозаготівельного Табору Східної Долини на сході Лісу Елвінн, щоб зустрітися з відставним військовим маршалом, який зберігає славетну колекцію зброї ветеранів. Це один із перших кроків на бойовому шляху воїна за межами безпечних міських мурів.",h="«Маршал Гаґґард» — завдання Альянсу, яке Гаррі Барлґард у Стормвінді дає воїнам-новачкам, що шукають кращої...",kw={"маршал гаґґард","гаррі барлґард","ліс елвінн","східна долина","воїн","зброя"},ang={["class:Warrior"]="Це завдання — один із перших рубежів для воїнів Альянсу: від упорядкованого міського навчання вони переходять у широкі дикі землі на пошуки бойового спорядження.",["faction:Alliance"]="Це завдання показує, як Стормвінд покладається на досвід і власні запаси відставних ветеранів, щоб виховати наступне покоління захисників."},sec={{t="Збройня ветерана",b="Воїнам-новачкам, що навчаються в Стормвінді, швидко нагадують: сама техніка мало чого варта без надійної сталі. Гаррі Барлґард скеровує перспективних бійців розшукати Маршала Гаґґарда — відставного офіцера королівства, що живе в тихих куточках східного Лісу Елвінн. За ціле життя в походах Гаґґард зібрав чималу власну збройню, тож його садиба — природна мета для молодих воїнів, яким потрібне справжнє спорядження."},{t="На спочинку в Східній Долині",b="Маршал Гаґґард живе у відлюдному маєтку біля Лісозаготівельного Табору Східної Долини. Роки виснажливої служби далися взнаки старому командирові: зір його слабне, і він часто приймає подорожніх, що наближаються, за гнолів Річколапів, які нишпорять довкола. Та попри вік і самотність, старий маршал лишається шанованою постаттю серед вартових і наставників Стормвінда."}},faq={{q="Хто дає це завдання?",a="Гаррі Барлґард, наставник воїнів у Стормвінді, пропонує це завдання, щойно молодий воїн доведе свої основні навички.",al={"де взяти завдання маршала гаґґарда","хто дає маршала гаґґарда","хто дає завдання маршала гаґґарда"}},{q="Де знайти Маршала Гаґґарда?",a="Маршал Гаґґард живе в садибі трохи на схід від Лісозаготівельного Табору Східної Долини, на крайньому сході Лісу Елвінн, біля кордону з Горами Редріджу.",al={"місце маршала гаґґарда","де гаґґард","маєток табору лісорубів іствейл"}},{q="Чому Гаррі Барлґард посилає вас до Гаґґарда?",a="Барлґард розуміє, що воїнові, який зростає, потрібне добре спорядження, а не звичайні учнівські клинки. За довгу службу Гаґґард зібрав чимало зброї й обладунків і, як відомо, охоче ділиться спорядженням із тими, хто доведе, що гідний.",al={"чому маршал гаґґард","чому йти до воїна в іствейл","мета завдання маршала гаґґарда"}},{q="Чому Гаґґард приймає відвідувачів за гнолів?",a="На старість зір Гаґґарда дуже погіршився. Гноли часто непокоять східні лісозаготівлі й околиці Лісу Елвінн, тож обережний старий ветеран завжди насторожі щодо раптових гостей.",al={"зір гаґґарда","чи гаґґард сліпий","діалог гаґґарда про гнолів"}},{q="Що далі після цього завдання?",a="Привітавши вас, відставний маршал перевіряє вашу відвагу, посилаючи вас на завдання «Мертвозубий Джек», перш ніж розщедритися на якусь зброю зі своїх запасів.",al={"наступне завдання маршала гаґґарда","що після маршала гаґґарда"}},{q="Чи доступне це завдання іншим класам, окрім воїнів?",a="Ні. Цей ланцюжок — частина класового розвитку воїна на 10-му рівні, покликаного спорядити молодих бійців до випробувань за межами Лісу Елвінн.",al={"чи паладини можуть маршала гаґґарда","завдання гаґґарда лише для воїнів"}}},fp="15,402,18.447.0,22.364.0,22.144.0,33.167.0,45.245.0,45.226.0,39.178.1,55.142.0"}
P.entries["quest:1667"] = {n="Мертвозубий Джек",s="Маршала Гаґґарда, відставного офіцера, що живе на сході Лісу Елвінн, обманом змусили віддати свій службовий знак розбійникові Дефіас на ім'я Мертвозубий Джек. У темряві Джек накинув стормвіндську накидку й видав себе за Маршала Дуґана, аби вкрасти значок. Гаґґард просить повернути його, поки Братство Дефіас не скористалося ним, щоб видавати себе за урядовців Стормвінда.",h="Маршала Гаґґарда, відставного офіцера, що живе на сході Лісу Елвінн, обманом змусили віддати свій службовий...",kw={"мертвозубий джек","маршал гаґґард","знак","дефіас","самозванець","ліс елвінн"},ang={["class:Rogue"]="Витівка Мертвозубого Джека доводить, що Братство Дефіас спирається на маскування, хитрість і зухвалість не менше, ніж на грубий розбій на дорогах.",["class:Warrior"]="Маршал Гаґґард колись був загартованим бійцем передової, і тим, хто повертає йому честь, він віддячує запасною зброєю, збереженою з років дійсної служби.",["race:Human"]="Для людей Стормвінда ця крадіжка показує, наскільки вразливі сільські околиці королівства перед шпигунами Дефіас, які без вагань надягають кольори корони, щоб обдурити відставних ветеранів."},sec={{t="Шахрайство в темряві",b="Навіть загартованих вояків на схилі літ можна заскочити зненацька. Маршал Гаґґард, що живе в самотній хатині на східних пагорбах Елвінну, був певен, що розмовляє з Маршалом Дуґаном, коли одного вечора до нього підійшов чоловік у стормвіндській накидці. Пославшись на службову справу, незнайомець попросив старий маршальський знак Гаґґарда. Гадаючи, що передає його товаришу по службі, Гаґґард послухався — а самозванець, злодій Дефіас на прізвисько Мертвозубий Джек, тільки й зміг, що засміятися йому в обличчя й зникнути в лісі."},{t="Загроза фальшивої влади",b="Хоч Гаґґард у відставці, його старий знак і досі має законну вагу й владу Королівства Стормвінд. Поки бандити Дефіас розповзаються Елвінном, Вестфолом і Редріджем, справжній офіцерський знак у руках злочинців — безпосередня небезпека. З ним шпигуни можуть проходити повз пости варти, переспрямовувати патрулі чи забирати припаси. Джек відходить до табору на півдні, щоб сховати крадену здобич у замкненій скрині, а Гаґґард відчайдушно сподівається повернути знак, перш ніж станеться непоправне."}},faq={{q="Хто такий Мертвозубий Джек?",a="Мертвозубий Джек — агент Братства Дефіас, що орудує у східній частині Лісу Елвінн. Відомий своєю зухвалістю, він під покровом темряви видав себе за Маршала Дуґана, щоб ошукати відставного Маршала Гаґґарда й виманити в нього офіційний значок Стормвінда.",al={"мертвозубий джек","хто такий мертвозубий","мертвозубий джек лор"}},{q="Чому Маршалові Гаґґарду треба повернути значок?",a="Значок — справжній символ влади Стормвінда. Гаґґард боїться, що, якщо Дефіас залишать його в себе, то видаватимуть себе за урядовців, обходитимуть військові патрулі й сіятимуть хаос по всьому королівству.",al={"чому повернути значок","значок гаґґарда","чому значок важливий"}},{q="Як Джекові вдалося обдурити Маршала Гаґґарда?",a="Джек підійшов до хатини Гаґґарда вночі в табарді Стормвінда. У поганому світлі Гаґґард сплутав його з Маршалом Дуґаном із Ґолдширу й без жодних питань віддав відзнаку, коли той її попросив.",al={"як він обдурив гаґґарда","гаґґарда обманули","чому гаґґард віддав значок"}},{q="Де Джек тримає вкрадений значок?",a="Джек тримає значок замкненим у скриньці у своєму бандитському таборі на південь від будинку Маршала Гаґґарда. Ключ від скрині він носить при собі.",al={"місце значка","де значок","табір мертвозубого"}},{q="Хто взагалі послав вас до Маршала Гаґґарда?",a="Гаррі Барлґард — ветеран-воїн, що частенько сидить у Таверні «Свиня і свисток» у Стормвінді, — посилає шукачів пригод до Гаґґарда, знаючи, що в старого маршала є зайва зброя, з якою він може розлучитися в обмін на допомогу.",al={"хто послав вас сюди","барлґард","хто дає це завдання"}},{q="Що буде, коли значок повернуто?",a="Гаґґард відчуває величезну полегкість, що Дефіас не зможуть використати його ім'я чи звання проти королівства. На знак вдячності він віддає вам честь і пропонує на вибір добре доглянуту військову зброю з часів своєї служби.",al={"здати завдання","реакція гаґґарда","значок повернуто"}}},fp="15,375,17.532.0,29.519.0,23.253.0,45.200.0,44.199.0,38.156.0,51.204.0,40.207.1"}
P.entries["quest:167"] = {n="Ох, брате. . .",s="«Ох, брате. . .» — завдання Альянсу від Вайлдера Тістлнетла в Стормвінді. Убитий горем після обвалу під час експедиції в глибини під Мунбруком, Вайлдер просить шукачів пригод обшукати лабіринт шахт і знайти його зниклого брата, Наглядача Тистлнеттла, — або принаймні повернути його відзнаку Ліги Дослідників.",h="«Ох, брате.",kw={"ох брате","вайлдер тістлнетл","наглядач тистлнеттл","ліга дослідників","мертві копальні","мунбрук"},ang={["faction:Alliance"]="Мертві Копальні — виразка на порозі Стормвінда, і це завдання показує, наскільки глибоко Дефіас і підземні жахіття скалічили життя безневинних людей.",["race:Dwarf"]="Трагічна загибель наглядача з Ліги Дослідників на людських землях зачепить кожного дворфа, якому дорогі братерство, каменярство й невтомна праця Ліги."},sec={{t="Замурована експедиція",b="Вайлдер Тістлнетл і його брат спустилися в печерні тунелі під Мунбруком у складі шахтарської бригади. Та все обернулося катастрофою: місцину заполонили ворожі злодії, а потужний обвал відрізав нижні тунелі. Вайлдерові вдалося втекти до Стормвінда, а брат і решта бригади лишилися замкненими за завалом."},{t="Гірка доля Наглядача Тистлнеттла",b="Кожного рятівника, що заглибиться в тунелі Мертвих Копалень, чекає трагічна правда. Наглядач Тистлнеттл не пережив ув'язнення під землею: темні сили, що ворушаться в покинутих шахтах, оживили нещасного дворфа, перетворивши його на неживу оболонку. Він блукає підземними печерами разом з іншими неспокійними мерцями, і від колишнього наглядача лишилася тільки дорога його серцю відзнака Ліги Дослідників."}},faq={{q="Де взяти завдання «Ох, брате. . .»?",a="Це завдання дає Вайлдер Тістлнетл, якого можна знайти в Дворфійському Кварталі Стормвінда.",al={"хто дає ох, брате","хто дає завдання ох, брате","де взяти ох, брате"}},{q="Де шукати Наглядача Тистлнеттла?",a="Наглядач Тистлнеттл блукає зовнішніми штреками Мертвих Копалень під селищем Мунбрук у Вестфолі. Він у тій частині тунелів, де кишить нежить, — ще перед порталом до підземелля.",al={"місце тистлнеттла","де тистлнеттл","де брат"}},{q="Що сталося з Наглядачем Тистлнеттлом?",a="Обвал замкнув Наглядача Тистлнеттла та його гірницьку бригаду в печерах, і відтоді про них нічого не чути. Лише знайшовши його — чи бодай його значок, — Вайлдер дізнається, що спіткало брата.",al={"чи тистлнеттл живий","що сталося з братом","тистлнеттл лор"}},{q="Який предмет треба принести?",a="Вам треба принести значок Ліги Дослідників Наглядача Тистлнеттла, з яким той ніколи не розлучався: знайдіть наглядача глибоко в тунелях Мертвих Копалень — значок буде при ньому.",al={"предмет завдання ох, брате","що падає для ох, брате"}},{q="Що робила експедиція в Мунбруку?",a="Обидва брати працювали в гірничій компанії, що розробляла величезну копальню під Мунбруком, аж поки на них не напали бандити Дефіас, а раптовий обвал тунелю не розлучив їх.",al={"чому дворфи у вестфолі","ліга дослідників мертві копальні","чому вони були в мунбруку"}},{q="Чи виконується це завдання всередині підземелля Мертві Копальні?",a="Ні, заходити в саме підземелля не потрібно. Наглядач Тистлнеттл — елітний супротивник, який блукає спірними тунелями копальні на підступах до порталу підземелля.",al={"чи ох, брате у мертвих копальнях","чи потрібна група в підземелля"}}},fp="15,316,20.372.0,38.411.1,45.105.0,39.207.0,39.215.1,32.173.1,43.182.0,62.168.0"}
P.entries["quest:1679"] = {n="Мурен Стормпайк",s="«Мурен Стормпайк» — вступне завдання для воїнів Альянсу, що набираються досвіду: його дають, щойно новобранець доведе свою базову стійкість у Дун Мороґу. За вказівкою Ґраніса Свіфтекса в Хараносі молодий боєць вирушає до гірського міста Айронфорджа по справжню бойову науку. Зустріч із Муреном знаменує початок глибшого навчання бойових стійок і дворфійських військових традицій.",h="«Мурен Стормпайк» — вступне завдання для воїнів Альянсу, що набираються досвіду: його дають, щойно...",kw={"мурен стормпайк","ґраніс свіфтекс","зала зброї","військовий квартал","айронфордж","воїн","оборонна стійка"},ang={["class:Warrior"]="Цей виклик знаменує ваш обряд посвяти: із завзятого новобранця ви стаєте дисциплінованим солдатом, здатним тримати стрій і захищати союзників.",["race:Dwarf"]="Для дворфійських бійців з'явитися до Зали Зброї — значить безпосередньо долучитися до славетного бойового родоводу й тактичної дисципліни гірських кланів.",["race:Gnome"]="Гноми-воїни, що після падіння Гномреґану перебралися до Дун Мороґа, покладаються на Залу Зброї в Айронфорджі, щоб опанувати традиційний важкий бій на передовій."},sec={{t="Виклик до Айронфорджа",b="Загартувавшись у сутичках із місцевими загрозами в засніжених долинах Дун Мороґа, воїни-новачки привертають увагу Ґраніса Свіфтекса в Хараносі. Розуміючи, що проста бійка далеко забіяку не заведе, Свіфтекс посилає обдарованих бійців до серця дворфійської бойової майстерності — Військового Кварталу Айронфорджа. Там, у гулких залах міста-кузні, досвідчені вояки опікуються справжнім навчанням тих, кому судилося йти в бій."},{t="Майстер зброї",b="Діставшись Зали Зброї, новобранці знайомляться з Муреном Стормпайком — досвідченим ветераном славетного дворфійського клану. Корчемні байки Мурена не цікавлять: він вимагає доказів, що нові підопічні витримають справжній бій. Зустріч із ним відкриває шлях до опанування оборонного мистецтва — уміння приймати на себе й стримувати ворожий натиск — і до добре викуваної залізної зброї, гідної справжньої служби на передовій."}},faq={{q="Хто посилає шукати Мурена Стормпайка?",a="Ґраніс Свіфтекс, наставник воїнів у Хараносі, дає вам це завдання, щойно ви доведете свою базову бойову вправність у Дун Мороґу.",al={"хто дає завдання мурена стормпайка","де взяти мурена стормпайка","хто посилає до мурена стормпайка"}},{q="Де знайти Мурена Стормпайка?",a="Мурен Стормпайк перебуває в Залі Зброї, що у Військовому Кварталі на східному боці Айронфорджа.",al={"де мурен стормпайк","місце мурена стормпайка","як знайти мурена"}},{q="Чому це завдання важливе для воїнів?",a="З Мурена починається поглиблене навчання воїна. Далі йдуть завдання, що відкривають Захисну стійку, навчають важливих захисних умінь на кшталт Провокації й винагороджують надійною зброєю для перших пригод.",al={"що відкриває мурен стормпайк","навіщо мурен стормпайк","нагороди мурена стормпайка"}},{q="Хто такий Мурен Стормпайк?",a="Мурен — досвідчений бойовий наставник з Айронфорджа зі славетного клану Стормпайк, впливового дворфійського роду, відомого запеклими воїнами та інженерами-дослідниками.",al={"хто такий мурен","мурен стормпайк лор","чи мурен із клану стормпайк"}},{q="Чи може це завдання взяти будь-який клас?",a="Ні. Це завдання — лише для молодих воїнів, готових до особливого бойового вишколу.",al={"чи не воїни можуть мурена стормпайка","чи мурен стормпайк лише для воїнів","класи мурена стормпайка"}},{q="Що відбувається після зустрічі з Муреном?",a="Щойно ви прибудете й поговорите з Муреном, він одразу випробує вашу рішучість і відправить на бойове випробування — почнеться все із завдання вистояти проти Вейрека.",al={"що далі після мурена стормпайка","наступне завдання після мурена стормпайка","завдання верека"}}},fp="15,395,22.444.0,18.414.0,38.145.0,33.115.0,41.202.0,23.180.0,30.105.0,38.158.0"}
P.entries["quest:168"] = {n="Збір спогадів",s="«Збір спогадів» — скорботне доручення дворфа-шахтаря Вайлдера Тістлнетла в Стормвінді. Він просить шукачів пригод, які наважаться спуститися в зруйновані шахти під Мунбруком, повернути Картки Спілки Шахтарів його загиблих товаришів. Ці картки дадуть скорботним родинам у столиці змогу нарешті відпустити біль після страшного обвалу.",h="«Збір спогадів» — скорботне доручення дворфа-шахтаря Вайлдера Тістлнетла в Стормвінді.",kw={"збір спогадів","вайлдер тістлнетл","картка спілки шахтарів","мунбрук","мертві копальні","обвал"},ang={["faction:Alliance"]="Повертаючи пам'ятні знаки загиблих робітників Вестфолу, ви підтримуєте робітничі родини, що в жалобі переживають скрутні часи за мурами Стормвінда.",["profession:Mining"]="Кожен шахтар знає той невідступний страх перед обвалом, тож завдання повернути загублені картки глибоко відгукується в серці всіх, хто тримає кайло.",["race:Dwarf"]="Дворфи високо цінують узи, викувані під землею, і святість пам'яті полеглих побратимів, тож прохання Вайлдера Тістлнетла особисто зачіпає кожного з кам'яного роду."},sec={{t="Трагічний обвал",b="Поки Мунбрук ще не поринув у беззаконня й тінь Братства Дефіас, шахти Вестфолу годували чимало робітничих родин. Вайлдер Тістлнетл пережив нищівний обвал, що поховав одне з крил лабіринту тунелів, але багатьом його друзям і товаришам не пощастило. Відрізані від порятунку, вони загинули глибоко під землею, а їхні рідні в Стормвінді так і не отримали ні певної звістки, ні змоги попрощатися."},{t="Неспокійні останки",b="Тунелі довкола головних підземних ливарень — уже не тихі гробниці. Душі шахтарів, що загинули під обвалом, блукають темними переходами неспокійними неживими оболонками. Щоб повернути Картки Спілки Шахтарів, подорожнім доведеться пройти цими проклятими шахтами й зустрітися з ожилими останками тих самих копачів, з якими колись працював Вайлдер. Повернені до Стормвінда картки нарешті відкриють родинам правду й дадуть Вайлдерові змогу вшанувати полеглих побратимів."}},faq={{q="Хто такий Вайлдер Тістлнетл?",a="Вайлдер Тістлнетл — дворф-гірник, який живе в Стормвінді. Він пережив катастрофічний обвал тунелю під Вестфолом, що забрав життя його близьких товаришів, і тепер хоче принести їхнім родинам спокій і певність.",al={"вайлдер тістлнетл","хто дає завдання","хто дає збір спогадів"}},{q="Що сталося з гірниками в Мертвих Копальнях?",a="Нищівний обвал замкнув і поховав цілу бригаду гірників в одному з крил розкопок Мунбрука. Позбавлені порятунку й гідного поховання, їхні духи й тіла повстали неспокійною нежиттю, що блукає покинутими ходами.",al={"чому є мертві гірники","обвал шахти","обвал мертвих копалень"}},{q="Навіщо Вайлдерові їхні картки Спілки гірників?",a="Профспілкові картки — офіційні посвідчення робітників, які загинули під обвалом. Тіла так і не дістали, тож лише з цими картками Вайлдер зможе офіційно сповістити їхні родини в Стормвінді й дати їм змогу попрощатися.",al={"навіщо картки спілки","картки спілки гірників"}},{q="Де шукати профспілкові картки?",a="Картки трапляються в населених примарами зовнішніх тунелях під Мунбруком — у коридорах перед самим входом до охоронюваних глибин Мертвих Копалень.",al={"де знайти картки","місце нежиті мертвих копалень","де мертві гірники"}},{q="Чи винне Братство Дефіас в обвалі?",a="Вайлдер Тістлнетл згадує це просто як жахливий нещасний випадок — обвал тунелю. Хоча тепер у глибоких ходах Мертвих Копалень панує Братство Дефіас, сама трагедія, схоже, була звичайною виробничою катастрофою, яка замурувала його товаришів.",al={"чи дефіас спричинили обвал","хто зруйнував шахту"}},{q="Чи вважаються гірники частиною Братства Дефіас?",a="Ні. Це були звичайні робітники зі спілки, які працювали в копальні, коли стався обвал. Їхні неспокійні мертві рештки блукають околицями печер окремо від організованих сил Дефіас Едвіна Венкліфа, що засіли глибше.",al={"чи мертві гірники дефіас","чи гірники нежить з дефіас"}}},fp="19,339,17.529.0,16.482.0,28.247.0,45.237.0,47.237.0,32.162.0,45.261.0,57.210.0"}
P.entries["quest:1681"] = {n="Поселення Айронбенда",s="Коваль Айронфорджа Тормус Діпфордж прагне помсти за свого наставника, Стерджі Айронбенда, чия віддалена навчальна застава на сході Дун Мороґу впала під раптовим і кривавим нападом. Різанина сталася після прибуття рідкісної партії тіньової руди, яка одразу привернула люту увагу дворфів Темного Заліза.",h="Коваль Айронфорджа Тормус Діпфордж прагне помсти за свого наставника, Стерджі Айронбенда, чия віддалена...",kw={"поселення айронбенда","стерджі айронбенд","тормус діпфордж","темне залізо","тіньова руда","помста","озеро ложа гелма"},ang={["profession:Blacksmithing"]="Трагічна доля Стерджі Айронбенда — пересторога про те, як гонитва за екзотичними, невипробуваними рудами може накликати смертельні небезпеки на кузню.",["race:Dwarf"]="Набіг на заставу Айронбенда підкреслює гірку й незгасну ненависть між дворфами Бронзбірдами з Айронфорджа та їхніми родичами з Темного Заліза."},sec={{t="Падіння майстра",b="Стерджі Айронбенда шанували по всьому Айронфорджу як неперевершеного вчителя ковальського ремесла. У своєму відлюдному поселенні на південь від Озера Ложа Гелма він навчав перспективних учнів далеко від людних ковадел Великої Кузні. Та мирна справа раптово скінчилася, коли один з учнів здобув незнайомий мінерал, названий тіньовою рудою. Зацікавлений її властивостями, Айронбенд вирішив поекспериментувати зі зразком, геть не підозрюючи, що саме володіння ним прирекло його школу на загибель."},{t="Набіг Темного Заліза",b="Невдовзі після того, як тіньова руда потрапила до поселення, ворожі дворфи Темного Заліза здійснили безжальний раптовий напад на заставу. Нападники не знали милосердя: вони вирізали Стерджі Айронбенда й кожного учня під його опікою, а тоді зайняли угіддя. Тормус Діпфордж, один з уцілілих вихованців Айронбенда, що живе в столиці, відмовляється лишити різанину безкарною й посилає мандрівників Альянсу помститися за вчителя та повернути прокляту руду, що принесла загибель поселенню."}},faq={{q="Де розташоване Поселення Айронбенда?",a="Поселення Айронбенда лежить у східному Дун Мороґу, сховане серед засніжених пагорбів на південь від Озера Ложа Гелма.",al={"місце айронбенда","де поселення","знайти поселення айронбенда"}},{q="Ким був Стерджі Айронбенд?",a="Стерджі Айронбенд був знаним дворфійським майстром-ковалем. Неподалік Айронфорджа він тримав навчальне поселення, де вчив учнів тонкощів ковальства, — аж доки не загинув під час набігу Темного Заліза.",al={"хто такий айронбенд","стерджі айронбенд лор","хто був стерджі"}},{q="Чому дворфи Темного Заліза напали на поселення?",a="Напад спровокувала партія тіньової руди, яку привіз один з учнів Айронбенда. Невдовзі після того, як руда прибула, дворфи Темного Заліза налетіли на поселення, перебили всіх, хто там був, і захопили його.",al={"чому напали на поселення","чому дворфи темного заліза напали","мотив темного заліза"}},{q="Що таке тіньова руда?",a="Тіньова руда — рідкісний і загадковий мінерал. Майстер Айронбенд дуже хотів її перекувати, але щойно її привезли, як нею смертельно зацікавився клан Темного Заліза.",al={"лор тіньової руди","що таке тіньова руда","дивна руда"}},{q="Хто такий Тормус Діпфордж?",a="Тормус Діпфордж — коваль з Айронфорджа й колишній учень Стерджі Айронбенда. Приголомшений загибеллю вчителя, він посилає шукачів пригод покарати загарбників з Темного Заліза й повернути руду.",al={"хто дає поселення айронбенда","тормус діпфордж лор","хто такий діпфордж"}},{q="Що Тормус хоче повернути з поселення?",a="Тормус доручає мандрівникам знищити нападників з Темного Заліза, щоб помститися за Айронбенда, і забрати партію тіньової руди, через яку й сталося лихо.",al={"що забрати","мета поселення","здати завдання"}}},fp="19,307,15.487.0,18.496.0,37.101.0,24.208.0,50.230.0,19.169.0,24.205.0,50.149.0"}
P.entries["quest:1683"] = {n="Ворлус Вайлгуф",s="«Ворлус Вайлгуф» — обряд посвяти для молодих воїнів нічних ельфів, що навчаються в Дарнасусі. За настановою наставниці воїнів Еланарії кандидати мають вистежити мерзенного сатира, який осквернив приховану місячний колодязь біля Курганного Лігва Бан'етіл.",h="«Ворлус Вайлгуф» — обряд посвяти для молодих воїнів нічних ельфів, що навчаються в Дарнасусі.",kw={"ворлус вайлгуф","сатир","місячний колодязь","курганне лігво бан'етіл","еланарія","воїн","ріг"},ang={["class:Warrior"]="Полювання на Ворлуса Вайлгуфа — ваша посвята у вищу бойову науку: воно доводить, що ваш клинок служить захисту земель калдореїв і святості богині.",["faction:Alliance"]="Очищення глибин Тельдрассилу від демонічних недобитків гарантує, що Дарнасус і далі буде незламною твердинею Альянсу на півночі Калімдору.",["race:NightElf"]="Місячні колодязі — втілення чистоти Елуни й життєдайна сила духовності калдореїв; сатир, що купається в їхніх водах, — нестерпна образа для кожного нічного ельфа."},sec={{t="Випробування рішучості",b="Перш ніж передати молодим воїнам нічних ельфів вищі бойові прийоми, Еланарія вимагає доказів їхньої відданості й дисципліни. Самі лише слова нічого не важать у захисті Калімдору: справжній охоронець має бути готовий зустріти скверну віч-на-віч і очистити від неї священне гілля Тельдрассилу."},{t="Осквернення священних вод",b="Мета цього випробування — Ворлус Вайлгуф, сатир, що проник до відлюдної місячного колодязя, захованої в горах на південний схід від Курганного Лігва Бан'етіл. Сатири — давні зрадники, спотворені демонічним впливом, — споконвіку ненавидять священні реліквії калдореїв. Ворлус узяв собі за звичку купатися в місячному колодязі: самою своєю присутністю він оскверняє її благословенні води й глузує з благодаті Елуни."},{t="Ріг як трофей",b="Щоб знайти Ворлуса, доведеться пройти прихованою гірською стежкою, яку стережуть ворожі фурболги Вузлошкірів. Загнаного в кут біля оскверненого джерела сатира треба вбити в чесному бою. Ріг Ворлуса, принесений на Терасу Воїна в Дарнасусі, доводить загибель звіра, повертає святість відлюдній галявині й відкриває шлях до особливої бойової зброї."}},faq={{q="Хто такий Ворлус Вайлгуф?",a="Ворлус Вайлгуф — зіпсований скверною сатир, що живе на Тельдрассилі. Він натрапив на відлюдний місячний колодязь на південний схід від Курганного Лігва Бан'етіл і почав у ньому купатися, оскверняючи його освячені води.",al={"ворлус вайлгуф лор","хто такий ворлус","ворлус сатир"}},{q="Чому Еланарія посилає воїнів по Ворлуса?",a="Для Еланарії це полювання — випробування для перспективних воїнів. Перемога над таким небезпечним і зіпсованим поганцем, як Ворлус, доводить зосередженість, відвагу й рішучість, без яких вона не навчатиме складніших бойових умінь і не допомагатиме викувати особливу зброю.",al={"чому вбити ворлуса","причина завдання еланарії","мета ворлуса вайлгуфа"}},{q="Де схований місячний колодязь?",a="Місячний колодязь схований серед хребтів на південний схід від Курганного Лігва Бан'етіл. Щоб дістатися до нього, треба знайти малопомітну гірську стежку з факелами — вона починається одразу за табором фурболгів-Вузлошкірів на схід від курганів.",al={"місце ворлуса","як знайти ворлуса","прихована стежка до місячного колодязя"}},{q="Що таке місячний колодязь і чому присутність Ворлуса так важить?",a="Місячні колодязі — священні чаші з благословенною водою, що спрямовує світло Елуни й живить силу природи. Коли демонічний сатир на кшталт Ворлуса валяється в такому колодязі, це пряме осквернення віри калдореїв і небезпечне джерело скверни на Тельдрассилі.",al={"чому місячні колодязі важливі","осквернення місячного колодязя","місячні колодязі нічних ельфів"}},{q="Що далі після перемоги над Ворлусом Вайлгуфом?",a="Відрубаний ріг Ворлуса задовольняє Еланарію й підтверджує, що воїн готовий. Далі вона спрямує воїна на пошуки легендарної зброї з елуніту — почати доведеться з того, щоб розшукати Примару Елури.",al={"наступне завдання після ворлуса","що буде далі","завдання примари елури"}},{q="Чи є на Тельдрассилі інші сатири?",a="Так. Хоч Тельдрассил і доволі молодий, сатири ховаються в таких місцях, як Скеля Скверни, та в розкиданих осквернених улоговинах і невпинно намагаються заразити Світове Дерево демонічною скверною.",al={"сатири на тельдрассилі","загроза сатирів тельдрассил"}}},fp="15,245,17.315.0,26.388.0,17.363.1,23.199.0,45.261.0,37.222.0,53.271.0,43.217.1,37.178.0"}
P.entries["quest:1685"] = {n="Ґакін кличе",s="«Ґакін кличе» — виклик, який Ремен Маркот передає від імені Ґакіна Зв'язувача Темряви перспективним чорнокнижникам Альянсу. Він скеровує молодих адептів у склепи під шинком «Зарізане Ягня» в Кварталі магів Стормвінда, де починається наступний етап їхнього темного окультного навчання.",h="«Ґакін кличе» — виклик, який Ремен Маркот передає від імені Ґакіна Зв'язувача Темряви перспективним...",kw={"ґакін кличе","ґакін зв'язувач темряви","ремен маркот","зарізане ягня","блукач порожнечі","чорнокнижник"},ang={["class:Warlock"]="Цей виклик означає, що ви переросли салонні фокуси й дрібних бісів: починаються випробування, потрібні, щоб поневолити блукача Порожнечі, який захищатиме вас у бою.",["faction:Alliance"]="Навіть у серці Стормвінда Альянс терпить підземне коло тіньових ткачів, чиє знання скверни дає потайну перевагу над ворогами."},sec={{t="Потайне послання",b="Демонологія суворо заборонена в упорядкованих кварталах Стормвінда, та темні мистецтва живуть просто під носом у міської варти. Коли чорнокнижник виявить достатню вправність зі своїми першими бісами, звістка тихо доходить до старших адептів. Ремен Маркот передає послання підкреслено обережно: він велить новачкам тримати місце зустрічі в таємниці й спуститися в темні закутки під Кварталом магів."},{t="Склепи «Зарізаного Ягняти»",b="За скромним фасадом шинку «Зарізане Ягня» ховається мережа вогких підвалів і потаємних катакомб. Тут, подалі від допитливих магів Кірін-Тору й інквізиторів Собору, Ґакін Зв'язувач Темряви наглядає за навчанням чорнокнижників Стормвінда. Його виклик відчиняє шлях до влади над блукачем Порожнечі — обряду, що вимагає небезпечних крадених реагентів і ризикованих кіл призову."}},faq={{q="Чому Ґакін Зв'язувач Темряви скликає чорнокнижників?",a="Ґакін кличе до себе чорнокнижників-початківців, щойно ті наберуться достатньо досвіду. Ненавчений чорнокнижник, на його думку, — це ризик: такий легко втратить голову. Тож Ґакін хоче навчити їх складного ритуалу, що підкоряє блукача Порожнечі.",al={"чому ґакін скликає","навіщо ґакін кличе","початок завдання порожнеходця"}},{q="Де знайти Ґакіна Зв'язувача Темряви?",a="Ґакін ховається в глибоких підземних криптах під корчмою «Зарізане Ягня» в Кварталі магів Стормвінда.",al={"де ґакін","місце ґакіна","підвал забитого ягняти"}},{q="Хто такий Ремен Маркот?",a="Ремен Маркот — спільник ковену чорнокнижників Стормвінда. Він розшукує в місті перспективних кандидатів і потай спрямовує їх до схованки Ґакіна.",al={"ремен маркот","хто починає ґакін кличе"}},{q="Чому місце треба тримати в таємниці?",a="Магія скверни й закликання демонів у Королівстві Стормвінд заборонені. Якщо про це дізнається Срібна Длань, Собор Світла чи міська варта, на винних чекає в'язниця або страта.",al={"чому таємниця","таємність чорнокнижників стормвінд"}},{q="Що далі, коли відгукнешся на поклик Ґакіна?",a="Коли чорнокнижник з'явиться до Ґакіна, той доручить йому вирушити на Гарбузову Ділянку Брекуеллів у Лісі Елвінн і забрати в Сурени Каледон намисто з кровавиком — без нього не обійтися в ритуалі підкорення блукача Порожнечі.",al={"наступне завдання після ґакін кличе","що буде далі"}},{q="Чи можуть цей поклик отримати не чорнокнижники?",a="Ні. Поклик — лише для чорнокнижників, які вже опанували свого першого біса й потребують глибшої окультної науки.",al={"чи маги можуть це","хто може виконати ґакін кличе"}}},fp="15,265,18.434.0,34.392.0,46.241.0,38.128.0,20.174.0,37.188.0,43.219.1,38.135.0"}
P.entries["quest:1686"] = {n="Тінь Елури",s="«Тінь Елури» — один із перших обрядів посвяти для молодих воїнів нічних ельфів, який доручає наставниця воїнів Еланарія в Дарнасусі. Воїн має пірнути у води біля Обердайна, упокоїти привида змученої капітанки й підняти ящики з рідкісною елунітовою рудою. З цих матеріалів потім виковують бойову зброю на замовлення.",h="«Тінь Елури» — один із перших обрядів посвяти для молодих воїнів нічних ельфів, який доручає наставниця...",kw={"тінь елури","примара елури","елуніт","обердайн","еланарія","затонулий корабель","воїн"},ang={["class:Warrior"]="Це завдання — визначальний крок у шляху воїна нічних ельфів: воно випробовує витривалість під водою й бойову дисципліну, а нагородою стає кована зброя з елуніту.",["profession:Blacksmithing"]="Підйом затонулого елуніту підкреслює своєрідні ковальські традиції нічних ельфів, які кують могутню зброю з благословенних матеріалів.",["race:NightElf"]="Упокоїти примару Елури — значить ушанувати одноплемінницю-калдорейку, чиє безмежне почуття обов'язку на покоління замкнуло її під хвилями."},sec={{t="Вічна варта капітанки",b="Колись давно корабель, що віз рідкісну елунітову руду, розбився об гострі прибережні скелі біля маяка Обердайна. У розпачі, незламно вірна своєму обов'язку, капітанка корабля Елура наклала прокляття на власну душу. Прикута до уламків під хвилями, її примара досі блукає морським дном і захищає втрачений вантаж від кожного, хто насмілиться його потривожити."},{t="Зброя з елуніту",b="Для воїнів нічних ельфів, що набираються сили, перша справжня кована зброя потребує і бойової вправності, і шани до полеглих родичів. Наставниця Еланарія посилає молодих бійців у холодний прибій Темного Узбережжя не просто по метал, а щоб здолати Примару Елури й забрати її медальйон. Упокоївши Елуру, воїн звільняє прокляту капітанку від її варти й здобуває руду для горна Коваля Матіеля."}},faq={{q="Хто така Примара Елури?",a="Елура була капітаном ельфійського корабля, що розбився на підступних мілинах біля маяка Обердайна. Не зрікшись свого обов'язку, вона прокляла себе: живою чи мертвою повік пильно стерегти затонулий вантаж елунітової руди.",al={"лор примари елури","хто така елура","капітан елура"}},{q="Чому Еланарія посилає воїнів по Елуру?",a="Еланарія хоче і дати спокій змученому духові Елури, і підняти затонулу елунітову руду. Перемога над капітаном і її медальйон доводять звитягу молодого воїна, а заразом дають сировину для доброї зброї.",al={"чому вбиваємо елуру","мета завдання еланарії"}},{q="Де розбився корабель?",a="Уламки корабля лежать під водою біля узбережжя Обердайна на Темному Узбережжі — неподалік маяка, трохи на південь від головних причалів гавані, розкидані по морському дну.",al={"де розбитий корабель","місце корабля елури"}},{q="Для чого використовують елунітову руду?",a="Елуніт — рідкісна руда, яку цінують ковалі нічних ельфів. У цьому випробуванні підняті ящики відносять ковалеві Матіелю в Дарнасус, і той кує з руди особливу зброю для перспективних воїнів.",al={"навіщо елунітова руда","призначення елуніту"}},{q="Чи шкодить Елурі назавжди перемога над її примарою?",a="Перемога над примарою знімає прокляття, яким Елура сама прикувала свій дух до морського дна. Як каже Еланарія, поразка в бою дарує капітанові заслужений спокій після століть холодної примарної варти.",al={"чи елура померла","чи елуру врятовано"}},{q="Хто кує зброю, коли руду зібрано?",a="Отримавши руду й медальйон, Еланарія відсилає воїна до коваля Матіеля на Терасі Воїна в Дарнасусі, і той перетворює метал на виняткову зброю.",al={"хто кує зброю з елуніту","наступне завдання після елури"}}},fp="18,370,25.362.0,18.423.0,26.254.0,44.248.0,27.157.0,29.206.0,48.209.0,48.173.0"}
P.entries["quest:1688"] = {n="Сурена Каледон",s="«Сурена Каледон» — навчальне завдання для чорнокнижників від Ґакіна Зв'язувача Темряви з потаємного підвалу під «Зарізаним Ягням» у Стормвінді. Ґакін доручає чорнокнижнику-початківцю вистежити його колишню ученицю, що зрадила його й утекла до Братства Дефіас, і повернути коштовне намисто з кровавика.",h="«Сурена Каледон» — навчальне завдання для чорнокнижників від Ґакіна Зв'язувача Темряви з потаємного підвалу...",kw={"сурена каледон","ґакін","чорнокнижник","кровавик","дефіас","зарізане ягня","стормвінд"},ang={["class:Warlock"]="Полювання на Сурену Каледон — випробування для чорнокнижника Альянсу, яке доводить: зрада коштує життя, а сентиментам у темних мистецтвах не місце.",["race:Human"]="Дезертирство Сурени показує, якою принадною лишається спокуса Братства Дефіас для невдоволених підданих королівства Стормвінд."},sec={{t="Озлоблений учитель",b="Під таверною «Зарізане Ягня» у Кварталі магів Ґакін Зв'язувач Темряви навчає новачків забороненого мистецтва прикликання скверни. Та й у Ґакіна в минулому були помилки. Перш ніж узяти нових учнів, він навчав молоду жінку на ім'я Сурена Каледон, захоплений і її прихованим магічним хистом, і її вродою. Однак Сурена покинула навчання й прихильність Ґакіна та втекла з міста, щоб приєднатися до Братства Дефіас разом зі своїм коханцем Ерланом Драджмуром."},{t="Украдений кровавик",b="Життя дівчини після втечі Ґакіна мало обходить, але він не бажає розлучатися з коштовним намистом із кровавика, яке подарував їй за часів навчання. Він посилає свого новітнього підмайстра на південний схід, до Гарбузової Ділянки Брекуеллів у Лісі Елвінн — садиби, захопленої бандитами Дефіас, — із чітким наказом зняти коштовність із Сурени будь-якою ціною. Повернений кровавик стане магічним каталізатором для наступного випробування учня: прикликати й зв'язати Блукача порожнечі."}},faq={{q="Хто така Сурена Каледон?",a="Сурена Каледон була ученицею чорнокнижника Ґакіна Зв'язувача Темряви в Стормвінді. Природно обдарована, вона здобула прихильність і дарунки Ґакіна, але покинула ремесло й утекла з бандитом Дефіас на ім'я Ерлан Драджмур.",al={"лор сурени","хто така сурена","сурена каледон передісторія"}},{q="Чому Ґакін хоче повернути її намисто?",a="У намисті — цінний кровавик, який Ґакін подарував Сурені, коли та ще вчилася. Ґакінові не лише гірко через крадіжку й зраду: темний резонанс каменя потрібен йому як реагент для ритуалу, щоб допомогти новому учневі підкорити блукача Порожнечі.",al={"чому повернути намисто","важливість намиста кровавика"}},{q="Де можна знайти Сурену Каледон?",a="Сурена переховується разом зі своїми спільниками з Дефіас на Гарбузовій Ділянці Брекуеллів — покинутому хуторі на південному сході Лісу Елвінн.",al={"місце сурени","де сурена","де гарбузова грядка"}},{q="Що відбувається після повернення намиста?",a="Коли намисто з кровавиком повертається до Ґакіна, випробування завершено й відкривається наступне завдання: увійти в коло закликання в криптах під «Зарізаним Ягням» і підкорити блукача Порожнечі з Викривленого Нижнього Світу.",al={"що далі","наступне завдання після сурени"}},{q="Хто такий Ерлан Драджмур?",a="Ерлан Драджмур — розбійник, пов'язаний з Братством Дефіас. Він звабив Сурену Каледон і вмовив її кинути навчання чорнокнижництва, втекти зі Стормвінда й жити серед бандитів.",al={"лор ерлана","хто такий ерлан драджмур"}},{q="Чи шкодує Ґакін про долю Сурени?",a="Анітрохи. Ґакін відверто заявляє, що її життя для нього більше нічого не важить, і холодно зауважує: шкода марнувати магічний хист, але через зраду її доведеться прибрати.",al={"чи ґакіну шкода","реакція ґакіна на сурену"}}},fp="14,305,15.455.0,21.499.1,22.227.0,36.250.0,34.148.0,41.205.1,24.189.0,47.190.0"}
P.entries["quest:1689"] = {n="Зв'язування",s="«Зв'язування» — останнє випробування на ранньому етапі навчання чорнокнижника Альянсу, мета якого — зв'язати блукача порожнечі в Стормвінді. Під проводом Ґакіна Зв'язувача Темряви майбутній прикликач за допомогою повернутого Намиста Кровавика витягає прислужника з безодні в потаємне підземне коло й силою змушує його скоритися.",h="«Зв'язування» — останнє випробування на ранньому етапі навчання чорнокнижника Альянсу, мета якого — зв'язати...",kw={"зв'язування","блукач порожнечі","чорнокнижник","ґакін","намисто кровавика","стормвінд","квартал магів"},ang={["class:Warlock"]="Цей обряд посвяти дає чорнокнижнику основного захисного прислужника й знаменує перехід від необачного аматора до повелителя сил з інших вимірів.",["faction:Alliance"]="Хоч Альянс відстоює Святе Світло й лад чародійства, прагматичні лідери заплющують очі на темних практиків під Кварталом магів, визнаючи, що в лихі часи без їхніх похмурих мистецтв не обійтися.",["race:Gnome"]="Гноми-чорнокнижники підходять до темного прикликання з науковою цікавістю: під проводом Ґакіна підкорення істот Порожнечі для них — точний метафізичний експеримент.",["race:Human"]="Люди-чорнокнижники мусять зважати на прискіпливу увагу стормвіндського духівництва: вони приборкують небезпечних істот у тіні, ховаючи свою силу від міста нагорі."},sec={{t="Підкорення у криптах",b="Під «Зарізаним Ягням» у стормвіндському Кварталі магів в'ється лабіринт забутих катакомб — далеко від пильних очей Срібної Длані та магістрів Кірін-Тору. Тут Ґакін Зв'язувач Темряви навчає новачків, що опанувати темні мистецтва означає не просто спрямовувати потоки магії, а утверджувати цілковиту владу над потойбічними істотами. Повернувши вкрадене Намисто Кровавика від Сурени Каледон, чорнокнижник має витягти блукача порожнечі просто в коло прикликання під таверною."},{t="Утвердити волю над Порожнечею",b="З блукачем порожнечі не домовляються — його ламають. Скориставшись прихованою силою Намиста Кровавика, прикликач розриває завісу й витягає істоту з тіні у світ смертних. Щоб завершити угоду, чорнокнижник мусить і фізично, і магічно бити створіння, доки його воля не розсиплеться, — так доводять свою владу. Коли блукача здолано, його сутність прив'язується до заклинача, і той здобуває витривалого тіньового захисника, здатного витримувати жорстокі удари в майбутніх битвах."}},faq={{q="Де розташоване коло закликання?",a="Коло закликання — глибоко в підвальних катакомбах під «Зарізаним Ягням» у Кварталі магів Стормвінда. Від Ґакіна Зв'язувача Темряви спускайтеся сходами в підземні ходи, аж поки не дійдете до найнижчої зали з фіолетовою руною, що світиться на кам'яній підлозі.",al={"місце кола закликання","де закликати порожнеходця","де коло"}},{q="Хто такий Ґакін Зв'язувач Темряви?",a="Ґакін Зв'язувач Темряви — наставник чорнокнижників, який потай діє під корчмою «Зарізане Ягня» в Стормвінді. Він таємно навчає здібних людей і гномів закликати, підкоряти й тримати в покорі демонів і створінь Порожнечі так, щоб про це не дізналися ні міська варта, ні церква.",al={"хто такий ґакін","ґакін зв'язувач темряви лор","ґакін"}},{q="Для чого потрібне Намисто Кровавика?",a="Намисто Кровавика — магічний талісман, який колись викрала Сурена Каледон. Насичене зосередженою магічною силою, воно стає каталізатором, що дає змогу чорнокнижникові-початківцеві прорвати завісу й витягти норовливого блукача Порожнечі в призначене коло закликання.",al={"навіщо намисто кровавика","чому мені потрібне намисто","намисто"}},{q="Чому чорнокнижникам доводиться битися з демонами, щоб їх підкорити?",a="Позасвітові істоти, як-от демони й створіння Порожнечі, не служать смертним господарям з власної волі. Чорнокнижник мусить довести свою перевагу й залізну волю, зламавши істоту в бою — силою чи магією, — і лише тоді вона назавжди стане його покірною слугою.",al={"чому битися з порожнеходцем","навіщо підкоряти демонів","підкорення демонів"}},{q="Що відбувається після завершення ритуалу?",a="Коли істоту переможено, а намисто повернуто Ґакінові, чорнокнижник здобуває знання й техніку ритуалу, щоб закликати вірного блукача Порожнечі й керувати ним, — той захищатиме його в мандрах.",al={"яку нагороду я отримаю","закляття порожнеходця","після зв'язування"}},{q="Чому цей ритуал проводять таємно, під корчмою?",a="Демонологія й магія Порожнечі — суворе табу: Церква Святого Світла й маги Альянсу ставляться до них украй вороже. Тож чорнокнижники Стормвінда практикують свої заборонені мистецтва в прихованих підвалах і катакомбах, подалі від влади.",al={"чому сховано під корчмою","чи магія скверни заборонена","підвал забитого ягняти"}}},fp="11,290,25.543.0,28.501.0,38.288.0,28.301.0,39.261.0,56.262.0,41.203.0,56.266.0"}
P.entries["quest:169"] = {n="Розшукується: Ґат'Ілзоґґ",s="Розшукується: Ґат'Ілзоґґ — оголошення Альянсу про нагороду в Горах Редріджу за воєводу, що стоїть за вторгненням Блекрок у Кам'яну Варту. Магістрат Соломон обіцяє щедру винагороду кожному, хто наважиться штурмувати захоплену фортецю й принести відрубану голову командира.",h="Розшукується: Ґат'Ілзоґґ — оголошення Альянсу про нагороду в Горах Редріджу за воєводу, що стоїть за...",kw={"розшукується: ґат'ілзоґґ","ґат'ілзоґґ","фортеця кам'яної варти","магістрат соломон","блекрок","нагорода"},ang={["class:Warrior"]="Прорватися на вершину Фортеці Кам'яної Варти — означає зустрітися із загартованими ветеранами й грубою силою передового командування Темної Орди.",["faction:Alliance"]="Убивши Ґат'Ілзоґґа, ви усуваєте одну з найнагальніших військових загроз східним кордонам королівства й даруєте мешканцям Лейкширу такий потрібний перепочинок.",["race:Human"]="Для стормвіндців Фортеця Кам'яної Варти була здобута нелегкою ціною; різанина невинних, яку Ґат'Ілзоґґ влаштував під час її падіння, робить цю нагороду справою гіркої помсти."},sec={{t="Воєвода Кам'яної Варти",b="Ґат'Ілзоґґ — жорстокий командир, що керує набігами клану Блекрок по всіх Горах Редріджу. Під його проводом орки штурмом узяли Фортецю Кам'яної Варти й перетворили колишній людський бастіон на укріплений плацдарм для нападів на довколишні поселення. З найвищих мурів фортеці він замишляє нові вторгнення в Лейкшир, погрожуючи відрізати Редрідж від решти королівства."},{t="Містечко на межі",b="Королівське військо Стормвінда так і не відрядило підкріплення до прикордонних земель, тож Магістрат Соломон узяв справу у свої руки. Лейкширу просто бракує війська, щоб силою відбити Фортецю Кам'яної Варти. Оголосивши публічну нагороду за Ґат'Ілзоґґа, Соломон прагне обезголовити провід Блекрок і почати перший етап повернення фортеці під владу корони."}},faq={{q="Хто такий Ґат'Ілзоґґ?",a="Ґат'Ілзоґґ — орк-воєвода, що очолює сили клану Блекрок, які захопили Кам'яну Варту. Він керував захопленням фортеці й відповідає за часті кровопролитні набіги на людей-поселенців Лейкшира.",al={"лор ґат'ілзоґґа","хто такий ґат'ілзоґґ","лідер блекрок у редріджі"}},{q="Де можна знайти Ґат'Ілзоґґа?",a="Він засів на самій вершині Фортеці Кам'яної Варти, серед східних скель Гір Редріджу. Його пильно стережуть ватажки й охоронці Блекрок.",al={"місце ґат'ілзоґґа","де ґат'ілзоґґ","місце боса кам'яної варти"}},{q="Чому Магістрат Соломон оголошує винагороду, а не посилає солдатів?",a="Міська варта Лейкшира ледве дає раду, а корона в Стормвінді так і не надіслала військ, щоб допомогти краю. Тож Магістрат Соломон змушений покладатися на найманців і незалежних шукачів пригод, коли йдеться про великі загрози.",al={"чому винагорода","де солдати стормвінда","чи допоможе охорона лейкширу"}},{q="Що відбувається після загибелі Ґат'Ілзоґґа?",a="Для Магістрата Соломона смерть воєводи — перший і вирішальний крок до того, щоб вичистити орків і зрештою повернути Фортецю Кам'яної Варти Королівству Стормвінд, хоча Блекрок у краї ще чимало.",al={"чи кам'яну варту відбили","після ґат'ілзоґґа"}},{q="Чому орки Блекрок захопили Фортецю Кам'яної Варти?",a="Клан Блекрок використовує Фортецю Кам'яної Варти як укріплену передову базу. Розташована високо в горах над Редріджем, вона дає їм контроль над перевалами й зручне місце, звідки можна нападати на людські поселення.",al={"чому блекрок у редріджі","чому кам'яну варту захоплено"}},{q="Хто видає винагороду, коли Ґат'Ілзоґґа вбито?",a="По винагороду треба прийти просто до Магістрата Соломона в ратушу Лейкшира, принісши голову Ґат'Ілзоґґа як незаперечний доказ його поразки.",al={"кому здати ґат'ілзоґґа","здати завдання ґат'ілзоґґ"}}},fp="19,281,25.414.0,26.396.0,19.208.0,31.173.0,72.237.0,41.240.0,50.228.0,47.154.0"}
P.entries["quest:1692"] = {n="Коваль Матіель",s="«Коваль Матіель» — важливе завдання воїнів у Дарнасусі, що знаменує перехід від сировини до кованої зброї. Здобувши священну елунітову руду з уламків корабля біля Обердайна, молодий воїн приносить її майстрові-ковалю Матіелю. Той погоджується перекувати благословенний метал на зброю, гідну захисника калдореїв.",h="«Коваль Матіель» — важливе завдання воїнів у Дарнасусі, що знаменує перехід від сировини до кованої зброї.",kw={"коваль матіель","елуніт","елунітова руда","дарнасус","тераса воїна","еланарія","ковальство"},ang={["class:Warrior"]="Для молодих воїнів-калдореїв принести елуніт Матіелю — обряд посвяти: прості навчальні клинки змінюються на зброю на замовлення, благословенну Богинею Місяця.",["profession:Blacksmithing"]="Шанобливе ставлення Матіеля до елуніту показує, як ковалі-калдореї вплітають священні благословення в ковальське ремесло, а не покладаються лише на жар і молот.",["race:NightElf"]="Обробка елунітової руди поєднує ремесло нічних ельфів зі священною відданістю Елуні й показує, що бойова сила та божественна віра йдуть пліч-о-пліч."},sec={{t="Священна посилка",b="Здобувши елунітову руду з уламків корабля з привидом біля Обердайна й передавши її наставниці воїнів Еланарії, молоді воїни нічних ельфів вирушають через Терасу Воїна в Дарнасусі. Еланарія дбайливо пакує руду в міцну скриньку й велить новачкові знайти Матіеля — одного з найкращих ковалів столиці, щоб той викував зброю, гідну бойового покликання."},{t="Благословення елуніту",b="Для Матіеля робота біля горна — не просто ручна праця, а побожне ремесло. Елуніт — не звичайна руда: на ньому священне благословення Богині Місяця, Елуни. Отримавши скриньку, Матіель охоче береться до справи й вважає за велику честь перетворити такий святий метал на зброю для захисту молодого гілля Тельдрассилу."}},faq={{q="Хто такий коваль Матіель?",a="Матіель — вправний коваль з нічних ельфів, що працює на Терасі Воїна в Дарнасусі. Він кує особливе спорядження й виконує замовлення для захисників Дарнасуса.",al={"хто такий матіель","коваль матіель","де матіель"}},{q="Чим особлива елунітова руда?",a="Елуніт — рідкісний метал, який нічні ельфи шанують, бо його благословила сама Елуна. Для ковалів на кшталт Матіеля працювати з ним — велика честь, а його священні властивості дають змогу кувати могутню зброю.",al={"що таке елуніт","чи елуніт магічний","елуніт лор"}},{q="Хто посилає до Матіеля?",a="Еланарія, знана наставниця воїнів на Терасі Воїна в Дарнасусі, пакує знайдену вами руду й відсилає вас до Матіеля — він по той бік тераси.",al={"хто дає коваля матіеля","хто дає завдання коваль матіель"}},{q="Чи це завдання лише для воїнів?",a="Так. Це завдання — частина ланцюжка завдань для воїнів 10-го рівня, що має забезпечити молодих воїнів першою особливою зброєю.",al={"лише воїни","чи інші класи можуть коваля матіеля"}},{q="Де в Дарнасусі знайти Матіеля?",a="Матіель працює на Терасі Воїна в Дарнасусі — на південь від Еланарії, на протилежному боці споруди.",al={"місце матіеля","знайти матіеля"}},{q="Що відбувається, коли віддати руду Матіелю?",a="Матіель береться кувати елунітову руду й одразу пропонує наступне завдання, де ви обираєте, яка зброя з елуніту найкраще пасує до вашого стилю бою.",al={"що після коваля матіеля","наступне завдання після коваля матіеля"}}},fp="13,330,17.400.0,23.351.0,21.180.0,34.209.0,25.167.0,41.143.0,40.107.0,50.170.0"}
P.entries["quest:1693"] = {n="Зброя з елуніту",s="«Зброя з елуніту» — завершення одного з перших обрядів посвяти для воїнів нічних ельфів у Дарнасусі. Здобувши сиру руду, благословенну Елуною, воїн приносить її вправному ковалеві Матіелю, щоб той викував зброю, гідну захисника Калімдору.",h="«Зброя з елуніту» — завершення одного з перших обрядів посвяти для воїнів нічних ельфів у Дарнасусі.",kw={"зброя з елуніту","елуніт","коваль матіель","дарнасус","воїн","елуна"},ang={["class:Warrior"]="Це завдання — важливий ранній обряд бойового служіння для молодих воїнів-калдореїв: їхню відданість винагороджують надійною зброєю, благословенною Елуною.",["profession:Blacksmithing"]="Ремесло Коваля Матіеля показує тонку рівновагу між звичайною обробкою металу й поводженням із божественними матеріалами на кшталт елуніту.",["race:NightElf"]="Кування елуніту показує, як суспільство нічних ельфів вплітає шанування Богині Місяця просто в практичне ремесло війни й оборони."},sec={{t="Священне горно",b="На воїнах нічних ельфів лежить священний обов'язок захищати Тельдрассил і народ калдореїв. Найздібніших не задовольняють звичайною сталлю — їх посилають по елуніт, мінерал, сповнений благодаті Богині Місяця. Щоб викувати з нього зброю, потрібен майстер, що розуміється і на металі, і на шані, якої заслуговують дари Елуни."},{t="Ремесло Матіеля",b="Коваль Матіель зі столиці Дарнасуса дуже пишається тим, що перетворює благословенну руду на бойову зброю. Для Матіеля робота з елунітом — не буденна металургія, а честь. Отримавши руду, він кує кілька видів зброї під стиль воїна й винагороджує його службу зброєю, благословенною їхньою богинею."}},faq={{q="Яка мета цього завдання?",a="Це завдання завершує ранні випробування воїна в Дарнасусі. Здобувши рідкісну елунітову руду, воїн приносить її ковалеві Матіелю, і той кує надійну зброю, сповнену сутності Елуни, яка допомагатиме в мандрах Калімдором.",al={"зброя з елуніту завдання","навіщо це завдання","воїн десятий рівень дарнас"}},{q="Хто такий Матіель?",a="Матіель — вправний бронник і зброяр з нічних ельфів, що живе в Дарнасусі. Він має особливі знання, щоб перекувати елунітову руду на добре врівноважену зброю для захисників міста, яких дедалі більшає.",al={"коваль матіель","хто такий матіель","коваль дарнаса"}},{q="Що таке елуніт?",a="Елуніт — рідкісний мінерал, священний для нічних ельфів: кажуть, він сповнений сяйва й ласки Місячної Богині Елуни. Через його божественну природу майстри вважають кування зброї з нього урочистою честю.",al={"що таке елунітова руда","елуніт лор"}},{q="Хто може взятися за це завдання?",a="Це завдання — лише для воїнів Альянсу, що навчаються біля Дарнасуса й уже виконали попередні доручення: розшукали й зібрали елуніт для коваля Матіеля.",al={"хто отримує зброю з елуніту","чи це лише для воїнів"}},{q="Де відбувається це завдання?",a="Завдання здають просто ковалеві Матіелю в столиці нічних ельфів Дарнасусі, що лежить високо в гіллі Світового Дерева Тельдрассил.",al={"місце зброї з елуніту","де матіель"}},{q="Чому Матіель дякує шукачеві пригод?",a="Для Матіеля робота з елунітом — і священна честь, і особиста втіха. Кувати руду, пов'язану з Елуною, випадає небагатьом ковалям, тож доставка від воїна — подарунок і для самого майстра.",al={"чому матіель вдячний","діалог матіеля"}}},fp="18,261,14.349.0,15.350.0,34.255.0,15.215.0,16.223.0,29.168.0,33.151.0,38.211.0"}
P.entries["quest:1698"] = {n="Йорус Барліброу",s="«Йорус Барліброу» — виклик для воїнів Альянсу, що скеровує бувалих бійців зі Стормвінда до прикордоння Редріджу. Його передають бойові наставники в столицях Альянсу: честолюбних вояків відсилають до дивакуватого дворфа, який кидає смертельно небезпечний виклик у Корчмі Лейкшира.",h="«Йорус Барліброу» — виклик для воїнів Альянсу, що скеровує бувалих бійців зі Стормвінда до прикордоння...",kw={"йорус барліброу","лейкшир","редрідж","воїн","виклик","корчма лейкшира"},ang={["class:Warrior"]="Це завдання — важливий обряд посвяти для воїнів Альянсу: від вступної муштри вони переходять до небезпечних випробувань на прикордонні Редріджу.",["faction:Alliance"]="Виклик Барліброу приводить вправних новобранців просто до Лейкшира — вразливого поселення, яке саме тепер облягають гноли й орки Блекрок."},sec={{t="Поклик для сильних",b="Наставники воїнів у столицях Альянсу — серед них Келв Стернгаммер, Ву Шен і Дарнат Блейдсінґер — пильно стежать за бійцями, що переросли звичайну муштру. Коли учень доводить свій гарт десь на двадцятому щаблі вишколу, ці майстри передають йому звістку про дворфа на ім'я Йорус Барліброу. Замість звичайного військового наказу Барліброу оголосив відкрите парі й випробування зброєю для кожного воїна Альянсу, якому стане сміливості відгукнутися."},{t="Чекання в Лейкширі",b="Барліброу осів у корчмі Лейкшира — просто на передовій боротьби Редріджу проти гнолів і орків Блекрок, що насуваються. Хто його розшукає, побачить хвалькуватого дворфа з добрячим кухлем у руці, готового зміряти поглядом кожного претендента, що вважає себе справжнім бійцем. Для воїнів, які прагнуть проявити себе за межами безпечних бруківок столиці, його випробування — посвята в суворіші прикордонні битви."}},faq={{q="Хто такий Йорус Барліброу?",a="Йорус Барліброу — дворф зі славетного пивоварського роду Барліброу, який кинув відкритий бойовий виклик воїнам Альянсу. Засівши в Корчмі Лейкшира, він випробовує бійців, що вважають себе готовими до суворого прикордоння Гір Редріджу.",al={"йорус барліброу","хто такий барліброу","дворф у корчмі лейкширу"}},{q="Чому наставники посилають воїнів у Редрідж?",a="Щойно воїн набуде достатньої вправності в Стормвінді, місцеві майстри зброї підштовхують його до справжніх боїв, де ставки високі. Йорус Барліброу пропонує випробування, яке змушує учнів вийти за міські мури й довести свою витривалість проти справжніх небезпек дикого краю.",al={"чому лейкшир","завдання наставника воїнів редрідж","чому йти до йоруса"}},{q="Де знайти Йоруса Барліброу?",a="Він сидить у Корчмі Лейкшира — у містечку Лейкшир у Горах Редріджу, одразу на схід від Лісу Елвінн.",al={"місце йоруса барліброу","де йорус","знайти барліброу"}},{q="Що відбувається після розмови з Йорусом?",a="Розмова з Йорусом розпочинає його бойове випробування: він кидає вам виклик пройти Ретбанське випробування — небезпечну перевірку проти лютих звірів і гнолів, що населяють довколишні пагорби.",al={"після йоруса","випробування барліброу","наступне завдання"}},{q="Хто дає завдання його розшукати?",a="Це завдання дають різні наставники воїнів у столицях Альянсу, зокрема Келв Стернгаммер, Ву Шен і Дарнат Блейдсінґер, — щойно воїн доведе свою базову вправність.",al={"хто дає завдання","початок завдання","наставники для йоруса"}},{q="Чи можуть узяти участь у цьому випробуванні інші класи, крім воїнів?",a="Ні. Виклик розрахований саме на воїнів. Йорус Барліброу пропонує своє випробування лише бійцям, які покладаються суто на фізичну витривалість і зброю.",al={"чи паладини можуть це","чи лише для воїнів","обмеження класів"}}},fp="16,295,20.458.0,20.457.0,24.263.0,46.263.0,34.142.0,39.185.0,33.181.0,50.172.0"}
P.entries["quest:1699"] = {n="Ретбанське випробування",s="Ретбанське випробування — дивакуватий іспит на витривалість, який вигадав дворф-пивовар Йорус Барліброу в Лейкширі. Сміливці мають ковтнути міцного вогняного Скалдеру Барліброу — родинного трунку Йоруса — й добігти на північ до Печер Ретбану, де кишать гноли, а потім повернутися назад, поки не мине година.",h="Ретбанське випробування — дивакуватий іспит на витривалість, який вигадав дворф-пивовар Йорус Барліброу в...",kw={"ретбанське випробування","йорус барліброу","скалдер","печери ретбану","гноли","лейкшир"},ang={["faction:Alliance"]="Поки Лейкшир потерпає від набігів гнолів, сміливці, що беруться за випробування, заразом проріджують ворожі патрулі біля північних печер.",["race:Dwarf"]="Дворфи почуватимуться як удома з галасливим уявленням Йоруса про розваги: міцний родинний трунок упереміш із небезпечними гірськими перегонами."},sec={{t="Дворфійське парі",b="У Лейкширі, де в корчмі зазвичай точаться похмурі розмови про набіги гнолів і зниклих вартових, дворф Йорус Барліброу пропонує розвагу суто дворфійського штибу. Його власне випробування, Ретбанське, перевіряє відвагу, прудкість і печінку шукача пригод — усе водночас. Учасник має випити ковток фірмового родинного трунку, Скалдеру Барліброу, просто перед тим, як вирушити пішки до північних передгір'їв."},{t="Забіг дикими пагорбами",b="Це випробування значно небезпечніше за звичайні п'яні перегони. Між Лейкширом і місцем призначення лежать землі Редріджу, що кишать агресивними гнолами. Щоб пройти випробування, бігун має пробитися крізь зграї чи прослизнути повз них, дістатися першого розгалуження в темних тунелях Печер Ретбану й мерщій повернутися до Йоруса протягом години — і все це борючись із нездоланною хиткою дією вогняного дворфійського трунку."}},faq={{q="Хто влаштовує Ретбанське випробування?",a="Йорус Барліброу, дворф-пивовар, що зупинився в Лейкширі, кидає мандрівникам виклик пробігти цей шлях, щоб довести свою стійкість — і заразом перевірити його напій.",al={"хто дає ретбанське випробування","завдання йоруса барліброу","хто починає випробування"}},{q="Чим це випробування таке складне?",a="Мало того що треба оминути зграї гнолів, які блукають передгір'ями Редріджу, і вкластися в суворий ліміт однієї години, — бігунам спершу доводиться випити Окріп Барліброу, такий міцний напій, що вони геть п'яніють і ледве тримаються на ногах.",al={"чому ретбанське випробування важке","ефект окропу барліброу"}},{q="Де розташовані Печери Ретбану?",a="Печери лежать у північних передгір'ях Гір Редріджу, на північний захід від Лейкшира. Стежка веде на північ повз місцеві хутори до скель, де живуть зграї гнолів.",al={"місце печер ретбану","де ретбан","як дістатися печер ретбану"}},{q="Як далеко в печери треба зайти?",a="Учасникам не треба зачищати всю печеру: досить дійти до першого розгалуження всередині, розвернутися й щодуху бігти назад до Лейкшира.",al={"мета печер ретбану","як далеко в ретбані"}},{q="Хто населяє пагорби й печери вздовж шляху?",a="Довкола шляху й у самих печерах кишать ворожі гноли Редріджу, тож, щоб пережити цей похід, доведеться або скрадатися, або битися швидко.",al={"які вороги в ретбані","що в печерах ретбану"}},{q="Куди веде це випробування далі?",a="Пройшовши випробування, ви доводите Йорусові Барліброу свою витривалість, і перед вами відкриваються нові завдання — наприклад, розшукати в Стормвінді майстра щитів Фурена Лонґбірда.",al={"що після ретбанського випробування","наступне завдання після ретбанського випробування"}}},fp="20,281,14.462.0,22.443.0,32.132.0,49.252.0,38.174.0,40.151.0,51.157.0,36.178.0"}
P.entries["quest:170"] = {n="Нова загроза",s="Нова загроза — раннє бойове доручення, яке дає Балір Фростгаммер у Долині Холодного Хребта. Дворфійських горян застав зненацька раптовий сплеск трогів, що вириваються по всьому Дун Мороґу, загрожуючи місцевим поселенням і таборам.",h="Нова загроза — раннє бойове доручення, яке дає Балір Фростгаммер у Долині Холодного Хребта.",kw={"нова загроза","балір фростгаммер","троги","скелещелепи","долина холодного хребта","анвілмар","табір"},ang={["faction:Alliance"]="Стримати підземну загрозу в Долині Холодного Хребта — означає зберегти навчальні угіддя Айронфорджа придатними й гарантувати, що південна гірська брама лишиться безпечною для новобранців Альянсу.",["race:Dwarf"]="Для молодих дворфів Бронзбірдів, що виходять з Анвілмара, відбити набіги трогів — особистий обов'язок захистити священні землі й тунелі Дун Мороґу."},sec={{t="Прорив у Долину Холодного Хребта",b="Долину Холодного Хребта довго вважали захищеним притулком для молодих дворфійських воїнів і горян, що навчаються в Дун Мороґу. Той спокій розбився, коли підземні кам'янощелепі троги почали в приголомшливій кількості видиратися на поверхню. До Анвілмара швидко дійшли звістки, що троги заполонили замерзле озеро й довколишні передгір'я, зриваючи щоденні патрулі й перерізаючи життєво важливі шляхи постачання через перевал долини."},{t="Захоплений табір",b="Криза сягнула піку, коли тварюки здійснили узгоджений напад на дворфійський табір на заході, змусивши горян відступити й покинути пости. Не маючи людей і не в змозі відірвати повноцінні полки від Айронфорджа, Балір Фростгаммер звернувся до щойно набраних шукачів пригод, щоб ті прорубалися крізь лави Кам'янощелепів і убезпечили пагорби, перш ніж тварюки підступлять просто до порога Анвілмара."}},faq={{q="Хто такий Балір Фростгаммер?",a="Балір Фростгаммер — бувалий дворф-горянин, що стоїть на варті біля Анвілмара в Долині Холодного Хребта. Він організовує оборону від диких звірів і трогів-загарбників, які загрожують місцевим новобранцям.",al={"балір фростгаммер","хто дає нову загрозу","фростгаммер анвілмар"}},{q="Звідки раптом у Долині Холодного Хребта троги?",a="Троги з племені Кам'янощелепів почали прокопуватися нагору з глибоких підземних розломів по всьому Дун Мороґу. Долина Холодного Хребта — одна з перших заселених долин, де стаються раптові жорстокі прориви, коли ці істоти захоплюють табори на поверхні.",al={"звідки троги","чому троги нападають","вторгнення трогів"}},{q="Який табір захопили троги?",a="Табір дворфів-горян у західній частині Долини Холодного Хребта нещодавно потрапив у засідку й був розгромлений трогами; уцілілі мусили відступити до Анвілмара.",al={"захоплений табір","західний табір","де напали троги"}},{q="Які троги загрожують долині?",a="Нападники належать до племені Кам'янощелепів: здебільшого це звичайні троги-каменещелепи та більші й кремезніші троги, що ведуть наступ довкола замерзлого озера й передгір'їв.",al={"скельнощелепі троги","які троги","могутні скельнощелепі троги"}},{q="Чи знає король Маґні про біду з трогами?",a="Місцева варта сподівається, що Король Маґні Бронзбірд і Сенат Айронфорджа готують ширшу відповідь, але прикордонні застави на кшталт Долини Холодного Хребта поки що мусять самотужки стримувати місцеві навали.",al={"чи маґні знає","реакція айронфорджа на трогів","сенат айронфорджа троги"}},{q="Що відбувається, коли проріджено лави трогів?",a="Проріджені лави трогів допомагають убезпечити найближчі околиці Анвілмара, хоча Балір та інші дворфійські офіцери й далі готують контрнаступ, щоб повернути втрачений західний табір і загнати шкідників назад під землю.",al={"наступне завдання","після нової загрози","ланцюжок трогів холодного хребта"}}},fp="12,240,26.426.0,14.404.0,25.209.0,44.222.0,36.179.0,47.196.0,41.203.0,40.220.0"}
P.entries["quest:1700"] = {n="Ґріманд Елмор",s="Створивши особливу броню, дворф-коваль Фурен Лонґбірд надсилає копію своїх відкриттів через квартал Ґріманду Елмору. Це коротке доручення переносить технічні записи між двома норовливими зброярами, що працюють по сусідству в Стормвінді.",h="Створивши особливу броню, дворф-коваль Фурен Лонґбірд надсилає копію своїх відкриттів через квартал Ґріманду...",kw={"ґріманд елмор","фурен лонґбірд","загартована вогнем кольчуга","ковальство","стормвінд","дворфи"},ang={["class:Warrior"]="Ця доставка — місток між власною бронею й пошуком бойової зброї, викуваної завдяки тим самим експериментам зі стихіями.",["profession:Blacksmithing"]="Цей обмін між Фуреном і Ґрімандом показує запеклу професійну суперечку й обмін ремісничими секретами, звичні серед майстрів-металістів.",["race:Dwarf"]="Гаряча, гонориста перепалка між Ґрімандом і Фуреном віддзеркалює глибоко змагальні, але водночас дружні традиції ковальської культури Каз Модану."},sec={{t="Послання через квартал",b="Викувавши особливу Загартовану вогнем кольчугу, Фурен Лонґбірд записує складні прийоми гартування й закони стихій, які відкрив під час роботи. Він не тримає цих знань лише при собі: заносить записи на пергамент і доручає шукачеві пригод доставити їх просто до Ґріманда Елмора — бувалого майстра, що тримає неподалік збройну крамницю."},{t="Професійна гордість і цікавість",b="Отримавши рукопис, Ґріманд Елмор передусім почувається ураженим у своїй гордості. Він уперто стоїть на тому, що сам навчив Фурена всього, що молодший дворф знає, і обурюється від самої думки, що колишній учень може чогось навчити його. Та попри показне обурення, майстер не може втриматися й переглядає текст — і швидко знаходить у записах цікаву ідею, яку йому кортить перевірити самому."}},faq={{q="Хто такий Ґріманд Елмор?",a="Ґріманд Елмор — шанований зброяр, що тримає крамницю в Дворфійському Кварталі Стормвінда. Він відомий неабиякою професійною гордістю й тим, що колись навчав ремесла інших місцевих ковалів, зокрема Фурена Лонґбірда.",al={"ґріманд елмор","хто такий ґріманд","елмор стормвінд"}},{q="Чому Фурен надсилає Ґрімандові записи?",a="Працюючи над загартованою вогнем кольчугою, Фурен відкрив нові прийоми й записав свої методи. Він хотів поділитися відкриттями з Ґрімандом, хоч і знав, що через запальну вдачу й уперте самолюбство Ґріманд сприйме науку від когось іншого в багнети.",al={"чому надсилати записи","записи фурена","фурен до ґріманда"}},{q="Де знайти Ґріманда Елмора?",a="Він працює у збройовій крамниці в Дворфійському Кварталі Стормвінда, за кілька кроків від кузні Фурена Лонґбірда.",al={"де ґріманд","місце ґріманда","крамниця ґріманда елмора"}},{q="Як Ґріманд реагує на записи?",a="Спершу Ґріманд обурюється й заявляє, що сам навчив Фурена всього, що той знає. Проте цікавість майстра-коваля швидко бере гору, щойно він помічає в записах цікавий прийом, який кортить спробувати.",al={"реакція ґріманда","чи ґріманд сердитий"}},{q="Що відбувається, коли Ґріманд прочитає записи?",a="Зацікавившись роботою Фурена з гартуванням металу вогнем, Ґріманд вирішує взятися за власний амбітний задум, і це веде до нових завдань — зібрати рідкісні складники, сповнені стихійного жару.",al={"що далі ґріманд","після завдання ґріманда елмора"}},{q="Чому Фурен радить пригнутися, коли віддаватимете записи?",a="Фурен на власному досвіді знає запальну вдачу й надмірну гордість Ґріманда. Він передбачає, що від самого натяку, ніби учень може навчити майстра чогось нового, Ґріманд влаштує скандал — а то й чимось пожбурить.",al={"чому пригнутися","застереження фурена пригнутися"}}},fp="14,256,29.392.0,32.407.0,22.240.0,37.270.0,34.149.0,36.233.0,43.187.1,56.215.0"}
P.entries["quest:1701"] = {n="Загартована вогнем кольчуга",s="«Загартована вогнем кольчуга» — завдання для воїнів Альянсу, яке дає дворф-бронник Фурен Лонґбірд у Стормвінді. Продовжуючи свою попередню ковальську роботу, Фурен обіцяє зробити надзвичайно міцну кольчугу, якщо воїн добуде рідкісні алхімічні складники й частини звірів, розкидані на обох континентах.",h="«Загартована вогнем кольчуга» — завдання для воїнів Альянсу, яке дає дворф-бронник Фурен Лонґбірд у...",kw={"загартована вогнем кольчуга","фурен лонґбірд","рейзорфен краул","рооґуґ","гори кам'яного кігтя","воїн"},ang={["class:Warrior"]="Ця справа — важливий обряд посвяти для воїнів Альянсу: щоб заслужити майстерну броню, доводиться пройти дикими краями Калімдору й спуститися в глибокі підземелля.",["faction:Alliance"]="Щоб виконати список Фурена, воякові Альянсу доведеться заглибитися в Пустки й Гори Кам'яного Кігтя — землі, за які запекло змагається Орда.",["race:Dwarf"]="Ремесло Фурена віддзеркалює давнє переконання дворфів: справжня броня потребує незламних матеріалів, узятих просто з найлютіших хижаків природи."},sec={{t="Задум майстра-бронника",b="Викувавши для молодого воїна чудовий щит-баклер, Фурен Лонґбірд пропонує ще більший задум: кольчугу, загартовану проти найлютіших ударів. Така дворфійська робота вимагає більшого, ніж просто залізо чи сталь, — потрібні екзотичні матеріали, сповнені жару стихій і природної стійкості. Оскільки коваль не може покинути свою кузню в Стормвінді, весь тягар збирання цих небезпечних реагентів лягає на воїна, якому потрібна броня."},{t="Експедиція через континенти",b="Докладні вказівки Фурена ведуть воїна в далекі дикі краї й підступні глибини. Для рецепта потрібні ікла отруйних павуків, що повзають вогкими розщілинами Багнокраю, а також обпалені й загартовані роги лютих химер, що гніздяться в Горах Кам'яного Кігтя. Щоб поєднати й загартувати ці частини звірів у придатну до носіння кольчугу, потрібен ще й флакон нестійкого флогістону, який доведеться відібрати в Рооґуґа — геоманта, що ховається глибоко в колючих лабіринтах Рейзорфен Краулу в Пустках."}},faq={{q="Хто такий Фурен Лонґбірд?",a="Фурен Лонґбірд — досвідчений дворфійський бронник і майстер щитів з Дворфійського Кварталу Стормвінда. Він виготовляє на замовлення захисне спорядження для перспективних воїнів, готових йому допомогти.",al={"фурен","хто дає загартовану вогнем кольчугу","хто той коваль"}},{q="Навіщо Фуренові такі дивні складники?",a="Звичайна виплавка дає звичайну сталь, але таємні прийоми Фурена потребують органічних матеріалів, загартованих природною отрутою, гірськими вітрами й вогняним подихом, а також нестійкого каталізатора — флогістону, щоб загартувати метал краще, ніж уміють дворфи.",al={"чому павучі ікла","чому роги","що таке флогістон"}},{q="Звідки беруться роги химер?",a="Обвуглені роги й цінний гальванізований ріг дають химери, що живуть у Горах Кам'яного Кігтя на Калімдорі, — особливо молоді звірі та грізна Матріарх Химер, яка їх веде.",al={"де роги химер","місце обпаленого рога","гальванізований ріг"}},{q="Де знайти флогістон?",a="Флакон флогістону має при собі шипогрив-геомант Рооґуґ, що облаштував лігво в Рейзорфен Краулі на південному краю Пусток на Калімдорі.",al={"флогістон флакон","хто дропає флогістон","рогуґ"}},{q="Які павуки мають обпалені павучі ікла?",a="Ікла здобувають з велетенських павуків Багнокраю у Східних Королівствах — п'явкових і печерних скрадачів, що чатують серед боліт і печер краю.",al={"обпалені павучі ікла","де павуки","павуки вологих земель"}},{q="Що відбувається, коли всі матеріали зібрано?",a="Отримавши ікла, роги й флогістон, Фурен одразу береться до кузні, щоб викувати з сировини нагрудник для воїна, — у завданні «Обладунок Фурена».",al={"що далі","наступне завдання кольчуги","нагорода"}}},fp="18,333,27.465.0,30.544.0,23.212.0,48.277.0,38.199.0,30.163.0,42.182.0,50.190.0"}
P.entries["quest:1702"] = {n="Майстер щитів",s="Після тяжкого випробування в Горах Редріджу Йорус Барліброу відсилає воїнів до Дворфійського Кварталу Стормвінда по справжню винагороду. Із барильцем міцного «Окропу Барліброу» вояки шукають майстра-бронника Фурена Лонґбірда, щоб той викував їм міцний щит.",h="Після тяжкого випробування в Горах Редріджу Йорус Барліброу відсилає воїнів до Дворфійського Кварталу...",kw={"майстер щитів","фурен лонґбірд","йорус барліброу","окріп барліброу","дворфійський квартал","щит"},ang={["class:Warrior"]="Ця доставка поєднує суворі випробування Редріджу з майстерністю Стормвінда й доводить ваше право носити щит, викуваний легендарним дворфійським бронником.",["profession:Blacksmithing"]="Зустріч із Фуреном Лонґбірдом знайомить вас із майстром ковадла, чию особливу роботу над захисною бронею шанують по всьому Альянсу.",["race:Dwarf"]="Обміняти барило доброго елю Барліброу на викуване залізо в самому серці Дворфійського Кварталу Стормвінда — більш по-дворфійському вести справи годі й уявити."},sec={{t="Дотримана обіцянка",b="Довівши свій гарт у сутичках із гнолами й небезпеками Ретбанського випробування, воїни чекають від Йоруса Барліброу винагороди. Йорус дотримує слова, та справжню нагороду в Лейкширі не викуєш. Тож він відсилає перспективних бійців назад до Стормвінда, де дворф-бронник готовий сплатити йому особистий борг."},{t="Найкраще від Барліброу",b="Замість пергаментного кредитного листа Йорус дає валюту, куди переконливішу для спраглого майстра з Айронфорджа: важке барило «Окропу Барліброу». Доставлений Фуренові Лонґбірду серед гуркоту й кіптяви Дворфійського Кварталу, цей трунок стає водночас і рекомендацією, і платою — і бувалий коваль охоче віддає своє вміння молодому захисникові."}},faq={{q="Хто такий Фурен Лонґбірд?",a="Фурен Лонґбірд — дворфійський майстер-бронник і майстер щитів з Дворфійського Кварталу Стормвінда. Знаний серед воїнів Альянсу, він кує особливе захисне спорядження й тісно співпрацює з бувалими бійцями, які заслужили його повагу.",al={"фурен лонґбірд","хто такий фурен","хто майстер щитів"}},{q="Чому Йорус посилає до Стормвінда?",a="Йорус Барліброу пообіцяв нагороду за проходження Ретбанського випробування, але сам не має ковальської майстерності, щоб викувати обіцяний бойовий щит. Тож він посилає вас до свого друга Фурена Лонґбірда, який має перед ним неабиякий борг.",al={"чому йти до стормвінда","чому стормвінд","місце нагороди йоруса"}},{q="Що таке Окріп Барліброу?",a="Окріп Барліброу — надзвичайно міцний дворфійський напій від родини Барліброу. Йорус посилає Фуренові Лонґбірду свіже барильце, щоб угамувати ковалеву спрагу й змастити колеса їхньої домовленості.",al={"барильце окропу","окріп барліброу","що таке окріп"}},{q="Де знайти Фурена Лонґбірда?",a="Фурен Лонґбірд порається біля своєї кузні в самому серці Дворфійського Кварталу Стормвінда, серед кіптяви, ковадел і майстерень дворфійських ремісників.",al={"місце фурена","де фурен лонґбірд","знайти фурена"}},{q="Що відбувається, коли віддати Фуренові барильце?",a="Окріп підтверджує, що вас прислав Йорус. Фурен визнає свій борг і одразу береться виготовити захисний обладунок для справжніх боїв — так починається шлях до спорядження, загартованого вогнем.",al={"що далі","наступне завдання фурена"}},{q="Чому це доручення важливе для воїнів Альянсу?",a="Це доручення знайомить воїна Альянсу з одним з найвправніших бронників королівства й відкриває шлях до спорядження на замовлення та подальшої науки оборонного бою.",al={"чому важливе для воїнів","чому воїнам байдуже"}}},fp="15,278,14.343.0,19.358.0,23.245.0,37.239.0,27.213.0,35.169.0,41.212.0,51.193.0"}
P.entries["quest:1703"] = {n="Матіель",s="У цьому завданні шукач пригод везе через моря до Дарнасуса ремісничі нотатки Фурена Лонґбірда. Їх отримує Матіель — коваль-майстер із Тераси Воїна, якому кортить вивчити дворфійські новинки в куванні кольчуг. Це важливий обмін ковальськими знаннями між Айронфорджем і калдореями.",h="У цьому завданні шукач пригод везе через моря до Дарнасуса ремісничі нотатки Фурена Лонґбірда.",kw={"матіель","фурен лонґбірд","нотатки","кольчуга","тераса воїна","дарнасус","ковальство"},ang={["class:Warrior"]="Ці нотатки ведуть вас від вогняних кузень Східних Королівств до випробувальних майданчиків Дарнасуса й поповнюють ваш власний арсенал.",["profession:Blacksmithing"]="Ця доставка показує, як важливо майстрам-ковалям співпрацювати: креслення й прийоми термічного гартування мандрують між далекими ковадлами.",["race:Dwarf"]="Те, що відкриттями Фурена в ковальстві діляться з нічними ельфами, показує, як дворфи пишаються своєю неперевершеною майстерністю біля горна.",["race:NightElf"]="Матіель уособлює готовність калдореїв вивчати підземне ковальство дворфів і поєднувати його з традиційним обладунковим ремеслом нічних ельфів."},sec={{t="Гонець через море",b="Опанувавши складне кування загартованих вогнем обладунків, досвідчений дворф-коваль Фурен Лонґбірд вирішує поділитися своїми відкриттями з іншими ремісниками Альянсу. Замість ревно берегти нові знання, Фурен ретельно перемальовує технічні креслення й посилає перевіреного шукача пригод через континенти до Матіеля — вправного коваля, що живе високо на Тельдрассилі."},{t="Калдорейська сталь і дворфійське ремесло",b="Матіель працює біля свого горна під кронами Тераси Воїна в Дарнасусі й кує для Вартових та бійців, що захищають столицю нічних ельфів. Нотатки Фурена стають мостом між двома різними ремісничими традиціями: суворою підземною плавкою дворфів Каз Модану й витонченим, суголосним природі обладунковим ремеслом калдореїв."}},faq={{q="Хто такий Матіель?",a="Матіель — коваль з нічних ельфів, що працює на Терасі Воїна в Дарнасусі. Він кує спорядження для захисників столиці й підтримує дружнє листування з іншими майстрами-ковалями по всьому Альянсу.",al={"лор матіеля","хто такий матіель дарнас"}},{q="Чому Фурен посилає до Дарнасуса?",a="Фурен Лонґбірд хоче, щоб його дослідження кування загартованих вогнем обладунків прислужилися й іншим ремісникам Альянсу. Матіель — надійний колега, здатний оцінити й застосувати передові металургійні прийоми, тож Фурен доручає вам віднести йому свої записи.",al={"чому надсилати записи матіелю","причина записів фурена"}},{q="Де в Дарнасусі знайти Матіеля?",a="Матіель працює біля кузні на Терасі Воїна — у східній частині Дарнасуса біля головної брами, де тренуються воїни й вартові.",al={"місце матіеля","де матіель"}},{q="Що відбувається, коли віддати Матіелю записи?",a="Вражений відкриттями Фурена, Матіель вирішує розвинути дворфійські прийоми й посилає воїна на нові випробування в дикі краї Калімдору — по незвичні складники на кшталт обпалених сонцем панцирів.",al={"наступне завдання після матіеля","продовження матіеля"}},{q="Що це за записи?",a="У записах — докладні металургійні спостереження й прийоми кування, яких Фурен навчився, експериментуючи з обпаленими павучими іклами, рогами химер і флогістоном, щоб зробити посилену кольчугу.",al={"вміст записів фурена","що в записах фурена"}},{q="Чи це завдання лише для воїнів?",a="Так, це доручення гінця — частина окремого ланцюжка випробувань для воїнів Альянсу, які розвивають бойову майстерність і знання обладунків.",al={"завдання воїна матіель","чи інші класи можуть матіеля"}}},fp="7,320,24.388.0,32.366.0,15.217.0,37.283.0,38.158.0,44.205.1,39.197.0,37.142.0"}
P.entries["quest:1704"] = {n="Клокморт Спаннерспан",s="У цьому завданні шукач пригод несе зі Стормвінда до Айронфорджа ремісничі секрети для Клокморта Спаннерспана в Містечку Майстрів. Опанувавши мистецтво загартованих вогнем обладунків, дворф-коваль Фурен Лонґбірд охоче ділиться своїми ковальськими відкриттями з колегою-гномом. Це важлива ланка в шляху молодого воїна, що хоче випробувати незвичні ремісничі методи.",h="У цьому завданні шукач пригод несе зі Стормвінда до Айронфорджа ремісничі секрети для Клокморта Спаннерспана...",kw={"клокморт спаннерспан","фурен лонґбірд","містечко майстрів","нотатки","ковальство","айронфордж"},ang={["class:Warrior"]="Ваш шлях до міцного бойового спорядження веде від дворфійських горнил просто до гномських винаходів і привертає до вас увагу найкращих майстрів Містечка Майстрів.",["profession:Blacksmithing"]="Нотатки Фурена — приклад спільного обміну найновішими ковальськими прийомами між майстрами Айронфорджа.",["race:Gnome"]="Клокморт уособлює винахідливе схрещення класичної дворфійської металургії та гномських експериментів у Містечку Майстрів."},sec={{t="Колега в Містечку Майстрів",b="Успішно викувавши комплект загартованої вогнем кольчуги, Фурен Лонґбірд збирає докладні нотатки про свої відкриття, щоб передати їх іншому майстрові. Замість ревно берегти нові прийоми, Фурен довіряє вам віднести його нотатки зі Стормвінда до Айронфорджа — у брязкіт і пару Містечка Майстрів, де свою справу провадить гном-коваль Клокморт Спаннерспан."},{t="Гномський захват",b="Гноми-ковалі — порівняно рідкість поряд із їхніми господарями-дворфами, і Клокморт палко прагне розсунути межі традиційної обробки металу. Переглянувши нотатки Фурена, Клокморт приходить у шалений захват від цього прориву й поривається вплести вогняні прийоми у власні незвичайні задуми."}},faq={{q="Хто такий Клокморт Спаннерспан?",a="Клокморт Спаннерспан — гном-коваль, що працює в Містечку Майстрів у підземному місті Айронфордж. Він тісно співпрацює з дворфійськими ковалями, як-от Фурен Лонґбірд, над передовими прийомами обробки металу.",al={"клокморт спаннерспан","хто такий клокморт","гном коваль айронфордж"}},{q="Чому Фурен Лонґбірд посилає до Клокморта?",a="Фурен записав прийоми, які відкрив, коли кував загартовану вогнем кольчугу. Знаючи пристрасть Клокморта до винахідливого ковальства, Фурен посилає вас передати ці відкриття, щоб гном міг з ними поекспериментувати.",al={"чому доставити записи","записи фурена","фурен лонґбірд клокморт"}},{q="Де знайти Клокморта Спаннерспана?",a="Клокморт Спаннерспан — у Містечку Майстрів, гномському кварталі в східній частині Айронфорджа, серед верстатів і механізмів.",al={"місце клокморта","де клокморт","клокморт айронфордж"}},{q="Що відбувається, коли віддати Клокмортові записи?",a="Захоплений відкриттям Фурена, Клокморт одразу береться планувати власні металургійні задуми й посилає вас по незвичні матеріали, як-от залізний корал.",al={"продовження завдання","що після клокморта","завдання залізного коралу"}},{q="Чи це завдання лише для воїнів?",a="Так. Це доручення — частина окремого ланцюжка про виготовлення обладунків, доступного лише воїнам Альянсу, які навчаються в досвідчених майстрів зброї й обладунків.",al={"лише воїни","чи кожен може це завдання","вимога до класу"}},{q="Чому Клокморт каже, що не відрізняє дня від ночі?",a="Айронфордж — цілком підземне місто, видовбане глибоко в самому серці гори в Дун Мороґу. Унизу, в Містечку Майстрів, під кам'яними склепіннями й світлом ламп, ремісники не бачать ні сонця, ні неба.",al={"діалог клокморта день і ніч","діалог тут унизу"}}},fp="21,386,25.371.0,18.314.0,29.214.0,47.245.0,39.153.0,46.175.1,34.156.0,53.189.0"}
P.entries["quest:1705"] = {n="Палаюча кров",s="Майстер-коваль Ґріманд Елмор у Стормвінді доручає шукачеві пригод вирушити в темні ліси Сутінколісся по екзотичні ковальські реагенти. Зацікавлений новаторськими прийомами кування броні, які відкрив Фурен Лонґбірд, Ґріманд хоче сам перевірити цей метод — і для цього йому потрібні палаюча кров і жаркий вогняний камінь, що його тримають у себе дикі воргени.",h="Майстер-коваль Ґріманд Елмор у Стормвінді доручає шукачеві пригод вирушити в темні ліси Сутінколісся по...",kw={"палаюча кров","ґріманд елмор","погибель роланда","кишкодер","воргени","сутінколісся"},ang={["class:Warrior"]="Для воїнів, що мандрують королівством, похід проти проклятих звірів Сутінколісся заради експерименту Ґріманда приносить незвичайно загартовану броню, створену для передової.",["faction:Alliance"]="Здобуваючи реагенти в Погибелі Роланда, ви допомагаєте стримувати загрозу воргенів у Сутінколіссі й водночас забезпечуєте збройні Стормвінда новими дієвими захисними прийомами.",["profession:Blacksmithing"]="Ковалі оцінять професійну гордість між Ґрімандом і його колишнім учнем Фуреном — і побачать, на що готові піти майстри, аби випробувати рідкісну металургію й речовини для гартування."},sec={{t="Неохочий експеримент",b="Ґріманд Елмор, один із найвправніших бронників Альянсу, рідко визнає, що інший майстер може перевершити його методи. Та почувши про незвичайні ковальські відкриття Фурена Лонґбірда, він піддається професійній цікавості, що бере гору над упертою гордістю. Ґріманд погоджується випробувати методи Фурена, викувавши особливий обладунок. Щоб загартувати метал точно як слід, звичайної води чи простого вугілля не досить — йому потрібні дивні, нестійкі складники, які трапляються лише в похмурих закутках півдня."},{t="Жахіття Погибелі Роланда",b="Завдання веде відважних молодих ковалів і воїнів до Сутінколісся — а саме до покинутої копальні Погибель Роланда. Печеру заполонили дикі воргени Найтбейн — вовкоподібні звірі, у чиїх проклятих жилах пульсує неприродна пекуча сукровиця. Ґріманду потрібні флакони цієї палаючої крові, а також рідкісне вогняне камінне осердя, відоме як палаючий камінь, яке тримає в себе лютий ватажок зграї — Кишкодер. Здолавши цих звірів і здобувши їхні пекучі рештки, ви дасте Ґріманду змогу розпалити кузню темною вогняною силою."}},faq={{q="Хто такий Ґріманд Елмор?",a="Ґріманд Елмор — шанований майстер-бронник з Дворфійського Кварталу Стормвінда. Разом з іншими ремісниками він споряджає захисників міста й показує воїнам-початківцям, якою має бути міцність і вага справжніх бойових лат.",al={"ґріманд","ґріманд елмор","збройник стормвінда"}},{q="Навіщо Ґрімандові палаюча кров і палаючий камінь?",a="Ґріманд хоче випробувати незвичний прийом виготовлення обладунків, який розробив Фурен Лонґбірд. Палаюча кров і палаючий камінь мають сильний надприродний жар, потрібний, щоб загартувати й викувати особливі латні пластини.",al={"навіщо палаюча кров","навіщо палаючий камінь","мета завдання"}},{q="Де шукати воргенів Найтбейн, у яких ці матеріали?",a="Матеріали можна здобути в Сутінколіссі — у Погибелі Роланда, покинутій копальні на південному сході Сутінколісся, на південний захід від Даркшира. Тунелі копальні кишать ворожими воргенами Найтбейн, у жилах яких тече пекуча кров.",al={"де воргени","місце загибелі роланда","де палаюча кров"}},{q="У кого палаючий камінь?",a="Палаючий камінь має при собі Кишкодер — могутній ватажок воргенів Найтбейн, що живуть у глибинах Погибелі Роланда.",al={"хто має палаючий камінь","ґатспілл","місце ґатспілла"}},{q="Як пов'язані Ґріманд Елмор і Фурен Лонґбірд?",a="Фурен Лонґбірд — колишній учень Ґріманда Елмора. Зазвичай Ґріманд скептично ставиться до чужих ідей, але останні нововведення Фурена в броньовій справі видалися йому настільки переконливими, що він вирішив випробувати їх сам.",al={"ґріманд і фурен","хто такий фурен лонґбірд"}},{q="Що відбувається, коли повернути кров і камінь?",a="Отримавши вогняні реагенти, Ґріманд одразу береться кувати обладунок, щоб перевірити прийоми Фурена, й обіцяє готову річ шукачеві пригод, який зібрав матеріали.",al={"наступне завдання","нагорода","що робить ґріманд"}}},fp="13,332,22.553.0,28.524.0,22.240.0,55.219.0,62.209.0,27.130.0,68.207.0,48.193.0"}
P.entries["quest:1706"] = {n="Обладунок Ґріманда",s="«Обладунок Ґріманда» — вершина низки завдань вишколу воїна під наглядом Ґріманда Елмора в Дворфійському Кварталі Стормвінда. Переконавшись, що металургійні прийоми Фурена Лонґбірда справді діють, коваль виготовляє грізний обладунок, здатний витримати нищівні удари в бою. Це важливий рубіж на шляху воїна Альянсу до майстерності.",h="«Обладунок Ґріманда» — вершина низки завдань вишколу воїна під наглядом Ґріманда Елмора в Дворфійському...",kw={"обладунок ґріманда","ґріманд елмор","фурен лонґбірд","дворфійський квартал","воїн","кольчужний каптур"},ang={["class:Warrior"]="Це завдання — визначальна мить у кар'єрі воїна Альянсу: нагородою стає знаковий міцний кольчужний каптур, викуваний, щоб витримувати жорстокі удари на передовій.",["faction:Alliance"]="Те, що Ґріманд Елмор покладається на задуми Фурена Лонґбірда, показує, як дворфійські ковалі Дворфійського Кварталу Стормвінда об'єднують свої відкриття, щоб озброїти воїнів Альянсу.",["profession:Blacksmithing"]="Ця історія показує співпрацю двох дворфійських ковалів із Дворфійського Кварталу Стормвінда, які за допомогою незвичайних реагентів надзвичайно загартовують метал."},sec={{t="Відкриття майстра підтверджено",b="Ґріманд Елмор, що працює у своїй кузні в Дворфійському Кварталі Стормвінда, спершу вельми скептично ставився до химерних і зухвалих прийомів, які розробив дворфійський майстер-бронник Фурен Лонґбірд. Щоб випробувати методи Фурена, довелося вирушати в небезпечні походи ворожими землями по рідкісні стихійні складники й частини звірів. Доставивши ці життєво важливі матеріали, воїн дає Ґріманду змогу випробувати теорії дворфа вогнем і перетворити сировину на зміцнений шолом, здатний витримати руйнівні удари."},{t="Кування захисту",b="Готовий виріб доводить, що металургійні здогадки Фурена були цілком слушними. Ґріманду вдається обробити метал так, що той витримує величезний тиск і удари, від яких звичайна сталь покоробилася б. Вручаючи викуваний кольчужний каптур воїнові, що допоміг йому, Ґріманд визнає і майстерність Фурена, і рішучість шукача пригод — і споряджає його тримати передову проти найбільших загроз Азероту."}},faq={{q="Яка мета цього завдання?",a="Це завдання — фінал великого ланцюжка завдань для воїнів. Ґріманд Елмор доробляє особливо оброблений кольчужний каптур з рідкісних матеріалів, які ви здобули, і так підтверджує експериментальні ковальські методи Фурена Лонґбірда.",al={"мета обладунку ґріманда","навіщо обладунок ґріманда","що дає ґріманд"}},{q="Хто такий Ґріманд Елмор?",a="Ґріманд Елмор — вправний дворфійський зброяр з Дворфійського Кварталу Стормвінда. Він працює пліч-о-пліч з колегами в Айронфорджі, допомагаючи молодим воїнам здобути особливі обладунки.",al={"хто такий ґріманд","роль ґріманда елмора","де ґріманд"}},{q="Хто такий Фурен Лонґбірд і чому про нього згадують?",a="Фурен Лонґбірд — дворфійський майстер-бронник з Дворфійського Кварталу Стормвінда, який вигадав експериментальний прийом, що зміцнює обладунок проти величезних навантажень. Ґріманд спершу не вірив Фуренові, аж поки ви не принесли матеріали, потрібні, щоб перевірити метод.",al={"хто такий фурен","техніка фурена","фурен лонґбірд"}},{q="Яке завдання веде безпосередньо до цього?",a="Це завдання йде за «Палаючою кров'ю», де воїн приносить Ґрімандові останній рідкісний реагент — Палаючу Кров воргенів Найтбейн з Погибелі Роланда в Сутінколіссі, — щоб той загартував метал.",al={"передумова обладунку ґріманда","завдання палаюча кров","що перед цим завданням"}},{q="Чи може будь-який клас виконати це завдання?",a="Ні. Цей ланцюжок завдань створено саме для воїнів Альянсу десь тридцятого рівня; він — своєрідний обряд посвяти, що дає міцну кольчугу.",al={"чи обладунок ґріманда лише для воїнів","хто може виконати обладунок ґріманда"}},{q="Де здають це завдання?",a="Завдання здають просто Ґрімандові Елмору біля його ковадла в Дворфійському Кварталі Стормвінда.",al={"де здати обладунок ґріманда","місце ґріманда стормвінд"}}},fp="15,395,28.521.0,17.417.0,34.230.0,22.200.0,47.278.0,40.206.0,34.158.0,35.105.0"}
P.entries["quest:1708"] = {n="Залізний корал",s="«Залізний корал» — завдання Альянсу від гнома-коваля Клокморта Спаннерспана в Містечку Майстрів в Айронфорджі. Прагнучи випробувати щойно передані ковальські методи на обладунку, зробленому на замовлення, Клокморт посилає вас пірнати по рідкісний пекучий корал біля узбережжя Багнокраю. Виконавши його прохання, ви допоможете поєднати гномську винахідливість із дворфійською майстерністю.",h="«Залізний корал» — завдання Альянсу від гнома-коваля Клокморта Спаннерспана в Містечку Майстрів в Айронфорджі.",kw={"залізний корал","пекучий корал","клокморт спаннерспан","багнокрай","гавань менетіл","фурен лонґбірд","ковальство"},ang={["profession:Blacksmithing"]="Ковалі оцінять незвичний спосіб плавлення, який випробовує Клокморт, перетворюючи зібрані океанські нарости на загартовані пластини для власного обладунку.",["profession:Engineering"]="Завдання показує винахідницький підхід: випробовувати незвичні властивості матеріалів, щоб домогтися кращого захисту.",["race:Dwarf"]="Дослід народився просто з ковальських відкриттів айронфорджського майстра Фурена Лонґбірда й показує тісну співпрацю гномів і дворфів у Містечку Майстрів.",["race:Gnome"]="Те, що Клокморт шукає дивні прибережні мінерали замість звичайного видобутого заліза, — типова гномська винахідливість, що завжди прагне вдосконалити традиційне ремесло експериментом."},sec={{t="Злиття ремесел",b="Обмінявшись знаннями з дворфом-майстром Фуреном Лонґбірдом, Клокморт Спаннерспан аж кипить натхненням. Цей дивакуватий гном-коваль хоче поєднати Фуренову металургію з власними винахідницькими ідеями, щоб викувати надзвичайно міцний обладунок. Для такого сміливого досліду звичайної гірської руди не досить — Клокмортові потрібна незвичайна, природно загартована морська речовина, відома як пекучий корал."},{t="Пірнання біля берегів Багнокраю",b="Пекучий корал — нестійкий, твердий океанський наріст, який трапляється лише в одному місці: під водою біля узбережжя на південь від Гавані Менетіл у Багнокраї. Щоб добути двадцять наростів, доведеться брести підступними болотяними водами, ризикувати зустріччю з місцевими водяними хижаками й нести мокру здобич назад до Айронфорджа. Та для Клокморта нагорода варта вологої мандрівки: він має намір виплавити корал і вкувати його просто у свої дослідні пластини."}},faq={{q="Хто такий Клокморт Спаннерспан?",a="Клокморт Спаннерспан — вправний гном-коваль, що живе в Містечку Майстрів у гірському місті Айронфордж. Захоплений механікою й найновішою металургією, він тісно співпрацює з дворфійськими майстрами, вигадуючи нові способи виготовлення обладунків.",al={"клокморт","хто дає залізний корал","хто дає завдання залізний корал"}},{q="Що таке пекучий корал?",a="Пекучий корал — рідкісний морський наріст, який добувають з морського дна на південь від Гавані Менетіл у Багнокраї. Він має унікальні хімічні й фізичні властивості, завдяки яким винахідливий майстер може виплавити його й викувати з нього посилення для важких лат.",al={"лор пекучого коралу","навіщо пекучий корал"}},{q="Де знайти пекучий корал?",a="Коралові зарості ростуть лише під водою вздовж морського берега одразу на південь від Гавані Менетіл у Багнокраї. Доведеться пірнати, щоб відламати багаті на мінерали гілки.",al={"місце пекучого коралу","де залізний корал","місце коралу вологих земель"}},{q="Чому Клокмортові потрібен пекучий корал, а не руда?",a="Клокморт намагається вдосконалити ковальські прийоми, яких навчився в дворфа Фурена Лонґбірда. Замість того щоб покладатися лише на звичні руди Айронфорджа, він сподівається, що незвичні властивості пекучого коралу дадуть легше й значно міцніше покриття після виплавки.",al={"чому корал для обладунку","металургія коралу"}},{q="Як із цим завданням пов'язаний Фурен Лонґбірд?",a="Фурен Лонґбірд раніше з вашою допомогою розробив нові прийоми виготовлення обладунків. Вдячний за поміч, Фурен поділився своїми секретами з Клокмортом, і це надихнуло гнома пристосувати їх до власних захисних винаходів.",al={"зв'язок фурена","фурен лонґбірд залізний корал"}},{q="Що відбувається, коли принести корал Клокмортові?",a="Отримавши двадцять шматків пекучого коралу, Клокморт одразу береться виплавляти й кувати його на своєму верстаті, а це веде просто до показу його експериментального спорядження в завданні «Витвір Клокморта».",al={"продовження залізного коралу","наступне завдання залізного коралу"}}},fp="10,353,18.451.0,25.468.0,29.265.0,22.245.0,34.203.0,59.284.0,45.227.0,51.233.1"}
P.entries["quest:1709"] = {n="Витвір Клокморта",s="«Витвір Клокморта» — успішне кування особливого обладунку в Містечку Майстрів в Айронфорджі. Застосувавши незвичний прийом, який винайшов майстер обладунків Фурен Лонґбірд, гном-коваль Клокморт Спаннерспан перетворює сировину на надзвичайно міцне спорядження.",h="«Витвір Клокморта» — успішне кування особливого обладунку в Містечку Майстрів в Айронфорджі.",kw={"витвір клокморта","клокморт спаннерспан","фурен лонґбірд","латні рукавиці","містечко майстрів","ковальство"},ang={["class:Warrior"]="Замовити ці рукавиці — важлива віха для воїнів Альянсу: це обладунок, загартований на замовлення, щоб витримувати нищівні удари на передовій.",["profession:Blacksmithing"]="Успішне застосування Фуренової формули показує, як важливо експериментувати з незвичними способами гартування й рідкісними океанськими матеріалами.",["race:Gnome"]="Робота Клокморта доводить, що гномська винахідливість важить навіть у важкому обладунковому ремеслі: механічна точність підсилює традиційне дворфійське ковальство."},sec={{t="Злиття наук",b="Важкі обладунки зазвичай кують на великих ковадлах біля Великої Кузні, але Клокморт Спаннерспан працює в Містечку Майстрів. Створення цього обладунку — спільна перемога дворфійської ковальської традиції та гномської механічної винахідливості. Переймаючи суворі методи Фурена Лонґбірда, Клокморт завершує пару латних рукавиць, розрахованих витримати удари, що розчавили б звичайну сталь."},{t="Неперевершена міцність",b="За словами Клокморта, готовий обладунок такий міцний, що по ньому може проїхати облогова машина, не залишивши жодної вм'ятини. Секрет — в особливій обробці рідкісних складників: це доводить, що поєднання давніх дворфійських ковальських прийомів із гномською кмітливістю дає обладунок, здатний витримати найлютіші бої на передовій."}},faq={{q="Хто такий Клокморт Спаннерспан?",a="Клокморт Спаннерспан — вправний гном-коваль, що живе в Містечку Майстрів в Айронфорджі. Він береться за складну механічну роботу й разом з дворфійськими майстрами, як-от Фурен Лонґбірд, створює унікальне й міцне спорядження.",al={"клокморт","хто такий клокморт","гном у містечку майстрів"}},{q="Хто розробив спосіб виготовлення цього обладунку?",a="Спосіб кування вигадав Фурен Лонґбірд, умілий дворфійський бронник. Клокморт точно дотримувався методу Фурена, обробляючи матеріали й доводячи обладунок до ладу.",al={"хто створив процес","обладунок фурена лонґбірда","метод фурена"}},{q="Чому цей обладунок зробив гном-коваль?",a="Клокморт, гномський коваль, хотів випробувати новий прийом Фурена Лонґбірда на власному обладунку. Оскільки ви допомогли Фуренові, гном запропонував вам готовий обладунок в обмін на пекучий корал, який ви для нього зібрали.",al={"чому гном","ковальство гнома","інженерний обладунок"}},{q="Чим цей обладунок кращий за звичайні лати?",a="Клокморт запевняє, що готовий обладунок напрочуд пружний і гнучкий, а водночас твердий і міцний. Він хвалиться, що навіть розплющений гусеницями важкої облогової машини метал одразу ж повернеться до первісної форми.",al={"наскільки він міцний","обладунок облогової машини","міцність обладунку"}},{q="Яке місце цей обладунок посідає в навчанні воїна?",a="Цей витвір — вершина окремого ланцюжка завдань, за який беруться перспективні воїни Альянсу, щоб здобути стійкий обладунок, викуваний на замовлення найкращими умами Айронфорджа.",al={"завдання воїна обладунок","навіщо це завдання","нагорода воїна"}},{q="Де знайти Клокморта?",a="Клокморт Спаннерспан працює серед майстерень, брязкоту шестерень і парових клапанів Містечка Майстрів — гномського кварталу Айронфорджа.",al={"місце клокморта","де спаннерспан"}}},fp="20,309,23.429.0,20.378.0,29.238.0,44.190.0,43.227.0,57.241.0,62.195.0,25.138.0"}
P.entries["quest:1710"] = {n="Обпалені сонцем панцирі",s="У Дарнасусі майстер обладунків Матіель разом із дворфом-ковалем Фуреном Лонґбірдом удосконалює новий спосіб кування кольчуг. Він доручає воїнам вирушити до Тисячі Голок і зібрати міцну шкаралупу яєць віверн на кручах Високосіду.",h="У Дарнасусі майстер обладунків Матіель разом із дворфом-ковалем Фуреном Лонґбірдом удосконалює новий спосіб...",kw={"обпалені сонцем панцирі","матіель","фурен лонґбірд","високосід","тисяча голок","віверни","кольчуга"},ang={["class:Warrior"]="Дослід Матіеля має на меті викувати міцну кольчугу, тож для воїнів Альянсу, що хочуть покращити бойове спорядження, це важливий етап становлення.",["faction:Alliance"]="Ця співпраця показує обмін знаннями між ремісниками нічних ельфів у Дарнасусі та дворфійськими майстрами обладунків у Стормвінді.",["profession:Blacksmithing"]="Завдання показує незвичний ковальський прийом: зі складників, добутих зі звірів, роблять захисний лак для обробки металевих кілець кольчуги."},sec={{t="Ремісничий союз двох народів",b="Матіель працює на Терасі Воїна в Дарнасусі, але його ремесло сягає далеко за межі традиційних прийомів нічних ельфів. Він листується з Фуреном Лонґбірдом — вправним дворфійським майстром обладунків у Стормвінді. Натхненний відкриттями Фурена в металургії та куванні обладунків, Матіель прагне викувати кольчугу, зміцнену природними складниками, що витримають надзвичайне навантаження. Щоб перевірити цю змішану теорію, йому потрібні незвичайні матеріали, яких не знайти ніде поблизу Тельдрассилу."},{t="Небезпеки Високосіду",b="Ключ до Матіелевого досліду лежить далеко на півдні, за морем, в ущелинах Тисячі Голок. Там, високо над солончаками й червоними кам'яними столовими горами, під палючим сонцем Калімдору гніздяться віверни Високосіду. Шкаралупа їхніх яєць твердне від постійної спеки й висоти. Матіель хоче розтерти ці випечені сонцем уламки на порох і зробити з них стійкий лак, щоб покрити ним кільця кольчуги й отримати гнучкий, але надзвичайно міцний обладунок."}},faq={{q="Хто такий Матіель?",a="Матіель — бронник з нічних ельфів, що живе на Терасі Воїна в Дарнасусі. Він охоче переймає дворфійські методи й разом із Фуреном Лонґбірдом розробляє вдосконалені кольчуги для випробуваних воїнів.",al={"матіель","хто дає обпалені сонцем панцирі","матіель дарнас"}},{q="Навіщо Матіелю панцирі виверн?",a="Панцирі виверн з Високосіду запікає й гартує нещадне сонце Тисячі Голок. Матіель подрібнює їх і виготовляє з них особливий лак, яким покриває кільця кольчуги, — так вони стають значно міцнішими.",al={"навіщо панцирі виверн","призначення обпаленого панцира","навіщо панцирі"}},{q="Де розташований Високосід?",a="Високосід — крутий столовий пагорб у західній частині Тисячі Голок, біля кордону з Фераласом. Виверни в'ють гнізда по всіх його скелях і плато.",al={"місце високосіду","де високосід","як знайти високосід"}},{q="Як із цим завданням пов'язаний Фурен Лонґбірд?",a="Фурен Лонґбірд — дворфійський майстер-бронник зі Стормвінда. Матіель вважає Фурена шанованим колегою, і відкриття Фурена в броньовій справі надихають його власну роботу в Дарнасусі.",al={"зв'язок фурена лонґбірда","хто такий фурен"}},{q="Чому ельф у Дарнасусі просить матеріали з Тисячі Голок?",a="Особлива хімічна стійкість, якої потребує Матіель, властива лише яйцям виверн, що лежать під нещадною сухою спекою південних каньйонів і столових гір, — у туманному гіллі Тельдрассила такого не відтвориш.",al={"чому тисяча голок","дарнас до тисячі голок"}},{q="Що відбувається, коли принести панцирі Матіелю?",a="Отримавши двадцять обпалених сонцем панцирів, Матіель одразу береться готувати лак і кувати кольчугу на замовлення — у нагороду за ваші труди.",al={"що далі матіель","після обпалених панцирів","продовження матіеля"}}},fp="18,244,33.501.0,23.484.0,15.204.0,36.215.0,27.148.0,46.195.0,70.202.0,50.169.0"}
P.entries["quest:1711"] = {n="Обладунок Матіеля",s="«Обладунок Матіеля» — завершення ковальської праці, яку Матіель провадив на Терасі Воїна в Дарнасусі. Поєднавши власну ельфійську майстерність із новаторськими дворфійськими методами обробки металу, які винайшов Фурен Лонґбірд, Матіель перековує незвичайні матеріали на захисне бойове спорядження. Це завдання — плідне поєднання традицій союзників на службі воїнам Альянсу.",h="«Обладунок Матіеля» — завершення ковальської праці, яку Матіель провадив на Терасі Воїна в Дарнасусі.",kw={"обладунок матіеля","матіель","фурен лонґбірд","дарнасус","поножі","шкаралупа"},ang={["faction:Alliance"]="Співпраця Матіеля й Фурена показує практичну військову користь Альянсу, що єднає далекі народи спільним ремеслом і взаємним захистом.",["profession:Blacksmithing"]="Ця справа — яскравий приклад ремесла, що об'єднує різні народи: суворе дворфійське гартування може гармонійно поєднуватися з витонченим ковальством нічних ельфів."},sec={{t="Поєднання ремесел",b="Night elven armorers traditionally favor methods honed over millennia, relying on harmony with nature, supple leathers, or delicately worked metals. However, the exchange between the night elves and the Eastern Kingdoms has prompted master smiths like Mathiel to experiment. By incorporating newly devised techniques from the dwarven armorer Furen Longbeard, Mathiel manages to meld dwarven metallurgy with elven artistry."},{t="Незвичайні складники",b="Щоб викувати цей міцний обладунок, знадобилася обпалена сонцем шкаралупа яєць, зібрана в гніздах віверн Високосіду в Тисячі Голок. Перетворивши загартовану сонцем шкаралупу на лак і застосувавши Фуренові формули термічної обробки, Матіель створив міцні поножі, що витримують жорстокі бої на передовій."}},faq={{q="Хто такий Матіель?",a="Матіель — вправний бронник з нічних ельфів, що працює на Терасі Воїна в Дарнасусі. Він тісно співпрацює з іншими майстрами по всьому Альянсу й випробовує нові задуми союзників, як-от Фурена Лонґбірда.",al={"матіель","хто такий матіель","збройник дарнаса"}},{q="Хто такий Фурен Лонґбірд?",a="Фурен Лонґбірд — дворфійський майстер-бронник, що живе в Стормвінді. Відомий новаторськими прийомами гартування й кування особливих латних пластин, він охоче ділиться настановами й кресленнями з ковалями-союзниками по всьому Альянсу.",al={"фурен","фурен лонґбірд"}},{q="З яких матеріалів викувано обладунок?",a="Обладунок кують з обпаленої сонцем шкаралупи, зібраної під гніздами виверн на Високосіді в Тисячі Голок; Матіель зміцнює її й надає їй форми, дотримуючись ковальських методів Фурена Лонґбірда.",al={"матеріали обладунку","з чого обладунок матіеля"}},{q="Чому ельф користується дворфійськими прийомами?",a="Ковалі Альянсу часто діляться знаннями, щоб спорядити своїх бійців проти дедалі грізніших загроз. Ковальство нічних ельфів славиться витонченістю й довговічністю, але дворфійські винаходи дають виняткові способи гартування, тож Матіель охоче їх перейняв.",al={"чому дворфійське ковальство","співпраця нічних ельфів і дворфів"}},{q="Де відбувається це завдання?",a="Завдання починається й завершується біля кузні на Терасі Воїна в Дарнасусі, на острові Тельдрассил.",al={"місце матіеля","де матіель"}},{q="Яке завдання в цьому ланцюжку йде перед цим?",a="Це завдання йде одразу за «Обпаленими сонцем панцирами», де шукач пригод мусить вирушити в далекі куточки Калімдору по міцну яєчну шкаралупу, придатну для ремесла Матіеля.",al={"попереднє завдання","передумова обладунку матіеля"}}},fp="15,404,17.422.0,17.323.0,15.220.0,23.251.0,44.200.0,39.251.0,33.118.0,41.174.0"}
P.entries["quest:1715"] = {n="Зарізане Ягня",s="Це доручення скеровує гномів-чорнокнижників, що лише починають свій шлях, з Айронфорджа до людських земель по вищу науку. Король Маґні Бронзбірд пильно стежить за темними практиками в дворфійській горі, тож наставникам доводиться покладатися на таємні мережі Стормвінда, щоб завершити навчання своїх учнів.",h="Це доручення скеровує гномів-чорнокнижників, що лише починають свій шлях, з Айронфорджа до людських земель по...",kw={"зарізане ягня","ґакін зв'язувач темряви","лаґо блеквренч","квартал магів","стормвінд","чорнокнижник","гноми"},ang={["class:Warlock"]="Ця подорож — важливий обряд посвяти для молодих чорнокнижників Альянсу: вона знайомить їх із таємною підпільною мережею, що єднає практиків різних рас.",["race:Dwarf"]="Влада Айронфорджа не має й краплі терпіння до забав із демонами, тож міські чорнокнижники ховаються глибоко в тіні, а своїх учнів змушені відсилати деінде.",["race:Gnome"]="Завдання показує приниження, якого зазнають гноми у вигнанні: вони тісняться в закутках Айронфорджа й мусять покладатися на людську гостинність, утративши власні академії в Гномреґані."},sec={{t="Вигнання й нагляд",b="До падіння Гномреґану молоді чорнокнижники Каз Модану навчалися в глибинах технічного міста у власних чародіїв-винахідників і знавців демонів. Катастрофа, що вигнала гномів, розпорошила ці школи. Уцілілі практики опинилися в тісних похмурих підземних печерах Айронфорджа, під недовірливим оком Короля Маґні Бронзбірда й дворфійської варти. Не маючи змоги відкрито практикувати демонічні мистецтва чи провадити небезпечні обряди в такій тісноті, старші наставники на кшталт Лаґо Блеквренча змушені відсилати своїх учнів геть."},{t="Таємний льох Кварталу магів",b="Ці учні-вигнанці прямують до «Зарізаного Ягняти» — непоказної корчми в Кварталі магів Стормвінда. Під її шинком, за звивистими кам'яними переходами й сходами, що ведуть донизу, ховається підземне святилище, де в тіні збираються людські чорнокнижники. Під наглядом досвідчених заклиначів на кшталт Ґакіна Зв'язувача Темряви цей осередок дає простір і темне приладдя, потрібні, щоб навчити новачків викликати й підкоряти дрібних демонів, не накликавши одразу гніву міської варти."},{t="Напруга в тіні",b="Ковен Стормвінда радо приймає вправні руки, але наплив новачків-біженців породжує тертя. Людські наставники й так ходять по лезу ножа, щоб їх не викрили міські паладини й влада. Ґакін і його колеги бачать, що їхній таємний прихисток дедалі тісніше заповнюють практики, яких шлють на південь із Каз Модану. Невпинний потік гостей із дворфійської гори загрожує розкрити їхню обачну справу, та жодна зі сторін не має простішої альтернативи."}},faq={{q="Чому гноми-чорнокнижники не можуть навчатися в Айронфорджі?",a="Король Маґні Бронзбірд пильно стежить за такими практиками в Айронфорджі. Гномреґан утрачено, тож чорнокнижники-вигнанці не мають власної потаємної школи, а ризиковані ритуали закликання в серці дворфійської гори надто небезпечні.",al={"чому слати до стормвінда","чорнокнижники айронфорджа навчання","чому гноми-чорнокнижники пішли з гномереґана"}},{q="Де раніше навчалися чорнокнижники Каз Модану?",a="Колись темні практики по всьому Каз Модану навчалися під наглядом майстрів-чорнокнижників у Гномреґані. Навала трогів і радіаційне отруєння знищили ці осередки, і вцілілі мусили перебратися до Айронфорджа.",al={"історія чорнокнижників гномереґана","де раніше навчалися чорнокнижники каз модану"}},{q="Хто такий Ґакін Зв'язувач Темряви?",a="Ґакін Зв'язувач Темряви — старший чорнокнижник-людина, що влаштувався в катакомбах під «Зарізаним Ягням» у Стормвінді. Він навчає учнів підкоряти й закликати демонів, зокрема й гномів-початківців, яких посилають на південь з Айронфорджа.",al={"хто такий ґакін","роль ґакіна"}},{q="Що таке «Зарізане Ягня»?",a="«Зарізане Ягня» — корчма в Кварталі магів Стормвінда. Нагорі це звичайний заклад, але в глибокому льоху під ним ховається таємна спільнота чорнокнижників, що діє подалі від очей міської влади.",al={"таверна зарізане ягня","де зарізане ягня"}},{q="Чому Ґакін незадоволений новачками?",a="Ґакін побоюється, що велика навала гномів-біженців приверне небажану увагу до таємного ковену в Стормвінді. Місця й наставників обмаль, а надто жвава діяльність чорнокнижників загрожує викриттям перед міською владою.",al={"ґакін скаржиться","чому ґакін сердитий"}},{q="Хто такий Лаґо Блеквренч?",a="Лаґо Блеквренч — гном, наставник чорнокнижників, що мешкає в темних закутках Айронфорджа. Гірко переживаючи втрату Гномреґана й дворфійський нагляд, він посилає перспективних новачків до Стормвінда, щоб ті уклали свої перші угоди.",al={"лаґо блеквренч","хто дає зарізане ягня"}}},fp="20,295,18.597.0,32.506.0,29.469.0,44.246.0,46.223.0,28.228.0,29.234.0,43.222.0,24.219.0"}
P.entries["quest:1716"] = {n="Пожирач Душ",s="«Пожирач Душ» — важливий обряд посвяти для чорнокнижників Альянсу, яких зі Стормвінда посилають учитися викликати сукуба. За вказівкою Ґакіна Зв'язувача Темряви новачки мусять перетнути пів світу й дістатися небезпечних диких земель Пусток, щоб попросити поради в Такара Провидця.",h="«Пожирач Душ» — важливий обряд посвяти для чорнокнижників Альянсу, яких зі Стормвінда посилають учитися...",kw={"пожирач душ","сукуб","ґакін зв'язувач темряви","такар провидець","чорнокнижник","альянс"},ang={["class:Warlock"]="Підкорення сукуба знаменує перехід чорнокнижника до опанування магії маніпуляції розумом і спокуси — і вимагає фізичної відваги, щоб здобути екзотичні обрядові складники.",["faction:Alliance"]="Це випробування змушує заклиначів Альянсу заглибитися в спірні землі Орди: на них чекає небезпечна морська подорож і мандри іншим континентом."},sec={{t="Небезпечна подорож на захід",b="Під «Зарізаним Ягням» у Кварталі магів Стормвінда Ґакін Зв'язувач Темряви навчає багатообіцяльних чорнокнижників наступного великого виклику — сукуба. Цю демонічну сутність, яку описують як пожирача душ, руйнівника сердець і володаря розумів, не можна викликати в Азерот наосліп. Потрібна могутня принада — а саме річ, пов'язана з чистим коханням, — щоб виманити його з Викривленого Нижнього Світу, а тоді здолати й підкорити. Щоб роздобути таку річ, потрібна мудрість, якої стормвіндські кола на місці дати не можуть."},{t="Провидець на ворожій землі",b="Щоб відшукати потрібний каталізатор, Ґакін посилає учнів за Велике море, до Калімдору. Глибоко в посушливих просторах Пусток, поблизу поселення Орди Табору Тауражо, живе Такар Провидець. Щоб дістатися до нього, чорнокнижникові Альянсу доведеться пройти дикими землями, де повно ворожих кентаврів, шипогривів і воїнів Орди, — це негласне випробування на виживання ще до того, як заклинач візьметься готувати обряд."}},faq={{q="Яка мета цього завдання?",a="Це завдання посилає чорнокнижників Альянсу зі Стормвінда на Калімдор, щоб вони навчилися закликати й підкоряти сукуба, який коритиметься їм цілковито.",al={"навіщо пожирач душ","мета завдання сукуба","ланцюжок сукуба чорнокнижника"}},{q="Чому треба їхати аж у Пустки?",a="Ґакін Зв'язувач Темряви знає, що для закликання сукуба потрібен емоційний каталізатор — символ чистого кохання, — щоб заманити демона з іншого світу. Такар Провидець, який живе в Пустках, має окультні знання, потрібні, щоб знайти такий артефакт.",al={"чому калімдор","чому йти в пустки","чому посилають так далеко"}},{q="Хто такий Ґакін Зв'язувач Темряви?",a="Ґакін — майстер закликання, що переховується в катакомбах під «Зарізаним Ягням» у Стормвінді. Він навчає чорнокнижників-початківців демонічних угод, підкорення й темних мистецтв подалі від цікавих очей міської варти.",al={"ґакін зв'язувач темряви лор","хто дає пожирача душ"}},{q="Хто такий Такар Провидець?",a="Такар Провидець — містик, що живе в центральних Пустках, неподалік таурентської застави Табір Тауражо. Він допомагає мандрівним чорнокнижникам, підказуючи, де шукати реліквії, якими можна заманити демонів в Азерот.",al={"де такар провидець","такар провидець лор"}},{q="Чому для закликання сукуба потрібен символ кохання?",a="Як пояснює Ґакін, сукуб живиться тим, що розбещує серця й підкоряє розум. Його за самою природою вабить пожирати щиру, чисту прихильність, тож реліквії кохання — єдина дієва принада, щоб витягти його з Викривленого Нижнього Світу.",al={"чому кохання для сукуба","приманка для сукуба","принада для сукуба"}},{q="Чи безпечні Пустки для героя Альянсу?",a="Ні. Пустки — землі Орди, де аж кишить ворожих звірів, племен шипогривів і ордійських поселень на кшталт Табору Тауражо. Мандрівникам з Альянсу варто не впадати в око й оминати вартових, поки вони шукають Такара.",al={"чи небезпечні пустки","чи орда нападе в пустках"}}},fp="17,292,24.541.0,29.431.0,34.141.0,47.259.0,28.213.0,22.215.0,55.223.0,46.216.0"}
P.entries["quest:1717"] = {n="Ґакін кличе",s="Виклик для обдарованих чорнокнижників Альянсу в Айронфорджі: їх кличуть на південь, до Стормвінда. Під Кварталом магів на них чекає Ґакін Зв'язувач Темряви, щоб навчити їх підкоряти могутніших демонів.",h="Виклик для обдарованих чорнокнижників Альянсу в Айронфорджі: їх кличуть на південь, до Стормвінда.",kw={"ґакін","чорнокнижник","сукуб","стормвінд","зарізане ягня","айронфордж"},ang={["class:Warlock"]="Це завдання скеровує чорнокнижників з Айронфорджа до Стормвінда, де починається довгий ланцюжок ритуальних завдань, щоб приборкати сукуба.",["faction:Alliance"]="Тут видно, як таємна мережа чорнокнижників тримає зв'язок між столицями Альянсу, хоч демонологію практикують потай, подалі від очей містян.",["race:Gnome"]="Гномів-чорнокнижників, які навчаються в Лаґо Блеквренча в Айронфорджі, скеровують до підземних ходів Стормвінда — по глибші демонічні знання."},sec={{t="Звістка з підземелля",b="На землях Альянсу демонологію й досі практикують лише в тіні. В Айронфорджі Лаґо Блеквренч нишком наглядає за мандрівними чорнокнижниками від імені стормвіндського братства. Щойно чорнокнижник доводить, що опанував перших слуг, звістка розлітається швидко. І Лаґо передає наказ: облишити всі справи, що тримають у засніжених горах Каз Модану, і без зволікань вирушати на південь."},{t="Назад до Зарізаного Ягняти",b="Глибоко під бруківкою стормвіндського Кварталу магів, під таверною «Зарізане Ягня», Ґакін Зв'язувач Темряви керує вишколом міських чорнокнижників. Кожного здібного учня Ґакін вважає цінним, але небезпечним вкладенням. Його виклик — це поріг справжнього підкорення демонів: попереду випробування, без яких не скорити сукуба з Викривленого Нижнього Світу."}},faq={{q="Хто надсилає цей поклик?",a="Лаґо Блеквренч, наставник чорнокнижників з Айронфорджа, передає поклик від імені Ґакіна Зв'язувача Темряви, який навчає демонології в Стормвінді.",al={"хто дає завдання","хто це починає","лаґо блеквренч"}},{q="Де знайти Ґакіна Зв'язувача Темряви?",a="Ґакін ховається в темних звивистих катакомбах під «Зарізаним Ягням» — корчмою, що загубилася в Кварталі магів Стормвінда.",al={"місце ґакіна","де ґакін","місце зарізаного ягняти"}},{q="Навіщо Ґакін мене кличе?",a="Ви досить просунулися у своєму ремеслі, щоб узятися за ритуали закликання й підкорення сукуба й поповнити свій демонічний арсенал.",al={"мета завдання","для чого це","чому кличуть"}},{q="Що буде після розмови з Ґакіном?",a="Ґакін дасть вам завдання «Пожирач Душ» і відправить у небезпечні краї по складники ритуалу, потрібні, щоб закликати й підкорити сукуба.",al={"наступний крок","що буде після цього","ланцюжок завдань"}},{q="Чому чорнокнижник з Айронфорджа виконує накази зі Стормвінда?",a="Чорнокнижники Альянсу з потреби діють як потаємна мережа. Практики з Айронфорджа й Стормвінда тримають зв'язок і спрямовують перспективних учнів до Ґакіна, який має під «Зарізаним Ягням» особливе ритуальне знаряддя й знання.",al={"чорнокнижники айронфорджа","гноми-чорнокнижники стормвінд","організація чорнокнижників"}},{q="Чи можна знехтувати цим покликом, якщо хочеш лишитися в Каз Модані?",a="Поїздку до Стормвінда можна відкласти, але без випробування Ґакіна закликати сукуба ви не навчитеся, тож для кожного чорнокнижника, що прагне зрости, ця подорож неминуча.",al={"чи це обов'язково","чи можна пропустити","чи треба йти до стормвінда"}}},fp="15,220,30.427.0,30.399.0,26.160.0,37.136.0,26.144.0,36.165.0,59.260.0,58.166.0"}
P.entries["quest:1718"] = {n="Остров'янин",s="«Остров'янин» — запрошення, яке досвідчені наставники воїнів по всьому Азероту дають тим, хто вже довів свою гартованість у бою. Воно скеровує молодих бійців на Острів Бійки біля Узбережжя Крамарів, де замкнене братство воїнів випробовує рівних собі в чистому бойовому двобої. Зустріч із головним воїном Кланноком Маклаудом — переломний крок до опанування вищої бойової майстерності.",h="«Остров'янин» — запрошення, яке досвідчені наставники воїнів по всьому Азероту дають тим, хто вже довів свою...",kw={"остров'янин","острів бійки","кланнок маклауд","воїн","купецьке узбережжя","раджет","стійки"},ang={["class:Warrior"]="Цей обряд посвяти — лише для воїнів: він знаменує важливий перехід від вивчення простих прийомів до опанування всієї люті й тактичної гнучкості стійок досвідченого бійця.",["faction:Alliance"]="Воїнам Альянсу доводиться перепливати море чи пробиратися нетрями Калімдору, щоб дістатися Острова Бійки, — так вони доводять відданість бойовому шляху на суворому прикордонні, далеко від твердинь людей і дворфів.",["faction:Horde"]="Вирушаючи з Тандер Блафа чи Оргріммара, воїни Орди спускаються до Пусток, щоб довести свою силу подалі від пильних очей своїх вождів."},sec={{t="Збір клинків",b="Наставники воїнів у столицях і Альянсу, і Орди розпізнають, коли учень переріс прості вправи. Бойове зростання вимагає не формальних звань чи політичної вірності, а змоги помірятися силою зі справді рівними. Ця подорож веде воїнів геть від цивілізованих тренувальних дворів — до суворого острова, відрізаного від світу у Великому Морі."},{t="Острів Бійки й Узбережжя Крамарів",b="Острів Бійки лежить на схід від Узбережжя Крамарів, трохи на південь від гоблінського порту Раджет у Пустках. Дістатися до нього можна вплав, над затопленими піщаними мілинами. На цій скелі політичні зв'язки розчиняються в бойовому братерстві: бійці збираються під поглядом Кланнока Маклауда, головного воїна острова, й чекають на будь-яке жорстоке випробування, яке він визнає за потрібне."}},faq={{q="Що таке Острів Бійки?",a="Острів Бійки — скеляста латка суходолу біля Узбережжя Крамарів Пусток, на південь від Раджета. Це відлюдне місце випробувань, де воїни з усього Азерота збираються відточувати майстерність, битися на спарингах і проходити виснажливі бойові випробування подалі від будь-якої влади.",al={"де острів бійки","острів бійки лор","острів бійки"}},{q="Хто такий Кланнок Маклауд?",a="Кланнок Маклауд — головний воїн Острова Бійки. Він оцінює претендентів, які дісталися острова, і вирішує, чи гідні їхній дух і вміння того, щоб вести їх далі шляхом воїна.",al={"хто такий кланнок","роль кланнока маклауда","воїн маклауд"}},{q="Чому наставники і з Орди, і з Альянсу посилають сюди воїнів?",a="Справжня бойова майстерність не знає меж фракцій. Майстри-наставники в Оргріммарі, Стормвінді, Тандер Блафі й Айронфорджі розуміють, що сиру бойову вправність треба перевірити в нестримному бою, а Острів Бійки — мовчазно визнане місце випробувань для кожного воїна, здатного пережити його виклики.",al={"чому обидві фракції сюди","чи острів бійки нейтральний","орда й альянс острів бійки"}},{q="Як дістатися Острова Бійки з суходолу?",a="Вирушайте на південь уздовж Узбережжя Крамарів від портового містечка Раджет у Пустках. Від берега пройдіть мілинами й піщаною косою, а тоді пливіть на схід відкритою водою до острова.",al={"як дістатися острова бійки","шлях до острова бійки","як знайти острів бійки"}},{q="Що відбувається після зустрічі з Кланноком Маклаудом?",a="Переконавшись, що ви здолали шлях, і оцінивши вашу рішучість, Кланнок запрошує вас узяти участь у Бійці — випробуванні, що перевіряє вашу бойову витривалість проти хвиль суперників.",al={"що після остров'янина","наступне завдання кланнока маклауда"}}},fp="12,393,21.364.0,34.375.0,20.263.0,23.232.0,64.296.0,47.188.0,43.199.1"}
P.entries["quest:1719"] = {n="Бійка",s="«Бійка» — жорстоке бойове випробування на Острові Бійки біля узбережжя Пусток. Його проводить Кланнок Маклауд: на арені честолюбні воїни б'ються з хвилями острівних суперників і їхнім чемпіоном, щоб довести, що мають досить гарту для поглибленого вишколу.",h="«Бійка» — жорстоке бойове випробування на Острові Бійки біля узбережжя Пусток.",kw={"бійка","острів бійки","кланнок маклауд","здоровань вілл","арена","воїн"},ang={["class:Warrior"]="Бійка — визначальний обряд посвяти для досвідчених воїнів: у цьому горнилі вони доводять свою майстерність у бойових стійках і витривалість, щоб відкрити глибше опанування свого ремесла."},sec={{t="Полігон посеред Великого моря",b="Острів Бійки стоїть осторонь чвар суходолу — це притулок для витривалих забіяк, вигнанців і бойових наставників. Кланнок Маклауд не вчить кожного мандрівника, що зійде з човна. Щоб стати його учнем, молоді воїни мусять узяти участь у Бійці — відкритому випробуванні бойової витривалості й пильності, покликаному відділити справжніх бійців від хвальків."},{t="Коло заліза й крові",b="Правила Бійки прості й безжальні. Ступивши на залізну решітку посеред глядачів, воїн дає знак розпорядникові Твіґґі Флетгеду починати змагання. Суперники виходять на арену один за одним, випробовуючи витривалість новачка. Хто витримає попередні сутички, той зустрінеться з острівним чемпіоном-важковаговиком Здорованем Віллом — і лише перемога над ним дає змогу здобути повагу Кланнока."}},faq={{q="Що таке Бійка?",a="Бійка — випробування на зразок арени, що відбувається на Острові Бійки. Воно перевіряє, чи має воїн-початківець досить витривалості й уміння для поглибленого бойового вишколу в Кланнока Маклауда.",al={"випробування бійка","що таке бійка","арена острова бійки"}},{q="Де відбувається Бійка?",a="На Острові Бійки — суворому острові біля східного узбережжя Пусток у Великому Морі.",al={"де бійка","місце бійки"}},{q="Хто влаштовує випробування?",a="Наставник воїнів Кланнок Маклауд наглядає за бійцями острова й визначає умови випробування, а Твіґґі Флетгед керує поєдинками з краю ями.",al={"хто влаштовує бійку","організатор бійки"}},{q="Як відбувається бій на арені?",a="Воїн стає на центральні залізні ґрати, показуючи, що готовий. Тоді Твіґґі Флетгед випускає в яму хвилі претендентів Бійки, а наостанок — кремезного чемпіона острова, Здорованя Вілла.",al={"як працює бій","хвилі бійки","початок бійки"}},{q="Хто такий Здоровань Вілл?",a="Здоровань Вілл — чинний чемпіон серед бійців Острова Бійки. Перемога над ним на арені — остання умова, щоб пройти Бійку.",al={"здоровань вілл","хто такий здоровань вілл","чемпіон острова бійки"}},{q="Чому воїни мусять пройти це випробування?",a="Кланнок Маклауд відмовляється вчити своїх бойових прийомів кожного, хто не довів своєї витривалості кров'ю й боєм проти кількох супротивників.",al={"навіщо проходити бійку","мета бійки"}}},fp="10,285,33.402.0,28.428.0,19.184.0,33.108.0,24.152.0,37.197.0,16.131.0,38.148.0"}
P.entries["quest:173"] = {n="Воргени в лісі",s="Калор, розчарований колишній вартовий, що мешкає в Даркширі, доручає шукачам пригод винищити зловісних Ткачів Тіней Найтбейн, що нишпорять Сутінколіссям. Полюючи в Гаю Брайтвуд і Гнилому Саду, чужинці можуть довести свою силу мисливцям на чудовиськ Майстра Джонатана Каревіна.",h="Калор, розчарований колишній вартовий, що мешкає в Даркширі, доручає шукачам пригод винищити зловісних Ткачів...",kw={"воргени в лісі","калор","нічна згуба","гай брайтвуд","гнилий сад","джонатан каревін"},ang={["class:Hunter"]="Полювання на Найтбейн до краю випробовує вміння вистежувати й знання звірів: воргени — не звичайна дичина й не прості людські розбійники, а двоногі жахіття, що чаклують тінями.",["faction:Alliance"]="Даркшир почувається цілком покинутим вищою владою Стормвінда, тож містяни й самочинні захисники на кшталт Калора вербують кожного мандрівного шукача пригод з Альянсу, здатного стримати чудовиськ.",["race:Human"]="Для людей з Елвінна чи Вестфолу трагічні руїни ферм Сутінколісся, як-от Гнилого Саду, — похмуре застереження: ось що неприборкана темна магія може зробити з житницями королівства."},sec={{t="Власна варта",b="Нічна Варта невпинно бореться з нежиттю, павуками й розбійниками, що тиснуть на кордони Даркшира. Та для декого, як-от Калора, офіційна варта виявилася надто повільною й самовдоволеною, щоб очистити землю. Покинувши Варту, Калор пов'язав свою долю з Майстром Джонатаном Каревіном і присвятив свій клинок цілковитому викоріненню єресі й скверни. Але Каревін приймає до свого кола не будь-кого: хто хоче допомогти їхній справі, мусить спершу довести, що здатен вистояти проти найлютіших жахіть лісу."},{t="Причаєні з Найтбейн",b="Місцем випробування стають Гай Брайтвуд і зотлілий Гнилий Сад, де панують дикі вовкоподібні звірі — воргени. Серед них Ткачі Тіней Найтбейн вдаються до темної магії, щоб засліпити й обплутати жертв, перш ніж розірвати їх. Калор посилає мисливців-початківців порубати цих звірів-чаклунів — і щоб перевірити рішучість чужинця, і щоб послабити загрозу, походження якої глибоко тривожить захисників Даркшира."},{t="Чудовиська нізвідки",b="Люди-вовки стали невідступним кошмаром Сутінколісся, але їхня поява не має пояснення. Калор зауважує, що воргени ніби взялися з повітря: у цьому краї в них немає жодного природного родоводу. На відміну від ненажерливих диких вовків чи ходячих трупів, що повстали з місцевих курганів, ці двоногі хижаки володіють дивним і чужим чаклунством. Перемога над Ткачами Тіней доводить бойову майстерність, але це лише верхівка протиприродної навали, що пускає коріння по всьому лісу."}},faq={{q="Хто такий Калор?",a="Калор — мисливець і колишній член Нічної Варти Даркшира. Утомившись від обережної бюрократії міського ополчення, він приєднався до майстра Джонатана Каревіна, щоб самому полювати на мерзенних тварюк, які загрожують Сутінколіссю.",al={"калор","калор даркшир","хто дає воргенів у лісі"}},{q="Чому Калор хоче, щоб убили тінеткачів Найтбейн?",a="Для Калора тінеткачі Найтбейн — перевірка вміння й відваги. Кожен, хто хоче допомогти справі майстра Каревіна, мусить довести, що здатен полювати на небезпечних воргенів-чаклунів, а не лише балакати про захист міста.",al={"чому вбивати тінеткачів","мета воргенів у лісі"}},{q="Де водяться тінеткачі Найтбейн?",a="Вони блукають двома місцями на захід і південний захід від Даркшира: серед покручених дерев Гаю Брайтвуд і на покинутих, зарослих землях Гнилого Саду.",al={"де тінеткачі найтбейн","місце тінеткачів"}},{q="Звідки взялися воргени в Сутінколіссі?",a="Їхня раптова поява — загадка для мешканців Сутінколісся. Як зауважує Калор, ці звірі ніби виникли нізвідки й принесли темну магію тіней і ненажерливу лють у ліс, що й без того був на межі загибелі.",al={"звідки воргени в сутінколіссі","чому воргени в сутінколіссі","звідки беруться воргени"}},{q="Хто такий майстер Каревін?",a="Майстер Джонатан Каревін — незалежний мисливець на чудовиськ з Даркшира. Він і його послідовники діють поза Нічною Вартою й рішуче винищують зло, нежить і химерних потвор по всьому краю.",al={"каревін","майстер каревін","хто такий майстер каревін"}},{q="Чому Калор покинув Нічну Варту?",a="Калор розчарувався в тому, що вважав пасивністю й самовдоволенням Нічної Варти. Замість стояти біля огорожі, поки темрява підступає, він обрав рішучий підхід Каревіна — полювати на зло самому.",al={"чому калор покинув варту","калор нічна варта"}}},fp="19,294,15.526.0,21.451.0,21.485.1,13.230.0,52.237.0,45.160.0,43.222.0,22.228.0,36.213.0"}
P.entries["quest:1738"] = {n="Серцедерево",s="«Серцедерево» — завдання для чорнокнижників Альянсу, що веде їх глибоко в Ашенваль по гілку прадавнього дерева з трагічною історією. Самітник Такар Провидець посилає їх від імені Ґакіна Зв'язувача Темряви: цю романтичну реліквію чорнокнижники шукають як могутню принаду, щоб виманити й підкорити сукуба у Стормвінді.",h="«Серцедерево» — завдання для чорнокнижників Альянсу, що веде їх глибоко в Ашенваль по гілку прадавнього...",kw={"серцедерево","сукуб","анатера","латеріон","руїни ордил'аран","чорнокнижник"},ang={["class:Warlock"]="Здобути шматок Серцедерева — важлива віха для молодих чорнокнижників: це дає змогу викликати й поневолити сукуба, щоб маніпулювати розумом ворогів на полі бою.",["faction:Alliance"]="Подорож до Калімдору знайомить молодих заклиначів Альянсу зі спірною дикою місцевістю, ворожими заставами Орди й прадавніми руїнами нічних ельфів.",["race:Human"]="Приховані чорнокнижники Стормвінда часто покладаються на далеких розвідників на кшталт Такара Провидця, щоб розшукати реліквії давнього Калімдору, яких людські маги ніколи не описували."},sec={{t="Пам'ятник трагічному коханню",b="За словами Такара Провидця, Серцедерево виросло на тому місці, де десять тисяч років тому, під час Війни Прадавніх, разом полягли двоє закоханих нічних ельфів — Анатера й Латеріон. Живлене їхніми останніми подихами й вічною відданістю, дерево виросло чистим символом безсмертного кохання. Для смертних це священний трагічний пам'ятник, але для знавців темних мистецтв зосереджена сила почуттів — могутнє магічне паливо."},{t="Принада для сукуба",b="Сукуби живляться смертними пристрастями, жаданням і душевними муками. Такар розуміє: звичайні спокуси — ніщо порівняно з артефактом, що тисячоліттями вбирав чисту, безсмертну відданість. Шматок Серцедерева дає Ґакінові Зв'язувачу Темряви саме той каталізатор, який потрібен, щоб виманити одного з цих хитрих демонів крізь Нижній Світ до кола виклику в Кварталі магів Стормвінда."},{t="Руїни Ордил'Аран",b="Дерево стоїть серед Руїн Ордил'Аран на північному заході Ашенвалю. Проте, щоб здобути гілку, доведеться кинути виклик не лише диким звірам і ворожим землям, а й сектантам Темного Пасма, які захопили ельфійські руїни. Здобуту деревину треба переправити через моря назад до «Зарізаного Ягняти» у Стормвінді, щоб розпочати обряд підкорення."}},faq={{q="Навіщо чорнокнижникам Серцедерево, щоб закликати сукуба?",a="Сукубів вабить пристрасть, жага й сильні почуттєві зв'язки. Серцедерево проросло там, де десять тисяч років тому разом загинули двоє відданих одне одному закоханих нічних ельфів. Їхня незгасна пристрасть просякла деревину, і та стала ідеальною духовною принадою, щоб витягти сукуба крізь Нижній Світ.",al={"навіщо серцедерево","приманка для сукуба","навіщо дерево для сукуба"}},{q="Де росте Серцедерево?",a="Воно росте в Руїнах Орділ'Арана, у північно-західних лісах Ашенвалю, неподалік на південь від Темного Узбережжя. Ця місцевість потрапила до рук зловісних культистів.",al={"місце серцедерева","де серцедерево","де знайти серцедерево"}},{q="Ким були Анатера й Латеріон?",a="Це двоє нічних ельфів, що билися пліч-о-пліч під час Війни Прадавніх. Коли вони разом полягли на полі бою, саме там, де вони востаннє зітхнули, виросло Серцедерево — пам'ятник їхньому незламному коханню.",al={"анатера і латеріон","хто були закохані","закохані ашенвалю"}},{q="Хто такий Такар Провидець?",a="Такар — обдарований провидець-людина, союзник чорнокнижників Стормвінда. Він живе відлюдником у південних Пустках біля Табору Тауражо й своїм містичним зором пронизує тумани часу, відшукуючи забуті реліквії для Ґакіна Зв'язувача Темряви.",al={"хто такий такар","такар провидець","відлюдник пусток"}},{q="Як чорнокнижникові Альянсу безпечно дістатися з Пусток до Ашенвалю?",a="Мандрівникам з Альянсу, що йдуть з Пусток, варто оминати добре охоронювану заставу Орди на Валу Мор'шан. Чорнокнижники часто прослизають крізь неохоронюваний пролом у частоколі трохи на схід від головної брами, ідуть верхнім шляхом через Гори Кам'яного Кігтя або перепливають прикордонну річку.",al={"як дістатися ашенвалю","обійти моршан","уникнути валу орди"}},{q="Що відбувається, коли Ґакін отримує Серцедерево?",a="Ґакін готує з деревини ритуал у катакомбах під «Зарізаним Ягням» у Стормвінді. Він креслить коло закликання, щоб витягти сукуба з Викривленого Нижнього Світу, і доручає чорнокнижникові перемогти й підкорити демона.",al={"що далі після серцедерева","що ґакін робить із серцедеревом"}}},fp="10,301,25.441.0,20.398.0,23.359.1,53.288.0,36.177.0,32.249.0,22.254.0,73.271.0,49.228.0"}
P.entries["quest:1739"] = {n="Зв'язування",s="«Зв'язування» — завершальний обряд посвяти для чорнокнижників Альянсу, що прагнуть підкорити сукуба в Стормвінді. Із зачарованим осердям, здобутим із Серцедерева, адепт входить до кола прикликання під «Зарізаним Ягням», щоб витягти демона й здолати його в бою. Коли демона переможено, його волю сковують, прирікаючи його служити прикликачу.",h="«Зв'язування» — завершальний обряд посвяти для чорнокнижників Альянсу, що прагнуть підкорити сукуба в...",kw={"зв'язування","сукуб","чорнокнижник","осердя серцедерева","ґакін","зарізане ягня","склеп"},ang={["class:Warlock"]="Цей обряд — ключова віха для чорнокнижників із людей і гномів: вони переходять від безмозких бісів і блукачів порожнечі до влади над розумними, розважливими демонами.",["faction:Alliance"]="Саме існування цього ритуалу глибоко під Стормвіндом показує, як Альянс тихо терпить магію тіні в потаємних закутках, попри доктрини Церкви."},sec={{t="Спуск до Склепу",b="Під мостинами «Зарізаного Ягняти» в стормвіндському Кварталі магів лежить просторий склеп, присвячений забороненим мистецтвам. Подалі від пильних очей міської варти й Собору Світла таємна громада міських чорнокнижників проводить тут свої найнебезпечніші ритуали. Кола прикликання, викарбувані в камені, спрямовують первісні сили Нижнього Світу й дають честолюбним посвяченим змогу прорвати завісу між світами."},{t="Приборкання спокусниці",b="Прикликати сукубу — це значно більше, ніж бурмотіти заклинання. Чорнокнижник має принести фокус — у цьому разі підготовлене Осердя Серцедерева — і здійснити біля кола обряд прориву. Сукуби вміють розбещувати, спокушати й підкорювати навіть найстійкіший розум. Щоб утвердити цілковиту владу, прикликач мусить зітнути тварюку в двобої, відіславши її тілесну оболонку назад у Викривлений Нижній Світ й водночас закріпивши справжню прив'язь."},{t="Таємниці Ґакіна",b="Убивши прикликане створіння, переможний посвячений повертає виснажене осердя Ґакіну Зв'язувачу Темряви. Довівши і силу духу, і бойову вправність, підмайстер отримує основні знання, потрібні, щоб кликати сукуба через порожнечу, коли завгодно. Цей ритуал знаменує змужніння чорнокнижника Альянсу — відтепер він адепт, здатний давати раду мінливим, розумним демонам."}},faq={{q="Де відбувається закликання?",a="Ритуал відбувається в глибоких катакомбах під «Зарізаним Ягням» — непримітною корчмою в Кварталі магів Стормвінда. Чорнокнижники спускаються гвинтовими сходами повз пивний льох у підземне святилище з чародійськими колами закликання.",al={"де закликати","місце закликання сукуба","місце склепу"}},{q="Навіщо потрібне Осердя Серцедерева?",a="Осердя Серцедерева — це якір і каталізатор. Узяте з Серцедерева, що виросло в Ашенвалі там, де під час Війни Прадавніх полягли двоє закоханих нічних ельфів, воно дає саме той духовний резонанс, який потрібен, щоб розірвати невеликий розлам і заманити сукуба крізь Викривлений Нижній Світ.",al={"навіщо осердя серцедерева","що робить серцедерево"}},{q="Чому чорнокнижник мусить убити сукуба?",a="Демони Нижнього Світу коряться лише сильнішій волі й силі. Сукуб — майстер психологічних маніпуляцій і підкорення розуму; дати йому втілитися й не здолати одразу — значить накликати біду. Вбивши істоту в бою, чорнокнижник утверджує свою владу й силоміць закарбовує її на духові, перш ніж той знову збереться в Нижньому Світі.",al={"чому я б'юся з сукубом","чому вбити демона, щоб підкорити"}},{q="Хто такий Ґакін Зв'язувач Темряви?",a="Ґакін Зв'язувач Темряви — старший чорнокнижник, що живе під «Зарізаним Ягням» і наглядає за навчанням практиків Альянсу в Стормвінді. Він таємно добуває демонологічні артефакти й оцінює, чи вистачить учням волі, щоб підкорити демонічних істот.",al={"хто такий ґакін","ґакін зв'язувач темряви лор"}},{q="Що за Сурену згадує Ґакін?",a="Сурена Каледон — колишня учениця Ґакіна, яка втекла до Дефіас і чиє намисто ви раніше повернули. Ґакін іронічно міркує, чи не була вона перевдягненим сукубом, якого підіслали заморочити йому голову, — а тоді вирішує, що забагато їй честі.",al={"згадка про сурену","хто була сурена"}},{q="Чи можна сукубам ходити вулицями Стормвінда?",a="Відкрита демонологія суворо заборонена Церквою Святого Світла й владою королівства. Хоча ігрові механіки дозволяють підкореним демонам іти за чорнокнижниками містом, за лором ця практика ховається в тінях, підвалах і відлюдних святилищах на кшталт крипт «Зарізаного Ягняти».",al={"чи вартові бачать мого сукуба","чи законне закликання демонів у стормвінді"}}},fp="11,370,22.421.0,26.440.0,15.398.1,36.258.0,43.307.0,39.356.0,28.297.0,34.235.0,50.298.0"}
P.entries["quest:174"] = {n="Подивись на зорі",s="«Подивись на зорі» — початок задуму Вікторі Призм'Антраса зазирнути за моторошне склепіння крон Сутінколісся. Вікторі вірить, що темне прокляття лісу має наукове пояснення, а не лише чародійські забобони, і просить вас зібрати деталі для телескопа, який сконструював його приятель-гном.",h="«Подивись на зорі» — початок задуму Вікторі Призм'Антраса зазирнути за моторошне склепіння крон Сутінколісся.",kw={"подивись на зорі","вікторі призм'антрас","телескоп","коґ","даркшир","інженерія"},ang={["faction:Alliance"]="Поки патрулі Нічної Варти відбиваються від жахіть на дорогах довкола Даркшира, задум Вікторі уособлює маленьку, вперту надію міста збагнути, що отруїло їхній дім.",["profession:Engineering"]="Уся справа тримається на гномській конструкції та вправній роботі з металом, тож майстри можуть безпосередньо допомогти Вікторі в його астрономічних пошуках.",["race:Gnome"]="Вікторі покладається на винахідливість свого гномського товариша Коґа — ще одне свідчення того, що гномське ремесло несе лад і розум навіть у найтемніші закутки королівства."},sec={{t="Шукаючи в небесах",b="Серед мороку й страху, що огорнули Даркшир, Вікторі Призм'Антрас дивиться на лихо Сутінколісся вельми незвично. Замість того щоб приписувати скверну краю самій лише чорній магії, прокльонам чи неспокійним мерцям, Вікторі підозрює, що важливіші істини чекають високо над кронами. З кресленнями свого гномського товариша Коґа він береться будувати оптичний прилад, здатний зазирнути в небеса."},{t="Справа інженерії",b="Щоб почати збирати прилад для споглядання зірок, Вікторі потрібна міцна основа. За специфікаціями Коґа він просить мандрівників роздобути виточену бронзову трубу. Цей перший крок тримається на винахідливості смертних механіків, а не на чарах — і підкреслює вперте переконання Вікторі, що практичне ремесло й спостереження можуть пролити світло там, де містика безсила."}},faq={{q="Хто такий Вікторі Призм'Антрас?",a="Вікторі Призм'Антрас — учений мешканець Даркшира. На відміну від багатьох місцевих, яких скував страх чи поглинули забобони, він шукає раціонального пояснення скверні, що охоплює Сутінколісся, вивчаючи зорі.",al={"вікторі","хто дає подивись на зорі","вікторі призм'антрас"}},{q="Навіщо Вікторі будує телескоп?",a="Вікторі вірить, що дивне перетворення Сутінколісся має відчутне пояснення поза магією. Він сподівається, що, вдивляючись у небо крізь телескоп, побачить те, що проґавили місцеві легенди й чарівники.",al={"навіщо дивитися на зорі","навіщо бронзова трубка","завдання телескопа даркшир"}},{q="Хто такий Коґ?",a="Коґ — гном-інженер і друг Вікторі. Він накреслив механічні креслення, потрібні, щоб збудувати пристрій для спостереження за зорями.",al={"гном коґ","хто спроєктував телескоп"}},{q="Де взяти бронзову трубку?",a="Бронзову трубку зазвичай виготовляють інженери з певним досвідом. Мандрівники, які самі не інженери, часто дістають її обміном, на аукціоні або в мандрівних торговців інженерним крамом, у яких випадково знайдеться запас.",al={"як дістати бронзову трубку","місце бронзової трубки","де знайти бронзову трубку"}},{q="Чи це частина довшого ланцюжка завдань?",a="Так. Це перший крок у кількаетапній справі: зібрати й налаштувати зореглядний пристрій Вікторі в Даркширі.",al={"ланцюжок подивись на зорі","скільки завдань подивись на зорі"}},{q="Чому Вікторі шукає в Сутінколіссі природних пояснень?",a="Хоча ліс аж кишить нежиттю й темними чарами, Вікторі вірить, що перетворенням досі можуть керувати фундаментальні космічні чи природні закони, — тож він шукає відповідей у вивченні небесних світил.",al={"чому наукове пояснення в сутінколіссі","магія чи наука в сутінколіссі"}}},fp="17,288,19.432.0,23.382.0,28.217.0,43.230.0,11.130.0,36.237.0,35.128.0,60.201.0"}
P.entries["quest:1740"] = {n="Сфера Соран'рука",s="«Сфера Соран'рука» — обряд посвяти для чорнокнижників, який доручає самітник Доан Кархан на півдні Пусток. Молоді знавці темних мистецтв розшукують розбиті демонічні реліквії по всьому Азероту, щоб знову скласти посудину, яка ув'язнює суть зганьбленого демона.",h="«Сфера Соран'рука» — обряд посвяти для чорнокнижників, який доручає самітник Доан Кархан на півдні Пусток.",kw={"сфера соран'рука","доан кархан","молот присмерку","фортеця шадовфенг","чорнокнижник","палаючий легіон"},ang={["class:Warlock"]="Відновлення Соран'рука — велика віха для чорнокнижників: воно вчить, як Легіон карає своїх і як ув'язнені демонічні сутності можна перетворити на робочі знаряддя.",["faction:Horde"]="Доан Кархан живе на суворих просторах Пусток, тож південні рівнини — обов'язкова зупинка для мандрівних заклиначів, що шукають глибших темних знань."},sec={{t="Посудини для зганьблених",b="В ієрархії Палаючого Легіону за невдачу карають довіку. Коли менші демони втрачають прихильність своїх демонічних володарів, їхні духи зв'язують і ув'язнюють у кришталевих сферах. Ці артефакти потім роздають смертним заклиначам і чорнокнижникам Легіону як провідники чистої, підкореної сили. Навіть коли сферу розбито на уламки, ув'язнена в ній демонічна суть зберігає могутню магічну силу."},{t="Розкидана по континентах",b="Сфера Соран'рука не лишилася цілою. Розбита на частини, вона розійшлася по темних закутках обох великих континентів. Одну половину розтрощили ще дрібніше, і її уламки тримають сектанти Молота Присмерку у вогких глибинах Чорноглибинних Печер в Ашенвалі. Більша, ціла половина потрапила за море, до Срібнолісся, і нею заволодів один із чаклунів у примарних руїнах Фортеці Шадовфенг. Доан Кархан, що все життя вивчає сфери Легіону й уже склав Сферу Зарґейна, використовує здобуті уламки, щоб відновити Соран'рук як дієве знаряддя."}},faq={{q="Що таке Сфера Соран'рука?",a="Соран'рук — демон Палаючого Легіону, що впав у неласку. За демонічним звичаєм його дух ув'язнили в магічній сфері й віддали смертним практикам. Згодом сферу розбили, але навіть її уламки зберігають силу ув'язненого демона.",al={"лор соран'рука","що таке соран'рук","хто був соран'рук"}},{q="Хто такий Доан Кархан?",a="Доан Кархан — відлюдний чорнокнижник з південних Пусток, який присвятив життя вивченню й відновленню сфер Палаючого Легіону. Багато років він збирав власний артефакт, Сферу Зарґайна, а тепер допомагає молодим чорнокнижникам скласти докупи Сферу Соран'рука.",al={"хто такий доан кархан","історія доана кархана"}},{q="Чому сфера розкидана по двох різних підземеллях?",a="Первісну сферу розкололо на дві головні частини. Одна розлетілася на дрібніші уламки, якими користуються культисти Молота Присмерку в Чорноглибинних Печерах, а великий залишок привласнив чарівник у похмурих мурах Фортеці Шадовфенг.",al={"чому уламки в двох підземеллях","де уламки соран'рука"}},{q="Хто може взятися за це завдання?",a="Це завдання — лише для чорнокнижників, які прагнуть удосконалити своє ремесло й опанувати артефакти, викувані з ув'язнених демонічних духів.",al={"хто може виконати завдання","чи сфера соран'рука лише для чорнокнижників"}},{q="Що Доан Кархан робить зі знайденими уламками?",a="Доан Кархан вивчає уламки, щоб просунути свої дослідження реліквій Легіону, а тоді складає їх у цілком відновлене магічне знаряддя тієї форми, яку обере чорнокнижник.",al={"що буде після збору уламків","відновлення соран'рука"}},{q="Що таке Сфера Зарґайна?",a="Сфера Зарґайна — демонічна сфера-в'язниця, яку Доан Кархан багато років розшукував і відновлював для себе; у ній ув'язнено іншого зганьбленого демона Легіону.",al={"сфера зарґайна","зарґайн лор"}}},fp="20,247,24.444.0,27.600.0,29.264.0,19.280.0,52.248.0,28.137.0,54.184.0,27.170.0"}
P.entries["quest:175"] = {n="Подивись на зорі",s="За кресленнями майстра Коґа Вікторі Призм'Антрас шукає дзеркальну поверхню, щоб зібрати свій телескоп у Даркширі. Він посилає мандрівників на південь Сутінколісся розшукати Мері — місцеву жінку, яку пам'ятають тим, що вона завжди носила при собі дзеркальце.",h="За кресленнями майстра Коґа Вікторі Призм'Антрас шукає дзеркальну поверхню, щоб зібрати свій телескоп у...",kw={"подивись на зорі","вікторі призм'антрас","сліпа мері","дзеркальце","цвинтар тихих садів","телескоп"},ang={["faction:Alliance"]="Допомога Вікторі з телескопом — рідкісний проблиск допитливості й поступу в місті, яке інакше поглинули жах і тлін.",["profession:Engineering"]="Збирання телескопа вимагає точних оптичних специфікацій: гномські креслення допомагають відбити й збільшити ледь помітне світло зірок."},sec={{t="Дзеркальна поверхня",b="Роздобувши бронзову трубу для телескопа, Вікторі Призм'Антрас береться за наступну вимогу з креслень Коґа: надійне дзеркало, що спрямовуватиме й відбиватиме світло в приладі. Замість того щоб у злиденному Даркширі виготовляти тонке посріблене скло з нуля, Вікторі згадує Мері — місцеву мешканку, відому на всю округу тим, що вона завжди мала при собі дзеркальце."},{t="Пошуки на півдні",b="Колишня оселя Мері лежить глибоко на півдні Сутінколісся, трохи на північ від проклятого Цвинтаря Тихих Садів. Шукаючи її, шукачі пригод виходять за безпечні межі патрулів Нічної Варти й потрапляють у зотлілі гаї, що кишать ненажерливими вовками, дикими павуками й блукаючою нежиттю."},{t="Трагічна мешканка",b="Діставшись скромної хатини Мері на півдні, мандрівники бачать гірку правду падіння Сутінколісся. Жінка, яку пам'ятав Вікторі, вже не жива мешканка, а Сліпа Мері — блукаючий дух, що тримається біля старої оселі й сусіднього цвинтаря, прив'язаний до спогадів і речей колишнього життя."}},faq={{q="Що будує Вікторі Призм'Антрас?",a="Вікторі будує астрономічний телескоп у своїй хатині на пагорбі в Даркширі за кресленнями майстра-винахідника на ім'я Коґ.",al={"телескоп вікторі","проєкт подивись на зорі","що робить вікторі"}},{q="Навіщо Вікторі дзеркальце?",a="За оптичними кресленнями Коґа потрібне дзеркало, щоб відбивати й фокусувати світло в корпусі телескопа. Вікторі пам'ятає, що Мері завжди носила із собою дзеркальце, і сподівається дістати його для свого пристрою.",al={"навіщо дзеркальце","відбивна поверхня телескопа"}},{q="Де знайти Мері?",a="Мері живе в зруйнованому домі на південному сході Сутінколісся, трохи на північ від Цвинтаря Тихих Садів.",al={"де мері","місце мері в сутінколіссі","знайти сліпу мері"}},{q="Хто така Мері?",a="Мері жила на півдні Сутінколісся ще до того, як край поглинула проклята темрява, і в Даркширі її добре знали, бо вона завжди мала при собі дзеркальце. Що з нею сталося, вам доведеться дізнатися самим у її старому домі біля Цвинтаря Тихих Садів.",al={"хто така сліпа мері","передісторія сліпої мері"}},{q="Чи ще має Мері своє дзеркальце?",a="Коли до неї підійти, Мері визнає, що колись мала дзеркальце, але тепер його в неї немає — вона може лише підказати, куди воно поділося.",al={"чи є в мері дзеркальце","дзеркальце сліпої мері"}},{q="Які небезпеки чатують довкола хатини Мері?",a="Південно-східні ліси й сусідній Цвинтар Тихих Садів кишать ворожою нежиттю, дикими сутінковими кажанами, отруйними павуками-тенетниками й скаженими вовками, що полюють на мандрівників, які забрели на південь від Даркшира.",al={"небезпеки біля мері","загрози цвинтаря тихих садів"}}},fp="17,265,20.388.0,19.282.0,17.298.1,38.138.0,38.189.0,24.109.0,12.246.1,39.144.1,37.199.0"}
P.entries["quest:1758"] = {n="Фоліант Кабали",s="«Фоліант Кабали» посилає молодого чорнокнижника Альянсу з круч над Раджетом назад до Бібліотеки Айронфорджа. Щоб викликати й підкорити ненажерливого мисливця Скверни, заклинач мусить відшукати легендарний посібник, написаний першими чорнокнижниками, яким колись вдалося приборкати цього звіра.",h="«Фоліант Кабали» посилає молодого чорнокнижника Альянсу з круч над Раджетом назад до Бібліотеки Айронфорджа.",kw={"фоліант кабали","кром стаутарм","зала дослідників","айронфордж","мисливець скверни","страгад фарсан"},ang={["class:Warlock"]="Здобути Фоліант Кабали — вирішальний обряд посвяти для знавця темних мистецтв, що прагне влади над мисливцями Скверни: це крок від менших слуг до справжньої антимагічної демонології.",["faction:Alliance"]="Знавцям темних мистецтв з Альянсу доводиться повертатися з рубежів Калімдору до Зали Дослідників в Айронфорджі, щоб звернутися до дворфійської вченості по заборонені темні тексти.",["race:Dwarf"]="Кром Стаутарм доводить, що не кожен дворф, який сидить у Залі Дослідників, відкопує артефакти Титанів, — дехто потай збирає знання Палаючої Тіні."},sec={{t="Звір, що живиться магією",b="Щоб підкорити біса, блукача Порожнечі чи сукуба, потрібен обряд, але мисливець Скверни — небезпека зовсім іншого штибу. Мисливці Скверни не просто служать Палаючому Легіонові: вони самі полюють на магічну енергію й пожирають її. Звичайне коло виклику перед таким звіром розсиплеться, а сам він висмокче магію заклинача ще до того, як зв'язування встигне вчепитися. Страгад Фарсан, що наглядає за Раджетом зі своєї твердині в Пустках, надто мудрий, щоб дозволити недосвідченому братися за таке зв'язування без підготовки."},{t="Перше зв'язування",b="Щоб безпечно викликати й зв'язати мисливця Скверни, учневі потрібні магічні формули, зібрані у Фоліанті Кабали. Цей рукопис написала найперша смертна кабала чорнокнижників, яка без сторонньої допомоги зуміла зламати мисливця Скверни; він докладно описує особливу геомантію, матеріали й руни зв'язування, потрібні, щоб устояти перед голодом істоти. На біду Страгада і його кола, їхній примірник цієї шедевральної праці давно загубився."},{t="Збирач із Дун Мороґа",b="Не маючи змоги дати текст сам, Страгад посилає чорнокнижників Альянсу за Велике море, до Зали Дослідників в Айронфорджі. Там тиняється Кром Стаутарм — мандрівний дворф-чорнокнижник, що на схилі літ перебирає давні рукописи й бібліотечні записи. Якщо у Східних Королівствах і лишився бодай якийсь слід загубленого гримуара, він похований у ретельних каталогах Крома."}},faq={{q="Навіщо шукати Фоліант Кабали?",a="У Фоліанті Кабали — точні настанови, які записали перші смертні чорнокнижники, що самотужки закликали й підкорили мисливця Скверни. Звичайних ритуалів закликання замало, щоб упіймати демона, який активно живиться магічною енергією.",al={"що таке фоліант кабали","навіщо шукати книгу","мета фоліанта кабали"}},{q="Хто такий Кром Стаутарм?",a="Кром Стаутарм — мандрівний дворф-чорнокнижник, що оселився в бібліотеці Зали Дослідників в Айронфорджі. Він днями сидить серед запилених фоліантів і впорядковує давні історичні записи.",al={"де кром","хто такий кром стаутарм","кром айронфордж"}},{q="Що Страгад Фарсан робить у Пустках?",a="Страгад Фарсан — досвідчений чорнокнижник-людина, що тримає тихий нейтральний притулок на кручах над Раджетом. Подалі від пильних очей Кірін-Тору й влади Стормвінда він навчає могутньої демонології практиків і Альянсу, і Орди.",al={"місце страгада","чому ретчет","хто такий страгад"}},{q="Що буде після розмови з Кромом Стаутармом?",a="Кром Стаутарм пригадує згадки про фоліант у старих каталожних реєстрах. Він доручить вам розшукати його загублені частини й рідкісні реагенти, потрібні, щоб відновити гримуар.",al={"наступне завдання","після крома","наступний крок фоліанта кабали"}},{q="Чи можуть чорнокнижники Орди виконати це завдання?",a="Ця подорож до Айронфорджа — лише для чорнокнижників Альянсу. Чорнокнижники Орди отримують від Страгада схоже завдання, яке натомість посилає їх до обізнаних людей на землях Орди.",al={"версія для орди","чи лише для альянсу"}},{q="Якого демона відкриває цей ланцюжок завдань?",a="Увесь ланцюжок завдань про Фоліант Кабали завершується ритуальним боєм із закликаним мисливцем Скверни, після якого чорнокнижник знає, як закликати й підкорити такого демона назавжди.",al={"який демон","завдання мисливця скверни","якого улюбленця я отримаю"}}},fp="17,266,27.470.0,17.439.0,25.399.0,44.244.0,21.197.0,37.269.0,44.198.1,33.203.0,38.180.0"}
P.entries["quest:176"] = {n="РОЗШУКУЄТЬСЯ: «Гоґґер»",s="«РОЗШУКУЄТЬСЯ: „Гоґґер“» — оголошення Альянсу про винагороду, вивішене біля Ґолдшира, за голову велетенського лютого ватажка гнолів. Гоґґер никає південно-західними хащами Лісу Елвінн і жорстоко зривав усі спроби місцевої влади його здолати.",h="«РОЗШУКУЄТЬСЯ: „Гоґґер“» — оголошення Альянсу про винагороду, вивішене біля Ґолдшира, за голову велетенського...",kw={"гоґґер","гноли","розшукується","винагорода","ґолдшир","ліс елвінн","узлісся"},ang={["faction:Alliance"]="Перемога над Гоґґером вважається обрядом посвяти для молодих героїв Альянсу, що гартують характер, обороняючи серце земель Стормвінда.",["race:Human"]="Для людей Елвінну смерть Гоґґера означає безпеку садиб і торгових шляхів, які місяцями тероризували засідки гнолів."},sec={{t="Загроза в лісі",b="Поки Ліс Елвінн потерпає від розбою й навали кобольдів, племена гнолів на півдні стали зухвалішими й згуртованішими під грубим проводом Гоґґера. Гоґґер, що височіє над звичайними гнолами Річколапів, отаборився біля Узлісся, нападає на подорожніх і бере гору над патрулями місцевого ополчення, яких посилають його вгамувати."},{t="Відчай Ґолдшира",b="Армія Стормвінда розтягнута до межі й не може виділити регулярних сил, щоб пильнувати околиці столиці, тож Маршал Дуґан пішов на незвичний крок — призначив відкриту винагороду за звіра. Щоб здолати Гоґґера, треба заглибитися у вкрай ворожі землі гнолів, а його лютість зробила його найсмертоноснішою загрозою для шукачів пригод-початківців в Елвінні."}},faq={{q="Хто такий Гоґґер?",a="Гоґґер — незвично великий і лютий ватажок гнолів, що тероризує південний захід Лісу Елвінн. Він керує місцевими зграями довкола Узлісся й жорстоко відбив усі попередні спроби вартових Стормвінда схопити чи вбити його.",al={"хто такий гоґґер","гоґґер лор","що таке гоґґер"}},{q="Де знайти Гоґґера?",a="Гоґґер блукає між таборами гнолів на південному заході Лісу Елвінн, біля південних околиць, відомих як Узлісся, трохи на північ від річки, що відділяє ліс від Вестфолу й Сутінколісся.",al={"місце гоґґера","де гоґґер","знайти гоґґера"}},{q="Чому за голову Гоґґера призначено винагороду?",a="Армія Стормвінда призначила винагороду за Гоґґера, бо він здолав місцеві патрулі й смертельно небезпечний для мандрівників. Регулярних військ по всьому королівству бракує, тож Маршал Дуґан звернувся до незалежних шукачів пригод і мисливців за головами, щоб позбутися загрози.",al={"чому вбити гоґґера","плакат розшукується гоґґер","хто призначив винагороду за гоґґера"}},{q="Кому нести доказ загибелі Гоґґера?",a="Доказ загибелі звіра — його Велетенський Кіготь Ґнола — треба принести просто Маршалові Дуґану, який командує місцевим гарнізоном у Ґолдширі.",al={"здати гоґґера","кому здати гоґґера","кому потрібен кіготь гоґґера"}},{q="Чому Гоґґер небезпечніший за інших гнолів?",a="На відміну від звичайних гнолів, що никають Елвінном, Гоґґер має велетенську статуру й неабияку жорстокість. Він б'є значно сильніше й витримує набагато більше, тож часто розправляється з бійцями-одинаками, які його недооцінюють.",al={"чи гоґґер сильний","чому гоґґер елітний"}},{q="Чому вартові Стормвінда не можуть самі впоратися з Гоґґером?",a="Військові сили королівства геть виснажені: вони прикуті до оборони головних кордонів і до клопотів зі зникненням короля Варіана Рінна. Невеликому загонові Маршала Дуґана в Ґолдширі бракує людей, щоб безпечно вполювати таку живучу потвору.",al={"чому дуґан не вб'є гоґґера","де армія стормвінда"}}},fp="16,253,21.347.0,23.369.0,14.234.0,26.184.0,32.274.0,41.151.0,52.226.0,56.251.0"}
P.entries["quest:177"] = {n="Подивись на зорі",s="Це завдання посилає шукачів пригод повернути викинуте дзеркальце Сліпої Мері для астронома Вікторі Призм'Антраса. Тендітне дзеркальце потрапило до лап Божевільного Гуля, що блукає спустошеним Цвинтарем Тихих Садів на півдні Сутінколісся.",h="Це завдання посилає шукачів пригод повернути викинуте дзеркальце Сліпої Мері для астронома Вікторі...",kw={"подивись на зорі","сліпа мері","божевільний гуль","цвинтар тихих садів","вікторі призм'антрас","дзеркальце"},ang={["class:Priest"]="Жерці, що ступають оскверненою землею Цвинтаря Тихих Садів, бачать жахливе приниження мерців Сутінколісся: загиблих селян обернено на божевільних трупоїдів.",["faction:Alliance"]="Повертаючи загублені реліквії містян із рук ненажерливої нежиті, ви бачите гірку долю людей Сутінколісся, покинутих на небезпечних околицях Королівства Стормвінд.",["profession:Engineering"]="Інженери оцінять імпровізовану оптику Вікторі, що обертає звичайні поліровані ручні дзеркальця на відбивачі для астрономічного приладу."},sec={{t="Реліквія кращих днів",b="Ще до того як темрява, що підкрадалася, поглинула Велике Селище й обернула її на заплакану примару, Сліпа Мері дорожила вишуканим дзеркальцем. Після жахливої події, що забрала в неї зір і розум, вона кинула пам'ятку в землю за родинною стодолою. Саме таке дзеркальце потрібне Вікторі Призм'Антрасу для його величного телескопа в Даркширі, але його поцупили в темряву задовго до того, як астроном замріяв вивчати небеса."},{t="Цвинтарний нишпорка",b="Дзеркальце підібрав Божевільний Гуль, що нишпорив за зруйнованими хуторами. Гнаний на південь неспокійним голодом, жалюгідний мрець заніс дзеркальце на Цвинтар Тихих Садів і тепер блукає покинутою каплицею серед зарослих надгробків. Щоб повернути тендітне скло, доведеться пробитися крізь трупоїдних жахіть, що заполонили південні ліси, і вирвати втрачений скарб Мері з гнилих пазурів."}},faq={{q="Навіщо Вікторі дзеркальце Мері?",a="Вікторі Призм'Антрас збирає потужний телескоп у своїй хатині на пагорбі в Даркширі. Йому потрібні якісні лінзи й дзеркала, щоб уловлювати тьмяне світло зір, а цінна родинна реліквія Мері якраз відповідає оптичним вимогам його винаходу.",al={"дзеркальце вікторі","навіщо дзеркальце","для чого дзеркало"}},{q="Хто такий Божевільний Гуль, що вкрав дзеркало?",a="Божевільний Гуль — мерзенна нежить-збирач, яка тягала дрібнички з покинутих хуторів біля дому Мері. Він утік на південь і сховався в зруйнованій каплиці на Цвинтарі Тихих Садів.",al={"де божевільний гуль","хто має дзеркальце","гуль у каплиці"}},{q="Чому Сліпа Мері викинула своє дзеркальце?",a="Мері дорожила дзеркальцем аж до «того випадку», що відібрав у неї зір, затьмарив розум і прикував її як неспокійну тінь. Після того лиха вона вже не могла ні дивитися в нього, ні тримати його в руках і в розпачі викинула за свою стодолу.",al={"чому мері викинула","дзеркальце сліпої мері","випадок із дзеркальцем мері"}},{q="Де розташований Цвинтар Тихих Садів?",a="Цвинтар Тихих Садів лежить на південному сході Сутінколісся, на південь від головного шляху. Колись це був спокійний цвинтар Ґранд-Гемлету, а тепер там кишать агресивні гулі, скелети й звірі-падальники.",al={"місце цвинтаря тихих садів","де цвинтар"}},{q="Хто такий Коґ?",a="Коґ — гном-винахідник, що живе в Даркширі. Вікторі покладається на інженерний хист Коґа, щоб оцінити й допомогти зібрати тонкі механізми своєї машини для спостереження за зорями.",al={"хто такий коґ","коґ вікторі"}},{q="Що відбувається, коли повернути дзеркало Вікторі?",a="Отримавши дзеркало, Вікторі в захваті від того, як просувається робота. Він переходить до останнього етапу складання телескопа й просить ще одну, вирішальну деталь, щоб завершити систему лінз.",al={"наступне завдання подивись на зорі","що буде далі"}}},fp="17,249,22.467.0,23.420.0,43.261.0,46.205.0,48.237.0,39.221.0,11.184.0,51.228.1"}
P.entries["quest:1782"] = {n="Обладунок Фурена",s="«Обладунок Фурена» — вершина завдання молодого воїна, який допомагає майстрові-ковалю Фуренові Лонґбірду в Стормвінді. Зібравши павучі ікла, роги химер і флакон флогістону, шукач пригод допомагає Лонґбірдові викувати міцну загартовану вогнем кольчугу. На подяку Лонґбірд вручає воїнові готову кольчугу й обіцяє поділитися своїми новими металургійними прийомами з усім Альянсом.",h="«Обладунок Фурена» — вершина завдання молодого воїна, який допомагає майстрові-ковалю Фуренові Лонґбірду в...",kw={"обладунок фурена","фурен лонґбірд","загартована вогнем кольчуга","воїн","ковальство","стормвінд"},ang={["class:Warrior"]="Для воїнів Альянсу, що тільки мужніють, здобути особливо загартовану броню Фурена — обряд посвяти й незамінний захист у перших походах на передовій.",["faction:Alliance"]="Добре спорядження вкрай важливе, щоб війська Альянсу вистояли проти невпинних загроз — Дефіас, гнолів і ворожих сил стихій.",["profession:Blacksmithing"]="Вдалий експеримент Фурена підкреслює традицію співпраці ковалів Альянсу, які діляться особливими металургійними відкриттями, щоб підносити рівень ремесла в Стормвінді й Айронфорджі."},sec={{t="Прорив майстра",b="Фурен Лонґбірд, шанований дворф-бронник, що працює в Стормвінді, присвятив своє ремесло тому, щоб розсунути межі захисної металургії Альянсу. Доручивши відважному шукачеві пригод розшукати рідкісні ікла, роги й флогістон, Лонґбірд прагнув випробувати новітні прийоми гартування кольчуги проти пекучого жару й нищівних ударів. Робота вдалася на славу й утвердила Лонґбірда як одного з провідних бронників Альянсу."},{t="Ремесло, яким діляться",b="Вручаючи щойно викувану загартовану вогнем кольчугу шукачеві пригод, який зібрав матеріали, Фурен щиро дякує за співпрацю. Його експерименти дали більше, ніж одну міцну кольчугу: вони поглибили його розуміння захисного ковальства. У дусі спільноти майстрів Айронфорджа й Стормвінда Лонґбірд вирішує розіслати свої записи й відкриття іншим ковалям Альянсу, щоб його прорив зміцнив бійців передової по всьому Альянсу."}},faq={{q="Хто такий Фурен Лонґбірд?",a="Фурен Лонґбірд — дворфійський майстер-бронник, що працює в Стормвінді. Він багато співпрацює з бойовими орденами Альянсу, особливо з воїнами, яким потрібен особливий, добротний обладунок.",al={"хто такий фурен","фурен лонґбірд","коваль стормвінда фурен"}},{q="Який обладунок створив Фурен?",a="Після численних дослідів з рідкісними іклами, рогами й флогістоном Фурен викував Загартований Вогнем Обладунок — кольчужний нагрудник. Він задумав його так, щоб той витримував люті атаки й нестерпний жар на полі бою.",al={"який обладунок робить фурен","загартована вогнем кольчуга","нагорода фурена"}},{q="Кому Фурен Лонґбірд надсилає свої ковальські відкриття?",a="Фурен обіцяє розіслати свої технічні висновки й записи іншим ковалям по всьому Альянсу, щоб нові, щойно випробувані способи гартування прислужилися зброярням і кузням усього королівства.",al={"кому надсилають записи фурена","хто отримує проєкти фурена","ковалі альянсу"}},{q="Чому воїна попросили зібрати реагенти для Фурена?",a="Фуренові потрібні були рідкісні й нестійкі складники, щоб випробувати ще не перевірені ковальські прийоми. Сам він не міг покинути кузню й полювати на павуків Багнокраю та химер у Горах Кам'яного Кігтя, тож покладався на завзятого воїна.",al={"чому збирати реагенти для фурена","матеріали завдання кольчуги"}},{q="Де кують і вручають цей обладунок?",a="Обмін відбувається просто біля кузні Фурена Лонґбірда в Стормвінді, де той завершує останнє кування й охолодження кольчуги.",al={"де фурен лонґбірд","місце здавання","місце фурена"}},{q="Чи прислужиться ця робота іншим бійцям Альянсу?",a="Так. Фурен зауважує, що здобутими під час роботи з цими матеріалами знаннями поділиться з іншими бронниками Альянсу, і сподівається, що це спонукає інших ковалів виготовляти добірне спорядження для вояків Альянсу.",al={"користь для альянсу","прорив фурена"}}},fp="13,426,23.485.0,17.494.0,23.201.0,36.214.0,57.204.0,55.237.0,41.155.0,47.223.0"}
P.entries["quest:179"] = {n="Дворфійські постачальники",s="Дворфійські постачальники — вступне завдання на виживання в Долині Холодного Хребта, яке пропонує Стен Стаутарм. За винищення місцевих вовків і збирання їхнього жилавого м'яса на зимові харчі новобранців винагороджують міцними рукавицями, що бережуть від обмороження в лютому холоді Дун Мороґу.",h="Дворфійські постачальники — вступне завдання на виживання в Долині Холодного Хребта, яке пропонує Стен...",kw={"дворфійські постачальники","стен стаутарм","вовки","рукавиці","долина холодного хребта","анвілмар","виживання"},ang={["race:Dwarf"]="Для молодих дворфів Бронзбірдів, що виходять у Долину Холодного Хребта, це завдання — ранній урок прикордонної самодостатності: заробіть своє утримання, забезпечте табір і шануйте гірський холод.",["race:Gnome"]="Знайшовши притулок у дворфійських родичів у Дун Мороґу, гноми швидко переконуються, що для виживання в Анвілмарі практичний гірський одяг потрібен не менше за гострий розум."},sec={{t="Чесна угода в Холодному Хребті",b="Високогірний перевал Долини Холодного Хребта люто холодний, і непідготовлені мандрівники швидко переконуються, що звичайне спорядження стихії не рівня. Стоячи біля Анвілмара, Стен Стаутарм пропонує новобранцям просту прикордонну угоду: вирушити в засніжені замети, вполювати вовків, що там никають, і принести шматки жилавого м'яса, щоб поповнити припаси застави. Натомість він дає справжні теплі рукавиці, щоб молоді шукачі пригод зберегли всі десять пальців."},{t="Жити з того, що дає долина",b="Хоч вовки — постійна небезпека для дворфійських розвідників і гномів-новачків, що навчаються в долині, вони також життєво важливий ресурс. Їхнє м'ясо годує гарнізон, що стоїть в Анвілмарі, а винищення їхнього поголів'я робить стежки між місцевими таборами дещо безпечнішими. Угода Стаутарма має подвійну мету: перевірити вміння новобранця давати раду місцевій звірині й заразом запасти харчі на люті ночі попереду."}},faq={{q="Хто такий Стен Стаутарм?",a="Стен Стаутарм — дворф, що стоїть біля Анвілмара в Долині Холодного Хребта. Він приглядає за новоприбулими новобранцями й дбає, щоб вони мали належне спорядження й пережили морози Дун Мороґу, — дає практичні речі в обмін на здобич з полювання.",al={"стен стаутарм","хто дає дворфійських постачальників","постачальник анвілмара"}},{q="Навіщо Стенові вовче м'ясо?",a="Застава в Анвілмарі поповнює запаси завдяки місцевому полюванню. Вовче м'ясо — ситна й надійна їжа для вояків і наставників, що живуть у відлюдній засніженій долині.",al={"навіщо вовче м'ясо","жорстке вовче м'ясо","для чого м'ясо"}},{q="Де шукати вовків для цього завдання?",a="Вовки блукають засніженими галявинами по всій Долині Холодного Хребта, особливо одразу за головним подвір'ям Анвілмара й уздовж стежок до віддалених таборів.",al={"де вовки","місця вовків холодного хребта","де взяти м'ясо"}},{q="Яку нагороду дає Стен?",a="Стен винагороджує новобранців надійною парою теплих рукавиць, які рятують від обмороження й захищають руки бійця від пронизливих вітрів Дун Мороґу.",al={"нагорода дворфійських постачальників","які рукавиці дадуть","нагорода за завдання"}},{q="Чи вважають дворфи вовче м'ясо доброю їжею?",a="Жорстке вовче м'ясо грубе й жилаве, але в суворому гірському кліматі Дун Мороґу дворфи цінують ситну їжу більше за вишукані страви. Тушковане чи засмажене над вогнищем, воно цілком годиться для гарнізону.",al={"чи смачне вовче м'ясо","дворфи вовче м'ясо","їсти вовка"}},{q="Чи можуть це завдання виконати й гноми?",a="Так. Гноми, що навчаються пліч-о-пліч із союзниками-дворфами в Долині Холодного Хребта, терплять ті самі пронизливі вітри й так само нагально потребують теплого одягу.",al={"гноми дворфійські постачальники","чи гноми можуть отримати рукавиці","гноми і холод"}}},fp="18,283,25.471.0,21.438.0,21.262.0,29.195.0,43.175.0,30.166.0,48.221.0,29.145.0"}
P.entries["quest:1791"] = {n="Спостерігач Вітрів",s="«Спостерігач Вітрів» — настанова, що скеровує досвідчених воїнів на пошуки відлюдного троля-шамана далеко на півночі. Довівши свій гарт у випробуванні Бійкою й опанувавши стійку берсерка, воїни вирушають шукати зброю, гідну їхньої зростаючої люті.",h="«Спостерігач Вітрів» — настанова, що скеровує досвідчених воїнів на пошуки відлюдного троля-шамана далеко на...",kw={"спостерігач вітрів","бат'ра","стійка берсерка","кланнок маклауд","гори альтерак","воїн"},ang={["class:Warrior"]="Цей обряд посвяти поєднує опанування стійки берсерка на Острові Бійки з пошуками легендарної зброї, викуваної силою стихій.",["race:Troll"]="Пошуки Бат'ри показують, що навіть серед зруйнованих руїн Лордерону тролі-шамани й зброярі володіють містичними знаннями, які шанують воїни будь-якого роду."},sec={{t="Зброя для берсерка",b="Пройшовши жорстоке випробування на витривалість у Бійці на Острові Бійки, воїни опановують у Кланнока Маклауда люту науку стійки берсерка. Та сира бойова наука вимагає зброї не меншої слави. Розуміючи це, Кланнок відсилає багатообіцяльних бійців геть від узбережжя Пусток — через континенти, на пошуки самотнього майстра, здатного викувати надзвичайну зброю."},{t="Самітник на березі річки",b="Завдання веде мандрівників углиб спірних долин північного Лордерону — до оповитого туманом прикордоння між Горами Альтерак і сплюндрованими Західними Чумними Землями. Біля річки, що тече на північ повз Таррен Мілл, серед кам'яних руїн самотньо живе троль-самітник Бат'ра Спостерігач Вітрів. Бат'ра — не звичайний самітник: він і обдарований зброяр, і могутній шаман стихій, що чекає на воїнів, досить рішучих, аби викувати щось справді величне."}},faq={{q="Хто посилає шукати Спостерігача Вітрів?",a="Кланнок Маклауд, майстер бойових випробувань з Острова Бійки біля східного узбережжя Пусток, відправляє вас у цю подорож, коли ви здолаєте Бійку й опануєте стійку берсерка.",al={"хто дає завдання","хто дає спостерігача вітрів","завдання кланнока маклауда"}},{q="Хто такий Бат'ра Спостерігач Вітрів?",a="Бат'ра — загадковий троль-відлюдник, майстер-зброяр і могутній шаман, що живе на самоті в дикій глушині між Горами Альтерак і Західними Чумними Землями.",al={"хто такий бат'ра","бат'ра спостерігач вітрів лор","особа бат'ри"}},{q="Де саме перебуває Бат'ра?",a="Бат'ра отаборився на східному березі річки, що тече на північ повз Таррен Мілл, біля давніх руїн на межі Альтераку й Західних Чумних Земель.",al={"де бат'ра","місце бат'ри","знайти бат'ру"}},{q="Чому Кланнок посилає воїнів до Бат'ри?",a="Кланнок розуміє, що воїнові, який опанував люту стійку берсерка, потрібна виняткова зброя, щоб спрямувати цю лють, а Бат'ра має рідкісні знання стихій і ковальства, щоб таку викувати.",al={"чому йти до бат'ри","мета цього завдання","навіщо спостерігач вітрів"}},{q="Що далі після розмови з Бат'рою?",a="Розмова з Бат'рою одразу веде до завдання вистояти проти буремного елементаля Циклоніана й зібрати рідкісні матеріали для потужної бойової зброї.",al={"що після спостерігача вітрів","наступне завдання циклоніана","продовження спостерігача вітрів"}},{q="Чи безпечна ця подорож для мандрівника з Пусток?",a="Вона доволі небезпечна. Шлях веде через передгір'я Гілсбреда до спірних північних земель повз схованки Синдикату, лютих гірських хижаків і смертоносну чуму Західних Чумних Земель.",al={"чи небезпечно","небезпека річки таррен мілл"}}},fp="15,283,24.410.0,27.517.0,38.202.0,32.171.0,34.175.0,43.210.0,40.163.1,60.223.0"}
P.entries["quest:1793"] = {n="Фоліант Звитяги",s="Фоліант Звитяги — одне з перших справжніх випробувань для паладинів Альянсу, що набираються сили. Наставники-паладини Стормвінда й Айронфорджа вимагають від посвячених довести, що їхня мужність і відданість захисту невинних не поступаються бойовій вправності.",h="Фоліант Звитяги — одне з перших справжніх випробувань для паладинів Альянсу, що набираються сили.",kw={"фоліант звитяги","паладин","святе світло","собор світла","зала таїнств","відвага"},ang={["class:Paladin"]="Цей обряд знаменує ваш перехід від простого послушника до надійного захисника Святого Світла: він вимагає ставити самовіддане служіння вище за власну безпеку.",["faction:Alliance"]="Випробування з Фоліанту готують поборників, що боронитимуть поселення Альянсу від нових загроз — від місцевих розбійників до жахливих загарбників.",["race:Dwarf"]="Паладини Айронфорджа на чолі з наставниками на кшталт Тізи Баттлфордж бачать у Фоліанті Звитяги доказ того, що дворфійську витривалість зміцнює свята мета.",["race:Human"]="Це випробування проводять під пильним оком Дуторіана Ралла в Соборі Світла; воно відбиває незмінну відданість Стормвінда засадам, на яких постала Срібна Длань."},sec={{t="Мірило паладина",b="Щоб нести Святе Світло в бій, мало важкої броні й бойової дисципліни. Коли юні паладини сягають нових висот у навчанні, наставники в Соборі Світла й Залі Таїнств вимагають доказів їхньої внутрішньої стійкості. Уроки Фоліанту Звитяги перевіряють, чи готовий посвячений стати проти найстрашнішого зла — від драконів до демонів, — не завагавшись і не покинувши тих, хто не може захистити себе сам."},{t="Чесноти ордену",b="Відвага перед смертельною загрозою для святого воїна така ж необхідна, як зброя і щит. Проходячи випробування з Фоліанту Звитяги, паладини засвоюють: сила без непохитної обітниці захищати безпорадних — порожня. Справжня небезпека гартує їх, тож коли на Альянс упаде темрява, його захисники встоять, а не зламаються."}},faq={{q="Навіщо потрібен Фоліант Звитяги?",a="Фоліант Звитяги — обряд посвяти для молодих паладинів Альянсу. Його задумали наставники Святого Світла, щоб переконатися: перш ніж посвячений просунеться в ордені, він має справжню мужність і безкорисливе прагнення захищати беззахисних.",al={"що таке фоліант звитяги","навіщо фоліант звитяги","чому робити фоліант звитяги"}},{q="Хто посилає паладинів на це випробування?",a="Зазвичай посвячених кличуть на це випробування старші паладини в столицях Альянсу, як-от Дуторіан Ралл у Соборі Світла в Стормвінді чи Тіза Баттлфордж у Залі Таїнств в Айронфорджі.",al={"хто дає фоліант звитяги","дає фоліант звитяги","хто починає фоліант звитяги"}},{q="Куди веде це випробування?",a="Перший поклик відкриває низку окремих завдань, що перевіряють рішучість паладина й ведуть його в поле назустріч справжній небезпеці, щоб захистити королівство й невинних.",al={"що після фоліанта звитяги","продовження фоліанта звитяги","ланцюжок фоліанта звитяги"}},{q="Чому для паладинів так важить хоробрість?",a="Святе Світло відгукується на віру й волю. Перед нездоланним жахом, як-от демони чи дракони, страх може зламати дух воїна; мужність же дає паладинові змогу й у найскрутніші часи лишатися непохитним щитом для інших.",al={"чому звитяга","чому хоробрість важлива паладинам"}},{q="Чи проходять паладини-дворфи й паладини-люди однакове випробування?",a="Паладини-дворфи навчаються в Айронфорджі, а люди — в Соборі Світла в Стормвінді, проте обидві традиції шанують ті самі головні чесноти: мужність, обов'язок і захист беззахисних під покровом Світла.",al={"чи різне для дворфів","фоліант звитяги айронфордж","фоліант звитяги стормвінд"}},{q="Яких головних уроків навчає випробування?",a="Випробування зосереджене на трьох основних обов'язках: незламна хоробрість попри будь-які шанси, діяльний захист слабких від лиха й віра, що не хитається перед жахом.",al={"уроки фоліанта звитяги","чого вчить фоліант"}}},fp="17,264,24.434.0,20.366.0,41.255.0,35.201.0,27.195.0,50.234.0,52.205.0,44.197.0"}
P.entries["quest:1795"] = {n="Зв'язування",s="«Зв'язування» — завершальний обряд для чорнокнижників, які прагнуть командувати мисливцем Скверни. Під наглядом загадкового заклинача Страгада Фарсана на кручах над Раджетом обряд за допомогою відновленого Фоліанта Кабали вириває лютого демонічного хижака з Нижнього Світу й змушує його скоритися в двобої.",h="«Зв'язування» — завершальний обряд для чорнокнижників, які прагнуть командувати мисливцем Скверни.",kw={"зв'язування","мисливець скверни","страгад фарсан","фоліант кабали","раджет","чорнокнижник"},ang={["class:Warlock"]="Підкорення мисливця Скверни — важлива віха для кожного чорнокнижника: він отримує особливого антимагічного хижака, здатного пожирати чари й знешкоджувати ворожих заклиначів.",["faction:Alliance"]="Чорнокнижників Альянсу посилають із безпечного Стормвінда за море, до суворого нейтрального притулку Раджета, щоб під пильним оком Страгада завершити небезпечний обряд виклику.",["faction:Horde"]="Знавці темних мистецтв з Орди вирушають у серце Пусток, щоб довести свою владу над Нижнім Світом, і стають перед Страгадом на нейтральній землі, щоб підкорити гончака."},sec={{t="Коло кабали",b="На кручах над гоблінським портом Раджет Страгад Фарсан проводить одні з найнебезпечніших демонологічних випробувань у Калімдорі. Коли чорнокнижник збере розрізнені уламки й реагенти, потрібні, щоб скласти прадавній Фоліант Кабали, Страгад готує місце для зв'язування. Він накреслює внутрішній знак стримування, а його вірні учні через зачаровані жезли замикають зовнішнє коло, щоб жахіття, які з'являться, лишилися відрізаними від поселення внизу."},{t="Підкорення мисливця",b="Читаючи заклинання з Фоліанта Кабали, новачок прокладає міст у Викривлений Нижній Світ. Мисливці Скверни — ненажерливі демонічні гончаки, що від природи прагнуть магічної сили й бенкетують магічною енергією. Викликаного звіра не вмовиш солодкими словами й не зачаруєш лагідно: його треба силою здолати й зламати в бою, і лише тоді він визнає чорнокнижника своїм законним господарем. Вистоявши в сутичці, заклинач доводить, що готовий спрямовувати цього гончака проти ворожих магів."}},faq={{q="Яка мета цього ритуалу?",a="Ритуал дає змогу чорнокнижникові закликати мисливця Скверни й підкорити його своїй волі. Читаючи з відновленого Фоліанта Кабали в колі закликання Страгада Фарсана, чорнокнижник витягає демонічного хижака з Нижнього Світу й перемагає його в бою, здобуваючи його вічну службу.",al={"навіщо це завдання","мета завдання мисливця скверни","мета зв'язування"}},{q="Хто такий Страгад Фарсан?",a="Страгад Фарсан — досвідчений чорнокнижник-людина, що працює у вежі над Раджетом у Пустках. Через його глибокі знання темних мистецтв закликання наставники і з Альянсу, і з Орди потай посилають до нього своїх найперспективніших учнів опановувати складні обряди підкорення.",al={"хто такий страгад","страгад фарсан лор","хто дає завдання страгад"}},{q="Чому чорнокнижник мусить убити демона, а не просто поневолити його?",a="Мисливець Скверни — агресивний хижак, що пожирає магію, і визнає лише цілковиту владу. Ритуал вимагає здолати демона в рукопашному й магічному бою, щоб зламати його лють і закарбувати свою владу на його духові, — тоді він коритиметься й надалі, щойно його закличуть.",al={"чому вбити мисливця скверни","чи можна поневолити мисливця скверни","бій з мисливцем скверни"}},{q="Чи можуть чорнокнижники і з Орди, і з Альянсу провести тут цей ритуал?",a="Так. Попередні завдання з відновлення Фоліанта Кабали різняться залежно від фракції, але зрештою і чорнокнижників Альянсу, і чорнокнижників Орди скеровують до Страгада Фарсана над Раджетом для останнього закликання.",al={"чи лише для орди","чи лише для альянсу","хто отримує це завдання"}},{q="Що буде, якщо мисливець Скверни переможе закликача?",a="Якщо закликач полягне, демона буде вигнано назад у Нижній Світ, а ритуал зазнає невдачі. Проте Страгад дозволяє чорнокнижникам, які пережили поразку, отримати новий примірник Фоліанта Кабали й повторити закликання, коли вони як слід підготуються.",al={"що якщо я помру","провал зв'язування","чи можна повторити ритуал"}},{q="Чим мисливці Скверни відрізняються від інших демонів?",a="Мисливці Скверни — демонічні пси, що полюють, відчуваючи магічні випромінювання. Замість покладатися лише на грубу силу чи закляття тіні, вони вміють винюхувати чаклунство, пожирати чинні чари й зривати закляття ворожих чарівників, тож вони — безцінні супутники проти суперників-магів.",al={"що робить мисливець скверни","мисливець скверни лор","чому мисливці скверни"}}},fp="11,301,18.506.0,22.507.0,35.285.0,22.302.0,66.283.0,62.227.0,51.257.0,54.293.0"}
P.entries["quest:1796"] = {n="Складники Зачарованої Золотої Кривавої Роби",s="Менара Войдрендер доручає молодим чорнокнижникам у Пустках роздобути Робу Аркани — основу для могутнього магічного вбрання. Це перший крок до створення Зачарованої Золотої Кривавої Роби: так готують надійну посудину, здатну витримати темні чари.",h="Менара Войдрендер доручає молодим чорнокнижникам у Пустках роздобути Робу Аркани — основу для могутнього...",kw={"зачарована золота кривава роба","роба аркани","менара войдрендер","чорнокнижник","кравецтво","пустки"},ang={["class:Warlock"]="Виготовлення Зачарованої Золотої Кривавої Роби — важливий обряд посвяти для чорнокнижників: воно вчить, що могутні артефакти творять на міцній, ретельно підготовленій основі.",["profession:Tailoring"]="Це завдання вимагає рідкісного вміння вправного кравця, що опанував викрійку Роби Аркани і працює з павучим шовком та сувій за сувоєм тонкого шовку.",["race:Orc"]="Для оркських чорнокнижників, що працюють у тіні демонічного минулого свого народу, збирання матеріалів для витонченої роби — тихіше опанування енергії Скверни, подалі від цікавих очей.",["race:Undead"]="Знавці темних мистецтв з Відступників часто мандрують аж до вибілених сонцем Пусток, щоб перейняти прийоми Менари й зміцнити свої крихкі смертні оболонки проти власного мінливого мистецтва."},sec={{t="Посудина магії",b="Перш ніж прив'язати темну магію до тканини, саме вбрання має бути гідним такої сили. Менара Войдрендер велить чорнокнижникам, що прагнуть більшої могутності, роздобути Робу Аркани. Як пояснює Менара, міць будь-якої магічної реліквії залежить від майстерності, рідкісності й праці, вкладених у її основу. Звичайне лахміття розлізлося б під тиском глибоких чарів, тож без тонко зшитого, сприйнятливого вбрання не обійтися."},{t="Ремесло й честолюбство",b="Менара особливо захоплюється тими, хто здатен зшити вбрання власноруч, але безжальне честолюбство цінує вище за гордість. Чи чорнокнижник сам шиє шовк, чи замовляє роботу в здібного майстра, чи торгується на ринку, — наслідок однаковий: готова роба, яку можна перетворити на особливе знаряддя влади над Скверною."}},faq={{q="Чому Менарі Войдрендер потрібна саме Роба Аркани?",a="Чари найвищого рівня потребують одягу, витканого з винятковою майстерністю й з рідкісних матеріалів. Менара бере Робу Аркани як чисту, сприйнятливу основу, здатну втримати нестійкі магічні сили, які невдовзі в неї вплетуть.",al={"чому роба аркани","чому саме ця роба","навіщо роба"}},{q="Де знайти Менару Войдрендер?",a="Менара Войдрендер живе в гоблінському порту Раджет у Пустках, де навчає чорнокнижників, які прагнуть удосконалити своє ремесло й виготовити особливе спорядження.",al={"місце менари войдрендер","де менара","де менара войдрендер"}},{q="Чи треба самому шити Робу Аркани?",a="Ні. Менара шанує відданість тих, хто шиє одяг власноруч, але прийме й робу, здобуту обміном чи куплену в інших майстрів. Для чорнокнижника годиться будь-який практичний спосіб роздобути цю основу.",al={"чи треба шити самому","чи можна купити робу","чи потрібне кравецтво"}},{q="Звідки береться викрійка Роби Аркани?",a="Викрійка — рідкісна здобич, що випадає здебільшого з культистів і темних чарівників, як-от закликачів Порожнечі з Темного Пасма біля Вежі Альталакса на Темному Узбережжі чи зачарувальників Дефіас у Сутінколіссі.",al={"викрійка роби аркани","як отримати викрійку","місце рецепта кравця"}},{q="Що стається з Робою Аркани, коли її віддати?",a="Менара забирає робу як сировину для подальшого ритуалу наснаження. Якщо на момент завершення завдання роба на вас, вона знімає її одразу, і ви лишаєтеся без нагрудного вбрання, доки не завершите наступні кроки.",al={"чи втрачу я робу","роба зникає","що з робою"}},{q="Що таке Зачарована Золота Кривава Роба?",a="Це особливе вбрання для чорнокнижників середнього рівня. Скріплене темними складниками й захисними чарами, воно зміцнює стійкість чарівника й запаси темної енергії.",al={"що таке кривава роба","кривава роба лор","зачарована золота кривава роба"}}},fp="43,292,18.443.0,18.366.0,61.234.0,35.159.0,47.225.0,53.191.0,58.255.0,37.182.0"}
P.entries["quest:1798"] = {n="У пошуках Страгада",s="«У пошуках Страгада» — завдання для чорнокнижників Альянсу, що посилає знавців темних мистецтв зі Стормвінда за Велике море, у Пустки. Там, неподалік від гоблінського порту Раджет, вони шукають знань Страгада Фарсана, щоб навчитися викликати мисливців Скверни. Це завдання знаменує перехід чорнокнижника на вищі, небезпечніші щаблі підкорення демонів.",h="«У пошуках Страгада» — завдання для чорнокнижників Альянсу, що посилає знавців темних мистецтв зі Стормвінда...",kw={"у пошуках страгада","страгад фарсан","ґакін зв'язувач темряви","мисливець скверни","чорнокнижник","раджет"},ang={["class:Warlock"]="Це завдання — важлива віха в зростанні чорнокнижника: від простих демонів і сукубів до хитрого мисливця Скверни, що пожирає магію.",["faction:Alliance"]="Для заклиначів Альянсу ця подорож — довгий шлях за Велике море, просто в суворе серце Калімдору, де панує Орда."},sec={{t="Поклик за море",b="У підземному притулку під «Зарізаним Ягням» у Стормвінді Ґакін Зв'язувач Темряви наглядає за розвитком молодих чорнокнижників. Та щоб опанувати хижого мисливця Скверни, потрібні матеріали, реліквії й обряди, яких скромний підвал у Кварталі магів дати не може. Бачачи, що учень набрав сили, Ґакін відсилає його геть із безпечного королівства до Калімдору — у подорож, що поєднує таємні кола людської демонології на різних континентах."},{t="Самітник із Раджета",b="Мета — посушливі пагорби над гоблінською гаванню Раджет. Там живе Страгад Фарсан, людський чорнокнижник і рівня Ґакіна в їхній таємній кабалі. Нейтральна земля дає Страгадові відносну свободу від пильних очей магістратів Альянсу, церковних інквізиторів і вартових Орди. Його присутність у Пустках — опора для честолюбних заклиначів, готових вирвати владу над демонами, що висмоктують ману."}},faq={{q="Хто посилає шукати Страгада?",a="Ґакін Зв'язувач Темряви, наставник чорнокнижників, що ховається в крипті під «Зарізаним Ягням» у Кварталі магів Стормвінда, відправляє вас у цю подорож, коли ви готові навчитися закликати мисливця Скверни.",al={"хто дає пошуки страгада","хто дає завдання","ґакін"}},{q="Де знайти Страгада Фарсана?",a="Страгад Фарсан живе в Пустках, на висотах над гоблінським портовим містечком Раджет.",al={"місце страгада","де страгад","знайти страгада"}},{q="Чому чорнокнижникові Альянсу треба їхати аж у Пустки?",a="У Стормвінді Ґакінові бракує особливих реагентів і знань, щоб провести обряди закликання мисливця Скверни. Страгад Фарсан має потрібні знання й матеріали, а оселився він на нейтральній землі Раджета, подалі від чужих очей.",al={"чому йти в пустки","чому калімдор","чому ретчет"}},{q="До якого вміння веде це завдання?",a="Це завдання — перший крок у ланцюжку, що веде до Фоліанта Кабали й ритуалу підкорення, потрібного, щоб закликати супутника — мисливця Скверни.",al={"для якого улюбленця","що я отримаю","завдання мисливця скверни"}},{q="Чи ворожий Страгад Фарсан до Орди?",a="Ні. Страгад живе на нейтральній гоблінській землі й навчає чорнокнижників і Альянсу, і Орди, які прагнуть таємниць закликання мисливців Скверни, та підтримує зв'язки з різними кабалами.",al={"чи страгад лише для альянсу","страгад орда"}},{q="Що буде після розмови зі Страгадом?",a="Привітавшись із вами, Страгад доручає зібрати потрібні складники для ритуалу підкорення — так починається кількаетапний ланцюжок завдань про Фоліант Кабали.",al={"наступне завдання","що після пошуків страгада","фоліант кабали"}}},fp="15,369,24.480.0,21.455.0,30.202.0,32.115.0,71.262.0,47.147.0,39.195.0,40.170.0"}
P.entries["quest:18"] = {n="Братство злодіїв",s="«Братство злодіїв» — одне з перших завдань, яке дає Помічник Віллем біля Абатства Нортшира. Він посилає молодих новобранців Альянсу за східну річку, щоб відтіснити зграю розбійників, відому як Братство Дефіас. Зібрані червоні бандани з мішковини — відмітний знак злодіїв — стають для влади Стормвінда першим речовим доказом організованої присутності цієї групи в долині.",h="«Братство злодіїв» — одне з перших завдань, яке дає Помічник Віллем біля Абатства Нортшира.",kw={"братство дефіас","бандани","помічник віллем","нортшир","розбійники","новобранці"},ang={["class:Rogue"]="Зустріч із Дефіас дає розбійникам-новачкам уявлення про те, як організовані злочинні мережі діють у тіні людських земель.",["faction:Alliance"]="Влада Стормвінда покладається на щойно прибулих новобранців Альянсу, щоб підтримувати мир у Нортширі, поки регулярне військо королівства розтягнуте до краю.",["race:Human"]="Для людей, що починають вишкіл у Нортширі, сутичка з Дефіас — перше суворе нагадування про те, що безпека Королівства Стормвінд руйнується зсередини."},sec={{t="Бандити в долині",b="Долину Нортширу довго вважали безпечним прихистком у Лісі Елвінн: її охороняла варта Стормвінда, а саму долину присвятили вишколу новобранців і кліриків Святого Світла. Останнім часом, однак, порядок на околицях похитнувся. Волоцюги й злодії перейшли східну річку, никають біля лісу й ставлять невеликі табори просто під носом в абатства. Помічник Віллем, що відповідає за лад у долині, розуміє: місцева варта не має людей, щоб пильнувати кожен закуток без допомоги добровольців."},{t="Багряний знак",b="Від звичайних розбійників цих злочинців відрізняють злагодженість і однакове вбрання. Вони звуть себе Братством Дефіас і засвідчують свою належність до нього червоними банданами з мішковини, якими закривають обличчя. Наказавши новобранцям полювати на розбійників і забирати їхні маски, Помічник Віллем прагне стримати їхній зухвалий наступ і водночас зважити, як глибоко Дефіас проникли в серце королівства."}},faq={{q="Хто такі Братство Дефіас?",a="Братство Дефіас — організоване угруповання розбійників і злочинців, що нині діє по всьому Лісу Елвінн і Вестфолу. Влада Нортширу спершу вважає їх просто зухвалими злодіями, але вони носять однакові червоні маски з мішковини й діють під злагодженим проводом.",al={"хто такі дефіас","що таке братство дефіас","дефіас лор"}},{q="Чому Помічник Віллем просить допомоги в новобранців, а не в Армії Стормвінда?",a="Армія Стормвінда й міська варта розпорошені по всьому королівству. Заворушення в сусідніх краях наростають, а в Стормвінді керівництву й так непросто, тож місцеві помічники шерифа мусять покладатися на завзятих добровольців і новобранців, щоб вигнати бандитів, які підбираються дедалі ближче.",al={"чому віллему потрібна допомога","де вартові стормвінда","чому немає армії"}},{q="Звідки беруться ці злодії?",a="У Нортширі злодії зібралися за річкою, на схід від абатства, і никають околицями місцевих хуторів і таборів біля виноградника.",al={"де бандити","місце дефіас нортшир"}},{q="Чому злодії носять червоні пов'язки з мішковини?",a="Червона пов'язка з мішковини — спільний знак Братства Дефіас: вона приховує обличчя й водночас показує належність до інших злочинців, що діють по всіх людських землях.",al={"чому червоні пов'язки","значення червоних масок","червона мішковина"}},{q="Що буде після цього завдання?",a="Помічник Віллем і місцеві швидко розуміють, що загроза від бандитів сягає глибше в Нортшир, тож новобранці допомагають Міллі Осворт з її знищеним урожаєм і вистежують ватажка на ім'я Ґаррик Педфут.",al={"що далі","після братства злодіїв"}},{q="Чи знає Помічник Віллем, хто очолює Дефіас?",a="Поки що Віллем не уявляє справжніх масштабів організації. Він знає лише, що вони звуть себе Братством Дефіас, і підозрює, що їхня поява біля абатства не віщує Стормвіндові нічого доброго.",al={"чи віллем знає венкліфа","хто очолює дефіас нортшир"}}},fp="22,393,21.543.0,17.440.0,31.267.0,82.264.0,36.162.0,44.197.0,41.217.0,45.203.0"}
P.entries["quest:180"] = {n="Розшукується: лейтенант Фанґор",s="Розшукується: лейтенант Фанґор — місцеве оголошення про нагороду, яке Магістрат Соломон вивісив у Лейкширі. Воно закликає шукачів пригод вистежити Лейтенанта Фанґора, лютого ватажка гнолів Тіньової Шкури, що заполонюють Гори Редріджу. Його смерть — прямий удар по чаклунові-ренегату Морґанту, якому служать гноли.",h="Розшукується: лейтенант Фанґор — місцеве оголошення про нагороду, яке Магістрат Соломон вивісив у Лейкширі.",kw={"розшукується: лейтенант фанґор","лейтенант фанґор","гноли Тіньової Шкури","морґант","магістрат соломон","лейкшир"},ang={["faction:Alliance"]="Лейкшир — важливий бастіон Альянсу в Редріджі; знищивши Фанґора, ви не дасте поселенню опинитися в цілковитій ізоляції.",["race:Human"]="Люди-захисники в Редріджі на власній шкурі відчувають байдужість Стормвінда, тож особиста боротьба з ватажками гнолів стає для них питанням виживання рідного краю."},sec={{t="Містечко в облозі",b="Лейкшир у відчайдушному становищі. Військо Стормвінда розпорошене, король Варіан Рінн загадково зник, і Верховний Лорд Болвар Фордрагон лишив прикордонні поселення на кшталт Редріджу самим дбати про себе. Клан гнолів Тіньової Шкури дедалі зухвалішає: грабує торгові шляхи, палить хутори й підступає під самі околиці містечка. Магістрат Соломон покладається на оголошення про нагороди, щоб залучити клинки найманців туди, куди не йдуть королівські солдати."},{t="Лейтенант Морґанта",b="Лейтенант Фанґор — не просто звір-мародер: він виконує волю Морґанта, темного чарівника-ренегата, що зачаївся в пагорбах Редріджу. Під командуванням Фанґора гноли Тіньової Шкури завдають злагоджених ударів, а не б'ються як розрізнені падальники, і погрожують зовсім відрізати Лейкшир від Лісу Елвінн. Відрубана лапа Фанґора стане для Магістрата Соломона доказом того, що грубий авангард Морґанта розбито."}},faq={{q="Хто такий Лейтенант Фанґор?",a="Лейтенант Фанґор — могутній ватажок гнолів з клану Тіньової Шкури, що живе в Редріджі. Він керує загонами гнолів-нападників і втілює волю Морґанта — темного чаклуна, що загрожує Лейкширу.",al={"лейтенант фанґор","хто такий фанґор","фанґор лор"}},{q="Хто оголосив винагороду за Лейтенанта Фанґора?",a="Винагороду оголосив Магістрат Соломон, очільник Лейкшира, який намагається вберегти околиці Редріджу від ворожих гнолів і темних чаклунів.",al={"хто призначив винагороду","хто хоче смерті фанґора","магістрат соломон фанґор"}},{q="Чому Стормвінд не посилає солдатів, щоб упоратися з гнолами?",a="Стормвінд паралізований раптовим зникненням короля Варіана Рінна й внутрішніми чварами. Верховний Лорд Болвар Фордрагон і Дім Вельмож відмовилися посилати загони регулярного війська до окраїнних містечок на кшталт Лейкшира, тож Магістрат Соломон мусить наймати шукачів пригод.",al={"чому немає вартових стормвінда","де солдати стормвінда","чому армія не допомагає"}},{q="Який доказ потрібен, щоб отримати винагороду?",a="Магістрат Соломон вимагає відрубану лапу Лейтенанта Фанґора як речовий доказ того, що воєводу Тіньової Шкури убито.",al={"доказ фанґора","лапа фанґора","який предмет здати"}},{q="Хто такий Морґант і чому Фанґор йому служить?",a="Морґант — чаклун-ренегат з людей, що практикує темну магію у вежі в Горах Редріджу. Він підкорив своїй волі гнолів Тіньової Шкури, а Лейтенант Фанґор став його виконавцем, що тероризує довколишні села.",al={"хто такий морґант","чому гноли слідують морганту","фанґор морґант"}},{q="Хто такі гноли Тіньової Шкури?",a="Клан Тіньової Шкури — люте плем'я гнолів, що населяє скелі й ліси Гір Редріджу. Відомі агресивністю й жорстокими засідками, вони роками не дають спокою поселенцям Лейкшира.",al={"клан тіньової шкури","гноли редріджа","тіньова шкура лор"}}},fp="26,333,18.465.0,21.441.0,26.209.0,45.174.0,57.282.0,43.127.0,48.222.0,31.219.0"}
P.entries["quest:1801"] = {n="Фоліант Кабали",s="Це завдання посилає чорнокнижників Орди з табору Страгада Фарсана в Пустках до Андерсіті на пошуки давніх демонологічних знань. Щоб викликати й підкорити мисливця Скверни, новачок мусить відшукати загублений Фоліант Кабали, почавши з картографа на ім'я Джора Аннісон. Це важливий крок до опанування вищих демонічних викликів.",h="Це завдання посилає чорнокнижників Орди з табору Страгада Фарсана в Пустках до Андерсіті на пошуки давніх...",kw={"фоліант кабали","джора аннісон","страгад фарсан","андерсіті","мисливець скверни","чорнокнижник"},ang={["class:Warlock"]="Цей обряд посвяти обов'язковий для чорнокнижників Орди, які хочуть приборкати мисливця Скверни: доведеться мандрувати між Калімдором і Східними Королівствами, щоб зібрати забуті обрядові складники.",["faction:Horde"]="Це завдання показує співпрацю темних заклиначів Калімдору з окультними вченими-Відступниками, що живуть під руїнами Лордерону."},sec={{t="Полювання на давні знання",b="Виклик мисливця Скверни — не дрібний фокус магії Скверни: ці хижі звірі пожирають магічну енергію й опираються звичайним колам виклику. Страгад Фарсан пояснює, що для цього новачкові потрібна допомога особливих кіл і давній гримуар, відомий як Фоліант Кабали. Написаний першим орденом чорнокнижників, який без сторонньої допомоги підкорив мисливця Скверни, він містить точні обряди й печаті, потрібні, щоб поневолити такого небезпечного демона."},{t="Картограф з Андерсіті",b="Оскільки примірники Фоліанта Кабали давно загубилися для чорнокнижників Калімдору, Страгад відсилає учня за море, до Джори Аннісона в Андерсіті. Хоч той формально служить королівським картографом і складає мапи Лордерону, Аннісон має надзвичайно глибокі знання про давні й маловідомі тексти. Як зізнається сам Аннісон, просте ремесло мапника він зневажає й набагато більше прагне рідкісних історій, окультних оповідей і трактатів про темну магію."}},faq={{q="Що таке Фоліант Кабали?",a="Фоліант Кабали — рідкісний окультний гримуар, написаний першими чорнокнижниками, які самотужки закликали й підкорили мисливця Скверни. У ньому — точні настанови, захисні знаки й обряди, потрібні, щоб безпечно привести в Азерот одного з цих звірів, що пожирають магію.",al={"лор фоліанта кабали","що це за книга","фоліант кабали"}},{q="Чому Страгад Фарсан посилає до Андерсіті?",a="У Страгада та його учнів у Пустках немає примірника Фоліанта Кабали. Він знає, що Джора Аннісон, картограф з Андерсіті, знавець рідкісних і давніх книжок, і може підказати, де шукати втрачені сторінки чи томи.",al={"чому до андерсіті","страгад фарсан андерсіті","чому до джори"}},{q="Хто такий Джора Аннісон?",a="Джора Аннісон — учений з Відступників, що працює в Андерсіті. Офіційно він картограф і креслить мапи, але його справжня пристрасть — маловідомі тексти, некромантські трактати й давня література.",al={"хто така джора","джора аннісон лор"}},{q="Чому для закликання мисливця Скверни потрібна особлива книга?",a="Мисливці Скверни за природою живляться чародійською й магічною енергією, тож закликати їх крізь звичайні демонічні кола важко й небезпечно. Фоліант Кабали описує особливі запобіжники, потрібні, щоб підкорити такого звіра, перш ніж той пожере закликача.",al={"навіщо книга для мисливця скверни","чому мисливця скверни важко закликати"}}},fp="17,352,28.467.0,29.487.0,30.273.0,50.237.0,21.209.0,51.254.0"}
P.entries["quest:1802"] = {n="Фоліант Кабали",s="Це завдання доручає чорнокнижникові Альянсу розшукати розірвані половини єдиного у своєму роді гримуара — Фоліанту Кабали. Без утрачених сторінок із далеких земель не розгадати темних обрядів, потрібних, щоб скорити мисливця Скверни.",h="Це завдання доручає чорнокнижникові Альянсу розшукати розірвані половини єдиного у своєму роді гримуара —...",kw={"фоліант кабали","чорнокнижник","мисливець скверни","гримуар","гілсбред","тисяча голок","кентаври"},ang={["class:Warlock"]="Здобуття розірваних половин гримуара — обряд посвяти: він відкриває вам ритуали виклику, без яких не витягти мисливця Скверни з Нижнього Світу й не поневолити його.",["faction:Alliance"]="Чорнокнижники Альянсу покладаються на айронфорджських спільників на кшталт Крома Стаутарма, щоб вистежувати рідкісні демонічні реліквії на різних континентах і не накликати відкритої підозри церкви чи корони."},sec={{t="Розділений гримуар",b="Фоліант Кабали переписали лише в одному примірнику, і бурхлива історія не дала йому вціліти. Розірваний і сплюндрований, він розлетівся уривками в зовсім різні куточки світу. Одна частина — пошматований рукопис, видертий просто з палітурки, — якось перетнула море й опинилася в суворих каньйонах Калімдору, у руках кентаврійських кланів. Другу частину мали перевезти морем із берегів Лордерону до Каз Модану, але корабель затонув, так і не дійшовши до порту."},{t="Через море й каньйони",b="Щоб знову скласти гримуар, доведеться пройти крізь дві підступні небезпеки. Сторінки, загублені в морі, винесло на узбережжя Гілсбреду на захід від Саутшора: уламки й розмоклі реліквії там прибрали до рук прибережні мурлоки біля Шахти Лазурової Жили. А по посушливу половину доведеться пробратися до Твердині Розщепленого Копита в Тисячі Голок і спуститися глибоко в печери кентаврів, щоб дістати рукопис зі старовинної скрині. Лише коли обидві половини знову разом, Кром Стаутарм зможе оглянути втрачений текст, перш ніж той повернеться до Страгада Фарсана."}},faq={{q="Що таке Фоліант Кабали?",a="Це рідкісний, єдиний у своєму роді демонічний гримуар з таємними знаннями, потрібними чорнокнижникам. У ньому — складні заклинання й ритуали підкорення, без яких не закликати мисливця Скверни з Викривленого Нижнього Світу й не скорити його.",al={"лор фоліанта кабали","що це за книга","фоліант кабали"}},{q="Хто такий Кром Стаутарм і навіщо йому фоліант?",a="Кром Стаутарм — дворф з Айронфорджа, що поринув у вивчення рідкісних і забутих текстів. За те, що він підкаже чорнокнижникам Альянсу, куди потрапили вирвані частини фоліанта, він просить лише змоги особисто вивчити його вміст, коли їх повернуть.",al={"хто такий кром стаутарм","навіщо крому книга","кром стаутарм айронфордж"}},{q="Куди потрапили дві частини книги?",a="Запліснявілий Фоліант винесло на берег Гілсбреда на захід від Саутшора, біля Шахти Лазурової Жили, і його підібрали прибережні мурлоки. Подертий Манускрипт опинився на Калімдорі, у Твердині Розщепленого Копита, — схований у пошарпаній скрині глибоко в печері кентаврів у Тисячі Голок.",al={"де частини фоліанта","місця книги","місце подертого рукопису"}},{q="Чому фоліант узагалі розірвали?",a="Фоліант Кабали переписали лише раз. Колись у його темному минулому книгу навмисно зіпсували: великий шмат вирвали з оправи й вивезли на Калімдор, а решта загинула в морі під час фатальної подорожі до Гавані Менетіл.",al={"чому фоліант розірвали","хто зіпсував фоліант"}},{q="Хто такий Страгад Фарсан і до чого він тут?",a="Страгад Фарсан — досвідчений чорнокнижник, що живе біля Раджета в Пустках. Він посилає молодих закликачів по фоліант, щоб під його наглядом вони опанували обряди закликання й підкорення мисливця Скверни.",al={"хто такий страгад","страгад фарсан","зв'язок страгада"}},{q="Чому Запліснявілий Фоліант укритий морським брудом?",a="Книга була на борту корабля, що плив з узбережжя Лордерону до Гавані Менетіл і так туди й не дістався. Уламки корабля прибило до берега Гілсбреда, де вологі, запліснявілі сторінки зібрали прибережні мурлоки біля Шахти Лазурової Жили.",al={"чому запліснявілий фоліант мокрий","фоліант хілсбрада мурлоки"}}},fp="17,262,18.560.0,21.545.0,30.227.0,51.262.0,44.274.0,47.281.0,66.214.0,43.247.0"}
P.entries["quest:1803"] = {n="Фоліант Кабали",s="Це завдання доручає чорнокнижникам Орди возз'єднати розірвані половини давнього Фоліанта Кабали для Джори Аннісона в Андерсіті. Колись гримуар зберігали в королівстві Лордерон, але його розірвали, розкидали світом, а згодом і зовсім загубили. Щоб відшукати його вогкі й пошматовані рештки, доведеться ризикнути у ворожих водах Східних Королівств і в самому серці земель кентаврів у Калімдорі.",h="Це завдання доручає чорнокнижникам Орди возз'єднати розірвані половини давнього Фоліанта Кабали для Джори...",kw={"фоліант кабали","джора аннісон","запліснявілий фоліант","подертий манускрипт","твердиня розщепленого копита","тисяча голок","чорнокнижник"},ang={["class:Warlock"]="Повернути Фоліант Кабали — обряд посвяти для досвідченіших чорнокнижників: так ви збираєте втрачені таємні знання Лордерона, щоб розширити свій арсенал викликів.",["faction:Horde"]="Пошуки манускрипту ведуть вас каньйонами Тисячі Голок, де загони Орди із Застави Вільного Вітру безупинно воюють із місцевими кентаврами.",["race:Undead"]="Фоліант зберігався в Лордероні ще до падіння королівства, тож повернути його — означає повернути окультну спадщину з колишнього людського життя Відступників."},sec={{t="Розділений спадок",b="Колись Фоліант Кабали зберігався в бібліотеці старого королівства Лордерон. Ще до падіння королівства хтось навмисно зіпсував зловісний гримуар: вирвав мало не половину сторінок і розірвав книгу надвоє. Решту основного тексту мали відправити на південь, до дворфійських зал Айронфорджа, але доля розпорядилася інакше: корабель розбився об скелясте узбережжя на захід від Саутшора, і сторінки лишилися гнити на мілині під пильним оком мурлоків, що нишпорять у пошуках поживи."},{t="Розкиданий континентами",b="Зіпсована половина фоліанта забрела ще далі. Викрадена з Лордерона, вона дісталася аж до південного Калімдору й опинилася в грубих руках кентаврів Ґалак глибоко у Твердині Розщепленого Копита в Тисячі Голок. Щоб відновити повний текст, чорнокнижник мусить обшукати вогке узбережжя Гілсбреда в пошуках Запліснявілого Фоліанта й пробратися крізь пил і дикість кентаврських каньйонів по Подертий Манускрипт. Коли обидві частини складуть перед Джорою Аннісоном, легендарний темний текст знову стане єдиною книгою, яку можна прочитати."}},faq={{q="Що таке Фоліант Кабали?",a="Це чародійський і демонічний гримуар, який колись зберігався в столиці Лордерону. У ньому — складні ритуали чорнокнижників; книгу зіпсували й розділили на дві частини, які загубилися на двох різних континентах.",al={"лор фоліанта кабали","що це за книга","фоліант кабали"}},{q="Чому одна частина книги опинилася біля Саутшора?",a="Після того як книгу зіпсували, вцілілу частину в оправі мали передати вченим Айронфорджа. Проте корабель, що її віз, розбився біля берега на захід від Саутшора, і гримуар лишився серед місцевих мурлоків.",al={"чому саутшор","походження запліснявілого фоліанта","узбережжя на захід від саутшора"}},{q="Як сторінки потрапили до кентаврів у Тисячі Голок?",a="Приблизно половину сторінок вирвали з первісного фоліанта ще в Лордероні й потай вивезли. Через торгівлю, грабунок чи випадкові руки цей подертий манускрипт зрештою опинився глибоко в Твердині Розщепленого Копита, де кентаври Ґалак тримали його в скрині.",al={"чому кентаври мають сторінки","сторінки тисячі голок","спліттхуфи тримають книгу"}},{q="Хто такий Джора Аннісон?",a="Джора Аннісон — чорнокнижник з Відступників, що працює в Магічному Кварталі Андерсіті. Він допомагає молодим чорнокнижникам Орди відшукувати забуті, заборонені знання, щоб ті глибше опанували владу над демонічними силами.",al={"джора аннісон лор","хто така джора"}},{q="Хто взагалі зіпсував фоліант?",a="Хто це зробив, достеменно невідомо. Джора Аннісон і сам бідкається через цей вандалізм і дивується, хто міг скоїти таку мерзоту з текстом такої глибокої окультної сили.",al={"хто роздер книгу","хто вкрав сторінки","вандал фоліанта"}},{q="Що Джора робить із книгою, коли ви принесете обидві частини?",a="Отримавши і Запліснявілий Фоліант, і Подертий Манускрипт, Джора Аннісон з'єднує їх в один том і прочитує сторінки, готуючи вас до наступних кроків ваших демонічних обрядів.",al={"що буде після здавання","відновлений фоліант"}}},fp="17,405,16.528.0,27.563.1,30.206.0,44.241.0,62.248.0,21.210.0,43.189.0,64.204.0"}
P.entries["quest:1804"] = {n="Фоліант Кабали",s="Це завдання — остання підготовка для чорнокнижників Альянсу, що прагнуть командувати мисливцем Скверни. Склавши докупи розірваний Фоліант Кабали, чорнокнижник мусить зібрати жезли каналізування в орків Драконячої Пащі в Багнокраї й повернутися до Страгада Фарсана на кручах над Раджетом.",h="Це завдання — остання підготовка для чорнокнижників Альянсу, що прагнуть командувати мисливцем Скверни.",kw={"фоліант кабали","кром стаутарм","жезл каналізування","драконяча паща","багнокрай","мисливець скверни"},ang={["class:Warlock"]="Підкорення мисливця Скверни — визначальний обряд посвяти, що підносить чорнокнижника від простих угод із бісами й блукачами Порожнечі до влади над хижими демонами, створеними пожирати магію.",["faction:Alliance"]="Це завдання посилає заклиначів Альянсу мандрувати між Айронфорджем, туманними болотами Багнокраю й нейтральним гоблінським портом Раджет у Калімдорі.",["race:Dwarf"]="Навіть темні мистецтва покладаються на ретельне вміння зберігати старовину, яким славиться Зала Дослідників Айронфорджа, де Кром Стаутарм складає докупи зруйновані реліквії."},sec={{t="Неохоча передача",b="У Залі Дослідників Айронфорджа Кром Стаутарм ретельно зшив докупи обвуглені, зотлілі рештки Фоліанта Кабали. Не бажаючи розлучатися з такою рідкісною пам'яткою темної вченості, дворф-учений вимагає обіцянки майбутньої копії, перш ніж передати свіжий лист від Страгада Фарсана. Фоліант містить обряди, потрібні, щоб пробити шлях у Нижній Світ, але самого лише пергаменту для обряду замало."},{t="Викрадені реліквії Драконячої Пащі",b="Перш ніж учні Страгада зможуть допомогти зв'язати такого ненажерливого демона, як мисливець Скверни, їм потрібні фокусні знаряддя, щоб утримати викликані енергії. Кром скеровує чорнокнижника до Багнокраю, де заклиначі клану Драконячої Пащі носять жезли каналізування. Вирвані з рук ворожих орків, ці фокуси дадуть колу Страгада провідник, щоб утримати розлам під контролем."},{t="Назад у Пустки",b="Доставка і відновленого гримуара, і жезлів заклиначів до вежі Страгада високо над Раджетом завершує виснажливе збирання. Знаряддя здобуто, текст перекладено, і Страгад готується розпочати небезпечний обряд зв'язування — перевірити, чи має заклинач досить сили волі, щоб приборкати гончака Палаючого Легіону."}},faq={{q="Навіщо Страгадові жезли спрямування?",a="Закликати й підкорити мисливця Скверни надто бурхлива справа для чорнокнижника-одинака без опори. Учні Страгада мусять підтримувати й фокусувати коло закликання під час ритуалу, а ці жезли спрямовують і врівноважують потрібну енергію, щоб портал не завалився й не вийшов з-під контролю.",al={"навіщо жезли спрямування","призначення жезлів спрямування","для чого жезли"}},{q="Де знайти жезли спрямування?",a="Жезли мають при собі орки-чаклуни з клану Драконячої Пащі, що живуть у Багнокраї, — особливо довкола боліт і руїн, які вони захопили.",al={"де взяти жезли спрямування","хто дропає жезли спрямування","місце жезлів спрямування"}},{q="Чому Кром Стаутарм долучився до ритуалу чорнокнижників?",a="Кром Стаутарм — майстер-дослідник з Айронфорджа, що має особливі навички, щоб перекладати, зберігати й фізично відновлювати давні пошкоджені рукописи. Захоплення рідкісними старожитностями спонукало його відновити зіпсовані сторінки Фоліанта Кабали.",al={"чому кром","чому дворф з айронфорджа допомагає чорнокнижнику","кром стаутарм чорнокнижник"}},{q="Що буде, коли віддати фоліант і жезли Страгадові?",a="Страгад одразу пускає зібране в діло й починає ритуал підкорення на вершині своєї вежі, де вам доведеться власноруч зійтися із закликаним мисливцем Скверни й скорити його.",al={"що буде далі","наступне завдання після фоліанта кабали","що робить страгад"}},{q="Хто такий Страгад Фарсан?",a="Страгад Фарсан — могутній чорнокнижник, що працює у відлюдній вежі на кручах над портовим містечком Раджет у Пустках. Досвідчені практики з усього Калімдору й Східних Королівств визнають його майстерність у демонології.",al={"страгад фарсан лор","хто такий страгад","чоловік над ретчетом"}},{q="Чи користується Фоліантом Кабали й Орда?",a="Чорнокнижники Орди проходять власну версію обрядів Фоліанта Кабали, але їхні сліди ведуть до інших людей на Калімдорі та в Андерсіті, а не до Крома Стаутарма в Айронфорджі.",al={"орда фоліант кабали","чи орки виконують це завдання"}}},fp="17,278,19.436.0,30.375.0,19.338.1,41.284.0,39.144.0,51.268.0,55.165.1,22.242.0,51.209.0"}
P.entries["quest:1805"] = {n="Фоліант Кабали",s="Це завдання — останній підготовчий етап на шляху чорнокнижника Орди до виклику мисливця Скверни й влади над ним. Допомігши Джорі Аннісону відновити давній Фоліант Кабали, знавець темних мистецтв мусить вирушити на ворожу землю, щоб здобути три жезли каналізування, а тоді принести складники Страгадові Фарсану в Раджет.",h="Це завдання — останній підготовчий етап на шляху чорнокнижника Орди до виклику мисливця Скверни й влади над...",kw={"фоліант кабали","відновлений фоліант","жезл каналізування","драконяча паща","джора аннісон","страгад фарсан"},ang={["class:Warlock"]="Це випробування перевіряє вашу рішучість здобути небезпечні обрядові складники на ворожих землях і доводить, що вам вистачить знань і відваги, щоб підкорити хижого мисливця Скверни.",["faction:Horde"]="Ренегати Драконячої Пащі в Багнокраї лишаються запеклими ворогами Орди Тралла, тож силою відібрати в них жезли каналізування — подвійна перемога для Орди.",["race:Orc"]="Розправа з орками-ренегатами Драконячої Пащі в Багнокраї — суворе нагадування про темний, нерозкаяний шлях, який Орда так прагнула залишити позаду.",["race:Undead"]="Наукова праця Джори Аннісона в Андерсіті відбиває традицію чорнокнижників-Відступників розбирати заборонені магічні тексти заради практичної магічної переваги."},sec={{t="Таємниці Відновленого фоліанта",b="В Андерсіті вчений-Відступник Джора Аннісон вивчає уламки знайденого Фоліанта Кабали, складаючи докупи його моторошні уривки. Задоволений рідкісною інтелектуальною здобиччю, Джора передає нагальне розпорядження від Страгада Фарсана. Щоб зв'язати демонічного хижака на кшталт мисливця Скверни, самих знань замало: чорнокнижник мусить мати точні знаряддя сили, здатні зосередити буйну демонічну енергію в колі зв'язування."},{t="Вилазка в Багнокрай",b="Страгадові потрібні три жезли каналізування — особливі провідники, які носять орки-ренегати з клану Драконячої Пащі. Далеко від серця земель Орди ці орки живуть серед руїн Табору Анґерфанґ у драговинах Багнокраю. Щоб їх вистежити, доведеться ступити на спірні землі, де панують ворожі рештки клану, які зневажають сучасну Орду так само, як охоче вирізають дослідників Альянсу."},{t="Повернення до Раджета",b="Зі здобутими жезлами й Відновленим фоліантом чорнокнижник повертається за море до вежі Страгада Фарсана над Раджетом. Страгад зустрічає заклинача з похмурим задоволенням. Складники для обряду виклику зібрано — усе готово до небезпечного випробування волі в сутичці з неприборканим звіром Викривленого Нижнього Світу."}},faq={{q="Яка мета цього завдання?",a="Це третій крок у ланцюжку завдань для чорнокнижників Орди, які вчаться закликати мисливця Скверни. Треба доставити відновлений Фоліант Кабали й три жезли спрямування Страгадові Фарсану, що живе над Раджетом.",al={"навіщо це завдання","мета завдання","для чого фоліант кабали"}},{q="Хто такий Джора Аннісон?",a="Джора Аннісон — чорнокнижник і вчений з Відступників, що працює в Магічному Кварталі Андерсіті. Він вивчає таємні й темні тексти й допомагає іншим практикам, складаючи докупи розірвані гримуари на кшталт Фоліанта Кабали.",al={"хто така джора","джора аннісон лор"}},{q="Навіщо потрібні жезли спрямування?",a="Щоб закликати й скорити мисливця Скверни, потрібен точний надприродний контроль. Жезли — фокусувальні провідники, що врівноважують і формують коло закликання, аби чорнокнижник скорив демона, а не сам став його здобиччю.",al={"навіщо жезли спрямування","призначення жезлів"}},{q="Де шукати орків Драконячої Пащі для цього завдання?",a="Клан Драконячої Пащі утримує Табір Анґерфанґ у Багнокраї — землях Альянсу за морем, у Каз Модані. Жадані жезли спрямування носять саме їхні кістяні вартові.",al={"де орки драконячої пащі","драконяча паща вологі землі","табір ангерфанґ"}},{q="Хто такий Страгад Фарсан?",a="Страгад Фарсан — впливовий чорнокнижник-людина, союзник темних чаклунів Орди, що працює у відлюдній вежі на кручах над гоблінським портом Раджет у Пустках.",al={"хто такий страгад","страгад фарсан ретчет"}},{q="Що буде після цього завдання?",a="Ця доставка веде просто до завдання «Зв'язування», де Страгад наказує чорнокнижникові накреслити коло закликання й зійтися в магічному бою із закликаним мисливцем Скверни, щоб скорити звіра.",al={"що далі","наступне завдання після фоліанта"}}},fp="17,320,33.453.0,25.411.0,17.365.1,34.199.0,21.231.0,34.222.0,52.199.0,22.192.0,41.191.1"}
P.entries["quest:1806"] = {n="Випробування праведності",s="Випробування праведності завершується біля кузні Джордана Стілвелла поза Айронфорджем у Дун Мороґу. Зібравши небезпечні складники по всіх Східних Королівствах і Калімдорі, паладин чекає, поки коваль створює могутній бойовий молот. Це знаменує перехід учня в визнаного захисника Світла.",h="Випробування праведності завершується біля кузні Джордана Стілвелла поза Айронфорджем у Дун Мороґу.",kw={"випробування праведності","кулак верігана","бош веріган","джордан стілвелл","паладин","бойовий молот","айронфордж"},ang={["class:Paladin"]="Цей обряд посвяти винагороджує ваші небезпечні мандри далекими землями Кулаком Верігана — знаковою зброєю, присвяченою обстоюванню праведності.",["profession:Blacksmithing"]="Спостерігати за Джорданом Стілвеллом біля ковадла — бачити, як майстерність може вкласти святе призначення в сиру сталь і здобуті матеріали.",["race:Dwarf"]="Викуваний тут молот увічнює пам'ять Боша Верігана, шанованого дворфійського паладина, який утілював стійкість Каз Модану."},sec={{t="Данина коваля",b="Майстер-коваль Джордан Стілвелл працює біля воріт Айронфорджа. Хоч він і зізнається в дрібці заздрості до мандрівних паладинів, він глибоко пишається тим, що підтримує справу своїм молотом і ковадлом. Коли йому приносять рідкісні матеріали, зібрані в тіньових криптах, затонулих руїнах і небезпечних копальнях, Стілвелл виконує обіцянку й кує зброю, гідну справжнього захисника."},{t="Спадщина Боша Верігана",b="Готовий бойовий молот охрещено Кулаком Верігана на честь Боша Верігана, шанованого дворфійського паладина й близького особистого друга Джордана Стілвелла. Передаючи цю священну зброю в руки молодого захисника від себе й від дружини, Стілвелл дбає, щоб пам'ять і доблесть його полеглого друга жили далі проти темряви, що загрожує Азероту."}},faq={{q="Що відбувається на цьому етапі завдання?",a="Джордан Стілвелл підходить до ковадла й кує розпечений метал, з'єднуючи складники, які ви зібрали за час своїх тяжких випробувань. Попрацювавши біля горна, він повертається й вручає вам готову зброю.",al={"кінець випробування праведності","джордан кує зброю","сцена веріґана"}},{q="Хто такий Бош Веріґан?",a="Бош Веріґан був шанованим паладином-дворфом і близьким другом Джордана Стілвелла. На його честь Джордан назвав щойно викуваний дворучний молот, ушановуючи його відданість Святому Світлу.",al={"хто такий веріґан","кулак веріґана","бош веріґан"}},{q="Де відбувається кування?",a="Кування відбувається одразу за великою брамою Айронфорджа, серед засніжених вершин Дун Мороґу, де Джордан Стілвелл тримає свою кузню й ковадло.",al={"місце джордана стілвелла","де кузня","ковадло дун морога"}},{q="Навіщо Джорданові рідкісні матеріали з усього світу?",a="Джордан задумав зброю винятково врівноважену й сповнену святого резонансу. Щоб викувати річ, здатну витримати святий гнів паладина, йому були потрібні рідкісні руди, деревина й самоцвіти, які можна здобути лише в небезпечних куточках світу.",al={"навіщо збирати матеріали","складники випробування праведності"}},{q="Чи б'ється Джордан Стілвелл сам?",a="Джордан Стілвелл — коваль, а не мандрівний воїн. Хоч він і зізнається, що часом заздрить шукачам пригод, які мандрують світом, своє справжнє покликання й гордість він знаходить у тому, щоб кувати зброю для захисників Світла.",al={"чи джордан воїн","джордан стілвелл боєць"}},{q="Що означає для паладина отримати цей молот?",a="Отримати молот — значить успішно завершити довгі випробування паладина. Це доказ того, що його власник має мужність, наполегливість і святу віру, потрібні, щоб боронити Світло в найнебезпечніших куточках Азерота.",al={"значення кулака веріґана","обряд паладина"}}},fp="25,320,17.391.0,27.358.0,43.211.0,21.190.0,35.152.0,59.243.0,50.225.0,54.228.0"}
P.entries["quest:181"] = {n="Подивись на зорі",s="Це завдання — останній розділ задуму Вікторі Призм'Антраса зібрати в Даркширі прилад для споглядання зірок. Телескоп уже майже готовий, тож Вікторі посилає мандрівників до небезпечного Огрського Кургану Вул'Ґол по лінзу, досить велику для його пристрою: монокль, який носить огр Ззарк'Вул.",h="Це завдання — останній розділ задуму Вікторі Призм'Антраса зібрати в Даркширі прилад для споглядання зірок.",kw={"подивись на зорі","ззарк'вул","огрський курган вул'ґол","коґ ґлітцспіннер","монокль","телескоп"},ang={["faction:Alliance"]="Даркшир ледве виживає серед жахіть і звірів, тож прагнення Вікторі до небесних знань стає незгасним, хай і дивакуватим, маяком людської стійкості.",["profession:Engineering"]="І маги, і майстри оцінять зухвалість задуму: замінити астрономічну лінзу величезним огрським моноклем, щоб досягти потрібної фокусної відстані.",["race:Gnome"]="Пристрій тримається на гномських кресленнях і вимагає геніальної польової імпровізації — як-от перетворити окуляри громила на точну оптику."},sec={{t="Остання деталь",b="Будуючи свій телескоп, Вікторі Призм'Антрас увесь час спирався на креслення гномського інженера Коґа Ґлітцспіннера. Латунні труби й міцні кріплення можна було роздобути чи зібрати з місцевих матеріалів, але приладові потрібна була надзвичайно велика фокусувальна лінза. Звичайним збільшувальним скельцям і оптичним деталям від торговців зі Стормвінда просто бракувало діаметра, якого вимагав сміливий задум Коґа, — тож Вікторі звернув погляд на несподівану й небезпечну альтернативу."},{t="Скельце огра",b="У тіні південних пагорбів лежить Огрський Курган Вул'Ґол — табір, що кишить ворожими громилами-ограми. Серед них живе Ззарк'Вул — особливий огр, відомий тим, що носить скляний монокль, досить великий, щоб стати лінзою обсерваторії. Пробившись углиб кургану й забравши скельце в Ззарк'Вула, ви виконаєте креслення Коґа, і Вікторі зможе завершити телескоп та зазирнути в небеса над темними кронами Сутінколісся."}},faq={{q="Хто такий Вікторі Призм'Антрас?",a="Вікторі Призм'Антрас — астроном і вчений, що живе в хатині на пагорбі в Даркширі. Попри морок, що огортає Сутінколісся, він і далі завзято добудовує свій телескоп, щоб вивчати зорі.",al={"хто такий вікторі","вікторі призм'антрас"}},{q="Де знайти Ззарк'Вула?",a="Ззарк'Вул живе на півдні Сутінколісся, в Огрському Кургані Вул'Ґол. Він никає табором і печерами кургану, тож шукачам доведеться пробиратися крізь добре охоронювані володіння огрів.",al={"місце ззарк'вула","де огр","місце монокля огра"}},{q="Звідки в огра монокль?",a="Огри не славляться ні вченістю, ні тонкою оптикою, проте Ззарк'Вул носить величезний монокль. Через свої незвичні розміри це єдина лінза в краю, достатньо велика для креслень телескопа від Коґа.",al={"чому в огра монокль","монокль огра лор"}},{q="Що буде, коли пристрій завершено?",a="Здобувши монокль, Вікторі вставляє на місце останню лінзу. Коли телескоп повністю зібрано, Вікторі може знову вивчати небо, і похмура лісова земля внизу йому вже не завадить.",al={"телескоп готовий","кінець завдання"}},{q="Хто сконструював телескоп?",a="Креслення пристрою надав інженер на ім'я Коґ; його складний задум вимагав особливих деталей, металевого каркаса й лінзи, значно більшої за звичайні дворфійські чи гномські окуляри.",al={"креслення коґа","хто збудував телескоп"}},{q="Чи безпечно йти в Огрський Курган Вул'Ґол самому?",a="Ні. Огрський Курган Вул'Ґол густо населений ворожими ограми, які часто патрулюють гуртом або стережуть вузькі проходи. Пробиратися вглиб кургану на пошуки Ззарк'Вула для мандрівника-одинака дуже небезпечно.",al={"складність вул'ґола","чи безпечно в огрському кургані"}}},fp="17,312,15.508.0,19.438.1,28.210.0,27.220.0,35.226.0,42.197.0,27.202.0,42.212.0"}
P.entries["quest:1818"] = {n="Поговори з Діллінджером",s="«Поговори з Діллінджером» — воєнний наказ Орди, виданий в Андерсіті. Остіл Де Мон посилає дужих бійців до Вартового Смерті Діллінджера в Бріллі, щоб ті взялися за небезпечне бойове доручення на службі Леді Сильвани.",h="«Поговори з Діллінджером» — воєнний наказ Орди, виданий в Андерсіті.",kw={"поговори з діллінджером","вартовий смерті діллінджер","остіл де мон","брілл","галявини тірісфалю","воїн"},ang={["class:Warrior"]="Командири вартових смерті понад усе цінують бойову загартованість, тож це доручення — пряма перевірка ваших бойових умінь на передовій.",["faction:Horde"]="Відгукуючись на заклики боронити Андерсіті, ви зміцнюєте єдність між союзниками з Калімдору й Відступниками, що нещодавно влилися в Орду.",["race:Undead"]="Для щойно визволених Відступників відгукнутися на поклик Діллінджера — важливий крок, щоб довести відданість Темній Леді й обороні Тірісфалю."},sec={{t="Виклик на передову",b="У підземних залах Андерсіті Остіл Де Мон пильно видивляється перспективних бійців, готових служити Темній Леді. Коли вартовим смерті на поверхні потрібні вправні руки, Де Мон відсилає ще не випробуваних шукачів пригод із королівської столиці в поле. Вартовий Смерті Діллінджер, що відповідає за безпеку на західних околицях Брілла, попросив прислати когось із бойовим вишколом для нагальної справи."},{t="Випробування вірних",b="Брілл стоїть просто на передовій Галявин Тірісфалю, де Відступники мусять постійно доводити свою бойову перевагу над ворожими загрозами. Пост Діллінджера біля сільського цвинтаря — найкраще місце, щоб давати раду місцевим вторгненням. Для молодого воїна прибути до Діллінджера — не просто доручення: це офіційне випробування бойової вправності й політичної вірності щойно викуваному народові Відступників."}},faq={{q="Хто посилає мене на це доручення?",a="Остіл Де Мон з Андерсіті вишукує можливих бійців і посилає їх на допомогу Вартовому Смерті Діллінджеру.",al={"хто дає завдання","остіл де мон","хто дає поговори з діллінджером"}},{q="Де знайти Вартового Смерті Діллінджера?",a="Вартовий Смерті Діллінджер стоїть на західній околиці Брілла в Галявинах Тірісфалю, біля входу на цвинтар.",al={"місце діллінджера","де діллінджер","знайти діллінджера"}},{q="Навіщо з'являтися до Діллінджера?",a="Діллінджерові потрібен вправний боєць для бойового доручення: захистити Брілл і довести свою відданість справі Відступників.",al={"навіщо говорити з діллінджером","мета діллінджера"}},{q="Яке доручення приготував Діллінджер?",a="Щойно ви з'явитеся до Вартового Смерті Діллінджера, він доручить вам вистежити небезпечну загрозу на ім'я Улаг Різник.",al={"чого хоче діллінджер","наступне завдання діллінджера"}},{q="Чи отримують цей наказ інші раси Орди?",a="Взятися за доручення може будь-який воїн Орди, що здобув довіру урядовців Андерсіті, хоча передусім воно розраховане на перевірку новобранців, які боронять Галявини Тірісфалю.",al={"чи лише для нежиті","чи орки можуть це"}},{q="Чому цей наказ дають в Андерсіті, а не в Бріллі?",a="Остіл Де Мон — вербувальник у столиці: він спрямовує щойно загартованих шукачів пригод до командирів на прикордонні, яким нагально потрібна сила.",al={"чому початок в андерсіті","роль остіла де мона"}}},fp="20,221,22.434.0,20.419.0,29.117.0,40.111.0,46.129.0,45.117.1,40.168.0,62.153.0"}
P.entries["quest:1819"] = {n="Улаг Різник",s="Улаг Різник — обряд посвяти для молодих воїнів Відступників у Галявинах Тірісфалю. Вартовий Смерті Діллінджер доручає вам звільнити й стратити поневоленого воїна Погибелі, ув'язненого в північному мавзолеї, — випробування вашої бойової рішучості, що здобуде вам повагу Вартових Смерті.",h="Улаг Різник — обряд посвяти для молодих воїнів Відступників у Галявинах Тірісфалю.",kw={"улаг різник","діллінджер","брілл","мавзолей","погибель","воїн","випробування"},ang={["class:Warrior"]="Це випробування — ранній полігон для воїнів Відступників: воно перевіряє вашу відвагу в сутичці з могутнім, підкореним чужій волі поборником Погибелі.",["race:Undead"]="Доля Улага показує жахливу правду про владу Погибелі — трагічну межу між Відступниками, які вирвалися на волю, і тими, чий розум досі в рабстві Короля-Ліча."},sec={{t="Скутий раб Погибелі",b="Коли Погибель прокотилася Лордероном, Відступникам вдалося захопити незвичайного воїна-нежить, який назвався Улагом Різником. Розум Улага лишався ясним і притомним, та дух його нерозривно скоряла психічна воля Короля-Ліча. Прагнучи зрозуміти, як саме Погибель сковує вільну волю, Відступники тримали його під магічною печаттю в мавзолеї на північ від Брілла, сподіваючись розірвати духовні ланцюги цієї сутності."},{t="Випробування ката",b="Усі спроби вирвати Улага з ментальних лещат Короля-Ліча зазнали невдачі. Збагнувши, що справжню свободу йому може дати лише знищення, Вартовий Смерті Діллінджер перетворив бранця на бойове випробування для молодих воїнів Відступників. Зрушивши камінь-череп біля входу до склепу, воїн ламає захисні печаті, випускає Улага з ув'язнення — і дарує йому звільнення лезом сокири."}},faq={{q="Хто такий Улаг Різник?",a="Улаг Різник — воїн-нежить, якого Відступники схопили під час навали Погибелі на Галявини Тірісфалю. Дивовижно, але він зберіг вільний розум і особистість, проте й далі цілковито корився подумковим наказам Короля-Ліча.",al={"улаг лор","хто такий улаг","особа улага різника"}},{q="Чому Улага ув'язнили під мавзолеєм?",a="Учені й солдати Відступників ув'язнили його під магічною печаттю, щоб вивчити, як діє влада Короля-Ліча над розумом. Вони сподівалися знайти спосіб розірвати псіонічний зв'язок, що тримав його, але досліди не вдалися.",al={"чому улага ув'язнили","в'язень мавзолею тіріфальські гаї"}},{q="Чому Вартові Смерті тепер хочуть убити Улага?",a="Визнавши, що вирвати Улага з лабет Короля-Ліча не вдасться, Відступники вирішили, що смерть — єдина милість, яка лишилася. Вартовий Смерті Діллінджер вирішив зробити цю страту перевіркою бойової відваги й дисципліни для молодих воїнів.",al={"чому вбити улага","причина вбити улага"}},{q="Як викликати Улага?",a="Він ув'язнений під мавзолеєм трохи на північ від Брілла. Якщо скористатися кам'яним черепом біля гробниці, магічна печать, що тримає його, спадає, і Улаг повстає й нападає.",al={"як викликати улага","де улаг","череп улага"}},{q="Хто дає завдання вбити Улага?",a="Вартовий Смерті Діллінджер, що стереже західний шлях з Брілла в Галявинах Тірісфалю, дає це доручення саме воїнам-Відступникам, які прагнуть подальшої науки.",al={"хто дає завдання улага","хто посилає до улага"}},{q="Що буде після перемоги над Улагом?",a="Переконавшись, що Улаг загинув, Вартовий Смерті Діллінджер визнає вашу доблесть і посилає вас до Коулмена Фартінґа в Бріллі, щоб продовжити навчання.",al={"після улага","продовження завдання улага"}}},fp="16,280,22.455.0,23.417.0,24.233.0,44.246.0,44.236.0,21.178.0,33.174.0,36.156.0"}
P.entries["quest:182"] = {n="Тролляча печера",s="Доручене горянином Ґреліном Вайтбірдом, це завдання посилає шукачів пригод винищити молодих тролів Морозогривів, що збираються в південних печерах Долини Холодного Хребта. Поки Сенат Айронфорджа заклопотаний дедалі гострішою кризою з трогами, самотні розвідники й охочі новобранці мусять давати раду прикордонним сутичкам, перш ніж тролі закріпляться назавжди.",h="Доручене горянином Ґреліном Вайтбірдом, це завдання посилає шукачів пригод винищити молодих тролів...",kw={"тролляча печера","ґрелін вайтбірд","морозогриви","тролі","долина холодного хребта","розвідка","печера"},ang={["class:Hunter"]="Скелі довкола південної печери — суворий полігон для молодих слідопитів, що вчаться виганяти ворожу здобич із гірських висот.",["race:Dwarf"]="Для молодих дворфів Бронзбірдів, що виходять у сніги, винищення загонів Морозогривів — і справа прикордонної безпеки, і давня гірська ворожнеча.",["race:Gnome"]="Знайшовши притулок у Дун Мороґу після падіння Гномреґану, гноми охоче дають свій розум і зброю, щоб позбавити дворфів-господарів довколишніх загроз."},sec={{t="Очі на холоді",b="Поки регулярні сили Айронфорджа поглинуті відбиттям набігів трогів Кам'янощелепів по снігових полях, південні підступи не можна лишати без нагляду. Ґреліна Вайтбірда та його брата Сеніра гірська влада відрядила оцінити, чи становлять тутешні крижані тролі безпосередню небезпеку для серця краю. З кручі над замерзлою долиною Ґрелін сам-один стежить за їхніми пересуваннями."},{t="Випереджувальний удар",b="Розвідка Ґреліна показала, що місцевий клан Морозогривів почав оселятися в глибокій печері вздовж південного хребта Долини Холодного Хребта. Вважаючи повну військову мобілізацію марною тратою дворфійських сил, розвідник волів найняти вправних місцевих добровольців, щоб винищити зухвалих молодиків. Прорідити їхніх молодих бійців — означає зірвати їхній табір, перш ніж Морозогриви зможуть здійснити узгоджені набіги на сусідні дворфійські обійстя."}},faq={{q="Чому Айронфордж не посилає регулярних солдатів проти цих тролів?",a="Сенат Айронфорджа й дворфійське військо розпорошені, бо мусять стримувати раптову нищівну навалу трогів по всьому Дун Мороґу. Дрібні загрози на кшталт невеликих ватаг тролів лишають розвідникам, як-от Ґреліну Вайтбірду, а ті наймають незалежних шукачів пригод.",al={"чому немає армії дворфів","де вартові","чому наймають шукачів пригод"}},{q="Хто такі тролі Морозогриви?",a="Морозогриви — корінне плем'я крижаних тролів, споконвіку мешканців холодних скель Дун Мороґу. Віддавна ворожі до дворфів Бронзбірдів, вони постійно сутичкуються з горянами за мисливські угіддя, землю й давні гірські перевали.",al={"клан морозогривів","тролі дун морога","хто такі морозогриви"}},{q="Де розташована тролляча печера?",a="Печера схована в південному гірському хребті Долини Холодного Хребта, на південь від спостережного табору Ґреліна Вайтбірда.",al={"місце тролячої печери","де печера","де молодняк"}},{q="Хто такий Ґрелін Вайтбірд?",a="Ґрелін Вайтбірд — розвідник з Айронфорджа, що стоїть у Долині Холодного Хребта. Разом із братом Сеніром, який оглядає інші куточки Дун Мороґу, Ґрелін стежить за ворожими тролями й доповідає дворфійським очільникам.",al={"ґрелін","хто дає завдання","вайтбірд"}},{q="Чому Ґрелін полює саме на молодняк Морозогривів?",a="Табір на півдні Долини Холодного Хребта — поселення, що швидко росте й повне молодих воїнів. Знищивши їхніх бійців, поки ті не підросли, можна не дати ватазі набратися сили й загрожувати дворфійським шляхам постачання.",al={"чому молодняк","чому молоді тролі"}},{q="Що буде, коли проріджено печеру?",a="Повернувшись, ви дізнаєтеся, що вночі тролі помстилися: напали на табір Ґреліна й поцупили його особистий польовий щоденник, тож його доведеться негайно повернути з глибин їхніх лігв.",al={"що далі","продовження тролячої печери"}}},fp="14,348,16.431.0,19.464.0,70.270.0,29.237.0,32.120.0,25.216.0,53.218.0,36.197.1"}
P.entries["quest:1820"] = {n="Поговори з Колманом",s="«Поговори з Колманом» — перехідне завдання в Галявинах Тірісфалю для тих, хто вже довів свою вартість у боротьбі з Погибеллю. Вартовий Смерті Діллінджер відсилає здібних воїнів із міської площі до місцевої таверни — допомогти Коулмену Фартінґу з його особистими та фракційними порахунками.",h="«Поговори з Колманом» — перехідне завдання в Галявинах Тірісфалю для тих, хто вже довів свою вартість у...",kw={"коулмен фартінґ","брілл","таверна","діллінджер","вендета","тірісфаль"},ang={["faction:Horde"]="Для мандрівників, що допомагають убезпечити Лордерон, знайомство з місцевими жителями Брілла — надійна опора для дій по всіх Галявинах Тірісфалю.",["race:Undead"]="Багато Відступників поряд із вірністю Темній Леді плекають особисті образи; прохання Коулмена Фартінґа показують, як тісно у Тірісфалі переплітаються особиста втрата й захист нації."},sec={{t="Слово від варти",b="Допомігши приборкати серйозні місцеві загрози — скажімо, упокоївши небезпечні рештки Погибелі на кшталт Улага Різника, — шукачі пригод здобувають особисту довіру Вартового Смерті Діллінджера. Як один із вартових, що пильнують дороги до Брілла, Діллінджер сам судить, хто здатен на більше, ніж звичайні обходи периметра, і скеровує вмілих бійців до городян, яким потрібна особлива послуга."},{t="Приватна вендета",b="Не кожен конфлікт у Галявинах Тірісфалю ведеться за наказом верховного командування з Андерсіті. По всьому зруйнованому королівству Лордерон уцілілі мерці носять у собі глибокі образи, пов'язані з землями, родинами й статками, що лишилися в минулому. Коулмен Фартінґ вичікує в Таверні «Шибеничний Кінець», шукаючи знаряддя помсти, щоб ударити по загрозах, які й досі тиняються біля колишніх поселень на кшталт Млинів Аґаманда."}},faq={{q="Де знайти Коулмена Фартінґа?",a="Коулмен Фартінґ чекає в таверні «Шибеничний Кінець» у східній частині Брілла в Галявинах Тірісфалю.",al={"місце коулмена фартінґа","де коулмен фартінґ","знайти фартінґа брилл"}},{q="Хто посилає поговорити з Коулменом?",a="Вартовий Смерті Діллінджер, що стереже шлях до Брілла, посилає вас до Коулмена, коли ви доведете свою бойову вправність.",al={"хто дає поговори з колманом","завдання діллінджера"}},{q="Яку роботу має Коулмен Фартінґ?",a="Коулменові потрібен вправний боєць, який стане знаряддям помсти ворогам Відступників, — ідеться про давні володіння Аґамандів.",al={"чого хоче коулмен","завдання коулмена фартінґа"}},{q="Що треба зробити, перш ніж отримати це завдання?",a="Вартовий Смерті Діллінджер посилає вас до Коулмена лише тоді, коли ви доведете Відступникам свою відданість і бойову вправність, перемігши Улага Різника.",al={"передумови поговори з колманом","вимога улага"}},{q="Чи дає це доручення вагомі нагороди?",a="Це доручення лише знайомить вас із Фартінґом у корчмі й відкриває низку його особистих прохань, а саме по собі не дає ні доброго спорядження, ні грошей.",al={"нагороди поговори з колманом","чи варто робити"}},{q="Що таке таверна «Шибеничний Кінець»?",a="Таверна «Шибеничний Кінець» — головний заїзд Брілла: місце зустрічей, відпочинку й неофіційний осередок приватних угод серед місцевої нежиті.",al={"таверна брилла","шибеничний кінець"}}},fp="18,283,21.406.0,18.413.0,34.123.0,33.132.0,45.174.0,57.145.0,53.164.0,32.162.0"}
P.entries["quest:1821"] = {n="Реліквії роду Аґамандів",s="Коулмен Фартінґ доручає шукачам пригод сплюндрувати Родинний Склеп Аґамандів на північному краю Млинів Аґаманда. Гнаний гіркою образою за власну смертну загибель, він прагне відібрати в колишніх господарів їхню родову зброю і стерти останні рештки їхньої гідності.",h="Коулмен Фартінґ доручає шукачам пригод сплюндрувати Родинний Склеп Аґамандів на північному краю Млинів...",kw={"аґаманди","склеп","реліквії","коулмен фартінґ","млини аґаманда","родова зброя"},ang={["class:Rogue"]="Прослизнути повз гулів, що чигають у темряві, і поцупити стародавню зброю з охоронюваних поховальних склепінь — для майстрів тіні справа звична.",["faction:Horde"]="Зачистка склепу підриває укорінену владу Погибелі над північчю Галявин Тірісфалю, роблячи край безпечнішим для мандрівників Орди.",["race:Undead"]="Гірке завдання Коулмена Фартінґа втілює давні образи й незагоєні рани, які чимало Відступників несуть зі смертного життя в нежиття."},sec={{t="Гірка образа слуги",b="Перш ніж Третя війна спустошила Лордерон, Коулмен Фартінґ служив заможній і впливовій родині Аґамандів на їхніх розлогих млинах у Галявинах Тірісфалю. Хай що сталося під час падіння маєтку, у своїй смерті Фартінґ цілковито звинувачує колишніх панів. Тепер, піднятий у нежитті серед Відступників, він дивиться на падіння Аґамандів зі злісним задоволенням, радіючи, що колись горда династія обернулася на безтямних прислужників Короля-Ліча."},{t="Осквернення склепу",b="Щоб остаточно загасити рештки родинної слави, Фартінґ посилає шукачів пригод до Родинного Склепу Аґамандів, схованого під північними кручами млинів. У його населених привидами кам'яних залах неспокійні мерці блукають пліч-о-пліч із недобитками Погибелі. Фартінґ вимагає добути чотири славетні реліквії — родовий меч, сокиру, кинджал і булаву Аґамандів, — щоб спадок їхнього роду позбувся останньої крихти честі."}},faq={{q="Ким був Коулмен Фартінґ за життя?",a="Коулмен Фартінґ був слугою заможної родини Аґамандів у Млинах Аґаманда ще до навали Погибелі на Лордерон. Він загинув під час лиха й звинувачує у своїй смерті господарів; ця пекуча образа не згасла й у нежитті.",al={"хто такий коулмен фартінґ","передісторія коулмена","історія фартінґа"}},{q="Навіщо Коулменові Фартінґу родинні реліквії?",a="Фартінґ прагне повної помсти колишнім господарям. Пограбувавши з родинного склепу їхні родові меч, сокиру, кинджал і булаву, він хоче позбавити занепалий рід останніх решток честі й пам'яті.",al={"навіщо красти реліквії","мотив коулмена","навіщо брати зброю"}},{q="Що сталося з родиною Аґамандів?",a="Родина Аґамандів загинула, коли Погибель пронеслася Галявинами Тірісфалю. Замість знайти спокій у смерті, вони повстали безвольними рабами-нежиттю, скореними волі Короля-Ліча, і тепер блукають своїми зруйнованими млинами й склепом.",al={"доля аґамандів","чи аґаманди живі","що з аґамандами тепер"}},{q="Де розташований Родинний Склеп Аґамандів?",a="Склеп лежить на північній околиці Млинів Аґаманда, врізаний у скелясті урвища над спаплюженими хуторами на півночі Галявин Тірісфалю.",al={"місце склепу","де склеп","мапа склепу аґамандів"}},{q="Яка зброя зберігається в склепі?",a="У склепі зберігаються чотири родові зброї цього роду: Меч Родини Аґаманд, Сокира Родини Аґаманд, Кинджал Родини Аґаманд і Булава Родини Аґаманд.",al={"які реліквії","чотири реліквії","зброя аґамандів"}},{q="Чому Відступники нападають на Аґамандів, якщо і ті, й інші — нежить?",a="Відступники мають вільну волю й борються за власне виживання, а Аґаманди-нежить лишаються безвольними рабами Погибелі й служать Королеві-Лічу, якого Відступники зневажають.",al={"нежить проти нежиті","чому б'ються з аґамандами","конфлікт відступників і погибелі"}}},fp="17,272,25.468.0,21.443.0,33.266.0,45.219.0,36.230.0,42.144.0,39.181.0,63.180.0"}
P.entries["quest:1824"] = {n="Випробування на Полі Велетнів",s="«Випробування на Полі Велетнів» — обрядове завдання для воїнів, яке дає Руґа Рейджтотем у Таборі Тауражо. У межах вишколу молодих бійців посилають на південь, до кишучих кучугур Поля Велетнів, щоб убивати чужинських комахоподібних загарбників. Кандидати мають зібрати кілька вусиків, що ще сіпаються, і щодуху примчати з ними назад, поки біологічний доказ не завмер.",h="«Випробування на Полі Велетнів» — обрядове завдання для воїнів, яке дає Руґа Рейджтотем у Таборі Тауражо.",kw={"випробування на полі велетнів","руґа рейджтотем","силітиди","сіпливе вусико","табір тауражо","воїн"},ang={["class:Warrior"]="Це випробування — важливий обряд посвяти приблизно на двадцятому рівні: воно перевіряє, чи вміє воїн швидко розправлятися з роями супротивників і зберігати витривалість у суворо обмежений час.",["faction:Horde"]="Орда насторожено стежить за поширенням силітидів на півдні Пусток і вважає кожне навчальне випробування передовою розвідкою проти загрози, що повзе.",["race:Tauren"]="Для тауренів-оборонців очищення оскверненого Поля Велетнів допомагає захистити їхні мисливські угіддя довкола Табору Тауражо від неприродного вулика-загарбника."},sec={{t="Випробування швидкості й сталі",b="Наставники воїнів в Орді рідко задовольняються самим лише бойовим умінням, не перевіривши стійкості й швидкості. Руґа Рейджтотем кидає виклик молодим воїнам у Таборі Тауражо: довести себе в бою з незнайомим супротивником. Від новачків вимагають не лише вбивати загарбників — вони мусять відтяти свіжі вусики й повернутися до Тауражо за пів години, поки зрізані тканини не перестали сіпатися, а для цього треба швидко орієнтуватися на півдні Пусток."},{t="Непрохані гості",b="Мета випробування — вулики силітидів, що розростаються на Полі Велетнів, під велетенськими скам'янілими реберними кістяками. Ці повзучі хітинові комахи — недавні прибульці в Пустках, і вони непокоять тауренських мисливців і шаманів, що наглядають за саванами. Руґа з тривогою зауважує, що їхня поява не віщує Калімдору нічого доброго, тож випробування-винищення має подвійну мету: перевірити бойове чуття молодого воїна й зібрати відомості про загрозу, що нависла над природою."}},faq={{q="Чому на вусики дано обмежений час?",a="Руґа Рейджтотем вимагає, щоб вусики ще сіпалися, коли їх принесуть до Табору Тауражо, тож воїни мають лише тридцять хвилин, щоб упоратися з полюванням і повернутися. Така свіжість доводить, що претендент швидко здолав сілітида в чесному бою, а не підібрав мертвий панцир.",al={"чому обмежений час","таймер вусиків","скільки часу"}},{q="Які істоти живуть на Полі Велетнів?",a="Поле Велетнів кишить сілітидами — дивною й агресивною расою комах-копачів. Вони нарили величезні горби й вулики під давніми скам'янілостями, порушуючи місцеву природу й насторожуючи Орду.",al={"які це комахи","істоти поля велетнів","що таке сіліти"}},{q="Хто такий Руґа Рейджтотем?",a="Руґа Рейджтотем — таурен, наставник воїнів, що стоїть у Таборі Тауражо в південних Пустках. Він проводить випробування, що перевіряють уміння, стійкість і швидкість воїнів Орди, які прагнуть піднятися вище.",al={"руґа","хто дає завдання","руґа рейджтотем лор"}},{q="Де розташоване Поле Велетнів?",a="Поле Велетнів лежить одразу на південь від Табору Тауражо, обабіч шляху перед південним перевалом до Тисячі Голок. Його легко впізнати за височенними кістяними ребрами й горбами сілітидів.",al={"де поле велетнів","місце поля велетнів","де шукати комах"}},{q="Куди веде цей ланцюжок навчання далі?",a="Коли воїн вчасно принесе вусики, що ще сіпаються, Руґа посилає його до Тун'ґріма Файрґейза — старого орка-коваля, що живе на пагорбі на схід від Перехрестя й кує обладунки для випробуваних воїнів.",al={"наступне завдання","що далі","продовження воїна"}},{q="Чому таурени непокояться через комах?",a="Сілітиди — неприродні прибульці в Пустках. Руґа каже, що їхня поява не віщує краю нічого доброго, і підозрює, що їхнє агресивне риття й поширення провіщають набагато більшу небезпеку, яка ворушиться під пісками.",al={"чому таурени переймаються","вісник комах","загроза сілітидів"}}},fp="28,361,25.458.0,19.485.0,42.297.0,43.221.0,22.208.0,37.205.0,41.226.0,47.220.0"}
P.entries["quest:1825"] = {n="Поговори з Тун'ґрімом",s="Це доручення скеровує молодих воїнів Орди до Тун'ґріма Файрґейза — знаного оркського коваля, що отаборився в Пустках. Довівши себе у важких фізичних випробуваннях, воїни отримують запрошення: їм викують обладунок на знак визнання їхньої доблесті. Завдання — важливий місток між загальними випробуваннями воїнів і куванням жорстокого обладунку.",h="Це доручення скеровує молодих воїнів Орди до Тун'ґріма Файрґейза — знаного оркського коваля, що отаборився в...",kw={"поговори з тун'ґрімом","тун'ґрім файрґейз","руґа рейджтотем","жорстокий обладунок","воїн","перехрестя"},ang={["class:Warrior"]="Це завдання — важливий обряд посвяти, що підносить вас від бійця-новачка до визнаного звитяжця, гідного обладунку, викуваного на замовлення.",["faction:Horde"]="Бронники Орди пишаються тим, що озброюють найзапекліших оборонців, і дбають, щоб ті, хто б'ється на рубежах, носили спорядження, гідне їхніх бойових звершень.",["profession:Blacksmithing"]="Тун'ґрім Файрґейз уособлює традиційну оркську ковальську філософію: майстерний обладунок треба заслужити бойовими випробуваннями, а не просто монетою."},sec={{t="Поклик коваля",b="Довівши свій гарт у сутичках із вуликами силітидів під час «Випробування на Полі Велетнів», воїни Орди отримують від Руґи Рейджтотема більше, ніж звичайну похвалу. Звістка про їхню витривалість і бойову вправність швидко доходить до Тун'ґріма Файрґейза — знаного оркського коваля, чий табір стоїть на кряжі на схід від Перехрестя. Упізнавши воїна, гідного своєї майстерності, Тун'ґрім передає, що хоче викувати для нього надзвичайні бойові лати."},{t="Мірило майстра",b="Тун'ґрім Файрґейз не кує для звичайних солдатів. Для бронника з такою славою сталь має відповідати духові того, хто понесе її в бій. Дійти до його табору — означає переступити поріг простої муштри ополченця й бути готовим до виснажливих особливих доручень, потрібних, щоб зібрати рідкісні ремісничі реагенти по всьому Калімдору."}},faq={{q="Хто такий Тун'ґрім Файрґейз?",a="Тун'ґрім Файрґейз — шанований орк-коваль, що отаборився на скелястому хребті трохи на схід від Перехрестя в Пустках. Він кує на замовлення грізні обладунки для воїнів Орди, які довели свою доблесть у небезпечних випробуваннях.",al={"хто такий тун'ґрім","тун'ґрім лор","тун'ґрім файрґейз"}},{q="Чому Руґа Рейджтотем посилає мене до нього?",a="Руґа Рейджтотем бачить, що, вистоявши проти сілітидів у південних Пустках, ви переросли прості випробування. Він посилає вас до Тун'ґріма, щоб майстер-коваль винагородив вашу службу Орді, викувавши особливий обладунок.",al={"чому говорити з тун'ґрімом","чому руґа посилає"}},{q="Де знайти табір Тун'ґріма?",a="Тун'ґрім отаборився на високих кручах на схід від Перехрестя в Пустках, звідки видно суху савану.",al={"де тун'ґрім","місце тун'ґріма","знайти тун'ґріма файрґейза"}},{q="Що буде після розмови з Тун'ґрімом?",a="Зустріч із Тун'ґрімом відкриває ланцюжок завдань про Жорстокий обладунок, що веде воїнів у далекі краї по міцні матеріали, як-от димчасті залізні зливки й залізні бруски, щоб викувати кольчугу на замовлення.",al={"наступне завдання після тун'ґріма","чого хоче тун'ґрім"}},{q="Чи доступне це завдання всім класам?",a="Ні. Це завдання й увесь пов'язаний із ним ланцюжок про обладунок — частина бойового вишколу лише для воїнів Орди.",al={"чи не воїни можуть це","чи лише для воїнів"}},{q="Яке випробування треба пройти перед цією зустріччю?",a="Перед цим дорученням воїни мусили вирушити в південні Пустки й пройти Випробування на Полі Велетнів, зібравши вусики сілітидів, що ще сіпаються, щоб довести свою бойову витривалість.",al={"передумова","що я робив перед цим"}}},fp="20,365,21.456.0,19.360.0,26.226.0,39.239.0,34.116.0,43.192.0,39.124.0,44.189.0"}
P.entries["quest:183"] = {n="Мисливець на вепрів",s="Мисливець на вепрів — раннє доручення від дворфа-мисливця Таліна Кіная в Долині Холодного Хребта. Сплеск місцевої популяції скельних вепрів зробив ліси надто небезпечними, і молодим новобранцям доручають винищити зухвалих звірів, щоб досвідчені мисливці могли спокійно йти по сліду.",h="Мисливець на вепрів — раннє доручення від дворфа-мисливця Таліна Кіная в Долині Холодного Хребта.",kw={"мисливець на вепрів","талін кінай","скельні вепри","вепр","долина холодного хребта","анвілмар","полювання"},ang={["class:Hunter"]="Талін Кінай утілює пряме дворфійське ставлення до вистежування: тримайте приціл твердо, шануйте звірів і розчищайте хащі, коли дичина стає надто ворожою.",["race:Dwarf"]="Жити в горах — означає ділити землю з лютою звіриною. Винищити войовничих скельних вепрів довкола Анвілмара — обряд посвяти для кожного молодого дворфа, що робить перші кроки за межі кузні.",["race:Gnome"]="Для гномів-біженців, що щойно прибули з Гномреґану, зустріч із лютими дикими вепрами Дун Мороґу — суворе, практичне знайомство з життям у суворому дворфійському краї."},sec={{t="Переповнена долина",b="Долина Холодного Хребта зазвичай тихий, захищений навчальний майданчик для молодих горян і вчених Айронфорджа. Та в суворому зимовому кліматі звірина часто стає неспокійною й надто численною. Талін Кінай, досвідчений мисливець, що стоїть біля Анвілмара, помічає, що зухвалі малі скельні вепри розплодилися так швидко, що становлять справжню загрозу для кожного, хто блукає засніженими стежками."},{t="Доглядаючи сніги",b="Полювання — наріжний камінь дворфійського життя: воно дає м'ясо, шкуру й необхідну практику польового ремесла. Та коли дичина стає напастю, що нападає, щойно побачить, треба винищити зайве, щоб відновити рівновагу. Прорідивши скельних вепрів на схилах долини, молоді шукачі пригод доводять свою бойову готовність і дають місцевим мисливцям простір для їхнього ремесла, щоб ті не були задавлені кількістю."}},faq={{q="Хто такий Талін Кінай?",a="Талін Кінай — дворф-мисливець, що стоїть у Долині Холодного Хребта біля Анвілмара. Днями він вистежує дичину на снігу й допомагає навчати молодих шукачів пригод, як на ділі позбуватися ворожих звірів.",al={"талін кінай","хто дає мисливця на вепрів","нпц мисливець на вепрів"}},{q="Чим так допікають скельні вепри?",a="Малих скельних вепрів у Долині Холодного Хребта незвично розплодилося, і вони без жодної причини кидаються на кожного, кого побачать. Через таку кількість звичайні мандри й полювання стали для місцевих небезпечними.",al={"чому вбивати вепрів","проблема вепрів холодного хребта","чим небезпечні вепри"}},{q="Де водяться скельні вепри?",a="Малі скельні вепри никають відкритими засніженими рівнинами й рідколіссям довкола Анвілмара по всій Долині Холодного Хребта.",al={"де вепри","місце скельних вепрів","мапа скельних вепрів"}},{q="Чи пов'язане це завдання з більшою загрозою в долині?",a="Ні. На відміну від навали трогів, що непокоїть дворфійські застави, це завдання — просто впорядкування місцевої живності, щоб стежки були безпечні, а Талін міг полювати спокійно.",al={"чи є наступне завдання","ланцюжок мисливця на вепрів","історія за вепрами"}},{q="Чим скельні вепри пристосовані до Дун Мороґу?",a="Скельні вепри — витривалі товстошкірі свині, створені, щоб витримувати морози Дун Мороґу. Агресивна вдача й гострі ікла дають їм змогу добувати поживу з мерзлої землі й відбиватися від гірських хижаків.",al={"лор скельних вепрів","вепри дворфів","дика природа дун мороґу"}},{q="Чому Талін Кінай не вб'є вепрів сам?",a="Талін зауважує, що агресивних вепрів так багато, що його неквапливі полювання стали неприємно небезпечними. Тож він залучає завзятих новачків, що проходять через Анвілмар, щоб ті проріджили стадо й він міг повернутися до звичного вистежування.",al={"чому талін потрібна допомога","талін лінивий","чому талін сам не полює"}}},fp="15,279,16.412.0,17.384.0,21.214.0,38.203.0,34.120.0,57.168.0,43.215.0,49.224.0"}
P.entries["quest:1838"] = {n="Жорстокий обладунок",s="«Жорстокий обладунок» — обряд посвяти для воїнів Орди під наглядом майже сліпого коваля Тун'ґріма Файрґейза на півночі Пусток. Прагнучи викувати обладунок, гідний молодого звитяжця, Тун'ґрім посилає досвідчених воїнів у далекі краї по рідкісні реагенти й екзотичні плавильні присадки. Виконавши вказане в його сувої, воїн дає почин куванню цілого комплекту жорстокого бойового спорядження.",h="«Жорстокий обладунок» — обряд посвяти для воїнів Орди під наглядом майже сліпого коваля Тун'ґріма Файрґейза...",kw={"жорстокий обладунок","тун'ґрім файрґейз","жорстока кольчуга","порошковий азурит","закопчений залізний злиток","воїн"},ang={["class:Warrior"]="Це завдання — визначальна віха для воїнів Орди: вони доводять свою доблесть і витривалість на кількох континентах, щоб заслужити бойовий обладунок, викуваний на замовлення.",["faction:Horde"]="Комплекти жорстокого обладунку — свідчення єдності Орди: вони поєднують окремі ремісничі традиції ковалів-орків, тауренів, тролів і Відступників в одне бойове спорядження.",["profession:Blacksmithing"]="Сувій Тун'ґріма показує передову металургійну алхімію: закопчене залізо, порошковий азурит і флогістон підносять звичайне плавлення заліза на новий рівень."},sec={{t="Поклик майстра",b="На скелястих пагорбах півночі Пусток старий оркський коваль Тун'ґрім Файрґейз уважно прислухається до вітрів війни. Хоч його зір слабне й затьмарюється, у кузні йому досі немає рівних. Почувши чутки про воїна, чия сила й доблесть переважають звичайних солдатів, Тун'ґрім вирішує викувати міцну кольчугу, що витримає найзапекліші сутички Калімдору й Східних Королівств."},{t="Пошуки через континенти",b="Щоб викувати обладунок такого ґатунку, звичайної руди замало. Насилу, при світлі вогню, слабкими очима Тун'ґрім пише точний сувій із переліком складників для основи — нагрудника. Потрібні звичайне очищене залізо, рідкісні закопчені залізні злитки, які носять кобольди-копачі, порошковий азурит, який добувають рудокопи за морем, і пляшечка мінливого флогістону. Лише воїн, готовий витримати випробування в далеких краях, може сподіватися побачити цей обладунок викуваним."},{t="Перший удар молота",b="Доставка цих рідкісних припасів — лише початок задуму Тун'ґріма. Прийнявши матеріали й розпаливши горно, щоб викувати Жорстоку Кольчугу, старий коваль визнає, що один майстер не завершить такого честолюбного задуму. Щоб створити повний комплект, треба покликати вправних майстрів з інших народів Орди — тауренського майстра шоломів, троля-майстра рукавиць і майстриню-нежить, що кує поножі за морем."}},faq={{q="Хто такий Тун'ґрім Файрґейз?",a="Тун'ґрім Файрґейз — шанований орк-коваль, ветеран, що живе на пагорбі над північними Пустками. Хоча зір його підводить, біля ковадла чуття в нього гостре, і він кує на замовлення могутні бойові обладунки для воїнів Орди, які прославилися доблесними вчинками.",al={"хто такий тун'ґрім","тун'ґрім файрґейз лор","історія тун'ґріма"}},{q="Що таке Жорстокий обладунок?",a="Жорстокий обладунок — знаний комплект загартованої в боях кольчуги, створений саме для бувалих воїнів Орди. Його кують спільними зусиллями ковалів Орди, і кожна частина вимагає небезпечних подорожей по рідкісні алхімічні реагенти, очищені руди й давні прийоми.",al={"що таке жорстокий обладунок","лор комплекту жорстокого обладунку","ланцюжок обладунку воїна"}},{q="Навіщо Тун'ґрімові такі незвичні складники?",a="Звичайне залізо надто крихке, щоб витримати важкі удари, яких зазнає боєць на передовій. Незвичні реагенти, як-от азуритовий порошок, димчасті залізні зливки й нестійкий флогістон, слугують флюсом і засобами гартування, і Тун'ґрім наділяє метал неймовірною стійкістю й міцністю.",al={"навіщо порошок азуриту","навіщо флогістон","для чого реагенти"}},{q="Чи кує Тун'ґрім увесь комплект сам?",a="Ні. Тун'ґрім сам кує головну частину — кольчугу, а по відповідні шолом, рукавиці й поножі посилає воїна до інших майстрів Орди, зокрема до Орма Стоунгуфа, Ула'елека й Велори Найтлі.",al={"чи тун'ґрім кує все сам","хто кує частини жорстокого обладунку"}},{q="Куди веде цей ланцюжок завдань далі?",a="Це випробування веде просто до кування Жорстокої Кольчуги й водночас відкриває шлях до ковалів у Тандер Блафі, Селі Сен'джин і Андерсіті, щоб зібрати решту жорстоких бойових обладунків.",al={"що після жорстокого обладунку","продовження жорстокого обладунку"}},{q="Чому воїнові доводиться мандрувати так далеко по ці матеріали?",a="Це випробування — і перевірка бойової завзятості, і урок кмітливості. Щоб заслужити обладунок від майстра, воїн мусить пробиратися ворожими землями, спускатися в небезпечні копальні й добувати складники, до яких звичайним людям не дотягтися.",al={"чому їхати до східних королівств","чому стільки матеріалів"}}},fp="12,365,18.438.0,26.474.0,30.423.1,26.284.0,21.277.0,49.286.0,44.234.1,38.221.1,61.236.0"}
P.entries["quest:1839"] = {n="Ула'елек і Жорстокі Латні Рукавиці",s="Це завдання веде молодих воїнів Орди з висот Пусток назад до узбережжя Дуротару. За дорученням коваля Тун'ґріма Файрґейза ви маєте розшукати майстра з Темного Спису Ула'елека в Селі Сен'джин, щоб викувати свої Жорстокі Латні Рукавиці.",h="Це завдання веде молодих воїнів Орди з висот Пусток назад до узбережжя Дуротару.",kw={"ула'елек","жорстокі латні рукавиці","село сен'джин","тун'ґрім файрґейз","темний спис","воїн"},ang={["class:Warrior"]="Ланцюжок завдань про жорстокий обладунок — важливий обряд посвяти для воїнів Орди, що знаменує їхнє перетворення на загартованих у боях звитяжців передової.",["faction:Horde"]="Спільна праця оркських ковалів-майстрів у Пустках і тролів-ковалів у Дуротарі показує співпрацю, що скріплює молодий союз Тралла.",["race:Troll"]="Відвідини Ула'елека підкреслюють внесок племені Темного Спису у воєнні зусилля Орди — вправним ковальством і злагодою з духами."},sec={{t="Подорож до узбережжя",b="Довівши свою доблесть по всіх Пустках і взявшись збирати комплект жорстокого обладунку, воїни вирушають на схід за вказівкою Тун'ґріма Файрґейза. Старий оркський коваль не кує кожну частину сам на своїй гірській кручі — він покладається на мережу вправних майстрів по всіх землях Орди. Щоб викувати важкі латні рукавиці для звитяжця, що росте в силі, він посилає бійців до скелястих південних берегів Дуротару."},{t="Очі лоа",b="У Селі Сен'джин серед своїх родичів із Темного Спису працює троль-бронник Ула'елек. Він аж ніяк не заскочений: Ула'елек розповідає, що Тун'ґрім уже передав звістку про ваші звершення, — а головне, самі духи бачили ваші перемоги в бою. Для воїна, що здобуває місце серед добірних бійців Орди, майстерність і визнання духів ідуть пліч-о-пліч."}},faq={{q="Хто дає завдання «Ула'елек і Жорстокі Латні Рукавиці»?",a="Це завдання дає Тун'ґрім Файрґейз — шанований орк-бронник, що живе в горах над Пустками.",al={"хто дає завдання","хто починає ула'елек і жорстокі рукавиці","завдання тун'ґріма файрґейза"}},{q="Де знайти Ула'елека?",a="Ула'елек перебуває в Селі Сен'джин на південному узбережжі Дуротару.",al={"місце ула'елека","де ула'елек","ула'елек сен'джин"}},{q="Що таке комплект Жорстокого обладунку?",a="Жорстокий обладунок — комплект кольчужних і латних обладунків на замовлення, створений саме для бувалих воїнів Орди десь тридцятого рівня; його кують союзні ковалі по всьому Калімдору.",al={"жорстокий обладунок","що таке жорстокі рукавиці","обладунок воїна тридцятого рівня"}},{q="Що буде, коли дістанешся Ула'елека?",a="Привітавшись і віддавши належне вашим бойовим звершенням, Ула'елек доручить вам зібрати незвичні матеріали для Жорстоких Латних Рукавиць — почати доведеться з копит сатирів.",al={"наступне завдання","після розмови з ула'елеком","завдання копит сатирів"}},{q="Чому Тун'ґрім посилає вас до троля-бронника?",a="Тун'ґрім розподіляє кування Жорстокого обладунку між найкращими вузькими майстрами Орди, а рукавиці довіряє ремісникам з Темного Спису, як-от Ула'елеку.",al={"чому ула'елек","чому йти до села сен'джин","троль-коваль жорстокий обладунок"}},{q="Чи мають гравці Альянсу схоже завдання?",a="Воїни Альянсу проходять схоже бойове випробування, щоб здобути власний обладунок для свого класу, але ланцюжок про Жорстокий обладунок і робота Ула'елека — лише для Орди.",al={"жорстокі рукавиці альянсу","аналог для альянсу"}}},fp="33,247,22.423.0,19.383.0,54.108.0,26.87.0,29.179.0,37.185.0,50.160.0,53.176.0"}
P.entries["quest:184"] = {n="Грамота Фурлброу",s="«Грамота Фурлброу» — викрадений документ на землю, який носять при собі злодії Дефіасу в Лісі Елвінн. Повернувши його вигнаному Фермерові Фурлброу біля кордону Вестфолу, ви даєте подружжю-втікачам єдину надію колись повернути свою відібрану садибу.",h="«Грамота Фурлброу» — викрадений документ на землю, який носять при собі злодії Дефіасу в Лісі Елвінн.",kw={"грамота фурлброу","фермер фурлброу","верна фурлброу","ліс елвінн","братство дефіас","вестфол"},ang={["class:Paladin"]="Повертати вкрадені грамоти знедоленим біженцям — означає виконувати святі обітниці: боронити беззахисних і нести справедливість у беззаконні прикордонні землі.",["faction:Alliance"]="Лихо родини Фурлброу показує, що корона Стормвінда не здатна захистити своїх платників податків поза укріпленими мурами столиці."},sec={{t="Підказка на вкраденому папері",b="У сутичках із розбійниками Дефіасу в Лісі Елвінн мандрівники нерідко знаходять зім'яту грамоту на землю з підписами Теодора й Верни Фурлброу. На звороті пергаменту корявий почерк розкриває задум розбійників: силою вигнавши літнього фермера з його землі, вони перенесли документ через річку до Елвінну, щоб за його зразком підробляти грамоти на інші захоплені землі. Нашкрябана записка також згадує, що Фурлброу бачили на дорозі просто за кордоном — вони застрягли там зі зламаним возом."},{t="Лихо фермерів Вестфолу",b="Утрата родини Фурлброу — символ трагедії, що охопила Вестфол. Армії Стормвінда немає, ресурси королівства виснажені, і Братство Дефіас вигнало десятки родин із прадідівської землі, силою й юридичними хитрощами зміцнюючи владу над житницею королівства. Хоч Теодор і Верна покидають ферму заради власної безпеки, законна грамота зберігає за ними єдине право на землю проти бунтівників — на випадок, якщо в краї колись знову запанує лад."}},faq={{q="Де знайти цю грамоту?",a="Грамота випадає з різних членів Братства Дефіас, що ховаються на півдні й заході Лісу Елвінн, — скажімо, біля Пристані Джерода чи в місцевих таборах.",al={"де випадає грамота","як отримати грамоту фурлброу","звідки грамота"}},{q="Де шукати Фермера Фурлброу?",a="Фермер Фурлброу та його дружина Верна застрягли біля зламаного воза на головному шляху одразу на в'їзді у Вестфол, невдовзі після мосту, що веде на захід від Лісу Елвінн.",al={"місце фурлброу","куди здати грамоту фурлброу","де фермер"}},{q="Навіщо грамота знадобилася Дефіас?",a="Записка на звороті показує, що бандити збиралися взяти справжню грамоту Фурлброу за зразок, щоб підробляти права на інші володіння в краю й закріпити свою владу над захопленими фермами фальшивими паперами.",al={"чому бандити вкрали грамоту","навіщо дефіас грамоти"}},{q="Чи повертаються Фурлброу на свою ферму?",a="Найближчим часом — ні. Подружжя тікає з краю через беззаконня й напади бандитів. Проте з грамотою в руках вони зможуть законно повернути собі землю, якщо у Вестфолі колись настане спокій.",al={"чи фурлброу повертаються додому","що буде з фермою фурлброу"}},{q="Чому Стормвінд не захищає ці ферми?",a="Стормвінд паралізований раптовим зникненням короля Варіана Рінна й внутрішньою політичною напругою. Королівські сили зосереджені на столиці, тож окраїнні землі на кшталт Вестфолу мусять самі боронитися від Братства Дефіас, що дедалі міцнішає.",al={"чому немає вартових у вестфолі","чому стормвінд ігнорує вестфол"}},{q="Як у цьому завданні пов'язані Елвінн і Вестфол?",a="Це завдання — ниточка, що веде шукачів пригод з Лісу Елвінн за річку, у Вестфол, і показує, як глибоко мережа Дефіас сягає в серцевинні землі королівства.",al={"чому грамота в елвінні","зв'язок між зонами"}}},fp="15,251,22.516.0,32.511.0,26.182.0,25.170.0,52.223.0,42.207.0,43.256.0,65.189.0"}
P.entries["quest:1840"] = {n="Орм Стоунгуф і Жорстокий Шолом",s="Це доручення скеровує молодих воїнів Орди до Тандер Блафа, до майстра-коваля Орма Стоунгуфа. Його рекомендує Тун'ґрім Файрґейз: Орм володіє особливим ремеслом, потрібним, щоб викувати Жорстокий Шолом.",h="Це доручення скеровує молодих воїнів Орди до Тандер Блафа, до майстра-коваля Орма Стоунгуфа.",kw={"орм стоунгуф","жорстокий шолом","тун'ґрім файрґейз","воїн","коваль","тандер блаф","жорстокий обладунок"},ang={["class:Warrior"]="Це завдання знаменує перехід до важкого захисту голови й відсилає воїнів до одного з найкращих майстрів-ковалів Орди.",["faction:Horde"]="Це завдання показує співпрацю між орками — майстрами зброї в Пустках — і ремісниками-тауренами на висотах Тандер Блафа."},sec={{t="Рекомендація в залізі",b="Довівши свою гартованість і зібравши частини Жорстокого Обладунку в Пустках, воїни вирушають вище — до міста на столових горах, Тандер Блафа. Тун'ґрім Файрґейз, сам вправний зброяр, визнає межі свого вміння й відсилає своїх чемпіонів до Орма Стоунгуфа. Ремесло Орма славиться на весь Калімдор, надто ж його вміння виготовляти міцні бойові шоломи з рідкісних трофеїв, здобутих у лютих звірів."},{t="Майстер біля ставка",b="Орм живе й працює на високих кручах Малгору, біля спокійних вод під височенним центральним тотемом міста. Коли приходить воїн із вісткою від Тун'ґріма, Орм відкладає буденну роботу, щоб обговорити вимогливі складники, потрібні для шолома, справді гідного передової Орди."}},faq={{q="Хто такий Орм Стоунгуф?",a="Орм Стоунгуф — вправний таурен-бронник, що живе в Тандер Блафі. Відомий своєю майстерністю, він допомагає воїнам, яких посилає Тун'ґрім Файрґейз, виготовити особливий бойовий шолом.",al={"орм стоунгуф","хто такий орм"}},{q="Де знайти Орма Стоунгуфа?",a="Він у самому серці Тандер Блафа — стоїть біля водойми неподалік величезного центрального тотема міста.",al={"де орм","місце орма стоунгуфа","знайти орма"}},{q="Чому Тун'ґрім Файрґейз посилає до Тандер Блафа?",a="Тун'ґрім може викувати нагрудник та інші частини Жорстокого комплекту, але визнає, що саме Орм Стоунгуф має точні знання, потрібні, щоб зробити Жорстокий Шолом.",al={"чому тандер блаф","чому до орма"}},{q="Що таке Жорстокий Шолом?",a="Жорстокий Шолом — знаковий шолом, який кують для воїнів Орди, що здобули звання ветеранів. Для нього потрібні небезпечні матеріали, здобуті зі звірів по всьому Калімдору.",al={"завдання жорстокий шолом","що таке жорстокий шолом"}},{q="Що Орм просить далі?",a="Щойно ви поговорите з Ормом, він посилає вас по потрібні для шолома мисливські трофеї — почати доведеться з полювання на химер у дикій глушині, щоб здобути ріг химери.",al={"наступне завдання","після орма стоунгуфа","завдання рога химери"}},{q="Чи може це завдання взяти будь-який клас?",a="Ні. Цей ланцюжок завдань — лише для воїнів, які досить просунулися в бойовому вишколі й виконали перші завдання Тун'ґріма щодо обладунку.",al={"чи лише для воїнів","хто може виконати завдання"}}},fp="33,213,24.405.0,23.328.0,21.185.0,33.119.0,54.180.0,24.168.0,27.164.1,30.146.0"}
P.entries["quest:1841"] = {n="Велора Найтлі і Жорстокі Поножі",kw={"велора найтлі","жорстокі поножі","андерсіті","торговий квартал","тун'ґрім файрґейз","воїн"},ang={["faction:Horde"]="Ланцюжок завдань про жорстокий обладунок скріплює молоду Орду: оркам, тролям і тауренам із Калімдору доводиться напряму співпрацювати з майстрами-Відступниками у Східних Королівствах.",["race:Undead"]="Велора Найтлі показує, що Відступники зберегли вишукані культурні вміння й мистецьку спадщину загиблого королівства Лордерон."},sec={{t="Подорож за море",b="Довівши свій гарт старому ковалеві Тун'ґрімові Файрґейзу на його сторожовій кручі в Пустках, воїни беруться збирати славетний жорстокий обладунок. Тун'ґрім не може викувати весь комплект сам і скеровує молодих звитяжців до вправних союзників по всій Орді. По поножі він посилає їх на схід за Велике море, до підземного королівства Відступників, — до майстрині, чию роботу шанували задовго до падіння північних людських королівств."},{t="Мистецтво Велори Найтлі",b="До своєї загибелі під час навали Погибелі на північ Велора Найтлі славилася як одна з найкращих бронниць Королівства Лордерон. Хоч вона втратила смертне життя, а її батьківщину спаплюжено, смерть не применшила її металургійної майстерності. Тепер вона працює в Торговому Кварталі Андерсіті, обертає своє давнє людське ремесло на допомогу воїнам Орди й зберігає сухий, моторошний дотеп щодо свого стану нежиті."}},faq={{q="Хто така Велора Найтлі?",a="Велору Найтлі колись славили як одну з найкращих бронниць королівства Лордерон. Після Третьої війни й воскресіння серед Відступників вона перебралася до Торгового Кварталу Андерсіті, де й далі займається ковальством на користь Орди.",al={"лор велори найтлі","хто така велора","коваль відступників велора"}},{q="Чому Тун'ґрім посилає мене до Андерсіті?",a="While Thun'grim Firegaze oversees your training in the Barrens, crafting the full Brutal Armor set requires specialized artisans across the Horde. He recognizes Velora's unmatched reputation for armor and dispatches you to Lordaeron to commission the legguards directly.",al={"чому до андерсіті","завдання тун'ґріма андерсіті","воїн з пусток до андерсіті"}},{q="Де в Андерсіті знайти Велору Найтлі?",a="Велора Найтлі працює біля горнів у Торговому Кварталі Андерсіті, серед інших майстрів і ковалів, що служать Леді Сильвані Віндраннер.",al={"місце велори найтлі","де велора найтлі","знайти велору найтлі"}},{q="Що далі після розмови з Велорою Найтлі?",a="Velora asks you to collect shinbones from Dragonmaw orcs in the Wetlands so she can use them to craft your Brutal Legguards.",al={"наступне завдання після велори","завдання гомілкових кісток","чого хоче велора"}},{q="Чи жартує Велора про те, що вона нежить?",a="Так. Коли ви здолаєте шлях і заговорите з нею, вона сухо жартує, хто для кого кує обладунок — вона для вас чи навпаки, — і зауважує, що почуття гумору втратила приблизно тоді ж, коли втратила нюх і перестала дихати.",al={"жарти велори","діалог коваля-нежиті","гумор велори"}},{q="Чи Жорстокий обладунок лише для воїнів?",a="Так, випробування Жорстокого обладунку — зокрема й пошуки Велори Найтлі заради поножів — це особливий обряд бойового зростання лише для воїнів Орди, що здобувають досвід.",al={"чи інші класи жорсткий обладунок","жорстокий обладунок лише для воїнів"}}},fp="38,330,24.463.0,29.458.0,21.266.0,40.270.0,48.168.0,43.124.1,49.242.0,34.197.0"}
P.entries["quest:1842"] = {n="Копита сатирів",s="«Копита сатирів» — завдання від троля-ремісника Ула'елека з Села Сен'джин. Щоб викувати пару наділених силою жорстоких латних рукавиць, воїни мають вирушити на північ, в Ашенваль, полювати на сатирів і здобути їхні магічно набряклі, нерозколоті копита.",h="«Копита сатирів» — завдання від троля-ремісника Ула'елека з Села Сен'джин.",kw={"копита сатирів","сатири","ашенваль","ула'елек","сен'джин","рукавиці","воїн"},ang={["class:Warrior"]="Це завдання — частина обряду поступу воїна, що випробовує його бойову стійкість проти хитрих демонічних засідників заради особистих обладунків.",["faction:Horde"]="Це полювання виводить воїнів Орди з посушливих рівнин Дуротару вглиб спірних земель нічних ельфів в Ашенвалі.",["race:Troll"]="Методи Ула'елека показують прагматичну вдачу ремесла Темного Списа: висмоктувати сиру сутність із полеглих магічних ворогів замість покладатися лише на звичайне ковальство."},sec={{t="Приборкання оскверненої сутності",b="Щоб викувати обладунки, здатні змагатися з найжорстокішими силами Калімдору, ремісник Темного Списа Ула'елек дивиться далі за буденне залізо та шкіру. Він посилає майбутніх воїнів на північ, у давні ліси Ашенвалю, де в тутешніх ковенах сатирів гніздиться невигасла демонічна скверна."},{t="Набряк магії Ашенвалю",b="За словами Ула'елека, сатири північно-східного Ашенвалю живляться, висмоктуючи приховану чистоту лісу й обертаючи її на мерзенну силу. Ті демони, що найглибше нажерлися цього позиченого життя, мають неприродно набряклі копита, які втратили природну розколину. Ула'елек має намір витягти цю зосереджену магічну енергію і вплести її просто в рукавиці, які кує."}},faq={{q="Навіщо Ула'елеку копита сатирів?",a="Копита потрібні Ула'елеку, щоб наснажити жорстокі рукавиці, які він кує. Він хоче витягти зосереджену лісову магію, яку сатири висмоктали, спотворили й зібрали у своїх роздутих ногах.",al={"навіщо копита сатирів","призначення копит","для чого копита"}},{q="Де водяться сатири?",a="Вони живуть на північному сході Ашенвалю, гніздяться серед осквернених давніх руїн і живляться рештками магічної енергії глибокого лісу.",al={"де сатири","місце сатирів","де взяти копита сатирів"}},{q="Чим особливе нерозщеплене копито?",a="Відсутність розщепу свідчить, що сатир наситився надмірною кількістю чистої магії Ашенвалю, і його кінцівки розпухли від украденої сили.",al={"лор нерозщепленого копита","чому нерозщеплене","набряклі копита"}},{q="Хто такий Ула'елек?",a="Ула'елек — вправний троль-бронник з Темного Спису, що живе в Селі Сен'джин на півдні Дуротару й допомагає воїнам виготовляти спорядження для випробувань.",al={"хто такий ула'елек","хто дає завдання","троль у сен'джині"}},{q="Який обладунок кує Ула'елек?",a="Він збирається викувати Жорстокі Латні Рукавиці — важкий захист для рук, сповнений украденої магічної сили, для воїнів Орди, що набираються досвіду.",al={"які жорстокі рукавиці","завдання рукавиць","нагорода обладунок"}},{q="Чи служать тутешні сатири Палаючому Легіону?",a="Так. Сатири — давні нічні ельфи, перетворені демонічними угодами, і їхні спільноти, що досі ховаються в лісах Калімдору, й далі поширюють скверну на службі демонічним силам.",al={"вірність сатирів","чи сатири легіон"}}},fp="12,253,28.286.0,30.413.0,36.195.0,27.145.0,36.161.0,16.157.0,31.140.0,44.180.0"}
P.entries["quest:1843"] = {n="Жорстокі Латні Рукавиці",s="«Жорстокі Латні Рукавиці» — вінець ремесла майстра для загартованих воїнів Орди. Коли рідкісні складники зібрано в далеких землях, ремісник Ула'елек виготовляє грізну пару рукавиць, покликаних принести честь і майстру, і носієві.",h="«Жорстокі Латні Рукавиці» — вінець ремесла майстра для загартованих воїнів Орди.",kw={"жорстокі латні рукавиці","рукавиці","ула'елек","воїн","обладунки","ремесло","дуротар"},ang={["class:Warrior"]="Ці рукавиці знаменують перехід воїна до дисциплінованого бойового лідерства і слугують надійною частиною захисного спорядження, викуваного саме для важкого ближнього бою.",["faction:Horde"]="Ремесло Орди тримається на тривкій традиції та бойовій гордості, щоб чемпіони несли в бій духовну вагу й честь своїх майстрів."},sec={{t="Шедевр ремісника",b="Викувати обладунок, гідний загартованого воїна передової, — для ремісників Орди більше ніж просте металоробство: це духовна справа. Ула'елек, ремісник із Дуротару, вкладає свій рід і вміння в ці жорстокі латні рукавиці. Використовуючи загартовані трофеї, здобуті з небезпечних супротивників, він створює обладунок, що витримує люті удари й водночас посилює наступальну міць носія."},{t="Честь предків",b="В орчих і тролячих традиціях добра зброя й обладунки несуть у бій престиж кузні та дух майстра. Вручаючи воїну готові рукавиці, Ула'елек довіряє йому спадщину своїх предків. Від чемпіона, який носить їх у бою, чекають відваги, бойової дисципліни та сили, гідних цієї майстерності."}},faq={{q="Хто такий Ула'елек?",a="Ула'елек — майстер з Дуротару, що допомагає воїнам Орди здобути добротні обладунки на замовлення. Він вимагає незвичних матеріалів, щоб його ковальство шанувало і ремесло, і традиції його предків.",al={"ула'елек","хто дає жорстокі рукавиці","хто дає завдання"}},{q="Навіщо для цих рукавиць знадобилися копита сатирів?",a="Роздуті нерозщеплені копита сатирів зберігають силу, яку ті висмоктали з магії Ашенвалю. Ула'елек витягає цю силу з копит і вкладає її в роботу, тож рукавиці сповнені могутньої магії.",al={"чому копита сатирів","частини сатирів","які матеріали"}},{q="Що для Ула'елека означає, коли хтось носить ці рукавиці?",a="Для Ула'елека ці рукавиці — вершина його майстерності. Довірити їх гідному воїнові — велика честь для його ремесла й предків, що пов'язує його працю з бойовими перемогами Орди.",al={"честь предків","честь ула'елека"}},{q="Де відбувається це завдання?",a="Кування завершується в Дуротарі — посушливому серці земель орків і тролів Темного Спису, де Ула'елек оглядає здобуті матеріали й вручає готовий обладунок.",al={"місце","де здати жорстокі рукавиці"}},{q="Чи це випробування для всіх шукачів пригод?",a="Цей шлях прокладено саме для воїнів передової, які довели свою витривалість і бойову відданість, — він знаменує їхнє зростання до досвідченіших бойових ролей в Орді.",al={"чи лише для воїнів","вимога до класу"}},{q="Що далі після отримання рукавиць?",a="Вручення рукавиць завершує це випробування, і воїн, повністю спорядившись, готовий зустріти більші загрози на розтерзаних війною полях битв Азерота.",al={"наступне завдання","продовження жорстоких рукавиць"}}},fp="16,262,25.416.0,15.367.0,16.212.0,49.203.0,52.214.0,32.168.0,43.180.0,41.182.0"}
P.entries["quest:1845"] = {n="Жорстокий Шолом",s="«Жорстокий Шолом» — кульмінація важкого воїнського випробування, яке веде Орм Стоунгуф на Тандер Блафі. Зібравши рідкісні трофеї звірів по всьому Калімдору, молодий воїн отримує грізний рогатий шолом як свідчення своєї сили.",h="«Жорстокий Шолом» — кульмінація важкого воїнського випробування, яке веде Орм Стоунгуф на Тандер Блафі.",kw={"жорстокий шолом","орм стоунгуф","ріг химери","воїн","тандер блаф","земна мати","обряд посвяти"},ang={["class:Warrior"]="Цей обряд — важлива віха для воїнів Орди: він відкриває їм важкі обладунки, виготовлені з лютих звірів і благословенні досвідченими наставниками-ветеранами.",["faction:Horde"]="Випробування Жорстокого Обладунку гарантує, що чемпіони під стягом Орди мають ту фізичну витривалість і мисливську вправність, якої вимагають від них провідники.",["race:Tauren"]="Шолом, вручений у Тандер Блафі, відображає традицію тауренів перетворювати мисливські трофеї на захисне бойове спорядження під благодаттю Земної Матері."},sec={{t="Обряд воїна",b="Орм Стоунгуф — суворий коваль у Тандер Блафі, що проводить воїнів Орди крізь виснажливі обряди посвяти. Ці випробування вимагають доказів бойової спроможності й кидають учнів у небезпечні краї полювати на лютих звірів і здобувати рідкісні трофеї. Лише тих, хто відповідає суворим вимогам Орма, він приймає, щоб завершити їхній обладунок."},{t="Дар Земної Матері",b="Принісши Ормові Стоунгуфу рідкісний ріг химери, воїн доводить свою рішучість перед лицем дикої природи. На знак визнання Орм вручає йому Жорстокий Шолом — важкий, грізний латний шолом, створений, щоб ушанувати звіра й підсилити власника в бою на передовій. Вручаючи шолом, Орм призиває благословення Земної Матері й наперед тішиться більшими подвигами, які воїнові судилося звершити по всьому Азероту."}},faq={{q="Хто вручає Жорстокий Шолом?",a="Орм Стоунгуф, шанований таурен-коваль з Тандер Блафа, вручає Жорстокий Шолом воїнам Орди, які пройдуть його випробування.",al={"хто дає жорстокий шолом","нпц жорстокий шолом","завдання орма стоунгуфа"}},{q="Яке завдання треба виконати, перш ніж отримати шолом?",a="Треба пройти випробування «Ріг химери»: вполювати лютих звірів у дикій глушині й принести їхній ріг Ормові Стоунгуфу в Тандер Блаф.",al={"передумова жорстокого шолома","завдання рога химери"}},{q="Де перебуває Орм Стоунгуф?",a="Орм Стоунгуф стоїть біля водойми коло великого центрального тотема у високому місті на столових горах — Тандер Блафі.",al={"місце орма стоунгуфа","де орм стоунгуф"}},{q="Чому Орм Стоунгуф звертається до Земної Матері?",a="Як таурен, Орм шанує Земну Матір як творчиню й духовну охоронницю світу. Благословляючи її ім'ям готовий шолом воїна, він виявляє давню віру тауренів у те, що сила в бою має бути врівноважена духовною шанобою.",al={"чому земна мати","земна мати лор"}},{q="Чи відкрите це випробування для будь-якого шукача пригод?",a="Ні. Випробування та його нагороди з Жорстокого обладунку — лише для воїнів Орди, які доводять свою загартованість у класових завданнях.",al={"чи кожен може отримати жорстокий шолом","клас жорстокого шолома"}},{q="Яке значення має комплект Жорстокого обладунку?",a="Частини Жорстокого обладунку уособлюють шлях воїна від новобранця до добірного поборника Орди; їх кують з матеріалів, здобутих з найлютіших хижаків Калімдору.",al={"лор жорстокого обладунку","чому жорстокий шолом"}}},fp="11,259,16.365.0,27.412.0,27.130.0,53.168.0,31.105.0,46.254.0,37.127.0,49.188.0"}
P.entries["quest:1846"] = {n="Гомілкові кістки Драконячої Пащі",s="«Гомілкові кістки Драконячої Пащі» — завдання для воїнів Орди, яке дає зброярка Велора Найтлі в Андерсіті. Щоб викувати міцні Жорстокі Поножі, воїнів посилають у Багнокрай по надзвичайно товсті гомілкові кістки ворожих орків Драконячої Пащі.",h="«Гомілкові кістки Драконячої Пащі» — завдання для воїнів Орди, яке дає зброярка Велора Найтлі в Андерсіті.",kw={"гомілкові кістки драконячої пащі","велора найтлі","жорстокі поножі","драконяча паща","багнокрай","каз модан","воїн"},ang={["class:Warrior"]="Це випробування перевіряє і вашу фізичну витривалість у полі, і готовність збирати моторошні матеріали заради кращого обладунку.",["faction:Horde"]="Розбиваючи клан-ренегат Драконячої Пащі в Каз Модані, ви послаблюєте небезпечні рештки Старої Орди й додаєте сили героям нового союзу Тралла.",["race:Orc"]="Для орків, вірних Оргріммару, винищення нерозкаяних орків Драконячої Пащі — суворе нагадування про скверну в минулому їхнього народу й криваву ціну спокути.",["race:Undead"]="Те, як прагматично Велора Найтлі використовує людиноподібні рештки, — взірець мислення Відступників: будь-який доступний ресурс, хай який моторошний, можна обернути на зброю."},sec={{t="Моторошний каркас",b="Обладунок, гідний загартованого воїна передової, потребує незвичних матеріалів. Узявшись виготовити Жорстокі Поножі, зброярка-Відступниця Велора Найтлі вимагає опорної скоби з товстої, тривкої кістки. Замість звичайних звірів вона спрямовує молодих воїнів до орків Драконячої Пащі в Багнокраї: їхні щільні кістяки дають потрібну міцність, щоб витримати важкі удари в бою."},{t="Перевірка на злам",b="Здобути кістки Драконячої Пащі — лише половина справи. Велора велить воїнам власноруч перевіряти кожну кістку просто на місці: будь-який зразок, що ламається в голих руках, для кузні зовсім непридатний. Воїни мусять обнишпорити табори ренегатів серед скель Багнокраю, ламаючи слабкі кістки, доки вісім справді міцних не витримають випробування силою."}},faq={{q="Чому Велорі Найтлі потрібні саме гомілкові кістки орків?",a="Велорі потрібен щільний, товстий матеріал, щоб зробити з нього опорний каркас для Жорстоких Поножів. Вона вважає, що орки Драконячої Пащі з Багнокраю підходять якнайкраще: їхній важкий, потужний кістяк дає набагато більшу жорсткість, ніж звичайна дичина чи знайдені рештки.",al={"чому гомілкові кістки орків","чому кістки драконячої пащі","кістяний обладунок велори"}},{q="Чому воїни Орди можуть вільно полювати на орків Драконячої Пащі?",a="Рештки клану Драконячої Пащі, що засіли в Багнокраї, — ворожі ренегати, які чіпляються за темну спадщину Другої війни. Вони не визнають сучасної Орди Тралла, тож вважаються ворогами держави й законною здобиччю для шукачів пригод з Орди.",al={"чи драконяча паща в орді","чому битися з драконячою пащею","становище драконячої пащі в орді"}},{q="Де шукати орків Драконячої Пащі для цього завдання?",a="Вони живуть у Багнокраї, на південь від Аратійського нагір'я за Мостом Тандол. Воїни зазвичай полюють на них серед гірських круч біля Табору Анґерфанґ, на південний захід від головного північного шляху.",al={"місце драконячої пащі","де гомілкові кістки драконячої пащі","місце табору ангерфанґ"}},{q="Чому під час завдання стільки кісток ламається?",a="Для кування обладунку Велорі потрібні лише найщільніші кістки. За її настановами воїни перевіряють кожну кістку руками: та, що ламається від звичайної сили, надто крихка, щоб захистити ноги воїна в бою, і її викидають.",al={"зламані гомілкові кістки","чому кістки ламаються","перевірка міцної кістки"}},{q="Хто така Велора Найтлі?",a="Велора Найтлі — бронниця з Відступників, що працює в Андерсіті. Сувора, з моторошно сухим гумором і схильністю до похмурих жартів, вона допомагає воїнам Орди виготовляти особливе бойове спорядження для загартованих ветеранів.",al={"лор велори найтлі","хто така велора","збройник андерсіті"}},{q="Яку частину обладунку кують з цих кісток?",a="Зібрані кістки стають внутрішнім каркасом Жорстоких Поножів — міцних кольчужних поножів для воїнів Орди середнього рівня.",al={"нагорода за гомілкові кістки","навіщо гомілкові кістки","жорстокі поножі"}}},fp="19,266,19.437.0,18.377.0,55.285.0,56.245.0,44.222.0,51.239.0,21.229.0,44.141.0"}
P.entries["quest:1848"] = {n="Жорстока Кольчуга",s="«Жорстока Кольчуга» — завершення виснажливого обряду посвяти для воїнів Орди в Пустках. Зібравши рідкісні матеріали й довівши свій гарт у сутичках із небезпечними ворогами в різних краях, воїни приносять здобуте відлюдькуватому ковалеві Тун'ґрімові Файрґейзу. Натомість він викує міцну кольчугу, що витримає найзапекліші бої.",h="«Жорстока Кольчуга» — завершення виснажливого обряду посвяти для воїнів Орди в Пустках.",kw={"жорстока кольчуга","тун'ґрім файрґейз","жорстокий обладунок","воїн","ковальство","пустки"},ang={["class:Warrior"]="Жорстока Кольчуга — визначне досягнення для молодих воїнів Орди: вона знаменує перехід від зеленого новобранця до загартованого бійця в кольчузі, викуваній саме для нього.",["faction:Horde"]="Викувана з трофеїв, здобутих кров'ю в диких краях Калімдору, кольчуга відбиває головні чесноти Орди — бойову самостійність і силу.",["profession:Blacksmithing"]="Спостерігати за роботою Тун'ґріма — це урок традиційного оркського ковальства, де бойовий дух і стійкість вковують просто в сталь."},sec={{t="Шедевр коваля",b="На скелястих пагорбах півночі Пусток Тун'ґрім Файрґейз кує обладунки далеко не для кожного. Відлюдькуватий орк вимагає, щоб молоді воїни обійшли далекі краї й здобули міцні частини звірів, рідкісний метал і алхімічні реагенти, — і лише тоді він береться роздмухувати міхи. Готова кольчуга — не просто захисне спорядження, а незнищенна відзнака витривалості й гарту, яку впізнають бувалі бійці по всій Орді."},{t="Викувана в злигоднях",b="Доручення Тун'ґріма навмисно суворе. Справжня зброя й обладунок Орди мають від самого народження нести піт і кров свого власника. Вручаючи готову Жорстоку Кольчугу, коваль не сипле квітчастими похвалами — лише чекає, що обладунок проявить себе в жорстокому бою й повернеться з оповідями про кров і честь."}},faq={{q="Що таке Жорстока Кольчуга?",a="Жорстока Кольчуга — міцний нагрудник, викуваний на замовлення орком-ковалем Тун'ґрімом Файрґейзом. Це найвища нагорода для воїнів Орди, які доводять свою бойову вправність, збираючи рідкісні матеріали в кількох небезпечних краях.",al={"що таке жорстока кольчуга","завдання жорстокої кольчуги","хто кує жорстоку кольчугу"}},{q="Хто такий Тун'ґрім Файрґейз?",a="Тун'ґрім Файрґейз — відлюдний коваль-ветеран, що живе на гірському відрозі в північних Пустках, трохи на схід від шляху між Перехрестям і Оргріммаром. Він випробовує молодих воїнів і кує їм особливі обладунки, коли ті доведуть, що на них заслуговують.",al={"хто такий тун'ґрім","тун'ґрім файрґейз","де тун'ґрім"}},{q="Чому Тун'ґрім вимагає стільки зусиль, перш ніж викувати обладунок?",a="У традиції воїнів Орди труднощі важать не менше за бойову вправність. Тун'ґрім вважає, що добротна кольчуга змарнується на тому, хто не пролив власної крові й не тяжко трудився, щоб здобути рідкісні складники для її кування.",al={"чому збирати стільки матеріалів","вимоги жорстокого обладунку","випробування тун'ґріма"}},{q="Куди веде цей ланцюжок завдань далі?",a="Це завдання — останній крок випробувань Жорстокого обладунку. Коли Тун'ґрім вручить вам готову кольчугу, його робота для вас завершена, і ви можете йти в ній у бій по всьому Калімдору й Східних Королівствах.",al={"що після жорстокої кольчуги","наступне завдання після жорстокої кольчуги","чи є продовження"}},{q="Чи доступне завдання про Жорстоку Кольчугу Альянсу?",a="Ні. Жорстока Кольчуга — випробування лише для Орди. Воїни Альянсу проходять окремий бойовий обряд за участю ковалів Айронфорджа й довколишніх дворфійських земель, щоб здобути власний знаковий обладунок.",al={"чи альянс отримає жорстоку кольчугу","аналог для альянсу","чи лише для орди"}},{q="Де в Пустках знайти Тун'ґріма?",a="Тун'ґрім живе на високому хребті в північних Пустках, на південь від Річки Південної Люті й трохи на схід від головного гірського шляху, що веде на північ до Дуротару.",al={"місце тун'ґріма","де тун'ґрім у пустках","як знайти тун'ґріма"}}},fp="14,363,21.433.0,18.356.0,27.241.0,26.255.0,68.223.0,38.233.0,54.212.0,44.169.0"}
P.entries["quest:1858"] = {n="Розтрощена Рука",s="Це випробування розбійника — останній крок посвяти в лави Розтрощеної Руки в Оргріммарі. Терзок доручає розбійникам-початківцям відімкнути здобуту сумку, витягнувши ключ у нічого не підозрюваного спільника.",h="Це випробування розбійника — останній крок посвяти в лави Розтрощеної Руки в Оргріммарі.",kw={"розтрощена рука","терзок","ґамон","тазан","обчищання кишень","розбійник"},ang={["class:Rogue"]="Цей обряд посвяти вчить основ розбійницького ремесла: вистежити неуважну ціль у людному місці, непомітно витягти ключ і здобути важливі відомості.",["faction:Horde"]="Під бойовою честю нової Орди Тралла криється потреба в таємній розвідці, яку тихо веде Розтрощена Рука глибоко в Оргріммарі."},sec={{t="Випробування спритності",b="Здобувши замкнену сумку Тазана, розбійники-початківці бачать, що без ключа вона нічого не варта. Замість ламати хитрий замок грубою силою, Розтрощена Рука вимагає справжнього вміння. Терзок вказує посвяченим на Ґамона — неуважного п'яничку-таурена, що частенько засиджується в таверні Оргріммара й раніше допомагав Тазанові: ідеальна жертва для тихої крадіжки."},{t="Ласкаво просимо в тінь",b="Звільнивши Ґамона від ключа так, щоб не сполошити всю таверну, посвячений відмикає сумку й забирає журнал Тазана. Принісши здобуте Терзокові в Тіньову Розколину, він задовольняє суворі вимоги гільдії. Чисто виконавши роботу, кандидат офіційно стає визнаним агентом Розтрощеної Руки."}},faq={{q="Хто такий Ґамон і чому ключ у нього?",a="Ґамон був помічником Тазана — агента, чию торбу розслідує Терзок. Торбу Тазан носив при собі, а ключ залишив Ґамонові, нічого не підозрюючому пияку, який днями просиджує в головній корчмі Оргріммара.",al={"чому ґамон","у кого ключ","ключ ґамона"}},{q="Що в торбі Тазана?",a="У замкненій торбі лежить журнал Тазана. У ньому відомості, що цікавлять Терзока й Розтрощену Руку, а здобувши його, новачок доводить, що вміє таємно добувати важливі дані.",al={"журнал тазана","вміст торби","що в торбі"}},{q="Що таке Розтрощена Рука в Оргріммарі?",a="Колись це був сумнозвісний орчий клан з Дренору, відомий самокалічінням і безжальністю, а в Оргріммарі Розтрощена Рука стала головною гільдією вбивць, шпигунів і розбійників Орди, що діє з підземної Тіньової Розколини.",al={"що таке розтрощена рука","розбійники розтрощеної руки","розбійники оргріммара"}},{q="Де працює Терзок?",a="Терзок працює в Тіньовій Розколині — сутінковій мережі печер, схованій під скелястими хребтами Оргріммара, де подалі від денного світла процвітають чорнокнижники, розбійники й мистецтво тіні.",al={"де терзок","місце терзока","тренер розбійників тіньової розколини"}},{q="Чому Терзок просто не розкриє торбу силою?",a="Торба має складний замок, але головне — це перевірка дисципліни розбійника. Розтрощена Рука цінує точну, витончену крадіжку, а не галасливе нищення.",al={"чому красти кишенею","чому потрібен ключ"}},{q="Що буде після цього завдання?",a="Це доручення завершує ланцюжок посвяти. Віддавши журнал Тазана, ви стаєте визнаним членом Розтрощеної Руки й отримуєте знаряддя, що знадобиться у ваших майбутніх таємних справах.",al={"нагорода розтрощеної руки","кінець ланцюжка"}}},fp="18,216,18.387.0,22.353.0,42.243.0,31.216.0,40.250.0,27.179.0,48.194.0,30.223.1"}
P.entries["quest:1859"] = {n="Терзок",s="Терзок — виклик для обдарованих розбійників Орди, що діють біля Долини Випробувань і Села Сен'джин. Наставник розбійників Каплак помічає ваш хист до насильства й потайливості й нишком скеровує вас до печерної Тіньової Розколини, на зустріч з агентом Розтрощеної Руки.",h="Терзок — виклик для обдарованих розбійників Орди, що діють біля Долини Випробувань і Села Сен'джин.",kw={"терзок","каплак","розтрощена рука","тіньова розколина","розбійник","дуротар"},ang={["class:Rogue"]="Цей виклик знаменує ваш офіційний вступ до Розтрощеної Руки й пов'язує вашу самотню роботу в Дуротарі з організованою шпигунською мережею, що діє по всій Орді.",["faction:Horde"]="Хоч Тралл проповідує честь і дух воїна, існування Терзока та його мережі доводить, що Орда розуміє практичну потребу в невидимих клинках і таємних збирачах відомостей."},sec={{t="Виклик пошепки",b="Не всі слуги нової Орди б'ються при денному світлі під стягом Траллової честі. Коли юні розбійники починають здобувати собі ім'я в Дуротарі, Каплак відводить їх убік і стиха заводить розмову. Звістка про агента, що поєднує смертоносну вправність із готовністю обходити правила відкритої війни, швидко доходить до вух підпільної гільдії в Оргріммарі."},{t="У Тіньову Розколину",b="Каплак посилає посвяченого глибоко під червоні кам'яні кручі Оргріммара, у Тіньову Розколину. Подалі від пильних очей міської варти в сутінках чекає Терзок. Ця зустріч — точка посвяти: вона приводить самотніх кишенькових злодіїв і майстрів засідок у впорядковані лави Розтрощеної Руки — таємної мережі, що служить Орді кинджалами в темряві."}},faq={{q="Хто такий Терзок?",a="Терзок — агент Розтрощеної Руки, що працює в підземній Тіньовій Розколині в Оргріммарі. Він оцінює перспективних молодих розбійників, які приходять з тренувальних таборів Дуротару, і приймає їх на службу гільдії.",al={"хто такий терзок","терзок лор","нпц терзок"}},{q="Чому Каплак посилає мене до нього?",a="Каплак бачить, що ви вправні в бою й маєте хист до скрадання та хитрощів. Знаючи, що Розтрощена Рука завжди шукає здібних шибайголів для поповнення лав, він передає вам Терзокове запрошення.",al={"чому до терзока","завдання каплака","чому в оргріммар"}},{q="Що таке Розтрощена Рука в Оргріммарі?",a="Назва походить від давнього клану з Дренору, але в сучасному Оргріммарі Розтрощена Рука — таємна гільдія вбивць, шпигунів і злодіїв на службі Орди. Вони беруться за потрібну, але морально неоднозначну роботу, якої шляхетні воїни Тралла не можуть виконувати відкрито.",al={"що таке розтрощена рука","розтрощена рука оргріммар","гільдія розбійників орди"}},{q="Де розташована Тіньова Розколина?",a="Тіньова Розколина — величезна печера під центром Оргріммара, до якої ведуть темні проходи з Долини Сили й Долини Честі. Там, подалі від чужих очей, живуть міські чорнокнижники й розбійники.",al={"де тіньова розколина","як знайти терзока","місце тіньової розколини"}},{q="Що далі після зустрічі з Терзоком?",a="Привітавшись, Терзок одразу знайомить вас з обов'язками служби в Розтрощеній Руці й дає завдання, щоб ви довели свою вправність, уміння скрадатися й відданість мережі.",al={"наступне завдання","чого хоче терзок","після терзока"}},{q="Чи отримують це завдання не розбійники?",a="Ні. Це завдання пропонують лише розбійникам, які набралися певного досвіду; воно знаменує їхній перехід від місцевих сутичок до офіційної служби в розвідувальній мережі Орди.",al={"чи інші класи можуть це","чи лише для розбійників","завдання розбійника"}}},fp="7,282,19.368.0,24.369.0,15.228.0,31.243.0,40.284.0,37.237.0,33.190.0,33.200.0"}
P.entries["quest:1860"] = {n="Поговори з Дженнеєю",s="«Поговори з Дженнеєю» — вступний виклик для магів-новачків Альянсу, які переросли початкове навчання в Лісі Елвінн. За дорученням наставника Залдімара Вефгеллта з Ґолдширу учні мають з'явитися просто до Дженнеї Кеннон у Святилище Чародія в Стормвінді.",h="«Поговори з Дженнеєю» — вступний виклик для магів-новачків Альянсу, які переросли початкове навчання в Лісі...",kw={"поговори з дженнеєю","дженнея кеннон","залдімар вефгеллт","святилище чародія","маг","ґолдшир"},ang={["class:Mage"]="Це доручення знаменує ваш перехід від сільського чарування в Ґолдширі до офіційної участі в справах вищих магів, що працюють у Святилищі Чародія в Стормвінді.",["faction:Alliance"]="Безпека Лісу Елвінн і Стормвінда тримається не лише на піхоті, а й на пильності тайної магії, за якою стежать просто зі столичної магічної академії."},sec={{t="Виклик до Святилища Чародія",b="Щойно учень-маг виявить достатню майстерність у простих заклинаннях у Ґолдширі, Залдімар Вефгеллт розуміє: польова наука під проводом місцевих наставників вичерпала себе. Замість того щоб без кінця затримуватися в селищах Елвінна, здібних чарівників скеровують до самого Стормвінда. У серці Кварталу магів здіймається Святилище Чародія — просторий осередок тайних досліджень і навчання, де старші маги королівства керують ширшими магічними справами."},{t="Справи безпеки королівства",b="Залдімар наголошує: з'явитися до Стормвінда — це куди більше, ніж звичайне переведення на вищий щабель навчання. Виникла конкретна справа, що безпосередньо стосується безпеки і Лісу Елвінн, і Стормвінда. Прибувши, учень доповідає Дженнеї Кеннон — досвідченій чарівниці, що відає важливими місцевими дорученнями. Дженнея тримається стримано й обережно, не поспішаючи відкривати великі таємниці щойно прибулому учневі, але саме з цієї зустрічі починається безпосереднє служіння ордену чарівників."}},faq={{q="Хто посилає мене на це завдання?",a="Залдімар Вефгеллт, наставник магів з людей у Корчмі «Лев'яча Гордість» у Ґолдширі, дає це завдання, щойно ви досягнете достатньої чародійської вправності.",al={"хто дає завдання","хто починає завдання","залдімар"}},{q="Де знайти Дженнею Кеннон?",a="Дженнея Кеннон перебуває у Святилищі Чародія в центрі Кварталу магів Стормвінда. Вона навчається в містичних залах святилища.",al={"місце дженнеї кеннон","де дженнея","знайти дженнею"}},{q="Що таке Святилище Чародія?",a="Святилище Чародія — знана магічна вежа в Кварталі магів Стормвінда. Це головна академія, бібліотека й осередок магів і вчених-чародіїв королівства.",al={"що таке святилище чародія","вежа магів стормвінд"}},{q="Чому Залдімар посилає мене до Дженнеї, а не займається цим сам?",a="Залдімар навчає молодих магів основ у Ґолдширі, а за більшими загрозами в краю й особливими завданнями, що стосуються королівства, наглядають вищі за рангом учені зі столиці, як-от Дженнея Кеннон.",al={"чому до стормвінда","чому дженнея"}},{q="Що буде, коли з'явитися до Дженнеї Кеннон?",a="Щойно ви з'явитеся до Дженнеї, вона доручить вам дослідити загадкові магічні аномалії довкола Дзеркального Озера в Лісі Елвінн.",al={"що далі","наступне завдання","наступний крок"}},{q="Чи доступне це завдання будь-якому класу?",a="Ні. Це завдання — лише для магів; це класовий обряд посвяти, що переводить учня з сільського навчання до офіційних лав чародійської спільноти Стормвінда.",al={"чи не маги можуть це","лише для магів","вимога до класу"}}},fp="17,310,30.503.0,27.490.0,27.159.0,31.170.0,29.189.0,67.208.0,46.135.1,37.190.0"}
P.entries["quest:1861"] = {n="Дзеркальне Озеро",s="«Дзеркальне Озеро» — вступне дослідницьке завдання для магів-початківців Альянсу, які навчаються в Кварталі магів Стормвінда. За дорученням Дженнеї Кеннон підмайстри вирушають на південний захід від міської брами, щоб узяти пробу води з водоспаду Дзеркального Озера на залишкове магічне забруднення.",h="«Дзеркальне Озеро» — вступне дослідницьке завдання для магів-початківців Альянсу, які навчаються в Кварталі...",kw={"дзеркальне озеро","маг","дженнея кеннон","святилище чародія","проба води","стормвінд"},ang={["class:Mage"]="Це завдання знаменує перехід підмайстра від запилюжених фоліантів у Святилищі Чародія до дослідження справжніх магічних явищ, і винагородою стає перший справжній посох мага або куля для другої руки.",["faction:Alliance"]="Дбати про безпеку природних багатств Елвінну — один із непомітних способів, якими маги Святилища Чародія оберігають серце королівства.",["race:Human"]="Дзеркальне Озеро живить довколишні поля й річки Елвінну, тож його чистота життєво важлива для щоденного здоров'я мешканців Стормвінда."},sec={{t="Лей-лінії та зміщені потоки",b="За останні десятиліття Азерот пережив катастрофічні магічні потрясіння — від відкриття Темного Порталу до Третьої війни й битви біля Гори Гіджал. Ці жорстокі удари зірвали прадавні чародійські потоки з їхніх колись стійких русел. У Святилищі Чародія в Стормвінді маги на кшталт Дженнеї Кеннон пильно стежать за цими зсувами, побоюючись, що зміщені потоки магічної сили просочаться в довколишні нетрі й отруять місцеву природу."},{t="Проба води",b="Дзеркальне Озеро притулилося під скелями на південний захід від брами Стормвінда й слугує головним природним водосховищем, яке живлять гірські водоспади. Від цих вод залежить уся округа, тож Дженнея посилає магів-новачків зі скляною пляшкою просто до підніжжя водоспаду. Зібрані свіжі бризки дають Святилищу змогу провести тонкі ворожіння й реагентні проби, щоб з'ясувати, чи не почала дика магія просочуватися в питну воду."}},faq={{q="Навіщо Дженнеї Кеннон зразок води з Дзеркального Озера?",a="Великі магічні війни по всьому Азероту порушили природні лей-потоки. Дженнея Кеннон боїться, що збурена чародійська енергія просочується в підземні води довкола Стормвінда, а це може зашкодити кожному, хто п'є з озера.",al={"навіщо вода дзеркального озера","зразок води дженнеї","мета завдання"}},{q="Де саме Дзеркальне Озеро?",a="Дзеркальне Озеро лежить на північному заході Лісу Елвінн, тулячись до високих круч трохи на південний захід від головної брами Стормвінда. Потрібний зразок беруть з водойми біля підніжжя його каскадного водоспаду.",al={"де дзеркальне озеро","місце дзеркального озера","знайти дзеркальне озеро"}},{q="Що буде, якщо вода отруєна?",a="Дженнея боїться, що коли довго пити воду, отруєну магією, це зашкодить тим, хто залежить від озера. Точні наслідки поки невідомі.",al={"чи вода отруєна","що якщо вода магічна","наслідки магічної скверни"}},{q="Хто може взятися за це доручення?",a="Це доручення — саме для магів-початківців Альянсу; це одне з їхніх перших практичних польових завдань для Святилища Чародія.",al={"хто отримує завдання дзеркального озера","чи дзеркальне озеро лише для магів"}},{q="Чи веде це завдання до подальших розслідувань?",a="Воно завершує перше доручення, що почалося з виклику Дженнеї Кеннон: учень отримує своє перше офіційне знаряддя мага й обов'язок стежити за магічними збуреннями по всьому королівству.",al={"що після дзеркального озера","ланцюжок дзеркального озера"}},{q="Що взагалі розхитало магічні потоки?",a="Дженнея пояснює зміну потоків великими магічними битвами світу, не називаючи якоїсь конкретної битви чи події.",al={"чому зіпсовані магічні лінії","сенс містичної боротьби","що зламало магію"}}},fp="11,279,31.453.0,18.464.0,60.237.0,29.215.0,37.141.0,31.177.0,47.214.0,67.127.0"}
P.entries["quest:1879"] = {n="Поговори з Бінк",s="«Поговори з Бінк» — виклик Альянсу, що скеровує магів-новачків із Дун Мороґу до столиці, Айронфорджа. Надісланий Маґісом Спаркмантлом, він посилає перспективних заклиначів на допомогу Бінк, дослідниці таємних мистецтв, що працює в Залі Таїнств.",h="«Поговори з Бінк» — виклик Альянсу, що скеровує магів-новачків із Дун Мороґу до столиці, Айронфорджа.",kw={"поговори з бінк","бінк","маґіс спаркмантл","маг","зала таїнств","містичний квартал","айронфордж"},ang={["class:Mage"]="Цей виклик знаменує ваш відхід від вступного вишколу в долині до ширших справ учених чародіїв Айронфорджа.",["faction:Alliance"]="Спільні студії в Залі Таїнств показують тісне поєднання гномського розуму й дворфійської гостинності під прапором Альянсу.",["race:Gnome"]="Бінк і Маґіс Спаркмантл утілюють продовження гномської традиції таємних мистецтв у гостинних залах Айронфорджа після втрати Гномреґану."},sec={{t="Виклик від колеги",b="Маги-новачки, що навчаються серед холодних скель Дун Мороґу, зрештою потрапляють на око Маґісу Спаркмантлу. Помітивши, що учень переріс елементарні вправи довкола Хараноса, Спаркмантл передає слово від своєї колеги, Бінк. Прохання точне й безкомпромісне: Бінк потрібен фахівець із таємних мистецтв, і вона відмовляється довіряти справу будь-кому, хто не володіє магією."},{t="Зала Таїнств",b="Завдання веде молодих магів до Кварталу містиків Айронфорджа, де вчені, жерці й чародії збираються під високими кам'яними склепіннями Зали Таїнств. Тут Бінк веде свої студії, оцінюючи прибулих учнів гострим поглядом. На її думку, сирий потенціал — лише початок: недисциплінований заклинач у таємних справах швидко стає небезпекою, а не помічником."}},faq={{q="Хто дає це завдання?",a="Маґіс Спаркмантл пропонує це завдання магам-початківцям Альянсу, які просунулися в першому навчанні в Дун Мороґу.",al={"хто дає завдання","де почати","хто дає поговори з бінк"}},{q="Де знайти Бінк?",a="Бінк перебуває в Залі Таїнств, що в Кварталі містиків на півночі Айронфорджа.",al={"місце бінк","де бінк","знайти бінк"}},{q="Чому Бінк потрібен саме маг?",a="Бінк проводить дослідження, пов'язане безпосередньо з чародійською енергією й чутливим вимірювальним обладнанням. Вона вважає, що не маги не впораються з магічними тонкощами й небезпеками цієї справи.",al={"чому лише маги","вимога до магів","бінк хоче лише магів"}},{q="Що буде після зустрічі з Бінк?",a="Привітавшись і оцінивши ваші здібності, Бінк залучає вас до свого дослідження — далі йде завдання «Магонезрівнянний Гізмонітор».",al={"наступне завдання","продовження бінк","що після бінк"}},{q="Чи доступне це завдання іншим класам, крім магів?",a="Ні. Це завдання створене лише для магів як перехід від місцевого навчання до особливих доручень у столиці.",al={"чи інші класи можуть це","чи лише для магів","специфічне для магів"}},{q="Що таке Зала Таїнств?",a="Зала Таїнств — осередок чародійських і святих наук в Айронфорджі, де працюють наставники, учені й дослідники магічних мистецтв і дворфів, і гномів.",al={"зала таїнств айронфордж","що таке зала таїнств"}}},fp="15,259,21.388.0,21.404.0,21.113.0,22.108.0,31.192.0,32.141.0,52.134.0,30.172.0"}
P.entries["quest:1881"] = {n="Поговори з Анастасією",s="«Поговори з Анастасією» — вступний виклик, що скеровує перспективних магів-Відступників до Анастасії Гартвелл в Андерсіті. Наставник магів Кейн Файрсонг посилає молодого заклинача до Магічного Кварталу, щоб той узявся за важливу роботу для магів Відступників. Цей короткий виклик готує ґрунт для розслідувань у спустошених землях Галявин Тірісфалю.",h="«Поговори з Анастасією» — вступний виклик, що скеровує перспективних магів-Відступників до Анастасії Гартвелл...",kw={"поговори з анастасією","анастасія гартвелл","кейн файрсонг","магічний квартал","маг","андерсіті"},ang={["class:Mage"]="Це завдання знаменує ваш перехід від початкового магічного навчання до активної служби магам Андерсіті.",["race:Undead"]="Для магів-Відступників поклик Гартвелл — нагода обернути інтелектуальне минуле Лордерона проти його теперішніх небезпек."},sec={{t="Поклик до Магічного Кварталу",b="Коли молоді заклиначі відточують перші вміння під наглядом Кейна Файрсонга, невдовзі їх скеровують глибше в столицю. Маги Відступників мають власний осередок у Магічному Кварталі Андерсіті, де провадять і магічні студії, і стратегічну оборону всього Лордерона. Кейн Файрсонг оцінює учнів: звичайних новачків він відсіює, а тих, хто виявляє справжній хист, посилає просто до старших майстрів, яким потрібні вправні помічники в полі."},{t="Задуми Анастасії Гартвелл",b="Анастасія Гартвелл — одна з чільних наставниць магів в Андерсіті. Вона не лишає здібних учнів у безпеці вивчати дрібні заклинання, а не гаючи часу залучає їх до служби земельним і практичним інтересам Відступників. Відгукнутися на її виклик — це і обряд посвяти для знавців магії, і вступ до похмурих, прагматичних магічних пошуків, якими живе нежить, що вирвалася з-під влади Погибелі."}},faq={{q="Хто посилає поговорити з Анастасією Гартвелл?",a="Кейн Файрсонг, наставник магів з Відступників, посилає вас до неї, побачивши, що ваш чародійський хист достатньо розвинений, щоб допомагати в складніших справах у столиці.",al={"хто дає поговори з анастасією","хто дає завдання поговори з анастасією","виклик кейна файрсонґа"}},{q="Де знайти Анастасію Гартвелл?",a="Анастасія Гартвелл перебуває в Магічному Кварталі Андерсіті, де керує практиками чародійських мистецтв серед Відступників і навчає їх.",al={"де анастасія гартвелл","місце анастасії гартвелл","знайти анастасію"}},{q="Яка мета цього виклику?",a="Анастасія шукає вправного чарівника для практичних доручень за міськими мурами — почати доведеться з польових завдань у Галявинах Тірісфалю, як-от обстежити Хутір Балнірів.",al={"чому вона мене кличе","мета поговори з анастасією","що потрібно анастасії"}},{q="Яке завдання йде після «Поговори з Анастасією»?",a="З'явившись до Анастасії, ви одразу отримуєте завдання «Ферма Балнірів», яке відправляє вас на схід Галявин Тірісфалю по левову пащу з городу хутора.",al={"яке завдання далі","наступне завдання після анастасії","продовження анастасії"}},{q="Чи це завдання лише для певних класів?",a="Так, це завдання призначене саме для магів-Відступників — це сходинка на класовому шляху, коли вони здобувають першу вправність десь на десятому рівні.",al={"чи це завдання лише для магів","хто може поговорити з анастасією","вимога до класу"}},{q="Чому маги-Відступники мають в Андерсіті власний квартал?",a="Магічний Квартал — окреме пристановище, де чародії, чорнокнижники й дослідники з Відступників можуть навчатися й чаклувати подалі від решти міста, продовжуючи свої давні, ще з часів до Третьої війни, традиції в надрах Лордерону.",al={"чому квартал магів","маги відступників андерсіті"}}},fp="20,370,27.494.0,29.442.0,47.178.0,38.152.0,36.183.0,40.160.0,41.163.0,67.227.0"}
P.entries["quest:1882"] = {n="Ферма Балнірів",s="«Ферма Балнірів» — одне з перших випробувань для молодих магів-Відступників, яке дає Анастасія Гартвелл у Магічному Кварталі Андерсіті. Учнів посилають на схід Галявин Тірісфалю по ротики з покинутого хутора, що стоїть небезпечно близько до кордону Чумних Земель. Квіти слугують барометрами магічної скверни, яка підповзає зі сходу, спустошеного Погибеллю.",h="«Ферма Балнірів» — одне з перших випробувань для молодих магів-Відступників, яке дає Анастасія Гартвелл у...",kw={"ферма балнірів","хутір балнірів","ротики балніра","анастасія гартвелл","західні чумні землі","галявини тірісфалю","маг"},ang={["class:Mage"]="Це раннє випробування вчить магів-початківців, що їхні магічні студії конче потрібні, аби стежити за чужою магічною скверною й боронитися від неї.",["profession:Herbalism"]="Ротики Балніра — приклад того, як рослини можуть водночас накопичувати магічне забруднення й показувати його рівень.",["race:Undead"]="Для Відступників захист кордонів Галявин Тірісфалю від навали Погибелі — питання негайного виживання й незалежності."},sec={{t="Магічний барометр",b="Поки Королівське Аптекарське Товариство здебільшого вивчає дію некромантії й розкладу, маги Відступників і самі пильно стежать за прикордонням. Анастасія Гартвелл доручає заклиначам-початківцям вирушити на Хутір Балнірів на сході Галявин Тірісфалю. Ротики, що ростуть у садах хутора, від природи чутливі до мінливих магічних потоків і вбирають розлиту довкола енергію з ґрунту й повітря. Вивчаючи ці квіти, учені-маги в Андерсіті можуть виміряти, чи не просочилася заразна скверна володінь Короля-Ліча крізь заслін у сам Тірісфаль."},{t="Східний кордон",b="Хутір Балнірів стоїть на краю галявин, неприємно близько до поораної заразою глушини Західних Чумних Земель. Відступники розуміють, що чума Короля-Ліча — некерована руйнівна сила, яка гноїть саму землю. Хоч Відступники й самі вдаються до темних мистецтв, нестримна скверна Погибелі загрожує їхнім кордонам і безпеці. Анастасія має намір передати зібрані ротики аптекарям, поєднавши магічні спостереження з алхімічними дослідами, щоб захистити відвойоване серце Лордерона."}},faq={{q="Чому Анастасії Гартвелл потрібна саме левова паща?",a="Левова паща з Хутора Балнірів має особливу природну чутливість до навколишніх магічних сил. Оскільки ці квіти вбирають енергію просто із землі й повітря, вивчивши їх, маги-Відступники можуть з'ясувати, чи не отруює чародійська й некромантська пошесть сусідніх Чумних Земель Галявини Тірісфалю.",al={"чому левова паща","призначення левової пащі балнірів","для чого левова паща"}},{q="Де розташований Хутір Балнірів?",a="Хутір лежить на сході Галявин Тірісфалю, ближче до межі, де галявини підступають до спаплюженого прикордоння Західних Чумних Земель. Левова паща росте на зарослих ділянках і городах довкола занедбаних будівель хутора.",al={"місце хутора балнірів","де ферма балнірів","знайти хутір балнірів"}},{q="Хто така Анастасія Гартвелл?",a="Анастасія Гартвелл — знана маг і наставниця з Відступників, що живе в Кварталі магів Андерсіті. Вона веде новоспечених чарівників-нежить, навчаючи їх дисципліни, чародійської рівноваги й практичного захисту кордонів від ворожих сил.",al={"лор анастасії гартвелл","хто така анастасія"}},{q="Чому магам-Відступникам не байдуже, як зупинити чуму?",a="Хоча Відступники й самі експериментують із власними чумами й пошестями, заразну магію Погибелі від Короля-Ліча вони вважають некерованим збоченням. Якщо її не стримати, скверна Погибелі поглине Галявини Тірісфалю цілком і підважить незалежність Відступників.",al={"чому зупинити чуму","чи відступники ненавидять чуму"}},{q="Що стається з квітами, коли ви їх зберете?",a="Отримавши левову пащу, Анастасія готується передати її аптекарям Андерсіті. Алхіміки й маги разом розтинають зразки, щоб оцінити, наскільки глибоко Погибель отруїла ґрунт і рослинність.",al={"що анастасія робить із квітами","кому квіти левової пащі"}},{q="Чи це завдання лише для магів?",a="Так. Це окреме класове завдання лише для молодих магів-Відступників, які вже пройшли перші уроки в Похоронному Подзвоні й прибули до столиці довести, що опанували чародійську теорію.",al={"чи хутір балнірів лише для магів","завдання класу магів"}}},fp="20,416,19.614.0,18.566.0,58.297.0,38.248.0,26.261.0,53.269.0,51.231.0,34.219.0"}
P.entries["quest:1885"] = {n="Меннет Каркад",s="«Меннет Каркад» — вступне завдання для розбійників в Андерсіті, що приводить перспективних агентів до лав скрадачів смерті. За вказівкою Маріон Колл молоді вбивці мають з'явитися просто до Меннета Каркада глибоко в Кварталі Розбійників.",h="«Меннет Каркад» — вступне завдання для розбійників в Андерсіті, що приводить перспективних агентів до лав...",kw={"меннет каркад","маріон колл","скрадачі смерті","квартал розбійників","розбійник","андерсіті"},ang={["class:Rogue"]="Цей виклик знаменує ваш перехід від непевного кишенькового злодюжки до визнаного агента скрадачів смерті — елітної тіньової мережі Відступників.",["race:Undead"]="Скрадачі смерті — запорука виживання Відступників: вони полюють на багряних фанатиків і рештки Погибелі та оберігають королеву Сильвану від прихованих загроз."},sec={{t="Виклик із тіні",b="У темних коридорах Андерсіті чутки тихо передаються між таємними агентами Відступників. Коли розвідник чи вбивця привертає увагу вищого проводу, йому надсилають запрошення. Маріон Колл переказує, що Меннет Каркад, помітна постать серед кураторів розбійників, особисто звернув увагу на новачка. Знаючи смертоносну славу розвідки Відступників, знехтувати таким наказом — не вихід."},{t="До лав скрадачів смерті",b="Меннет Каркад чекає в затінених нішах Кварталу Розбійників: він стежить за новобранцями й оцінює їхню готовність. Ті, хто відгукнеться на його поклик, вступають не до звичайної злодійської гільдії — їх випробовують на вступ до скрадачів смерті, грізної служби шпигунства й таємних убивств Відступників. Швидка покора — лише перше, найпростіше випробування для кожного, хто хоче служити Темній Леді з тіні."}},faq={{q="Хто такий Меннет Каркад?",a="Меннет Каркад — наставник розбійників і куратор Скрадачів смерті, що працює в Кварталі Розбійників Андерсіті. Він наглядає за перспективними таємними агентами й дає важливі доручення від імені проводу Відступників.",al={"лор меннета каркада","хто такий каркад"}},{q="Що буде, якщо знехтувати викликом Меннета Каркада?",a="Marion Call warns that you would not want to know what happened to those who ignored Carkad's call. She leaves their exact fate unexplained.",al={"ігнорувати каркада","що буде, якщо знехтувати викликом"}},{q="Хто такі Скрадачі смерті?",a="Скрадачі смерті — добірний орден розбійників, шпигунів і вбивць на службі Відступників. Діючи з тіней Андерсіті, вони усувають важливі цілі, збирають розвідані й боронять Лордерон від ворогів, як-от Багряний Хрестовий Похід і Погибель.",al={"лор скрадачів смерті","хто такі скрадачі смерті"}},{q="Де знайти Меннета Каркада?",a="Меннет Каркад перебуває в Кварталі Розбійників Андерсіті, зазвичай серед інших таємних агентів, наставників і припасів для мистецтва тіні.",al={"місце каркада","де меннет каркад"}},{q="Хто дає завдання розшукати Меннета Каркада?",a="Це завдання дає Маріон Колл у таверні «Шибеничний Кінець» у Бріллі: вона помічає, як зростає ваша вправність, і попереджає, що Каркад чекає швидкого послуху.",al={"хто починає це завдання","завдання кліч маріон"}},{q="Що буде, коли з'явитися до Меннета Каркада?",a="Щойно ви з'явитеся до Меннета Каркада, починається безпосередня служба Скрадачам смерті — з доручень, що мають довести вашу кмітливість і відданість справі Відступників.",al={"наступне завдання після каркада","чого хоче каркад"}}},fp="13,256,26.446.0,25.425.0,21.216.0,56.140.0,26.268.0,31.150.0,46.154.0,44.173.0"}
P.entries["quest:1886"] = {n="Смертолови",s="Це завдання — випробування для новачків, які прагнуть до лав скрадачів смерті, таємної й смертоносної служби, що підкоряється лордові Варіматрасу в Андерсіті. Доручення дає Меннет Каркад у Кварталі Розбійників, і воно вимагає безжальної кмітливості, щоб перехопити гінця в дорозі. Виконавши його, агент отримує доступ до глибших таємних задумів у королівстві Відступників.",h="Це завдання — випробування для новачків, які прагнуть до лав скрадачів смерті, таємної й смертоносної служби...",kw={"скрадачі смерті","меннет каркад","астор гадрен","варіматрас","квартал розбійників","розбійник"},ang={["class:Rogue"]="Для розбійників-Відступників вступ до скрадачів смерті — найвищий щабель служби державі: так вуличні пройдисвіти стають присяжними знаряддями Варіматраса й Темної Леді.",["faction:Horde"]="Скрадачі смерті діють у глибокій таємниці: вони підтримують важливі розвідувальні мережі Відступників, а південні союзники Орди здебільшого й гадки не мають про їхні темніші внутрішні справи.",["race:Undead"]="Скрадачі смерті — залізна хватка внутрішньої безпеки Лордерона: вони пильно й підозріливо стежать і за зовнішніми ворогами, і за можливими зрадниками серед Відступників."},sec={{t="Випробування в тіні",b="Скрадачі смерті приймають до своїх лав не кожного. Цей таємний орден, що підкоряється просто жахолордові Варіматрасу, водночас і таємна поліція, і елітний загін убивць Відступників. Щоб привернути його увагу, кандидат мусить показати хитрість, стриманість і готовність без вагань усувати цілі. У затінених кутках Кварталу Розбійників куратор Меннет Каркад призначає вступне випробування, що відсіює слабких і надто розбірливих."},{t="Перехоплення",b="Ціль новачка — Астор Гадрен, гонець, що мандрує дорогою між Андерсіті й Срібноліссям. Каркад не дає жодних тактичних порад: як здобути рекомендаційний лист Гадрена, агент вирішує сам. Головне — перехопити Астора, забрати його документи й дати скрадачам смерті змогу видати свого новобранця за очікуваного посланця до агента на ім'я Андрон."}},faq={{q="Хто такі Скрадачі смерті?",a="Скрадачі смерті — добірна гілка скрадання й убивств серед Відступників. Їхній осередок — у Кварталі Розбійників Андерсіті; вони займаються шпигунством, таємними стратами й збиранням відомостей і звітують безпосередньо лордові Варіматрасу.",al={"лор скрадачів смерті","хто такі скрадачі смерті","розбійники-нежить"}},{q="Хто такий Меннет Каркад?",a="Меннет Каркад — куратор Скрадачів смерті, що працює в Кварталі Розбійників Андерсіті. Він проводить перші випробування й перевіряє новобранців, які хочуть приєднатися до таємних лав.",al={"роль меннета каркада","хто дає завдання"}},{q="Навіщо Меннетові лист Астора Гадрена?",a="Астор Гадрен — гонець, що мандрує між Срібноліссям і Андерсіті. Здобувши його рекомендаційний лист, Скрадачі смерті можуть підставити замість Гадрена свого нового агента, щоб обдурити його знайомого на ім'я Андрон.",al={"лист астора гадрена","навіщо перехопити гінця","рекомендаційний лист астора"}},{q="Куди мандрує Астор Гадрен?",a="Астор Гадрен ходить шляхом, що сполучає Андерсіті й Срібнолісся, і доставляє листування між краями для своїх знайомих.",al={"маршрут астора гадрена","місце астора гадрена","де астор"}},{q="Хто такий лорд Варіматрас?",a="Варіматрас — жахолорд-натрезим, що уклав союз із королевою Сильваною Віндраннер, аби зберегти власне існування. З Королівського Кварталу він наглядає за безпекою, обороною й таємними операціями Андерсіті.",al={"роль варіматраса","володар жаху в андерсіті"}},{q="Що буде після цього випробування?",a="Пройшовши випробування, агент доводить свою вправність, і далі на нього чекає таємне доручення: видати себе за Астора, доставити його папери й проникнути в оборудки Андрона.",al={"що далі","продовження лінії скрадачів смерті"}}},fp="17,363,21.480.0,16.414.1,26.240.0,21.173.0,43.231.0,31.151.0,24.201.0,30.158.1"}
P.entries["quest:1898"] = {n="Смертолови",s="Це таємне доручення посилає агента під прикриттям у темні закутки Андерсіті, щоб випитати все в необачного змовника. Діючи за наказом, що надійшов від лорда Варіматраса, ви видаєте себе за очікуваного гінця, щоб викрити зраду в самій столиці Відступників.",h="Це таємне доручення посилає агента під прикриттям у темні закутки Андерсіті, щоб випитати все в необачного...",kw={"скрадачі смерті","андрон ґант","меннет каркад","астор гадрен","варіматрас","аптекаріум"},ang={["class:Rogue"]="Проникнути в шпигунську мережу під іменем мертвого, щоб виманити необачного змовника, — це прийом просто з підручника скрадачів смерті.",["faction:Horde"]="Під поверхнею Андерсіті кишать політичні інтриги — доказ того, що навіть у межах Орди довіра — рідкісний скарб.",["race:Undead"]="Для Відступників пильність — це виживання. Кожного громадянина, викритого в допомозі чужим угрупованням, може негайно знищити таємна поліція Темної Леді."},sec={{t="Павутина обману",b="Скрадачі смерті не лише усувають зовнішні загрози Відступникам — вони й безжально пильнують власних громадян. Через підозри лорда Варіматраса скрадач смерті Меннет Каркад запускає план проникнення. Маючи підроблений чи здобутий рекомендаційний лист Астора Гадрена, ви маєте приспати пильність місцевого крамаря на ім'я Андрон Ґант."},{t="Крамниця біля Апотекаріуму",b="Андрон Ґант тримає крамницю неподалік мерзенних випарів і булькотливих казанів Апотекаріуму. Меннет вважає крамаря дурнуватим і неуважним — йому забракне кмітливості, щоб розкусити самозванця. Показавши лист, ви утверджуєте своє прикриття гінця, і Ґант охоче втрачає пильність та сам розповідає подробиці своїх оборудок із невідомою третьою стороною."}},faq={{q="Хто такий Андрон Ґант?",a="Андрон Ґант — крамар з Андерсіті, чия крамниця біля Апотекаріуму. Він привернув увагу Скрадачів смерті і лорда Варіматраса, бо нібито передає відомості й допомогу якійсь невідомій сторонній силі.",al={"андрон ґант","хто такий ґант","де андрон ґант"}},{q="Чому лорда Варіматраса цікавить цей крамар?",a="Варіматрас підозрює, що Ґант співпрацює з якоюсь організацією поза Відступниками. Щоб уберегти місто й викорінити можливу змову, жахолорд вимагає конкретних доказів зв'язків і намірів Ґанта.",al={"чому варіматрас цікавиться","варіматрас андрон ґант","чому шпигувати за андроном"}},{q="Як обдурити Андрона Ґанта?",a="Меннет Каркад дає вам Рекомендаційний Лист Астора. Ґант чекав гінця, а Скрадачі смерті вважають його не надто кмітливим, тож досить показати йому папери, щоб здобути його довіру.",al={"лист астора","як обдурити андрона ґанта","маскування гінця"}},{q="Що за угруповання — Скрадачі смерті?",a="Скрадачі смерті — добірний орден розбійників і таємна розвідка Відступників. Діючи з тіней під проводом королеви Сильвани й лорда Варіматраса, вони викорінюють заколоти, шкодять ворогам і усувають внутрішні загрози.",al={"лор скрадачів смерті","хто такі скрадачі смерті","розбійники андерсіті"}},{q="Де знайти Андрона Ґанта?",a="Він сидить у своїй крамниці біля входу до кварталу Апотекаріуму в Андерсіті й веде справи під пильним оком Королівського Аптекарського Товариства та Скрадачів смерті.",al={"місце андрона ґанта","де крамниця ґанта"}},{q="Що буде, коли Ґант прийме лист?",a="Ґант без жодної підозри бере лист і вважає вас звичайним гінцем. Він одразу натякає на співпрацю зі спільними знайомими, що триває, — і це відкриває шлях до нових доказів його зради.",al={"що робить ґант","реакція ґанта"}}},fp="17,276,15.416.0,30.377.1,19.228.0,52.214.0,40.225.0,33.235.0,31.189.0,43.228.1"}
P.entries["quest:1899"] = {n="Смертолови",s="Це доручення — важливий крок до укладення домовленості між інформатором Андроном Ґантом і скрадачами смерті Андерсіті. Заручившись його співпрацею, агент доставляє докладний гросбух Ґанта просто в руки Меннета Каркада в Кварталі Розбійників. Ця передача знаменує перехід від простих розпитувань до глибших, таємніших операцій на користь держави Відступників.",h="Це доручення — важливий крок до укладення домовленості між інформатором Андроном Ґантом і скрадачами смерті...",kw={"скрадачі смерті","андрон ґант","гросбух","меннет каркад","квартал розбійників"},ang={["class:Rogue"]="Для молодого розбійника в Андерсіті делікатні доручення гінця для Меннета Каркада — базова перевірка стриманості: так агент доводить, що вміє вести таємні справи, не привертаючи зайвої уваги.",["race:Undead"]="Внутрішня безпека в Андерсіті — питання виживання: допомагаючи скрадачам смерті, ви прямо зміцнюєте владу Темної Леді над столицею проти живих лазутчиків і суперницької нежиті."},sec={{t="Гонець у тіні",b="Скрадачі смерті покладаються не лише на грубу силу чи тіньову магію: їхні операції значною мірою тримаються на буденних гросбухах, записаних іменах і ретельному стеженні. Андрон Ґант, що діє в Андерсіті, погоджується віддати особистий гросбух, напханий відомостями, яких так прагнуть убивці. Замість того щоб мати справу просто зі смертоносним ядром організації, Ґант довіряється посередникові-гінцю — і в цьому видно обережність, типову для кожного, хто торгує відомостями серед мертвих."},{t="Розвіддані в Кварталі Розбійників",b="Доставлений Меннетові Каркаду в Кварталі Розбійників, гросбух виявляється куди промовистішим, ніж сподівалися скрадачі смерті. Замість побіжних нотаток записи Ґанта дають конкретні зачіпки, що дозволяють Каркаду розширити розслідування. У такому підозріливому й розколотому світі, як королівство Відступників, перевірений паперовий слід конче потрібен, щоб викорінювати внутрішню крамолу й стежити за зовнішніми загрозами, перш ніж вони вдарять по столиці."}},faq={{q="Що в Гросбуху Андрона?",a="У гросбуху — делікатні відомості й записи, які зібрав Андрон Ґант. Точний вміст уголос не зачитують, але Меннет Каркад зауважує, що там значно більше подробиць і цінних розвіданих, ніж Скрадачі смерті спершу від нього чекали.",al={"вміст гросбуха андрона","що в гросбуху","гросбух скрадачів смерті"}},{q="Хто такі Скрадачі смерті?",a="Скрадачі смерті — провідна таємна організація й гільдія вбивць Відступників. Їхній осередок — у Кварталі Розбійників Андерсіті; вони — очі, вуха й приховані кинджали Леді Сильвани Віндраннер, що займаються шпигунством, розвідкою й цілеспрямованими вбивствами по всьому Лордерону.",al={"лор скрадачів смерті","хто такі скрадачі смерті","розбійники андерсіті"}},{q="Чому Ґант хоче й надалі мати справу з тим самим гінцем?",a="У каламутній, недовірливій атмосфері Андерсіті рідко трапляється посланець, який доставляє делікатні документи, нічого не крадучи й не підробляючи. Ґант прямо просить, щоб надалі справи вів той самий гонець, — так менше ризику, і налагоджена домовленість зберігається.",al={"чому ґант вас любить","довіра андрона ґанта","гінець ґанта"}},{q="Хто такий Меннет Каркад?",a="Меннет Каркад — досвідчений агент Скрадачів смерті, що стоїть у Кварталі Розбійників. Він координує місцевих агентів, збирає польові розвідані від донощиків на кшталт Андрона Ґанта й керує таємними дорученнями по всій столиці й довколишніх землях.",al={"лор меннета каркада","хто такий каркад"}},{q="Де розташований Квартал Розбійників?",a="Квартал Розбійників — південна частина Андерсіті. Це головний осередок агентів-скрадачів, злодіїв і вбивць Відступників, із тренувальними майданчиками й темними нішами далеко від людних площ верхніх руїн.",al={"місце кварталу розбійників","де квартал розбійників","квартал розбійників андерсіті"}},{q="Навіщо Відступникам власна внутрішня розвідка?",a="Оточений з усіх боків Погибеллю, Багряним Хрестовим Походом і недовірливими рештками Альянсу, молодий народ Відступників постійно потерпає від загрози проникнення й заколоту. Скрадачі смерті викорінюють змови в межах Лордерону, щоб молода влада вистояла.",al={"чому скрадачі смерті існують","шпигуни відступників","розвідка андерсіті"}}},fp="17,408,24.503.0,35.465.1,27.270.0,26.299.0,55.305.0,21.265.0,37.248.0,57.274.0"}
P.entries["quest:19"] = {n="Таріл'зун",s="Маршал Марріс оголошує нагороду за Таріл'зуна, хитрого ватажка скороходів Блекрок, що не дають спокою дорогам біля Фортеці Кам'яної Варти. Його смерть — важливий крок до того, щоб зламати владу клану Блекрок над північним Редріджем. Відрубана голова ватажка, принесена до Лейкширу, — тяжко здобута перемога знесиленої міської варти.",h="Маршал Марріс оголошує нагороду за Таріл'зуна, хитрого ватажка скороходів Блекрок, що не дають спокою дорогам...",kw={"таріл'зун","скороходи блекрок","маршал марріс","фортеця кам'яної варти","лейкшир","нагорода"},ang={["faction:Alliance"]="Лейкшир здебільшого відрізаний від прямого підкріплення зі Стормвінда, тож нагорода за Таріл'зуна — життєво важливий місцевий захід, щоб не допустити облоги містечка.",["race:Human"]="Присутність Блекрок у Редріджі — болюче нагадування про Першу й Другу війни, а смерть Таріл'зуна повертає королівству відібрану землю.",["race:Orc"]="Таріл'зун належить до темних решток Старої Орди під прапором Блекрок і служить володарям, які відкидають новий лад Тралла за морем."},sec={{t="Дорога до Кам'яної Варти",b="Звивистий перевал між Лейкширом і Фортецею Кам'яної Варти перетворився на смугу раптових засідок. Скороходи й ренегати Блекрок нишпорять кам'янистими хребтами, перехоплюють розвідників і загрожують кожному підкріпленню, що намагається пробитися до фортеці. Маршал Марріс вважає, що ці злагоджені удари спрямовує Таріл'зун, і оголошує, що його треба знищити, інакше Лейкшир опиниться в цілковитій облозі."},{t="Обезголовити скороходів",b="Таріл'зун — небезпечний тип польового командира: лютий, хитрий і здатний згуртувати розрізнених орків-грабіжників у дієвий загін. Щоб здобути його голову в тіні Кам'яної Варти, доведеться прорубатися крізь укріплені застави Блекрок. Його смерть руйнує злагодженість патрулів скороходів і відкриває Альянсові шлях до гарнізону, що засів у самій фортеці."}},faq={{q="Хто такий Таріл'зун?",a="Таріл'зун — грізний командир орків Блекрок, що керує розвідниками й ренегатами, які влаштовують засідки на стежках між Лейкширом і Фортецею Кам'яної Варти.",al={"хто такий таріл'зун","таріл'зун лор","бос таріл'зун"}},{q="Де знайти Таріл'зуна?",a="Таріл'зун стоїть біля Фортеці Кам'яної Варти на північному сході Редріджу й командує розвідниками, які патрулюють довколишні перевали й застави.",al={"де таріл'зун","місце таріл'зуна","знайти таріл'зуна"}},{q="Навіщо Маршалові Маррісу його голова?",a="Марріс бачить у Таріл'зуні хитрого тактика, що спрямовує засідки, які не дають спокою Редріджу. Голова ватажка означає, що розвідники лишилися без проводу, і стає незаперечним доказом того, що загрозу усунуто.",al={"чому вбити таріл'зуна","причина винагороди за таріл'зуна"}},{q="Що буде після перемоги над Таріл'зуном?",a="Загибель Таріл'зуна розладнує дії розвідників, і захисники Лейкшира разом із шукачами пригод можуть просунутися глибше до Фортеці Кам'яної Варти, щоб зійтися з головним гарнізоном Блекрок.",al={"завдання після таріл'зуна","що після таріл'зуна"}},{q="Що орки Блекрок роблять у Горах Редріджу?",a="Рештки клану Блекрок просунулися на південь з Палаючих Степів у Редрідж і укріпили старі людські застави, як-от Фортецю Кам'яної Варти, щоб загрожувати Східним Королівствам, поки військо Стормвінда розпорошене.",al={"чому орки блекрок у редріджі","орки кам'яної варти передісторія"}},{q="Що треба зробити, перш ніж полювати на Таріл'зуна?",a="Маршал Марріс вимагає, щоб шукачі пригод спершу довели свою загартованість, проріджуючи загарбників у завданні «Загроза Блекрок», і лише тоді посилає їх по самого Таріл'зуна.",al={"передумова таріл'зуна","як відкрити завдання таріл'зуна"}}},fp="10,342,22.432.0,27.419.0,18.176.0,30.144.0,38.216.0,42.185.0,45.218.0,62.173.0"}
P.entries["quest:1918"] = {n="Опоганений елемент",s="Убиваючи збурених водяних елементалів довкола Озера Містраль, шукачі пригод знаходять мерзенну сяйливу кулю отруєної води. Прагнучи зрозуміти, що отруїло озеро та його стихійних духів, вони несуть зразок до Мастока Врайлгісса на Заставу Розщепленого Дерева.",h="Убиваючи збурених водяних елементалів довкола Озера Містраль, шукачі пригод знаходять мерзенну сяйливу кулю...",kw={"опоганений елемент","озеро містраль","водяні елементалі","масток врайлгісс","земляне кільце","завдання"},ang={["class:Shaman"]="Спотворений стан духів Озера Містраль глибоко тривожить шаманів, які чують біль стихій і розуміють, що без втручання Земляного Кільця не обійтися.",["faction:Horde"]="Застава Розщепленого Дерева не може дозволити, щоб у неї під боком гноїлася хаотична стихійна загроза, поки вартові Альянсу й фурболги загрожують шляхам постачання Орди.",["race:Tauren"]="Таурени-мандрівники відчувають глибокий обов'язок свого народу зцілювати отруєні води землі, тож відновлення Озера Містраль для них — нагальна духовна справа."},sec={{t="Отруєні води Озера Містраль",b="Озеро Містраль на південному сході Ашенвалю потрапило в тяжку біду. Водяні елементалі, що живуть на його мілинах, стали жорстоко агресивними й помітно зіпсованими. Убиті, вони лишають по собі не чисту стихійну есенцію, а дивні, яскраво сяйливі кулі гнилої рідини. Хай яка порча оселилася над озером, вона зосереджена в цих кулях, — а отже, заворушення значно серйозніше, ніж звичайна природна агресивність."},{t="По пораду до Розщепленого Дерева",b="Не розуміючи, яка мерзенна магія тут діє, розвідники Орди звертаються по пораду до гарнізону Застави Розщепленого Дерева. Масток Врайлгісс, один із наглядачів застави, спершу гидливо відсахується від мерзенного зразка. Вояк, а не вчений, Масток швидко розуміє, що звичайна сталь не вилікує хворої води, і посилає шукача пригод до знавців стихій із Земляного Кільця."}},faq={{q="Що в Опоганеній Водяній Кулі?",a="У кулі — огидний зосереджений зразок скверни, що нині отруює Озеро Містраль. Вона утворюється з решток убитих елементалів, і це доводить, що їхня духовна скверна цілком відчутна й потужна.",al={"вміст опоганеної кулі","що у водяній кулі","водяна куля містралового озера"}},{q="Де починається це завдання?",a="Завдання починається з предмета, що випадає під час боїв з розлюченими чи опоганеними водяними елементалями Озера Містраль у південній частині центрального Ашенвалю.",al={"де знайти водяну кулю","як почати опоганений елемент","початок завдання"}},{q="Чому Масток Врайлгісс не хоче мати з цим нічого спільного?",a="Масток Врайлгісс — офіцер Орди на Заставі Розщепленого Дерева, якого обходять передусім виживання війська й постачання. Розбиратися в хворих магічних водах — не його справа, тож він радить звернутися до Земляного Кільця.",al={"хто такий масток","чому говорити з мастоком","роль масток врайлгісс"}},{q="Чому це цікавить Земляне Кільце?",a="Земляне Кільце — орден шаманів, що вивчає стихії, угамовує їх і відновлює між ними гармонію. Зіпсовані елементалі на кшталт тих, що в Озері Містраль, якраз підлягають їхньому духовному відомству.",al={"чому земляне кільце","зв'язок земляного кільця","хто такі земляне кільце"}},{q="Куди веде розслідування далі?",a="Масток спрямовує вас до Дже'ню Санкреа — шамана Земляного Кільця, що стоїть на західному узбережжі Ашенвалю, на Березі Зорам'ґар, і може як слід оглянути опоганену реліквію.",al={"що далі","наступне завдання після опоганеного елемента","куди йти далі"}}},fp="20,271,30.469.0,30.429.1,40.219.0,28.140.0,53.222.0,44.208.0,39.175.1"}
P.entries["quest:1938"] = {n="Трактат Ура про Магію Тіні",s="«Трактат Ура про Магію Тіні» — завдання, яке дає Верховний Чаклун Андромат у Кварталі магів Стормвінда. Він доручає шукачам пригод повернути заборонений, магічно запечатаний фоліант, з яким утік маг-ренегат Морґант, сховавшись у Вежі Ілґалара в Горах Редріджу.",h="«Трактат Ура про Магію Тіні» — завдання, яке дає Верховний Чаклун Андромат у Кварталі магів Стормвінда.",kw={"трактат ура","магія тіні","морґант","вежа ілґалара","верховний чаклун андромат","гори редріджу"},ang={["class:Mage"]="Маги Стормвінда серйозно ставляться до внутрішньої дисципліни: довіреним чарівникам доручають розгрібати небезпечні наслідки, які залишив по собі товариш, що звернувся до забороненої магії тіні.",["class:Warlock"]="Поки Кірін-Тор і маги Стормвінда бояться трактатів Ура про тіні, чорнокнижники нерідко жадають саме тих сил — призову з інших світів і темних чарів, — що запечатані в них.",["faction:Alliance"]="Повернувши викрадений фоліант, ви вбережете кордони Редріджу від дедалі більшої магічної загрози Морґанта й захистите королівство Стормвінд від свавільної тайної магії."},sec={{t="Розкол у вежі",b="Колись давно троє обдарованих магів навчалися разом у Святилищі Чародія в Стормвінді. З часом один із них, Морґант, піддався спокусам темних мистецтв і магії тіні. Попри відчайдушні застереження товаришів, які благали його відвернутися від цієї згубної сили, він не захотів зректися своєї одержимості. Його офіційно вигнали з магічного ордену міста, але пішов він не з порожніми руками: він викрав небезпечну працю Ура — сумнозвісного архімага, чиї дослідження виходили далеко за межі визнаної тайної науки."},{t="Лігво занепалого мага",b="Морґант звив собі нове кубло далеко від пильного ока Стормвінда, захопивши Вежу Ілґалара на висотах Гір Редріджу. Верховний Чаклун Андромат не може допустити, щоб такі небезпечні знання лишалися в руках вигнанця, що практикує заборонене чаклунство. Доручивши шукачам пригод Альянсу прорвати оборону вежі, Андромат прагне повернути фоліант, перш ніж упадуть його захисні чари."},{t="Захисні чари вціліли",b="Коли трактат вдається забрати з бібліотеки Ілґалара й повернути до Святилища Чародія, Андромат відчуває величезне полегшення. Він боявся, що Морґант уже розплутав його захисні чари або сховав книгу так, що не дістати. На щастя, магічні печаті на трактаті Ура витримали — і магові-ренегату не вдалося випустити на волю згубні таємниці, ув'язнені на його сторінках."}},faq={{q="Хто написав трактат?",a="Трактат написав Ур — легендарний маг з Даларана, знаний своїми таємничими дослідженнями позасвітових істот і магії тіні.",al={"хто такий ур","автор трактату","автор трактату ура"}},{q="Хто викрав Трактат Ура про Магію Тіні?",a="Морґант, колишній маг зі Стормвінда, викрав книгу, коли піддався темній магії й був вигнаний зі Святилища Чародія.",al={"хто вкрав книгу","хто забрав трактат","книга морганта"}},{q="Де зберігається книга?",a="Книга зберігається в бібліотеці Вежі Ілґалара, високо в Горах Редріджу, де Морґант облаштував свій новий притулок.",al={"де трактат","місце книги вежі ілґалара","де знайти трактат ура"}},{q="Чи вдалося Морґантові прочитати книгу?",a="Ні. Коли трактат повертають Верховному Чаклунові Андромату, той підтверджує, що захисні печаті на книзі втрималися, тож Морґант так і не зміг її відкрити.",al={"чи морґант відкрив книгу","чи відкрили трактат","чи зламані печаті"}},{q="Чому маги Стормвінда хочуть повернути книгу?",a="У фоліанті — глибокі таємниці магії тіні, що можуть згубити недосвідчених. Маги Стормвінда вважають, що лишати його в руках ренегата на кшталт Морґанта надто небезпечно.",al={"навіщо повернути книгу","чому трактат небезпечний","мета андромата"}},{q="Хто дає це завдання?",a="Це завдання пропонує Верховний Чаклун Андромат, що перебуває у Святилищі Чародія в Кварталі магів Стормвінда.",al={"хто дає завдання","де взяти завдання трактату ура","завдання андромата"}}},fp="29,282,21.515.0,22.395.0,12.383.1,23.135.0,40.123.0,23.145.0,37.174.1,49.186.0,21.118.0"}
P.entries["quest:1940"] = {n="Бездоганний Павучий Шовк",s="«Бездоганний Павучий Шовк» — посвятне доручення для молодих магів Альянсу, яке дає Верховний Чаклун Андромат у Стормвінді. Щоб заслужити вбрання, гідне адепта, чарівника відсилають у темні ліси Сутінколісся по найкращий шовк падложерних самітників. Зібрані мотки доставляють кравчині Вінн Ларсон у Кварталі магів, щоб вона пошила зачаровану мантію.",h="«Бездоганний Павучий Шовк» — посвятне доручення для молодих магів Альянсу, яке дає Верховний Чаклун Андромат...",kw={"бездоганний павучий шовк","верховний чаклун андромат","вінн ларсон","сутінколісся","маг","мантія"},ang={["class:Mage"]="Цей обряд посвяти — місток між учнівством і справжньою майстерністю: кожен маг Стормвінда носить мантію, виткану з того, що здобув, власноруч подолавши небезпеку.",["faction:Alliance"]="Сутінколісся лишається небезпечним прикордонням для підданих Стормвінда, тож магам доводиться виходити зі столичного прихистку по рідкісні місцеві ресурси.",["profession:Tailoring"]="Методи Вінн Ларсон показують, як із добірних волокон диких чудовиськ виходять тканини, чутливі до магії, — куди кращі за звичайну овечу вовну чи льон."},sec={{t="Вбрання адепта",b="У Святилищі Чародія визнання вимірюють не лише владою над тайною магією, а й вбранням, яке носять чарівники. Верховний Чаклун Андромат бачить, коли учень переріс звичайну учнівську роботу, і велить йому замовити вбрання, гідне адепта. Маг не може просто купити готову річ: він мусить довести і вправність у полі, і розбірливість, власноруч добувши бездоганний, незаплямований шовк у небезпечних тварин."},{t="Ткацький верстат Сутінколісся",b="Потрібного матеріалу не знайти на звичайних торгових ятках. Його треба обережно добути з отруйних павуків — падложерних самітників, що чатують у примарних сутінках Сутінколісся. Вісім добірних мотків несуть через усе місто до крамниці «Одяг Ларсонів» у Кварталі магів, де кравчиня Вінн Ларсон готова спрясти з тонких ниток мантію, сповнену тайної сили."}},faq={{q="Хто посилає магів на це доручення?",a="Верховний Чаклун Андромат, що очолює Святилище Чародія в Стормвінді, пропонує це завдання чарівникам, які довели свою відданість.",al={"хто дає бездоганний павучий шовк","хто дає завдання","завдання андромата"}},{q="Де збирають шовк?",a="Шовк збирають з падложерних самітників, що никають похмурими лісами й заплетеними павутинням галявинами Сутінколісся.",al={"де брати шовк","місце бездоганного шовку","місце самітників падальниць"}},{q="Хто шиє з шовку робу?",a="Ткацтвом і шиттям займається Вінн Ларсон — кравчиня з крамниці одягу «Ларсон» у Кварталі магів Стормвінда.",al={"хто пряде шовк","вінн ларсон","одяг ларсон"}},{q="Чому маги шиють одяг з павучого шовку?",a="Бездоганний павучий шовк природно міцний і має надзвичайно тонке плетиво, тож з нього виходить легка тканина, здатна втримувати тонкі чари й не обтяжувати чарівника.",al={"чому павучий шовк","магічні робі з павучого шовку"}},{q="Що буде, коли доставити шовк?",a="Оглянувши шовк і попрацювавши за ткацьким верстатом, Вінн вручає магові готове Вбрання Астрального Вузла.",al={"наступне завдання після шовку","що буде далі"}},{q="Чи годиться будь-який павучий шовк із Сутінколісся?",a="Ні. Для тонких чарів, якими славиться крамниця «Ларсон», потрібні саме бездоганні зразки, обережно здобуті з падложерних самітників; грубішого павутиння там не приймають.",al={"чи звичайний шовк годиться","бездоганний чи звичайний шовк"}}},fp="20,381,22.460.0,20.400.0,35.146.0,28.117.0,34.131.0,42.185.0,37.113.0,44.163.0"}
P.entries["quest:1941"] = {n="Маноткана Роба",s="«Маноткана Роба» завершує сміливе кравецьке замовлення в самому серці Стормвінда. Вінн Ларсон вручає готове зачароване вбрання з добірних матеріалів — горду візитівку родинної крамниці. Для молодих чарівників ця роба — один із перших знаків відданості тайній магії й доброї людської майстерності.",h="«Маноткана Роба» завершує сміливе кравецьке замовлення в самому серці Стормвінда.",kw={"маноткана роба","вінн ларсон","одяг ларсонів","квартал магів","кравецтво","маг"},ang={["class:Mage"]="Для молодого мага, що навчається у вежах Стормвінда, вдягти пошиту на замовлення Маноткану Робу — знак переходу до серйозних польових досліджень і самостійного чарування.",["faction:Alliance"]="Споряджаючи перспективних героїв у місцевих крамницях столиці, Стормвінд показує свій престиж і самодостатність у неспокійних краях.",["profession:Tailoring"]="Робота Вінн Ларсон показує високий рівень людського кравецтва: як із земних матеріалів виткати тканину, що приборкує й гартує нестійку тайну силу."},sec={{t="«Одяг Ларсонів»",b="У гамірному Кварталі магів Стормвінда крамниця «Одяг Ларсонів» обслуговує адептів тайних мистецтв, яким потрібне вбрання, здатне проводити нестійкі енергії. Пошиття вишуканого магічного вбрання вимагає рідкісних матеріалів, ретельної голки й пильного ока до ниток, які не розплутаються від містичного резонансу. Вінн Ларсон особисто пишається кожною річчю, що виходить з її крамниці, і вважає кожну мантію, яку носять у мандрах, ходячим свідченням слави імені Ларсонів."},{t="Виткані чари",b="Маноткана Роба створена на допомогу молодим магам: вона дає зручність, свободу рухів і практичну стійкість, потрібну в мандрах спірними землями. Коли потрібні складники доставлено, Вінн сама робить останній стібок і вручає готове вбрання не як звичайний товар, а як шедевр, що має привертати погляди й славити якість кравецтва Ларсонів по всьому королівству."}},faq={{q="Хто шиє Маноткану Робу?",a="Вінн Ларсон шиє її у своїй крамниці одягу «Ларсон» у Кварталі магів Стормвінда.",al={"хто шиє маноткану робу","вінн ларсон роба","одяг ларсон"}},{q="Чому Вінн Ларсон хоче, щоб ви носили робу з гордістю?",a="Вінн вважає цю робу одним зі своїх найкращих витворів. Вона просить шукачів пригод розповідати про крамницю «Ларсон» щоразу, коли хтось милуватиметься роботою, — для неї це жива реклама.",al={"чому носити з гордістю","реклама ларсон","діалог вінн"}},{q="Де розташована крамниця «Ларсон»?",a="Крамниця — у Кварталі магів Стормвінда, неподалік академій і святилищ, де збираються чарівники Альянсу.",al={"місце крамниці ларсон","де вінн ларсон","кравецька крамниця кварталу магів"}},{q="Що за одяг — Маноткана Роба?",a="Це зачарована тканинна роба для практиків магії, пошита так, щоб спрямовувати містичну енергію й водночас бути зручною в небезпечних мандрах.",al={"лор манотканої роби","що таке маноткана роба","що робить роба"}},{q="Чи це частина довшого ланцюжка завдань?",a="Так, це замовлення — останній крок кравецького ланцюжка завдань, у якому ви допомагаєте Вінн Ларсон з матеріалами для її роботи.",al={"ланцюжок маноткана роба","ланцюжок завдань робі","кінець лінії"}},{q="Яка фракція може взятися за це завдання?",a="Це завдання лише для Альянсу, бо Вінн Ларсон працює виключно в столиці — Стормвінді.",al={"роба альянсу чи орди","чи орда отримає маноткану робу","вимога до фракції"}}},fp="14,347,16.468.0,13.412.0,30.95.0,59.208.0,34.134.0,41.159.0,35.135.0,38.123.0"}
P.entries["quest:1942"] = {n="Вбрання Астрального Вузла",s="«Вбрання Астрального Вузла» — вершина відданої кравецької праці в Стормвінді. Подолавши дикі краї, щоб зібрати рідкісний павучий шовк, шукач пригод приносить матеріали вправній кравчині Вінн Ларсон. Результат — вишукана магічна тканина, що пасує і для небезпечних мандрів, і для світських зібрань.",h="«Вбрання Астрального Вузла» — вершина відданої кравецької праці в Стормвінді.",kw={"вбрання астрального вузла","вінн ларсон","павучий шовк","квартал магів","кравецтво","маг"},ang={["class:Mage"]="Вбрання Астрального Вузла поєднує тайну гідність Кварталу магів Стормвінда з практичними чарами, потрібними в мандрах за укріпленими мурами королівства.",["faction:Alliance"]="Ремісники Стормвінда пишаються тим, що постачають героям Альянсу спорядження, гідне і королівських зал, і небезпечної передової.",["profession:Tailoring"]="Робота Вінн Ларсон — вершина майстерності з Бездоганним Павучим Шовком: вона показує, як сировину від чудовиськ можна перетворити на розкішне вбрання."},sec={{t="Дотепність ткалі",b="У гамірному Кварталі магів Стормвінда кравці й швачки обшивають і тайну еліту, і знать, що навідується до міста. Вінн Ларсон — одна з таких майстринь, знана вмінням ткати з Бездоганного Павучого Шовку міцне зачароване вбрання. Вона славиться грайливим гумором і, перш ніж віддати свій майстерно пошитий витвір, жартує, що залишить собі кілька клаптиків дорогоцінного шовку для власного гардеробу."},{t="Вишуканість на всі випадки",b="Вбрання Астрального Вузла цінують чарівники, що носять тканинний одяг і вимагають від нього і стійкості, і вишуканості. Виткане з тонкого, проте міцного шовку, зібраного в небезпечних павуків, це вбрання здатне витримати тяготи бою й водночас зберігає бездоганний вигляд, якого чекають на урочистих бенкетах у Фортеці Стормвінда."}},faq={{q="Що таке Вбрання Астрального Вузла?",a="Це майстерно пошитий одяг від Вінн Ларсон зі Стормвінда. Зроблене з бездоганного павучого шовку, воно призначене для тих, хто носить тканинне вбрання, — і для пригод із боями, і для урочистих світських подій.",al={"що таке вбрання астрального вузла","роба астрального вузла","одяг астрального вузла"}},{q="Хто шиє Вбрання Астрального Вузла?",a="Вінн Ларсон, кравчиня з Кварталу магів Стормвінда, шиє його, щойно отримає потрібні незвичні матеріали.",al={"хто шиє астральний вузол","завдання вінн ларсон","кравець астрального вузла"}},{q="Які матеріали потрібні для цього вбрання?",a="Для вбрання потрібен бездоганний павучий шовк, зібраний зі смертоносних павуків у диких краях світу, і кравецькі прийоми, що зберігають природну міцність шовку та його здатність утримувати чари.",al={"матеріали астрального вузла","потрібний павучий шовк","як це робиться"}},{q="Чому Вінн Ларсон жартує, що лишить собі рештки шовку?",a="Бездоганний павучий шовк надзвичайно рідкісний і цінний серед кравців. Вінн жартує, що могла б пошити вбрання трохи коротшим і приберегти кілька клаптиків для себе, проте віддає роботу повністю.",al={"чи вона вкрала мій шовк","жарт вінн ларсон","коротка роба"}},{q="Де саме в Стормвінді шиють це вбрання?",a="Вінн Ларсон працює в Кварталі магів Стормвінда — кварталі вчених, чародіїв і вузьких майстрів одягу, які знаються на зачарованих тканинах.",al={"де вінн ларсон","місце астрального вузла","куди здати астральний вузол"}},{q="Хто зазвичай носить Вбрання Астрального Вузла?",a="Його здобувають і полюбляють маги Альянсу — за легке захисне плетиво й гідний вигляд.",al={"хто користується астральним вузлом","для якого класу","хто носить"}}},fp="19,317,14.408.0,18.327.0,32.228.0,35.136.0,53.212.0,56.207.0,50.158.0,44.99.0"}
P.entries["quest:1944"] = {n="Води Ксавіана",s="«Води Ксавіана» — завдання для магів Орди, яке дає Дейно в Оргріммарі. Прагнучи збагнути прадавні ельфійські таємниці, вона доручає своєму учневі вирушити до руїн Ксавіана в Ашенвалі й набрати зразок води з його найвищого водоспаду.",h="«Води Ксавіана» — завдання для магів Орди, яке дає Дейно в Оргріммарі.",kw={"води ксавіана","дейно","ксавіан","маг","сатири","завдання"},ang={["class:Mage"]="Це завдання — особливий навчальний обряд для магів Орди, що перевіряє, чи здатні вони вирушити у ворожу глушину й здобути неприборкані таємні реагенти.",["faction:Horde"]="Застава Розщепленого Дерева — найближчий плацдарм Орди на сході Ашенвалю, звідки можна вирушати в кишучу сатирами глушину довкола Ксавіана."},sec={{t="Цікавість чарівниці",b="У темних закутках Долини Духів магиня-тролиця Дейно шукає по всьому Калімдору залишкові вмістища первісної таємної сили. Її погляд падає на Ксавіан — прадавнє місто нічних ельфів, заховане глибоко в східних хащах Ашенвалю. Серед учених ходять перекази, що до Розколу місто було просякнуте магічним знанням, а його води, кажуть, досі зберігають могутні таємні властивості, які сучасні чаклуни прагнуть розібрати до найдрібніших подробиць."},{t="Руїни Ксавіана",b="Дістатися джерела цих вод — непросте доручення. Ксавіан більше не належить мирним ельфійським мудрецям: він лежить у руїнах, і його заполонили дикі, зіпсовані сатири, що люто стережуть свою територію від чужинців. Допитливим магам доведеться пробратися повз Сатирнаар і пройти небезпечними протоками, уникаючи і хижих звірів, і демонічних вартових, щоб наповнити флакон Дейно біля підніжжя височенного міського водоспаду."}},faq={{q="Хто така Дейно?",a="Дейно — тролиця, наставниця магів і вчена з Долини Духів в Оргріммарі. Вона навчає магів Орди й досліджує реліквії давньої магії Калімдору.",al={"хто дає води ксавіана","дейно оргріммар"}},{q="Де розташований Ксавіан?",a="Ксавіан — давнє зруйноване місто на північному сході Ашенвалю, на північ від Застави Розщепленого Дерева й трохи на північний захід від твердині сатирів Сатирнаар.",al={"місце ксавіана","де ксавіан","як знайти ксавіан"}},{q="Навіщо Дейно ця вода?",a="За свідченнями вчених, колись Ксавіан зберігав величезні магічні знання, і вважають, що в його водах досі лишилася чародійська сила. Дейно хоче свіжий зразок просто з джерела водоспаду, щоб дослідити його властивості.",al={"навіщо вода ксавіана","мета води ксавіана"}},{q="Які небезпеки стережуть руїни Ксавіана?",a="Руїни кишать сатирами — демонічними, зіпсованими скверною істотами, які ненавидять чужинців і люто боронять свою землю від цікавих магів.",al={"вороги ксавіана","хто керує ксавіаном"}},{q="Де саме набирати зразок води?",a="Зразок треба зачерпнути в Дейнину пляшку з водойми біля самого підніжжя найвищого водоспаду в руїнах Ксавіана.",al={"місце водоспаду","де наповнити флакон","водоспад ксавіана"}},{q="Що далі, коли повернути зразок Дейно?",a="Задоволена зразком води, Дейно посилає мага на наступний етап досліджень — до дріад Ашенвалю, у завданні «Сестри-реготухи».",al={"продовження вод ксавіана","наступне завдання після вод ксавіана"}}},fp="16,230,18.440.0,19.426.0,13.165.0,24.152.0,31.207.0,39.147.0,44.129.0,52.147.1"}
P.entries["quest:1945"] = {n="Сестри-реготухи",s="«Сестри-реготухи» — завдання Орди, яке посилає магів у серце Ашенвалю по зачаровані пасма волосся диких дріад. Матеріал призначено для Кіл'гали, досвідченого кравця-троля на Перехресті, який спряде з нього посилену мантію мага. Полювання на доньок Кенарія підкреслює невпинне тертя між чаклунами Орди та споконвічними захисниками прадавнього лісу.",h="«Сестри-реготухи» — завдання Орди, яке посилає магів у серце Ашенвалю по зачаровані пасма волосся диких дріад.",kw={"сестри-реготухи","дріади","кіл'гала","дейно","кравецтво","маг","завдання"},ang={["class:Mage"]="Цей обряд посвяти вчить молодих магів, що навіть священних лісових духів Ашенвалю можна використати як матеріал для чарівного ремесла.",["faction:Horde"]="Убивство дріад Ашенвалю загострює конфлікт між загарбницькою присутністю Орди та священними охоронцями лісу, вірними нічним ельфам.",["profession:Tailoring"]="Завдання показує рідкісне мистецтво вплітати живі чарівні волокна в тканинний обладунок — майстерний прийом, яким володіє Кіл'гала на Перехресті."},sec={{t="Таємне ткацтво",b="Після того як молоді маги здобули зіпсовану воду з Ксавіана, Дейно в Оргріммарі посилає їх допомогти пошити власні зачаровані шати. Таке чарівне кравецтво вимагає матеріалів, сповнених сирої магічної сутності. Пасма дріад, природно просякнуті первісною життєвою силою лісу, мають усе потрібне, щоб виткати складні чарівні вбрання, здатні захищати чаклуна й посилювати його силу."},{t="На полюванні в Рейнвуді",b="Щоб здобути ці пасма, магам доведеться вирушити на південь, до Притулку Рейнвуд в Ашенвалі. Сестри-реготухи — моторні лісові дріади, союзниці нічних ельфів — люто стережуть ці гаї і від лісорубів, і від будь-яких чужинців. Лісові чарівні істоти ніколи добровільно не віддадуть свого волосся чаклунам Орди, тож за здобич неминуче доводиться платити кров'ю під покровом прадавніх дерев."},{t="Право ткалі",b="Зібрані пасма несуть на південь через кордон, до курного поселення Перехрестя в Пустках. Там кравець-троль Кіл'гала без жодних докорів сумління приймає цю данину. Ледь іронічно визнаючи втрату лісових створінь, Кіл'гала не гає часу й одразу пускає зачаровані пасма в діло, бо знає: сила в Орді часто вимагає непохитної рішучості."}},faq={{q="Хто дає завдання полювати на сестер-реготух?",a="Дейно, тролиця-маг з Оселі Темного Терну в Оргріммарі, посилає магів у це доручення як нагороду й підготовку до виготовлення їхніх класових роб.",al={"хто дає сестер-реготух","хто дає завдання сестри-реготухи","завдання дейно"}},{q="Хто такі реготливі сестри?",a="Реготливі сестри — дріади, доньки напівбога Кенарія. Верхня частина тіла в них, як у жінок з нічних ельфів, а нижня — як у оленят; вони оберігають ліси й священні галявини Ашенвалю.",al={"що таке реготлива сестра","реготлива сестра дріада","чи реготливі сестри дріади"}},{q="Де знайти реготливих сестер?",a="Вони блукають лісами біля Притулку Рейнвуд і галявини Реготливої Сестри в центральному Ашенвалі, неподалік торгового шляху.",al={"місце реготливих сестер","де реготливі сестри","де знайти реготливих сестер"}},{q="Навіщо Кіл'галі волосся дріад?",a="Волосся дріад просякнуте природними чарами, тож це ідеальна нитка, яку Кіл'гала вплітає в особливі роби з магічним резонансом для чародійських мистецтв.",al={"чому волосся дріад","чому волосся реготливої сестри","навіщо волосся"}},{q="Куди нести зібране волосся?",a="Віднесіть волосся Кіл'галі — майстрові-кравцю з гамірної застави Перехрестя в Пустках.",al={"де кіл'гала","здати сестер-реготух","кравчиня чорнокнижників перехрестя"}},{q="Що буде, коли Кіл'гала візьме волосся?",a="Отримавши волосся, Кіл'гала трохи працює з матеріалом, а тоді пропонує наступне завдання — «Вбрання з Мережива Нижнього Світу», щоб завершити робу.",al={"наступне завдання після сестер-реготух","після сестер-реготух","продовження вбрання з мережива"}}},fp="16,400,18.441.0,18.412.0,24.410.0,51.141.0,30.199.0,40.135.0,34.164.0,49.117.0,43.160.0"}
P.entries["quest:1946"] = {n="Вбрання з Мережива Нижнього Світу",s="«Вбрання з Мережива Нижнього Світу» завершує особливу ремісничу роботу кравця Кіл'гали в Пустках. Вплітаючи зібране волосся дріад у тонку тканину, кравець створює зачароване вбрання, гідне заклиначів.",h="«Вбрання з Мережива Нижнього Світу» завершує особливу ремісничу роботу кравця Кіл'гали в Пустках.",kw={"вбрання з мережива нижнього світу","кіл'гала","дейно","дріади","маг","кравецтво"},ang={["class:Mage"]="Вбрання з мережива Нижнього Світу — важлива віха для магів, що зростають у силі: воно поєднує випробування в дикому Ашенвалі з майстерністю Кіл'гали під наглядом Дейно.",["faction:Horde"]="Збирання складників у священних лісах Калімдору, щоб спорядити заклиначів Орди, показує тривале суперництво між Ордою й лісовими оборонцями Ашенвалю.",["profession:Tailoring"]="Ремесло Кіл'гали показує, як екзотичні складники на кшталт волосся дріад можна спрясти в тканину з природним магічним захистом."},sec={{t="Плетіння мережива Нижнього Світу",b="Кіл'гала, що працює на Перехресті в Пустках, береться за тонку справу — виготовлення мережива Нижнього Світу. Для цього потрібні рідкісні складники, що відгукуються на магію, — а саме коси, зрізані з дріад, яких в Ашенвалі звуть регітливими сестрами. Так кравець вплітає природні лісові чари просто в зручну, міцну тканину."},{t="Послуги для Оргріммара",b="Кіл'гала не просто займається своїм ремеслом — у нього є й особисті причини дбати про якість вбрання. Він дуже хоче догодити Дейно, шанованій тролиці-магині з Долини Духів в Оргріммарі. Шиючи виняткове вбрання для молодих заклиначів, Кіл'гала сподівається здобути й зберегти прихильність Дейно."}},faq={{q="Що таке мереживо Нижнього Світу?",a="Мереживо Нижнього Світу — зачарована тканина, яку виготовляє Кіл'гала. Її ткуть з магічних матеріалів, а саме з кіс реготливих сестер, тож вона й міцна, і природно сповнена чародійського резонансу.",al={"мереживо нижнього світу","що таке вбрання з мережива"}},{q="Хто шиє Вбрання з Мережива Нижнього Світу?",a="Кіл'гала, вправний кравець Орди з Перехрестя в Пустках, шиє вбрання, щойно отримає потрібне волосся дріад з Ашенвалю.",al={"хто шиє мереживо","кіл'гала мереживо нижнього світу"}},{q="Чому Кіл'гала згадує Дейно?",a="Дейно — впливова тролиця, наставниця магів, що живе в Долині Духів в Оргріммарі. Кіл'гала дуже хоче бути в неї на доброму рахунку й сподівається, що ваше задоволення його роботою прислужиться його репутації.",al={"хто така дейно","чому дейно"}},{q="Звідки взялися матеріали для вбрання?",a="Головний матеріал — волосся реготливих сестер, невловних дріад, що живуть у лісах Ашенвалю.",al={"матеріали мережива","волосся дріад тканина"}},{q="Для кого шиють це вбрання?",a="Передусім для чарівників, особливо магів-учнів, яким потрібні роби, що спрямовують чародійську енергію й не сковують рухів.",al={"хто користується мереживом","клас мережива"}},{q="Де знайти Кіл'галу?",a="Кіл'гала живе на Перехресті — поселенні на перетині шляхів у самому серці Пусток.",al={"місце кіл'гали","де кіл'гала"}}},fp="19,223,23.343.0,20.351.0,20.207.0,35.155.0,32.208.0,50.126.0,29.151.0,26.107.0"}
P.entries["quest:1950"] = {n="Вивідати подробиці",s="Магус Тірт замкнув важливу книгу заклять у магічно запечатаній скрині, але не може пригадати фразу, що її відмикає. Щоб дістати том, вам доведеться розшукати його зниклого учня десь біля траси в Мерехтливих Низинах і вивідати в нього забуті слова.",h="Магус Тірт замкнув важливу книгу заклять у магічно запечатаній скрині, але не може пригадати фразу, що її...",kw={"вивідати подробиці","магус тірт","джонсон","курка","перевтілення","мерехтливі низини"},ang={["class:Mage"]="Справа з Тіртом — кумедне, але повчальне видовище небезпек прокляття перевтілення й тієї неуважності, що може спіткати могутніх учених."},sec={{t="Магус і його пам'ять",b="Магус Тірт — дивакуватий чарівник, що мешкає на потрісканому соляному дні Мерехтливих Низин у Тисячі Голок. Він має езотеричні знання й томи, яких відчайдушно шукають маги, що прагнуть зростати, але мати з ним справу — випробування терпіння. Тірт покладається на помічника в усіх буденних дрібницях, зокрема й у паролях, що стережуть його чародійські сховища. Тож маги, яким доручено забрати книгу сили, швидко дізнаються: Тірт замкнув том за чарівними словами, які геть вилетіли йому з голови."},{t="Куряча справа",b="Щоб розшукати учня Тірта, Джонсона, мало просто блукати загонами біля Перегонів Міражу. Розпитавши гоблінів і гномів, що порядкують на трасі, дізнаєшся, що Джонсон став жертвою класичної професійної небезпеки на службі в химерного чарівника: перетворення. Зачарований господарем у звичайнісіньку курку, Джонсон блукає солончаками й не може вимовити ні слова — доки поруч не опиниться мандрівник і на мить не розвіє магічний туман, щоб той зміг прокудкудакати забутий пароль."}},faq={{q="Хто такий Магус Тірт?",a="Магус Тірт — відлюдний чарівник з людей, що живе біля Перегонів Міражу в Мерехтливих Низинах Тисячі Голок. Він має глибокі чародійські знання, по які приходять маги, що прагнуть удосконалити ремесло.",al={"лор тірта","хто такий магус тірт","тірт мерехтливі рівнини"}},{q="Чому Тіртові потрібен пароль до власної скриньки?",a="Тірт замкнув свою скриньку магічно, на промовлену фразу, а такі буденні дрібниці, як паролі, мав пам'ятати його помічник. Розсіяний, як завжди, він забув слова, щойно учень зник.",al={"чому тірт забув","пароль скриньки тірта"}},{q="Куди подівся учень?",a="Джонсон утік недалеко. Він блукає біля перегонової траси на схід від табору Тірта, але знайти його непросто, бо Тірт перетворив його на курку.",al={"знайти помічника тірта","де учень","місце учня"}},{q="Чому учня перетворили на курку?",a="Тірт наклав на Джонсона прокляття, а тоді забув про це. Дізнавшись, що сталося з помічником, Тірт невиразно припускає, що невдячний учень на це заслужив.",al={"чому учень курка","тірт перетворив учня"}},{q="Що в скриньці Тірта?",a="У магічно замкненій скрині — книга з ритуалами й настановами, потрібними для подальшого навчання мага та виготовлення магічного знаряддя.",al={"вміст скриньки тірта","яка книга в скрині"}},{q="Хто може взятися за це доручення?",a="Це доручення — частина окремого випробування лише для магів, які шукають особливої науки й матеріалів, щоб виготовити могутню чарівну паличку.",al={"чи не маги можуть вивідати подробиці","чи лише для магів"}}},fp="13,283,22.549.0,9.526.1,19.201.0,48.218.0,28.167.1,45.186.1,33.143.0,28.138.0"}
P.entries["quest:1959"] = {n="Доповісти Анастасії",s="«Доповісти Анастасії» — поклик, який отримують маги Орди, що набираються сили в Калімдорі та Східних Королівствах. Анастасія Гартвелл, знана чарівниця з Магічного Кварталу Андерсіті, помітила в місті невідоме магічне збурення, і їй потрібні вправні чарівники, щоб його розслідувати.",h="«Доповісти Анастасії» — поклик, який отримують маги Орди, що набираються сили в Калімдорі та Східних...",kw={"доповісти анастасії","анастасія гартвелл","маг","магічний квартал","андерсіті","аптекаріум","таємна магія"},ang={["class:Mage"]="Це завдання — важлива віха для магів Орди: воно виводить їх із місцевих навчальних застав і знайомить із глибшими таємницями — і небезпеками — таємної магії, що визрівають під руїнами Лордерона.",["faction:Horde"]="Цей поклик показує співпрацю між Відступниками й рештою Орди: магічні таланти всіх її народів служать захистові спільних інтересів.",["race:Undead"]="Магів-Відступників кличуть додому, до Магічного Кварталу Андерсіті, щоб допомогти вберегти їхнє молоде королівство від невидимих магічних загроз у його власних стінах."},sec={{t="Поклик таємної магії",b="Звістки серед чарівників Орди ширяться швидко. Чи то навчаючись на кручах Тандер Блафа, чи в запиленій спеці Дуротару, чи серед руїн Лордерона, достатньо обдаровані маги отримують чіткий наказ. Знавці таємної магії в Андерсіті відчули незбагненне збурення, що прокочується їхніми володіннями, і їм потрібна допомога на місці."},{t="Чарівниця Андерсіті",b="Анастасія Гартвелл опікується справами таємної магії з Магічного Кварталу Андерсіті. Коли маг прибуває, вона підтверджує тривожні вісті: у підземному місті зафіксовано аномальну енергію. Природа цієї магії досі зовсім невідома — не доведено ні що вона нешкідлива, ні що відверто ворожа, — тож Анастасії потрібен вправний чарівник, щоб тихо розшукати її джерело, почавши з міського Апотекаріуму."}},faq={{q="Хто така Анастасія Гартвелл?",a="Анастасія Гартвелл — маг і чародійська наставниця з Відступників, що працює в Магічному Кварталі Андерсіті. Вона веде молодих практиків і пильно стежить за чародійськими аномаліями в столиці Відступників.",al={"лор анастасії гартвелл","хто така анастасія","гартвелл андерсіті"}},{q="Де перебуває Анастасія Гартвелл?",a="Вона в Магічному Кварталі Андерсіті, у північній дузі підземного міста, серед інших наставників-чарівників і чародійських дослідників.",al={"де анастасія","місце гартвелл","мапа анастасії в андерсіті"}},{q="Чому магів з Тандер Блафа чи Пусток кличуть до Андерсіті?",a="Відступники мають власних фахівців-чародіїв, але незвичні магічні аномалії загрожують усій присутності Орди в Лордероні. Наставники на Калімдорі посилають своїх перспективних учнів до Андерсіті, щоб ті допомогли й набули практичного досвіду зі складними магічними явищами.",al={"чому їхати до андерсіті","чому доповісти анастасії","завдання мага тандер блафа"}},{q="Яке збурення розслідує Анастасія?",a="Маги виявили в місті незрозумілі магічні коливання. На час виклику Анастасія Гартвелл ще не з'ясувала, чи ця енергія ворожа, випадкова чи нешкідлива, тож починає обережне розслідування.",al={"яке збурення","магічне збурення андерсіті","що негаразд в андерсіті"}},{q="Хто дає це завдання?",a="Цей виклик можуть передати різні наставники магів Орди, щойно чарівник набереться досвіду, зокрема Утел'най в Оргріммарі, Терстон Ксейн у Тандер Блафі, Кейн Файрсонг у Бріллі та Ун'Тува в Селі Сен'джин.",al={"хто дає доповісти анастасії","хто починає доповісти анастасії"}},{q="Що буде, коли з'явитися до Анастасії?",a="Поговоривши з Анастасією й вислухавши її, ви одразу отримуєте доручення глибше дослідити збурення — почати доведеться з Апотекаріуму міста, у завданні «Обстежити крамницю алхіміка».",al={"наступне завдання після доповіді","продовження доповісти анастасії"}}},fp="19,292,20.385.0,25.418.0,26.229.0,36.183.0,80.273.0,52.238.0,21.220.0,42.221.0"}
P.entries["quest:1960"] = {n="Розслідування в алхімічній крамниці",s="«Розслідування в алхімічній крамниці» — завдання в Андерсіті для магів Орди, яким належить розібратися з магічною аномалією в Апотекаріумі. Під проводом Анастасії Гартвелл заклиначі вистежують і ловлять невидимих істот із чистої магічної енергії, що розгулюють крамницею Алджернона.",h="«Розслідування в алхімічній крамниці» — завдання в Андерсіті для магів Орди, яким належить розібратися з...",kw={"розслідування в алхімічній крамниці","анастасія гартвелл","алджернон","аптекаріум","заклинання прояву","породження розлому","маг"},ang={["class:Mage"]="Це завдання перевіряє, як учень володіє чистою магічною силою: тут потрібні особливі заклинання прояву й посудини для утримання, а не лише руйнівна міць.",["race:Undead"]="Хоч аптекарі-Відступники здебільшого зосереджені на алхімії й чумах, це завдання показує, як пильно магічні вчені Андерсіті оберігають місто від магічного проникнення."},sec={{t="Неспокій в Апотекаріумі",b="Андерсіті не звикати до неприродних явищ, але нещодавно в Апотекаріумі виникла проблема суто магічного походження. В алхімічній крамниці Алджернона помітили незримих магічних істот, що безгучно блукали між булькотливими казанами й отруйними реагентами. Розпізнавши неприродний розрив у потоці магії, наставниця магів Андерсіті Анастасія Гартвелл посилає здібних учнів розслідувати справу й приборкати істот, перш ніж ті завдадуть непоправної шкоди."},{t="Прояв і утримання",b="Оскільки істоти невидимі й цілком складаються з сирої магічної сили, звичайні способи вистежування марні. Анастасія дає учням особливе Заклинання Прояву, що знімає з істот невидимість, і міцні скриньки зберігання. Щойно породження розлому проявляться, їх треба здолати й надійно запечатати в скриньках, перш ніж вони розпадуться ще більше чи зашкодять алхімікам за роботою."},{t="Випадковість чи напад?",b="Коли зразки впіймано, Анастасію починає турбувати їхнє походження. Мимовільний розрив у потоці магії — уже тривожно, але навмисний прорив означав би діяльний, злагоджений магічний напад на столицю Відступників. Упійманих істот передають на вивчення, щоб з'ясувати, чи Апотекаріум просто спіткав магічний нещасний випадок, чи він опинився на передовій цілеспрямованої загрози."}},faq={{q="Хто дає це завдання і де його знайти?",a="Це завдання пропонує Анастасія Гартвелл — наставниця магів у Магічному Кварталі Андерсіті.",al={"хто дає завдання","де почати","місце анастасії"}},{q="Де відбувається збурення?",a="Збурення зосереджене довкола алхімічної крамниці Алджернона в кварталі Апотекаріуму в Андерсіті.",al={"куди йти","місце алхімічної крамниці","де алджернон"}},{q="Що за істоти никають крамницею?",a="Це породження розлому — невидимі істоти, цілковито складені із зосередженої магічної енергії, що з'явилися через аномалію в місцевих магічних потоках.",al={"які це монстри","невидимі істоти","породження розколини"}},{q="Як упіймати цих істот?",a="Треба прочитати в крамниці Заклинання Прояву, щоб виявити породження розлому, послабити їх закляттями, а тоді скористатися скринькою-пасткою, щоб замкнути їх усередині.",al={"як упіймати їх","як користуватися скринею","як завершити"}},{q="Чому Анастасія хоче впіймати цих істот живими?",a="Анастасії та вченим Андерсіті потрібні живі зразки, щоб з'ясувати, чи цей розрив у магії — природний, випадковий розлам, чи навмисний напад на місто якоїсь сторонньої магічної сили.",al={"чому впіймати їх","призначення скринь утримання","навіщо їх вивчати"}},{q="Чи можуть це завдання виконати інші класи, крім магів?",a="Ні, це завдання — частина раннього навчання лише для магів Орди.",al={"лише маги","хто може взяти це завдання"}}},fp="30,277,33.479.0,29.435.0,27.417.1,46.109.0,33.123.0,42.144.0,33.168.0,55.195.0,43.101.0"}
P.entries["quest:1961"] = {n="Збір матеріалів",s="«Збір матеріалів» — обряд посвяти для молодих магів Орди, що навчаються в Андерсіті. Анастасія Гартвелл посилає учнів у Срібнолісся, щоб відібрати магічні самоцвіти в чарівників Даларана й зібрати все потрібне для першої справжньої мантії мага.",h="«Збір матеріалів» — обряд посвяти для молодих магів Орди, що навчаються в Андерсіті.",kw={"збір матеріалів","анастасія гартвелл","самоцвіт мани з даларана","йозеф ґреґоріан","амбермілл","мантія","маг"},ang={["class:Mage"]="Це завдання — переломна мить для магів Орди: ви змінюєте просте учнівське вбрання на пошиту на замовлення мантію, в яку вплетено здобуту магічну силу.",["profession:Tailoring"]="Цей процес показує, як звичайне лляне полотно можна поєднати з могутніми самоцвітами мани, щоб створити міцний зачарований одяг.",["race:Undead"]="Це завдання показує безжальний світогляд Відступників: колишня спорідненість із чарівниками Даларана не дає їм жодної пощади, якщо ці живі маги надто слабкі, щоб утримати Срібнолісся."},sec={{t="Обряд магічного визнання",b="У магічних покоях Магічного Кварталу маги-початківці мусять довести, що володіють не лише сирими заклинаннями. Щоб заслужити свою першу справжню мантію — офіційне вбрання, яке засвідчує їхнє становище й особисту гідність, — учні за вказівкою Анастасії Гартвелл мають здобути сировину для зачарованої тканини: сувій простого лляного полотна й кілька могутніх Самоцвітів Мани з Даларана."},{t="Прагматизм Відступників",b="Самоцвіти мани не можна просто купити чи створити чарами: їх доводиться виривати в магів Даларана, що стоять у Срібноліссі, особливо довкола Амбермілла. Анастасія Гартвелл холодно зауважує, що хоч магічні вчення Даларана й перегукуються з їхніми власними, сентиментальним ваганням в Андерсіті не місце. В очах Відступників, якщо живі чарівники не здатні захистити свої реліквії, вони втрачають і скарби, і життя."},{t="Кравець Магічного Кварталу",b="Зібрані полотно й самоцвіти доставляють Йозефові Ґреґоріану — кравцеві з Магічного Кварталу. Ґреґоріан охоче визнає, що йому бракує магічного хисту, щоб оцінити бездоганну якість зачарованих каменів Даларана, але він володіє рідкісною майстерністю, потрібною, щоб уплести їхню сиру силу просто в тканину мантії."}},faq={{q="Яка мета завдання «Збір матеріалів»?",a="Це завдання — посвята для магів Орди. Виконавши його, ви постачаєте кравцеві Йозефові Ґреґоріану потрібні складники — полотно й самоцвіти мани, — щоб пошити новачкові його першу справжню зачаровану мантію.",al={"навіщо збір матеріалів","мета збору матеріалів","завдання робі мага андерсіті"}},{q="Чому Анастасія Гартвелл посилає вас по магів Даларана?",a="Чарівники Даларана, що стоять у Срібноліссі, носять очищені самоцвіти мани, здатні спрямовувати потужні магічні потоки. Гартвелл дивиться на цих живих магів прагматично: попри спільне інтелектуальне коріння, слабкість у полі означає, що їхні життя й припаси дістаються Відступникам.",al={"чому вбивати магів даларана","лор самоцвітів мани даларана","чому маги сільверпайна"}},{q="Де шукати чарівників Даларана?",a="Їх можна зустріти в Срібноліссі: вони займають застави й угіддя на південний схід від Гробниці, довкола поселення Амбермілл.",al={"де самоцвіти мани даларана","місце магів сільверпайна","маги амбермілла"}},{q="Хто такий Йозеф Ґреґоріан?",a="Йозеф Ґреґоріан — кравець-нежить, що працює в Магічному Кварталі Андерсіті. Він майстер, а не чарівник, але спеціалізується на шитті зачарованого одягу, як-от мантій чарівного вогню.",al={"йозеф ґреґоріан андерсіті","хто кравець у кварталі магів","кравець ґреґоріан"}},{q="Що шиють з цих матеріалів?",a="З полотна й даларанських самоцвітів мани Йозеф Ґреґоріан шиє Мантію Чарівного Вогню — класичне вбрання, що знаменує перехід учня до звання справжнього мага.",al={"яку робу отримаєш","роби вогню чар нагорода","нагорода роба збору матеріалів"}},{q="Чому Анастасії трохи неприємно вбивати магів Даларана?",a="Багато чарівників-Відступників, зокрема й сама Гартвелл, за життя навчалися за даларанськими традиціями й поділяють схожі інтелектуальні й магічні погляди. Проте, попри цю спорідненість, виживання й потреба беруть гору над почуттями.",al={"почуття гартвелл до даларана","відступники проти даларана","лор анастасії гартвелл"}}},fp="19,297,25.384.0,26.464.0,31.334.0,43.208.0,57.284.0,38.149.0,23.214.0,44.158.0,67.222.0"}
P.entries["quest:1962"] = {n="Мантія Чарівного Вогню",s="«Мантія Чарівного Вогню» — завершальний обряд у навчанні молодих магів Орди в Андерсіті, який довершує кравець Йозеф Ґреґоріан. Зібравши рідкісні складники в різних куточках світу, учень отримує зачароване вбрання, пошите на замовлення, — знак дедалі більшої влади над магією.",h="«Мантія Чарівного Вогню» — завершальний обряд у навчанні молодих магів Орди в Андерсіті, який довершує...",kw={"мантія чарівного вогню","йозеф ґреґоріан","кравецтво","магічний квартал","маг","андерсіті"},ang={["class:Mage"]="Здобути цю мантію — один із перших обрядів посвяти для заклиначів Орди: вона дає вам пошите на замовлення вбрання, що витримує нестійку енергію вогню й магії.",["profession:Tailoring"]="Це завдання показує, як звичайну тканину підсилюють незвичними реагентами, щоб вона витримувала й підсилювала потужні магічні потоки.",["race:Undead"]="Заклиначі-Відступники в Андерсіті зберігають магічну дисципліну на зразок даларанської, поєднуючи давні магічні традиції з новим існуванням серед руїн Лордерона."},sec={{t="Шати мага",b="Для учнів, що опановують магічні мистецтва в Лордероні, звичайні плащі й буденний одяг майже не допомагають спрямовувати сирі потойбічні сили чи захищатися від них. Йозеф Ґреґоріан, кравець із Магічного Кварталу Андерсіті, тче справжнє магічне вбрання з особливих матеріалів, які збирають здібні заклиначі Орди. Останній стібок Мантії Чарівного Вогню знаменує перехід учня від простих заклинань до визнаного чародія, що володіє і чистою магією, і вогнем."},{t="Вплетена сила",b="Пошити вбрання, здатне безпечно зосереджувати потужну магію, — вимоглива справа. Це не просто кравецтво: для таких мантій потрібні особливі алхімічні й магічні складники, здобуті в небезпечних випробуваннях. Коли все зібрано й принесено до майстерні Ґреґоріана, кравець одразу сплітає складники докупи й дарує молодому магові відчутний знак становища й захисту."}},faq={{q="Яка мета завдання «Мантія Чарівного Вогню»?",a="Це останній крок раннього класового обряду для магів Орди: зібравши для кравця Йозефа Ґреґоріана складники, вони отримують особливо зачаровану мантію.",al={"мета мантії чарівного вогню","що робить мантія чарівного вогню","навіщо це завдання"}},{q="Хто такий Йозеф Ґреґоріан?",a="Йозеф Ґреґоріан — кравець з Відступників, що працює в кравецькій майстерні Магічного Кварталу в Андерсіті. Він шиє перший справжній класовий одяг для новоспечених магів, яких посилає до нього Анастасія Гартвелл.",al={"хто такий йозеф","хто шиє робу","йозеф ґреґоріан андерсіті"}},{q="Де відбувається це завдання?",a="Усе відбувається в Магічному Кварталі Андерсіті, просто в кравецькій майстерні Йозефа Ґреґоріана.",al={"місце мантії чарівного вогню","куди здати мантію чарівного вогню"}},{q="Чому для цього завдання не треба нікуди йти?",a="Усю роботу ви виконали в попередньому дорученні — «Збір матеріалів». Щойно ви віддасте Йозефові реагенти, він за мить шиє вбрання й одразу вручає вам готову мантію.",al={"чому миттєво","як виконати мантію чарівного вогню","автозавершення роби"}},{q="Чи можуть цю мантію отримати інші класи, крім магів?",a="Ні. Увесь ланцюжок завдань і зачароване вбрання, яке він дає, — лише для магів, що служать Орді.",al={"чи лише для магів","чи чорнокнижник може отримати","хто може виконати мантію чарівного вогню"}},{q="З яких матеріалів шиють цю мантію?",a="Мантію шиють з рідкісних припасів, зібраних у попередньому завданні: полотна й даларанських самоцвітів мани, здобутих у магів Кірін-Тору в Срібноліссі.",al={"що йде на робу","інгредієнти роби","здавання збору матеріалів"}}},fp="15,301,17.487.0,11.426.0,49.191.0,23.199.0,33.120.0,62.209.0,48.110.0,49.183.0"}
P.entries["quest:1963"] = {n="Розтрощена Рука",s="Це випробування розбійника, яке дає Терзок у Тіньовій Розколині, перевіряє посвячених, що прагнуть вступити до таємної гільдії Розтрощеної Руки. Щоб довести свою смертоносну вправність, розбійники-початківці мусять вистежити троля-контрабандиста Тазана й забрати його замкнену сумку.",h="Це випробування розбійника, яке дає Терзок у Тіньовій Розколині, перевіряє посвячених, що прагнуть вступити...",kw={"розтрощена рука","терзок","тазан","раджет","контрабандист","розбійник"},ang={["class:Rogue"]="Цей обряд посвяти вводить юних розбійників Орди до лав Розтрощеної Руки й ставить безжальну вправність, убивства й користь вище за відкритий бій.",["faction:Horde"]="Розтрощена Рука уособлює ідейні тертя в Оргріммарі, де потаємні угруповання тихо кидають виклик обережному баченню Тралла щодо молодої Орди."},sec={{t="Тіні в Розколині",b="Під гамірними вулицями Оргріммара лежить підземний морок Тіньової Розколини. Тут діє Розтрощена Рука — таємний орден убивць і злодіїв, що сягає корінням давніх оркських традицій. Поки Вождь Тралл проповідує честь, дипломатію й обачність у правлінні молодою Ордою, провід Розтрощеної Руки вважає, що така нерішучість послаблює їхній народ. Вони прагнуть повернути бойову першість таємним насильством — ножами й отрутою там, де атака на полі бою може не вдатися."},{t="Доля контрабандиста",b="Щоб відсіяти незграбних і слабких, куратор Терзок пропонує простий контракт: усунути Тазана, свавільного троля, що діє в Пустках біля Раджета. Тазан торгує з прибережними піратами й володіє делікатними відомостями, яких прагне гільдія. Здобута замкнена сумка підтверджує, що розбійник уміє вистежити здобич за міськими мурами, хоча щоб дістати її вміст, знадобиться ще більше вправності."}},faq={{q="Що таке Розтрощена Рука в Оргріммарі?",a="Розтрощена Рука — таємна гільдія розбійників, розвідників і вбивць Орди, що діє з Тіньової Розколини в Оргріммарі. Колись це був давній орчий клан, відомий жорстоким самокалічінням, а в сучасній Орді вони — тіньова мережа розвідки й ліквідацій, що віддає перевагу безжальному прагматизмові над обережною дипломатією Тралла.",al={"хто такі розтрощена рука","розбійники розтрощеної руки","мета розтрощеної руки"}},{q="Хто такий Терзок?",a="Терзок — куратор Розтрощеної Руки в Тіньовій Розколині. Він випробовує майбутніх розбійників, щоб переконатися, що ті мають хитрість і смертоносність, потрібні для служби гільдії, і відкрито скептично ставиться до стриманості Тралла.",al={"роль терзока","хто дає завдання","терзок оргріммар"}},{q="Чому Терзок хоче смерті Тазана?",a="Тазан — троль-контрабандист, що веде незаконну торгівлю з піратами Південних Морів біля порту Раджет. Хай яку контрабанду він возить, у його торбі ще й важливі відомості, які Розтрощена Рука хоче мати для власних таємних операцій.",al={"чому вбити тазана","лор тазана","що зробив тазан"}},{q="Де шукати Тазана?",a="Тазан діє в Пустках — никає біля узбережжя й піратських схованок на південь від Раджета.",al={"місце тазана","де тазан","знайти тазана"}},{q="Що буде, коли здобути торбу Тазана?",a="Коли торбу приносять Терзокові, з'ясовується, що вона замкнена. Задоволений загибеллю Тазана, але потребуючи відомостей усередині, Терзок робить із цього наступну перевірку — чи вміє розбійник відмикати замки.",al={"наступне завдання","замкнена торба","що робити з торбою"}},{q="Чи знає Тралл про методи Розтрощеної Руки?",a="Формально Розтрощена Рука служить Орді, але її члени діють здебільшого з тіні й зневажають обережне керівництво Тралла. Вони тихцем розбудовують власні розвідувальні мережі, щоб усувати загрози, перш ніж дипломатія Вождя загальмує справу.",al={"тралл і розтрощена рука","чи вождь схвалює","тралл і розбійники"}}},fp="18,266,20.505.0,17.421.1,40.345.0,15.226.0,33.250.0,23.97.0,46.211.1,52.286.0"}
P.entries["quest:1978"] = {n="Смертолови",s="Це доручення знаменує офіційний вступ здібного агента до лав скрадачів смерті — ордену вбивць і шпигунів Відступників. Доставивши Гросбух Андрона просто жахолордові Варіматрасу, гонець передає докази таємної діяльності Синдикату найвищому проводові Андерсіті.",h="Це доручення знаменує офіційний вступ здібного агента до лав скрадачів смерті — ордену вбивць і шпигунів...",kw={"скрадачі смерті","гросбух андрона","синдикат","варіматрас","альтерак","королівський квартал"},ang={["class:Rogue"]="Ця посвята — офіційний вступ до розбійницьких лав Відступників: прості кишенькові злодюжки стають агентами державної розвідки.",["faction:Horde"]="Хоч це внутрішня справа безпеки Відступників, нагляд за людськими рештками Альтераку захищає північні землі Орди від підривних диверсій.",["race:Undead"]="Для Відступників вступ до скрадачів смерті — пряма присяга оберігати хитку незалежність Лордерона від уцілілих людей і зрадників, що причаїлися."},sec={{t="Посвята в тінях",b="Після того як агент здобув викривальні записи Андрона Ґанта, Меннет Каркад офіційно приймає його до скрадачів смерті. Ця організація — очі, вуха й кинджали Леді Сильвани по всьому Лордерону: вона покладається на розвідувальні мережі, безжальну дієвість і скритність, щоб усувати загрози, перш ніж ті вийдуть на світло. Офіційне визнання в ордені — великий рубіж для кожного молодого розбійника чи розвідника в Андерсіті."},{t="Слід Синдикату",b="Здобич цього таємного розслідування — Гросбух Андрона, що викриває незаконні зв'язки місцевих агентів із Синдикатом. Колись Синдикат був шляхетною аристократією занепалого людського королівства Альтерак, але після краху свого королівства в Другій війні вдався до розбою й підривної діяльності. Каркад здивовано й зневажливо відзначає, як низько скотилися занепалі лорди Альтераку, що опустилися до дрібних змов, аби видряпати назад хоч трохи влади."},{t="Аудієнція в жахолорда",b="Через делікатність відомостей гросбух доставляють просто Варіматрасові в Королівський Квартал Андерсіті. Цей командувач-натрезим керує тактичною розвідкою Відступників на службі Сильвани Віндраннер. Задоволений ініціативою скрадачів смерті, Варіматрас схвально відзначає вправність агента й зауважує, що його розвідці завжди знадобиться той, хто досягає результату."}},faq={{q="Хто такі Скрадачі смерті?",a="Скрадачі смерті — провідний орден шпигунства, розвідки й убивств Відступників. Їхній осередок — у Кварталі Розбійників Андерсіті; вони діють по всьому Лордерону, знешкоджуючи політичних суперників, проникаючи у ворожі угруповання й боронячи королівство Відступників від зовнішніх і внутрішніх підступів.",al={"хто такі скрадачі смерті","лор скрадачів смерті","вбивці відступників"}},{q="До чого тут Синдикат?",a="Здобутий гросбух розкриває таємні зв'язки із Синдикатом — вигнаною аристократією Альтераку, що вдалася до організованого бандитизму. Відступники пильно стежать за рештками Альтераку на своїх землях, бо агенти Синдикату постійно шукають нагоди повернути втрачені володіння й грабувати північний Лордерон.",al={"чому синдикат","зв'язок з альтераком","гросбух синдикату"}},{q="Чому доповідати треба просто Варіматрасові?",a="Варіматрас — тактичний радник королеви Сильвани, що наглядає за безпекою та розвідкою Андерсіті. Важливі відкриття про чужоземні змови — як-от таємні операції Синдикату — мають розглядатися на найвищому рівні, щоб узгодити ширші військові й дипломатичні заходи у відповідь.",al={"чому варіматрас","хто такий варіматрас","роль володаря жаху"}},{q="Хто такий Меннет Каркад?",a="Меннет Каркад — старший куратор і зв'язковий Скрадачів смерті в Андерсіті. Він наглядає за польовими агентами, оцінює новобранців і перебирає зібрані відомості, перш ніж передати найважливіше вище.",al={"роль меннета каркада","хто дає завдання каркад"}},{q="Де відбувається ця аудієнція?",a="Аудієнція відбувається в Залі Темної Леді в Королівському Кварталі, глибоко в Андерсіті. Варіматрас стоїть поруч із королевою Сильваною Віндраннер у самому серці влади Відступників.",al={"де варіматрас","місце зали темної пані"}},{q="Що буде після вступу до Скрадачів смерті?",a="Підтвердивши свої повноваження й довівши свою надійність і Меннетові Каркаду, і Варіматрасові, ви стаєте довіреним польовим агентом Відступників, і попереду — нові розвідувальні доручення й замовлення на ліквідацію по всіх спірних землях Лордерону.",al={"продовження лінії скрадачів смерті","що далі"}}},fp="17,326,26.441.0,24.431.1,27.427.0,27.311.0,30.341.0,35.327.0,22.243.0,36.206.0,45.277.0"}
P.entries["quest:199"] = {n="Насувається темна загроза",s="Це завдання — мить, коли розслідування диверсії на Каменетесній Греблі натрапляє на речовий доказ лихого задуму. Знайшовши підозрілу бочку, заховану біля велетенської дворфійської споруди, шукачі пригод беруть зразок дивно пахучого порошку й несуть його Головному Інженерові Гіндервіру VII.",h="Це завдання — мить, коли розслідування диверсії на Каменетесній Греблі натрапляє на речовий доказ лихого...",kw={"насувається темна загроза","каменетесна гребля","гіндервір","порошок","диверсія","лох модан"},ang={["profession:Engineering"]="Інженер одразу відчуває небезпеку, побачивши нестійкі порошки, навмисно закладені в найвразливіших місцях великої греблі.",["race:Dwarf"]="Каменетесна Гребля — одне з найвеличніших будівельних досягнень дворфів Айронфорджа. Будь-яка загроза її цілісності б'є просто по безпеці й гордості Каз Модану.",["race:Gnome"]="Гномський розум цінує точність дворфійських споруд, тож хімічна природа цієї грубої диверсії особливо тривожить."},sec={{t="Підозріла знахідка",b="Каменетесна Гребля — величний тріумф дворфійської інженерії, що стримує неосяжні води озера. Проте чутки про диверсію привернули пильну увагу до навколишнього берега. Біля самої води захована бочка, якій тут не місце, а в ній — зловісна речовина: дивний, їдкий порошок, що явно не належить до звичайних припасів для догляду за греблею."},{t="Тривога на греблі",b="Коли зразок невідомого порошку показують Головному Інженерові Гіндервіру VII, справджуються найгірші побоювання влади Лох Модану. Інженер одразу розуміє, що проти греблі змовляється чужа сила, — і розслідування з простої підозри обертається нагальною справою оборони краю."}},faq={{q="Що за дивний пахучий порошок?",a="Дивний пахучий порошок з бочки — вибухова чи алхімічна речовина, підкладена біля підніжжя Каменетесної Греблі. Це прямий доказ того, що ворог замишляє зруйнувати чи пошкодити велику загату.",al={"дивний порошок","що в бочці","порошок із підозрілої бочки"}},{q="Хто такий Головний Інженер Гіндервір VII?",a="Головний Інженер Гіндервір VII — дворфійський майстер-інженер, що відповідає за обслуговування, цілісність і безпеку Каменетесної Греблі в Лох Модані.",al={"хто такий гіндервір","головний інженер гіндервір","інженер греблі"}},{q="Де знайти підозрілу бочку?",a="Підозріла бочка схована на березі біля основи Каменетесної Греблі на півночі Лох Модану.",al={"місце бочки","де бочка","бочка лох модан"}},{q="Чому ціль — саме Каменетесна Гребля?",a="Каменетесна Гребля стримує величезне водосховище Лох Модану. Якщо її прорве, катастрофічна повінь промчить Багнокраєм унизу, підірве торговельні шляхи Альянсу й спустошить дворфійські володіння по всьому Каз Модану.",al={"чому знищити греблю","диверсія на греблі","загроза лох модану"}},{q="Хто залишив тут підозрілу бочку?",a="Бочку підклали агенти, що хочуть розхитати дворфійські землі, і Головний Інженер Гіндервір починає ширше розслідування, щоб з'ясувати, хто стоїть за змовою.",al={"хто підклав бочку","диверсанти","хто залишив порошок"}},{q="Що робити, коли порошок зібрано?",a="Віднесіть зразок просто Головному Інженерові Гіндервіру VII на вершину Каменетесної Греблі, щоб він оглянув речовину й підготував відповідь.",al={"що далі","здати порошок","з ким говорити"}}},fp="19,308,22.377.0,16.319.1,36.233.0,37.149.0,37.124.0,43.226.0,36.168.0,45.139.0"}
P.entries["quest:1998"] = {n="Фенвік Татрос",s="Меннет Каркад посилає здібних розбійників Андерсіті вистежити Фенвіка Татроса — за наказом самого лорда Варіматраса. Татроса підозрюють у тому, що він збирає незалежні загони нежиті на берегах у Срібноліссі. Усунувши його, агент доводить скрадачам смерті свою вартість і відкриває собі шлях до тонкощів ремесла.",h="Меннет Каркад посилає здібних розбійників Андерсіті вистежити Фенвіка Татроса — за наказом самого лорда...",kw={"фенвік татрос","меннет каркад","варіматрас","скрадачі смерті","озеро лордамер","срібнолісся","розбійник"},ang={["class:Rogue"]="Це замовлення — полігон для розбійників-Відступників: воно підтверджує вашу скритність і смертоносність, перш ніж вам довірять глибші знаряддя ремесла скрадачів смерті.",["race:Undead"]="Відступники не можуть терпіти суперницьких угруповань нежиті, що претендують на владу так близько від Столиці, — тож голова Татроса стає політичною потребою."},sec={{t="Наказ жахолорда",b="У темних коридорах Кварталу Розбійників Меннет Каркад веде внутрішні замовлення й навчання скрадачів смерті — таємного розвідувального крила Відступників. Коли лорд Варіматрас спускає першочергову ціль, таке доручення не дають новобранцям абияк. Фенвік Татрос привернув увагу жахолорда, закріпившись серед вільної нежиті в Срібноліссі. Якщо його не зупинити, незалежний провід нежиті може зашкодити Відступникам, які згуртовують під своєю владою старі володіння Лордерона."},{t="Трухлявий причал на Лордамері",b="За розвідданими скрадачів смерті, Татрос не ховається ні в глибоких фортецях, ні в склепах. Розвідники вистежили його біля трухлявого причалу на березі Озера Лордамер у Срібноліссі. Щоб убити його там, треба пройти спірною глушиною, де панують дикі звірі, гнилошкірі гноли й рештки Погибелі. Його відрубана голова — той відчутний доказ, якого вимагає Варіматрас, перш ніж допустити агента до глибших таємних операцій."}},faq={{q="Хто такий Фенвік Татрос?",a="Фенвік Татрос — ватажок нежиті, що діє на берегах Озера Лордамір у Срібноліссі. На відміну від Відступників, які служать Леді Сильвані, Татрос керує осередками нежиті, що лишаються незалежними чи ворожими до Андерсіті, тож лорд Варіматрас наказав його стратити.",al={"лор фенвіка","хто такий татрос","передісторія фенвіка татроса"}},{q="Чому Варіматрас хоче смерті Фенвіка Татроса?",a="Варіматрас бачить у Татросі загрозу, що зростає: той може згуртувати бездомну нежить Срібнолісся проти Відступників. Щоб убезпечити кордони довкола Андерсіті, кожного ватажка-суперника, що загрожує цілковитій владі Сильвани в краю, треба швидко усунути.",al={"варіматрас татрос","чому вбити фенвіка"}},{q="Хто такі Скрадачі смерті?",a="Скрадачі смерті — провідна служба шпигунства, убивств і розвідки Відступників. Діючи з Кварталу Розбійників Андерсіті, вони працюють по всьому Лордерону: усувають внутрішні загрози, стежать за суперниками й захищають землі для Темної Леді.",al={"лор скрадачів смерті","що таке скрадачі смерті","фракція розбійників-нежиті"}},{q="Де знайти Фенвіка Татроса?",a="За звітами Скрадачів смерті, Татрос перебуває біля зруйнованої, напівзгнилої пристані на березі Озера Лордамір на північному сході Срібнолісся.",al={"де фенвік","пристань фенвіка","татрос озеро лордамер"}},{q="Що дає це доручення в Скрадачів смерті?",a="Стративши Татроса, агент доводить Меннетові Каркаду й Скрадачам смерті свою вправність і відданість. Переконавшись у вашій надійності, Каркад пропонує вдосконалити ваше мистецтво тіні особливою ремісничою наукою.",al={"нагорода фенвіка","що після фенвіка"}},{q="Хто такий Меннет Каркад?",a="Меннет Каркад — наставник розбійників і куратор Скрадачів смерті у Кварталі Розбійників Андерсіті. Він наглядає за польовими агентами й дає доручення, безпосередньо пов'язані з безпекою королівства Відступників.",al={"меннет каркад","хто дає завдання фенвіка"}}},fp="15,348,28.525.0,30.480.0,23.290.0,47.256.0,26.279.0,33.129.0,62.236.0,21.206.0"}
P.entries["quest:2"] = {n="Кіготь Шарпталона",s="«Кіготь Шарпталона» — завдання-трофей про перемогу над лютим гіпогрифом Шарпталоном в Ашенвалі. Принісши відтятий кіготь істоти Сенані Тандергарт на Заставу Розщепленого Дерева, ви доведете свою вправність і захистите шляхи постачання Орди крізь прадавній ліс.",h="«Кіготь Шарпталона» — завдання-трофей про перемогу над лютим гіпогрифом Шарпталоном в Ашенвалі.",kw={"кіготь шарпталона","шарпталон","гіпогриф","сенані тандергарт","полювання","завдання"},ang={["class:Hunter"]="Здолати легендарного крилатого хижака на кшталт Шарпталона — найвище випробування вміння вистежувати й влучно стріляти під густим лісовим покровом Ашенвалю.",["faction:Horde"]="Перемога над Шарпталоном убезпечує важливі стежки для лісозаготівель Бойової Пісні й захищає беззахисних пеонів, що ходять між передовими заставами й Заставою Розщепленого Дерева.",["race:Orc"]="Знищення крилатих страховиськ у лісі полегшує виснажливу лісозаготівельну кампанію клану Бойової Пісні.",["race:Tauren"]="Дотримуючись мисливських обрядів під проводом Сенані Тандергарт, ви виявляєте споконвічну тауренську шану до випробування себе в двобої з найлютішими звірами природи."},sec={{t="Лихо лісових стежок",b="Поки Орда намагається видобувати ресурси в Ашенвалі, тутешні звірі виявляються не менш небезпечними, ніж вартові нічних ельфів. Шарпталон, сумно відомий своєю лютістю гіпогриф, чатував у кронах і на стежках, що ведуть до Застави Розщепленого Дерева. Звір полював на беззахисних пеонів і гінців, які ходили між передовими лісозаготівельними таборами й заставою, і тяжко заважав діям Орди в краї."},{t="Доказ полювання",b="Під проводом тауренської мисливиці Сенані Тандергарт слідопити Орди мають вичистити найнебезпечніших хижаків, що чатують під лісовим покровом Ашенвалю. Величезний кіготь, відтятий у Шарпталона, — незаперечний доказ того, що небесне страховисько загинуло. Трофей, принесений на Заставу Розщепленого Дерева, здобуває шану серед захисників застави й полегшує життя наляканим робітникам, яким доводиться ходити лісом."}},faq={{q="Хто такий Шарпталон?",a="Шарпталон — хижий гіпогриф з власним ім'ям, що живе в Ашенвалі. Відомий своєю лютістю, він раз у раз нападав на мандрівників у давніх лісах.",al={"хто такий шарпталон","шарпталон моб","що за звір шарпталон"}},{q="Навіщо Сенані Тандергарт кіготь?",a="Сенані Тандергарт керує Полюванням в Ашенвалі із Застави Розщепленого Дерева. Кіготь — речовий доказ того, що великого хижака, який загрожував робітникам і шляхам постачання Орди, знищено.",al={"навіщо кіготь сенані","трофей сенані тандергарт","призначення пазура шарпталона"}},{q="Кому здавати Кіготь Шарпталона?",a="Кіготь треба віддати Сенані Тандергарт — тауренці, що перебуває на Заставі Розщепленого Дерева на сході Ашенвалю.",al={"де здати кіготь","хто бере кіготь","місце здавання пазура"}},{q="Як смерть Шарпталона допомагає Орді?",a="Шарпталон раз у раз нападав на пеонів, що ходили між віддаленими лісопильнями й Заставою Розщепленого Дерева. Убивши звіра, ви робите безпечнішим шлях для припасів, деревини й гінців.",al={"чому вбити шарпталона","інтерес орди до шарпталона"}},{q="Чи це завдання — частина більшого ланцюжка?",a="Так. Воно входить до «Полювання в Ашенвалі» — низки випробувань із вистежування звірів від Сенані Тандергарт, що завершується завданням «Полювання завершено».",al={"ланцюжок полювання ашенвалю","ланцюжок завдань шарпталона"}},{q="Хто така Сенані Тандергарт?",a="Сенані Тандергарт — тауренка-мисливиця із Застави Розщепленого Дерева, яка стежить за рівновагою лісу й випробовує загартованість мисливців Орди проти найнебезпечніших створінь Ашенвалю.",al={"лор сенані","хто така сенані"}}},fp="17,275,30.407.0,17.424.0,19.162.0,43.195.0,37.104.0,43.178.0,37.146.0,27.194.0"}
P.entries["quest:20"] = {n="Загроза Блекроку",s="Маршал Марріс із Лейкширу доручає шукачам пригод винищувати агресивних орків Блекрок, що підступають до Редріджу. Забираючи в них зужиті в боях сокири, захисники містечка сподіваються прорвати облогу, яка дедалі щільніше стискає поселення.",h="Маршал Марріс із Лейкширу доручає шукачам пригод винищувати агресивних орків Блекрок, що підступають до...",kw={"загроза блекроку","орки блекрок","маршал марріс","зужита в боях сокира","лейкшир","редрідж"},ang={["class:Warrior"]="Зійтися щит у щит із досвідченими мародерами Блекрок — жорстке випробування бойової дисципліни й стійкості на передовій.",["faction:Alliance"]="Захист Лейкширу вкрай важливий, щоб утримати південний кордон королівства Стормвінд від давніх ворогів.",["race:Human"]="Клан Блекрок зруйнував давнє королівство Стормвінд у Першій війні; нова зустріч із ним у Редріджі пробуджує гірку пам'ять поколінь."},sec={{t="Містечко в облозі",b="Лейкшир затиснутий з кількох боків, але найгрізніша загроза — орки Блекрок, що ринули сюди з вогняних Палаючих Степів. Просунувшись на південь, у Редрідж, ці досвідчені грабіжники захопили опорні пункти й блукають скелястими перевалами. Через них містяни фактично замкнені в поселенні: торгівля, збиральництво й подорожі північними дорогами зупинилися."},{t="Удар по авангарду",b="Маршал Марріс, командир знесиленої варти Лейкширу, не може виділити загін, щоб прямо штурмувати ворожі позиції. Натомість він залучає мандрівних шукачів пригод, щоб ті знекровлювали передових розвідників і піхоту загарбників. Вимагаючи їхні грубі, зужиті в боях сокири як доказ загибелі, Марріс прагне зменшити число загарбників і довкола Кам'яної Варти на півночі, і в скелястих закутках південно-східного Редріджу."}},faq={{q="Звідки взялися ці орки Блекрок?",a="Вони прийшли на південь зубчастими гірськими перевалами з Палаючих Степів, де довкола Гори Блекрок стоїть їхня споконвічна твердиня.",al={"звідки орки","вторгнення блекрок у редрідж","чому орки в редріджі"}},{q="Хто дає це завдання?",a="Маршал Марріс — старший військовий офіцер, якому доручено боронити Лейкшир і підтримувати лад, поки кільце довкола містечка дедалі тісніше.",al={"хто дає загрозу блекроку","хто дає завдання","завдання маршала маррісі"}},{q="Де шукати загарбників Блекрок?",a="Вони займають північне нагір'я довкола Фортеці Кам'яної Варти, а також закріпилися в південно-східному закутку Гір Редріджу.",al={"де орки блекрок","місця пошарпаних сокир","табори орків редріджа"}},{q="Навіщо Маршалові Маррісу пошарбані в боях сокири?",a="Пошарбані сокири — незаперечний речовий доказ того, що шукач пригод справді бився з мародерами Блекрок, які загрожують долині, і вбивав їх.",al={"навіщо сокири","доказ смерті","призначення пошарпаної сокири"}},{q="Що буде після перемоги над цими розвідниками?",a="Коли авангард проріджено, Маршал Марріс наказує вдарити по місцевому ватажкові Блекрок, що засів у горах, — Таріл'зунові.",al={"що після загрози блекроку","наступне завдання після загрози блекроку","хто веде орків"}},{q="Чи належать ці орки до Орди Тралла?",a="Ні. Клан Блекрок, що діє тут, — рештки Старої Орди, люто ворожі до Альянсу; вони діють незалежно від нової Орди Тралла на Калімдорі.",al={"чи це орки орди","чи клан блекрок частина орди тралла","дружні орки в редріджі"}}},fp="16,228,18.405.0,21.413.0,41.142.0,21.135.0,42.147.0,48.154.0,45.136.1,44.183.0"}
P.entries["quest:2038"] = {n="Зниклі припаси Бінґлза",s="Коли дивакуватий гномський інженер Бінґлз Бластенгаймер аварійно посадив свій гірокоптер у води озера, на нього напали місцеві троги й поцупили його найпотрібніше спорядження. Застрягши на південно-східному березі, він просить повернути вкрадені гайковий ключ, викрутку, молот і саморобну вибухівку з Вибухокапсулятора, щоб полагодити машину й знову долучитися до боротьби за Гномреґан.",h="Коли дивакуватий гномський інженер Бінґлз Бластенгаймер аварійно посадив свій гірокоптер у води озера, на...",kw={"зниклі припаси бінґлза","бінґлз бластенгаймер","гірокоптер","троги","лох модан","гномреґан","інструменти"},ang={["faction:Alliance"]="Допомагаючи пілотові Альянсу в серці Лох Модану, ви вбезпечуєте водні шляхи й підтримуєте ширшу війну за повернення втрачених земель Каз Модану.",["profession:Engineering"]="Залишити особливі інструменти й нестійкі боєприпаси на кшталт Вибухокапсулятора Бластенгаймера в незграбних руках трогів — образа для ремесла й катастрофа, що тільки чекає своєї миті.",["race:Dwarf"]="Навала трогів на острівцях озера загрожує місцевій торгівлі й подорожам, тож будь-який удар по їхніх таборах — бажана послуга горянам.",["race:Gnome"]="Кожен повернений інструмент на крок наближає гномський народ до повітряного контрнаступу на трогів і прокажених гномів, що душать Гномреґан."},sec={{t="Мокре приземлення",b="Бінґлз Бластенгаймер вів свій гірокоптер над Лох Моданом, коли несподівана аварія скинула його просто в холодні води озера. Уціліти після удару — вже неабияка удача, але вибратися на берег виявилося лише половиною біди. Троги, що кишать на центральних острівцях озера, одразу скористалися його скрутою: обсіли приголомшеного пілота й розтягли найцінніші його речі."},{t="Гномська винахідливість в облозі",b="Троги-грабіжники розкидали найпотрібніше спорядження Бінґлза по своїх острівних таборах. Серед зниклого — його звичайні польові інструменти: гайковий ключ, викрутка й молот, а ще його гордість, винахід під назвою Вибухокапсулятор Бластенгаймера. Втратити звичайне начиння прикро й саме собою, але потужна нестійка вибухівка в краї, де й так кишать троги, — пряма небезпека для кожного, хто мандрує Лох Моданом."},{t="За Гномреґан",b="Бінґлз не просто катається в небі Каз Модану заради втіхи: він вважає себе повітряним авангардом визволення своєї занепалої батьківщини. Гномреґан нині захопили підземні троги й опромінені прокажені гноми, і Бінґлз мріє про рішучий удар з повітря, що зламає ворожу хватку. Та без інструментів і вибухівки, без яких не відбудувати літальну машину, його великий повітряний похід міцно застряг в очереті."}},faq={{q="Чому Бінґлз Бластенгаймер застряг у Лох Модані?",a="Бінґлз урізався своїм гірокоптером просто в озеро. Поки він оговтувався від аварії на південно-східному березі, на нього напали троги з сусідніх островів і поцупили його знаряддя й експериментальні боєприпаси.",al={"чому бінґлз тут","як бінґлз розбився","аварія бінґлза"}},{q="Які припаси вкрали троги?",a="Троги потягли чотири важливі речі: гайковий ключ Бінґлза, викрутку, молоток і особливий вибуховий заряд — Бластенкепер Бластенгаймера.",al={"що вкрали троги","припаси бінґлза","які предмети бінґлза"}},{q="Куди троги понесли речі Бінґлза?",a="Троги віднесли вкрадене до своїх таборів на островах у північній частині озера, розкидавши відра з інструментами й вибухівку по скелястих берегах.",al={"де інструменти бінґлза","острів трогів","де бластенкепер"}},{q="Що таке Бластенкепер?",a="Бластенкепер — власний вибуховий пристрій Бінґлза Бластенгаймера, призначений для бойових повітряних ударів по ворогах, що захопили Гномреґан.",al={"що таке бластенкепер","бластенгаймер бластенкепер","вибухівка бінґлза"}},{q="Про який рух говорить Бінґлз?",a="Бінґлз відданий справі повернення Гномреґана. Він хоче розгорнути кампанію повітряних бомбардувань, щоб вичистити підземних трогів і гномів-прокажених, які тримають гномську столицю в полоні.",al={"який рух","за гномреґан","справа бінґлза"}},{q="Чому Бінґлз не може сам повернути припаси?",a="Після катастрофічної аварії Бінґлз лишився сам-один, мокрий до нитки й геть без зброї. Вийти без зброї й без літальної машини проти укріпленого табору лютих трогів через відкриту воду — для інженера-одинака це самогубство.",al={"чому бінґлз сам не дістане","чому бінґлз чекає"}}},fp="25,387,14.419.0,29.443.0,14.446.0,52.210.0,40.155.0,40.188.0,26.169.0,38.192.0,48.227.0"}
P.entries["quest:2039"] = {n="Знайти Бінглза",s="Знайти Бінґлза — завдання Альянсу, яке в Айронфорджі дає гном Ґноарн. Він тривожиться за льотчика, що понад тиждень тому зник під час повітряної розвідки над занепалим Гномреґаном, і посилає шукачів пригод прочесати береги Лох Модану. Слід зниклого пілота веде просто до Бінґлза Бластенгаймера — живого й неушкодженого, але в розпачливій потребі механічних запчастин.",h="Знайти Бінґлза — завдання Альянсу, яке в Айронфорджі дає гном Ґноарн.",kw={"бінґлз","ґноарн","лох модан","гномреґан","льотчик","троги"},ang={["faction:Alliance"]="Розвідники Альянсу часто стають ланкою зв'язку між залами Айронфорджа й польовими загонами в Лох Модані.",["profession:Engineering"]="Інженери оцінять професійні ризики гномської авіації, де загублена гайка на крилі чи вибух двигуна — звичайнісінький вівторок.",["race:Gnome"]="Для гномів порятунок Бінґлза — це надія колись повернути Гномреґан, де на рахунку кожен розвідник і кожна літальна машина."},sec={{t="Зниклий пілот",b="У гамірному гномському кварталі Айронфорджа, Містечку Майстрів, неспокійно: тут бідкаються за зниклими родичами й утраченими машинами. Гнома-льотчика Бінґлза Бластенгаймера відрядили на повітряну розвідку над зараженими радіацією руїнами Гномреґана. Коли минуло понад тиждень без жодної звістки, Ґноарн почав боятися найгіршого: що Бінґлз став жертвою професійного ризику гномської інженерії й просто підірвав себе в небі. Востаннє дивакуватого льотчика бачили десь над водами Лох Модану."},{t="Біля озера",b="Замість купи уламків, що тліють, шукачі знаходять Бінґлза живим і бадьорим на березі Лох Модану. Його анітрохи не бентежить довга відсутність, а сумніви в його льотній майстерності навіть трохи ображають. Застряглий тут винахідник цілком захоплений своєю великою справою. Замість того щоб поспішити з доповіддю до Ґноарна, Бінґлз одразу просить рятівника про допомогу: троги поцупили його інструменти й вибухівку Бластенкеппер, а без них він не повернеться до служби гномській справі."}},faq={{q="Хто такий Бінґлз Бластенгаймер?",a="Бінґлз Бластенгаймер — дивакуватий гном-авіатор і механік. Його відправили в повітря вести спостереження над полеглим Гномреґаном, але він розбив свою літальну машину біля Лох Модану.",al={"хто такий бінґлз","лор бінґлза бластенгаймера","хто той пілот"}},{q="Навіщо Бінґлз літав над Гномреґаном?",a="Гномський провід і майстри постійно стежать за Гномреґаном після його трагічного падіння під навалою трогів і радіації. Бінґлз піднявся в небо, щоб розвідати згори позиції ворога й стан довкілля, допомагаючи загальній справі повернення дому.",al={"місія бінґлза","чому бінґлз літав","розвідка гномреґана"}},{q="Де знайти Бінґлза?",a="Бінґлз застряг на південно-східному березі озера в Лох Модані, де намагається дати раду своїй розбитій літальній машині.",al={"де бінґлз","місце бінґлза","де знайти бінґлза"}},{q="Хто такий Ґноарн?",a="Ґноарн — гном-координатор з Містечка Майстрів в Айронфорджі. Він стежить за гномським особовим складом і місіями, і саме він починає пошуки, коли Бінґлз не повертається вчасно.",al={"хто такий ґноарн","хто дає завдання ґноарн"}},{q="Що буде, коли знайти Бінґлза?",a="Знайшовши Бінґлза, ви отримуєте наступне завдання — «Зниклі припаси Бінґлза», де треба забрати в трогів на островах озера його гайковий ключ, викрутку, молоток і вибухівку Бластенкепер.",al={"що після пошуку бінґлза","завдання крилатої гайки","продовження бінґлза"}},{q="Чи постраждав Бінґлз в аварії?",a="Бінґлз цілий і неушкоджений, хоча його гордість трохи зачепило те, що Ґноарн засумнівався в його льотній майстерності. Насправді його турбує лише те, як повернути знаряддя й вибухівку, які поцупили троги.",al={"чи бінґлз поранений","чи бінґлз помер"}}},fp="12,409,15.522.0,16.513.0,29.203.0,39.253.0,25.145.0,14.187.0,35.197.0,31.191.0"}
P.entries["quest:2040"] = {n="Підземний штурм",s="«Підземний штурм» — завдання Альянсу, яке дає Шоні Тихий у Дворфійському Кварталі Стормвінда. Допомагаючи гномам-вигнанцям, шукачі пригод вирушають до Мертвих Копалень, щоб зняти ціле енергетичне ядро з гоблінського потрощувача. Цій здобичі судилося живити бурильні машини, що мають очолити визволення Гномреґана.",h="«Підземний штурм» — завдання Альянсу, яке дає Шоні Тихий у Дворфійському Кварталі Стормвінда.",kw={"підземний штурм","шоні тихий","гномреґан","потрощувач","мертві копальні","ґноам спрекльспрокет"},ang={["faction:Alliance"]="Допомагаючи гномам-вигнанцям із Дворфійського Кварталу, ви зміцнюєте зв'язок між Стормвіндом і його союзниками у вигнанні та завдаєте удару по постачанню Дефіас.",["profession:Engineering"]="Майстри оцінять зухвалу інженерну думку: розібрати енергоядро грубого гоблінського потрощувача, щоб живити ним точну гномську прохідницьку техніку.",["race:Gnome"]="Для гномів-вигнанців ця здобич — особистий крок до того, щоб пробити скелясті стіни загиблої домівки й вигнати трогів із Гномреґана."},sec={{t="Відчайдушна винахідливість",b="Після того як Гномреґан упав під натиском первісних трогів, уцілілі гномські майстри опинилися у вигнанні в Каз Модані та Стормвінді. Замість того щоб упадати у відчай, інженери на кшталт Шоні вже розробляють механічні операції, щоб прорватися до втраченої домівки. Головна перешкода — щільна скельна порода довкола технократичного міста, і щоб її здолати, потрібні величезні прохідницькі машини — гіросвердломатичні екскаваціонатори. На людських землях бракує потрібних джерел енергії, тож гноми звернули погляд на несподівану й небезпечну альтернативу: важку гоблінську техніку, що працює в злочинному підпіллі."},{t="Грабунок ливарень Дефіас",b="Глибоко у звивистих шахтах Мертвих Копалень у Вестфолі Братство Дефіас Едвіна Венкліфа тримає гоблінських інженерів, що виготовляють бойові машини, зокрема й цілком робочий гоблінський потрощувач. Шоні посилає агентів Альянсу проникнути до цієї ливарні, знищити чи розібрати неповороткий автомат і забрати його особливе серце — Ґноам Спрекльспрокет. Заволодівши потужним гоблінським джерелом живлення, гноми-вигнанці отримають досить механічної сили, щоб пробуритися крізь підземний рубіж і почати контрнаступ за Гномреґан."}},faq={{q="Хто дає завдання «Підземний штурм»?",a="Це завдання дає Шоні Тиха — гномська інженерка з Дворфійського Кварталу Стормвінда. Шукачі пригод часто приходять до неї після розмов з іншими гномами, які згадують її амбітні задуми.",al={"хто дає підземний штурм","хто дає завдання підземний штурм","завдання шоні"}},{q="Де знайти Ґноам Спрекльспрокет?",a="Ґноам Спрекльспрокет здобувають з робочого гоблінського подрібнювача глибоко в ливарних тунелях Мертвих Копалень у Вестфолі.",al={"місце ґноам спрекльспрокет","де спрекльспрокет","деталь подрібнювача мертві копальні"}},{q="Навіщо Шоні деталі гоблінського подрібнювача?",a="Гномським гіробуроматичним екскаватораторам потрібне величезне переносне джерело живлення, щоб прорватися крізь укріплені підземні рубежі довкола Гномреґана. Потужне енергетичне ядро гоблінського подрібнювача Братства Дефіас дає саме ту механічну силу, якої потребують бури.",al={"чому гоблінські деталі","живлення подрібнювача","призначення спрекльспрокета"}},{q="Яка ширша мета цієї місії?",a="Ця місія готує майбутнє визволення Гномреґана. Запустивши важкі бури, гноми-вигнанці збираються прокопатися просто крізь скелясті рубежі свого захопленого міста й раптово вдарити по трогах, що його окупували.",al={"навіщо підземний штурм","завдання відвоювання гномреґана","план штурму гномів"}},{q="Що сталося з Гномреґаном, що довелося планувати цей штурм?",a="Гномреґан захлеснула навала трогів, що вийшли з глибин під містом. Під час хаотичної оборони місто отруїла токсична радіація, і вцілілі гноми мусили тікати біженцями до Айронфорджа й Стормвінда.",al={"чому впав гномреґан","що сталося з гномреґаном","вторгнення трогів"}},{q="Чи в союзі Братство Дефіас і троги?",a="Ні, вони ніяк не пов'язані. Братство Дефіас лише найняло гоблінів-майстрів будувати бойові машини у Вестфолі. Шоні просто використовує присутність Дефіас у Мертвих Копальнях як зручне джерело потужної гоблінської техніки.",al={"дефіас і троги","чи троги з дефіас"}}},fp="19,356,21.658.0,28.571.0,40.214.0,43.135.0,49.279.0,41.251.0,67.253.0,49.230.0"}
P.entries["quest:2078"] = {n="Помста Джайромаста",s="Ґелкак Джайромаст жадає розплати з місцевими мурлоками, які пограбували його розбитий корабель біля берегів Темного Узбережжя. Щоб здійснити свою вендету, ексцентричний капітан посилає шукачів пригод знову запустити свого механічного першого помічника — Трешвакінатор 4100.",h="Ґелкак Джайромаст жадає розплати з місцевими мурлоками, які пограбували його розбитий корабель біля берегів...",kw={"помста джайромаста","ґелкак джайромаст","трешвакінатор 4100","перший помічник","мурлоки","темне узбережжя"},ang={["faction:Alliance"]="Позбувшись несправних машин і агресивних мурлоків, ви допоможете вберегти узбережжя для подорожей Альянсу між Обердайном і землями на півдні.",["profession:Engineering"]="Механічний перший помічник Ґелкака показує, наскільки капітан, що застряг на березі, залежить від свого інженерного спорядження.",["race:Gnome"]="Гноми впізнають у заводному ключі звичний спосіб запустити механічний автомат."},sec={{t="Капітанська вендета",b="Застрягши на імлистих берегах Темного Узбережжя, Ґелкак Джайромаст не хоче миритися з поразкою від прибережних мурлоків. Зібравши уламки, потрібні для своїх задумів, ексцентричний капітан прагне повної відплати племені та його ватажкові. Замість того щоб брести в прибій з абордажною шаблею в руці, Ґелкак покладається на важку інженерію й довіряє заводний ключ кожному сухопутному щурові, якому вистачить сміливості впоратися з його механічним підлеглим."},{t="Бунт першого помічника",b="Вірний перший помічник Ґелкака — не просолений дворф і не моряк, а Трешвакінатор 4100: брязкітливий механічний голем, покинутий на мілині на південь від корабельних решток. Заводна автоматика обіцяє легку розправу над мурлоками, та саме ця машина виявляється небезпечно ненадійною. Коли її заводять і ведуть назад до капітана, конструкція дає катастрофічний збій, сприймає рятівника й творця за ворогів — і на пляжі зав'язується бій."}},faq={{q="Хто такий помічник Ґелкака?",a="Помічник Ґелкака — Трешвакінатор 4100, механічний голем-автомат, що лежить на узбережжі на південь від табору капітана, який зазнав корабельної аварії.",al={"помічник","помічник ґелкака","хто помічник"}},{q="Чому Ґелкак прагне помсти?",a="Корабель Ґелкака розбився біля Темного Узбережжя, а місцеві мурлоки Сірої Імли розтягли його майно й не дають спокою вцілілій команді. Ґелкак збирається розчавити плем'я та їхнього вождя за допомогою свого голема.",al={"чому помста","помста мурлоків","мотив ґелкака"}},{q="Що буде, коли привести Трешвакінатора назад?",a="Увімкнувши помічника ключем, проведіть його назад до Ґелкака. Як він поведеться, коли дійде до капітана, ви побачите під час супроводу.",al={"напад трешвакінатора","збій робота","чому голем нападає"}},{q="Що робити з Ключем Гіромаста, коли завдання виконано?",a="Ключ запускає Трешвакінатора. Коли місію завершено, він більше ні до чого.",al={"використання ключа гіромаста","залишити ключ гіромаста","чи можна видалити ключ"}},{q="Звідки в Ґелкака Трешвакінатор?",a="Голем — частина вантажу й спорядження, врятованого з невдалого плавання Ґелкака вздовж північного Калімдору; його створили як важку механічну силу для команди.",al={"хто створив трешвакінатора","походження трешвакінатора"}},{q="Чи здається Ґелкак, коли голема знищено?",a="Які плани має Ґелкак і як він відповість на вашу роботу, з'ясується, коли ви приведете назад його помічника.",al={"що з ґелкаком","після помсти джайромаста"}}},fp="18,252,20.490.0,23.473.1,27.138.0,29.206.0,54.140.1,59.97.1,42.159.0,49.93.1"}
P.entries["quest:2098"] = {n="Пропажа Джайромаста",s="Ексцентричний гном-пірат Ґелкак Джайромаст, що зазнав корабельної аварії біля імлистих берегів Темного Узбережжя, шукає допомоги, щоб відновити свого механічного першого помічника. Його незамінний заводний ключ розбився об каміння, а уламки розтягли місцеві звірі й мурлоки. Повернути три частини — перший крок до того, щоб знову поставити команду до ладу.",h="Ексцентричний гном-пірат Ґелкак Джайромаст, що зазнав корабельної аварії біля імлистих берегів Темного...",kw={"пропажа джайромаста","ґелкак джайромаст","заводний ключ","мурлоки сірої імли","трешадони","південні моря"},ang={["profession:Engineering"]="Інженери оцінять, як складно підтримувати годинникові механізми в робочому стані після бурхливої корабельної аварії в солоній воді.",["race:Gnome"]="Гноми одразу впізнають, що Ґелкак покладається на годинникові механізми, а не на товаришів із плоті й крові, — хоч його піратське життя для їхнього народу доволі незвичне."},sec={{t="Викинутий морем на Темне Узбережжя",b="Ґелкак Джайромаст — дивне видовище на похмурих пісках Темного Узбережжя: гном-пірат, що застряг далеко від звичних морських шляхів Південних Морів. За словами Ґелкака, його судно спіткав сумний кінець просто біля берега — його атакували й потопили агресивні трешадони. Викинутий на берег серед уламків, він опинився геть сам, відрізаний від своєї вірної команди."},{t="Розтягнутий ключ",b="Найбільше Ґелкака турбують не харчі й не золото, а його перший помічник. Щоб запустити цього товариша й керувати ним, потрібен особливий ключ, який розлетівся на три уламки, коли Ґелкака кинуло на кам'янисті мілини. Не встиг він зібрати уламки, як місцеві звірі — рифові повзуни, що снують пляжем, височенні лісові довгоступи біля лісу та падальники з місцевого племені мурлоків Сірої Імли — розхапали блискучі металеві шматки."},{t="Дивний товариш",b="Ґелкак говорить про свого першого помічника з палкою відданістю морського капітана, хоча слова про те, що товариша треба «поставити до ладу», натякають на незвичайного члена команди. Гном-мореплавець, що застряг на чужих берегах, природно покладається на механічну винахідливість, і зібрати розбитий ключ украй важливо, щоб знову запустити ту годинникову дивовижу, яку Ґелкак витяг із глибин."}},faq={{q="Хто такий Ґелкак Джайромаст?",a="Ґелкак Джайромаст — дивакуватий гном-пірат, чий корабель розбився біля узбережжя Темного Узбережжя, коли на нього напали й потопили хижі трешадони.",al={"ґелкак джайромаст","хто гном-пірат","гном-пірат темного узбережжя"}},{q="Для чого потрібен ключ?",a="Ключ потрібен, щоб знову запустити й завести помічника Ґелкака — механічне створіння, що вимкнулося під час злощасної корабельної аварії.",al={"навіщо ґелкаку ключ","призначення ключа ґелкака","ключ помічника"}},{q="Куди поділися три частини ключа?",a="Коли ключ зламався на березі, його частини розтягли місцеві створіння: верхню забрали лісоступи, середню — мурлоки Сірої Імли, а нижню — прибережні рифові повзуни.",al={"де частини ключа","хто вкрав ключ","зламаний ключ темне узбережжя"}},{q="Що гном-пірат робив біля Темного Узбережжя?",a="Ґелкак плавав водами північного Калімдору в пошуках здобичі, але ворожі трешадони раптово поклали край його подорожі.",al={"чому ґелкак на темному узбережжі","пірати темного узбережжя"}},{q="Що буде, коли ключ складено?",a="Щойно в Ґелкака будуть усі три частини ключа, він зможе завести свого товариша — це веде просто до завдання «Помста Джайромаста».",al={"що після ключа","продовження пропажі джайромаста"}},{q="Що за мурлоки тримають частину ключа?",a="Середню частину підібрало плем'я мурлоків Сірої Імли, що оселилося серед уламків затонулих кораблів на мілинах Темного Узбережжя.",al={"мурлоки темного узбережжя","мурлоки сірої мли ключ","мурлоки розбитого корабля"}}},fp="20,328,21.381.0,17.468.0,20.376.1,23.148.0,25.145.0,41.194.0,46.137.0,42.144.1,42.150.0"}
